/// The registry id for the `type.argument-mismatch` proof-layer check (ADR-0022).
pub const ID: &str = "type.argument-mismatch";

/// The registry id for the `type.return-mismatch` proof-layer check (ADR-0022):
/// a function/method whose return type is a native scalar/union and one of its
/// (trace-visible) `return <literal>;` statements provably raises a `TypeError`.
pub const RETURN_ID: &str = "type.return-mismatch";

/// The registry id for the phpdoc declared-contract param check (ADR-0030 relation
/// #1): a proven value flowing into a parameter with a `@param` phpdoc envelope
/// that it provably does **not** inhabit under contract (set) acceptance — no
/// coercion (a numeric string `"5"` does not satisfy `int` here). Distinct from the
/// runtime relation ([`ID`]); phpdoc types are never enforced at runtime.
pub const PARAM_MISMATCH_ID: &str = "phpdoc.param-mismatch";

/// The registry id for the phpdoc declared-contract return check (ADR-0030): a
/// proven `return <value>;` that provably does not inhabit the `@return` envelope
/// under contract acceptance.
pub const RETURN_MISMATCH_ID: &str = "phpdoc.return-mismatch";

/// The registry id for the branch-sensitive null-dereference proof (ADR-0031
/// stage 1): a method call whose receiver variable is **proven `null`** on the
/// current path (e.g. inside `if ($u === null) { $u->name(); }`) — a guaranteed
/// runtime `Error` ("Call to a member function on null"). Only a *`Singleton(null)`*
/// receiver fires; a `OneOf` that merely *includes* null is `Maybe` → silent.
pub const CALL_ON_NULL_ID: &str = "call.on-null";

/// The registry id for the native property-type check (ADR-0036): a proven value
/// assigned to a native-typed property provably raises a `TypeError` under the
/// assigning file's strict mode (`$x->p = "abc"` on `int $p`).
pub const PROP_MISMATCH_ID: &str = "type.property-mismatch";

/// The registry id for the phpdoc `@var` property-contract check (ADR-0036/0030):
/// a proven or abstract value assigned to a property provably does not inhabit its
/// `@var` contract type (definite `No` only; no double-report where native fired).
pub const PHPDOC_PROP_MISMATCH_ID: &str = "phpdoc.property-mismatch";

/// The registry id for the readonly-reassignment proof (ADR-0036): a second proven
/// write to a `readonly` property on one path — a guaranteed runtime `Error`.
pub const READONLY_REASSIGNED_ID: &str = "readonly.reassigned";

/// The registry id for the effect-envelope check (ADR-0005/0022): a function
/// declared `#[\Steins\Pure]` / `#[\Steins\Effect(...)]` whose inferred effects
/// exceed the declared envelope (ADR-0018 prefix subsumption).
pub const EFFECT_ID: &str = "effect.envelope-exceeded";

/// The one unified trinary judgment (ADR-0031), defined in `steins-domain`
/// and re-exported here: condition evaluation in the branch walk, phpdoc
/// contract acceptance (ADR-0030), and the domain's own fact queries all
/// speak the same `Certainty`.
pub use steins_domain::Certainty;

/// The registry id for the unknown-effect-label check (ADR-0018/0022): a declared
/// `#[\Steins\Effect(...)]` label that is not in the label registry
/// (`steins_catalog::LabelRegistry` — the builtin taxonomy plus whatever the
/// ADR-0068 plugin channel registered for this project) — a typo, or a private
/// label no plugin registers.
pub const UNKNOWN_LABEL_ID: &str = "effect.unknown-label";

/// The registry id for the `@throws` envelope check (ADR-0040/0007): a **checked**
/// exception that **provably escapes** (`Yes`) a function/method whose docblock
/// declares `@throws`, and is a subclass of **none** of the declared classes. Only
/// proven escapes report; `Maybe`-escape and unknown-hierarchy stay silent (the
/// consumer-inverted safe side of ADR-0040).
pub const THROW_UNDECLARED_ID: &str = "throw.undeclared";

/// The registry id for the Liskov throw-widening check (ADR-0033/0040 rule 4): an
/// override/implementation whose declared `@throws` names a checked class that is
/// a subclass of none of the parent method's declared `@throws` classes. Fires
/// only when **both** sides declare `@throws`; `Maybe` resolution stays silent.
pub const THROW_LISKOV_ID: &str = "throw.liskov-widened";

/// The registry id for the Liskov effect-widening check (ADR-0033 point 5): a
/// project method whose **proven** inferred effects exceed the effect envelope
/// (`#[\Steins\Pure]` / `#[\Steins\Effect(...)]`) declared on the abstraction it
/// overrides or implements (a parent class or interface method). Implementations
/// may be purer, never less pure; the exhaustiveness-tainted (unknown) remainder
/// stays silent — only the proven subset judges.
pub const EFFECT_LISKOV_ID: &str = "effect.liskov-widened";

// ---------------------------------------------------------------------------
// The finding-breadth family (ADR-0049): absence-proof ids. An id not yet wired to
// an emitter lives in `REGISTERED_NOT_YET_EMITTED` rather than `ALL_EMITTABLE_IDS`;
// the totality test binds the two lists to the registry.
// ---------------------------------------------------------------------------

/// The registry id for the undefined-function check (ADR-0049 §3, proof layer): a
/// call to a function no candidate FQN defines and the sidecar reports not-found,
/// with the dam clear.
pub const CALL_UNDEFINED_FUNCTION_ID: &str = "call.undefined-function";

/// The registry id for the undefined-method check (ADR-0049 §4, proof layer): a
/// method call on a proven-exact receiver whose fully-enumerated hierarchy defines
/// no such method, with no `__call`/trait obstacle.
pub const CALL_UNDEFINED_METHOD_ID: &str = "call.undefined-method";

/// The registry id for the undefined-class check (ADR-0049 §5, proof layer): a
/// class reference at a hard-error position (`new`, static call, class-const /
/// static-property fetch) whose FQN is absent from the index, the builtin
/// hierarchy, and the sidecar, with the dam clear.
pub const CLASS_UNDEFINED_ID: &str = "class.undefined";

/// The registry id for the too-few-arguments check (ADR-0049 §6, proof layer): a
/// uniquely-resolved call passing fewer positional arguments than the target's
/// required parameters (always `ArgumentCountError`).
pub const CALL_TOO_FEW_ARGUMENTS_ID: &str = "call.too-few-arguments";

/// The registry id for the too-many-arguments check (ADR-0049 §6, proof layer):
/// extra arguments to an **internal** non-variadic target (userland silently
/// ignores them — never a finding).
pub const CALL_TOO_MANY_ARGUMENTS_ID: &str = "call.too-many-arguments";

/// The registry id for the unknown-named-argument check (ADR-0049 §6, proof
/// layer): a named argument binding no parameter of a resolved non-variadic target
/// (fatal `Error`).
pub const CALL_UNKNOWN_NAMED_ARGUMENT_ID: &str = "call.unknown-named-argument";

/// The registry id for the missing-offset check (ADR-0049 §7, proof layer): a read
/// of a key provably absent from a proven container value (`Undefined array key`).
pub const OFFSET_MISSING_ID: &str = "offset.missing";

/// The registry id for the offset-on-unsupported check (ADR-0049 §7, proof layer):
/// an offset read on a proven non-offsetable base (object → fatal `Error`;
/// scalar/null → warning).
pub const OFFSET_ON_UNSUPPORTED_ID: &str = "offset.on-unsupported";

/// The registry id for the undeclared-offset check (ADR-0062 A-G10, **contract**
/// layer, floor `strict`): a constant-key read of a key the base's *declared* shape
/// excludes — a field declared `Absent`, a key outside a `Sealed` shape's fields, or
/// a key the unsealed tail's own key class rejects (`ShapeRead::DeclaredAbsent`).
///
/// The absence is definite **conditional on the docblock**, so the evidence is the
/// Asserted world and the finding is contract-grade — never a proof-layer claim
/// (A-G9's corollary). v1 scope: shape-declared bases with
/// constant/env-resolved keys only.
pub const OFFSET_UNDECLARED_ID: &str = "offset.undeclared";

/// The registry id for the undischarged optional-offset read (ADR-0062 A-G10 /
/// issue #51, **contract** layer, floor `strict`): a constant-key read of a key the
/// base's declared shape marks `Optional` (`ShapeRead::MaybeMissing`) that no
/// proof on this path discharges — no `isset`/`array_key_exists` guard promoted it
/// (S4), and no KeyCover + `¬isset` premise ladder proved it (S5).
///
/// At runtime such a read warns `Undefined array key` and yields `null`, which then
/// propagates — a real soundness hazard, reported only on the strict surface because
/// its evidence is the declaration, not a proven value. The `??`
/// chain's non-final arms NEVER fire: the operator itself protects them.
pub const OFFSET_MAYBE_MISSING_ID: &str = "offset.maybe-missing";

/// The registry id for the declared-receiver undefined-method check (ADR-0049 §8,
/// **contract** layer): a method absent on a phpdoc-declared receiver narrowed by
/// branch analysis, under descendant closure.
pub const PHPDOC_UNDEFINED_METHOD_ID: &str = "phpdoc.undefined-method";

// ---------------------------------------------------------------------------
// The dump surface (ADR-0053): requested introspection in the debug layer.
// ---------------------------------------------------------------------------

/// The registry id for the explicit `PHPStan\dumpType($e)` dump (ADR-0053 §2, debug
/// layer): renders the walk's best knowledge of `$e` at the call position (the trust
/// order — proven value beats membership beats declared arms). Fail-level, fixed:
/// the named function does not exist at runtime, so a committed call is a guaranteed
/// fatal (§3). Emitted from D3.
pub const DEBUG_TYPE_ID: &str = "debug.type";

/// The registry id for the explicit `PHPStan\dumpPhpDocType($e)` dump (ADR-0053 §2,
/// debug layer): renders the **contract-fact arm list** (the declared envelope as
/// narrowed by guards) — the declared-side view. Fail-level, fixed (§3). Emitted
/// from D3.
pub const DEBUG_PHPDOC_TYPE_ID: &str = "debug.phpdoc-type";

/// The registry id for the default-on `var_dump($e)` dump (ADR-0053 §2, debug
/// layer): one `debug.type`-shaped report per argument expression. Warn-level,
/// fixed — exit-neutral forever (§3), profile-disableable (§4). Emitted from D4.
pub const DEBUG_VAR_DUMP_ID: &str = "debug.var-dump";

/// The registry id for `@psalm-trace` (ADR-0074, debug layer). It renders the
/// same trust-ordered fact as `PHPStan\dumpType($x)`, including the `(asserted)`
/// marker. It is warn-level and cannot be disabled by a profile: the runtime-inert
/// annotation is an authored question, removed by deleting the comment.
pub const DEBUG_TRACE_ID: &str = "debug.trace";

/// The resolved FQN of `PHPStan\dumpType` (ADR-0053 §2), lowercase-normalized and
/// leading-`\`-stripped — the case-insensitive matching key (PHP function names are
/// case-insensitive).
pub const DUMP_TYPE_FQN: &str = "phpstan\\dumptype";

/// The resolved FQN of `PHPStan\dumpPhpDocType` (ADR-0053 §2), lowercase-normalized.
pub const DUMP_PHPDOC_TYPE_FQN: &str = "phpstan\\dumpphpdoctype";

/// The reserved dump-family FQNs (ADR-0053 §5), recognized case-insensitively by
/// resolved FQN even if userland defines the name. Undefined-function reporting
/// excludes this set because the fail-level dump diagnostic already accounts for
/// the call.
pub const DUMP_FQNS: &[&str] = &[DUMP_TYPE_FQN, DUMP_PHPDOC_TYPE_FQN];

/// Whether normalized `fqn` belongs to the reserved dump family.
#[must_use]
pub fn is_dump_family_fqn(fqn: &str) -> bool {
    DUMP_FQNS.contains(&fqn)
}

/// Every id constant that reaches a `Diagnostic { id: … }` construction site — the
/// canonical enumeration of what the emitters can produce (ADR-0050 §2 totality).
///
/// **Invariant, checked by the workspace totality test** (`tests/registry.rs`):
/// this list and [`DIAGNOSTIC_REGISTRY`] are the same set, both directions — so a
/// new emitter whose id is added here but not registered (or the reverse) fails to
/// build the tests. Adding a `*_ID` constant and emitting it therefore *forces*
/// both a registry entry (with a layer) and an entry here. The two live in
/// different files on purpose: the registry carries the layer attribute, this
/// carries "is emitted", and the test binds them.
///
/// `SUPPRESS_UNMATCHED_ID` / `SUPPRESS_UNKNOWN_ID` are emitted from
/// [`suppress`] and so are covered via the registry side of the test.
pub const ALL_EMITTABLE_IDS: &[&str] = &[
    ID,
    RETURN_ID,
    CALL_ON_NULL_ID,
    PROP_MISMATCH_ID,
    READONLY_REASSIGNED_ID,
    PARAM_MISMATCH_ID,
    RETURN_MISMATCH_ID,
    PHPDOC_PROP_MISMATCH_ID,
    THROW_UNDECLARED_ID,
    THROW_LISKOV_ID,
    EFFECT_ID,
    EFFECT_LISKOV_ID,
    UNKNOWN_LABEL_ID,
    CALL_UNDEFINED_METHOD_ID,
    OFFSET_MISSING_ID,
    OFFSET_ON_UNSUPPORTED_ID,
    OFFSET_UNDECLARED_ID,
    OFFSET_MAYBE_MISSING_ID,
    PHPDOC_UNDEFINED_METHOD_ID,
    CALL_TOO_FEW_ARGUMENTS_ID,
    CALL_UNKNOWN_NAMED_ARGUMENT_ID,
    CALL_UNDEFINED_FUNCTION_ID,
    CLASS_UNDEFINED_ID,
    DEBUG_TYPE_ID,
    DEBUG_PHPDOC_TYPE_ID,
    DEBUG_VAR_DUMP_ID,
    DEBUG_TRACE_ID,
    suppress::SUPPRESS_UNMATCHED_ID,
    suppress::SUPPRESS_UNKNOWN_ID,
];

/// Ids **registered ahead of emission**: they exist in [`DIAGNOSTIC_REGISTRY`]
/// (so `@steins-ignore` can name them and their layer is pinned) but no emitter
/// produces them yet. An id moves into [`ALL_EMITTABLE_IDS`] once its emitter lands.
///
/// The totality test (`tests/registry.rs`) keeps this honest: every registered id
/// must be in `ALL_EMITTABLE_IDS ∪ REGISTERED_NOT_YET_EMITTED`, the two lists are
/// **disjoint**, and every id here must actually be registered. An emitted id
/// missing from `ALL_EMITTABLE_IDS` still fails forward totality.
pub const REGISTERED_NOT_YET_EMITTED: &[&str] = &[
    // The too-many-arguments arm fires for INTERNAL targets only (userland
    // too-many runs clean), so it waits for the reflect slice (M2).
    CALL_TOO_MANY_ARGUMENTS_ID,
];

/// The maximum depth of interprocedural argument-binding descent (Feature B).
///
/// ADR-0009 makes inference cutoffs a first-class budget discipline: a chain of
/// calls propagating a literal is followed at most this many frames deep, after
/// which the descent stops with **no** diagnostic (a cutoff names itself as
/// silence, never a manufactured finding). Direct and indirect recursion is
/// caught earlier by the on-stack binding set; this bound guards against merely
/// long, non-cyclic chains.
pub const MAX_BINDING_DEPTH: usize = 8;

/// The one-line coverage-posture notice (ADR-0004): printed to stderr when a run
/// executes as the sound subset because the PHP sidecar is unavailable, and served
/// as the browser envelope's `notice` field for the engine-off playground (ADR-0065).
///
/// The second clause is ADR-0069's: with no engine to reflect them, a builtin's
/// return type comes from the catalog's mined declaration, which is a claim rather
/// than a runtime answer — so the sentence says so where the posture is stated.
pub const SOUND_SUBSET_NOTICE: &str = "note: running as sound subset (no PHP sidecar) — findings that require executing PHP are omitted, and builtin return types come from the catalog's declarations, unverified";

/// The notice for issue #110's degradation mode: PHP spawned but the opening
/// handshake or a later request stopped answering. This differs from
/// [`SOUND_SUBSET_NOTICE`], where PHP is unavailable; `steins doctor` diagnoses
/// the unresponsive-process case. [`ProcessEngine`] emits this at most once per
/// run, and it never changes the exit status.
pub const SIDECAR_HANDSHAKE_NOTICE: &str = "note: PHP sidecar stopped answering — running as sound subset (degraded): findings that require executing PHP are omitted, and builtin return types come from the catalog's declarations, unverified; run `steins doctor` for detail";

// ---------------------------------------------------------------------------
// Folding seam (ADR-0004 / ADR-0024).
// ---------------------------------------------------------------------------

/// Something that can fold a builtin call to a concrete literal value, and (from
/// ADR-0049 S2) answer the runtime boot surface for the absence-proof family.
pub trait Folder {
    /// Fold `name(args...)` to a literal, or `None` to widen.
    fn fold(&mut self, name: &str, args: &[ArgValue]) -> Option<ArgValue>;

    /// Whether the absence-proof family (ADR-0049) may fire **at all** this run.
    /// `true` only when a live PHP sidecar is answering the boot surface *and* no
    /// runtime-redefinition extension (`uopz`/`runkit7`/`Componere`, ADR-0049 A9)
    /// is loaded — with any such extension present, no absence claim holds. The
    /// default is `false`: the sound subset (ADR-0004) keeps every absence id
    /// silent when there is no sidecar to ask (A2ii's honest consequence — the
    /// homonym question has no textual answer).
    fn absence_family_available(&mut self) -> bool {
        false
    }

    /// Ask the project's own PHP whether `fqn` is a resident builtin/extension
    /// class-like — the ADR-0049 A2ii **homonym** leg. `Some(true)` — a boot-surface
    /// homonym stands, so the textual twin may be dead code shadowed by the loaded
    /// class (silence); `Some(false)` — definitively absent from the boot surface;
    /// `None` — unanswerable (no sidecar / a mid-run failure ⇒ Unknown ⇒ silence).
    /// The default is `None` (the sound subset). `fqn` is the index's
    /// lowercase-normalized form; PHP's class-existence predicates are
    /// case-insensitive, so the lowercased name is a faithful query.
    fn boot_surface_class_like(&mut self, fqn: &str) -> Option<bool> {
        let _ = fqn;
        None
    }

    /// Ask the project's own PHP whether `fqn` is a resident builtin/extension
    /// **function** — the arity family's A2ii homonym leg (ADR-0049 §6). A user
    /// function that shares a name with a boot-surface function is only bound to
    /// the indexed signature when the userland declaration actually executes (the
    /// `function_exists`-guarded polyfill shadowed by a loaded extension is the
    /// live counterexample); `Some(true)` therefore forces silence. `Some(false)`
    /// — definitively absent from the boot surface; `None` — unanswerable (no
    /// sidecar / a mid-run failure ⇒ silence). The default is `None`. `fqn` is the
    /// index's lowercase-normalized form; PHP function names are case-insensitive,
    /// so the lowercased name is a faithful query.
    fn boot_surface_function(&mut self, fqn: &str) -> Option<bool> {
        let _ = fqn;
        None
    }

    /// The project's own PHP `(major, minor)` from the sidecar `env()` — the
    /// ADR-0052 A11 version-skew input. `None` (the default / sound subset) when no
    /// sidecar answers: an unknown minor is treated as "no detectable skew", so the
    /// catalog pin stands and arm deletion behaves exactly as it did before A11.
    fn php_minor(&mut self) -> Option<(u16, u16)> {
        None
    }

    /// The boot surface's self-description for the existence-id message register
    /// (ADR-0049 §9): `PHP 8.5.8 (32 extensions)`, sourced from the sidecar `env()`.
    /// `None` (the default / sound subset) when no sidecar answers — the emitter
    /// then falls back to a version-agnostic phrasing. The existence ids only fire
    /// when [`Self::absence_family_available`] is `true`, so a live label is the
    /// normal case at a firing site.
    fn boot_surface_label(&mut self) -> Option<String> {
        None
    }

    /// The value-domain **return fact** of a uniquely-resolved builtin `name`
    /// (ADR-0056 R1): the reflected return envelope (the running engine's own
    /// declaration), refined by an admitted curated row. `None` when nothing may
    /// be seeded — no sidecar, a runtime-redefinition extension loaded (a
    /// monkey-patched builtin disowns its declared type — the ADR-0049 A9 posture,
    /// value-domain edition), a name the runtime does not know as a function, a
    /// return type not representable as a single value-domain [`Fact`] (a
    /// multi-base union such as `int|false` — deferred to the contract-lane arms),
    /// or no return type at all. The default is `None` (the
    /// sound subset — ADR-0004). Always seeded at the `Verified` stratum: it is a
    /// native declaration read off the engine's own arginfo (§2), never demoted to
    /// Asserted. `name` is the call's simple name (the fold path's key).
    fn builtin_return_fact(&mut self, name: &str) -> Option<Fact> {
        let _ = name;
        None
    }

    /// The **reflected return-type declaration** of a uniquely-resolved builtin
    /// `name` — the `(string)` rendering of the running engine's own
    /// `ReflectionFunction::getReturnType()` (`"array"`, `"string|int|null"`).
    ///
    /// This is [`Self::builtin_return_fact`]'s raw sibling, for the transfers
    /// whose result is not a scalar the value domain names in a single `Fact`
    /// (ADR-0062 §4's positional projections return arrays; `array_key_first`
    /// returns an `int|string|null` union). It carries the *same* gates —
    /// a live sidecar and no runtime-redefinition extension loaded (ADR-0049 A9:
    /// a monkey-patched builtin disowns its declared type) — so a rule admitted
    /// through it is admitted on exactly the ADR-0061 §2 evidence, unweakened.
    /// The default is `None`: the sound subset withholds the rule.
    fn builtin_return_type(&mut self, name: &str) -> Option<String> {
        let _ = name;
        None
    }

    /// The **reflected parameter counts** of a uniquely-resolved builtin `name` —
    /// `(getNumberOfParameters(), getNumberOfRequiredParameters())` off the running
    /// engine's own signature.
    ///
    /// This is the **arity second leg** of ADR-0064's mixed-pin ruling. The
    /// declaration pin ([`Self::builtin_return_type`]) is what countersigns a
    /// structural transfer — but a name declaring a bare `mixed` (the whole array
    /// read-position family: `current`, `array_pop`, `array_first`, …) pins
    /// *nothing*: `mixed` is compatible with any rule output, so the check degenerates
    /// to a presence test. The ruling is that such a rule is inadmissible on the
    /// declaration alone and must additionally pin the live signature, which is a
    /// real, movable fact about this engine's version of the function.
    ///
    /// It carries the same gates the declaration does — a live sidecar, no
    /// runtime-redefinition extension loaded — so nothing is weakened by using it.
    /// The default is `None`: no arity, no rule (the sound subset, ADR-0004), which
    /// is also what an older runner's reply and every pre-arity replay table yield.
    fn builtin_param_counts(&mut self, name: &str) -> Option<(u32, u32)> {
        let _ = name;
        None
    }
}

/// The runtime-redefinition extensions that void the absence family (ADR-0049 A9):
/// with any of them loaded, a defined class can gain a method and a missing name
/// can be minted at runtime, so no absence claim holds. Matched case-insensitively
/// against the sidecar's loaded-extension list. Public so `doctor` (ADR-0054 §9.1)
/// can name a loaded monkey-patch extension from the same single source of truth.
pub const MONKEY_PATCH_EXTENSIONS: &[&str] = &["uopz", "runkit7", "runkit", "componere"];

/// The sound-subset folder: never folds anything. This is what the salsa
/// [`diagnostics`] query uses, keeping that query deterministic.
pub struct NoFold;

impl Folder for NoFold {
    fn fold(&mut self, _name: &str, _args: &[ArgValue]) -> Option<ArgValue> {
        None
    }
}

// ---------------------------------------------------------------------------
// The fold seam, split transport-from-policy (ADR-0066).
//
// `FoldEngine` is the transport: three questions, no judgment. `EngineFolder` is
// the policy: every memo, every gate, the whole ADR-0056 admission sequence — and
// it exists EXACTLY ONCE, generic over the transport. That is the point of the
// split. The browser's replay transport (issue #64) and the native process
// transport answer the same questions, so they cannot disagree about what the
// answers MEAN; issue #63 was a bug in precisely this seam, found only because a
// second caller reached the policy by a second path.
// ---------------------------------------------------------------------------

/// The **transport** half of the fold seam: the three questions the analysis puts
/// to the project's own PHP (ADR-0004/0024), with no policy attached.
///
/// An implementation answers or declines; it never decides what an answer licenses.
/// [`ProcessEngine`] talks to a resident `php` child, and [`TableEngine`] answers
/// from a supplied memo table and records its misses (ADR-0066).
///
/// Declining is spelled the way the wire spells it: `None` for `env`/`reflect`,
/// [`FoldResult::Widen`] for `fold`. No implementation may fabricate an answer —
/// a wrong answer here becomes a wrong diagnostic, which is the one thing the
/// zero-FP contract forbids.
pub trait FoldEngine {
    /// The engine's environment (version, loaded extensions, SAPI, integer width).
    fn env(&mut self) -> Option<EnvInfo>;
    /// Whether the engine knows `target` as a resident function / class-like, plus
    /// its declared return type when it is a function.
    fn reflect(&mut self, target: &str) -> Option<Reflection>;
    /// Run `name(args)` on the engine and report the outcome.
    fn fold(&mut self, name: &str, args: &[FoldArg]) -> FoldResult;
}

/// The **policy** half of the fold seam: a [`Folder`] over any [`FoldEngine`],
/// carrying every per-run memo and every admission gate.
///
/// Two folders ship on top of it — [`SidecarFolder`] (the resident `php` child)
/// and [`TableFolder`] (the replay table) — and they differ ONLY in their engine.
/// Every question of *what an answer licenses* is decided here: the A9
/// monkey-patch veto, the issue-#28 target/runtime agreement, the ADR-0056 curated
/// admission gates, the issue-#64 integer-width gate. A gate added here is added
/// for both transports at once, which is the property the split exists to buy.
pub struct EngineFolder<E: FoldEngine> {
    engine: E,
    memo: HashMap<(String, Vec<ArgValue>), Option<ArgValue>>,
    /// Cached ADR-0049 A9 verdict: whether the absence family is available (a live
    /// engine and no monkey-patch extension). Computed once from `env` and then
    /// memoized — a whole-run property (ADR-0048 query answer).
    absence_available: Option<bool>,
    /// Per-FQN memo of the A2ii homonym oracle so a repeated chain class never
    /// triggers duplicate `reflect` traffic.
    boot_surface_memo: HashMap<String, Option<bool>>,
    /// Per-FQN memo of the arity family's function-homonym oracle (ADR-0049 §6),
    /// the function-namespace analogue of [`Self::boot_surface_memo`].
    boot_surface_fn_memo: HashMap<String, Option<bool>>,
    /// Memoized project PHP `(major, minor)` from `env` (ADR-0052 A11) — a
    /// whole-run query answer. `Some(None)` records "asked, unanswerable".
    php_minor: Option<Option<(u16, u16)>>,
    /// Memoized `PHP_INT_SIZE` from `env` (issue #64) — the engine's integer width
    /// in bytes. `Some(None)` records "asked, unanswerable". Engine-intrinsic, so
    /// unlike the target-dependent memos it survives [`Self::set_php_target`].
    int_size: Option<Option<u32>>,
    /// Memoized boot-surface description (`PHP 8.5.8 (32 extensions)`) from `env`
    /// — the ADR-0049 §9 message register's closure-evidence clause for the
    /// existence ids. `Some(None)` records "asked, unanswerable".
    boot_surface_label: Option<Option<String>>,
    /// Per-name memo of the builtin return-fact (ADR-0056 R1) so a repeated call to
    /// the same builtin never triggers duplicate `reflect` traffic. Keyed by the
    /// lowercased simple name (PHP function names are case-insensitive).
    return_fact_memo: HashMap<String, Option<Fact>>,
    /// Per-name memo of the raw reflected return-type declaration (ADR-0062 S7's
    /// projection gate), the string sibling of [`Self::return_fact_memo`].
    return_type_memo: HashMap<String, Option<String>>,
    /// Per-name memo of the reflected `(total, required)` parameter counts —
    /// ADR-0064's mixed-pin second leg, riding the same `reflect` reply as the two
    /// memos above and following the same per-name pattern.
    param_counts_memo: HashMap<String, Option<(u32, u32)>>,
    /// The project's declared target PHP range (issue #28), when the layout
    /// resolved one. Set by the CLI after layout discovery; gates the absence
    /// family (the boot surface interrogated must be a declared-supported
    /// version) and the curated return-fact admission.
    php_target: Option<steins_db::PhpTarget>,
}

impl<E: FoldEngine> EngineFolder<E> {
    /// Wrap `engine` in the shared policy. Every memo starts empty: a folder is a
    /// per-run object, and its answers are whole-run query answers (ADR-0048).
    pub fn with_engine(engine: E) -> Self {
        Self {
            engine,
            memo: HashMap::new(),
            absence_available: None,
            boot_surface_memo: HashMap::new(),
            boot_surface_fn_memo: HashMap::new(),
            php_minor: None,
            int_size: None,
            boot_surface_label: None,
            return_fact_memo: HashMap::new(),
            return_type_memo: HashMap::new(),
            param_counts_memo: HashMap::new(),
            php_target: None,
        }
    }

    /// The engine, for a caller that owns transport-specific state on it (the
    /// replay transport's pending list).
    pub fn engine_mut(&mut self) -> &mut E {
        &mut self.engine
    }

    /// Declare the project's target PHP range (issue #28), from the resolved
    /// layout. Target-dependent memos are dropped on a change, so a resident
    /// folder reused across projects (the corpus gate's thread-local) answers
    /// each project under its own target.
    ///
    /// The env-derived memos (`php_minor`, `int_size`) are NOT dropped: they
    /// describe the engine, not the project, and no target changes what version
    /// the engine is or how wide its integers are.
    pub fn set_php_target(&mut self, target: Option<steins_db::PhpTarget>) {
        if self.php_target != target {
            self.absence_available = None;
            self.return_fact_memo.clear();
            self.return_type_memo.clear();
            self.param_counts_memo.clear();
            self.boot_surface_memo.clear();
            self.boot_surface_fn_memo.clear();
        }
        self.php_target = target;
    }

    /// The engine's integer width in bytes (`PHP_INT_SIZE`), memoized like the
    /// other whole-run `env` answers. `None` = unanswerable, which every caller
    /// here treats as "not provably 64-bit".
    fn engine_int_size(&mut self) -> Option<u32> {
        if let Some(cached) = self.int_size {
            return cached;
        }
        let answer = self.engine.env().and_then(|e| e.int_size);
        self.int_size = Some(answer);
        answer
    }

    /// Whether the engine's integer machine is the one every value rule here
    /// assumes: 64-bit (issue #64).
    ///
    /// A minor is not a machine. php-wasm 0.1.0 is PHP 8.5.2 — the pinned minor,
    /// which every existing version gate admits — built 32-bit, and on it
    /// `ip2long('255.255.255.255')` is `-1`, `crc32('x')` is negative, `1 << 40` is
    /// `0`, `hexdec('FFFFFFFFF')` promotes to float and `strtotime('2040-01-01')` is
    /// `false`. Those are silently wrong *values*, not failures: nothing widens,
    /// nothing throws, and a fold would carry the wrong literal straight into a
    /// proof. So the ADR-0056 curated admission requires a **provably** 64-bit
    /// engine, and an unknown width declines.
    ///
    /// This is the CURATED-ROW leg, and it stays all-or-nothing on purpose. A
    /// curated row is a claim about a builtin's whole return domain, verified
    /// against the 64-bit engine at `PINNED_PHP`; there is no per-call argument
    /// tuple to range-check it against, so there is nothing for the fold lane's
    /// width-safe subset (below) to be the analogue of.
    fn engine_is_64_bit(&mut self) -> bool {
        self.engine_int_size() == Some(8)
    }

    /// Gate 2 of the ADR-0056 §2 admission sequence, on its own: whether a
    /// **curated** return-fact row may refine the reflected envelope.
    ///
    /// A curated row is verified against the 64-bit engine at
    /// [`steins_catalog::PINNED_PHP`] and nowhere else, so the row is admitted only
    /// when the analysis is about exactly that version *and* that machine. With a
    /// declared target (issue #28) the WHOLE range must be the pin; with no target
    /// the runtime-vs-pin comparison stands as it did before #28.
    ///
    /// Extracted so [`Self::surface_summary`] reports the same verdict the gate
    /// applies rather than a second copy of it.
    fn curated_rows_admitted(&mut self) -> bool {
        self.engine_is_64_bit()
            && match &self.php_target {
                Some(t) => t.is_exactly(steins_catalog::PINNED_PHP),
                None => self.php_minor() == Some(steins_catalog::PINNED_PHP),
            }
    }

    /// Describe the engine surface **as this folder's own gates see it** — the
    /// data a frontend needs to state its precision boundary (issue #64 S3).
    ///
    /// Every field is read off the same helpers that decide admission
    /// ([`Self::boot_surface_label`], `engine_int_size`, `fold_lane_at_width`,
    /// `curated_rows_admitted`, [`Folder::absence_family_available`] — the last two
    /// private, hence plain spans), so a description and the behaviour it
    /// describes cannot drift: changing a gate changes what this reports, in the
    /// same commit and by construction. Nothing here is prose — the wording of the
    /// boundary belongs to whoever renders it.
    ///
    /// Asking is not free of consequence on the replay transport: an unanswered
    /// `env` is recorded as pending exactly as any other miss is, so a caller that
    /// summarizes *before* collecting pending gets a run that asks for the boot
    /// surface it could not describe, and converges one iteration later with it.
    /// That is the intended shape: a converged run always has a complete summary.
    pub fn surface_summary(&mut self) -> SurfaceSummary {
        let label = self.boot_surface_label();
        let php_version = self.engine.env().map(|e| e.php_version);
        let int_size = self.engine_int_size();
        SurfaceSummary {
            label,
            php_version,
            int_size,
            fold_lane: fold_lane_at_width(int_size),
            curated_rows: self.absence_family_available() && self.curated_rows_admitted(),
            absence_family: self.absence_family_available(),
            fold_total: steins_catalog::width_safe_names().len()
                + steins_catalog::width_refused_names().len(),
            fold_safe: steins_catalog::width_safe_names().len(),
            refused_folds: steins_catalog::width_refused_names(),
        }
    }

    /// Compute the builtin return fact for `key` (already lowercased) — the
    /// admission gate of ADR-0056 §2 assembled from three whole-run engine
    /// answers. Called once per name; [`Folder::builtin_return_fact`] memoizes.
    fn compute_builtin_return_fact(&mut self, key: &str) -> Option<Fact> {
        // Gate 1 — a live engine and no runtime-redefinition extension. A
        // monkey-patched builtin (uopz/runkit7/Componere) can return a type its
        // native declaration disowns, so the reflected envelope is not trustworthy;
        // this is the ADR-0049 A9 posture applied to the value domain. Also covers
        // the no-engine sound subset (returns `false`).
        if !self.absence_family_available() {
            return None;
        }
        // Gate 2 (minor pin, ADR-0052 A11 / ADR-0056 §2, target-aware per issue
        // #28) — governs the CURATED refinement only; the reflected envelope is
        // version-correct by construction and needs no pin. A curated row is
        // verified at PINNED_PHP and nowhere else, so with a declared target the
        // row is admitted only when the WHOLE range is the pin (`§2`'s hole is
        // exactly cross-version drift); with no target, the runtime-vs-pin
        // comparison stands as before.
        //
        // The pin is a version AND a machine (issue #64): a curated row is verified
        // against the 64-bit engine at that minor, and a 32-bit engine at the SAME
        // minor can violate it (`hexdec` returning float where the row says int).
        // The reflected envelope is unaffected — a declared return type is a
        // platform-independent claim, and the 32-bit build reports the same ones —
        // so an unpinned or narrow-integer engine still SEEDS, it just does not
        // get the curated refinement.
        let minor_matches_pin = self.curated_rows_admitted();
        // The reflected return envelope — the running engine's own declaration.
        let refl = self.engine.reflect(key)?;
        if !refl.function_exists {
            return None;
        }
        let return_type = refl.return_type.as_deref()?;
        let curated = steins_catalog::return_fact(key);
        admit_return_fact(return_type, curated, minor_matches_pin)
    }

    /// The raw reflected return-type declaration for `key` (already lowercased),
    /// under the same A9 / sound-subset gate [`Self::compute_builtin_return_fact`]
    /// applies. Called once per name; [`Folder::builtin_return_type`] memoizes.
    ///
    /// No integer-width gate: this is the engine's own declaration read back
    /// verbatim, and a declaration does not change with the integer machine.
    fn compute_builtin_return_type(&mut self, key: &str) -> Option<String> {
        if !self.absence_family_available() {
            return None;
        }
        let refl = self.engine.reflect(key)?;
        refl.function_exists.then_some(refl.return_type).flatten()
    }

    /// The reflected `(total, required)` parameter counts for `key` (already
    /// lowercased), under the same gate the two computations above apply. Called
    /// once per name; [`Folder::builtin_param_counts`] memoizes.
    ///
    /// Both counts must be present: a reply carrying one and not the other is not a
    /// signature, and a half-known arity pins nothing.
    fn compute_builtin_param_counts(&mut self, key: &str) -> Option<(u32, u32)> {
        if !self.absence_family_available() {
            return None;
        }
        let refl = self.engine.reflect(key)?;
        if !refl.function_exists {
            return None;
        }
        Some((refl.params_total?, refl.params_required?))
    }
}

impl<E: FoldEngine> Folder for EngineFolder<E> {
    fn fold(&mut self, name: &str, args: &[ArgValue]) -> Option<ArgValue> {
        let key = (name.to_owned(), args.to_vec());
        if let Some(cached) = self.memo.get(&key) {
            return cached.clone();
        }
        let folded = self.fold_uncached(name, args);
        self.memo.insert(key, folded.clone());
        folded
    }

    fn absence_family_available(&mut self) -> bool {
        if let Some(cached) = self.absence_available {
            return cached;
        }
        // No live engine ⇒ the family is silent (the ADR-0004 sound subset covers
        // it — A2ii). Otherwise consult the loaded-extension list once (A9), and
        // (issue #28) require the runtime to BE a declared-supported version:
        // every absence claim is evidence about THIS boot surface, and proof of
        // absence on a version the project does not ship on proves nothing about
        // the versions it does. A runtime inside the declared range stays a
        // legitimate witness — absence on it is a break on a supported version.
        //
        // The integer width is NOT consulted: existence is not arithmetic. A
        // 32-bit engine knows exactly the same names as a 64-bit one at the same
        // version, so an absence claim from it is as good.
        let target_admits_runtime = |minor: Option<(u16, u16)>, t: &Option<steins_db::PhpTarget>| {
            match (t, minor) {
                (Some(t), Some(m)) => t.contains(m),
                (Some(_), None) => false, // a declared target, an unparseable runtime: no witness
                (None, _) => true,        // no declaration: the pre-#28 posture
            }
        };
        let verdict = match self.engine.env() {
            Some(env) => {
                let clean = !env.extensions.iter().any(|e| {
                    MONKEY_PATCH_EXTENSIONS.iter().any(|m| e.eq_ignore_ascii_case(m))
                });
                let minor = parse_php_minor(&env.php_version);
                clean && target_admits_runtime(minor, &self.php_target)
            }
            None => false,
        };
        self.absence_available = Some(verdict);
        verdict
    }

    fn boot_surface_class_like(&mut self, fqn: &str) -> Option<bool> {
        if let Some(cached) = self.boot_surface_memo.get(fqn) {
            return *cached;
        }
        let answer = self.engine.reflect(fqn).map(|r| r.class_like_exists);
        self.boot_surface_memo.insert(fqn.to_owned(), answer);
        answer
    }

    fn boot_surface_function(&mut self, fqn: &str) -> Option<bool> {
        if let Some(cached) = self.boot_surface_fn_memo.get(fqn) {
            return *cached;
        }
        let answer = self.engine.reflect(fqn).map(|r| r.function_exists);
        self.boot_surface_fn_memo.insert(fqn.to_owned(), answer);
        answer
    }

    fn php_minor(&mut self) -> Option<(u16, u16)> {
        if let Some(cached) = self.php_minor {
            return cached;
        }
        // Parse the engine-reported `php_version` (`"8.5.8"`) to `(major, minor)`;
        // an unparseable / absent report stays `None` (no detectable skew — A11).
        let answer = self.engine.env().and_then(|e| parse_php_minor(&e.php_version));
        self.php_minor = Some(answer);
        answer
    }

    fn boot_surface_label(&mut self) -> Option<String> {
        if let Some(cached) = &self.boot_surface_label {
            return cached.clone();
        }
        let answer = self
            .engine
            .env()
            .map(|e| format!("PHP {} ({} extensions)", e.php_version, e.extensions.len()));
        self.boot_surface_label = Some(answer.clone());
        answer
    }

    fn builtin_return_fact(&mut self, name: &str) -> Option<Fact> {
        let key = name.to_ascii_lowercase();
        if let Some(cached) = self.return_fact_memo.get(&key) {
            return cached.clone();
        }
        let answer = self.compute_builtin_return_fact(&key);
        self.return_fact_memo.insert(key, answer.clone());
        answer
    }

    fn builtin_return_type(&mut self, name: &str) -> Option<String> {
        let key = name.to_ascii_lowercase();
        if let Some(cached) = self.return_type_memo.get(&key) {
            return cached.clone();
        }
        let answer = self.compute_builtin_return_type(&key);
        self.return_type_memo.insert(key, answer.clone());
        answer
    }

    fn builtin_param_counts(&mut self, name: &str) -> Option<(u32, u32)> {
        let key = name.to_ascii_lowercase();
        if let Some(cached) = self.param_counts_memo.get(&key) {
            return *cached;
        }
        let answer = self.compute_builtin_param_counts(&key);
        self.param_counts_memo.insert(key, answer);
        answer
    }
}

impl<E: FoldEngine> EngineFolder<E> {
    /// The uncached body of [`Folder::fold`].
    fn fold_uncached(&mut self, name: &str, args: &[ArgValue]) -> Option<ArgValue> {
        // The integer-width gate (issue #64): a fold is a VALUE, and a 32-bit
        // engine answers arithmetic questions differently while failing at
        // nothing. Asked before the engine is dispatched to, so a narrow engine
        // is never handed a question its machine would answer wrongly.
        //
        // The width is asked FIRST, before the arguments are even encoded, so the
        // first iteration of a replay loop reports the `env` question and nothing
        // else — the round trip that establishes the machine.
        let width = self.engine_int_size();
        let fargs: Vec<FoldArg> = args.iter().filter_map(arg_to_fold).collect();
        if fargs.len() != args.len() {
            return None;
        }
        if !fold_admitted_at_width(width, name, &fargs) {
            return None;
        }
        match self.engine.fold(name, &fargs) {
            FoldResult::Value(v) => fold_value_to_arg(&v),
            FoldResult::Throw { .. } | FoldResult::Widen { .. } => None,
        }
    }
}

/// The fold lane's integer-width admission (issue #64 S1.5) — a pure function of
/// the engine's reported `PHP_INT_SIZE`, the callee, and the encoded arguments.
///
/// Three cases, and only three:
///
/// * `Some(8)` — the machine every value rule here assumes. Admit everything, so
///   this is byte-identical to the pre-S1.5 behaviour on every native run.
/// * `Some(4)` — the **width-safe subset**. Admit `name` only when the catalog
///   certifies it ([`steins_catalog::width_safe`]) *and* every integer occurring
///   anywhere in the arguments is inside [`I32_SAFE`]. Both legs are required:
///   the catalog verdict is stated for exactly the tuples this range guard admits,
///   so neither leg means anything alone.
/// * anything else (`None`, or a width nobody has verified) — **default-deny**.
///   An old or foreign runner is unknown, not assumed; and there is no verified
///   subset for a 16-bit or 128-bit machine because nobody has probed one.
///
/// Declining is spelled as it always was: the caller returns `None`, which widens.
/// Nothing here fabricates, and nothing here narrows on a guess.
fn fold_admitted_at_width(int_size: Option<u32>, name: &str, args: &[FoldArg]) -> bool {
    match fold_lane_at_width(int_size) {
        FoldLane::Full => true,
        FoldLane::WidthSafeSubset => {
            steins_catalog::width_safe(name) && args.iter().all(fold_arg_fits_i32)
        }
        FoldLane::Declined => false,
    }
}

/// Which fold lane an engine of this integer width gets — the width half of
/// [`fold_admitted_at_width`], named so a description of the boundary
/// ([`EngineFolder::surface_summary`]) reads the same three cases the gate
/// branches on instead of restating them.
fn fold_lane_at_width(int_size: Option<u32>) -> FoldLane {
    match int_size {
        Some(8) => FoldLane::Full,
        Some(4) => FoldLane::WidthSafeSubset,
        _ => FoldLane::Declined,
    }
}

/// The fold lane an engine's integer width admits (issue #64 / ADR-0066 §4 and its
/// S1.5 amendment).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FoldLane {
    /// A provably 64-bit engine: the whole [`steins_catalog::foldable`] allowlist,
    /// which is the machine every value rule here assumes.
    Full,
    /// A provably 32-bit engine: [`steins_catalog::width_safe_names`] only, and
    /// only for argument tuples the range guard admits.
    WidthSafeSubset,
    /// An unreported or unprobed width: nothing folds. Default-deny — an old or
    /// foreign runner is unknown, not assumed.
    Declined,
}

impl FoldLane {
    /// A stable machine-readable spelling, for an envelope that carries the lane
    /// as data (the playground's boot object).
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Full => "full",
            Self::WidthSafeSubset => "width_safe_subset",
            Self::Declined => "declined",
        }
    }
}

/// The engine surface as the shared fold policy sees it — what
/// [`EngineFolder::surface_summary`] answers.
///
/// This is **data about the gates**, not prose about them: each field is the
/// verdict of a gate that is applied elsewhere in this file, read from the same
/// helper. A renderer decides what to say; nothing here decides for it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SurfaceSummary {
    /// The ADR-0049 §9 boot-surface label (`PHP 8.5.2 (32 extensions)`), or `None`
    /// when no engine answered.
    pub label: Option<String>,
    /// The engine's own `PHP_VERSION`, verbatim.
    pub php_version: Option<String>,
    /// `PHP_INT_SIZE` in bytes. `None` = unreported, which every gate here reads
    /// as "not provably anything".
    pub int_size: Option<u32>,
    /// Which builtins may fold at that width.
    pub fold_lane: FoldLane,
    /// Whether a curated return-fact row may refine a reflected envelope — both
    /// ADR-0056 gates, conjoined as the admission sequence conjoins them.
    pub curated_rows: bool,
    /// Whether the ADR-0049 A9 absence family is available (a live engine, no
    /// monkey-patch extension, and a runtime the declared target admits).
    pub absence_family: bool,
    /// The size of the folding allowlist, and how much of it
    /// [`FoldLane::WidthSafeSubset`] keeps — the catalog's own counts, so a
    /// renderer states the boundary without a number of its own.
    pub fold_total: usize,
    /// See [`Self::fold_total`].
    pub fold_safe: usize,
    /// The folds a [`FoldLane::WidthSafeSubset`] engine does **not** get, by name:
    /// the catalog complement (`foldable ∧ !width_safe`), never a second list.
    pub refused_folds: &'static [&'static str],
}

/// The 32-bit argument range guard: `[-(2^31 - 1), 2^31 - 1]`.
///
/// Deliberately **not** `-2^31`. `PHP_INT_MIN` on a 32-bit engine is the one
/// integer whose magnitude is not representable, so it is the seed of every
/// boundary flip — `abs(-2147483648)` promotes to float there and stays `int` on
/// a 64-bit engine. Excluding it means no admitted integer has an out-of-range
/// magnitude, which is what makes the `abs`-shaped flip structurally unreachable
/// rather than merely unobserved. The cost is one value per call site.
const I32_SAFE: std::ops::RangeInclusive<i64> = -2_147_483_647..=2_147_483_647;

/// Whether every integer `arg` carries is inside [`I32_SAFE`] — recursively
/// through array literals, and over **keys as well as values**.
///
/// The keys matter as much as the values. `count([3000000000 => 'a', 'b'])` has no
/// out-of-range integer *value*, and yet the key decides what PHP's next-int rule
/// assigns to `'b'` and therefore whether the array has one element or two. Only
/// `FoldKey::Int` is charged: a `FoldKey::Str` is a string key by the time it
/// reaches the wire (lowering already applied PHP's key normalization), and a
/// `FoldArg::Float` is an IEEE double on both machines.
fn fold_arg_fits_i32(arg: &FoldArg) -> bool {
    match arg {
        FoldArg::Int(v) => I32_SAFE.contains(v),
        FoldArg::Array(entries) => entries.iter().all(|(k, v)| {
            let key_ok = !matches!(k, Some(FoldKey::Int(i)) if !I32_SAFE.contains(i));
            key_ok && fold_arg_fits_i32(v)
        }),
        FoldArg::Float(_) | FoldArg::Str(_) | FoldArg::Bool(_) | FoldArg::Null => true,
    }
}

// ---------------------------------------------------------------------------
// The native transport: a resident `php` child.
// ---------------------------------------------------------------------------

/// The process [`FoldEngine`]: a lazily-spawned PHP [`Sidecar`] (ADR-0004/0024).
///
/// Owns exactly the transport's own state — whether folding is disabled, whether
/// the spawn already failed, whether the sound-subset notice has been printed,
/// and (issue #110) whether the "stopped answering" notice has been printed.
/// No analysis policy lives here; that is [`EngineFolder`]'s.
#[cfg(not(target_arch = "wasm32"))]
pub struct ProcessEngine {
    sidecar: Option<Sidecar>,
    disabled: bool,
    spawn_failed: bool,
    notified: bool,
    /// Whether [`SIDECAR_HANDSHAKE_NOTICE`] has already been printed this run —
    /// the issue #110 latch, sibling to `notified` above but for "spawned, then
    /// a request went unanswered" rather than "could not spawn at all". The two
    /// notices are mutually exclusive per instance (a spawn failure never
    /// reaches a live sidecar to poison), but are kept as separate flags since
    /// they guard different text and, unlike `notified`, this one can still be
    /// meaningfully false after `ensure` has long since stopped being consulted.
    ///
    /// A prior revision also tracked "has any request ever succeeded" and used
    /// that to permanently suppress this notice after the first success — on
    /// the theory that later poisoning is always the respawn-tolerant failure
    /// mode `Sidecar`'s own doc comment describes, and therefore not silent
    /// incompleteness. That theory does not hold: `Sidecar`'s own contract is
    /// that "the request whose reply never arrived still fails... it is never
    /// retried" — respawn makes the INSTANCE recover, it does not un-widen the
    /// answer that request already lost. A mid-run timeout after a healthy
    /// opening handshake is exactly as silent, to the caller, as one at the
    /// very start, and the issue's own acceptance criterion says so ("fails or
    /// times out mid-run"). So this is a plain once-per-run latch now, armed by
    /// the first poisoning event at any point in the run — no permanent
    /// suppression from an earlier success (review finding on PR #134).
    unresponsive_notified: bool,
}

#[cfg(not(target_arch = "wasm32"))]
impl ProcessEngine {
    /// `disabled` (the CLI's `--no-php`) makes this a permanent no-op that never
    /// spawns PHP, and never announces the sound subset (the user asked for it).
    #[must_use]
    pub fn new(disabled: bool) -> Self {
        Self {
            sidecar: None,
            disabled,
            spawn_failed: false,
            notified: true, // suppress our own notice; only spawn-failure re-arms it.
            unresponsive_notified: true, // suppress; only enabled() re-arms it (mirrors `notified`).
        }
    }

    /// An enabled engine that emits the sound-subset notice itself if it cannot
    /// spawn PHP, or the "stopped answering" notice the first time a request
    /// poisons the sidecar, at any point in the run.
    #[must_use]
    pub fn enabled() -> Self {
        Self { notified: false, unresponsive_notified: false, ..Self::new(false) }
    }

    /// Ensure a live sidecar, or record that we cannot have one.
    fn ensure(&mut self) -> Option<&mut Sidecar> {
        if self.disabled || self.spawn_failed {
            return None;
        }
        if self.sidecar.is_none() {
            match Sidecar::spawn() {
                Ok(sc) => self.sidecar = Some(sc),
                Err(_) => {
                    self.spawn_failed = true;
                    if !self.notified {
                        // The one place a *library* crate writes to a user-facing
                        // stream, and it obeys the CLI's output seam rule (issue
                        // #44): `eprintln!` panics when the write fails, and
                        // `steins check 2>&1 | head` closes stderr like any other
                        // pipe. A lost notice is not a reason to abort a run, so
                        // the error is dropped rather than propagated — the seam's
                        // stderr policy, stated in `steins-cli/src/out.rs`.
                        use std::io::Write;
                        let _ = writeln!(std::io::stderr(), "{SOUND_SUBSET_NOTICE}");
                        self.notified = true;
                    }
                    return None;
                }
            }
        }
        self.sidecar.as_mut()
    }

    /// Run one request against the live sidecar (spawning it first if needed),
    /// then check the issue #110 latch from the transport's OWN post-call state
    /// (`Sidecar::is_poisoned`) rather than from `op`'s return value: a `fold`
    /// that legitimately widens — an argument out of the width-safe range, a
    /// callee not on the allowlist, an exception result — is not a transport
    /// failure and must never arm the notice; only the child actually going
    /// silent or dying does. `None` when no sidecar can be had at all (disabled,
    /// or a prior spawn already failed — [`Self::ensure`] already speaks for
    /// that case).
    fn call<T>(&mut self, op: impl FnOnce(&mut Sidecar) -> T) -> Option<T> {
        let sc = self.ensure()?;
        let result = op(sc);
        if sc.is_poisoned() {
            self.note_unresponsive();
        }
        Some(result)
    }

    /// The latch body: the request [`Self::call`] just ran left the sidecar
    /// poisoned. Prints [`SIDECAR_HANDSHAKE_NOTICE`] on the FIRST such event in
    /// the run, wherever it falls — the opening `env()` handshake or a request
    /// deep into an otherwise-healthy run — and never again after. There is
    /// deliberately no "but a request succeeded before this one" escape: a
    /// widened request stays widened regardless of what the sidecar does next
    /// (`Sidecar`'s own contract — a lost reply is never retried), so a mid-run
    /// failure is exactly as silent to the caller as one at the very start.
    fn note_unresponsive(&mut self) {
        if self.unresponsive_notified {
            return;
        }
        self.unresponsive_notified = true;
        // Same stderr policy as the spawn-failure notice above: a dropped write
        // is not a reason to abort a run (issue #44 / steins-cli/src/out.rs).
        use std::io::Write;
        let _ = writeln!(std::io::stderr(), "{SIDECAR_HANDSHAKE_NOTICE}");
    }

    /// Send `method`/`params` verbatim to the child and return the raw `result`.
    /// The native answering half of an ADR-0066 replay request; `None` when no
    /// sidecar can be had or the request failed.
    pub fn call_raw(&mut self, method: &str, params: serde_json::Value) -> Option<serde_json::Value> {
        self.call(|sc| sc.call_raw(method, params)).flatten()
    }
}

#[cfg(not(target_arch = "wasm32"))]
impl FoldEngine for ProcessEngine {
    fn env(&mut self) -> Option<EnvInfo> {
        self.call(Sidecar::env).flatten()
    }

    fn reflect(&mut self, target: &str) -> Option<Reflection> {
        self.call(|sc| sc.reflect(target)).flatten()
    }

    fn fold(&mut self, name: &str, args: &[FoldArg]) -> FoldResult {
        self.call(|sc| sc.fold(name, args)).unwrap_or_else(|| FoldResult::widen("no sidecar"))
    }
}

/// The default native folder: the shared policy over the process transport.
///
/// A type alias, not a wrapper — [`EngineFolder`] IS the policy, and giving the
/// native pairing a name keeps every existing call site (`SidecarFolder::new`,
/// `SidecarFolder::enabled`, `set_php_target`, `impl Folder`) spelled as before.
#[cfg(not(target_arch = "wasm32"))]
pub type SidecarFolder = EngineFolder<ProcessEngine>;

#[cfg(not(target_arch = "wasm32"))]
impl EngineFolder<ProcessEngine> {
    /// Create a folder. `disabled` (the CLI's `--no-php`) makes it a permanent
    /// no-op that never spawns PHP.
    #[must_use]
    pub fn new(disabled: bool) -> Self {
        Self::with_engine(ProcessEngine::new(disabled))
    }

    /// Create an enabled folder that will emit the sound-subset notice itself if
    /// it cannot spawn PHP.
    #[must_use]
    pub fn enabled() -> Self {
        Self::with_engine(ProcessEngine::enabled())
    }
}

// ---------------------------------------------------------------------------
// The replay transport: a supplied answer table, plus the misses (ADR-0066).
// ---------------------------------------------------------------------------

/// The canonical key of a sidecar request: the JSON-RPC request object **minus its
/// `id`**, serialized.
///
/// `id` is framing, not identity: two `fold(strtoupper, ["ab"])` requests differ in
/// `id` and ask the same question, and a memo table keyed on the whole request
/// would never hit. Everything else IS identity, and it comes from the wire
/// module's own `*_params` constructors, so a key built here and a request sent by
/// the process transport agree by construction.
///
/// The string is also the interchange format: the replay loop hands these keys out
/// as its pending list and takes them back as table keys, and each one parses as
/// `{"method": …, "params": …}` — everything a caller needs to answer it.
#[must_use]
pub fn request_key(method: &str, params: &serde_json::Value) -> String {
    serde_json::json!({ "method": method, "params": params }).to_string()
}

/// The replay [`FoldEngine`] (ADR-0066): answers from a supplied table of
/// already-known results, and records the questions it could not answer.
///
/// This is the transport that makes the sidecar surface reachable where no
/// process can be spawned — the browser (issue #64), where php-wasm answers
/// asynchronously and the analysis walk is synchronous. One run is one pass: a
/// miss declines *immediately* and is appended to [`Self::pending`], the caller
/// answers the pending set and runs again, and the answered set strictly grows,
/// so the fixpoint terminates. The iteration cap lives with the caller.
///
/// **A miss never fabricates.** It declines exactly as a dead sidecar declines,
/// which means a run with non-empty pending is a NoFold-grade run: sound, less
/// precise, and never to be shown to a user as if it were complete.
pub struct TableEngine {
    /// `request_key` → the raw JSON-RPC `result` value for that request.
    table: HashMap<String, serde_json::Value>,
    /// The misses, in order of first occurrence, deduped.
    pending: Vec<String>,
    /// Membership index for `pending`'s dedupe.
    asked: HashSet<String>,
}

impl TableEngine {
    /// A replay engine over `table` (`request_key` → raw `result` value). An empty
    /// table is the normal starting point: the first run answers nothing and
    /// reports every question the walk asked.
    #[must_use]
    pub fn new(table: HashMap<String, serde_json::Value>) -> Self {
        Self { table, pending: Vec::new(), asked: HashSet::new() }
    }

    /// The unanswered requests recorded so far, in first-occurrence order.
    #[must_use]
    pub fn pending(&self) -> &[String] {
        &self.pending
    }

    /// Take the unanswered requests, leaving the recorder empty.
    pub fn take_pending(&mut self) -> Vec<String> {
        self.asked.clear();
        std::mem::take(&mut self.pending)
    }

    /// Answer one request from the table, or record the miss and decline.
    fn ask(&mut self, method: &str, params: &serde_json::Value) -> Option<serde_json::Value> {
        let key = request_key(method, params);
        if let Some(answer) = self.table.get(&key) {
            return Some(answer.clone());
        }
        if self.asked.insert(key.clone()) {
            self.pending.push(key);
        }
        None
    }
}

impl FoldEngine for TableEngine {
    fn env(&mut self) -> Option<EnvInfo> {
        let answer = self.ask("env", &steins_sidecar::env_params())?;
        steins_sidecar::parse_env_result(&answer)
    }

    fn reflect(&mut self, target: &str) -> Option<Reflection> {
        let answer = self.ask("reflect", &steins_sidecar::reflect_params(target))?;
        steins_sidecar::parse_reflection_result(&answer, target)
    }

    fn fold(&mut self, name: &str, args: &[FoldArg]) -> FoldResult {
        match self.ask("fold", &steins_sidecar::fold_params(name, args)) {
            Some(answer) => steins_sidecar::parse_fold_result(&answer),
            // Unanswered: the same decline a dead sidecar gives.
            None => FoldResult::widen("pending"),
        }
    }
}

/// The replay folder: the shared policy over the [`TableEngine`] transport.
///
/// # Replayability (ADR-0048)
///
/// A run of this folder is a **pure function of its table**. The walk is already
/// replayable — analysis is a function of (CST, canonical entry state, query
/// answers, fold memo) with no reliance on global ordering — and a `TableFolder`
/// adds nothing that could break that: it consults no clock, no process, no
/// filesystem, and no ambient state. The same source and the same table produce
/// the same findings and the same pending list, every time and on any target.
pub type TableFolder = EngineFolder<TableEngine>;

impl EngineFolder<TableEngine> {
    /// A fresh replay folder over `table`. Fresh per analysis run by construction:
    /// the memos inside are whole-run answers, and reusing them across tables
    /// would let a stale decline outlive the answer that fixes it.
    #[must_use]
    pub fn with_table(table: HashMap<String, serde_json::Value>) -> Self {
        Self::with_engine(TableEngine::new(table))
    }

    /// The unanswered requests this run recorded, in first-occurrence order.
    /// Non-empty ⇒ the run's results are NoFold-degraded and must not be shown.
    #[must_use]
    pub fn pending(&self) -> &[String] {
        self.engine.pending()
    }

    /// Take this run's unanswered requests, leaving the recorder empty.
    pub fn take_pending(&mut self) -> Vec<String> {
        self.engine.take_pending()
    }
}

/// The ADR-0049 A12 boundary: the minor where PHP changed the next-auto-index
/// rule for array literals with negative keys. The one version boundary any
/// value rule keys on today.
const NEXT_INT_BOUNDARY: (u16, u16) = (8, 3);

/// The analysis PHP view (issue #28): fold the sidecar's **runtime** minor and
/// the project's **declared target** into the two per-run answers the checker
/// consumes.
///
/// - The **effective minor** feeds `normalize_array` (ADR-0049 A12): with a
///   declared target, the range must agree on the next-int boundary — a range
///   entirely on one side answers with its floor (any minor on that side picks
///   the same rule), a straddling range answers `None`, which is exactly A12's
///   existing unknown leg (a boundary-sensitive literal declines; every other
///   literal still resolves). With no target, the runtime minor answers, as it
///   did before #28.
/// - The **catalog skew** flag feeds ADR-0052 A11's arm-deletion demotion: the
///   catalog is verified at [`steins_catalog::PINNED_PHP`], so the verdicts are
///   trustworthy only when every version the analysis is about is the pin —
///   a target range is skewed unless it is exactly the pin; no target falls
///   back to the runtime-vs-pin comparison (A11 unchanged).
/// - The **version-id interval** feeds the issue-#29 `PHP_VERSION_ID` guard
///   fold — see [`PhpView::version_id`].
///
/// (This doc describes [`effective_php_view`]; the two small id helpers below
/// are its arithmetic.)
///
/// The lowest `PHP_VERSION_ID` a `(major, minor)` admits (patch `00`).
fn version_id_lo(m: (u16, u16)) -> u32 {
    u32::from(m.0) * 10_000 + u32::from(m.1.min(99)) * 100
}

/// The highest `PHP_VERSION_ID` a `(major, minor)` ceiling admits (patch `99`;
/// a `(maj, u16::MAX)` "any minor of this major" ceiling caps at minor 99 —
/// PHP_VERSION_ID reserves two digits per component).
fn version_id_hi(m: (u16, u16)) -> u32 {
    u32::from(m.0) * 10_000 + u32::from(m.1.min(99)) * 100 + 99
}

/// The per-run PHP view (issues #28/#29): the three version answers the checker
/// consumes, all derived from the one target-or-runtime seam.
#[derive(Debug, PartialEq, Eq)]
struct PhpView {
    /// The effective minor for version-keyed value rules (ADR-0049 A12) — see
    /// [`effective_php_view`].
    effective_minor: Option<(u16, u16)>,
    /// The ADR-0052 A11 catalog-skew flag.
    catalog_skew: bool,
    /// The `PHP_VERSION_ID` interval `[lo, hi]` the analysis is about (issue
    /// #29): the declared target range's, else the runtime minor's (its exact
    /// patch is unknown, so the interval spans the minor). `hi = None` is an
    /// open upper bound; the whole thing `None` when no version is known at all.
    version_id: Option<(u32, Option<u32>)>,
}

fn effective_php_view(
    runtime: Option<(u16, u16)>,
    target: Option<&steins_db::PhpTarget>,
) -> PhpView {
    match target {
        Some(t) => PhpView {
            effective_minor: if t.straddles(NEXT_INT_BOUNDARY) { None } else { Some(t.floor) },
            catalog_skew: !t.is_exactly(steins_catalog::PINNED_PHP),
            version_id: Some((version_id_lo(t.floor), t.ceiling.map(version_id_hi))),
        },
        None => PhpView {
            effective_minor: runtime,
            catalog_skew: runtime.is_some_and(|m| m != steins_catalog::PINNED_PHP),
            version_id: runtime.map(|m| (version_id_lo(m), Some(version_id_hi(m)))),
        },
    }
}

/// Parse a PHP version string (`"8.5.8"`, `"8.5.8-dev"`) to `(major, minor)`.
/// `None` when the first two dotted components are not both integers.
fn parse_php_minor(v: &str) -> Option<(u16, u16)> {
    let mut it = v.split('.');
    let major = it.next()?.parse().ok()?;
    let minor_part = it.next()?;
    // A minor like `5` or `5-dev`: take the leading digit run.
    let minor: u16 = minor_part.trim_matches(|c: char| !c.is_ascii_digit()).parse().ok()?;
    Some((major, minor))
}

/// The fold seam's array budget (issue #39): the greatest number of entries an
/// array argument may contribute, counted **recursively** over nesting, and the
/// deepest nesting a fold argument may have.
///
/// Both exist because a fold argument is serialized, sent over IPC, executed, and
/// used as a memo key — all linear in the literal's size, all paid per call site.
/// The values are chosen to cover every array literal a human writes as a `count`
/// / `in_array` / `implode` argument while refusing the generated 10,000-entry
/// lookup table, where a fold costs real time and buys nothing (its `count` is a
/// number nobody is about to mistype into a `string` parameter). Exceeding either
/// bound **widens** — a miss, never a false positive (ADR-0002).
///
/// The depth bound is also what keeps the recursive encoders here and in the
/// runner off an unbounded stack.
const FOLD_ARRAY_MAX_ENTRIES: usize = 256;
const FOLD_ARRAY_MAX_DEPTH: u8 = 8;

/// The member-wise union fold's bounds (issue #74): at most this many members in
/// any one argument's union, and at most [`UNION_FOLD_COMBINATION_CAP`]
/// combinations across the whole argument list.
///
/// Busting either bound **declines** — [`Cx::try_union_fold`] never truncates the
/// product. A union missing a member is a *wrong* value domain, not a wider one,
/// and widening is the only safe direction (ADR-0002).
const UNION_FOLD_MEMBER_CAP: usize = 4;
const UNION_FOLD_COMBINATION_CAP: usize = 16;

/// Charge `v` against the fold seam's array budget: `false` when it nests deeper
/// than `depth` or its entries (recursively) exhaust `budget`, or when it is not a
/// self-evident value at all. A scalar literal always fits and costs nothing.
///
/// The budget is **per argument**, and both users of it ([`Cx::try_fold`]'s gate
/// and [`arg_to_fold`]'s encoder) charge identically, so the gate's verdict and the
/// encoder's are the same verdict computed twice — never a gate that admits what
/// the encoder then refuses.
fn fits_fold_budget(v: &ArgValue, depth: u8, budget: &mut usize) -> bool {
    match v {
        ArgValue::Array(items) => {
            if depth == 0 {
                return false;
            }
            for (_, el) in items {
                if *budget == 0 {
                    return false;
                }
                *budget -= 1;
                if !fits_fold_budget(el, depth - 1, budget) {
                    return false;
                }
            }
            true
        }
        v => v.is_literal(),
    }
}

/// The PHP string cast of a proven operand of `.` (issue #59), or `None` when the
/// cast is not one this crate may derive.
///
/// # Why this is derived here and not sent to the sidecar
///
/// The fold seam's standing rule is that PHP semantics are answered by running the
/// project's own PHP (ADR-0004/0028), never re-derived in Rust. Concatenation earns
/// an exception on a narrow, checkable ground: for the operand types admitted below
/// the cast is *total and environment-independent*. Byte concatenation of two
/// strings consults no locale, no encoding, and no ini setting; `int` has one
/// decimal spelling; `bool` and `null` have fixed one-character-or-empty spellings.
/// There is no configuration under which php-src answers differently, so there is
/// nothing for the sidecar to arbitrate.
///
/// That is also why `float` is **excluded**. PHP's float-to-string conversion is
/// governed by the `precision` ini directive (default 14), so `0.1 + 0.2` prints as
/// `0.3` on a stock build and as `0.30000000000000004` under `precision=17`. A value
/// that depends on the runtime's configuration is exactly what this crate must not
/// invent: `strval(1.5)` stays on the `foldable` allowlist and is answered by the
/// real engine, which knows the real setting. `Float` here therefore widens.
///
/// Arrays (`"Array"` plus a warning), objects (`__toString` or an `Error`) and every
/// unresolved carrier widen for the ordinary reason — the result is not proven.
fn concat_cast(v: &ArgValue) -> Option<String> {
    match v {
        ArgValue::Str(s) => Some(s.clone()),
        ArgValue::Int(i) => Some(i.to_string()),
        // `true` is "1", `false` is "" — verified against php-src, not assumed.
        ArgValue::Bool(b) => Some(if *b { "1".to_owned() } else { String::new() }),
        ArgValue::Null => Some(String::new()),
        _ => None,
    }
}

/// Whether `arg` may be sent to the sidecar at all: a scalar literal, or an array
/// literal that is concrete all the way down *and* inside the budget.
fn is_fold_arg(arg: &ArgValue) -> bool {
    let mut budget = FOLD_ARRAY_MAX_ENTRIES;
    fits_fold_budget(arg, FOLD_ARRAY_MAX_DEPTH, &mut budget)
}

/// Convert a literal or literal-array [`ArgValue`] to a [`FoldArg`]; anything else
/// (and anything over the budget) yields `None`, which widens.
fn arg_to_fold(arg: &ArgValue) -> Option<FoldArg> {
    let mut budget = FOLD_ARRAY_MAX_ENTRIES;
    arg_to_fold_within(arg, FOLD_ARRAY_MAX_DEPTH, &mut budget)
}

/// The budget-carrying body of [`arg_to_fold`]. Array entries keep their **source
/// order and their raw keys**: an absent key stays absent on the wire, so PHP's own
/// next-int rule assigns it, and a duplicate key is resolved by PHP's own
/// last-wins. Nothing here re-derives array semantics — that is precisely what
/// running the fold on the project's PHP is for (ADR-0004/0028).
fn arg_to_fold_within(arg: &ArgValue, depth: u8, budget: &mut usize) -> Option<FoldArg> {
    match arg {
        ArgValue::Int(v) => Some(FoldArg::Int(*v)),
        ArgValue::Float(v) => Some(FoldArg::Float(*v)),
        ArgValue::Str(v) => Some(FoldArg::Str(v.clone())),
        ArgValue::Bool(v) => Some(FoldArg::Bool(*v)),
        ArgValue::Null => Some(FoldArg::Null),
        // An array literal (issue #39): representable when every element is, and
        // nested literals recurse. One unrepresentable element widens the WHOLE
        // array — `count([1, $x])` is not 2, because `$x` may not be one entry.
        ArgValue::Array(items) => {
            if depth == 0 {
                return None;
            }
            let mut entries = Vec::with_capacity(items.len());
            for (k, v) in items {
                if *budget == 0 {
                    return None;
                }
                *budget -= 1;
                let key = match k {
                    ArrayKey::Auto => None,
                    ArrayKey::Int(i) => Some(FoldKey::Int(*i)),
                    ArrayKey::Str(s) => Some(FoldKey::Str(s.clone())),
                };
                entries.push((key, arg_to_fold_within(v, depth - 1, budget)?));
            }
            Some(FoldArg::Array(entries))
        }
        ArgValue::Var(_)
        | ArgValue::Call(..)
        | ArgValue::New(..)
        | ArgValue::Ternary { .. }
        | ArgValue::Closure(_)
        | ArgValue::PropFetch { .. }
        | ArgValue::Clone(_)
        | ArgValue::Coalesce(..)
        | ArgValue::OffsetRead { .. }
        // A concatenation is not a wire value: `try_fold` resolves each argument
        // through `resolve_literal` first, so a provable `"a" . $b` arrives here
        // already collapsed to its `Str`. One that did not resolve is unproven, and
        // sending its operands would be sending a different call than was written.
        | ArgValue::Concat(..)
        // Object-world values (ADR-0043) are not fold arguments — unproven, == Other.
        | ArgValue::ClassConst(..)
        | ArgValue::EnumCase(..)
        | ArgValue::Other => None,
    }
}

/// Convert a folded value back to a literal [`ArgValue`].
fn fold_value_to_arg(value: &FoldValue) -> Option<ArgValue> {
    Some(match value {
        FoldValue::Int(v) => ArgValue::Int(*v),
        FoldValue::Float(v) => ArgValue::Float(*v),
        FoldValue::Str(v) => ArgValue::Str(v.clone()),
        FoldValue::Bool(v) => ArgValue::Bool(*v),
        FoldValue::Null => ArgValue::Null,
    })
}

/// Whether a diagnostic path lies inside a `vendor/` directory (ADR-0015).
///
/// **The floor, not the rule.** This is the directory-name guess: a path with a
/// `vendor` component — a top-level `vendor/…` or any nested `…/vendor/…` — is
/// vendor. It is right for the common Composer install and wrong for a tree that
/// vendors elsewhere, so the answer a run actually uses comes from
/// [`ProjectLayout::is_vendor`], which reads the project's own `composer.json`
/// and falls back to this. Kept public for callers that have no project in hand.
///
/// Vendor code is fully indexed and inferred (shapes/values/effects flow through
/// it) either way; only its diagnostics are off by default.
pub fn is_vendor_path(path: &str) -> bool {
    steins_db::fallback_is_vendor(path)
}

/// A proof-layer finding. Kept deliberately flat so the CLI can render text or
/// JSON without knowing anything about the analysis.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct Diagnostic {
    pub id: &'static str,
    pub path: String,
    pub line: u32,
    pub column: u32,
    pub message: String,
    /// The registry-declared facet this finding carries (ADR-0050 §4), or `None`
    /// for ids that declare no facet. v1: `Some(Facet::Origin(_))` on
    /// `throw.undeclared` only, computed at emit time from walk-local data (the
    /// measurement note's same-file-plus-own-origin rule). Additive — the
    /// `--format json` output shows it as an extra key only when present, and the
    /// value never participates in a check's inference behavior. It *does* take
    /// part in equality/hash, but harmlessly: two findings that were previously
    /// equal share an origin file+offset and so compute the same facet.
    pub facet: Option<Facet>,
    /// The fix-it this finding carries as a first-class payload (ADR-0010), or
    /// `None` for the many findings whose remedy is a judgment call. v1: only
    /// the explicit dump pair (`debug.type` / `debug.phpdoc-type`) ships one —
    /// delete the whole dump expression-statement, the remedy ADR-0053 itself
    /// names. Additive like `facet`: the `--format json` output shows it as an
    /// extra key only when present, `check --fix` applies it, and the value
    /// never participates in a check's inference behavior. Equality/hash
    /// participation is likewise harmless — equal findings compute equal fixes.
    pub fix: Option<Fix>,
}

/// The mechanical remedy a diagnostic carries (ADR-0010): byte-span edits
/// that, applied together, resolve the finding. The edit shape mirrors
/// steins-edit's `Edit` (path + `[start, end)` byte span + replacement), so
/// the CLI can pour a run's fixes into one atomic `EditPlan` — and a JSON
/// consumer can apply them with the same splice — without translation.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct Fix {
    /// A short human label of the remedy ("remove the dump statement").
    pub title: &'static str,
    /// The non-overlapping edits, in file order.
    pub edits: Vec<FixEdit>,
}

/// One byte-span replacement of a [`Fix`]: splice `replacement` over the
/// `[start, end)` byte range of `path`'s current contents. Deletion is an
/// empty replacement; insertion is a zero-width span.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct FixEdit {
    pub path: String,
    pub start: u32,
    pub end: u32,
    pub replacement: String,
}

// ---------------------------------------------------------------------------
// The project view: the files analyzed together and their symbol index.
// ---------------------------------------------------------------------------

/// One file in the analyzed project: its diagnostic path and its lowered tree.
/// The tree owns everything else the analysis needs (functions, classes,
/// scopes, positions, namespace contexts).
#[derive(Clone, Copy)]
pub struct FileUnit<'a> {
    pub path: &'a str,
    pub tree: &'a SourceTree,
}

/// A declaration's position within the project view: the file's index in the
/// [`FileUnit`] slice, and the declaration's index in that file's list.
#[derive(Clone, Copy, PartialEq, Eq)]
struct Site {
    file: usize,
    index: usize,
}

/// The outcome of resolving an FQN against the in-memory project index.
#[derive(Clone, Copy)]
enum Res {
    Absent,
    Unique(Site),
    Ambiguous,
}

/// The project symbol index in the analysis's own `Site` terms (a file *index*,
/// not a salsa handle). Built either directly from the [`FileUnit`] slice
/// (single-file / test paths) or adapted from the salsa [`ProjectIndex`]
/// (the db-backed [`check_project`] path — so the tracked query is the authority
/// on incrementality, ADR-0009).
#[derive(Default)]
struct Index {
    functions: HashMap<String, Site>,
    ambiguous_functions: HashSet<String>,
    classes: HashMap<String, Site>,
    ambiguous_classes: HashSet<String>,
    fn_by_simple: HashMap<String, Vec<Site>>,
}

impl Index {
    /// Build the index straight from the file units (mirrors the db query).
    fn from_units(units: &[FileUnit]) -> Self {
        let mut idx = Index::default();
        for (fi, u) in units.iter().enumerate() {
            for (i, f) in u.tree.functions().iter().enumerate() {
                let site = Site { file: fi, index: i };
                idx.fn_by_simple.entry(f.name.to_ascii_lowercase()).or_default().push(site);
                insert_unique(&mut idx.functions, &mut idx.ambiguous_functions, &f.fqn, site);
            }
            for (i, c) in u.tree.classes().iter().enumerate() {
                let site = Site { file: fi, index: i };
                insert_unique(&mut idx.classes, &mut idx.ambiguous_classes, &c.fqn, site);
            }
        }
        // Literal `class_alias` edges (ADR-0049 §2 / A2iii) fold in after every
        // textual decl, mirroring the db-backed `project_index`. Targets resolve
        // against the textual snapshot (order-independent, ADR-0048); collisions
        // (alias vs textual, or two aliases for one name) demote to `Ambiguous`.
        let mut resolved: Vec<(String, Site)> = Vec::new();
        for u in units {
            for edge in u.tree.class_alias_edges() {
                if idx.ambiguous_classes.contains(&edge.target_fqn) {
                    continue;
                }
                if let Some(&target) = idx.classes.get(&edge.target_fqn) {
                    resolved.push((edge.alias_fqn.clone(), target));
                }
            }
        }
        for (alias_fqn, target) in resolved {
            insert_unique(&mut idx.classes, &mut idx.ambiguous_classes, &alias_fqn, target);
        }
        idx
    }

    /// Adapt the salsa [`ProjectIndex`] to `Site`s, using `pos` to map each
    /// [`SourceFile`] to its position in the (identically ordered) unit slice.
    fn from_db(db_index: &ProjectIndex, pos: &HashMap<SourceFile, usize>) -> Self {
        let site = |ds: &DeclSite| Site { file: pos[&ds.file], index: ds.index };
        let mut idx = Index::default();
        for (fqn, ds) in db_index.functions() {
            idx.functions.insert(fqn.clone(), site(ds));
        }
        for (fqn, ds) in db_index.classes() {
            idx.classes.insert(fqn.clone(), site(ds));
        }
        idx.ambiguous_functions = db_index.ambiguous_functions().clone();
        idx.ambiguous_classes = db_index.ambiguous_classes().clone();
        for (simple, sites) in db_index.fn_by_simple() {
            idx.fn_by_simple.insert(simple.clone(), sites.iter().map(site).collect());
        }
        idx
    }

    fn resolve_function(&self, fqn: &str) -> Res {
        let key = fqn.to_ascii_lowercase();
        if self.ambiguous_functions.contains(&key) {
            Res::Ambiguous
        } else {
            self.functions.get(&key).copied().map_or(Res::Absent, Res::Unique)
        }
    }

    fn resolve_class(&self, fqn: &str) -> Res {
        let key = fqn.to_ascii_lowercase();
        if self.ambiguous_classes.contains(&key) {
            Res::Ambiguous
        } else {
            self.classes.get(&key).copied().map_or(Res::Absent, Res::Unique)
        }
    }

    fn unique_fn_by_simple(&self, simple: &str) -> Option<Site> {
        match self.fn_by_simple.get(&simple.to_ascii_lowercase()) {
            Some(sites) if sites.len() == 1 => Some(sites[0]),
            _ => None,
        }
    }

    fn has_simple_function(&self, simple: &str) -> bool {
        self.fn_by_simple.contains_key(&simple.to_ascii_lowercase())
    }
}

/// Whether a function-call reference resolves to a **user** function defined in
/// the project (as opposed to a builtin, or an unresolved/ambiguous name),
/// applying PHP name resolution against the salsa [`ProjectIndex`]. Public so
/// tooling (`xtask freq`) can exclude userland cross-file calls from the
/// builtin-frequency ranking. A name is "userland" here if the project uniquely
/// defines it at any candidate FQN the reference could denote — the
/// builtin-shadow nuance the checker applies is irrelevant to this question.
#[must_use]
pub fn resolves_to_user_function(index: &ProjectIndex, tree: &SourceTree, r: &NameRef) -> bool {
    let unique = |fqn: &str| matches!(index.resolve_function(fqn), Resolve::Unique(_));
    match r.kind {
        RefKind::FullyQualified => unique(&r.raw.to_ascii_lowercase()),
        RefKind::Qualified => {
            let ctx = tree.ctx_at(r.offset);
            let first_len = r.raw.find('\\').unwrap_or(r.raw.len());
            let first = &r.raw[..first_len];
            let fqn = if let Some(t) = ctx.class_imports.get(&first.to_ascii_lowercase()) {
                format!("{t}{}", &r.raw[first_len..])
            } else if ctx.namespace.is_empty() {
                r.raw.clone()
            } else {
                format!("{}\\{}", ctx.namespace, r.raw)
            };
            unique(&fqn)
        }
        RefKind::Unqualified => {
            let ctx = tree.ctx_at(r.offset);
            let name = r.raw.to_ascii_lowercase();
            if let Some(t) = ctx.fn_imports.get(&name) {
                return unique(&t.to_ascii_lowercase());
            }
            if !ctx.namespace.is_empty() && unique(&format!("{}\\{}", ctx.namespace, name)) {
                return true;
            }
            unique(&name)
        }
        // ADR-0049 A8: `namespace\name` — the enclosing-namespace candidate only.
        RefKind::Relative => {
            let ctx = tree.ctx_at(r.offset);
            let fqn = if ctx.namespace.is_empty() {
                r.raw.clone()
            } else {
                format!("{}\\{}", ctx.namespace, r.raw)
            };
            unique(&fqn.to_ascii_lowercase())
        }
    }
}

/// Insert `fqn → site`, demoting to ambiguity on any collision.
fn insert_unique(
    map: &mut HashMap<String, Site>,
    ambiguous: &mut HashSet<String>,
    fqn: &str,
    site: Site,
) {
    if ambiguous.contains(fqn) {
        return;
    }
    if map.remove(fqn).is_some() {
        ambiguous.insert(fqn.to_owned());
    } else {
        map.insert(fqn.to_owned(), site);
    }
}

/// How an unqualified/qualified/FQ **function** call resolves (ADR-0001).
enum FnResolution {
    /// A user function defined in the project (its declaration site).
    User(Site),
    /// A catalogued builtin — no user body, but folding/effect labels apply.
    Builtin,
    /// Ambiguous or unresolved — skip everything (no check, no fold, no effect
    /// classification). The silent side.
    Unknown,
}

// ---------------------------------------------------------------------------
// Public entry points.
// ---------------------------------------------------------------------------

/// The proof-layer diagnostics for one file, as a memoized salsa query (sound
/// subset — [`NoFold`], no PHP). Analyzes the file as a one-file project.
#[salsa::tracked]
pub fn diagnostics(db: &dyn Db, file: SourceFile) -> Vec<Diagnostic> {
    let tree = parse(db, file);
    let units = [FileUnit { path: file.path(db), tree }];
    let index = Index::from_units(&units);
    check_units(&units, &index, &mut NoFold, true, &ProjectLayout::fallback(), &PluginFacts::none())
}

/// The folding-aware check for one file (run **outside** salsa; ADR-0004),
/// analyzed as a one-file project.
#[must_use]
pub fn check_file(db: &dyn Db, file: SourceFile, folder: &mut dyn Folder) -> Vec<Diagnostic> {
    let tree = parse(db, file);
    let units = [FileUnit { path: file.path(db), tree }];
    let index = Index::from_units(&units);
    check_units(&units, &index, folder, true, &ProjectLayout::fallback(), &PluginFacts::none())
}

/// The folding-aware check for a whole **project** (ADR-0009/0015): every file
/// in `project` is analyzed as one unit, so cross-file calls, class chains, and
/// effects resolve. Resolution is driven by the salsa [`project_index`] query.
#[must_use]
pub fn check_project(db: &dyn Db, project: Project, folder: &mut dyn Folder) -> Vec<Diagnostic> {
    check_project_with_runtime(db, project, folder, true)
}

/// [`check_project`] with the `[runtime]` pseudo-constants declared (ADR-0049 §7):
/// `warning_handler_abort` (the `warning-handler` posture) is `true` for the default
/// `"abort"` — proven warning-grade offset findings emit — and `false` for `"null"`,
/// which silences them. The default entry point ([`check_project`]) passes `true`:
/// the safe production default. (The former `zend_assertions` knob was abolished by
/// the 2026-07-25 owner ruling — `assert($expr)` is `Verified` unconditionally.)
#[must_use]
pub fn check_project_with_runtime(
    db: &dyn Db,
    project: Project,
    folder: &mut dyn Folder,
    warning_handler_abort: bool,
) -> Vec<Diagnostic> {
    let handles: Vec<SourceFile> = project.files(db).to_vec();
    let units: Vec<FileUnit> =
        handles.iter().map(|&f| FileUnit { path: f.path(db), tree: parse(db, f) }).collect();
    let db_index = project_index(db, project);
    let pos: HashMap<SourceFile, usize> =
        handles.iter().enumerate().map(|(i, &f)| (f, i)).collect();
    let index = Index::from_db(db_index, &pos);
    check_units(
        &units,
        &index,
        folder,
        warning_handler_abort,
        project.layout(db),
        project.plugins(db),
    )
}

// ---------------------------------------------------------------------------
// The assertType harness seam (oracle idea B): consume
// `PHPStan\Testing\assertType('T', $e)` and measure Steins' rendering of `$e`
// against PHPStan's asserted string. This is **harness-only** — recognition is
// gated on a thread-local sink installed exclusively by [`collect_assert_types`],
// so a normal check never sees `assertType` as anything but an ordinary call (the
// check surface is byte-identical). It reuses the D3 dump path verbatim
// (`best_dump_type` → `render_dump_fact`/speller) so the rendered fact matches
// what `PHPStan\dumpType` would emit for the same expression.
// ---------------------------------------------------------------------------

/// One `PHPStan\Testing\assertType('Expected', $expr)` observation (oracle idea B).
/// The expected type string PHPStan asserts, paired with Steins' own rendering of
/// the second argument at that call position (the same best-fact + speller path the
/// D3 dump surface uses). Collected ONLY by [`collect_assert_types`].
#[derive(Debug, Clone)]
pub struct AssertObservation {
    /// The project-relative path of the file the assertion lives in.
    pub path: String,
    /// The 1-based line of the `assertType(...)` call.
    pub line: u32,
    /// The 1-based column of the call.
    pub column: u32,
    /// The first-argument type-string literal PHPStan asserts, when it is a
    /// resolvable string literal. `None` when the expected slot is a
    /// `::class`/concatenation expression Steins cannot fold to a plain string —
    /// the harness counts those as *skipped*, never a spurious match.
    pub expected: Option<String>,
    /// Steins' rendering of the second argument's best fact (the dump-surface
    /// speller), or the honest `unknown` when nothing faithful can be spelled.
    pub got: String,
    /// Whether `got` rode an `Asserted`-stratum premise (a docblock/assert claim
    /// rather than a proven value) — surfaced so the harness never mistakes a
    /// laundered docblock type for a proof.
    pub asserted: bool,
}

thread_local! {
    /// The harness-only assertType sink (oracle idea B). `None` during every normal
    /// check — the [`emit_asserts`] recognizer is a no-op then and the ADR-0070
    /// survival gate's assertType read exception ([`is_assert_read_site`]) is off,
    /// so the check surface is byte-identical (assertType stays an ordinary call).
    /// [`collect_assert_types`] installs a fresh buffer for one project run and
    /// drains it; both consumers key on the same installed-sink condition, so the
    /// harness universe is entered and left as one piece.
    static ASSERT_SINK: std::cell::RefCell<Option<Vec<AssertObservation>>> =
        const { std::cell::RefCell::new(None) };
}

/// Harness entry point (oracle idea B, the nsrt assertType measurement): analyze
/// `project` exactly as [`check_project`] would, but collect every
/// `PHPStan\Testing\assertType('T', $e)` call's (expected string, Steins rendering)
/// pair. NOT part of the check surface — recognition is gated on the installed sink,
/// so a normal check never sees `assertType` as anything but an ordinary call. Inside
/// THIS run the sink also makes every `assertType` site a transparent read (the
/// ADR-0070 gate's assertType exception), so repeated assertions on one variable
/// each observe the undegraded env; the diagnostics `check_project` returns under
/// that universe are discarded here, never reported.
#[must_use]
pub fn collect_assert_types(
    db: &dyn Db,
    project: Project,
    folder: &mut dyn Folder,
) -> Vec<AssertObservation> {
    ASSERT_SINK.with(|s| *s.borrow_mut() = Some(Vec::new()));
    let _ = check_project(db, project, folder);
    ASSERT_SINK.with(|s| s.borrow_mut().take().unwrap_or_default())
}

/// What the propagation walk knows about one variable at one program point
/// (ADR-0076 §3, the loop-subject probe). Every field is `false` when the walk
/// bound nothing there — a missing answer is "not proven", never a guess.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct SubjectFact {
    /// `true` when the bound fact is an array value (an abstract shape or a
    /// fully-known array literal) that does **not** also admit `null`.
    pub array: bool,
    /// `true` when that array's denotational `array_is_list` verdict is `Yes`
    /// (ADR-0062 §3). `array_map` over a single array preserves keys, while
    /// `$out[] = …` renumbers `0..n-1`, so anything weaker is not equivalent.
    pub list: bool,
    /// `true` when the fact sits at the `Verified` stratum (ADR-0052 §5) — a
    /// runtime-executed test or a native declaration, fit to premise a proof. A
    /// docblock-asserted array shape answers `false` here and never qualifies.
    pub verified: bool,
}

thread_local! {
    /// The ADR-0076 loop-subject probe. `None` during every normal check, so the
    /// walk's per-statement hook is a single `is_some()` test and the check
    /// surface is byte-identical; [`probe_subjects`] installs a request table for
    /// one project run and drains the answers.
    static SUBJECT_PROBE: std::cell::RefCell<Option<SubjectProbeState>> =
        const { std::cell::RefCell::new(None) };
}

/// The installed probe's request table plus the answers collected so far.
#[derive(Default)]
struct SubjectProbeState {
    /// `(path, statement start offset)` → the variable name to observe there.
    wanted: HashMap<(String, u32), String>,
    /// `(path, statement start offset)` → what the walk knew on entry.
    answers: HashMap<(String, u32), SubjectFact>,
}

/// Ask the propagation walk what it knows about a variable at a program point
/// (ADR-0076 §3): each site is `(path, statement start offset, variable name)`,
/// and the answer is keyed by `(path, offset)`.
///
/// The walk observes **entry** facts — what holds *before* the statement runs —
/// which is the state a `foreach` head reads its subject in. A site with no
/// answer (unreachable, poisoned scope, or simply unbound) is absent from the
/// map, which callers read as [`SubjectFact::default`]: nothing proven.
///
/// Analysis runs in the sound subset ([`NoFold`]), matching the rest of the
/// transform engine: a planned rewrite must not depend on whether a PHP sidecar
/// happened to be reachable.
#[must_use]
pub fn probe_subjects(
    db: &dyn Db,
    project: Project,
    sites: &[(String, u32, String)],
) -> HashMap<(String, u32), SubjectFact> {
    if sites.is_empty() {
        return HashMap::new();
    }
    let wanted: HashMap<(String, u32), String> =
        sites.iter().map(|(p, off, var)| ((p.clone(), *off), var.clone())).collect();
    SUBJECT_PROBE.with(|s| {
        *s.borrow_mut() = Some(SubjectProbeState { wanted, answers: HashMap::new() });
    });
    let _ = check_project(db, project, &mut NoFold);
    SUBJECT_PROBE.with(|s| s.borrow_mut().take().map(|st| st.answers).unwrap_or_default())
}

/// Answer any installed [`SUBJECT_PROBE`] request keyed at this statement, from
/// the walk's **entry** env. A no-op with no probe installed (every normal
/// check), and never run under a binding descent — the plain per-scope pass is
/// the one universal reading, exactly as the dump and trace observers are gated.
fn record_subject_probe(cx: &Cx<'_>, stmt: &Stmt, env: &HashMap<String, Known>) {
    SUBJECT_PROBE.with(|slot| {
        let mut slot = slot.borrow_mut();
        let Some(state) = slot.as_mut() else { return };
        let key = (cx.path().to_owned(), stmt.span.start);
        let Some(var) = state.wanted.get(&key) else { return };
        let fact = env.get(var).map_or_else(SubjectFact::default, |known| {
            let (array, list) = match &known.fact {
                Some(Fact::Shape { shape, nullable: false }) => {
                    (true, shape.is_list == Certainty::Yes)
                }
                Some(Fact::Singleton(Val::Array(entries))) => {
                    (true, steins_domain::array_is_list(entries))
                }
                _ => (false, false),
            };
            SubjectFact { array, list, verified: known.stratum == Stratum::Verified }
        });
        state.answers.insert(key, fact);
    });
}

/// The pure single-file check (sound subset). Kept for unit tests and callers
/// that never execute PHP. `functions` is accepted for signature stability; the
/// tree's own function list is authoritative.
#[must_use]
pub fn check(tree: &SourceTree, functions: &[FunctionDecl], path: &str) -> Vec<Diagnostic> {
    check_with(tree, functions, path, &mut NoFold)
}

/// The folding-aware single-file check core, analyzed as a one-file project.
#[must_use]
pub fn check_with(
    tree: &SourceTree,
    functions: &[FunctionDecl],
    path: &str,
    folder: &mut dyn Folder,
) -> Vec<Diagnostic> {
    let _ = functions; // authoritative list comes from `tree.functions()`
    let units = [FileUnit { path, tree }];
    let index = Index::from_units(&units);
    check_units(&units, &index, folder, true, &ProjectLayout::fallback(), &PluginFacts::none())
}

/// The single-file check with a folder **and** the `warning-handler` posture
/// (`warning_handler_abort`, ADR-0049 §7). Kept for tests that must exercise both a
/// live folder (the offset family is gated on [`Folder::absence_family_available`],
/// ADR-0049 A9) and a chosen `warning-handler` posture. (The former `zend_assertions`
/// knob was abolished by the 2026-07-25 owner ruling — `assert($expr)` is `Verified`
/// unconditionally, so no runtime knob controls its stratum.)
#[must_use]
pub fn check_full(
    tree: &SourceTree,
    path: &str,
    folder: &mut dyn Folder,
    warning_handler_abort: bool,
) -> Vec<Diagnostic> {
    let units = [FileUnit { path, tree }];
    let index = Index::from_units(&units);
    check_units(
        &units,
        &index,
        folder,
        warning_handler_abort,
        &ProjectLayout::fallback(),
        &PluginFacts::none(),
    )
}

/// The project checking core: direct + propagation passes over every file's
/// calls and scopes, then the one project-wide effects pass.
fn check_units(
    units: &[FileUnit],
    index: &Index,
    folder: &mut dyn Folder,
    warning_handler_abort: bool,
    layout: &ProjectLayout,
    plugins: &PluginFacts,
) -> Vec<Diagnostic> {
    let mut out = Vec::new();

    // The whole-universe dam fact (ADR-0049 §2): one query answer per run, shared by
    // every file's context. Consumed by the absence family's conditional-decl leg.
    let dam = dam_facts(units, layout);

    // The analysis PHP view (issue #28): the TARGET the project declares
    // (`config.platform.php` / `require.php`, via the layout) is what
    // version-sensitive decisions key on; the sidecar's runtime minor is the
    // fallback when the project declares nothing. One computation per run,
    // shared by every file's context — ADR-0052 A11 (catalog skew) and
    // ADR-0049 A12 (the next-int rule, through `normalize_array`) both follow
    // this one seam.
    let runtime_minor = folder.php_minor();
    let view = effective_php_view(runtime_minor, layout.php_target());
    let (php_minor, catalog_skew) = (view.effective_minor, view.catalog_skew);
    // The PHP_VERSION_ID guard fold (issue #29) is disabled project-wide the
    // moment any file declares a userland constant of that name — constant
    // resolution is otherwise unmodeled, so the conservative reading is the
    // only sound one.
    let version_id = if units.iter().any(|u| u.tree.php_version_id_declared()) {
        None
    } else {
        view.version_id
    };

    // The callable-purity oracle (ADR-0063 P3): one whole-project effect fixpoint per
    // run, shared by every file's context, and built only when some docblock actually
    // spells a purity-bearing callable.
    let purity = PurityOracle::build(units, index, plugins);

    for fi in 0..units.len() {
        let cx = Cx::new_with(
            units,
            index,
            fi,
            &dam,
            warning_handler_abort,
            php_minor,
            catalog_skew,
            version_id,
            purity.as_ref(),
            layout.php_target(),
        );

        // --- Propagation pass FIRST: it walks every scope and, as a side
        // product, proves dead regions (decided branches, unreachable tails) —
        // the env-free direct pass below must not report inside them
        // (live-path discipline, ADR-0002/0031). Binding descents contribute
        // nothing here: their deadness is per-binding, not universal. ---------
        let mut dead_spans: Vec<Span> = Vec::new();
        for scope in cx.tree().scopes() {
            analyze_scope(
                &cx,
                folder,
                scope,
                HashMap::new(),
                Store::default(),
                None,
                None,
                None,
                Some(&mut dead_spans),
                None,
                &mut out,
            );
        }

        // --- The `class.undefined` pass (ADR-0049 §5 / S4): the file's hard-error
        // class references, judged once each. A reference in a proven-dead region is
        // skipped — which IS this id's guard leg (a `class_exists('X')` whose class
        // meets the firing conditions folds its branch dead under the same closure).
        for r in cx.tree().hard_class_refs() {
            if in_dead(&dead_spans, r.offset) {
                continue;
            }
            check_undefined_class(&cx, folder, r, &mut out);
        }

        // --- Direct pass: literal / array / `new` arguments at every function
        // call site (env-free; propagation adds `$var`/folded resolution). Native
        // scalar checks and the phpdoc declared-contract check both run here; a
        // site where the native check fired is skipped by the phpdoc check (no
        // double-report; ADR-0030). Calls in proven-dead regions are skipped. ---
        let empty_env: HashMap<String, Known> = HashMap::new();
        let empty_classes: Store = Store::default();
        for call in cx.tree().calls() {
            if in_dead(&dead_spans, call.span.start) {
                continue;
            }
            // Resolve the positional prefix of a mixed call too (Gap A) — the guard
            // that keeps the binding descent positional-only lives on the descent path.
            let Some(site) = cx.resolve_user_fn_any(call) else { continue };
            let decl = cx.fn_decl(site);
            let envelopes = parse_envelopes(decl.docblock.as_deref());
            for (i, arg) in call.args.iter().enumerate() {
                let Some(param) = decl.params.get(i) else { break };
                if param.variadic {
                    break;
                }
                if param.by_ref {
                    continue;
                }
                let mut native_fired = false;
                // Env-free resolution: a literal, a proven object (`new` / enum
                // case), or a resolved class constant (ADR-0043 stage 3). At file
                // scope there is no enclosing class for `self`/`parent`.
                if let Some(ty) = param.ty.as_ref()
                    && let Some(checkable) = cx.resolve_static_value(&arg.value, None)
                    && is_type_error(&cx, ty, &checkable)
                {
                    out.push(cx.diagnostic(
                        arg.span.start,
                        &checkable,
                        None,
                        &decl.name,
                        &param.name,
                        ty,
                    ));
                    native_fired = true;
                }
                // The direct pass owns env-free arg kinds (literal / array / `new`,
                // plus enum-case / class-const object values — ADR-0043 stage 4);
                // `$var`/`call()` resolution — and their phpdoc check — belong to the
                // propagation pass, so the two never both fire on one arg.
                let env_free = arg.value.is_literal()
                    || matches!(
                        arg.value,
                        ArgValue::Array(_) | ArgValue::New(..) | ArgValue::EnumCase(..) | ArgValue::ClassConst(..)
                    );
                if !native_fired
                    && env_free
                    && let Some(env) = &envelopes
                {
                    check_phpdoc_param(
                        &cx,
                        folder,
                        env,
                        param,
                        site.file,
                        decl.span.start,
                        &decl.name,
                        arg.span.start,
                        &arg.value,
                        &empty_env,
                        &empty_classes,
                        false,
                        false, // in_descent — the direct pass is never a descent
                        &mut out,
                    );
                }
                // Callable-signature variance (issue #11): a closure / first-class
                // callable argument against a signature-bearing `callable(...)`
                // @param. Env-free (a closure's declared signature is a static CST
                // fact), so the direct pass owns it — no overlap with the
                // propagation pass, which owns `$var`/`call()` arg kinds.
                if let ArgValue::Closure(closure) = &arg.value
                    && let Some(env) = &envelopes
                {
                    check_callable_arg(&cx, env, param, &decl.name, arg.span.start, closure, &mut out);
                }
            }
        }

    }

    // --- Effects pass (ADR-0005), computed once over the whole project. ------
    out.extend(effect_diagnostics(units, index, plugins));

    // --- Throw system (ADR-0040/0007): `@throws` envelope + Liskov. ----------
    out.extend(throw_diagnostics(units, index));

    dedup(&mut out);
    out
}

/// Drop exact-duplicate diagnostics, preserving first-occurrence order.
fn dedup(out: &mut Vec<Diagnostic>) {
    let mut seen: HashSet<Diagnostic> = HashSet::new();
    out.retain(|d| seen.insert(d.clone()));
}

// ---------------------------------------------------------------------------
// `annotate` facts (ADR-0020): the Rigor-style margin — proven facts only.
// ---------------------------------------------------------------------------

/// One proven fact the `annotate` margin can print against a source line.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FactKind {
    /// The inferred effect set: `labels` is the proven lane, `declared` the
    /// ADR-0067 declared one (rendered `≤label`, normalized against `labels`).
    Effects { labels: Vec<String>, declared: Vec<String>, exhaustive: bool },
    /// The inferred throw set (ADR-0040): the classes a function/method can raise
    /// that escape it, with a shared `…?` taint marker when non-exhaustive.
    Throws { classes: Vec<String>, exhaustive: bool },
    Value { var: String, rendered: String },
    ExactClass { var: String, class: String },
    Finding { id: &'static str },
}

/// A [`FactKind`] keyed to a 1-based source line (ADR-0020 margin display).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LineFact {
    pub line: u32,
    pub kind: FactKind,
}

impl LineFact {
    /// The margin body (without the `//=>` prefix or padding).
    #[must_use]
    pub fn body(&self) -> String {
        match &self.kind {
            FactKind::Effects { labels, declared, exhaustive } => {
                let mut parts = labels.clone();
                // A declared bound shares the braces with the proven labels but
                // wears a `≤`: "at most this, because a contract says so" — never
                // "this happens, because we saw it" (ADR-0067).
                parts.extend(declared.iter().map(|l| format!("≤{l}")));
                if !*exhaustive {
                    parts.push("…?".to_owned());
                }
                format!("effects: {{{}}}", parts.join(", "))
            }
            FactKind::Throws { classes, exhaustive } => {
                let mut parts = classes.clone();
                if !*exhaustive {
                    parts.push("…?".to_owned());
                }
                format!("throws: {{{}}}", parts.join(", "))
            }
            FactKind::Value { var, rendered } => format!("${var} = {rendered}"),
            FactKind::ExactClass { var, class } => format!("${var}: {class} (exact)"),
            FactKind::Finding { id } => format!("✗ {id}"),
        }
    }
}

/// Single-file annotate facts (kept for tests / the no-`--project` CLI path).
#[must_use]
pub fn annotate_facts(
    tree: &SourceTree,
    functions: &[FunctionDecl],
    classes: &[ClassDecl],
    path: &str,
    folder: &mut dyn Folder,
) -> Vec<LineFact> {
    let _ = (functions, classes);
    let units = [FileUnit { path, tree }];
    let index = Index::from_units(&units);
    annotate_units(&units, &index, 0, folder, &ProjectLayout::fallback(), &PluginFacts::none())
}

/// Salsa-fed single-file annotate.
#[must_use]
pub fn annotate_file(db: &dyn Db, file: SourceFile, folder: &mut dyn Folder) -> Vec<LineFact> {
    let tree = parse(db, file);
    let units = [FileUnit { path: file.path(db), tree }];
    let index = Index::from_units(&units);
    annotate_units(&units, &index, 0, folder, &ProjectLayout::fallback(), &PluginFacts::none())
}

/// Project-aware annotate (ADR-0020, `--project`): compute the margin facts for
/// `target` while resolving names, classes, and effects against the whole
/// `project`. Returns facts for the target file only.
#[must_use]
pub fn annotate_project(
    db: &dyn Db,
    project: Project,
    target: SourceFile,
    folder: &mut dyn Folder,
) -> Vec<LineFact> {
    let handles: Vec<SourceFile> = project.files(db).to_vec();
    let units: Vec<FileUnit> =
        handles.iter().map(|&f| FileUnit { path: f.path(db), tree: parse(db, f) }).collect();
    let db_index = project_index(db, project);
    let pos: HashMap<SourceFile, usize> =
        handles.iter().enumerate().map(|(i, &f)| (f, i)).collect();
    let index = Index::from_db(db_index, &pos);
    let Some(target_idx) = handles.iter().position(|&f| f == target) else {
        return Vec::new();
    };
    annotate_units(&units, &index, target_idx, folder, project.layout(db), project.plugins(db))
}

/// Salsa-fed single-file effect summaries — the data source behind `annotate
/// --format json` (issue #65). Mirrors [`annotate_file`], but returns the
/// [`EffectSummary`] list itself rather than rendered [`LineFact`]s, so a JSON
/// consumer keeps the proven-labels/exhaustiveness dimensions distinct instead
/// of reading the `…?`-flattened margin string.
#[must_use]
pub fn effect_summaries_file(db: &dyn Db, file: SourceFile) -> Vec<EffectSummary> {
    let tree = parse(db, file);
    let units = [FileUnit { path: file.path(db), tree }];
    let index = Index::from_units(&units);
    effect_summary_units(&units, &index, 0, &PluginFacts::none())
}

/// Project-aware effect summaries (issue #65): the same cross-file resolution
/// [`annotate_project`] uses for the margin, returning [`EffectSummary`] for
/// the target file only.
#[must_use]
pub fn effect_summaries_project(
    db: &dyn Db,
    project: Project,
    target: SourceFile,
) -> Vec<EffectSummary> {
    let handles: Vec<SourceFile> = project.files(db).to_vec();
    let units: Vec<FileUnit> =
        handles.iter().map(|&f| FileUnit { path: f.path(db), tree: parse(db, f) }).collect();
    let db_index = project_index(db, project);
    let pos: HashMap<SourceFile, usize> =
        handles.iter().enumerate().map(|(i, &f)| (f, i)).collect();
    let index = Index::from_db(db_index, &pos);
    let Some(target_idx) = handles.iter().position(|&f| f == target) else {
        return Vec::new();
    };
    effect_summary_units(&units, &index, target_idx, project.plugins(db))
}

/// Compute the annotate facts for `target` file within a project view.
fn annotate_units(
    units: &[FileUnit],
    index: &Index,
    target: usize,
    folder: &mut dyn Folder,
    layout: &ProjectLayout,
    plugins: &PluginFacts,
) -> Vec<LineFact> {
    let mut facts: Vec<LineFact> = Vec::new();

    // 1. Effects (and throws) on each declaration line in the target file.
    for s in effect_summary_units(units, index, target, plugins) {
        let throws_present = !s.throws.is_empty() || !s.throws_exhaustive;
        facts.push(LineFact {
            line: s.line,
            kind: FactKind::Effects {
                labels: s.labels,
                declared: s.declared,
                exhaustive: s.exhaustive,
            },
        });
        // Throws print on the same line, after effects, only when non-empty
        // (or tainted) — one color, one spelling (ADR-0006): throws are their
        // own margin fact, never an effect label.
        if throws_present {
            facts.push(LineFact {
                line: s.line,
                kind: FactKind::Throws { classes: s.throws, exhaustive: s.throws_exhaustive },
            });
        }
    }

    // 2. Value / exact-class facts from the propagation walk of the target file.
    let cx = Cx::new(units, index, target);
    let mut sink: Vec<Diagnostic> = Vec::new();
    for scope in cx.tree().scopes() {
        analyze_scope(
            &cx,
            folder,
            scope,
            HashMap::new(),
            Store::default(),
            None,
            None,
            Some(&mut facts),
            None,
            None,
            &mut sink,
        );
    }

    // 3. Findings on the target file (project-wide check, filtered by path).
    let target_path = units[target].path;
    for d in check_units(units, index, folder, true, layout, plugins) {
        if d.path == target_path {
            facts.push(LineFact { line: d.line, kind: FactKind::Finding { id: d.id } });
        }
    }

    facts.sort_by_key(|f| f.line);
    facts
}

// ---------------------------------------------------------------------------
// Effects pass (ADR-0005): `#[\Steins\Pure]` envelope checking, project-wide.
// ---------------------------------------------------------------------------

/// One proven effect a unit carries, with the provenance a transitive `via`
/// message needs.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct EffectFinding {
    label: String,
    origin: String,
    line: u32,
    /// The path of the file the origin lives in, so a transitive `via` message
    /// can name the other file when the effect arises cross-file.
    path: String,
}

/// A node in the unified project effect call graph — a free function (keyed by
/// FQN) or a class method (keyed by class FQN + method name).
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
enum Sym {
    Func(String),
    Method(String, String),
    /// A closure/arrow body (ADR-0033), keyed by file path + definition-site
    /// offset (closures are same-file, so this key is stable within a project).
    Closure(String, u32),
}

/// One unit's fixpoint result: its proven effect findings, its **declared** lane,
/// and exhaustiveness.
///
/// The two lanes never mix (ADR-0067). `findings` is what inference *proved* —
/// the only lane `effect.envelope-exceeded` and `effect.liskov-widened` read, so
/// a declaration can never manufacture a finding. `declared` is what a
/// declaration *bounds*: the envelope labels imported at a call through an
/// interface-typed receiver, joined along call edges exactly as findings are. Both
/// lanes are stored raw — the display-time normalization that drops a declared
/// label already covered by a proven one lives in [`effect_summary_units`].
#[derive(Debug, Clone, Default)]
struct EffectSet {
    findings: HashSet<EffectFinding>,
    /// Declared-lane labels (ADR-0018 dot-paths), no provenance: they name a
    /// bound, not an origin, so nothing ever reports them at a source position.
    declared: HashSet<String>,
    exhaustive: bool,
}

/// Resolve a [`CallbackRef`] to its effect [`Sym`], for the [`Sym::Closure`] key.
/// A named callback resolving to a builtin/unknown returns `None` (the caller
/// handles those inline).
fn callback_effect_edge(cx: &Cx, cbref: &steins_syntax::CallbackRef) -> Option<Sym> {
    match cbref {
        steins_syntax::CallbackRef::Closure(off) => Some(Sym::Closure(cx.path().to_owned(), *off)),
        steins_syntax::CallbackRef::Named(name) => match cx.resolve_effect_function(name) {
            FnResolution::User(site) => Some(Sym::Func(cx.fn_decl(site).fqn.clone())),
            FnResolution::Builtin | FnResolution::Unknown => None,
        },
    }
}

/// Wire a resolved callback into the effect graph (ADR-0033): a closure or user
/// function becomes an edge; a builtin callback contributes its catalog findings
/// directly; an unknown callback taints exhaustiveness (`…?`).
fn add_callback_effects(
    cx: &Cx,
    cbref: &steins_syntax::CallbackRef,
    span: steins_syntax::Span,
    d: &mut HashSet<EffectFinding>,
    e: &mut HashSet<Sym>,
    ex: &mut bool,
) {
    match cbref {
        steins_syntax::CallbackRef::Closure(off) => {
            e.insert(Sym::Closure(cx.path().to_owned(), *off));
        }
        steins_syntax::CallbackRef::Named(name) => match cx.resolve_effect_function(name) {
            FnResolution::User(site) => {
                e.insert(Sym::Func(cx.fn_decl(site).fqn.clone()));
            }
            FnResolution::Builtin => {
                // A builtin passed *as* a callback is invoked by the higher-order
                // callee with arguments of its choosing, never with an lvalue of
                // this frame — the conditional out-param row cannot apply.
                for f in builtin_findings(name.simple(), span, cx.tree(), cx.path(), None) {
                    d.insert(f);
                }
            }
            FnResolution::Unknown => *ex = false,
        },
    }
}

/// A function's declared **conditional-purity** contracts (ADR-0063 §2 decision 2),
/// resolved from parameter names to positional indices.
#[derive(Debug, Default, Clone)]
struct ConditionalPurity {
    /// Positions flagged by `@pure-unless-callable-is-impure $cb`: this
    /// function's envelope is the join of the callables bound here.
    callables: Vec<usize>,
    /// Positions flagged by `@pure-unless-parameter-passed $out`: this function
    /// is pure unless the argument is supplied. The declarative twin of a catalog
    /// out-param row — a userland row, written by the author instead of curated.
    passed: Vec<usize>,
}

impl ConditionalPurity {
    fn is_empty(&self) -> bool {
        self.callables.is_empty() && self.passed.is_empty()
    }
}

/// Read a declaration's conditional-purity tags, mapping each flagged parameter
/// name to its positional index. `None` when the docblock declares none.
///
/// A tag naming a parameter the signature does not have is dropped, not
/// diagnosed: the crate's tag discipline is that a malformed or stale tag costs
/// its own effect and nothing else.
fn conditional_purity(docblock: Option<&String>, params: &[steins_syntax::Param]) -> Option<ConditionalPurity> {
    let text = docblock?;
    // Cheap gate: both spellings share this substring, and it is vanishingly rare
    // in prose. Scanning every docblock in the project would not be.
    if !text.contains("pure-unless") {
        return None;
    }
    let mut cp = ConditionalPurity::default();
    for tag in scan_docblock(text) {
        let TagKind::ConditionalPurity(cond) = tag.kind else { continue };
        let Some(var) = &tag.var_name else { continue };
        let name = var.trim_start_matches('$');
        let Some(pos) = params.iter().position(|p| p.name == name) else { continue };
        let slot = match cond {
            steins_phpdoc::PurityCondition::CallableIsImpure => &mut cp.callables,
            steins_phpdoc::PurityCondition::ParameterIsPassed => &mut cp.passed,
        };
        if !slot.contains(&pos) {
            slot.push(pos);
        }
    }
    (!cp.is_empty()).then_some(cp)
}

/// How a call to a **user** function contributes to the caller's effect set, once
/// the callee's conditional-purity contracts (ADR-0063 §2 decision 2) are honored.
struct UserCallEffects {
    /// Whether the callee's *exhaustiveness taint* is discharged by its contract.
    ///
    /// A tagged function's body calls its callable parameter dynamically
    /// (`$cb(...)`), which is an [`EffectOrigin::Opaque`] and taints the callee
    /// forever — the very unprovability the contract exists to answer. When every
    /// flagged condition is decided at this call site (the callable is a
    /// resolvable callback, or the flagged argument is simply absent), the
    /// declaration discharges that taint.
    ///
    /// This does not invert ADR-0037's "proven beats declared": every finding the
    /// fixpoint *proved* about the callee still propagates. A declaration is only
    /// permitted to answer what inference left unknown.
    discharge_taint: bool,
    /// Labels the call contributes directly — the `@pure-unless-parameter-passed`
    /// leg, resolved against the argument's lvalue root exactly as a catalog
    /// out-param row would be.
    labels: Vec<&'static str>,
}

/// Evaluate a user callee's conditional-purity contracts against one call site.
///
/// `callbacks` are the resolvable callback arguments by position (empty for a
/// plain [`EffectOrigin::Call`]); `arg_targets` is `None` when positional mapping
/// was defeated, in which case no condition can be evaluated and nothing is
/// discharged.
fn eval_conditional_purity(
    cp: &ConditionalPurity,
    callbacks: &[(usize, steins_syntax::CallbackRef)],
    arg_targets: Option<&[steins_syntax::RefTarget]>,
    mut on_callback: impl FnMut(&steins_syntax::CallbackRef),
) -> UserCallEffects {
    let Some(targets) = arg_targets else {
        return UserCallEffects { discharge_taint: false, labels: Vec::new() };
    };
    let arity = targets.len();
    let mut discharge = true;
    let mut labels: Vec<&'static str> = Vec::new();
    for &p in &cp.callables {
        // Not supplied → the condition is vacuous and the function is pure.
        if p >= arity {
            continue;
        }
        match callbacks.iter().find(|(q, _)| *q == p) {
            // Visible callback: its envelope joins the caller's (ADR-0063
            // decision 1's semantic answer, reached through the declaration).
            Some((_, cbref)) => on_callback(cbref),
            // An opaque `callable` sits in the flagged slot — precisely the case
            // the contract cannot resolve either. The taint stands, as today.
            None => discharge = false,
        }
    }
    for &p in &cp.passed {
        let Some(&target) = targets.get(p) else { continue };
        let label = by_ref_label(target);
        if !labels.contains(&label) {
            labels.push(label);
        }
    }
    UserCallEffects { discharge_taint: discharge, labels }
}

/// The plugin channel's coloring for a statically-named call that resolved to
/// **nothing** — no project body, no catalog row (ADR-0068 §1).
///
/// Precedence is structural rather than compared: this is only ever reached from
/// the `FnResolution::Unknown` arm, so a builtin row and a project function have
/// both already won. The extra guards below are for the two shapes `Unknown` also
/// covers and a plugin must not speak for: an **ambiguous** name (the project does
/// define it, twice) and a **namespaced** name (a plugin manifest colors global
/// functions, which is what `acme_cache_get` is).
///
/// The caller puts the answer in the DECLARED lane and keeps the exhaustiveness
/// taint. That is the opposite of ADR-0067's interface-envelope import, and
/// deliberately so: an envelope is a checked contract (`effect.liskov-widened`
/// holds every analyzed implementation to it), while nothing checks a plugin's
/// assertion. Assert, never prove — so the summary reads "declared `acme.cache`,
/// and possibly more", which is the truth of an unchecked claim.
fn plugin_call_labels<'p>(
    cx: &Cx,
    plugins: &'p PluginFacts,
    name: &NameRef,
) -> Option<&'p [String]> {
    let simple = name.simple();
    if simple != name.raw.trim_start_matches('\\') {
        return None; // a namespaced userland name is not a global function
    }
    if cx.index.has_simple_function(simple) {
        return None; // the project defines it (ambiguously, or we would be elsewhere)
    }
    plugins.effect_labels(simple)
}

/// The unified effect fixpoint for **every** function and method in the whole
/// project, keyed by [`Sym`] (FQN-based, so cross-file edges match).
fn compute_effects(
    units: &[FileUnit],
    index: &Index,
    plugins: &PluginFacts,
) -> HashMap<Sym, EffectSet> {
    // Each effect unit with the file it lives in and its enclosing class FQN.
    struct Unit<'a> {
        sym: Sym,
        file: usize,
        class_fqn: Option<String>,
        origins: &'a [EffectOrigin],
        /// The frame's declared parameters — read only to type an ADR-0067
        /// declared receiver (`EffectRecv::Var`).
        params: &'a [steins_syntax::Param],
    }
    let mut ulist: Vec<Unit> = Vec::new();
    for (fi, u) in units.iter().enumerate() {
        for f in u.tree.functions() {
            ulist.push(Unit {
                sym: Sym::Func(f.fqn.clone()),
                file: fi,
                class_fqn: None,
                origins: &f.effect_origins,
                params: &f.params,
            });
        }
        for c in u.tree.classes() {
            for m in &c.methods {
                ulist.push(Unit {
                    sym: Sym::Method(c.fqn.clone(), m.name.clone()),
                    file: fi,
                    class_fqn: Some(c.fqn.clone()),
                    origins: &m.effect_origins,
                    params: &m.params,
                });
            }
        }
        // Closure/arrow bodies are effect nodes too (ADR-0033) — a HigherOrder /
        // Callback edge into one carries the callback's proven effects.
        for scope in u.tree.scopes() {
            if let ScopeOwner::Closure { def_offset } = &scope.owner {
                ulist.push(Unit {
                    sym: Sym::Closure(u.path.to_owned(), *def_offset),
                    file: fi,
                    class_fqn: None,
                    origins: &scope.effect_origins,
                    params: &scope.params,
                });
            }
        }
    }

    let mut direct: HashMap<Sym, HashSet<EffectFinding>> = HashMap::new();
    // Declared-lane labels imported *locally* — one entry per call site whose
    // receiver's declared interface method carries an envelope (ADR-0067).
    let mut declared_direct: HashMap<Sym, HashSet<String>> = HashMap::new();
    let mut edges: HashMap<Sym, HashSet<Sym>> = HashMap::new();
    // Edges whose findings propagate but whose exhaustiveness taint does not — a
    // callee whose ADR-0063 conditional-purity contract was fully decided here.
    let mut untainting: HashMap<Sym, HashSet<Sym>> = HashMap::new();
    let mut exhaustive: HashMap<Sym, bool> = HashMap::new();
    for unit in &ulist {
        let cx = Cx::new(units, index, unit.file);
        let d = direct.entry(unit.sym.clone()).or_default();
        let dc = declared_direct.entry(unit.sym.clone()).or_default();
        let e = edges.entry(unit.sym.clone()).or_default();
        let nt = untainting.entry(unit.sym.clone()).or_default();
        let ex = exhaustive.entry(unit.sym.clone()).or_insert(true);
        classify_effect_origins(
            &cx,
            unit.class_fqn.as_deref(),
            unit.params,
            unit.origins,
            plugins,
            d,
            dc,
            e,
            nt,
            ex,
        );
    }

    // Fixpoint: effects(u) = direct(u) ∪ ⋃ effects(callees); exhaustive taints.
    // The declared lane rides the same edges, monotone in the same way (ADR-0067):
    // declared(u) = locally-imported bounds(u) ∪ ⋃ declared(callees). A declared
    // label never crosses into `findings`, in either direction.
    let syms: Vec<Sym> = ulist.iter().map(|u| u.sym.clone()).collect();
    let mut findings: HashMap<Sym, HashSet<EffectFinding>> = direct;
    let mut declared: HashMap<Sym, HashSet<String>> = declared_direct;
    loop {
        let mut changed = false;
        for sym in &syms {
            let callees: Vec<Sym> = edges.get(sym).into_iter().flatten().cloned().collect();
            // Contract-discharged callees (ADR-0063 §2 decision 2): their proven
            // findings still join, their unknown remainder does not.
            let untainted: Vec<Sym> = untainting.get(sym).into_iter().flatten().cloned().collect();
            let mut incoming: Vec<EffectFinding> = Vec::new();
            let mut incoming_declared: Vec<String> = Vec::new();
            let mut callee_taint = false;
            for c in callees.iter().chain(untainted.iter()) {
                if let Some(ce) = findings.get(c) {
                    incoming.extend(ce.iter().cloned());
                }
                if let Some(cd) = declared.get(c) {
                    incoming_declared.extend(cd.iter().cloned());
                }
            }
            for c in &callees {
                if exhaustive.get(c).copied() == Some(false) {
                    callee_taint = true;
                }
            }
            let set = findings.entry(sym.clone()).or_default();
            for ef in incoming {
                changed |= set.insert(ef);
            }
            let dset = declared.entry(sym.clone()).or_default();
            for label in incoming_declared {
                changed |= dset.insert(label);
            }
            if callee_taint && exhaustive.get(sym).copied() != Some(false) {
                exhaustive.insert(sym.clone(), false);
                changed = true;
            }
        }
        if !changed {
            break;
        }
    }

    syms.into_iter()
        .map(|s| {
            let f = findings.remove(&s).unwrap_or_default();
            let dc = declared.remove(&s).unwrap_or_default();
            let ex = exhaustive.get(&s).copied().unwrap_or(true);
            (s, EffectSet { findings: f, declared: dc, exhaustive: ex })
        })
        .collect()
}

/// Classify one unit's (or one **region**'s — ADR-0076) effect origins into the
/// fixpoint's four accumulators plus the exhaustiveness bit. Split out of
/// [`compute_effects`] so a *sub-span* of a body can be asked the same question
/// the whole body is asked, through exactly the same code: the loop→`array_map`
/// transform's purity precondition is the fixpoint's own verdict restricted to
/// the loop body, never a second opinion about what an effect is.
#[allow(clippy::too_many_arguments)]
fn classify_effect_origins(
    cx: &Cx,
    class_fqn: Option<&str>,
    params: &[steins_syntax::Param],
    origins: &[EffectOrigin],
    plugins: &PluginFacts,
    d: &mut HashSet<EffectFinding>,
    dc: &mut HashSet<String>,
    e: &mut HashSet<Sym>,
    nt: &mut HashSet<Sym>,
    ex: &mut bool,
) {
    for origin in origins {
        match origin {
            EffectOrigin::Call { name, span, arg_targets } => {
                let targets = arg_targets.as_deref();
                match cx.resolve_effect_function(name) {
                    FnResolution::User(site) => {
                        let decl = cx.fn_decl(site);
                        let sym = Sym::Func(decl.fqn.clone());
                        match conditional_purity(decl.docblock.as_ref(), &decl.params) {
                            Some(cp) => {
                                let r = eval_conditional_purity(&cp, &[], targets, |cbref| {
                                    add_callback_effects(cx, cbref, *span, d, e, ex);
                                });
                                for label in r.labels {
                                    d.insert(EffectFinding {
                                        label: label.to_owned(),
                                        origin: name.simple().to_owned(),
                                        line: cx.tree().position(span.start).line,
                                        path: cx.path().to_owned(),
                                    });
                                }
                                if r.discharge_taint {
                                    nt.insert(sym);
                                } else {
                                    e.insert(sym);
                                }
                            }
                            None => {
                                e.insert(sym);
                            }
                        }
                    }
                    FnResolution::Builtin => {
                        for f in
                            builtin_findings(name.simple(), *span, cx.tree(), cx.path(), targets)
                        {
                            d.insert(f);
                        }
                    }
                    // Ambiguous / unresolved: effects unknown → non-exhaustive.
                    // The plugin channel gets the last word here and nowhere
                    // else (ADR-0068 precedence): a project body and a catalog
                    // row are both already spoken for above.
                    FnResolution::Unknown => {
                        if let Some(labels) = plugin_call_labels(cx, plugins, name) {
                            dc.extend(labels.iter().cloned());
                        }
                        *ex = false;
                    }
                }
            }
            EffectOrigin::Output { keyword, span } => {
                d.insert(EffectFinding {
                    label: "output".to_owned(),
                    origin: (*keyword).to_owned(),
                    line: cx.tree().position(span.start).line,
                    path: cx.path().to_owned(),
                });
            }
            EffectOrigin::Exit { keyword, span } => {
                d.insert(EffectFinding {
                    label: "exit".to_owned(),
                    origin: (*keyword).to_owned(),
                    line: cx.tree().position(span.start).line,
                    path: cx.path().to_owned(),
                });
            }
            EffectOrigin::MethodCall { receiver, method, span } => {
                match resolve_effect_edge(cx, class_fqn, receiver, method) {
                    Some(callee) => {
                        e.insert(callee);
                    }
                    // No project edge — the builtin-class catalog gets its say
                    // (`new PDO(...)->query()` is `io.db`), and failing that the
                    // receiver may still carry a *declared* bound: an interface
                    // envelope caps what the call can do even when no body is
                    // resolvable (ADR-0067). Importing it discharges **this**
                    // call site's taint and nothing else — another unresolved
                    // call in the same body still marks the summary `…?`. An
                    // uncatalogued, undeclared receiver stays the taint it has
                    // always been.
                    //
                    // The two legs cannot both fire: `builtin_method_findings`
                    // answers only for `EffectRecv::ClassName` (a catalogued
                    // external class), `resolve_declared_bound` only for the
                    // declared receivers, which name no class here.
                    None => match builtin_method_findings(cx, receiver, method, *span) {
                        Some(fs) => {
                            for f in fs {
                                d.insert(f);
                            }
                        }
                        None => match resolve_declared_bound(
                            cx,
                            class_fqn,
                            params,
                            receiver,
                            method,
                        ) {
                            Some(labels) => dc.extend(labels),
                            None => *ex = false,
                        },
                    },
                }
            }
            // A higher-order call: the callback's effects join the caller's, or
            // the base call resolves normally for a non-invoker callee (ADR-0033).
            EffectOrigin::HigherOrder { callee, callbacks, arg_count, arg_targets, span } => {
                let targets = Some(arg_targets.as_slice());
                match steins_catalog::invocation_shape(callee.simple()) {
                    Some(shape) => {
                        // ADR-0063 P1: the call's effect is the invoker's OWN
                        // catalog color ⊔ the envelope of the callback it
                        // immediately invokes. The own-color leg runs first and
                        // unconditionally — an unresolvable (or absent) callback
                        // never *weakens* the invoker's declared color; it only
                        // adds the `…?` taint below. P2 is what puts anything in
                        // that leg for the sort family: `usort`'s own color is
                        // the by-ref write to its array argument.
                        for f in
                            builtin_findings(callee.simple(), *span, cx.tree(), cx.path(), targets)
                        {
                            d.insert(f);
                        }
                        if shape.callback_param < *arg_count {
                            match callbacks.iter().find(|(p, _)| *p == shape.callback_param) {
                                Some((_, cbref)) => {
                                    add_callback_effects(cx, cbref, *span, d, e, ex);
                                }
                                // Callback slot filled by an unresolvable value.
                                None => *ex = false,
                            }
                        }
                    }
                    // Not a known invoker: the callee is a normal edge, unless it
                    // is a user function declaring a conditional-purity contract
                    // — a userland catalog row (ADR-0063 §2 decision 2).
                    None => match cx.resolve_effect_function(callee) {
                        FnResolution::User(site) => {
                            let decl = cx.fn_decl(site);
                            let sym = Sym::Func(decl.fqn.clone());
                            match conditional_purity(decl.docblock.as_ref(), &decl.params) {
                                Some(cp) => {
                                    let r = eval_conditional_purity(
                                        &cp,
                                        callbacks,
                                        targets,
                                        |cbref| add_callback_effects(cx, cbref, *span, d, e, ex),
                                    );
                                    for label in r.labels {
                                        d.insert(EffectFinding {
                                            label: label.to_owned(),
                                            origin: callee.simple().to_owned(),
                                            line: cx.tree().position(span.start).line,
                                            path: cx.path().to_owned(),
                                        });
                                    }
                                    if r.discharge_taint {
                                        nt.insert(sym);
                                    } else {
                                        e.insert(sym);
                                    }
                                }
                                None => {
                                    e.insert(sym);
                                }
                            }
                        }
                        FnResolution::Builtin => {
                            for f in builtin_findings(
                                callee.simple(),
                                *span,
                                cx.tree(),
                                cx.path(),
                                targets,
                            ) {
                                d.insert(f);
                            }
                        }
                        FnResolution::Unknown => {
                            if let Some(labels) = plugin_call_labels(cx, plugins, callee) {
                                dc.extend(labels.iter().cloned());
                            }
                            *ex = false;
                        }
                    },
                }
            }
            // A `$fn()` resolved to a body-local closure — its effects join.
            EffectOrigin::Callback { cbref, span } => {
                add_callback_effects(cx, cbref, *span, d, e, ex);
            }
            EffectOrigin::Opaque { .. } => *ex = false,
        }
    }
}

/// One line of the `annotate` effect margin.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EffectSummary {
    pub symbol: String,
    /// The same function under its **namespace-qualified** name — `App\Checkout::confirm`
    /// for a method, `App\render_page` for a function — while [`Self::symbol`] stays the
    /// short display name the margin prints. Two declarations with the same short name in
    /// one file (one per namespace block) are legal PHP; a consumer that *keys* on a
    /// summary (the effect baseline of issue #69) needs the name that tells them apart.
    ///
    /// Casing follows the declaration for the simple name and the resolved class FQN;
    /// a function's namespace prefix is the index's lowercase-normalized one, since PHP
    /// folds namespace and function case anyway.
    pub qualified: String,
    pub line: u32,
    pub labels: Vec<String>,
    /// The **declared** effect labels (ADR-0067), sorted: bounds imported from an
    /// interface envelope at a call through an injected receiver, not effects
    /// inference proved. Rendered with a `≤` prefix; never a finding's input.
    ///
    /// Normalized for display: a declared label already covered by a proven label
    /// of this same summary is dropped, since the proven lane says strictly more.
    pub declared: Vec<String>,
    pub exhaustive: bool,
    /// The inferred escaping throw classes (ADR-0040), sorted; empty when none.
    pub throws: Vec<String>,
    /// Whether the throw set is exhaustive (no dynamic/unresolved taint).
    pub throws_exhaustive: bool,
}

/// The proven effect set of every concrete function/method in a single file
/// (ADR-0020 annotate margin). Analyzed as a one-file project.
#[must_use]
pub fn effect_summary(
    tree: &SourceTree,
    functions: &[FunctionDecl],
    classes: &[ClassDecl],
) -> Vec<EffectSummary> {
    let _ = (functions, classes);
    let units = [FileUnit { path: "", tree }];
    let index = Index::from_units(&units);
    effect_summary_units(&units, &index, 0, &PluginFacts::none())
}

/// The proven effect set of every concrete function/method in the `target` file.
#[must_use]
fn effect_summary_units(
    units: &[FileUnit],
    index: &Index,
    target: usize,
    plugins: &PluginFacts,
) -> Vec<EffectSummary> {
    let effects = compute_effects(units, index, plugins);
    let throws = compute_throws(units, index);
    let tree = units[target].tree;
    let sorted_labels = |sym: &Sym| -> Vec<String> {
        let mut labels: Vec<String> = effects
            .get(sym)
            .into_iter()
            .flat_map(|e| e.findings.iter().map(|f| f.label.clone()))
            .collect();
        labels.sort();
        labels.dedup();
        labels
    };
    // The declared lane, normalized against this summary's own proven labels
    // (ADR-0067 rendering rule): `≤io.db` beside a proven `io` (or a proven
    // `io.db`) says nothing the proven lane has not already said, so it is dropped
    // from the display. The stored lanes keep their raw sets.
    let declared_labels = |sym: &Sym, proven: &[String]| -> Vec<String> {
        let mut labels: Vec<String> = effects
            .get(sym)
            .into_iter()
            .flat_map(|e| e.declared.iter().cloned())
            .filter(|l| !proven.iter().any(|p| steins_catalog::subsumes(p, l)))
            .collect();
        labels.sort();
        labels.dedup();
        labels
    };
    let exhaustive = |sym: &Sym| effects.get(sym).is_none_or(|e| e.exhaustive);
    // Escaping throw classes (Yes or Maybe escape) as compact simple names.
    let throw_classes = |sym: &Sym| -> Vec<String> {
        let mut cs: Vec<String> = throws
            .get(sym)
            .into_iter()
            .flat_map(|t| t.facts.keys().map(|f| last_segment(&f.class).to_owned()))
            .collect();
        cs.sort();
        cs.dedup();
        cs
    };
    let throws_exhaustive = |sym: &Sym| throws.get(sym).is_none_or(|t| t.exhaustive);

    // The namespace prefix of a function's index FQN (lowercase-normalized), rejoined
    // with the simple name as declared: `app\renderPage` rather than `app\renderpage`.
    // A global function has no prefix and reads exactly like its declaration.
    let qualify_func = |f: &FunctionDecl| -> String {
        match f.fqn.rsplit_once('\\') {
            Some((ns, _)) => format!("{ns}\\{}", f.name),
            None => f.name.clone(),
        }
    };

    let mut out = Vec::new();
    for f in tree.functions() {
        let sym = Sym::Func(f.fqn.clone());
        let labels = sorted_labels(&sym);
        let declared = declared_labels(&sym, &labels);
        out.push(EffectSummary {
            symbol: f.name.clone(),
            qualified: qualify_func(f),
            line: tree.position(f.span.start).line,
            labels,
            declared,
            exhaustive: exhaustive(&sym),
            throws: throw_classes(&sym),
            throws_exhaustive: throws_exhaustive(&sym),
        });
    }
    for c in tree.classes() {
        // The resolved FQN with the source's casing, when the tree-build pass has
        // stamped it; the simple name is the pre-stamp (and global-namespace) reading.
        let class_display = if c.display.is_empty() { c.name.as_str() } else { c.display.as_str() };
        for m in &c.methods {
            if m.is_abstract {
                continue;
            }
            let sym = Sym::Method(c.fqn.clone(), m.name.clone());
            let labels = sorted_labels(&sym);
            let declared = declared_labels(&sym, &labels);
            out.push(EffectSummary {
                symbol: format!("{}::{}", c.name, m.name),
                qualified: format!("{class_display}::{}", m.name),
                line: tree.position(m.span.start).line,
                labels,
                declared,
                exhaustive: exhaustive(&sym),
                throws: throw_classes(&sym),
                throws_exhaustive: throws_exhaustive(&sym),
            });
        }
    }
    out
}

/// What the effect and throw fixpoints prove about one **region** of source —
/// a byte span inside a function body (ADR-0076 §2). The purity precondition of
/// the loop→`array_map` transform is spelled entirely in these four fields.
///
/// The two lanes stay apart, exactly as ADR-0067 built them. [`Self::labels`] is
/// what inference **proved**; [`Self::declared`] is what a declaration merely
/// **bounds** — an envelope imported at an interface-typed receiver, or a plugin
/// coloring. A cap is not an occurrence proof, so a consumer that needs "provably
/// no effects" must read a non-empty declared lane as *unproven*, never as a
/// weaker kind of proof. The two are reported separately rather than merged so
/// that reading is the consumer's explicit decision.
///
/// Carrying the declared lane is load-bearing, not documentation: the effect pass
/// deliberately **discharges** the exhaustiveness taint at a call whose declared
/// receiver answered (ADR-0067 — the envelope is a checked contract, so the call
/// site is no longer "unknown"), which would otherwise let a declared-only call
/// through a proven-purity gate reading [`Self::exhaustive`] alone.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct RegionPurity {
    /// The proven effect labels arising inside the region, sorted and deduped.
    pub labels: Vec<String>,
    /// The **declared** effect labels bounding calls inside the region, sorted
    /// and deduped (ADR-0067). Never a proof; a non-empty set means some call was
    /// answered by a contract rather than by inference.
    pub declared: Vec<String>,
    /// Whether every call inside the region resolved. `false` means some callee
    /// is unanalyzable — the region *may* have effects nothing proved. A call
    /// answered by a declared envelope is *resolved* for this bit's purposes and
    /// shows up in [`Self::declared`] instead.
    pub exhaustive: bool,
    /// The throw classes (compact simple names) that would escape the region
    /// **with the enclosing `try`/`catch` guards stripped**, sorted and deduped.
    /// Stripping is the point: an enclosing `catch` is exactly the observer that
    /// can tell partial accumulation from an unassigned accumulator, so a body
    /// whose throw an outer `catch` absorbs is still ineligible (ADR-0076 §2.3).
    pub throws: Vec<String>,
    /// Whether the throw set is exhaustive (no dynamic / unresolved taint).
    pub throws_exhaustive: bool,
}

/// Ask the effect and throw fixpoints what they prove about each of `regions`
/// (ADR-0076 §2). Each region is a `(path, start, end)` byte span; the answer at
/// index `i` is the verdict for `regions[i]`.
///
/// The whole-project fixpoints run **once** for the batch, so a transform run
/// over a project pays for them once however many loops it enumerates.
///
/// An origin counts for a region when its span falls inside it, taken over every
/// effect/throw unit of the region's file — the enclosing function's own origins
/// plus those of any closure defined inside the region. Counting a closure that
/// is never invoked can only *refuse* a rewrite, never permit one, which is the
/// direction conservatism has to fall.
#[must_use]
pub fn region_purity_project(
    db: &dyn Db,
    project: Project,
    regions: &[(String, u32, u32)],
) -> Vec<RegionPurity> {
    if regions.is_empty() {
        return Vec::new();
    }
    let handles: Vec<SourceFile> = project.files(db).to_vec();
    let units: Vec<FileUnit> =
        handles.iter().map(|&f| FileUnit { path: f.path(db), tree: parse(db, f) }).collect();
    let db_index = project_index(db, project);
    let pos: HashMap<SourceFile, usize> =
        handles.iter().enumerate().map(|(i, &f)| (f, i)).collect();
    let index = Index::from_db(db_index, &pos);
    let plugins = project.plugins(db);
    let effects = compute_effects(&units, &index, plugins);
    let throws = compute_throws(&units, &index);

    regions
        .iter()
        .map(|(path, start, end)| {
            let Some(fi) = units.iter().position(|u| u.path == path) else {
                return RegionPurity::default();
            };
            region_purity_in(&units, &index, plugins, fi, (*start, *end), &effects, &throws)
        })
        .collect()
}

/// The per-region half of [`region_purity_project`], against already-computed
/// fixpoints.
fn region_purity_in(
    units: &[FileUnit],
    index: &Index,
    plugins: &PluginFacts,
    file: usize,
    region: (u32, u32),
    effects: &HashMap<Sym, EffectSet>,
    throws: &HashMap<Sym, ThrowSet>,
) -> RegionPurity {
    let inside = |s: steins_syntax::Span| s.start >= region.0 && s.end <= region.1;
    let cx = Cx::new(units, index, file);
    let tree = units[file].tree;

    // Every effect/throw origin of this file that falls inside the region, kept
    // with the frame facts its classification needs (the enclosing class for a
    // `$this->`/`self::` edge, the parameter list for an ADR-0067 receiver type).
    let mut eff: HashSet<EffectFinding> = HashSet::new();
    let mut declared: HashSet<String> = HashSet::new();
    let mut edges: HashSet<Sym> = HashSet::new();
    let mut untainting: HashSet<Sym> = HashSet::new();
    let mut exhaustive = true;
    let mut throw_direct: HashMap<ThrowFact, Certainty> = HashMap::new();
    let mut throw_edges: Vec<(Sym, Vec<Vec<CatchClause>>)> = Vec::new();
    let mut throws_exhaustive = true;

    let mut take = |class_fqn: Option<&str>,
                    params: &[steins_syntax::Param],
                    eo: &[EffectOrigin],
                    to: &[ThrowOrigin]| {
        let picked: Vec<EffectOrigin> =
            eo.iter().filter(|o| inside(effect_origin_span(o))).cloned().collect();
        classify_effect_origins(
            &cx,
            class_fqn,
            params,
            &picked,
            plugins,
            &mut eff,
            &mut declared,
            &mut edges,
            &mut untainting,
            &mut exhaustive,
        );
        // The guards are dropped, not carried: this region's own body cannot
        // hold a `try` (a `try` is a statement, and the eligible body is one
        // append), so every guard on a picked origin is an ENCLOSING one — and
        // an enclosing `catch` is the observer that distinguishes the two
        // spellings, so it must not absorb anything here (ADR-0076 §2.3).
        let picked_throws: Vec<ThrowOrigin> = to
            .iter()
            .filter(|o| inside(o.span))
            .map(|o| ThrowOrigin { kind: o.kind.clone(), span: o.span, guards: Vec::new() })
            .collect();
        classify_throw_origins(
            &cx,
            file,
            class_fqn,
            &picked_throws,
            &mut throw_direct,
            &mut throw_edges,
            &mut throws_exhaustive,
        );
    };

    for f in tree.functions() {
        take(None, &f.params, &f.effect_origins, &f.throw_origins);
    }
    for c in tree.classes() {
        for m in &c.methods {
            take(Some(&c.fqn), &m.params, &m.effect_origins, &m.throw_origins);
        }
    }
    for scope in tree.scopes() {
        take(None, &scope.params, &scope.effect_origins, &scope.throw_origins);
    }

    // Join the callees' fixpoint results — the region's transitive answer. Both
    // lanes ride the same edges, monotone in the same way, and never mix.
    let mut labels: Vec<String> = eff.iter().map(|f| f.label.clone()).collect();
    let mut declared_labels: Vec<String> = declared.into_iter().collect();
    for callee in edges.iter().chain(untainting.iter()) {
        if let Some(set) = effects.get(callee) {
            labels.extend(set.findings.iter().map(|f| f.label.clone()));
            declared_labels.extend(set.declared.iter().cloned());
        }
    }
    for callee in &edges {
        if effects.get(callee).is_some_and(|s| !s.exhaustive) {
            exhaustive = false;
        }
    }
    labels.sort();
    labels.dedup();
    declared_labels.sort();
    declared_labels.dedup();

    let mut classes: Vec<String> =
        throw_direct.keys().map(|f| last_segment(&f.class).to_owned()).collect();
    for (callee, _) in &throw_edges {
        if let Some(set) = throws.get(callee) {
            classes.extend(set.facts.keys().map(|f| last_segment(&f.class).to_owned()));
            if !set.exhaustive {
                throws_exhaustive = false;
            }
        }
    }
    classes.sort();
    classes.dedup();

    RegionPurity {
        labels,
        declared: declared_labels,
        exhaustive,
        throws: classes,
        throws_exhaustive,
    }
}

/// The source span of an [`EffectOrigin`], whatever its shape.
const fn effect_origin_span(o: &EffectOrigin) -> steins_syntax::Span {
    match o {
        EffectOrigin::Call { span, .. }
        | EffectOrigin::Output { span, .. }
        | EffectOrigin::Exit { span, .. }
        | EffectOrigin::MethodCall { span, .. }
        | EffectOrigin::Opaque { span }
        | EffectOrigin::HigherOrder { span, .. }
        | EffectOrigin::Callback { span, .. } => *span,
    }
}

/// The bridge between the effect fixpoint and the contract judgment (ADR-0063 P3).
///
/// The purity half of `pure-callable`/`pure-closure`/`static-pure-closure` asks one
/// question of a bound callable — "is its inferred effect envelope pure?" — and the
/// machinery that answers it ([`compute_effects`]) already exists, keyed by exactly
/// the [`Sym`] a `ClosureRef`/`ClosureTarget` names. What did not exist was a way to
/// ask it from a *call site*: [`compute_effects`] ran only inside
/// [`effect_diagnostics`], a whole-project pass that runs strictly **after** the
/// per-call-site loop. This type is the connection, and nothing more — it adds no
/// effect semantics of its own.
///
/// Purity is read against the same relation the envelope check uses, so the two
/// consumers cannot disagree: a label is disqualifying here exactly when
/// [`exceeds`] would report it against an empty envelope. In particular a closure
/// that `preg_match`es into one of its own locals satisfies `pure-callable` —
/// ADR-0063 §2.3's `mutate.local` tolerance — while the same closure writing
/// `$this->matches` does not.
struct PurityOracle {
    effects: HashMap<Sym, EffectSet>,
}

impl PurityOracle {
    /// Build the oracle, or `None` when no docblock in the project spells a
    /// purity-bearing callable. The fixpoint is a whole-project pass and
    /// [`effect_diagnostics`] already guards its own use of it the same way; without
    /// such a spelling nothing could consult the answer, so the work is pure cost.
    ///
    /// The gate is exact rather than merely cheap: an obligation can only reach a
    /// judgment by being *written*, and every purity-bearing spelling in the
    /// vocabulary (`pure-callable`, `pure-closure`, `static-pure-closure`) contains
    /// one of the two literal substrings tested.
    fn build(units: &[FileUnit], index: &Index, plugins: &PluginFacts) -> Option<Self> {
        let spells_purity = |doc: Option<&String>| {
            doc.is_some_and(|t| t.contains("pure-callable") || t.contains("pure-closure"))
        };
        let any = units.iter().any(|u| {
            u.tree.functions().iter().any(|f| spells_purity(f.docblock.as_ref()))
                || u.tree
                    .classes()
                    .iter()
                    .any(|c| c.methods.iter().any(|m| spells_purity(m.docblock.as_ref())))
        });
        if !any {
            return None;
        }
        Some(PurityOracle { effects: compute_effects(units, index, plugins) })
    }

    /// Whether `sym`'s inferred effect envelope is **provably** not pure: the
    /// fixpoint proved at least one effect finding for it.
    ///
    /// Deliberately one-sided. An unknown symbol answers `false`, and so does a
    /// symbol whose proven finding set is empty but whose `exhaustive` bit is off
    /// (an unresolved callee somewhere below it) — "not proven impure" is the only
    /// answer that can never manufacture a finding. Non-exhaustiveness can hide an
    /// effect, never invent one, so a *non-empty* finding set is a definite verdict
    /// regardless of it.
    ///
    /// Findings every envelope tolerates ([`tolerated_by_every_envelope`]) do not
    /// count: they are proven, but they are not impurity.
    fn provably_impure(&self, sym: &Sym) -> bool {
        self.effects.get(sym).is_some_and(|e| {
            e.findings.iter().any(|f| !tolerated_by_every_envelope(&f.label))
        })
    }
}

/// Effect-envelope diagnostics for the whole project (proven violations only).
fn effect_diagnostics(units: &[FileUnit], index: &Index, plugins: &PluginFacts) -> Vec<Diagnostic> {
    // Fast path: no envelope anywhere → nothing to check.
    let any_envelope = units.iter().any(|u| {
        u.tree.functions().iter().any(|f| f.effect_envelope.is_some())
            || u.tree.classes().iter().any(|c| c.methods.iter().any(|m| m.effect_envelope.is_some()))
    });
    if !any_envelope {
        return Vec::new();
    }

    let effects = compute_effects(units, index, plugins);
    // The registry this project's declared labels are judged against (ADR-0068):
    // builtin taxonomy plus whatever the plugin channel registered.
    let registry = plugins.registry();
    let mut out = Vec::new();
    for fi in 0..units.len() {
        let cx = Cx::new(units, index, fi);
        for f in cx.tree().functions() {
            let Some(env) = &f.effect_envelope else { continue };
            report_unit(&mut out, &cx, None, &f.name, env, &f.effect_origins, &effects, registry);
        }
        for c in cx.tree().classes() {
            for m in &c.methods {
                if let Some(env) = &m.effect_envelope {
                    let display = format!("{}::{}", c.name, m.name);
                    report_unit(
                        &mut out,
                        &cx,
                        Some(&c.fqn),
                        &display,
                        env,
                        &m.effect_origins,
                        &effects,
                        registry,
                    );
                }
                // Liskov (ADR-0033 point 5): a concrete implementation whose PROVEN
                // effects exceed an abstraction's effect envelope. Interfaces carry
                // no bodies, so only concrete class methods are judged.
                if !c.is_interface && !m.is_abstract {
                    emit_effect_liskov(&mut out, &cx, c, m, &effects);
                }
            }
        }
    }
    out
}

/// Emit `effect.liskov-widened` when a concrete method's PROVEN inferred effects
/// exceed the effect envelope declared on an abstraction it overrides/implements
/// (a parent class or interface method — ADR-0033 point 5). Only the proven part
/// judges: the exhaustiveness-tainted (unknown) remainder stays silent.
fn emit_effect_liskov(
    out: &mut Vec<Diagnostic>,
    cx: &Cx,
    class: &ClassDecl,
    m: &MethodDecl,
    effects: &HashMap<Sym, EffectSet>,
) {
    let abstractions = collect_abstraction_effects(cx, class, &m.name);
    if abstractions.is_empty() {
        return;
    }
    let sym = Sym::Method(class.fqn.clone(), m.name.clone());
    let Some(set) = effects.get(&sym) else { return };
    // The impl's proven effect labels (deduplicated, sorted for stable output).
    let mut proven: Vec<&str> = set.findings.iter().map(|f| f.label.as_str()).collect();
    proven.sort_unstable();
    proven.dedup();
    if proven.is_empty() {
        return;
    }
    for (abs_display, labels) in abstractions {
        for label in &proven {
            if !exceeds(&labels, label) {
                continue; // within the abstraction's envelope (purer OK)
            }
            let clause = if labels.is_empty() {
                "#[\\Steins\\Pure]".to_owned()
            } else {
                let quoted: Vec<String> = labels.iter().map(|l| format!("'{l}'")).collect();
                format!("#[\\Steins\\Effect({})]", quoted.join(", "))
            };
            let pos = cx.tree().position(m.span.start);
            let msg = format!(
                "{}::{}() has proven effect {label} but {abs_display}::{}() (its abstraction) is declared {clause} — Liskov effect widening",
                class.name, m.name, m.name
            );
            out.push(Diagnostic {
                id: EFFECT_LISKOV_ID,
                path: cx.path().to_owned(),
                line: pos.line,
                column: pos.column,
                message: msg,
                facet: None,
                fix: None,
            });
        }
    }
}

/// Every abstraction carrier of `method` with a declared effect envelope: the
/// nearest parent CLASS declaring it, plus each interface the class
/// implements/extends (transitively) declaring it — `(display, envelope labels)`.
fn collect_abstraction_effects(cx: &Cx, class: &ClassDecl, method: &str) -> Vec<(String, Vec<String>)> {
    let mut out = Vec::new();
    // Nearest parent class with an effect envelope on this method.
    if let Some((display, labels)) = nearest_parent_effect(cx, class, method) {
        out.push((display, labels));
    }
    // Implemented/extended interfaces declaring the method with an envelope.
    for (display, _file, im) in interface_abstraction_methods(cx, class, method) {
        if let Some(env) = &im.effect_envelope {
            out.push((display, env.labels.clone()));
        }
    }
    out
}

/// The nearest ancestor CLASS (walking `extends`, non-interfaces) declaring
/// `method` with an effect envelope — `(class name, envelope labels)`.
fn nearest_parent_effect(cx: &Cx, class: &ClassDecl, method: &str) -> Option<(String, Vec<String>)> {
    let mut cur = class.parent.as_ref().map(|p| cx.class_fqn(p))?;
    let mut seen: HashSet<String> = HashSet::new();
    loop {
        if !seen.insert(cur.to_ascii_lowercase()) {
            return None;
        }
        let (file, cd) = cx.find_class(&cur)?;
        if cd.is_interface {
            return None;
        }
        if let Some(pm) = cd.methods.iter().find(|pm| pm.name.eq_ignore_ascii_case(method))
            && let Some(env) = &pm.effect_envelope
        {
            return Some((cd.name.clone(), env.labels.clone()));
        }
        cur = cx.units[file].tree.resolve_class_fqn(cd.parent.as_ref()?);
    }
}

/// Emit the diagnostics for one declared-envelope unit (ADR-0005/0018).
#[allow(clippy::too_many_arguments)]
fn report_unit(
    out: &mut Vec<Diagnostic>,
    cx: &Cx,
    class_fqn: Option<&str>,
    display: &str,
    envelope: &EffectEnvelope,
    origins: &[EffectOrigin],
    effects: &HashMap<Sym, EffectSet>,
    registry: &steins_catalog::LabelRegistry,
) {
    // 1. Unknown declared labels (one diagnostic each, at the attribute span).
    for label in &envelope.labels {
        if registry.is_known(label) {
            continue;
        }
        let suggestion = registry
            .nearest(label)
            .map(|s| format!(" — did you mean '{s}'?"))
            .unwrap_or_default();
        let msg = format!(
            "unknown effect label '{label}' in #[\\Steins\\Effect] on {display}(){suggestion}"
        );
        let pos = cx.tree().position(envelope.span.start);
        out.push(Diagnostic {
            id: UNKNOWN_LABEL_ID,
            path: cx.path().to_owned(),
            line: pos.line,
            column: pos.column,
            message: msg,
            facet: None,
            fix: None,
        });
    }

    // 2. Envelope-exceeded violations.
    let labels = &envelope.labels;
    for origin in origins {
        match origin {
            EffectOrigin::Call { name, span, arg_targets } => {
                let targets = arg_targets.as_deref();
                match cx.resolve_effect_function(name) {
                    FnResolution::User(site) => {
                        let decl = cx.fn_decl(site);
                        let callee = Sym::Func(decl.fqn.clone());
                        emit_transitive(out, cx, &callee, effects, span.start, display, labels);
                        // The `@pure-unless-parameter-passed` leg: a userland
                        // out-param row, reported like the catalog's.
                        report_conditional_purity(
                            out, cx, decl, &[], targets, effects, *span, display, labels,
                        );
                    }
                    FnResolution::Builtin => {
                        for f in
                            builtin_findings(name.simple(), *span, cx.tree(), cx.path(), targets)
                        {
                            if exceeds(labels, &f.label) {
                                let prefix = format!("{}() has effect {}", name.simple(), f.label);
                                out.push(exceeded_diag(
                                    cx, span.start, &prefix, display, labels, &f.label,
                                ));
                            }
                        }
                    }
                    FnResolution::Unknown => {}
                }
            }
            EffectOrigin::Output { keyword, span } if exceeds(labels, "output") => {
                let prefix = format!("{keyword} has effect output");
                out.push(exceeded_diag(cx, span.start, &prefix, display, labels, "output"));
            }
            EffectOrigin::Exit { keyword, span } if exceeds(labels, "exit") => {
                let prefix = format!("{keyword} has effect exit");
                out.push(exceeded_diag(cx, span.start, &prefix, display, labels, "exit"));
            }
            EffectOrigin::MethodCall { receiver, method, span } => {
                if let Some(callee) = resolve_effect_edge(cx, class_fqn, receiver, method) {
                    emit_transitive(out, cx, &callee, effects, span.start, display, labels);
                // There is deliberately no declared-lane leg here: a declared bound
                // is not a proven effect, and this function only reports proven
                // ones (ADR-0067 decision 5). An ADR-0067 receiver reaches neither
                // arm and so reports nothing, which is the whole point.
                } else if let Some(fs) = builtin_method_findings(cx, receiver, method, *span) {
                    // A builtin-class catalog row, reported like a builtin call's.
                    for f in fs {
                        if exceeds(labels, &f.label) {
                            let prefix = format!("{}() has effect {}", f.origin, f.label);
                            out.push(exceeded_diag(
                                cx, span.start, &prefix, display, labels, &f.label,
                            ));
                        }
                    }
                }
            }
            // A higher-order call (the array_map redemption): a resolvable callback
            // at the shape's callback param contributes its effects with the
            // callback's own origin in the provenance (ADR-0033). A non-invoker
            // callee resolves as a normal edge.
            EffectOrigin::HigherOrder { callee, callbacks, arg_count, arg_targets, span } => {
                let targets = Some(arg_targets.as_slice());
                match steins_catalog::invocation_shape(callee.simple()) {
                    Some(shape) => {
                        // ADR-0063 P1 own-color leg, mirroring `compute_effects`:
                        // the invoker's own catalog color is reported whether or not
                        // the callback at the shape's position resolves.
                        for f in
                            builtin_findings(callee.simple(), *span, cx.tree(), cx.path(), targets)
                        {
                            if exceeds(labels, &f.label) {
                                let prefix = format!("{}() has effect {}", callee.simple(), f.label);
                                out.push(exceeded_diag(cx, span.start, &prefix, display, labels, &f.label));
                            }
                        }
                        if shape.callback_param < *arg_count
                            && let Some((_, cbref)) =
                                callbacks.iter().find(|(p, _)| *p == shape.callback_param)
                        {
                            report_callback(out, cx, cbref, effects, span.start, display, labels);
                        }
                    }
                    None => {
                        if let FnResolution::User(site) = cx.resolve_effect_function(callee) {
                            let decl = cx.fn_decl(site);
                            let cs = Sym::Func(decl.fqn.clone());
                            emit_transitive(out, cx, &cs, effects, span.start, display, labels);
                            report_conditional_purity(
                                out, cx, decl, callbacks, targets, effects, *span, display, labels,
                            );
                        } else if let FnResolution::Builtin = cx.resolve_effect_function(callee) {
                            for f in builtin_findings(
                                callee.simple(),
                                *span,
                                cx.tree(),
                                cx.path(),
                                targets,
                            ) {
                                if exceeds(labels, &f.label) {
                                    let prefix = format!("{}() has effect {}", callee.simple(), f.label);
                                    out.push(exceeded_diag(cx, span.start, &prefix, display, labels, &f.label));
                                }
                            }
                        }
                    }
                }
            }
            // A `$fn()` resolved to a body-local closure — report its effects.
            EffectOrigin::Callback { cbref, span } => {
                report_callback(out, cx, cbref, effects, span.start, display, labels);
            }
            EffectOrigin::Output { .. } | EffectOrigin::Exit { .. } => {}
            EffectOrigin::Opaque { .. } => {}
        }
    }
}

/// Emit the envelope-exceeded violations a callee's **conditional-purity**
/// contracts produce at this call site (ADR-0063 §2 decision 2), mirroring the
/// `compute_effects` arm: the bound callables' effects for
/// `@pure-unless-callable-is-impure`, the by-ref color for
/// `@pure-unless-parameter-passed`.
#[expect(clippy::too_many_arguments, reason = "mirrors report_unit's own parameter set")]
fn report_conditional_purity(
    out: &mut Vec<Diagnostic>,
    cx: &Cx,
    decl: &FunctionDecl,
    callbacks: &[(usize, steins_syntax::CallbackRef)],
    arg_targets: Option<&[steins_syntax::RefTarget]>,
    effects: &HashMap<Sym, EffectSet>,
    span: steins_syntax::Span,
    display: &str,
    labels: &[String],
) {
    let Some(cp) = conditional_purity(decl.docblock.as_ref(), &decl.params) else { return };
    let mut pending: Vec<steins_syntax::CallbackRef> = Vec::new();
    let r = eval_conditional_purity(&cp, callbacks, arg_targets, |cbref| {
        pending.push(cbref.clone());
    });
    for cbref in &pending {
        report_callback(out, cx, cbref, effects, span.start, display, labels);
    }
    for label in r.labels {
        if exceeds(labels, label) {
            let prefix = format!("{}() has effect {label}", decl.name);
            out.push(exceeded_diag(cx, span.start, &prefix, display, labels, label));
        }
    }
}

/// Emit envelope-exceeded violations for a resolved callback (ADR-0033): a
/// closure/user callback's transitive effects, or a builtin callback's catalog
/// effect, each named with the callback in the provenance.
fn report_callback(
    out: &mut Vec<Diagnostic>,
    cx: &Cx,
    cbref: &steins_syntax::CallbackRef,
    effects: &HashMap<Sym, EffectSet>,
    offset: u32,
    display: &str,
    labels: &[String],
) {
    if let Some(sym) = callback_effect_edge(cx, cbref) {
        emit_transitive(out, cx, &sym, effects, offset, display, labels);
    } else if let steins_syntax::CallbackRef::Named(name) = cbref
        && let FnResolution::Builtin = cx.resolve_effect_function(name)
    {
        for f in builtin_findings(
            name.simple(),
            steins_syntax::Span { start: offset, end: offset },
            cx.tree(),
            cx.path(),
            None,
        ) {
            if exceeds(labels, &f.label) {
                let prefix = format!("{}() has effect {}", name.simple(), f.label);
                out.push(exceeded_diag(cx, offset, &prefix, display, labels, &f.label));
            }
        }
    }
}

/// Emit each proven effect of `callee` not subsumed by the envelope as a
/// transitive violation, naming the ultimate origin.
fn emit_transitive(
    out: &mut Vec<Diagnostic>,
    cx: &Cx,
    callee: &Sym,
    effects: &HashMap<Sym, EffectSet>,
    offset: u32,
    display: &str,
    labels: &[String],
) {
    let callee_display = cx.sym_display(callee);
    let mut fs: Vec<&EffectFinding> =
        effects.get(callee).map(|e| &e.findings).into_iter().flatten().collect();
    fs.sort_by(|a, b| (a.line, &a.label, &a.origin).cmp(&(b.line, &b.label, &b.origin)));
    for ef in fs {
        if !exceeds(labels, &ef.label) {
            continue;
        }
        // Name the file when the ultimate origin arises in a different file than
        // the declared-envelope unit being reported (cross-file provenance).
        let loc = if ef.path == cx.path() {
            format!("line {}", ef.line)
        } else {
            format!("{} line {}", ef.path, ef.line)
        };
        let prefix =
            format!("{callee_display}() has effect {} (via {} at {loc})", ef.label, ef.origin);
        out.push(exceeded_diag(cx, offset, &prefix, display, labels, &ef.label));
    }
}

/// The by-ref-into-a-caller-local color (ADR-0063 §2.3).
const MUTATE_LOCAL: &str = "mutate.local";

/// Whether an effect label is tolerated by **every** envelope, `#[\Steins\Pure]`
/// included (ADR-0063 §2.3).
///
/// `mutate.local` is the only member and, by construction, the only one there can
/// be: it names a write whose target lives inside the calling frame, so no
/// observer outside that frame can distinguish a run where it happened from one
/// where it did not. An envelope constrains what a *caller* may observe; a label
/// no caller can observe cannot exceed one.
///
/// The ADR states the tolerance for `Pure` specifically. It is implemented for
/// every envelope because `Pure` is the *tightest* envelope in the lattice —
/// tolerating a label there while rejecting it under a wider declaration would
/// make the check non-monotone, and `#[\Steins\Effect('output')]` (strictly
/// weaker than `Pure`) would flag a call `#[\Steins\Pure]` accepts.
fn tolerated_by_every_envelope(effect_label: &str) -> bool {
    effect_label == MUTATE_LOCAL
}

/// Whether an inferred `effect_label` **exceeds** the declared `labels`.
fn exceeds(labels: &[String], effect_label: &str) -> bool {
    if tolerated_by_every_envelope(effect_label) {
        return false;
    }
    !labels.iter().any(|l| steins_catalog::subsumes(l, effect_label))
}

/// Build an `effect.envelope-exceeded` diagnostic.
fn exceeded_diag(
    cx: &Cx,
    offset: u32,
    prefix: &str,
    display: &str,
    labels: &[String],
    exceeding_label: &str,
) -> Diagnostic {
    let clause = if labels.is_empty() {
        "#[\\Steins\\Pure]".to_owned()
    } else {
        let quoted: Vec<String> = labels.iter().map(|l| format!("'{l}'")).collect();
        format!(
            "#[\\Steins\\Effect({})] — {exceeding_label} exceeds the envelope",
            quoted.join(", ")
        )
    };
    let msg = format!("{prefix}, but {display}() is declared {clause}");
    let pos = cx.tree().position(offset);
    Diagnostic { id: EFFECT_ID, path: cx.path().to_owned(), line: pos.line, column: pos.column, message: msg, facet: None, fix: None }
}

/// The effect label a by-ref write through an argument with this lvalue root
/// carries (ADR-0063 §2.3) — the **target leg** of the conditional out-param row.
///
/// The three answers are three genuinely different contracts, which is exactly
/// why the row cannot be a per-function flag: `preg_match($p, $s, $m)` writes
/// only the frame, `preg_match($p, $s, $this->m)` mutates an object every caller
/// shares, and `preg_match($p, $s, $_SESSION['m'])` writes interpreter-global
/// state.
///
/// Non-local targets stop at the conservative parent `mutate` rather than pick an
/// ADR-0055 child (`mutate.self` / `mutate.instance` / `mutate.static`): that
/// taxonomy's *inference* (ADR-0055) is not built, and a coarse-but-true
/// label is worth more than a precise guess. So Steins **does** distinguish the
/// targets — property-rooted by-ref writes never claim `mutate.local` — while
/// declining to name which flavor of escape it is.
fn by_ref_label(target: steins_syntax::RefTarget) -> &'static str {
    match target {
        steins_syntax::RefTarget::Local => MUTATE_LOCAL,
        steins_syntax::RefTarget::Superglobal => "global.write",
        steins_syntax::RefTarget::Escaping => "mutate",
    }
}

/// The by-ref out-parameter labels a call to `name` carries, given the classified
/// argument list (ADR-0063 §2.3). `arg_targets` is `None` when positional mapping
/// was defeated by a named/spread argument — every conditional judgment is then
/// withheld, because `preg_match(matches: $m, …)` and `preg_match($p, $s)` cannot
/// be told apart by position and a guess in either direction is a lie.
fn out_param_labels(name: &str, arg_targets: Option<&[steins_syntax::RefTarget]>) -> Vec<&'static str> {
    let (Some(positions), Some(targets)) = (steins_catalog::out_params(name), arg_targets) else {
        return Vec::new();
    };
    let mut labels: Vec<&'static str> = Vec::new();
    for &p in positions {
        // The arity leg: an argument that was not supplied is not written.
        let Some(&target) = targets.get(p) else { continue };
        let label = by_ref_label(target);
        if !labels.contains(&label) {
            labels.push(label);
        }
    }
    labels
}

/// The proven effect findings a builtin `name` carries: its unconditional catalog
/// color ([`steins_catalog::effect_labels`]) joined with the **conditional**
/// by-ref out-parameter color this particular call earns
/// ([`steins_catalog::out_params`]).
///
/// The two axes are independent and both may fire: `shuffle($rows)` is
/// `nondet.random` *and* `mutate.local`. Empty for a pure or uncatalogued builtin
/// called without an out-parameter.
fn builtin_findings(
    name: &str,
    span: steins_syntax::Span,
    tree: &SourceTree,
    path: &str,
    arg_targets: Option<&[steins_syntax::RefTarget]>,
) -> Vec<EffectFinding> {
    let colored = steins_catalog::effect_labels(name).unwrap_or(&[]);
    let by_ref = out_param_labels(name, arg_targets);
    if colored.is_empty() && by_ref.is_empty() {
        return Vec::new();
    }
    let line = tree.position(span.start).line;
    colored
        .iter()
        .copied()
        .chain(by_ref)
        .map(|label| EffectFinding {
            label: label.to_owned(),
            origin: name.to_owned(),
            line,
            path: path.to_owned(),
        })
        .collect()
}

/// Resolve a method-call effect origin to the unit it edges to (project-wide).
fn resolve_effect_edge(
    cx: &Cx,
    enclosing: Option<&str>,
    receiver: &EffectRecv,
    method: &str,
) -> Option<Sym> {
    let (start, exact) = match receiver {
        EffectRecv::This | EffectRecv::SelfKw => (enclosing?.to_owned(), false),
        EffectRecv::Parent => (cx.parent_fqn(enclosing?)?, true),
        EffectRecv::ClassName(name) => (cx.class_fqn(name), true),
        // A declared receiver (ADR-0067) names an abstraction, never a body: the
        // whole point is that dependency injection put an unknown implementation
        // behind it. It draws no propagation edge — see [`resolve_declared_bound`].
        EffectRecv::Var(_) | EffectRecv::PropRead(_) => return None,
    };
    let Resolution::Found(r) = resolve_in_chain(cx, &start, method) else { return None };
    if r.method.visibility == Visibility::Private
        && !enclosing.is_some_and(|e| e.eq_ignore_ascii_case(&r.declaring_class.fqn))
    {
        return None;
    }
    if !exact {
        let declaring_final = r.declaring_class.is_final;
        if !(r.method.is_final || r.method.visibility == Visibility::Private || declaring_final) {
            return None;
        }
    }
    Some(Sym::Method(r.declaring_class.fqn.clone(), r.method.name.clone()))
}

/// The **builtin-class catalog** answer for a method-call origin whose receiver
/// draws no project edge (issue #67): the findings a
/// [`steins_catalog::method_effect_labels`] row contributes, `Some(vec![])` for a
/// catalogued-pure row, and `None` when the catalog says nothing — which is the
/// caller's cue to taint exhaustiveness, exactly as an unresolved receiver does
/// today.
///
/// Three gates stand between a method call and a row, and each one is the
/// FP-safe side of a question the analyzer cannot otherwise answer:
///
/// * the receiver must be a **named class** (`new PDO(...)->query()`,
///   `PDO::…`) — `$this`/`self`/`parent` are the project's own world, and a
///   `$pdo->query()` variable receiver names no class to look up (it is either an
///   [`EffectOrigin::Opaque`] or an ADR-0067 declared receiver, and both taint
///   here);
/// * the name must resolve to a class the project **does not define**
///   ([`Cx::class_absent`]) — a project `PDO` shadows the catalog, because its
///   body is the truth and [`resolve_effect_edge`] already drew that edge;
/// * the resolved FQN must be **global** — the engine's classes are unnamespaced,
///   so an unimported `PDO` inside `namespace App;` is `App\PDO`, some class of
///   the user's that Steins simply has not indexed, and coloring it `io.db` would
///   be the guess this analyzer does not make.
fn builtin_method_findings(
    cx: &Cx,
    receiver: &EffectRecv,
    method: &str,
    span: steins_syntax::Span,
) -> Option<Vec<EffectFinding>> {
    let EffectRecv::ClassName(name) = receiver else { return None };
    let fqn = cx.class_fqn(name);
    if fqn.contains('\\') || !cx.class_absent(&fqn) {
        return None;
    }
    let labels = steins_catalog::method_effect_labels(&fqn, method)?;
    // The source spelling, as the function rows use `name.simple()`.
    let origin = format!("{}::{}", name.simple(), method);
    let line = cx.tree().position(span.start).line;
    Some(
        labels
            .iter()
            .map(|label| EffectFinding {
                label: (*label).to_owned(),
                origin: origin.clone(),
                line,
                path: cx.path().to_owned(),
            })
            .collect(),
    )
}

/// The **declared** effect bound a call through a declared receiver imports
/// (ADR-0067): the effect envelope carried by `method` on the project interface
/// the receiver's declared type names.
///
/// `None` is the pre-ADR-0067 answer — the receiver has no declared type, the type
/// is not a single project interface, the interface does not declare the method,
/// or the declaration carries no envelope. In every one of those cases the call
/// site keeps tainting exhaustiveness: *absence of a contract is not a contract*.
///
/// Only interfaces qualify. A non-final class is an abstraction carrier too, but a
/// class *has* a body, so its envelope and its inferred effects are two different
/// facts that the proven lane already reasons about; keeping the declared lane to
/// interfaces keeps the two from arguing.
fn resolve_declared_bound(
    cx: &Cx,
    enclosing: Option<&str>,
    params: &[steins_syntax::Param],
    receiver: &EffectRecv,
    method: &str,
) -> Option<Vec<String>> {
    let ty = match receiver {
        // `f(Repo $r) { $r->find(); }` — the parameter's own declared type. The
        // syntax gate already proved this frame never writes `$r`, so the binding
        // still holds what the signature typed.
        EffectRecv::Var(name) => params.iter().find(|p| &p.name == name)?.ty.as_ref()?,
        // `$this->repo->find()` — the declared (or constructor-promoted) type of
        // the property, inherited members included.
        EffectRecv::PropRead(prop) => {
            cx.class_props(enclosing?).into_iter().find(|p| &p.name == prop)?.ty.as_ref()?
        }
        EffectRecv::This | EffectRecv::SelfKw | EffectRecv::Parent | EffectRecv::ClassName(_) => {
            return None;
        }
    };
    let fqn = sole_object_fqn(ty)?;
    let (file, decl) = cx.find_class(&fqn)?;
    if !decl.is_interface {
        return None;
    }
    nearest_interface_envelope(cx, file, decl, method)
}

/// The FQN of a declared type that names **exactly one** object type, or `None`
/// for a union, an intersection, or a scalar. A nullable single object type still
/// qualifies: `null` never reaches the method, so the interface's envelope still
/// bounds every call that actually happens.
fn sole_object_fqn(ty: &steins_syntax::NativeType) -> Option<String> {
    match ty.members.as_slice() {
        [steins_syntax::TypeMember::Instance { fqn, .. }] => Some(fqn.clone()),
        _ => None,
    }
}

/// The nearest effect envelope declared for `method` on an interface hierarchy,
/// searched breadth-first from the interface itself outward through the
/// interfaces it extends — so the nearest carrier wins. An interface that
/// redeclares the method without an envelope does not erase an ancestor's bound
/// (an implementation owes both, and the ancestor's is the one that was written).
fn nearest_interface_envelope<'a>(
    cx: &Cx<'a>,
    start_file: usize,
    start: &'a ClassDecl,
    method: &str,
) -> Option<Vec<String>> {
    let mut level: Vec<(usize, &'a ClassDecl)> = vec![(start_file, start)];
    let mut seen: HashSet<String> = HashSet::new();
    while !level.is_empty() {
        let mut next: Vec<(usize, &'a ClassDecl)> = Vec::new();
        for (file, id) in level {
            if !seen.insert(id.fqn.to_ascii_lowercase()) {
                continue;
            }
            if let Some(m) = id.methods.iter().find(|m| m.name.eq_ignore_ascii_case(method))
                && let Some(env) = &m.effect_envelope
            {
                return Some(env.labels.clone());
            }
            let tree = cx.units[file].tree;
            let parents = id
                .parent
                .iter()
                .chain(id.implements.iter())
                .map(|r| tree.resolve_class_fqn(r))
                .collect::<Vec<String>>();
            for fqn in parents {
                if let Some((f, d)) = cx.find_class(&fqn)
                    && d.is_interface
                {
                    next.push((f, d));
                }
            }
        }
        level = next;
    }
    None
}

// ---------------------------------------------------------------------------
// Throw system (ADR-0040 damming / ADR-0007 checked accounting). Runs alongside
// the effect fixpoint over the same resolved call graph: `throws(f) = escaping
// own-throws(f) ∪ ⋃ filter(throws(callee), caller-guards)`, monotone to a
// fixpoint, with a throw-exhaustiveness bit tainted by dynamic/unresolved calls
// and opaque throws (mirroring effects).
// ---------------------------------------------------------------------------

/// One throw fact a unit can raise, with the provenance a `via` message needs.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct ThrowFact {
    /// The thrown class, resolved to an FQN in its origin file's context.
    class: String,
    /// Display for the throwing construct (`new RuntimeException`, `intdiv()`).
    origin: String,
    /// The file the origin lives in (for cross-file position/provenance).
    origin_file: usize,
    /// The origin construct's span start in `origin_file`.
    offset: u32,
    line: u32,
    path: String,
}

/// A unit's throw fixpoint result: the set of throws that **escape** it (each
/// with an escape [`Certainty`] — only `Yes`/`Maybe` are stored; `No`/absorbed
/// throws never enter), plus whether the set is exhaustive (ADR-0040).
#[derive(Debug, Clone, Default)]
struct ThrowSet {
    facts: HashMap<ThrowFact, Certainty>,
    exhaustive: bool,
}

/// Wire a resolved callback's throws into the throw graph (ADR-0033), filtered by
/// the call site's `guards`: a closure/user callback is an edge; a builtin
/// callback contributes its curated throws directly; an unknown callback taints.
#[allow(clippy::too_many_arguments)]
fn add_callback_throws(
    cx: &Cx,
    file: usize,
    cbref: &steins_syntax::CallbackRef,
    span: steins_syntax::Span,
    guards: &[Vec<CatchClause>],
    d: &mut HashMap<ThrowFact, Certainty>,
    e: &mut Vec<(Sym, Vec<Vec<CatchClause>>)>,
    x: &mut bool,
) {
    match cbref {
        steins_syntax::CallbackRef::Closure(off) => {
            e.push((Sym::Closure(cx.path().to_owned(), *off), guards.to_vec()));
        }
        steins_syntax::CallbackRef::Named(name) => match cx.resolve_function(name) {
            FnResolution::User(site) => {
                e.push((Sym::Func(cx.fn_decl(site).fqn.clone()), guards.to_vec()));
            }
            FnResolution::Builtin => {
                if let Some(classes) = steins_catalog::builtin_throws(name.simple()) {
                    for c in classes {
                        let esc = escape_through_guards(cx, c, guards);
                        if esc == Certainty::No {
                            continue;
                        }
                        let line = cx.tree().position(span.start).line;
                        let fact = ThrowFact {
                            class: (*c).to_owned(),
                            origin: format!("{}()", name.simple()),
                            origin_file: file,
                            offset: span.start,
                            line,
                            path: cx.path().to_owned(),
                        };
                        let slot = d.entry(fact).or_insert(Certainty::No);
                        *slot = slot.or(esc);
                    }
                }
            }
            FnResolution::Unknown => *x = false,
        },
    }
}

/// `sub <: super` through the project inheritance chain **and** the builtin
/// exception table (ADR-0040), as a [`Certainty`]: `Yes` when the chain reaches
/// `super`; `No` when the chain is fully known (terminates at a project root or a
/// builtin root like `Throwable`) without reaching it; `Maybe` when the chain
/// leaves both the project and the builtin table (an unknown external class —
/// the FP-safe middle).
fn throw_subtype(cx: &Cx, sub_fqn: &str, sup_fqn: &str) -> Certainty {
    let sup = sup_fqn.trim_start_matches('\\');
    let mut cur = sub_fqn.trim_start_matches('\\').to_owned();
    let mut seen: HashSet<String> = HashSet::new();
    loop {
        if cur.eq_ignore_ascii_case(sup) {
            return Certainty::Yes;
        }
        if !seen.insert(cur.to_ascii_lowercase()) {
            return Certainty::Maybe; // cycle → give up
        }
        if let Some((file, cd)) = cx.find_class(&cur) {
            match &cd.parent {
                Some(pref) => cur = cx.units[file].tree.resolve_class_fqn(pref),
                None => return Certainty::No, // known project root, no match
            }
        } else if let Some(parent) = steins_catalog::builtin_exception_parent(&cur) {
            cur = parent.to_owned();
        } else if cur.eq_ignore_ascii_case("Throwable") {
            return Certainty::No; // known builtin root, no match
        } else {
            return Certainty::Maybe; // unknown external class — chain incomplete
        }
    }
}

/// Whether a thrown `class` is **checked** for envelope purposes (ADR-0007):
/// `No` (unchecked) for the `Error` / `LogicException` families, `Yes` when
/// provably neither, `Maybe` when the hierarchy is unknown (checked-but-Maybe —
/// envelope-silent, exhaustiveness-tainting).
fn throw_checked(cx: &Cx, class: &str) -> Certainty {
    let unchecked = throw_subtype(cx, class, "Error").or(throw_subtype(cx, class, "LogicException"));
    match unchecked {
        Certainty::Yes => Certainty::No,
        Certainty::No => Certainty::Yes,
        Certainty::Maybe => Certainty::Maybe,
    }
}

/// Whether one catch `clause` absorbs a thrown `sub` class (ADR-0040): `Yes` when
/// a caught member is provably a supertype; `Maybe` when a member might be (chain
/// leaves known territory) or the clause has an unnameable caught member; `No`
/// when no member can catch it.
fn clause_absorbs(cx: &Cx, sub: &str, clause: &CatchClause) -> Certainty {
    let mut r = if clause.has_unresolvable { Certainty::Maybe } else { Certainty::No };
    for cref in &clause.classes {
        let d = cx.class_fqn(cref);
        r = r.or(throw_subtype(cx, sub, &d));
        if r == Certainty::Yes {
            return Certainty::Yes;
        }
    }
    r
}

/// The escape [`Certainty`] of a `Yes`-arriving throw of `sub` past an ordered
/// (innermost-first) guard stack: `No` once a guard provably absorbs it; `Maybe`
/// if a guard might; else `Yes` (ADR-0040 damming, envelope-consumer side).
fn escape_through_guards(cx: &Cx, sub: &str, guards: &[Vec<CatchClause>]) -> Certainty {
    let mut maybe = false;
    for guard in guards {
        let mut absorb = Certainty::No;
        for clause in guard {
            absorb = absorb.or(clause_absorbs(cx, sub, clause));
            if absorb == Certainty::Yes {
                break;
            }
        }
        match absorb {
            Certainty::Yes => return Certainty::No,
            Certainty::Maybe => maybe = true,
            Certainty::No => {}
        }
    }
    if maybe { Certainty::Maybe } else { Certainty::Yes }
}

/// The unified throw fixpoint for every function/method in the project, keyed by
/// [`Sym`] (shared with the effect graph).
fn compute_throws(units: &[FileUnit], index: &Index) -> HashMap<Sym, ThrowSet> {
    struct Unit<'a> {
        sym: Sym,
        file: usize,
        class_fqn: Option<String>,
        origins: &'a [ThrowOrigin],
    }
    let mut ulist: Vec<Unit> = Vec::new();
    for (fi, u) in units.iter().enumerate() {
        for f in u.tree.functions() {
            ulist.push(Unit { sym: Sym::Func(f.fqn.clone()), file: fi, class_fqn: None, origins: &f.throw_origins });
        }
        for c in u.tree.classes() {
            for m in &c.methods {
                ulist.push(Unit {
                    sym: Sym::Method(c.fqn.clone(), m.name.clone()),
                    file: fi,
                    class_fqn: Some(c.fqn.clone()),
                    origins: &m.throw_origins,
                });
            }
        }
        // Closure/arrow bodies are throw nodes too (ADR-0033).
        for scope in u.tree.scopes() {
            if let ScopeOwner::Closure { def_offset } = &scope.owner {
                ulist.push(Unit {
                    sym: Sym::Closure(u.path.to_owned(), *def_offset),
                    file: fi,
                    class_fqn: None,
                    origins: &scope.throw_origins,
                });
            }
        }
    }

    type Edge = (Sym, Vec<Vec<CatchClause>>);
    let mut direct: HashMap<Sym, HashMap<ThrowFact, Certainty>> = HashMap::new();
    let mut edges: HashMap<Sym, Vec<Edge>> = HashMap::new();
    let mut ex: HashMap<Sym, bool> = HashMap::new();
    let mut sym_file: HashMap<Sym, usize> = HashMap::new();

    for unit in &ulist {
        let cx = Cx::new(units, index, unit.file);
        sym_file.insert(unit.sym.clone(), unit.file);
        let d = direct.entry(unit.sym.clone()).or_default();
        let e = edges.entry(unit.sym.clone()).or_default();
        let x = ex.entry(unit.sym.clone()).or_insert(true);
        classify_throw_origins(
            &cx,
            unit.file,
            unit.class_fqn.as_deref(),
            unit.origins,
            d,
            e,
            x,
        );
    }

    // Fixpoint: propagate callee throws through each call site's guards.
    let syms: Vec<Sym> = ulist.iter().map(|u| u.sym.clone()).collect();
    let mut facts = direct;
    loop {
        let mut changed = false;
        for sym in &syms {
            let file = sym_file[sym];
            let cx = Cx::new(units, index, file);
            let sym_edges: Vec<Edge> = edges.get(sym).cloned().unwrap_or_default();
            for (callee, guards) in &sym_edges {
                if ex.get(callee).copied() == Some(false) && ex.get(sym).copied() != Some(false) {
                    ex.insert(sym.clone(), false);
                    changed = true;
                }
                let callee_facts: Vec<(ThrowFact, Certainty)> =
                    facts.get(callee).into_iter().flatten().map(|(f, c)| (f.clone(), *c)).collect();
                for (fact, cert) in callee_facts {
                    let esc = escape_through_guards(&cx, &fact.class, guards);
                    let nc = cert.and(esc);
                    if nc == Certainty::No {
                        continue;
                    }
                    let slot = facts.entry(sym.clone()).or_default();
                    match slot.get(&fact).copied() {
                        Some(prev) => {
                            let merged = prev.or(nc);
                            if merged != prev {
                                slot.insert(fact, merged);
                                changed = true;
                            }
                        }
                        None => {
                            slot.insert(fact, nc);
                            changed = true;
                        }
                    }
                }
            }
        }
        if !changed {
            break;
        }
    }

    syms.into_iter()
        .map(|s| {
            let f = facts.remove(&s).unwrap_or_default();
            let x = ex.get(&s).copied().unwrap_or(true);
            (s, ThrowSet { facts: f, exhaustive: x })
        })
        .collect()
}

/// Classify one unit's (or one **region**'s — ADR-0076) throw origins into the
/// throw fixpoint's accumulators. The regional twin of [`classify_effect_origins`]:
/// a sub-span of a body is asked exactly the question the whole body is asked, so
/// the loop transform's "proven throw set empty" precondition is the throw pass's
/// own verdict rather than a second opinion about what a throw is.
fn classify_throw_origins(
    cx: &Cx,
    file: usize,
    class_fqn: Option<&str>,
    origins: &[ThrowOrigin],
    d: &mut HashMap<ThrowFact, Certainty>,
    e: &mut Vec<(Sym, Vec<Vec<CatchClause>>)>,
    x: &mut bool,
) {
    let add_fact = |class: String, origin: String, span: steins_syntax::Span, cert: Certainty, d: &mut HashMap<ThrowFact, Certainty>| {
        if cert == Certainty::No {
            return;
        }
        let line = cx.tree().position(span.start).line;
        let fact = ThrowFact {
            class,
            origin,
            origin_file: file,
            offset: span.start,
            line,
            path: cx.path().to_owned(),
        };
        let slot = d.entry(fact).or_insert(Certainty::No);
        *slot = slot.or(cert);
    };
    for origin in origins {
        match &origin.kind {
            ThrowKind::New(class) => {
                let d_fqn = cx.class_fqn(class);
                let esc = escape_through_guards(cx, &d_fqn, &origin.guards);
                let display = format!("new {}", last_segment(&d_fqn));
                add_fact(d_fqn, display, origin.span, esc, d);
            }
            ThrowKind::Rethrow { caught, has_unresolvable } => {
                for cref in caught {
                    let d_fqn = cx.class_fqn(cref);
                    let esc = escape_through_guards(cx, &d_fqn, &origin.guards);
                    let display = format!("rethrow {}", last_segment(&d_fqn));
                    add_fact(d_fqn, display, origin.span, esc, d);
                }
                if *has_unresolvable {
                    *x = false;
                }
            }
            ThrowKind::Call(name) => match cx.resolve_function(name) {
                FnResolution::User(site) => {
                    e.push((Sym::Func(cx.fn_decl(site).fqn.clone()), origin.guards.clone()));
                }
                FnResolution::Builtin => {
                    if let Some(classes) = steins_catalog::builtin_throws(name.simple()) {
                        for c in classes {
                            let esc = escape_through_guards(cx, c, &origin.guards);
                            add_fact((*c).to_owned(), format!("{}()", name.simple()), origin.span, esc, d);
                        }
                    }
                }
                FnResolution::Unknown => *x = false,
            },
            ThrowKind::MethodCall { receiver, method } => {
                match resolve_effect_edge(cx, class_fqn, receiver, method) {
                    Some(callee) => e.push((callee, origin.guards.clone())),
                    None => *x = false,
                }
            }
            // A resolved callback's throws propagate through this call site's
            // guards (ADR-0033): a closure/user callback is an edge; a builtin
            // callback contributes its curated throws; unknown taints.
            ThrowKind::Callback { cbref } => {
                add_callback_throws(cx, file, cbref, origin.span, &origin.guards, d, e, x);
            }
            ThrowKind::HigherOrder { callee, callbacks, arg_count } => {
                match steins_catalog::invocation_shape(callee.simple()) {
                    Some(shape) => {
                        if shape.callback_param < *arg_count {
                            match callbacks.iter().find(|(p, _)| *p == shape.callback_param) {
                                Some((_, cbref)) => add_callback_throws(
                                    cx, file, cbref, origin.span, &origin.guards, d, e, x,
                                ),
                                None => *x = false,
                            }
                        }
                    }
                    None => match cx.resolve_function(callee) {
                        FnResolution::User(site) => {
                            e.push((Sym::Func(cx.fn_decl(site).fqn.clone()), origin.guards.clone()));
                        }
                        FnResolution::Builtin => {
                            if let Some(classes) = steins_catalog::builtin_throws(callee.simple()) {
                                for c in classes {
                                    let esc = escape_through_guards(cx, c, &origin.guards);
                                    add_fact((*c).to_owned(), format!("{}()", callee.simple()), origin.span, esc, d);
                                }
                            }
                        }
                        FnResolution::Unknown => *x = false,
                    },
                }
            }
            ThrowKind::Taint => *x = false,
        }
    }
}

/// The last `\`-segment of an FQN (for a compact throw display).
fn last_segment(fqn: &str) -> &str {
    fqn.rsplit('\\').next().unwrap_or(fqn)
}

/// The declared `@throws` class FQNs of one docblock, resolved in the file's
/// context at `offset` (ADR-0040 envelope opt-in). Accepts bare class names and
/// unions of them; anything else contributes nothing. Empty ⇒ no envelope.
fn declared_throws(cx: &Cx, offset: u32, docblock: Option<&str>) -> Vec<String> {
    let Some(text) = docblock else { return Vec::new() };
    let mut out = Vec::new();
    for tag in scan_docblock(text) {
        if tag.kind != TagKind::Throws {
            continue;
        }
        let Some(ty) = parse_tag_type(&tag.type_text) else { continue };
        collect_class_names(&ty, &mut |name| {
            let fqn = resolve_class_name(cx, offset, name);
            if !out.contains(&fqn) {
                out.push(fqn);
            }
        });
    }
    out
}

/// Resolve a phpdoc class name to an FQN in the current file at `offset`.
fn resolve_class_name(cx: &Cx, offset: u32, name: &str) -> String {
    let raw = name.trim_start_matches('\\').to_owned();
    let kind = if name.starts_with('\\') {
        RefKind::FullyQualified
    } else if raw.contains('\\') {
        RefKind::Qualified
    } else {
        RefKind::Unqualified
    };
    cx.tree().resolve_class_fqn(&NameRef { raw, kind, offset })
}

/// Visit each plain class-name identifier in a phpdoc type that is a class name
/// or a union of class names; non-class members are ignored (no envelope).
fn collect_class_names(ty: &PType, f: &mut dyn FnMut(&str)) {
    match &ty.kind {
        PKind::Identifier(name) => f(name),
        PKind::Union { types, .. } => {
            for t in types {
                collect_class_names(t, f);
            }
        }
        PKind::Nullable(inner) => collect_class_names(inner, f),
        _ => {}
    }
}

/// The whole-project throw diagnostics: `throw.undeclared` envelope escapes and
/// `throw.liskov-widened` overrides (ADR-0040/0033).
fn throw_diagnostics(units: &[FileUnit], index: &Index) -> Vec<Diagnostic> {
    // Fast path: nothing to check without a `@throws` tag anywhere.
    let any_throws = units.iter().any(|u| {
        let has = |d: Option<&str>| d.is_some_and(|t| t.contains("@throws") || t.contains("throws"));
        u.tree.functions().iter().any(|f| f.docblock.as_deref().is_some_and(|t| t.contains("throws")))
            || u.tree.classes().iter().any(|c| {
                c.methods.iter().any(|m| has(m.docblock.as_deref()))
            })
    });
    if !any_throws {
        return Vec::new();
    }

    let throws = compute_throws(units, index);
    let mut out = Vec::new();
    for fi in 0..units.len() {
        let cx = Cx::new(units, index, fi);
        for f in cx.tree().functions() {
            let declared = declared_throws(&cx, f.span.start, f.docblock.as_deref());
            if declared.is_empty() {
                continue;
            }
            let sym = Sym::Func(f.fqn.clone());
            emit_undeclared(&mut out, &cx, index, units, &sym, &f.name, &declared, &throws, &f.throw_origins);
        }
        for c in cx.tree().classes() {
            for m in &c.methods {
                let declared = declared_throws(&cx, m.span.start, m.docblock.as_deref());
                let display = format!("{}::{}", c.name, m.name);
                if !declared.is_empty() {
                    let sym = Sym::Method(c.fqn.clone(), m.name.clone());
                    emit_undeclared(&mut out, &cx, index, units, &sym, &display, &declared, &throws, &m.throw_origins);
                }
                // Liskov: an override/impl whose declared throws widen the parent's.
                emit_liskov(&mut out, &cx, c, m, &declared);
            }
        }
    }
    out
}

/// Emit `throw.undeclared` for each checked, proven-escaping throw of `sym` not
/// covered by its declared `@throws` set.
#[allow(clippy::too_many_arguments)]
fn emit_undeclared(
    out: &mut Vec<Diagnostic>,
    cx: &Cx,
    index: &Index,
    units: &[FileUnit],
    sym: &Sym,
    display: &str,
    declared: &[String],
    throws: &HashMap<Sym, ThrowSet>,
    decl_origins: &[ThrowOrigin],
) {
    let Some(set) = throws.get(sym) else { return };
    let declared_list = declared.iter().map(|d| last_segment(d).to_owned()).collect::<Vec<_>>().join("|");
    let mut facts: Vec<(&ThrowFact, Certainty)> = set.facts.iter().map(|(f, c)| (f, *c)).collect();
    facts.sort_by(|a, b| (a.0.origin_file, a.0.offset, &a.0.class).cmp(&(b.0.origin_file, b.0.offset, &b.0.class)));
    for (fact, cert) in facts {
        if cert != Certainty::Yes {
            continue; // Maybe-escape is silent (ADR-0040)
        }
        if throw_checked(cx, &fact.class) != Certainty::Yes {
            continue; // unchecked or unknown-hierarchy — never counts
        }
        // Covered iff a subclass of some declared class (Yes through chain).
        let covered = declared.iter().any(|d| throw_subtype(cx, &fact.class, d) != Certainty::No);
        if covered {
            continue; // Yes (covered) or Maybe (unproven) → silent
        }
        let ocx = Cx::new(units, index, fact.origin_file);
        let pos = ocx.tree().position(fact.offset);
        let simple = last_segment(&fact.class);
        let msg = format!(
            "{simple} can escape {display}() but is not declared (@throws {declared_list}) — proven escape"
        );
        // The `origin` facet (ADR-0050 §4), productionizing the measurement note's
        // rule: DIRECT iff the escaping throw's origin is in the annotated
        // declaration's OWN body — same file as the declaration (`cx.cur`) *and* a
        // member of its own scanned `throw_origins` — else PROPAGATED (it arrived up
        // a call edge). The origin offset is a unique file byte position and
        // `throw_origins` is scoped to this one declaration's body, so the
        // same-file-plus-own-origin test is exact even when a callee shares the file.
        let origin = if fact.origin_file == cx.cur
            && decl_origins.iter().any(|o| o.span.start == fact.offset)
        {
            Origin::Direct
        } else {
            Origin::Propagated
        };
        out.push(Diagnostic {
            id: THROW_UNDECLARED_ID,
            path: fact.path.clone(),
            line: pos.line,
            column: pos.column,
            message: msg,
            facet: Some(Facet::Origin(origin)),
            fix: None,
        });
    }
}

/// Emit `throw.liskov-widened` when a child method's declared `@throws` names a
/// checked class covered by none of the nearest ancestor method's declared
/// `@throws` (both sides must declare; `Maybe` resolution is silent).
fn emit_liskov(out: &mut Vec<Diagnostic>, cx: &Cx, class: &ClassDecl, m: &MethodDecl, child_declared: &[String]) {
    if child_declared.is_empty() {
        return;
    }
    // Every abstraction carrier of this method: the nearest parent class declaring
    // `@throws`, plus every implemented/extended interface declaring it (ADR-0033).
    for (abs_display, abs_declared) in collect_abstraction_throws(cx, class, &m.name) {
        if abs_declared.is_empty() {
            continue;
        }
        let abs_list = abs_declared.iter().map(|d| last_segment(d)).collect::<Vec<_>>().join("|");
        for c in child_declared {
            // A child-declared class widens iff it is a subclass of NO abstraction class.
            let covered = abs_declared.iter().any(|p| throw_subtype(cx, c, p) != Certainty::No);
            if covered {
                continue;
            }
            let pos = cx.tree().position(m.span.start);
            let msg = format!(
                "{} is declared thrown by {}::{}() but {abs_display}::{}() (its abstraction) declares only @throws {abs_list} — Liskov widening",
                last_segment(c), class.name, m.name, m.name
            );
            out.push(Diagnostic {
                id: THROW_LISKOV_ID,
                path: cx.path().to_owned(),
                line: pos.line,
                column: pos.column,
                message: msg,
                facet: None,
                fix: None,
            });
        }
    }
}

/// Every abstraction carrier of `method` with a declared `@throws` envelope: the
/// nearest parent CLASS declaring it (existing behavior), plus each interface the
/// class implements/extends (transitively) declaring it (ADR-0033 Liskov).
fn collect_abstraction_throws(cx: &Cx, class: &ClassDecl, method: &str) -> Vec<(String, Vec<String>)> {
    let mut out = Vec::new();
    if let Some(p) = nearest_parent_throws(cx, class, method) {
        out.push(p);
    }
    for (display, file, im) in interface_abstraction_methods(cx, class, method) {
        let icx = Cx::new(cx.units, cx.index, file);
        let declared = declared_throws(&icx, im.span.start, im.docblock.as_deref());
        if !declared.is_empty() {
            out.push((display, declared));
        }
    }
    out
}

/// The nearest ancestor class (walking `extends`, non-interfaces only) that
/// declares a method named `method` with a `@throws` docblock, returning its class
/// name and declared set.
fn nearest_parent_throws(cx: &Cx, class: &ClassDecl, method: &str) -> Option<(String, Vec<String>)> {
    let mut cur = class.parent.as_ref().map(|p| cx.class_fqn(p))?;
    let mut seen: HashSet<String> = HashSet::new();
    loop {
        if !seen.insert(cur.to_ascii_lowercase()) {
            return None;
        }
        let (file, cd) = cx.find_class(&cur)?;
        // An interface reached via `parent` (an interface's `extends`) is handled by
        // the interface walker, not the parent-class chain.
        if cd.is_interface {
            return None;
        }
        if let Some(pm) = cd.methods.iter().find(|pm| pm.name.eq_ignore_ascii_case(method)) {
            let pcx = Cx::new(cx.units, cx.index, file);
            let declared = declared_throws(&pcx, pm.span.start, pm.docblock.as_deref());
            if !declared.is_empty() {
                return Some((cd.name.clone(), declared));
            }
        }
        cur = cx.units[file].tree.resolve_class_fqn(cd.parent.as_ref()?);
    }
}

/// Every interface method (in an implemented/extended interface, transitively) a
/// class's `method` implements — `(interface display, file, &MethodDecl)`
/// (ADR-0033 Liskov). BFS over `implements` (and each interface's own
/// `parent`/`implements` extends chain); dedup by interface FQN.
fn interface_abstraction_methods<'a>(
    cx: &Cx<'a>,
    class: &ClassDecl,
    method: &str,
) -> Vec<(String, usize, &'a MethodDecl)> {
    let mut out = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();
    // Seed with the class's directly-implemented interfaces.
    let mut queue: Vec<String> = class.implements.iter().map(|r| cx.class_fqn(r)).collect();
    while let Some(fqn) = queue.pop() {
        if !seen.insert(fqn.to_ascii_lowercase()) {
            continue;
        }
        let Some((file, id)) = cx.find_class(&fqn) else { continue };
        if !id.is_interface {
            continue; // only interfaces are abstraction carriers here
        }
        if let Some(im) = id.methods.iter().find(|im| im.name.eq_ignore_ascii_case(method)) {
            out.push((id.name.clone(), file, im));
        }
        // An interface's extended interfaces (parent + implements) are abstractions too.
        let itree = cx.units[file].tree;
        if let Some(p) = &id.parent {
            queue.push(itree.resolve_class_fqn(p));
        }
        for r in &id.implements {
            queue.push(itree.resolve_class_fqn(r));
        }
    }
    out
}

// ---------------------------------------------------------------------------
// The project-aware analysis context.
// ---------------------------------------------------------------------------

/// Read-only analysis context: the whole project view plus the file currently
/// being analyzed. Cheap to copy (all borrows); descent rebuilds it at the
/// callee's file via [`Cx::at`].
/// The shared empty dam fact for the auxiliary passes (effects/throws/const
/// resolution) that never emit an absence id and so never read the dam. The main
/// analysis pass ([`check_units`]) computes the real whole-universe fact and hands
/// it to [`Cx::new_with`]; these passes use [`Cx::new`], which points here.
static EMPTY_DAM: std::sync::LazyLock<DamFacts> = std::sync::LazyLock::new(DamFacts::default);

#[derive(Clone, Copy)]
struct Cx<'a> {
    units: &'a [FileUnit<'a>],
    index: &'a Index,
    cur: usize,
    /// The whole-universe runtime-definition dam fact (ADR-0049 §2), a per-run query
    /// answer (ADR-0048). Read by the absence family's conditional-declaration leg
    /// (A2i): a chain containing a conditional declaration re-dams the claim, so it
    /// fires only when the dam is clear. The auxiliary passes point at [`EMPTY_DAM`].
    dam: &'a DamFacts,
    /// The `[runtime] warning-handler` pseudo-constant (ADR-0049 §7 amendment,
    /// ADR-0037 §2 family). `true` = `"abort"` (the owner-confirmed realistic-app
    /// default: a warning handler converts an `E_WARNING` to an exception / halts, so
    /// a *proven* warning is a proven runtime break — warning-grade offset findings
    /// emit). `false` = `"null"`: the application tolerates the warning and continues,
    /// so warning-grade offset findings leave the proof surface and stay silent (v1
    /// simplification: the ADR-0050 layer-demotion + value-side `null`/`""` adoption
    /// is deferred; v1 either emits under "abort" or silences under "null"). The
    /// Error-grade `offset.on-unsupported` object case (not yet implemented) is
    /// posture-independent and would emit under both.
    warning_handler_abort: bool,
    /// The **effective analysis minor** for version-keyed value rules (issue
    /// #28): the target floor when the project declares a target whose range
    /// agrees on the ADR-0049 A12 next-int boundary, `None` when the declared
    /// range straddles it (a boundary-sensitive literal must then decline —
    /// A12's unknown leg, generalized to a range), and the sidecar's runtime
    /// minor when the project declares nothing (the pre-#28 behavior).
    /// Computed once per run by [`effective_php_view`].
    php_minor: Option<(u16, u16)>,
    /// Whether a catalog-backed is-a verdict used for **arm deletion** must be
    /// demoted to `Unknown` (ADR-0052 A11): some version the analysis is about
    /// — any minor of the declared target range, else the runtime minor — is
    /// not the catalog pin. Computed once per run by [`effective_php_view`].
    catalog_skew: bool,
    /// The `PHP_VERSION_ID` interval the analysis is about (issue #29), for the
    /// version-guard fold — already `None` when a userland constant of that
    /// name is declared anywhere in the project. See [`PhpView::version_id`].
    version_id: Option<(u32, Option<u32>)>,
    /// The whole-project purity answer for the callable-purity obligation
    /// (ADR-0063 P3), or `None` when no purity-bearing callable is spelled anywhere
    /// (and therefore also for every auxiliary pass, which reports no findings of
    /// this family). `None` makes [`Self::provably_impure`] answer `false`, i.e. the
    /// obligation stays silent — the safe side.
    purity: Option<&'a PurityOracle>,
    /// The PHP target range the project DECLARES, verbatim (issue #73). The
    /// version-keyed value rules read [`Self::php_minor`], which has already
    /// collapsed the range to one effective minor; the ADR-0069 floor's gate needs
    /// the range itself, because it asks a different question — whether the whole
    /// declared range lies at or above one builtin's change boundary. `None` is an
    /// undeclared target, which the floor admits.
    php_target: Option<&'a steins_db::PhpTarget>,
}

impl<'a> Cx<'a> {
    fn new(units: &'a [FileUnit<'a>], index: &'a Index, cur: usize) -> Self {
        Self {
            units,
            index,
            cur,
            dam: &EMPTY_DAM,
            warning_handler_abort: true,
            php_minor: None,
            catalog_skew: false,
            version_id: None,
            purity: None,
            php_target: None,
        }
    }

    /// A context carrying an explicit runtime config (the top-level analysis pass).
    #[allow(clippy::too_many_arguments)]
    fn new_with(
        units: &'a [FileUnit<'a>],
        index: &'a Index,
        cur: usize,
        dam: &'a DamFacts,
        warning_handler_abort: bool,
        php_minor: Option<(u16, u16)>,
        catalog_skew: bool,
        version_id: Option<(u32, Option<u32>)>,
        purity: Option<&'a PurityOracle>,
        php_target: Option<&'a steins_db::PhpTarget>,
    ) -> Self {
        Self {
            units,
            index,
            cur,
            dam,
            warning_handler_abort,
            php_minor,
            catalog_skew,
            version_id,
            purity,
            php_target,
        }
    }

    /// A context pointing at a different file (for cross-file descent); the runtime
    /// config and dam fact are whole-run properties and are inherited unchanged.
    fn at(&self, file: usize) -> Cx<'a> {
        Cx {
            units: self.units,
            index: self.index,
            cur: file,
            dam: self.dam,
            warning_handler_abort: self.warning_handler_abort,
            php_minor: self.php_minor,
            catalog_skew: self.catalog_skew,
            version_id: self.version_id,
            purity: self.purity,
            php_target: self.php_target,
        }
    }

    /// Whether a callable symbol is **provably** impure (ADR-0063 P3) — the one
    /// question the purity obligation asks. `false` whenever the oracle is absent,
    /// so an auxiliary pass and a project with no purity spelling both stay silent.
    fn provably_impure(&self, sym: &Sym) -> bool {
        self.purity.is_some_and(|p| p.provably_impure(sym))
    }

    /// Whether a **catalog-backed** is-a verdict used for arm deletion must be
    /// demoted to `Unknown` (ADR-0052 A11): the project PHP minor is known and
    /// differs from the catalog pin. When the minor is unknown or matches, catalog
    /// verdicts stand.
    fn a11_demote_catalog(&self) -> bool {
        self.catalog_skew
    }

    fn tree(&self) -> &'a SourceTree {
        self.units[self.cur].tree
    }
    fn path(&self) -> &'a str {
        self.units[self.cur].path
    }
    fn strict(&self) -> bool {
        self.tree().has_strict_types()
    }

    fn fn_decl(&self, site: Site) -> &'a FunctionDecl {
        &self.units[site.file].tree.functions()[site.index]
    }
    fn class_decl(&self, site: Site) -> (usize, &'a ClassDecl) {
        (site.file, &self.units[site.file].tree.classes()[site.index])
    }

    /// Resolve a class reference (in the current file's context) to its FQN.
    fn class_fqn(&self, r: &NameRef) -> String {
        self.tree().resolve_class_fqn(r)
    }

    /// Whether `fqn` names **no** project class at all. Stricter than
    /// `find_class(..).is_none()`, which also answers "none" for an *ambiguous*
    /// name (two project declarations): that is a project class Steins merely
    /// cannot pick, not an absent one, and the builtin-class catalog must not
    /// speak over it (issue #67 precedence).
    fn class_absent(&self, fqn: &str) -> bool {
        matches!(self.index.resolve_class(fqn), Res::Absent)
    }

    /// Find a class by FQN (case-insensitive), returning its file and decl.
    fn find_class(&self, fqn: &str) -> Option<(usize, &'a ClassDecl)> {
        match self.index.resolve_class(fqn) {
            Res::Unique(site) => Some(self.class_decl(site)),
            _ => None,
        }
    }

    /// The source-cased, namespace-qualified display form of a class FQN (the
    /// spelling diagnostics use, matching PHPStan — no leading `\`). A project class
    /// contributes its declared casing ([`ClassDecl::display`]); a name **no**
    /// project file declares ([`Cx::class_absent`] — so an ambiguous project name
    /// keeps issue #67 precedence and never reads the catalog) recovers the casing
    /// php-src declares from the builtin display-name table
    /// ([`steins_catalog::builtin_class_display`]): `dumpType(gmp_init($x))` reads
    /// `GMP`, as PHPStan does. Anything still unresolved falls back to the given
    /// key with any leading `\` stripped. Drives the dump surface's class rendering
    /// (ADR-0053 §7 / the class rendering-fidelity fix; builtin casing closes the
    /// ADR-0069 third-amendment residual).
    fn class_display_fqn(&self, fqn: &str) -> String {
        match self.find_class(fqn) {
            Some((_, cd)) if !cd.display.is_empty() => cd.display.clone(),
            _ => {
                if self.class_absent(fqn)
                    && let Some(declared) = steins_catalog::builtin_class_display(fqn)
                {
                    return declared.to_owned();
                }
                fqn.trim_start_matches('\\').to_owned()
            }
        }
    }

    /// Whether a `$this` seeded from enclosing class `class_fqn` is provably the
    /// **exact** runtime class (audit G1). A `final` class or an enum has no
    /// subclass, so its `$this` is exact; any other project class is only a lower
    /// bound (some subclass instance may be running the method). A class the index
    /// cannot uniquely resolve is conservatively *not* exact.
    fn this_class_exact(&self, class_fqn: &str) -> bool {
        self.find_class(class_fqn).is_some_and(|(_, cd)| cd.is_final || cd.is_enum)
    }

    /// The FQN of `class_fqn`'s parent, resolved in the parent's own file ctx.
    fn parent_fqn(&self, class_fqn: &str) -> Option<String> {
        let (file, cd) = self.find_class(class_fqn)?;
        let pref = cd.parent.as_ref()?;
        Some(self.units[file].tree.resolve_class_fqn(pref))
    }

    /// The non-static properties of `class_fqn` including inherited ones (ADR-0036),
    /// walking the parent chain; a derived-class declaration shadows an ancestor's
    /// property of the same name (first-seen wins, own class first). Static
    /// properties are excluded (never heap-tracked). Stops at an unknown/absent
    /// parent or a trait-using class (give up → the props gathered so far).
    fn class_props(&self, class_fqn: &str) -> Vec<&'a PropertyDecl> {
        let mut out: Vec<&'a PropertyDecl> = Vec::new();
        let mut seen: HashSet<String> = HashSet::new();
        let mut cur = class_fqn.to_owned();
        let mut chain_seen: HashSet<String> = HashSet::new();
        loop {
            if !chain_seen.insert(cur.to_ascii_lowercase()) {
                break;
            }
            let Some((file, cd)) = self.find_class(&cur) else { break };
            for p in &cd.properties {
                if p.is_static {
                    continue;
                }
                if seen.insert(p.name.to_ascii_lowercase()) {
                    out.push(p);
                }
            }
            match &cd.parent {
                Some(pref) => cur = self.units[file].tree.resolve_class_fqn(pref),
                None => break,
            }
        }
        out
    }

    /// The `__construct` method resolved through `class_fqn`'s chain (ADR-0036),
    /// for mapping `new` args to promoted-property positions.
    fn find_ctor(&self, class_fqn: &str) -> Option<&'a MethodDecl> {
        let mut cur = class_fqn.to_owned();
        let mut seen: HashSet<String> = HashSet::new();
        loop {
            if !seen.insert(cur.to_ascii_lowercase()) {
                return None;
            }
            let (file, cd) = self.find_class(&cur)?;
            if let Some(m) = cd.methods.iter().find(|m| m.is_constructor) {
                return Some(m);
            }
            cur = self.units[file].tree.resolve_class_fqn(cd.parent.as_ref()?);
        }
    }

    /// Infer the class-level generic type-argument VALUES a `new Class(args)`
    /// expression carries (ADR-0032 tier 1 propagation feeding tier 3 carry,
    /// issue #10). For each class-level `@template` (declaration order) that binds
    /// to a DIRECT top-level `@param T $p` constructor parameter, the matching
    /// positional argument's resolved value becomes that template's carried value.
    ///
    /// Deliberately **not a solver** (ADR-0030/0032 "won't build"): a template is
    /// bound only from a *bare* `@param T` occurrence at a constructor parameter; a
    /// nested or compound occurrence (`@param array<T>`, `@param T|null`) does not
    /// bind it. The result is **all-or-nothing**: one carried value per template
    /// only when EVERY template resolved to a proven value at an aligned positional
    /// argument; any gap (a template with no direct parameter, a missing/unprovable
    /// argument, a variadic in the way) returns EMPTY. An empty carry is the honest
    /// floor — downstream acceptance answers `Maybe` on the argument half, never a
    /// manufactured `No`, and the positional args↔templates alignment stays sound.
    ///
    /// ADR-0048: this is a pure function of the already-seeded `new` argument trace
    /// (§2 replayable from the scope walk), touches no scope entry state (§3), and
    /// carries no global-ordering dependence (§4).
    fn infer_generic_args(
        &self,
        class_fqn: &str,
        args: &[ArgValue],
        env: &HashMap<String, Known>,
        store: &Store,
        poisoned: bool,
        folder: &mut dyn Folder,
    ) -> Vec<CVal> {
        let empty = Vec::new();
        let Some((_, cd)) = self.find_class(class_fqn) else { return empty };
        let templates: Vec<String> = cd
            .docblock
            .as_deref()
            .map(steins_phpdoc::scan_template_names)
            .unwrap_or_default()
            .iter()
            .map(|t| t.to_ascii_lowercase())
            .collect();
        if templates.is_empty() {
            return empty; // not a generic class — no carry.
        }
        let Some(ctor) = self.find_ctor(class_fqn) else { return empty };
        // The constructor's own `@param` envelopes, WITHOUT the class-level template
        // shadow applied: a bare `@param T` must stay readable as the template name
        // `T` here (the shadow that neutralizes it to opaque is a check-site concern).
        let Some(ctor_env) = parse_envelopes(ctor.docblock.as_deref()) else { return empty };
        let mut out = Vec::with_capacity(templates.len());
        for tmpl in &templates {
            // The single constructor parameter whose `@param` is exactly this
            // template name (a direct, top-level occurrence — no solver).
            let Some(pos) = ctor.params.iter().position(|p| {
                ctor_env.param(&p.name).is_some_and(|pty| {
                    matches!(&pty.kind, PKind::Identifier(n) if n.eq_ignore_ascii_case(tmpl))
                })
            }) else {
                return empty;
            };
            if ctor.params[pos].variadic {
                return empty; // a variadic element breaks positional alignment.
            }
            let Some(arg) = args.get(pos) else { return empty };
            let Some(cv) = self.resolve_cval(arg, env, store, poisoned, folder) else {
                return empty;
            };
            out.push(cv);
        }
        out
    }

    /// Resolve a **function** call reference per PHP name resolution (ADR-0001).
    fn resolve_function(&self, r: &NameRef) -> FnResolution {
        self.resolve_function_with(r, &|n| steins_catalog::effect_labels(n).is_some())
    }

    /// [`Self::resolve_function`] with the **effects pass's** wider notion of a
    /// known builtin: a name carrying a by-ref out-parameter row
    /// ([`steins_catalog::out_params`]) is catalogued too, even when it has no
    /// unconditional color and is not foldable — `preg_match` and `sort` are
    /// exactly that, and P2 is what gives them something to say.
    ///
    /// Scoped to the effects pass on purpose. The same widening would also change
    /// how the *throws* pass classifies these names (from an unresolved taint to
    /// a `builtin_throws` consultation) — a real gap, but a different pass's
    /// accounting, left untouched here.
    fn resolve_effect_function(&self, r: &NameRef) -> FnResolution {
        self.resolve_function_with(r, &|n| {
            steins_catalog::effect_labels(n).is_some() || steins_catalog::out_params(n).is_some()
        })
    }

    /// [`Self::resolve_function`] with the **ADR-0070** notion of a known
    /// builtin: a name whose *argument semantics* the catalog can state
    /// ([`steins_catalog::by_value_arg`], three-valued — a `None` there is
    /// exactly "the catalog does not know this name"). That is a different
    /// question from having an effect color or a by-ref row, and either alone
    /// would be the wrong widening: `trim` has no out-param row and is still
    /// fully described, `sscanf` has neither and must stay unknown.
    ///
    /// Scoped to the call-argument survival gate, in the same spirit as
    /// [`Self::resolve_effect_function`]'s scoping: no other pass's baseline
    /// moves behind its back.
    fn resolve_arg_function(&self, r: &NameRef) -> FnResolution {
        self.resolve_function_with(r, &|n| steins_catalog::by_value_arg(n, 0).is_some())
    }

    fn resolve_function_with(
        &self,
        r: &NameRef,
        catalog_knows: &dyn Fn(&str) -> bool,
    ) -> FnResolution {
        match r.kind {
            RefKind::FullyQualified => {
                let fqn = r.raw.to_ascii_lowercase();
                match self.index.resolve_function(&fqn) {
                    Res::Unique(site) => FnResolution::User(site),
                    Res::Ambiguous => FnResolution::Unknown,
                    Res::Absent => {
                        // `\strlen` — a single-segment global name may be a builtin.
                        if !r.raw.contains('\\') && catalog_knows(&r.raw) {
                            FnResolution::Builtin
                        } else {
                            FnResolution::Unknown
                        }
                    }
                }
            }
            RefKind::Qualified => {
                // First segment via class/namespace imports, else current ns.
                let ctx = self.tree().ctx_at(r.offset);
                let first_len = r.raw.find('\\').unwrap_or(r.raw.len());
                let first = &r.raw[..first_len];
                let fqn = if let Some(t) = ctx.class_imports.get(&first.to_ascii_lowercase()) {
                    format!("{t}{}", &r.raw[first_len..])
                } else if ctx.namespace.is_empty() {
                    r.raw.clone()
                } else {
                    format!("{}\\{}", ctx.namespace, r.raw)
                };
                match self.index.resolve_function(&fqn) {
                    Res::Unique(site) => FnResolution::User(site),
                    _ => FnResolution::Unknown,
                }
            }
            RefKind::Unqualified => {
                let ctx = self.tree().ctx_at(r.offset);
                let name = r.raw.to_ascii_lowercase();
                // `use function` import wins outright.
                if let Some(t) = ctx.fn_imports.get(&name) {
                    return match self.index.resolve_function(&t.to_ascii_lowercase()) {
                        Res::Unique(site) => FnResolution::User(site),
                        _ => FnResolution::Unknown,
                    };
                }
                let is_builtin = catalog_knows(&name);
                // PHP tries NS\name first (when in a namespace).
                if !ctx.namespace.is_empty() {
                    let ns_fqn = format!("{}\\{}", ctx.namespace, name);
                    match self.index.resolve_function(&ns_fqn) {
                        Res::Unique(site) => return FnResolution::User(site),
                        Res::Ambiguous => return FnResolution::Unknown,
                        Res::Absent => {}
                    }
                }
                // Global fallback (also the whole story in the global namespace).
                match self.index.resolve_function(&name) {
                    Res::Ambiguous => FnResolution::Unknown,
                    Res::Unique(site) => {
                        // A user global that shadows a builtin name is ambiguous.
                        if is_builtin { FnResolution::Unknown } else { FnResolution::User(site) }
                    }
                    Res::Absent => {
                        if is_builtin { FnResolution::Builtin } else { FnResolution::Unknown }
                    }
                }
            }
            // ADR-0049 A8: `namespace\name` — resolves against the enclosing namespace
            // ONLY, with no `use` imports and no global fallback (an undefined `Ns\name`
            // is a fatal error, never a fall-through to a global builtin). In the global
            // namespace the candidate is `name` itself, where a catalog builtin applies.
            RefKind::Relative => {
                let ctx = self.tree().ctx_at(r.offset);
                let name = r.raw.to_ascii_lowercase();
                if ctx.namespace.is_empty() {
                    match self.index.resolve_function(&name) {
                        Res::Ambiguous => FnResolution::Unknown,
                        Res::Unique(site) => {
                            if catalog_knows(&name) { FnResolution::Unknown } else { FnResolution::User(site) }
                        }
                        Res::Absent => {
                            if catalog_knows(&name) { FnResolution::Builtin } else { FnResolution::Unknown }
                        }
                    }
                } else {
                    let fqn = format!("{}\\{}", ctx.namespace.to_ascii_lowercase(), name);
                    match self.index.resolve_function(&fqn) {
                        Res::Unique(site) => FnResolution::User(site),
                        _ => FnResolution::Unknown,
                    }
                }
            }
        }
    }

    /// The site of a **user** function this call resolves to (positional-only),
    /// or `None` for builtins / unknown / dynamic / named-arg calls.
    fn resolve_user_fn(&self, call: &CallExpr) -> Option<Site> {
        if !call.positional_only {
            return None;
        }
        self.resolve_user_fn_any(call)
    }

    /// Resolve the call's user-function target **without** the positional-only guard
    /// (Gap A). The argument-contract lanes bind named arguments by name and check the
    /// positional prefix of a mixed call, so they must resolve a non-positional call;
    /// the binding descent still routes through [`Self::resolve_user_fn`], whose guard
    /// keeps the positional-mapping descent off named/spread calls.
    fn resolve_user_fn_any(&self, call: &CallExpr) -> Option<Site> {
        let r = call.callee_ref.as_ref()?;
        match self.resolve_function(r) {
            FnResolution::User(site) => Some(site),
            _ => None,
        }
    }

    /// The unique body scope of the user function at `site`, plus its file.
    fn fn_scope(&self, site: Site) -> Option<(usize, &'a Scope)> {
        let name = &self.fn_decl(site).name;
        let tree = self.units[site.file].tree;
        let mut it = tree.scopes().iter().filter(|s| s.function_name.as_deref() == Some(name));
        let scope = it.next()?;
        if it.next().is_some() { None } else { Some((site.file, scope)) }
    }

    /// The unique method body scope for `class_fqn::method` in `file`.
    fn method_scope(&self, file: usize, class_fqn: &str, method: &str) -> Option<&'a Scope> {
        let tree = self.units[file].tree;
        let mut it = tree.scopes().iter().filter(|s| {
            matches!(&s.owner, ScopeOwner::Method { class: c, method: m }
                if c.eq_ignore_ascii_case(class_fqn) && m.eq_ignore_ascii_case(method))
        });
        let scope = it.next()?;
        if it.next().is_some() { None } else { Some(scope) }
    }

    /// The closure/arrow body scope defined at `def_offset` in this file (ADR-0033),
    /// for descent through a proven `$fn()` closure value.
    fn closure_scope(&self, def_offset: u32) -> Option<&'a Scope> {
        self.tree().scopes().iter().find(|s| {
            matches!(&s.owner, ScopeOwner::Closure { def_offset: d } if *d == def_offset)
        })
    }

    /// A display name for an effect [`Sym`] (`f`, `Foo::bar`), using the resolved
    /// declaration's written case where available.
    fn sym_display(&self, sym: &Sym) -> String {
        match sym {
            Sym::Func(fqn) => match self.index.resolve_function(fqn) {
                Res::Unique(site) => self.fn_decl(site).name.clone(),
                _ => fqn.clone(),
            },
            Sym::Method(cfqn, m) => match self.find_class(cfqn) {
                Some((_, cd)) => format!("{}::{}", cd.name, m),
                None => format!("{cfqn}::{m}"),
            },
            Sym::Closure(_, off) => {
                let line = self.tree().position(*off).line;
                format!("closure (line {line})")
            }
        }
    }

    /// Resolve an [`ArgValue`] to a concrete literal, if provable.
    ///
    /// Equivalent to [`Self::resolve_literal_under`] with no live descent — the
    /// common call sites (assignment, dump, property checks) that are not mid-
    /// binding. Project-call arguments of foldable builtins still resolve via a
    /// fresh descent tree (issue #127); live-descent callers must use
    /// [`Self::resolve_literal_under`] so the on-stack guard is threaded.
    ///
    /// The second return is the trust stratum of the resolved value (ADR-0052 §5):
    /// a fold that consumed an Asserted project-call summary stays Asserted, so
    /// it cannot launder into a proof-layer premise.
    fn resolve_literal(
        &self,
        value: &ArgValue,
        env: &HashMap<String, Known>,
        poisoned: bool,
        folder: &mut dyn Folder,
    ) -> Option<ArgValue> {
        self.resolve_literal_under(value, env, poisoned, folder, None, None)
            .map(|(v, _)| v)
    }

    /// Like [`Self::resolve_literal`], but also returns the trust stratum of the
    /// resolved value (issue #127: fold-arg Asserted must not launder).
    fn resolve_literal_strat(
        &self,
        value: &ArgValue,
        env: &HashMap<String, Known>,
        poisoned: bool,
        folder: &mut dyn Folder,
    ) -> Option<(ArgValue, Stratum)> {
        self.resolve_literal_under(value, env, poisoned, folder, None, None)
    }

    /// [`Self::resolve_literal_strat`] with optional live descent and findings sink
    /// (issue #127). Nested project-call descents for fold args emit through `out`
    /// when provided so binding-specific diagnostics are not discarded.
    fn resolve_literal_strat_ex(
        &self,
        value: &ArgValue,
        env: &HashMap<String, Known>,
        poisoned: bool,
        folder: &mut dyn Folder,
        descent: Option<&mut Descent<'_>>,
        out: Option<&mut Vec<Diagnostic>>,
    ) -> Option<(ArgValue, Stratum)> {
        self.resolve_literal_under(value, env, poisoned, folder, descent, out)
    }

    /// [`Self::resolve_literal`] with an optional live [`Descent`] and findings sink
    /// (issue #127). Returns `(value, stratum)`: for a fold, stratum is `min` over
    /// the resolved fold arguments (including a nested project-call summary's
    /// stratum).
    fn resolve_literal_under(
        &self,
        value: &ArgValue,
        env: &HashMap<String, Known>,
        poisoned: bool,
        folder: &mut dyn Folder,
        mut descent: Option<&mut Descent<'_>>,
        mut out: Option<&mut Vec<Diagnostic>>,
    ) -> Option<(ArgValue, Stratum)> {
        if poisoned {
            return None;
        }
        match value {
            v if v.is_literal() => Some((v.clone(), Stratum::Verified)),
            ArgValue::Var(name) => {
                let k = env.get(name)?;
                Some((k.singleton()?, k.stratum))
            }
            ArgValue::Call(name, args) => {
                if args.is_empty()
                    && let Some((lit, _line)) = self.resolve_const_fn(name)
                {
                    return Some((lit, Stratum::Verified));
                }
                // Builtin fold (allowlist + project-shadow gate). Project-call
                // arguments of the fold are resolved inside `try_fold_under`
                // (issue #127). A bare project call (`g(1)` as a value) is *not*
                // resolved here — that stays the caller's job (`nested_call_singleton`
                // / `project_call_summary`) so findings still emit on the live `out`.
                self.try_fold_under(name, args, env, poisoned, folder, descent, out)
                    .map(|(lit, _prov, strat)| (lit, strat))
            }
            // `$a . $b` (issue #59): proven iff BOTH operands resolve to values whose
            // string cast is total and environment-independent (`concat_cast`). One
            // unresolved operand yields `None` — the same silence as any other
            // unprovable value, never a partial string.
            ArgValue::Concat(a, b) => {
                let (l, sl) = self.resolve_literal_under(
                    a, env, poisoned, folder, descent.as_deref_mut(), out.as_deref_mut(),
                )?;
                let (r, sr) = self.resolve_literal_under(
                    b, env, poisoned, folder, descent.as_deref_mut(), out.as_deref_mut(),
                )?;
                Some((ArgValue::Str(concat_cast(&l)? + &concat_cast(&r)?), sl.min(sr)))
            }
            // An array is proven iff every element value is proven (keys are fixed
            // at lowering). Folding is never applied to arrays (ADR-0001).
            ArgValue::Array(items) => {
                let mut resolved = Vec::with_capacity(items.len());
                let mut strat = Stratum::Verified;
                for (k, v) in items {
                    let (rv, s) = self.resolve_literal_under(
                        v, env, poisoned, folder, descent.as_deref_mut(), out.as_deref_mut(),
                    )?;
                    strat = strat.min(s);
                    resolved.push((k.clone(), rv));
                }
                Some((ArgValue::Array(resolved), strat))
            }
            _ => None,
        }
    }

    /// Try to fold an allowlisted builtin call over **proven** arguments.
    ///
    /// # The env-resolved argument (ADR-0062 S7, the §1 fold gap)
    ///
    /// Each argument is first rendered as the value it provably *is*, through
    /// [`Self::resolve_literal`]: a bare `$a` bound to a proven value becomes that
    /// value, an array literal with a proven element becomes the concrete array,
    /// a nested foldable call becomes its folded result. An argument that does not
    /// resolve is left **exactly as written**, so the gate below judges it the way
    /// it always did — resolution can only ever add arguments to the fold, never
    /// remove one (a literal resolves to itself, and a poisoned scope resolves
    /// nothing at all).
    ///
    /// This is what closes ADR-0062 §1's measured gap: `$a = ['x', 'y'];
    /// count($a)` now folds to `2` exactly as the written `count(['x', 'y'])`
    /// does. **Nothing about the allowlist or the purity discipline changed** —
    /// the fold still runs on the project's own PHP (ADR-0004/0028), so every
    /// order-dependent builtin the allowlist admits (`in_array`, `implode`,
    /// `count`) is answered by the real engine over the real, order-witnessed
    /// array (ADR-0062 §2's value lane), never by a re-derivation here.
    ///
    /// # Project-call arguments (issue #127)
    ///
    /// A foldable arg that is itself a project call (`strtoupper(g(1))`) resolves
    /// through the T0 summary under the same descent guard as a nested binding —
    /// see [`Self::resolve_literal_under`]. Budget exhaustion widens (the gate
    /// declines); it never partially folds. The result stratum is `min` over the
    /// resolved arguments (including a nested summary's Asserted stratum), so an
    /// Asserted project-call premise cannot launder into a Verified fold.
    ///
    /// Provenance names the *resolved* call — the call that actually ran.
    /// Returns `(folded, provenance, stratum)`.
    fn try_fold(
        &self,
        name: &str,
        args: &[ArgValue],
        env: &HashMap<String, Known>,
        poisoned: bool,
        folder: &mut dyn Folder,
    ) -> Option<(ArgValue, String, Stratum)> {
        self.try_fold_under(name, args, env, poisoned, folder, None, None)
    }

    /// Like [`Self::try_fold`], threading a findings sink so nested project-call
    /// descents for fold arguments emit binding-specific diagnostics (issue #127).
    fn try_fold_emit(
        &self,
        name: &str,
        args: &[ArgValue],
        env: &HashMap<String, Known>,
        poisoned: bool,
        folder: &mut dyn Folder,
        out: &mut Vec<Diagnostic>,
    ) -> Option<(ArgValue, String, Stratum)> {
        self.try_fold_under(name, args, env, poisoned, folder, None, Some(out))
    }

    /// [`Self::try_fold`] with optional live [`Descent`] and findings sink (issue #127).
    #[allow(clippy::too_many_arguments)]
    fn try_fold_under(
        &self,
        name: &str,
        args: &[ArgValue],
        env: &HashMap<String, Known>,
        poisoned: bool,
        folder: &mut dyn Folder,
        mut descent: Option<&mut Descent<'_>>,
        mut out: Option<&mut Vec<Diagnostic>>,
    ) -> Option<(ArgValue, String, Stratum)> {
        // Any project user function sharing this simple name shadows the builtin
        // (or makes it ambiguous) — do not fold. Conservative, never an FP.
        if self.index.has_simple_function(name) {
            return None;
        }
        if !steins_catalog::foldable(name) {
            return None;
        }
        let mut resolved = Vec::with_capacity(args.len());
        let mut arg_strat = Stratum::Verified;
        // When no external sink is provided (dump surface, pure resolution), use a
        // scratch so nested descents stay silent. Walk/check paths pass a real
        // `out` so binding-specific findings under `g(1)` in `strtoupper(g(1))`
        // are not discarded (issue #127 review).
        let mut scratch: Vec<Diagnostic> = Vec::new();
        for a in args {
            // Resolve under the live descent so a project-call arg's summary
            // reuses the on-stack guard (issue #127). `resolve_literal_under`
            // covers literals / env / nested folds; a project call that is not
            // itself foldable is answered by `nested_call_singleton`.
            let (r, s) = if let Some((v, s)) = self.resolve_literal_under(
                a,
                env,
                poisoned,
                folder,
                descent.as_deref_mut(),
                out.as_deref_mut(),
            ) {
                (v, s)
            } else if let Some((v, s)) = {
                let sink: &mut Vec<Diagnostic> = match out.as_deref_mut() {
                    Some(o) => o,
                    None => &mut scratch,
                };
                nested_call_singleton(
                    self,
                    folder,
                    a,
                    env,
                    poisoned,
                    0,
                    descent.as_deref_mut(),
                    sink,
                )
            } {
                (v, s)
            } else {
                // Unresolved: keep the written form for the gate, stratum from
                // the syntactic arm (env/prop reads only — no summary).
                (a.clone(), value_stratum(a, env, None))
            };
            arg_strat = arg_strat.min(s);
            resolved.push(r);
        }
        // Every argument must be a self-evident value: a scalar literal, or an
        // array literal that is concrete all the way down and inside the fold
        // budget (issue #39). This is the gate the `count`/`in_array`/`implode`
        // entries were parked behind — nothing about the allowlist changed, the
        // arguments they take simply became representable. Checked BEFORE
        // `folder.fold`, so an over-budget literal is never cloned into the memo.
        if !resolved.iter().all(is_fold_arg) {
            return None;
        }
        let folded = folder.fold(name, &resolved)?;
        Some((folded, format!("folded from {}", render_call(name, &resolved)), arg_strat))
    }

    /// Fold an allowlisted builtin over a **bounded union of constant arguments**,
    /// composing the members' answers into one value fact (issue #74).
    ///
    /// # Why this rung exists
    ///
    /// PHPStan's dynamic return extensions accept a constant *or a union of
    /// constants*, call the real function once per member and compose the results.
    /// ADR-0069's amendment tabulates Steins' return ladder against that stack and
    /// names the union of constants as the one condition the fold lane could not
    /// meet: [`Self::try_fold`] admits a single constant tuple, so `$x = $c ? 'a' :
    /// 'b'; strtoupper($x)` widened where PHPStan answers `'A'|'B'`. This closes it.
    ///
    /// # The resolution ladder, per argument
    ///
    /// 1. whatever [`Self::resolve_literal`] proves — a written literal, a
    ///    `Singleton` env fact, a nested fold, a proven concatenation or array;
    /// 2. failing that, a `Fact::OneOf` env fact **every** member of which converts
    ///    to a foldable argument.
    ///
    /// An argument that resolves to neither declines the whole fold — the existing
    /// silence, reached one rung later. A `Singleton` is simply the one-member case
    /// of the same ladder, which is what makes `intdiv($u, 2)` work: the literal
    /// lane and the union lane compose in the product.
    ///
    /// # The bounds, and why busting one declines
    ///
    /// At most [`UNION_FOLD_MEMBER_CAP`] members per argument and
    /// [`UNION_FOLD_COMBINATION_CAP`] combinations in total. Over either bound the
    /// fold **declines**; it never truncates. A union missing a member is a *wrong*
    /// value domain, not a wider one — the analyzer would claim `'A'|'B'` for a
    /// value that can also be `'C'`, which is the one thing ADR-0002 forbids.
    ///
    /// # Every combination is an ordinary fold
    ///
    /// Each member tuple goes back through [`Self::try_fold`] — the same seam a
    /// literal call takes — so the name gates, the per-argument fold budget, the
    /// `(name, args)` memo, the issue-#64 integer-width gate with its argument
    /// range guard, and (in the browser) the ADR-0066 replay loop all apply
    /// unchanged and un-duplicated. A member that widens or throws answers `None`,
    /// and the whole fold declines with it: a union that quietly drops its throwing
    /// member is the same wrong domain the cap refuses to mint. (Treating a
    /// *uniform* throw as a proven throw is a separate inference question.) Every
    /// combination is nonetheless *asked* before the decline is returned, so a
    /// replay transport learns the whole batch in one round trip.
    ///
    /// # Replayability (ADR-0028 / ADR-0048)
    ///
    /// The enumeration is a pure function of (CST, entry state, fold memo): the
    /// arguments are in source order and a `Fact::OneOf` is canonically sorted, so
    /// the product is walked in one fixed order with no map iteration anywhere.
    ///
    /// Returns the composed fact, its stratum, and a provenance string.
    fn try_union_fold(
        &self,
        name: &str,
        args: &[ArgValue],
        env: &HashMap<String, Known>,
        poisoned: bool,
        folder: &mut dyn Folder,
    ) -> Option<(Fact, Stratum, String)> {
        if poisoned || args.is_empty() {
            return None;
        }
        // The two name gates `try_fold` opens with, asked before any enumeration so
        // a shadowed or non-allowlisted name costs nothing at all.
        if self.index.has_simple_function(name) || !steins_catalog::foldable(name) {
            return None;
        }
        let mut lanes: Vec<Vec<ArgValue>> = Vec::with_capacity(args.len());
        let mut combinations: usize = 1;
        for arg in args {
            let members: Vec<ArgValue> = match self.resolve_literal(arg, env, poisoned, folder) {
                Some(lit) => vec![lit],
                None => {
                    let ArgValue::Var(var) = arg else { return None };
                    let Some(Fact::OneOf(vals)) = env.get(var).and_then(|k| k.fact.as_ref()) else {
                        return None;
                    };
                    if vals.len() > UNION_FOLD_MEMBER_CAP {
                        return None;
                    }
                    vals.iter().map(arg_of_val).collect()
                }
            };
            // The gate `try_fold` applies per call, applied here per member: a
            // member that is not a self-evident value (or busts the array budget)
            // takes the whole fold down rather than being quietly dropped.
            if !members.iter().all(is_fold_arg) {
                return None;
            }
            combinations = combinations.checked_mul(members.len())?;
            if combinations > UNION_FOLD_COMBINATION_CAP {
                return None;
            }
            lanes.push(members);
        }
        // One combination is the plain fold, and `resolve_literal` already owns it
        // (this rung is only ever reached after that one declined).
        if combinations < 2 {
            return None;
        }
        // The bounded cartesian product, last argument varying fastest.
        //
        // EVERY combination is asked, even once one has declined. The verdict is
        // unaffected — one declining member declines the whole fold — but the
        // browser's replay transport (ADR-0066) collects a *batch* of unanswered
        // requests per iteration, so asking them all in one pass is the difference
        // between one round trip and one per member. On the native transport the
        // extra questions are bounded by the combination cap and memoized.
        let mut vals: Vec<Val> = Vec::with_capacity(combinations);
        let mut declined = false;
        let mut odometer = vec![0usize; lanes.len()];
        for _ in 0..combinations {
            let combo: Vec<ArgValue> =
                lanes.iter().zip(&odometer).map(|(lane, i)| lane[*i].clone()).collect();
            match self
                .try_fold(name, &combo, env, poisoned, folder)
                .and_then(|(folded, _, _)| val_of(&folded, self.php_minor))
            {
                Some(v) => vals.push(v),
                None => declined = true,
            }
            for k in (0..odometer.len()).rev() {
                odometer[k] += 1;
                if odometer[k] < lanes[k].len() {
                    break;
                }
                odometer[k] = 0;
            }
        }
        if declined {
            return None;
        }
        // `Fact::from_vals` is the narrowing lanes' own composition: deduped and
        // sorted, a `Singleton` when every member agreed, a `OneOf` up to the
        // domain's own CAP, and past that the *computed* widening — sound, and the
        // same summary any other value set would get.
        let fact = Fact::from_vals(vals)?;
        // Stratum (ADR-0048 N2 / ADR-0052 §5's derivation clause): each member
        // answer is engine-`Verified`, but the INPUT union carries its own trust,
        // and the composed fact consumed all of them — `min` over the arguments.
        // An `Asserted` union in, an `Asserted` result out.
        let stratum =
            args.iter().fold(Stratum::Verified, |acc, a| acc.min(value_stratum(a, env, None)));
        Some((fact, stratum, format!("folded from {name}() over {combinations} argument combinations")))
    }

    /// Resolve a zero-argument constant function anywhere in the project by its
    /// simple name: unique definition, no params, body exactly `return <lit>`,
    /// scope not poisoned. Returns the literal and the definition line.
    fn resolve_const_fn(&self, name: &str) -> Option<(ArgValue, u32)> {
        let site = self.index.unique_fn_by_simple(name)?;
        let decl = self.fn_decl(site);
        if !decl.params.is_empty() {
            return None;
        }
        let tree = self.units[site.file].tree;
        let mut scopes = tree.scopes().iter().filter(|s| s.function_name.as_deref() == Some(&decl.name));
        let scope = scopes.next()?;
        if scopes.next().is_some() || scope.poisoned {
            return None;
        }
        let [stmt] = scope.stmts.as_slice() else { return None };
        let StmtKind::Return { value, .. } = &stmt.kind else { return None };
        if !value.is_literal() {
            return None;
        }
        Some((value.clone(), tree.position(decl.span.start).line))
    }

    /// Build a `type.argument-mismatch` diagnostic (path/line from the current
    /// file — where the call textually is).
    fn diagnostic(
        &self,
        offset: u32,
        value: &ArgValue,
        provenance: Option<&str>,
        callee: &str,
        param_name: &str,
        ty: &NativeType,
    ) -> Diagnostic {
        let pos = self.tree().position(offset);
        let mode = if self.strict() { "strict" } else { "coercive" };
        let message = match provenance {
            Some(p) => format!(
                "argument {} ({}) to {}() cannot become {} ${} — proven TypeError ({} mode)",
                value.render(), p, callee, ty.render(), param_name, mode,
            ),
            None => format!(
                "argument {} to {}() cannot become {} ${} — proven TypeError ({} mode)",
                value.render(), callee, ty.render(), param_name, mode,
            ),
        };
        Diagnostic { id: ID, path: self.path().to_owned(), line: pos.line, column: pos.column, message, facet: None, fix: None }
    }

    /// Build a `type.return-mismatch` diagnostic. `display` is the owning
    /// function/method name (`f`, `Foo::bar`); `mode` is governed by the owning
    /// file's `declare(strict_types=1)` — the file this `Cx` points at.
    fn return_diagnostic(
        &self,
        offset: u32,
        value: &ArgValue,
        ret: &NativeType,
        display: &str,
    ) -> Diagnostic {
        let pos = self.tree().position(offset);
        let mode = if self.strict() { "strict" } else { "coercive" };
        let message = format!(
            "return {} cannot become {} (return type of {}()) — proven TypeError ({} mode)",
            value.render(),
            ret.render(),
            display,
            mode,
        );
        Diagnostic {
            id: RETURN_ID,
            path: self.path().to_owned(),
            line: pos.line,
            column: pos.column,
            message,
            facet: None,
            fix: None,
        }
    }

    /// The parameter list of a scope's owning function or method (same file this
    /// `Cx` points at), or `None` for the top-level script scope. Used by the
    /// native-type parameter seeding (Feature B).
    fn scope_params(&self, scope: &Scope) -> Option<&'a [Param]> {
        match &scope.owner {
            ScopeOwner::TopLevel => None,
            ScopeOwner::Function(name) => {
                let f = self.tree().functions().iter().find(|f| f.name.eq_ignore_ascii_case(name))?;
                Some(&f.params)
            }
            ScopeOwner::Method { class, method } => {
                let cd = self.tree().classes().iter().find(|c| c.fqn.eq_ignore_ascii_case(class))?;
                let m = cd.methods.iter().find(|m| m.name.eq_ignore_ascii_case(method))?;
                Some(&m.params)
            }
            // A closure/arrow scope carries its own params (no FunctionDecl). Look
            // the scope up in the tree so the borrow has the `'a` project lifetime.
            ScopeOwner::Closure { def_offset } => {
                let s = self.tree().scopes().iter().find(|s| {
                    matches!(&s.owner, ScopeOwner::Closure { def_offset: d } if d == def_offset)
                })?;
                Some(&s.params)
            }
        }
    }

    /// The parsed `@param`/`@return`/assert envelopes off the scope's owning
    /// declaration docblock (function or method), with class-level `@template`
    /// names shadowed for a method (issue #5), or `None` when there is no docblock
    /// / the scope is a closure or top-level. Used by contract-fact seeding
    /// (ADR-0052 §9) to refine the native member list with the declared `@param`.
    fn scope_envelopes(&self, scope: &Scope) -> Option<Envelopes> {
        match &scope.owner {
            // Closures: deliberately `None` even though the scope may carry an
            // adopted docblock (issue #128 lit up `@return` only, via
            // `scope_return_phpdoc`) — `@param`/`@throws` on closures stays dark.
            ScopeOwner::TopLevel | ScopeOwner::Closure { .. } => None,
            ScopeOwner::Function(name) => {
                let f = self.tree().functions().iter().find(|f| f.name.eq_ignore_ascii_case(name))?;
                parse_envelopes(f.docblock.as_deref())
            }
            ScopeOwner::Method { class, method } => {
                let cd = self.tree().classes().iter().find(|c| c.fqn.eq_ignore_ascii_case(class))?;
                let m = cd.methods.iter().find(|m| m.name.eq_ignore_ascii_case(method))?;
                let mut env = parse_envelopes(m.docblock.as_deref())?;
                env.shadow_templates(&template_names_of(cd.docblock.as_deref()));
                Some(env)
            }
        }
    }

    /// The `@template` shadow set in force over a scope's *body* (issue #5 applied
    /// to statement-level docblocks): the owning declaration's own template names
    /// plus, for a method, the enclosing class-level ones — the same two idempotent
    /// stages [`Cx::scope_envelopes`] applies to the declaration's envelopes. Empty
    /// for top-level and closure scopes (no owning docblock).
    fn scope_template_shadow(&self, scope: &Scope) -> HashSet<String> {
        match &scope.owner {
            ScopeOwner::TopLevel | ScopeOwner::Closure { .. } => HashSet::new(),
            ScopeOwner::Function(name) => self
                .tree()
                .functions()
                .iter()
                .find(|f| f.name.eq_ignore_ascii_case(name))
                .map_or_else(HashSet::new, |f| template_names_of(f.docblock.as_deref())),
            ScopeOwner::Method { class, method } => {
                let Some(cd) =
                    self.tree().classes().iter().find(|c| c.fqn.eq_ignore_ascii_case(class))
                else {
                    return HashSet::new();
                };
                let mut shadow = template_names_of(cd.docblock.as_deref());
                if let Some(m) = cd.methods.iter().find(|m| m.name.eq_ignore_ascii_case(method)) {
                    shadow.extend(template_names_of(m.docblock.as_deref()));
                }
                shadow
            }
        }
    }

    /// The native return type and display name of a scope's owning function,
    /// method, or closure (the same file this `Cx` points at), or `None` for the
    /// top-level script scope or an owner with no native scalar/union return type.
    fn scope_return(&self, scope: &'a Scope) -> Option<(&'a NativeType, String)> {
        // A generator's declared return type names the `Generator` object the
        // *call* yields, not the values of in-body `return` (those are
        // `Generator::getReturn()`). Checking body returns against `: Generator`
        // is a false positive (issue #128 review).
        if scope.is_generator {
            return None;
        }
        match &scope.owner {
            ScopeOwner::TopLevel => None,
            ScopeOwner::Function(name) => {
                let f =
                    self.tree().functions().iter().find(|f| f.name.eq_ignore_ascii_case(name))?;
                f.ret.as_ref().map(|r| (r, f.name.clone()))
            }
            ScopeOwner::Method { class, method } => {
                // `owner.class` is the case-preserved FQN; `ClassDecl.fqn` is
                // lowercase-normalized — compare case-insensitively.
                let cd =
                    self.tree().classes().iter().find(|c| c.fqn.eq_ignore_ascii_case(class))?;
                let m = cd.methods.iter().find(|m| m.name.eq_ignore_ascii_case(method))?;
                m.ret.as_ref().map(|r| (r, format!("{}::{}", cd.name, m.name)))
            }
            // Issue #128: closures carry their native `: R` on the scope itself
            // (`Scope::ret_ty`) — same check surface as free functions.
            ScopeOwner::Closure { .. } => {
                scope.ret_ty.as_ref().map(|r| (r, "closure".to_owned()))
            }
        }
    }

    /// The `@return` phpdoc envelope and display name of a scope's owning
    /// function, method, or closure (same file this `Cx` points at), or `None`
    /// when there is no docblock `@return` (or the scope is top-level).
    fn scope_return_phpdoc(&self, scope: &Scope) -> Option<(PType, String)> {
        // Scope-wide, mirroring [`Cx::scope_return`]'s native guard (issue #142):
        // a generator's declared return type names the `Generator` object the
        // *call* yields, not the values of in-body `return` (those are
        // `Generator::getReturn()`). Checking body returns against
        // `@return Generator` is a false positive (issue #128 review) — and the
        // phpdoc leg fires exactly where the native one stayed silent, so
        // guarding only the native side left the FP alive on every owner arm.
        if scope.is_generator {
            return None;
        }
        match &scope.owner {
            ScopeOwner::TopLevel => None,
            ScopeOwner::Function(name) => {
                let f =
                    self.tree().functions().iter().find(|f| f.name.eq_ignore_ascii_case(name))?;
                let ret = parse_envelopes(f.docblock.as_deref())?.ret?;
                Some((ret, f.name.clone()))
            }
            ScopeOwner::Method { class, method } => {
                let cd =
                    self.tree().classes().iter().find(|c| c.fqn.eq_ignore_ascii_case(class))?;
                let m = cd.methods.iter().find(|m| m.name.eq_ignore_ascii_case(method))?;
                let mut env = parse_envelopes(m.docblock.as_deref())?;
                // Class-level `@template` names shadow in this method's `@return` too
                // (issue #5) — the idempotent class-level stage.
                env.shadow_templates(&template_names_of(cd.docblock.as_deref()));
                let ret = env.ret?;
                Some((ret, format!("{}::{}", cd.name, m.name)))
            }
            // Issue #128: closures carry their adopted docblock on the scope
            // itself (`Scope::docblock`, two-position adoption in steins-syntax)
            // — same `parse_envelopes` grammar as free functions. No
            // enclosing-class `@template` shadowing here (known limitation — a
            // closure inside a templated class could misread a template name as
            // a class name).
            ScopeOwner::Closure { .. } => {
                let ret = parse_envelopes(scope.docblock.as_deref())?.ret?;
                Some((ret, "closure".to_owned()))
            }
        }
    }
}

// ---------------------------------------------------------------------------
// The env now stores the full four-layer `steins_domain::Fact` (ADR-0035) — the
// finished algebra lives in `steins-domain`; this crate only converts to/from
// the trace IR's `ArgValue` at the two seams below and calls the domain's joins,
// membership, and trinary queries. Stage-2 abstract facts (`Refined`/`General`)
// now flow through the env exactly like the finite layers: they resolve no
// *value* (only a `Singleton` does), but they carry knowledge for guard
// refinements (ADR-0031 stage 2), native-type seeding, and contract-on-fact
// acceptance (ADR-0030).
// ---------------------------------------------------------------------------

/// The domain value-fact (four layers), aliased as `Fact` throughout the walk.
use steins_domain::Fact;
use steins_domain::{
    Base, CoverFlavor, IntRange, Key as VKey, Refinement, ShapeFact, StrPreds, Val, php_is_numeric,
};

/// The conversion seam **into** the domain: a literal (or fully-literal array)
/// [`ArgValue`] to a domain [`Val`]. Array keys carry PHP key-normalization in
/// insertion order (reusing [`normalize_array`], matching [`VKey`]). Any
/// non-literal element (or a non-literal `ArgValue`) yields `None` — the fact is
/// dropped (the safe side).
fn val_of(arg: &ArgValue, php_minor: Option<(u16, u16)>) -> Option<Val> {
    match arg {
        ArgValue::Int(i) => Some(Val::Int(*i)),
        ArgValue::Float(f) => Some(Val::Float(*f)),
        ArgValue::Str(s) => Some(Val::Str(s.clone())),
        ArgValue::Bool(b) => Some(Val::Bool(*b)),
        ArgValue::Null => Some(Val::Null),
        ArgValue::Array(items) => {
            // An unknown minor over a literal straddling the 8.3 next-int change
            // yields `None` here (ADR-0049 A12) — the keys are unproven, so the
            // singleton fact is dropped rather than built on a guessed key.
            let normalized = normalize_array(items, php_minor)?;
            let mut out = Vec::with_capacity(normalized.len());
            for (k, v) in normalized {
                let key = match k {
                    NormKey::Int(i) => VKey::Int(i),
                    NormKey::Str(s) => VKey::Str(s),
                };
                out.push((key, val_of(&v, php_minor)?));
            }
            Some(Val::Array(out))
        }
        ArgValue::Var(_)
        | ArgValue::Call(..)
        | ArgValue::New(..)
        | ArgValue::Ternary { .. }
        | ArgValue::Coalesce(..)
        | ArgValue::Closure(_)
        | ArgValue::PropFetch { .. }
        | ArgValue::Clone(_)
        // An offset read is never a proven `Val` — the walk judges it separately
        // (ADR-0049 §7); it manufactures no fact here (the safe side).
        | ArgValue::OffsetRead { .. }
        // Like the carriers above, a concatenation is structural: it becomes a `Val`
        // only by way of `resolve_literal`, which needs the env this seam does not see.
        | ArgValue::Concat(..)
        // Object-world values (ADR-0043): not domain `Val`s — unproven, == Other.
        | ArgValue::ClassConst(..)
        | ArgValue::EnumCase(..)
        | ArgValue::Other => None,
    }
}

/// The conversion seam **out of** the domain: a concrete [`Val`] back to the
/// trace IR's [`ArgValue`]. Total (the domain's `Val` is exactly the concrete
/// subset of `ArgValue`), so proven-value consumers (native truth table, folding
/// args, descent binding) keep receiving an `ArgValue` as before.
fn arg_of_val(v: &Val) -> ArgValue {
    match v {
        Val::Int(i) => ArgValue::Int(*i),
        Val::Float(f) => ArgValue::Float(*f),
        Val::Str(s) => ArgValue::Str(s.clone()),
        Val::Bool(b) => ArgValue::Bool(*b),
        Val::Null => ArgValue::Null,
        Val::Array(items) => ArgValue::Array(
            items
                .iter()
                .map(|(k, v)| {
                    let key = match k {
                        VKey::Int(i) => ArrayKey::Int(*i),
                        VKey::Str(s) => ArrayKey::Str(s.clone()),
                    };
                    (key, arg_of_val(v))
                })
                .collect(),
        ),
    }
}

/// Render a domain [`Val`] for a message/margin **byte-for-byte** identically to
/// the existing [`ArgValue::render`] (float `5.0` form, `['a', 'b']` arrays,
/// double-quoted scalars) — it simply routes through the shared renderer, so a
/// `Singleton` fact renders exactly as its `ArgValue` always did.
fn render_val(v: &Val) -> String {
    arg_of_val(v).render()
}

/// A domain `Singleton` fact from a literal/array [`ArgValue`], or `None` when
/// the value is not representable (a non-literal) — the fact is then dropped.
fn singleton_fact(arg: &ArgValue, php_minor: Option<(u16, u16)>) -> Option<Fact> {
    val_of(arg, php_minor).map(Fact::Singleton)
}

/// The target of a proven closure value (ADR-0033): an anonymous closure/arrow
/// scope (by definition-site byte offset), or a first-class callable naming a free
/// function.
#[derive(Clone)]
enum ClosureTarget {
    /// An anonymous closure/arrow scope addressed by its `def_offset`.
    Scope(u32),
    /// A first-class callable of a named free function (`strtolower(...)`).
    Named(NameRef),
}

/// A proven closure value carried in the env (ADR-0033). Normal value discipline
/// applies: a reassignment/invalidation drops the whole [`Known`], so the closure
/// dies exactly like any other value. The by-value capture **snapshot** is taken
/// at closure-creation time (the definition-site env), which is the semantically
/// correct PHP by-value capture — a later mutation of the captured variable does
/// not change what the closure sees.
#[derive(Clone)]
struct ClosureVal {
    target: ClosureTarget,
    /// The by-value captured variable facts, snapshotted at creation with their
    /// trust stratum (issue #128 review). Seeding the descent without the stratum
    /// would launder an `Asserted` capture into a `Verified` summary premise.
    captures: Vec<(String, Fact, Stratum)>,
    /// The closure definition line, for descent provenance.
    def_line: u32,
}

/// Whether two closure targets denote the same closure (same anonymous scope, or
/// the same named function) — for join survival.
fn closure_target_eq(a: &ClosureTarget, b: &ClosureTarget) -> bool {
    match (a, b) {
        (ClosureTarget::Scope(x), ClosureTarget::Scope(y)) => x == y,
        (ClosureTarget::Named(x), ClosureTarget::Named(y)) => x.raw == y.raw && x.kind == y.kind,
        _ => false,
    }
}

/// A capture fact reduced to a [`BindingKey`]-comparable [`ArgValue`]: a concrete
/// `Singleton` becomes its value (so a snapshot of `1` and of `"abc"` key
/// distinctly); any abstract fact collapses to `Other` (still distinct from a
/// concrete snapshot, sound for memoization).
fn arg_of_fact_key(fact: &Fact) -> ArgValue {
    match fact {
        Fact::Singleton(v) => arg_of_val(v),
        _ => ArgValue::Other,
    }
}

/// An allocation identity — the key the heap is stored under (ADR-0036). Fresh
/// per `new`/`clone`; a variable holds one via [`Store::refs`] (its ObjRef).
type AllocId = u32;

/// A property's value-domain fact together with its trust stratum (ADR-0052 §5).
/// A prop written from an `Asserted` rvalue is `Asserted`; a prop read back out
/// (`$x = $o->p`) carries the stratum forward, so an assert cannot launder into a
/// proof-layer premise through the heap (the derivation clause — heap writes).
#[derive(Clone)]
struct PropFact {
    fact: Fact,
    stratum: Stratum,
}

/// A heap object (ADR-0036 object state): allocation-keyed, so aliases share it.
/// The `class` is fixed at construction and never swept; `class_exact` says whether
/// it is the *exact* runtime class or only a lower bound (see below); `props` are
/// the per-property value-domain facts.
#[derive(Clone)]
struct HeapObj {
    /// The class FQN (lowercase-normalized, as `classes_env` held). For an
    /// allocation-proven object (`new`, enum case, clone-of-exact) this is the exact
    /// runtime class; for a `$this` seed it is only a **lower bound** — the runtime
    /// object may be any descendant that inherited the method. `class_exact`
    /// distinguishes the two (audit G1, ADR-0036).
    class: String,
    /// Whether `class` is the *exact* runtime class (`true`) or a lower bound
    /// (`false`). A No-side conclusion — `is_a(class, T) = No` implies the object is
    /// not a `T` — is only sound when this is `true`: with a lower bound the actual
    /// instance may be a descendant of `class` that *is* a `T`. Yes-side conclusions
    /// (`is_a(class, T) = Yes`) hold for a lower bound too (every descendant is a T).
    class_exact: bool,
    /// Property facts keyed by property name (ADR-0035 Facts live in props), each
    /// with its trust stratum (ADR-0052 §5).
    props: HashMap<String, PropFact>,
    /// Properties declared `readonly` — sweep-immune once established (ADR-0036).
    readonly: HashSet<String>,
    /// readonly props provably written on THIS path (for `readonly.reassigned`).
    ro_written: HashSet<String>,
    /// Whether this object has escaped (passed to a call, returned, stored into an
    /// array/property, or captured by a closure). Escaped objects have their
    /// non-readonly props swept by unknown calls; a purely-local object's props
    /// survive — the ADR-0036 precision payoff.
    escaped: bool,
}

impl HeapObj {
    /// A fresh heap object. `class_exact` defaults to `false` (a lower bound — the
    /// safe default); allocation-proven construction sites set it to `true`
    /// explicitly (`build_new_object`, exact `$this`/clone seeds).
    fn new(class: String) -> Self {
        HeapObj {
            class,
            class_exact: false,
            props: HashMap::new(),
            readonly: HashSet::new(),
            ro_written: HashSet::new(),
            escaped: false,
        }
    }

    /// Sweep the non-readonly props (an unknown/overridable call on an escaped or
    /// `$this` object may have mutated them). readonly props and the class survive.
    fn sweep_nonreadonly(&mut self) {
        self.props.retain(|name, _| self.readonly.contains(name));
    }
}

/// The object store threaded through the walk (ADR-0036). `refs` binds a variable
/// to an allocation id (its ObjRef);
/// `heap` maps ids to objects. Aliasing (`$b = $a`) copies the ref (shared id), so
/// a write through any alias is visible through all. A variable's exact-class fact
/// lives at `heap[refs[var]].class`.
#[derive(Clone, Default)]
struct Store {
    refs: HashMap<String, AllocId>,
    heap: HashMap<AllocId, HeapObj>,
    /// **Contract facts** (ADR-0052 §1, the NEW carrier): a variable's *declared*
    /// type as a lowered, syntactic **arm list**, seeded at scope entry (§9 — THE
    /// entry-state contribution) and narrowed by guards arm-wise (`instanceof`,
    /// `!== null`). Each arm carries its own trust stratum: the native member list
    /// seeds `Verified`, a `@param` phpdoc refinement seeds `Asserted` (ADR-0037
    /// trust order). Subtraction preserves each surviving arm's stratum — an
    /// `Asserted` arm can never launder to `Verified`. Consumed ONLY by the four
    /// §3 consumers (arm filtering, `eval_instanceof` implication, catch matching,
    /// and — reserved for S6 — the declared-receiver lane); NEVER by `call.on-null`
    /// proofs, arity, `call.undefined-method`, or binding descent.
    contract: HashMap<String, Vec<ContractArm>>,
    /// **Class facts** (ADR-0052 §1, the NEW carrier): guard-derived is-a bounds on
    /// an object-holding variable, beside the heap's *exact* class. A positive
    /// `instanceof T` binds `T` into `yes`; a negative branch binds it into `no`.
    /// `Member` is deliberately weaker than exactness (ADR-0043) — it is NOT fed to
    /// the exactness-gated consumers (§3 NOT-fed list); a final-class `Member` is
    /// deliberately not treated as exactness in v1.
    members: HashMap<String, Member>,
    /// **Existence vouches** (ADR-0049 §4 conservative guard-respect leg): the set of
    /// symbols a positive `method_exists`/`function_exists`/`class_exists` … guard has
    /// vouched for on THIS branch. An absence-family emitter (`call.undefined-method`
    /// today, S4's ids tomorrow) that resolves to a vouched symbol stays silent even
    /// when its own proof reached `Absent` — firing against programmer-supplied
    /// existence evidence would call the programmer a liar. Purely additive and
    /// walk-local (ADR-0048): bound on the guarded branch clone, INTERSECTED at a
    /// join (a vouch survives past the `if` only if every fall-through path carried
    /// it — so `if (method_exists(C,'m')) {} (new C)->m();` never silences the tail),
    /// and deliberately untouched by [`Self::unbind`]/[`Self::clear`] (a symbol's
    /// existence does not change when a variable is rebound or a barrier is crossed).
    vouched: HashSet<Vouch>,
}

/// A symbol a positive existence guard vouches for (ADR-0049 §4 guard-respect leg).
/// All names are lowercased — PHP class/function/method names are case-insensitive,
/// so the vouch matches the resolved emitter symbol case-blind.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
enum Vouch {
    /// `method_exists(C, 'm')` vouched `C::m` — `class` is the receiver's FQN.
    Method { class: String, method: String },
    /// `function_exists('f')` vouched the function `f`.
    Function(String),
    /// `class_exists`/`interface_exists`/`trait_exists`/`enum_exists('N')` vouched `N`.
    Class(String),
}

/// One arm of a [`Store::contract`] lane: a declared-type alternative plus the
/// trust stratum it was seeded at (ADR-0052 §1/§5). The `ty` is the syntactic arm
/// judged arm-wise through steins-contract's single acceptance relation.
#[derive(Clone, Debug, PartialEq)]
struct ContractArm {
    ty: steins_contract::ContractTy,
    stratum: Stratum,
}

/// Guard-derived is-a bounds on an object variable (ADR-0052 §1 `Member`): is-a
/// every class in `yes`, provably-not-is-a every class in `no`. FQNs are stored
/// lowercase-normalized (matching the is-a oracle's key). Bound at the `Verified`
/// stratum — a runtime `instanceof` executed on the live branch.
#[derive(Clone, Debug, Default, PartialEq)]
struct Member {
    yes: Vec<String>,
    no: Vec<String>,
}

impl Store {
    /// The exact class of the object `var` currently refers to, if any.
    fn class_of(&self, var: &str) -> Option<&str> {
        self.heap.get(self.refs.get(var)?).map(|o| o.class.as_str())
    }

    /// The allocation id `var` currently refers to.
    fn id_of(&self, var: &str) -> Option<AllocId> {
        self.refs.get(var).copied()
    }

    /// Whether `var` refers to an object whose `class` is the **exact** runtime
    /// class (audit G1). `false` for an unbound var and for any lower-bound object
    /// (a `$this` seed that is not provably exact) — the No-side gate.
    fn is_exact(&self, var: &str) -> bool {
        self.obj_of(var).is_some_and(|o| o.class_exact)
    }

    /// The object `var` currently refers to.
    fn obj_of(&self, var: &str) -> Option<&HeapObj> {
        self.heap.get(self.refs.get(var)?)
    }

    /// Whether `var` is bound to any object.
    fn is_bound(&self, var: &str) -> bool {
        self.refs.contains_key(var)
    }

    /// A property fact of the object `var` refers to (stratum-agnostic — used by
    /// contract-layer consumers, which accept `Asserted`).
    fn prop_fact(&self, var: &str, prop: &str) -> Option<&Fact> {
        self.obj_of(var)?.props.get(prop).map(|p| &p.fact)
    }

    /// The trust stratum of a property fact of the object `var` refers to, or
    /// `Verified` when there is no such prop (the neutral element of `min`).
    fn prop_stratum(&self, var: &str, prop: &str) -> Stratum {
        self.obj_of(var).and_then(|o| o.props.get(prop)).map_or(Stratum::Verified, |p| p.stratum)
    }

    /// Drop `var`'s ObjRef binding — the heap object survives (other aliases keep
    /// seeing it); `var` just forgets which object it held (ADR-0036: a pass-to-call
    /// may rebind `$var`, so the var→id link must die exactly as `classes_env`
    /// entries did, while the id lives on for its other aliases).
    fn unbind(&mut self, var: &str) {
        self.refs.remove(var);
        // Reassignment / invalidation also voids the guard-derived class facts and
        // the declared-type arm lane: a rebound `$var` no longer satisfies the
        // narrowed possibilities established for the old value (ADR-0052 §9 —
        // narrowing carriers are scope-local and die with the value they described).
        self.members.remove(var);
        self.contract.remove(var);
    }

    /// Clear all bindings and the heap — a Barrier: nothing is reachable.
    fn clear(&mut self) {
        self.refs.clear();
        self.heap.clear();
        self.members.clear();
        self.contract.clear();
    }

    /// The narrowed declared-type arm lane of `var` (ADR-0052 §3, consumer (d) —
    /// the declared-receiver lane **reserved for S6** `phpdoc.undefined-method`).
    /// Built now so S6 consumes a stable accessor; N4 itself emits nothing from it.
    /// The returned arms are the seeded declared type minus every guard subtraction
    /// on the live branch (e.g. `{Guest}` after the else of `instanceof User` over
    /// `User|Guest`); each carries its stratum for the min-premise rule.
    fn contract_arms(&self, var: &str) -> Option<&[ContractArm]> {
        self.contract.get(var).map(Vec::as_slice)
    }

    /// The class-membership fact of `var` (ADR-0052 §1 `Member`), if any guard bound
    /// one on this branch. Consumed only by [`eval_instanceof`] implication (§3b)
    /// and catch-arm matching — never the exactness-gated lanes.
    fn member_of(&self, var: &str) -> Option<&Member> {
        self.members.get(var)
    }

    /// Record an existence vouch on this branch (ADR-0049 §4 guard-respect leg).
    fn vouch(&mut self, v: Vouch) {
        self.vouched.insert(v);
    }

    /// Whether a positive existence guard on this path vouched `class::method`
    /// (case-insensitively — the vouch stores lowercased names).
    fn vouches_method(&self, class: &str, method: &str) -> bool {
        self.vouched.contains(&Vouch::Method {
            class: class.to_ascii_lowercase(),
            method: method.to_ascii_lowercase(),
        })
    }

    /// Whether a positive `function_exists('f')` guard on this path vouched the
    /// function `f` (ADR-0049 §3 / FP-15 guard leg; case-insensitive — the vouch
    /// stores the lowercased, leading-`\`-stripped name). (`class.undefined` needs no
    /// twin here: its firing conditions — index Absent + boot not-found — are exactly
    /// what folds a `class_exists('X')` guard's branch dead, so dead-region pruning
    /// is that id's guard leg.)
    fn vouches_function(&self, fqn: &str) -> bool {
        self.vouched.contains(&Vouch::Function(fqn.trim_start_matches('\\').to_ascii_lowercase()))
    }

    /// Mark the object `var` refers to as escaped (if any).
    fn mark_escaped(&mut self, var: &str) {
        if let Some(id) = self.refs.get(var).copied()
            && let Some(o) = self.heap.get_mut(&id)
        {
            o.escaped = true;
        }
    }

    /// Sweep every escaped object's non-readonly props (an unknown call ran that may
    /// mutate any escaped object). Non-escaped objects survive (ADR-0036 payoff).
    fn sweep_escaped(&mut self) {
        for o in self.heap.values_mut() {
            if o.escaped {
                o.sweep_nonreadonly();
            }
        }
    }
}

/// The **trust stratum** of a bound fact (ADR-0052 §5): whether it is fit to
/// premise a proof-layer finding. `Verified` facts come from a runtime-executed
/// test on the live branch (`===`, `is_int`, `instanceof`, ordering, truthiness)
/// or a native declaration seed — the branch runs only if the test passed, so the
/// fact holds on the live path. The `assert($expr)` construct is `Verified` too:
/// the 2026-07-25 owner ruling reads it as a throw-guard (`if (!$expr) throw`),
/// unconditionally, without consulting `zend.assertions`. `Asserted` facts come from
/// docblock claims (`@phpstan-assert` family) — a claim, not a proof. The bit is a *checked*
/// attribute (the `"asserted"` provenance string is prose, only for display); the
/// consumption rule (proof-layer ids require all-Verified premises) reads it.
///
/// A derived fact's stratum is the **minimum** over every fact consumed in its
/// derivation (the amendment's derivation clause): folds, array composition, heap
/// property writes, branch joins, and binding-descent seeding all propagate
/// `min(inputs)`, so `Asserted` can never launder into `Verified` across a
/// derivation step. `min` is `Asserted` whenever either operand is `Asserted`.
#[derive(Clone, Copy, PartialEq, Eq, Debug, Hash)]
enum Stratum {
    /// A runtime-executed test or a native declaration — fit for the proof layer.
    Verified,
    /// A docblock claim or an `assert($expr)` narrowing — never premises proof.
    Asserted,
}

impl Stratum {
    /// The weaker of two strata: `Asserted` dominates (the derivation clause). This
    /// is commutative and associative, so the min-stratum rule is order-independent
    /// (ADR-0048: no global ordering enters a fact).
    fn min(self, other: Stratum) -> Stratum {
        match (self, other) {
            (Stratum::Verified, Stratum::Verified) => Stratum::Verified,
            _ => Stratum::Asserted,
        }
    }
}

/// A proven local fact plus where it was established (for provenance). A closure
/// value has no scalar `fact` — it rides in [`Known::closure`] instead (ADR-0033).
#[derive(Clone)]
struct Known {
    /// The scalar/array value-domain fact, or `None` for a closure-only binding.
    fact: Option<Fact>,
    line: u32,
    bound: Option<String>,
    /// The proven closure value bound to this variable, if any (ADR-0033).
    closure: Option<ClosureVal>,
    /// The trust stratum of `fact` (ADR-0052 §5). `Verified` by default; an
    /// assert-derived or assert-laundered fact carries `Asserted`.
    stratum: Stratum,
}

impl Known {
    /// A plain value binding at the `Verified` stratum (native seeds, literal
    /// assignments, native-condition refinements — the common case).
    fn value(fact: Fact, line: u32, bound: Option<String>) -> Self {
        Known { fact: Some(fact), line, bound, closure: None, stratum: Stratum::Verified }
    }

    /// A plain value binding at an explicit stratum (derivation sites propagating
    /// `min(inputs)`, and the assert family binding `Asserted`).
    fn value_strat(fact: Fact, line: u32, bound: Option<String>, stratum: Stratum) -> Self {
        Known { fact: Some(fact), line, bound, closure: None, stratum }
    }

    /// A closure binding (no scalar fact; a closure is never assert-derived).
    fn closure(cv: ClosureVal, line: u32) -> Self {
        Known { fact: None, line, bound: None, closure: Some(cv), stratum: Stratum::Verified }
    }

    /// The single proven value, when the fact is a `Singleton` (converted back to
    /// the trace IR's [`ArgValue`]); `None` for every abstract or multi-valued
    /// layer (and for a closure-only binding) — those resolve no proven value.
    fn singleton(&self) -> Option<ArgValue> {
        match &self.fact {
            Some(Fact::Singleton(v)) => Some(arg_of_val(v)),
            _ => None,
        }
    }
}

/// A binding-descent key: the callee (by FQN-ish key) plus its bound params.
/// Each binding carries its trust [`Stratum`] so a Verified summary cannot be
/// replayed for an Asserted entry with the same value (issue #128 review).
/// Method descents may also carry a `this:` pseudo-binding for the exact
/// receiver (ADR-0075 §2.1); closure descents carry `use:{name}` captures.
type BindingKey = (String, Vec<(String, ArgValue, Stratum)>);

/// A **return-fact summary** (ADR-0057 amendment): the join, over a callee's
/// returning exits, of the returned expression's value-domain fact — a
/// legitimate query answer (ADR-0048 §2), a pure function of (callee CST, bound
/// entry state). It rides the same descent, the same [`BindingKey`] memo (now a
/// value map), and is consumed at the call-result binding as the value FLOOR above
/// the declared arms (A1). The heap-object component (ADR-0057 §1) is reserved in
/// the summary shape but currently always `None`.
#[derive(Clone)]
struct ReturnSummary {
    /// The value-domain component (this amendment): the joined returned-expression
    /// fact with its trust stratum.
    value: Option<SummaryValue>,
    /// The heap-object component (ADR-0057 §1) — populated by T1; always `None` here.
    #[allow(dead_code)] // T1 slot, present for the memo/value-map shape
    heap: Option<HeapSummary>,
}

/// The value-domain half of a [`ReturnSummary`]: the joined fact and its stratum
/// (`min` over exits, N2 — an `Asserted` exit drags the whole summary to `Asserted`).
#[derive(Clone)]
struct SummaryValue {
    fact: Fact,
    stratum: Stratum,
}

/// The heap-object component of a [`ReturnSummary`] (ADR-0057 §1) — reserved for a
/// later heap summary (class/exactness/props/readonly/escape); never constructed yet.
#[derive(Clone)]
#[allow(dead_code)] // reserved heap-summary slot
struct HeapSummary;

/// One returning exit's contribution to the summary join (A2/A3). A native-envelope
/// violating exit is DROPPED (a proven boundary TypeError, its value never reaches
/// the caller) — it is simply never recorded, so there is no variant for it.
enum ExitContribution {
    /// An informative exit within the declared envelope: its fact crosses with its
    /// stratum (a phpdoc-only violation crosses here — the walk truth, A2).
    Fact(Fact, Stratum),
    /// A factless returning exit: it contributes the declared value FLOOR (A3), the
    /// sound top within the envelope — `General{base}` degrades, never lies.
    Floor,
}

/// The per-descent summary-collection context threaded through [`WalkCx`] while a
/// callee body is walked for its return-fact summary. Holds the callee's native
/// return arms (the A2 drop oracle) and the accumulating exit list.
struct SummaryCtx {
    /// The callee's native return type lowered to contract arms — the drop test's
    /// oracle (A2): an exit fact every arm provably rejects is a boundary TypeError.
    native: Vec<ContractTy>,
    /// Each returning exit's contribution, in walk order (RefCell — pushed through
    /// the shared-immutable [`WalkCx`] as branches recurse).
    exits: std::cell::RefCell<Vec<ExitContribution>>,
}

impl SummaryCtx {
    /// Whether `fact` provably violates the native return envelope (A2): every native
    /// arm rejects it. With no native declaration there is nothing to violate.
    fn native_violates(&self, fact: &Fact) -> bool {
        !self.native.is_empty()
            && self
                .native
                .iter()
                .fold(Certainty::No, |acc, arm| acc.or(steins_contract::admits_fact(arm, fact)))
                .is_no()
    }
}

/// The state threaded down an interprocedural binding descent (Feature B). The memo
/// is a **value map** (ADR-0057 §3): a key's computed [`ReturnSummary`] is cached so
/// a memo hit REPLAYS it (a summary is a value, not a suppression bit) — legitimate
/// caching, since the summary is a pure function of the key's entry state.
struct Descent<'a> {
    provenance: &'a str,
    depth: usize,
    stack: &'a mut Vec<BindingKey>,
    memo: &'a mut HashMap<BindingKey, Option<ReturnSummary>>,
}

/// Walk one scope's trace with a given initial environment.
#[allow(clippy::too_many_arguments)]
fn analyze_scope(
    cx: &Cx,
    folder: &mut dyn Folder,
    scope: &Scope,
    mut env: HashMap<String, Known>,
    mut store: Store,
    this_exact: Option<String>,
    mut descent: Option<Descent<'_>>,
    mut facts: Option<&mut Vec<LineFact>>,
    dead_out: Option<&mut Vec<Span>>,
    ret_exits: Option<&mut Vec<ExitContribution>>,
    out: &mut Vec<Diagnostic>,
) {
    let enclosing_class = scope_class(scope);

    // The owning function/method's native return type, resolved once. Return-type
    // checking runs only in the plain per-scope pass (`descent.is_none()`), never
    // under an interprocedural binding descent: a descent rebinds the *callee's*
    // parameters, not its return, so re-checking there would only duplicate the
    // per-scope finding (and the file's own strict mode already governs it). The
    // returned value is resolved against the *file's own* `strict` via `cx`.
    let ret_info: Option<(&NativeType, String)> =
        if descent.is_none() { cx.scope_return(scope) } else { None };
    // The owning declaration's `@return` phpdoc envelope, resolved the same way
    // (plain per-scope pass only). Checked under contract acceptance, skipped where
    // the native return check already fired (no double-report).
    let ret_phpdoc: Option<(PType, String)> =
        if descent.is_none() { cx.scope_return_phpdoc(scope) } else { None };

    // Native-type parameter seeding (Feature B): seed each parameter with the fact
    // its native type guarantees at runtime. This is sound in BOTH strict and
    // coercive modes: the engine coerces or throws at entry, so inside the body an
    // `int $x` param IS an int (post-coercion) — the seed is a *runtime-enforced*
    // fact, not a guess. A descent already binds actual values for the params the
    // caller supplied; we only seed params still absent from the env (unbound
    // params may still carry their native-type fact — sound).
    if let Some(params) = cx.scope_params(scope) {
        for p in params {
            if env.contains_key(&p.name) || store.is_bound(&p.name) {
                continue;
            }
            if let Some(fact) = seed_fact(p) {
                env.insert(p.name.clone(), Known::value(fact, 0, Some("native parameter type".to_owned())));
            }
        }
    }

    // Contract-fact seeding (ADR-0052 §9) — THE entry-state contribution of this
    // ADR (ADR-0048 §3 canonical entry state, defined at landing, not retrofitted):
    // per declared parameter, the native member list (`Verified`) refined by the
    // declared `@param` phpdoc envelope (`Asserted`), the ADR-0037 trust order. The
    // arm lane lives in the walk-local `Store` (cloned as `bclasses` at every
    // branch); a descent that already bound a param's value gets no lane (its value
    // is known, the declared possibilities are moot). Every other narrowing carrier
    // (guard facts, members, static-prop channels) contributes nothing to entry
    // state — the deliberately boring §9 answer.
    if descent.is_none()
        && let Some(params) = cx.scope_params(scope)
    {
        let envelopes = cx.scope_envelopes(scope);
        for p in params {
            if store.contract.contains_key(&p.name) {
                continue;
            }
            let phpdoc = envelopes.as_ref().and_then(|e| {
                // An assertion-target `@param` states a post-condition, not the
                // parameter's declared type — never seed a lane from it.
                if e.is_assert_target(&p.name) { None } else { e.param(&p.name) }
            });
            // Resolve phpdoc class arms in the param's namespace context (its offset
            // falls in the same region as the `@param` docblock), matching the FQNs
            // the `instanceof` subtrahend and S6's `find_class` use.
            let resolve = |n: &str| {
                cx.resolve_pclass(cx.cur, p.span.start, n).trim_start_matches('\\').to_ascii_lowercase()
            };
            if let Some(arms) = seed_contract_arms(p, phpdoc, &resolve)
                && !arms.is_empty()
            {
                // The abstract array stratum's entry state (ADR-0062 S3): a lane
                // whose array vocabulary has collapsed to ONE arm also seeds the
                // value lane with that arm's canonical shape fact. Multi-array-arm
                // lanes seed nothing — a shape∪shape union lives in the arm lane
                // until a guard subtracts it down to one (A-G3; the subtraction is
                // S4's), and the fact lane holds a single shape only then.
                if !env.contains_key(&p.name)
                    && let Some(fact) = seed_shape_fact(&arms)
                {
                    env.insert(
                        p.name.clone(),
                        // ALWAYS `Asserted`, even where the arm itself is
                        // `Verified` (a native `array $x`): A-G9's corollary is
                        // normative — shape-derived facts never feed proof-layer
                        // findings — and the stratum is the mechanism that
                        // enforces it structurally rather than by review.
                        Known::value_strat(
                            fact,
                            0,
                            Some("declared array shape".to_owned()),
                            Stratum::Asserted,
                        ),
                    );
                }
                store.contract.insert(p.name.clone(), arms);
            }
        }
    }

    // Seed the `$this` object in a method scope (ADR-0036): props/readonly from the
    // class surface. Only when the class declares tracked properties (otherwise
    // `$this` stays unbound — identical to pre-heap behavior). A descent that
    // already bound `this` (impossible today — descents pass an empty store) is left
    // untouched.
    if let Some(class) = enclosing_class
        && !store.is_bound("this")
    {
        // G1 (audit): `$this`'s heap class is a LOWER BOUND — any subclass instance
        // may be running this method — UNLESS exactness is locally provable. A
        // binding descent that proved the exact receiver (`this_exact`) makes `$this`
        // exactly that class; otherwise the enclosing class is the class, exact only
        // when it is `final` or an enum (no subclass can exist).
        let (this_class, exact): (&str, bool) = match this_exact.as_deref() {
            Some(exact) => (exact, true),
            None => (class, cx.this_class_exact(class)),
        };
        if let Some(obj) = seed_this_object(cx, this_class, exact) {
            let id = store.heap.keys().copied().max().map_or(0, |m| m + 1);
            store.heap.insert(id, obj);
            store.refs.insert("this".to_owned(), id);
        }
    }

    // The allocation counter starts past any id already in the store (the seeded
    // `$this`), so a fresh `new`/`clone` never collides with it.
    let alloc_start = store.heap.keys().copied().max().map_or(0, |m| m + 1);
    // Return-fact summary collection (ADR-0057 amendment T0): active only when the
    // caller requested exits (a descent building the callee's summary). The native
    // return arms are resolved once, up front, as the A2 drop oracle.
    let summary = ret_exits.as_ref().map(|_| SummaryCtx {
        native: cx.scope_return(scope).map(|(ty, _)| native_arms(ty)).unwrap_or_default(),
        exits: std::cell::RefCell::new(Vec::new()),
    });
    let w = WalkCx {
        cx,
        scope,
        enclosing_class,
        this_exact: this_exact.as_deref(),
        ret_info: &ret_info,
        ret_phpdoc: &ret_phpdoc,
        dead: std::cell::RefCell::new(Vec::new()),
        alloc: std::cell::Cell::new(alloc_start),
        summary,
    };
    let flow =
        walk_trace(&w, folder, &scope.stmts, &mut env, &mut store, &mut descent, &mut facts, false, out);
    if let Some(out) = ret_exits
        && let Some(sc) = w.summary
    {
        let mut exits = sc.exits.into_inner();
        // Untyped fallthrough is PHP's implicit `return null` (ADR-0057 §5). The
        // test is the **raw** written return hint (`ret_hint`), not whether Steins
        // lowers a representable `NativeType`: `void` / `never` / `: object` /
        // `: array` all leave `scope_return` as `None` but must not contribute null.
        // A written non-void hint that falls through is a boundary TypeError —
        // nothing is contributed (same as an A2-dropped exit). Generators refuse
        // summaries entirely (`join_summary`); they also skip fallthrough null.
        if flow == Flow::FellThrough && scope.ret_hint.is_none() && !scope.is_generator {
            exits.push(ExitContribution::Fact(Fact::Singleton(Val::Null), Stratum::Verified));
        }
        *out = exits;
    }
    if let Some(sink) = dead_out {
        sink.extend(w.dead.into_inner());
    }
}

/// Whether a walked (sub-)trace runs off its end (its successor is reachable) or
/// terminates (`return`/`throw`/`exit`, or an `if` where no branch falls through).
#[derive(Clone, Copy, PartialEq, Eq)]
enum Flow {
    FellThrough,
    Terminated,
}

/// The immutable context shared across a scope's recursive branch walk (ADR-0031).
struct WalkCx<'a, 'w> {
    cx: &'w Cx<'a>,
    scope: &'w Scope,
    enclosing_class: Option<&'w str>,
    this_exact: Option<&'w str>,
    ret_info: &'w Option<(&'a NativeType, String)>,
    ret_phpdoc: &'w Option<(PType, String)>,
    /// Proven-dead statement spans discovered during this walk (skipped decided
    /// branches, unreachable tails). Only the PLAIN per-scope walk's regions are
    /// universal truths — a binding descent's dead branches are dead *for that
    /// binding only*, so descents discard theirs (`dead_out: None`).
    dead: std::cell::RefCell<Vec<Span>>,
    /// A monotone allocation-id counter for this scope walk (ADR-0036). Shared
    /// across branch clones (they clone the `Store`, not this cell), so a `new` in
    /// one branch never collides with a `new` in another that later joins.
    alloc: std::cell::Cell<AllocId>,
    /// Return-fact summary collection (ADR-0057 amendment T0): `Some` only while a
    /// callee body is walked for its summary (a descent requested it). Each returning
    /// exit pushes its contribution here; the join happens in [`descend`].
    summary: Option<SummaryCtx>,
}

impl WalkCx<'_, '_> {
    /// Mint a fresh allocation id for a `new`/`clone`.
    fn fresh_id(&self) -> AllocId {
        let id = self.alloc.get();
        self.alloc.set(id + 1);
        id
    }
}

/// Record every top-level statement span of the given traces as proven dead.
/// Nested constructs' calls lie within their statement's span, so containment
/// filtering over these covers them. (Skipped `elseif` *conditions* are not
/// yet marked — a literal-arg call inside one is vanishingly rare; TODO.)
fn mark_dead(w: &WalkCx, traces: &[&[Stmt]]) {
    let mut dead = w.dead.borrow_mut();
    for trace in traces {
        for stmt in *trace {
            dead.push(stmt.span);
        }
    }
}

/// Whether a byte position falls inside any proven-dead region.
fn in_dead(dead: &[Span], pos: u32) -> bool {
    dead.iter().any(|s| s.start <= pos && pos < s.end)
}

/// Walk an ordered statement (sub-)trace against a mutable env, threading the same
/// findings sink, descent, and facts. Returns whether the trace falls through.
/// Statements after a terminator are unreachable and are **not** walked (ADR-0031
/// closes ADR-0027's dead-fallthrough gap).
#[allow(clippy::too_many_arguments)]
fn walk_trace(
    w: &WalkCx,
    folder: &mut dyn Folder,
    stmts: &[Stmt],
    env: &mut HashMap<String, Known>,
    store: &mut Store,
    descent: &mut Option<Descent<'_>>,
    facts: &mut Option<&mut Vec<LineFact>>,
    guarded: bool,
    out: &mut Vec<Diagnostic>,
) -> Flow {
    let cx = w.cx;
    let scope = w.scope;
    for (stmt_idx, stmt) in stmts.iter().enumerate() {
        // 0. Statement-level inline `@var` casts (ADR-0073), applied before the
        // statement's own checks read the env — the docblock precedes the
        // statement, so its cast is in force for everything the statement does.
        // A tag above an `Assign` to the same variable is erased by step 2's own
        // rebind: the assignment-form `@var` (PHPStan casts the RHS there) is a
        // separate unsupported feature that stays silent, never a wrong claim.
        // Plain per-scope pass only (see `apply_inline_var_casts`).
        if descent.is_none() {
            apply_inline_var_casts(w, stmt, env, store);
            // 0a. The ADR-0076 loop-subject probe, read from the ENTRY env (after
            // the inline cast, which the statement's own checks also see). Gated on
            // an installed probe, so a normal check pays one `is_some()` and sees
            // no behaviour change; never under a binding descent, like every other
            // observer.
            record_subject_probe(cx, stmt, env);
        }
        // 0b. The trace annotation (ADR-0074, issue #94): a statement-adopted
        // `@psalm-trace $x` docblock asks the dump surface's question against
        // this statement's EXIT facts (§5, Psalm's semantics: the annotation is
        // "applied to the next statement" and reports what it leaves behind).
        // Adoption is resolved here — the same shared `stmt_docblock` query the
        // step-0 cast reads (§6: one position, one adoption grammar) — and the
        // answer is flushed via `.take()` on whichever exit this iteration
        // takes: the divergent `return`s in step 2 or the common bottom, so
        // every annotated site (diverging statements included) answers exactly
        // once. Plain per-scope pass only (the `emit_dumps` gate): never
        // per-caller under a binding descent.
        let mut pending_trace = if descent.is_none() {
            adopted_trace_docblock(w, stmt)
        } else {
            None
        };
        // The return-fact summary of a `$x = f(...)` / `$x = $o->m(...)` RHS
        // descent (ADR-0057 amendment T0; ADR-0075 for methods/statics), captured
        // in step 1 and consumed by `apply_assign` in step 2. For an `Assign`
        // statement `checkable_calls` yields exactly the RHS call, so the summary
        // below is unambiguously this assignment's. Constructors keep descending
        // for diagnostics but never fill this slot (ADR-0075 §3).
        //
        // `stmt_return_arms` is the declared return floor resolved **before**
        // `apply_assign` unbinds the assignment target (self-assign
        // `$o = $o->m(1)` would otherwise drop the exact receiver before floor
        // re-resolution).
        let mut stmt_summary: Option<ReturnSummary> = None;
        let mut stmt_return_arms: Option<Vec<ContractArm>> = None;
        // 1. Check + descend every statically-named call this statement carries.
        for call in checkable_calls(&stmt.kind) {
            match &call.receiver {
                Callee::Function(_) => {
                    check_propagated_call(
                        cx, folder, scope.poisoned, descent.is_some(), call, env, store, out,
                    );
                    // Userland function arity (ADR-0049 §6 / S5): judged once in the
                    // plain per-scope pass, like the absence flagship.
                    if descent.is_none() {
                        check_arity(cx, folder, call, store, scope.poisoned, out);
                        // The existence flagship (ADR-0049 §3 / S4): a call to a
                        // provably-undefined function behind a clear dam. Judged once
                        // in the plain per-scope pass; the walk has already pruned any
                        // proven-dead region, and the branch store carries the FP-15
                        // `function_exists` vouch.
                        check_undefined_function(cx, folder, call, store, out);
                        // The dump surface (ADR-0053 D3/D4): a recognized
                        // `PHPStan\dumpType`-family or `var_dump` call emits its fact
                        // rendering at this position. Plain per-scope pass only, so a
                        // site is dumped once (never re-emitted under a binding descent).
                        // A statement-position call (`StmtKind::Call` — the dump IS the
                        // whole expression-statement) also hands its statement span
                        // down, so the explicit pair's findings can carry the
                        // statement-deletion fix payload (ADR-0010, issue #114).
                        let removal =
                            matches!(stmt.kind, StmtKind::Call(_)).then_some(stmt.span);
                        emit_dumps(w, folder, call, env, store, removal, out);
                        // Oracle idea B (harness-only): when the assertType sink is
                        // installed, record this call's (expected, rendering) pair.
                        // A no-op in every normal check (the sink is absent), so this
                        // adds nothing to the check surface.
                        emit_asserts(w, folder, call, env, store);
                    }
                    stmt_summary =
                        try_descend_function(cx, folder, call, env, scope.poisoned, descent.as_mut(), out);
                    stmt_return_arms = cx.resolve_user_fn_any(call).and_then(|site| fn_return_arms(cx, site));
                }
                Callee::Method { .. } | Callee::Static { .. } | Callee::Construct { .. } => {
                    // Branch-sensitive null-dereference proof (ADR-0031): a `$v->m()`
                    // whose receiver is proven `Singleton(null)` on this path.
                    check_call_on_null(w, call, env, store, out);
                    // The absence flagship (ADR-0049 §4 / S2): fire only in the plain
                    // per-scope pass — every scope (method bodies included) is walked
                    // once there, so a descent must not re-judge the same site.
                    if descent.is_none() {
                        check_undefined_method(cx, folder, call, store, scope.poisoned, out);
                        // The declared-receiver lane (ADR-0049 §8 / S6): a method
                        // absent on a phpdoc-declared receiver narrowed by branch
                        // analysis, under per-arm descendant closure. Disjoint from
                        // S2 by construction — S2 fires on class_exact receivers, S6
                        // only on non-exact receivers carrying a narrowed arm lane.
                        check_phpdoc_undefined_method(cx, folder, call, store, scope.poisoned, out);
                        // Method / constructor / static arity (ADR-0049 §6 / S5),
                        // under a proven-exact receiver only (the declared-receiver
                        // variant is unsound — see `resolve_arity_method`).
                        check_arity(cx, folder, call, store, scope.poisoned, out);
                    }
                    let outcome = handle_method_call(
                        cx,
                        folder,
                        scope,
                        call,
                        env,
                        store,
                        w.this_exact,
                        w.enclosing_class,
                        descent.as_mut(),
                        out,
                    );
                    // ADR-0075: a resolved method/static summary rebinds on the same
                    // rungs as a function's. Constructors keep their exactness lane
                    // (ADR-0036) and leave the summary/arms unread.
                    if !matches!(call.receiver, Callee::Construct { .. }) {
                        stmt_summary = outcome.summary;
                        stmt_return_arms = outcome.return_arms;
                    }
                }
                // `$fn(...)` — resolve the callee variable against the env: a proven
                // closure value descends into its scope (ADR-0033), a proven string
                // resolves as a function name.
                Callee::DynamicVar(name) => {
                    // Issue #128: a `$fn(...)` on a proven closure rebinds its
                    // return summary on the same rungs as free functions / methods.
                    let outcome =
                        handle_var_call(cx, folder, scope, name, call, env, descent.as_mut(), out);
                    stmt_summary = outcome.summary;
                    if stmt_return_arms.is_none() {
                        stmt_return_arms = outcome.return_arms;
                    }
                }
                Callee::Dynamic => {}
            }
        }

        // 1z. Offset family (ADR-0049 §7 / S3): fire `offset.missing` /
        // `offset.on-unsupported` at the whitelisted read positions only (A7) — a
        // plain assignment-RHS and a return operand whose value is directly an
        // `OffsetRead`. Judged once per site in the plain per-scope pass
        // (`descent.is_none()`), reading the pre-statement env (which already carries
        // this sub-trace's branch refinements — e.g. an `=== []` guard narrowing the
        // container to `Singleton([])`).
        if descent.is_none()
            && let StmtKind::Assign { value: ArgValue::OffsetRead { base, key }, span, .. }
            | StmtKind::Return { value: ArgValue::OffsetRead { base, key }, span, .. } = &stmt.kind
        {
            check_offset_read(cx, folder, base, key, env, scope.poisoned, *span, out);
            // The strict leg (ADR-0062 S6 / A-G10) at the SAME whitelisted position:
            // where `check_offset_read` judges a proven whole container, this judges
            // the *declared* shape. The two are disjoint by construction — a
            // `Fact::Shape` is `Asserted`, and `check_offset_read`'s operand gate
            // takes `Verified` facts only — so at most one of them ever fires here.
            check_shape_read(cx, base, key, env, scope.poisoned, *span, out);
        }

        // 1z-bis. The `??` final arm (ADR-0062 S6, issue #51 §2). A coalesce operand
        // is a silence carrier for every arm the operator protects, but the RIGHT-MOST
        // arm is a plain read: it is the value whenever everything left of it fell
        // through. Judged at the same two whitelisted positions, under the accumulated
        // `¬isset` premise ladder S5 built.
        if descent.is_none()
            && let StmtKind::Assign { value: value @ ArgValue::Coalesce(..), span, .. }
            | StmtKind::Return { value: value @ ArgValue::Coalesce(..), span, .. } = &stmt.kind
        {
            check_coalesce_final_arm(cx, value, env, scope.poisoned, *span, out);
        }

        // 1a. Escape + sweep (ADR-0036): passing an object into a call escapes it;
        // an unknown/overridable call — or any call an object was passed into —
        // sweeps every escaped object's non-readonly props. `$this` is pre-escaped,
        // so an overridable call on it (unresolved via the guard) sweeps it, while a
        // private/final call (resolved, no object args) leaves it intact.
        apply_call_escape_and_sweep(w, &stmt.kind, store);

        // 1b. Return-type check (native + phpdoc contract); see the original notes.
        if let StmtKind::Return { value, span, .. } = &stmt.kind {
            let mut native_fired = false;
            // A proven scalar (env/fold), or a proven object / class constant
            // (ADR-0043 stage 3 return path); the object arm rides the is-a oracle.
            // Stratum rides with the resolution (issue #127 review): an Asserted
            // fold (`return strtoupper(g(...))`) must not launder to Verified via a
            // syntactic re-read. Nested fold descents emit through `out`.
            let ret_resolved: Option<(ArgValue, Stratum)> = cx
                .resolve_literal_strat_ex(
                    value,
                    env,
                    scope.poisoned,
                    folder,
                    descent.as_mut(),
                    Some(&mut *out),
                )
                .or_else(|| {
                    cx.resolve_static_value(value, w.enclosing_class)
                        .map(|v| (v, Stratum::Verified))
                });
            // The native return check is proof-layer (`type.return-mismatch`): a
            // returned value proven only through an `Asserted` fact stays silent
            // (ADR-0052 §5). The phpdoc contract check below accepts `Asserted`.
            if let Some((ret, display)) = w.ret_info
                && let Some((lit, strat)) = ret_resolved.as_ref()
                && *strat == Stratum::Verified
                && is_type_error(cx, ret, lit)
                && !object_world_guard_blind(descent.is_some(), ret, lit)
            {
                out.push(cx.return_diagnostic(span.start, lit, ret, display));
                native_fired = true;
            }
            if !native_fired
                && let Some((pret, display)) = w.ret_phpdoc
            {
                // Proven-value path, then the abstract-fact path (Feature E) —
                // same discipline as the `@param` check: only a definite `No`.
                let rendered = match cx.resolve_cval(value, env, store, scope.poisoned, folder) {
                    // ADR-0043 stage 4: the class arm of `accepts` now yields definite
                    // verdicts; a class-touching return verdict is guard-blind inside a
                    // descent (mirror of the native `object_world_guard_blind`).
                    Some(cv) => (accepts(cx, cx.cur, span.start, pret, &cv) == Certainty::No
                        && !phpdoc_object_guard_blind(descent.is_some(), pret, Some(&cv)))
                    .then(|| rendered_cval(&cv)),
                    None => arg_abstract_fact(value, env, scope.poisoned).and_then(|fact| {
                        let cty = steins_contract::lower(pret);
                        // The class valve opens for a pure known-class contract against
                        // a definite scalar fact (see `check_phpdoc_param`).
                        let open_class_valve = is_pure_class_contract(cx, cx.cur, span.start, pret)
                            && !phpdoc_object_guard_blind(descent.is_some(), pret, None);
                        ((!contract_touches_class(&cty) || open_class_valve)
                            && steins_contract::admits_fact(&cty, fact) == Certainty::No)
                            .then(|| describe_fact(fact))
                    }),
                };
                if let Some(rendered) = rendered {
                    let pos = cx.tree().position(span.start);
                    out.push(Diagnostic {
                        id: RETURN_MISMATCH_ID,
                        facet: None,
                        fix: None,
                        path: cx.path().to_owned(),
                        line: pos.line,
                        column: pos.column,
                        message: format!(
                            "return value {rendered} violates declared @return {pret} of {display}() — declared contract violation",
                        ),
                    });
                }
            }
        }

        // 1c. Return-fact summary (ADR-0057 amendment T0): when a descent is building
        // this callee's summary, snapshot each returning exit's value-domain fact.
        // Read here — before the return's own escape/invalidation effect (step 2) —
        // so the returned variable's env fact is still live. The join is deferred to
        // `descend`; here we only classify the exit (A2 drop / cross, A3 floor).
        if let StmtKind::Return { value, .. } = &stmt.kind
            && let Some(sc) = &w.summary
        {
            // Composition (A1): when the returned expression IS a call whose
            // summary step 1 captured into `stmt_summary`, that summary is this
            // exit's fact — `return g(...)` and `return $o->m(...)` / `return C::m(...)`
            // (ADR-0075) cross the proven fact. A constructor `return new Foo(...)`
            // is `ArgValue::New` and never composes a construct-body summary as a
            // value (object return is T1). A recursive / unbindable inner call left
            // `stmt_summary` empty, so this falls through to the direct value fact
            // (and thence the A3 floor).
            let composed = if matches!(value, ArgValue::New(..)) {
                None
            } else {
                stmt_summary
                    .as_ref()
                    .and_then(|s| s.value.as_ref())
                    .map(|sv| (sv.fact.clone(), sv.stratum))
            };
            let exit_fact = composed.or_else(|| return_value_fact(w, folder, value, env, store));
            let contrib = match exit_fact {
                // A2 — native-envelope violation: a proven boundary `TypeError`, the
                // value never reaches the caller. Drop the exit (record nothing); the
                // callee's own `type.return-mismatch` is the standing record.
                Some((fact, _)) if sc.native_violates(&fact) => None,
                // An informative exit within the envelope: it crosses with its stratum
                // (a phpdoc-only violation crosses HERE — the walk truth, A2).
                Some((fact, strat)) => Some(ExitContribution::Fact(fact, strat)),
                // A3 — a factless returning exit degrades to the declared arm floor.
                None => Some(ExitContribution::Floor),
            };
            if let Some(c) = contrib {
                sc.exits.borrow_mut().push(c);
            }
        }

        // 2. Apply the statement's own effect on the environment + compute its flow.
        let flow = match &stmt.kind {
            StmtKind::Barrier => {
                env.clear();
                store.clear();
                Flow::FellThrough
            }
            // The A-G8 invalidation table: barrier semantics, plus the base
            // binding's array shape carried across with the key promoted/removed.
            StmtKind::OffsetWrite { base, keys, value } => {
                apply_offset_write(w, folder, base, keys, Some(value), env, store);
                Flow::FellThrough
            }
            StmtKind::OffsetUnset { base, key } => {
                apply_offset_write(w, folder, base, std::slice::from_ref(key), None, env, store);
                Flow::FellThrough
            }
            // `echo` assigns nothing on its own; anything it *can* mutate (embedded
            // assignment / by-ref call) is in `invalidated` (step 3). Reading a
            // variable in an echo no longer forgets it (ADR-0031 precision payoff).
            StmtKind::Echo(_) => Flow::FellThrough,
            // A still-`Opaque` construct (loop / switch / try) forgets what it may
            // write AND what it branches on (reads) (ADR-0027), because the trace
            // does not model its control flow. When the subtree
            // may `return` (`may_return`), a summary walk contributes the declared
            // floor so those hidden exits join the visible ones (ADR-0057 A3;
            // ADR-0075 / #126: without this, a sibling `return null` alone pins
            // Singleton(null) and manufactures call.on-null FPs).
            StmtKind::Opaque { writes, reads, poisons, may_return } => {
                if *poisons {
                    env.clear();
                    store.clear();
                } else {
                    for v in writes.iter().chain(reads) {
                        env.remove(v);
                        store.unbind(v);
                    }
                }
                if *may_return
                    && let Some(sc) = &w.summary
                {
                    sc.exits.borrow_mut().push(ExitContribution::Floor);
                }
                Flow::FellThrough
            }
            StmtKind::Call(_) => Flow::FellThrough,
            // `assert($expr)` narrows the fall-through env with the guard's
            // true-branch refinements (ADR-0052 §5, amended 2026-07-25 — owner
            // ruling "assert() reads as a throw-guard"). Steins reads `assert($expr)`
            // as statically equivalent to `if (!$expr) throw`: continuing past it
            // means the condition held, at the `Verified` stratum unconditionally.
            // `zend.assertions` is never consulted — the risk of running production
            // with assertions compiled out is the operator's, not the analysis's.
            StmtKind::Assert { cond } => {
                apply_type_narrowing(w.cx, cond, true, env, store);
                let refs = then_refinements(cond, w.cx.php_minor);
                apply_refinements(&refs, env, store, Stratum::Verified);
                // The assert lowering already models its argument as a `CondExpr`
                // and applies the true-branch refinements, so `assert(isset(...))`
                // routes into the S4 narrowing through exactly the `if`-guard
                // path — no assert-specific plumbing.
                // …and the same holds for the DR2 type-predicate vocabulary
                // (applied above, in the branch walk's order): `assert(is_string($x))`
                // narrows through the `if`-guard path with no assert-specific
                // plumbing — ADR-0064 §5's "assert inherits every guard for free".
                apply_shape_narrowing(w.cx, cond, true, env, store, true);
                Flow::FellThrough
            }
            // Terminators: the trace stops; the remainder is unreachable.
            StmtKind::Return { value, .. } => {
                // `return $o;` escapes the returned object (ADR-0036).
                if let ArgValue::Var(v) = value {
                    store.mark_escaped(v);
                }
                for v in &stmt.invalidated {
                    env.remove(&v.name);
                    store.unbind(&v.name);
                }
                // A `return $x;` under the annotation still answers (ADR-0074
                // §5): flush the pending trace at this divergent exit.
                emit_trace_annotations(w, folder, pending_trace.take(), stmt, env, store, out);
                return Flow::Terminated;
            }
            StmtKind::Throw { .. } | StmtKind::Exit { .. } => {
                for v in &stmt.invalidated {
                    env.remove(&v.name);
                    store.unbind(&v.name);
                }
                // A diverging `throw`/`exit` under the annotation still
                // answers (ADR-0074 §5).
                emit_trace_annotations(w, folder, pending_trace.take(), stmt, env, store, out);
                return Flow::Terminated;
            }
            StmtKind::Assign { var, value, span, call } => {
                apply_assign(
                    w,
                    folder,
                    var,
                    value,
                    call.as_ref(),
                    span.start,
                    env,
                    store,
                    facts,
                    stmt_summary.as_ref(),
                    stmt_return_arms.as_deref(),
                    out,
                );
                Flow::FellThrough
            }
            StmtKind::PropAssign { target_var, prop, value, span, .. } => {
                // Property checks run only in the plain per-scope pass (like the
                // return check): a binding descent rebinds the callee's params to
                // hypothetical caller values that in-body guards (unmodeled here)
                // would narrow — checking a descent-bound property write is
                // guard-blind and unsound. The heap update always runs so reads
                // within the descent still resolve.
                let checks_enabled = descent.is_none();
                apply_prop_assign(
                    w, folder, target_var, prop, value, span.start, guarded, checks_enabled, env,
                    store, out,
                );
                Flow::FellThrough
            }
            StmtKind::If { cond, then_trace, elseifs, else_trace } => walk_if(
                w, folder, cond, then_trace, elseifs, else_trace.as_deref(), env, store,
                descent, facts, out,
            ),
            StmtKind::Match { subject, arms, default, loose } => walk_match(
                w, folder, subject, arms, default.as_deref(), *loose, env, store, descent,
                facts, out,
            ),
        };

        // 3. Apply `@phpstan-assert` (Always) narrowings from every call in this
        // statement (Feature D), collecting the vars they establish. This runs
        // BEFORE the by-ref invalidation below so the replace-if-weaker decision
        // sees a proven `Singleton`/`OneOf` (kept over a weaker asserted fact); the
        // asserted vars are then protected from the conservative forget, since the
        // assertion helper's contract is a *stronger* statement than "the call may
        // have mutated this by reference".
        let mut asserted: HashSet<String> = HashSet::new();
        for call in checkable_calls(&stmt.kind) {
            apply_stmt_asserts(
                cx, scope, call, env, store, w.this_exact, w.enclosing_class, &mut asserted,
            );
        }

        // 4. After the statement, invalidate any variable handed to a call — except
        // one an assertion just narrowed (its post-call fact is known), and except
        // one every occurrence of which is a proven by-value argument (ADR-0070).
        let by_value = by_value_survivors(cx, scope.poisoned, &stmt.invalidated, env, store);
        for v in &stmt.invalidated {
            if asserted.contains(&v.name) || by_value.contains(v.name.as_str()) {
                continue;
            }
            env.remove(&v.name);
            store.unbind(&v.name);
        }

        // Flush the pending trace annotation at the iteration's common exit —
        // the statement's own effect (step 2), its assert narrowings (step 3)
        // and the by-ref invalidation (step 4) have all applied, so this env IS
        // the state the next statement would enter with (ADR-0074 §5's exit
        // facts). Covers the fall-through path and the diverging `If`/`Match`
        // below alike; the step-2 terminators flushed at their own `return`s.
        emit_trace_annotations(w, folder, pending_trace.take(), stmt, env, store, out);

        if flow == Flow::Terminated {
            // The rest of this trace is proven unreachable (ADR-0031).
            mark_dead(w, &[&stmts[stmt_idx + 1..]]);
            return Flow::Terminated;
        }
    }
    Flow::FellThrough
}

/// The variables `stmt` hands to a call whose facts nevertheless **survive** it
/// (ADR-0070) — the precise reading of the blanket `Stmt::invalidated` drop.
///
/// Takes the evidence rather than the statement, because two positions carry
/// it: a statement's [`Stmt::invalidated`], and a comparison operand's
/// [`CondOperand::Other`] `sites` (issue #158 — `count($a) === count($b)` hands
/// `$a` to the same by-value parameter `count($a);` does, and the branch has the
/// same right to keep its shape).
///
/// # Why anything may survive at all
///
/// PHP passes scalars, strings and arrays **by value** (copy-on-write): the
/// callee's parameter is a separate zval, and writing it cannot reach the
/// caller's binding. So `array_first($a)` — a by-value argument — leaves `$a`
/// exactly as it was, and forgetting `$a`'s shape there is a precision loss with
/// no soundness content. Only a `&$x` parameter (an alias of the caller's
/// lvalue) and an object *handle* (whose referent the callee can mutate) pierce
/// that, and both are refused below.
///
/// # The gate — all five must hold, per variable
///
/// 1. **Every** occurrence of the name in this statement's call arguments is a
///    recorded site on its [`steins_syntax::InvalidatedVar`] entry — an entry
///    with an unprovable occurrence anywhere is `opaque` and carries no sites
///    (the syntax layer's completeness invariant) — and each of
///    those callees **resolves with a known signature**: a project function the
///    index knows (its declared [`Param::by_ref`] answers directly), or a
///    builtin whose argument semantics the catalog states
///    ([`steins_catalog::by_value_arg`]). A name nobody knows refuses.
/// 2. The argument is **by value** at that position. Call-time pass-by-reference
///    was removed in PHP 8, so this is a property of the declaration alone; a
///    `&$x` parameter, an argument past the declared arity, and a variadic
///    position all refuse.
/// 3. The variable denotes a **value-semantic** thing. An object binding (a heap
///    handle, a guard-derived class bound, a closure value) always drops: the
///    handle is copied, the object is not.
/// 4. The scope is **not poisoned**. Every aliasing / scope-injection construct
///    (`$x = &$y`, `global`, `static $x`, `$$v`, `extract`/`compact`, `eval`,
///    `include`, a by-ref `use (&$x)`) poisons the whole scope, so a live
///    reference into a local can never coexist with a surviving fact here. The
///    same veto is applied to the *callee's* body for a project function, which
///    is what closes the one route a by-value argument does not describe — a
///    callee reaching a caller local through `global` at top-level scope.
/// 5. Language constructs never reach this path: `isset`/`empty`/`unset`/`list`
///    are not call nodes, so the lowering records no site for them.
///
/// # The dump-surface exception (ADR-0053)
///
/// A recognized dump callee — the reserved `PHPStan\dumpType` pair (D3) or the
/// global `var_dump` (D4) — is a **read**: it observes the walk's facts at the
/// call position and binds nothing (§10 §3). Such a site keeps the argument's
/// every binding (object holders included — nothing is handed anywhere that
/// could mutate the referent's state) and is exempt from conditions 1–3, so the
/// dump surface stays idempotent: the second dump of a variable answers exactly
/// what the first one did. Recognition is the emitters' own — resolved-FQN,
/// definition-insensitive for the reserved pair ([`dump_family`]'s rule) — so
/// the gate and the emitter can never disagree about what a dump is.
///
/// # The harness assertType exception (oracle idea B)
///
/// In the **harness universe only** — the [`ASSERT_SINK`] installed by
/// [`collect_assert_types`] — a `PHPStan\Testing\assertType('T', $e)` site is
/// the same kind of read: the observer records facts at the call position and
/// binds nothing, so its arguments survive exactly like a dump's. This is what
/// keeps the measurement honest when a corpus file asserts one variable twice
/// (phpstan-src's nsrt files do, routinely): the second assertion must observe
/// the same env the first did, not one degraded by the first assertion's own
/// scaffolding. The exception is deliberately **not** unconditional, unlike the
/// dump pair's: the dumps earn theirs by being normal-check-surface features
/// (D3/D4 emit diagnostics in every check), while `assertType` has no
/// normal-check emitter — with the sink absent, [`is_assert_read_site`] is
/// `false` everywhere and the check surface stays byte-identical (the
/// [`emit_asserts`] pin), so a project that really calls
/// `PHPStan\Testing\assertType` keeps the ordinary conservative treatment.
///
/// # Replayability (ADR-0048)
///
/// The verdict is a **pure function** of (the statement's recorded sites, the
/// project index, the static catalog, the walk-local env/store at this point,
/// and which universe is running — the harness sink is installed for a whole
/// [`collect_assert_types`] run and absent for a whole check, never toggled
/// mid-walk, so it selects a universe rather than injecting per-name state).
/// It asks the engine nothing — no sidecar reflection, no boot surface, no fold
/// — so there is no per-name engine state to memo (the issue #63 discipline
/// applies vacuously here, and deliberately so), and no global ordering can
/// enter a kept fact. Two runs of the same universe over the same sources
/// decide identically, with or without PHP.
fn by_value_survivors<'s>(
    cx: &Cx<'_>,
    poisoned: bool,
    invalidated: &'s [InvalidatedVar],
    env: &HashMap<String, Known>,
    store: &Store,
) -> HashSet<&'s str> {
    let mut kept: HashSet<&'s str> = HashSet::new();
    // Condition 4 (this scope's half): every scope on the ADR-0001 give-up list
    // keeps the blanket drop outright.
    if poisoned {
        return kept;
    }
    for entry in invalidated {
        // An opaque entry has an unprovable occurrence somewhere in the
        // statement — the lowering already discarded whatever provable sites
        // the name had, so no protection may be granted (the blanket drop).
        if entry.opaque {
            continue;
        }
        let var = entry.name.as_str();
        // Whether the name already passed the value-semantic gate (condition 3)
        // — a memo of its own, since `keep` can also record dump-read survival,
        // which never takes that gate.
        let mut sem_ok = false;
        let mut keep = false;
        for (callee, position) in &entry.sites {
            // The read-site exceptions (docs above): a dump (ADR-0053) — and, in
            // the harness universe only, an `assertType` observation (oracle idea
            // B) — reads and binds nothing, so this occurrence keeps the name —
            // object bindings included — and never condemns it.
            if is_dump_read_site(cx, callee) || is_assert_read_site(cx, callee) {
                keep = true;
                continue;
            }
            // Condition 3, asked once per name and BEFORE any index work: a name
            // with an object binding refuses whatever its callees say, and a name
            // with no binding at all has nothing to save (dropping it is already a
            // no-op), so neither is worth resolving a callee for.
            if !sem_ok {
                if !is_value_semantic(var, env, store) {
                    keep = false;
                    break;
                }
                sem_ok = true;
            }
            if arg_is_by_value(cx, callee, *position) {
                keep = true;
            } else {
                // One by-ref (or unresolvable) occurrence condemns the name for
                // the whole statement, whatever its other occurrences promised.
                keep = false;
                break;
            }
        }
        if keep {
            kept.insert(var);
        }
    }
    kept
}

/// Whether a call-argument site's callee is a **dump-surface read** (ADR-0053):
/// the reserved `PHPStan\dumpType` pair (D3) by resolved FQN, or the global
/// `var_dump` (D4) by the PHP fallback rule — each by exactly the recognizer its
/// emitter uses ([`dump_family`]'s FQN rule, [`recognizes_var_dump`]'s name
/// core), so the survival gate and the emitters can never disagree about what a
/// dump is. See the exception paragraph on [`by_value_survivors`].
fn is_dump_read_site(cx: &Cx<'_>, r: &NameRef) -> bool {
    is_dump_family_fqn(&resolved_fn_fqn(cx, r)) || name_reaches_global_var_dump(cx, r)
}

/// Whether a call-argument site's callee is the **harness assertType read**
/// (oracle idea B): the reserved `PHPStan\Testing\assertType` FQN, recognized
/// only while the [`ASSERT_SINK`] is installed — the same condition, and the
/// same resolved-FQN rule ([`ASSERT_TYPE_FQN`]), that gates [`emit_asserts`],
/// so the survival gate and the observer can never disagree about what an
/// assertion is. With no sink (every normal check) this is `false` for every
/// site and `assertType` stays an ordinary call — the check surface is
/// byte-identical. See the exception paragraph on [`by_value_survivors`].
fn is_assert_read_site(cx: &Cx<'_>, r: &NameRef) -> bool {
    ASSERT_SINK.with(|s| s.borrow().is_some()) && resolved_fn_fqn(cx, r) == ASSERT_TYPE_FQN
}

/// Whether `var` holds a **value-semantic** binding worth saving — a scalar, a
/// string or an array — rather than an object handle or nothing at all
/// (ADR-0070 condition 3).
///
/// [`Fact`] has no object layer by construction (its `Val` is int/float/string/
/// bool/null/array), so the object question is asked of the carriers that do
/// hold one: the heap handle lane, the guard-derived class-bound lane, and the
/// closure value on the binding itself. Class identity is *not* the reason the
/// heap lane refuses — a by-value call cannot change what class an object is —
/// the object's own mutable state is.
///
/// A name none of the lanes mention answers `false` too, and that leg is purely
/// a cost gate: invalidating an unbound name is already a no-op, so the callee
/// resolution behind conditions 1 and 2 would be work spent on nothing. Most
/// call arguments in real code are exactly that, which is what keeps the precise
/// path off the hot path.
fn is_value_semantic(var: &str, env: &HashMap<String, Known>, store: &Store) -> bool {
    if store.refs.contains_key(var) || store.members.contains_key(var) {
        return false;
    }
    match env.get(var) {
        Some(k) => k.closure.is_none(),
        // No value binding: only a declared-arm (contract) lane is left to save.
        None => store.contract.contains_key(var),
    }
}

/// Whether one recorded site — callee reference plus 0-based argument
/// `position` — is a **by-value** argument position of a callee with a known
/// signature (ADR-0070 conditions 1 and 2). The refusing answer is `false` for
/// every uncertainty — an unresolved name, an ambiguous one, a method, an
/// argument past the declared arity.
fn arg_is_by_value(cx: &Cx<'_>, callee: &NameRef, position: u32) -> bool {
    let position = position as usize;
    match cx.resolve_arg_function(callee) {
        // The catalog states this name's argument semantics; `Some(true)` is the
        // only admitting answer (`None` cannot occur — it is what made the name
        // resolve to `Builtin` — but is spelled out rather than assumed).
        FnResolution::Builtin => {
            steins_catalog::by_value_arg(&callee.raw, position) == Some(true)
        }
        FnResolution::User(fn_site) => {
            // The declaration answers condition 2 directly, and it is the cheap
            // half — asked first so a by-ref parameter refuses without the scope
            // lookup below. A variadic position refuses: the analysis does not
            // model spread/variadic binding (v1). An argument past the declared
            // arity is `func_get_args()` territory, with nothing to read.
            match cx.fn_decl(fn_site).params.get(position) {
                Some(p) if !p.by_ref && !p.variadic => {}
                _ => return false,
            }
            // Condition 4's callee half: a body that itself defeats value
            // tracking (`global $w`, `extract`, `$$v`, `eval`) may reach the
            // caller's binding by a route argument passing does not describe.
            matches!(cx.fn_scope(fn_site), Some((_, body)) if !body.poisoned)
        }
        FnResolution::Unknown => false,
    }
}

/// The trust stratum a resolved value carries (ADR-0052 §5 derivation clause): the
/// minimum over every env/heap fact consumed while resolving `value`. A literal, a
/// `new`/enum/const, or a fully-literal subtree is `Verified`; a bare `$var` takes
/// its env stratum; a property fetch takes the prop's stratum; an array literal or
/// a foldable call takes the min over its elements/arguments; a ternary the min of
/// its arms. Consulted only where resolution succeeded (so consumed vars were
/// proven), it stamps the derived binding with `min(inputs)`, closing the
/// laundering hazard the audit's `$pair = [$x, 99]` snippet names.
fn value_stratum(value: &ArgValue, env: &HashMap<String, Known>, store: Option<&Store>) -> Stratum {
    match value {
        ArgValue::Var(name) => env.get(name).map_or(Stratum::Verified, |k| k.stratum),
        // A property fetch takes its prop's stratum; with no store in scope (the
        // variable-call check) a prop fetch never resolves to a proof premise, so
        // `Verified` is the correct neutral answer.
        ArgValue::PropFetch { var, prop } => {
            store.map_or(Stratum::Verified, |s| s.prop_stratum(var, prop))
        }
        ArgValue::Array(items) => items
            .iter()
            .fold(Stratum::Verified, |acc, (_, v)| acc.min(value_stratum(v, env, store))),
        ArgValue::Call(_, args) => {
            args.iter().fold(Stratum::Verified, |acc, v| acc.min(value_stratum(v, env, store)))
        }
        ArgValue::Ternary { then_val, else_val, .. } => {
            value_stratum(then_val, env, store).min(value_stratum(else_val, env, store))
        }
        // `$a ?? $b` consumes both operands' facts (a widening join): `min` (§5).
        ArgValue::Coalesce(a, b) => {
            value_stratum(a, env, store).min(value_stratum(b, env, store))
        }
        // `$a . $b` consumes both operands' facts to build one string — the same
        // derivation clause: `min`. An asserted operand must not launder itself into
        // a verified result string.
        ArgValue::Concat(a, b) => {
            value_stratum(a, env, store).min(value_stratum(b, env, store))
        }
        _ => Stratum::Verified,
    }
}

// ---------------------------------------------------------------------------
// The dump surface (ADR-0053): requested introspection — an "answered question".
// Emitted mid-walk at the call position, reading (never binding) the walk's facts
// (§7 / §10); the plain per-scope pass only (`descent.is_none()`), so a site is
// dumped once. The explicit pair (D3) is recognized by resolved FQN; `var_dump`
// (D4) by the PHP fallback rule. Rendering shares the ONE speller (`spell_arms`).
// ---------------------------------------------------------------------------

/// The honest-incompleteness rendering (ADR-0053 §7): the dump knows nothing faithful
/// to spell about the expression. Never a guess, never a `mixed` pretense.
const DUMP_UNKNOWN: &str = "unknown";

/// The `debug.phpdoc-type` rendering when the contract carrier is empty (ADR-0053
/// §2): no declared `@param`/native envelope narrows the expression — never a
/// synthesized type.
const DUMP_NO_CONTRACT: &str = "no declared contract";

/// Which explicit dump the reserved FQN names (ADR-0053 §2).
#[derive(Clone, Copy, PartialEq, Eq)]
enum DumpFamily {
    /// `PHPStan\dumpType($e)` → `debug.type`: the trust-ordered best value fact.
    Type,
    /// `PHPStan\dumpPhpDocType($e)` → `debug.phpdoc-type`: the declared arm list.
    PhpDocType,
}

/// A rendered dump fact plus whether it rode an `Asserted`-stratum premise (ADR-0053
/// §2 / ADR-0052 §5): an asserted fact carries an explicit `(asserted)` marker so the
/// introspection surface never launders a docblock claim into a proven value.
struct DumpRendering {
    text: String,
    asserted: bool,
}

/// The resolved function FQN a call names (ADR-0001 name resolution), lowercase-
/// normalized and leading-`\`-stripped — **definition-insensitive** (no index lookup:
/// the reserved dump pair is recognized regardless of whether a userland definition
/// exists, ADR-0053 §5). Mirrors [`Cx::resolve_function`]'s name computation but
/// yields the FQN string rather than a resolution verdict.
fn resolved_fn_fqn(cx: &Cx, r: &NameRef) -> String {
    match r.kind {
        RefKind::FullyQualified => r.raw.to_ascii_lowercase(),
        RefKind::Qualified => {
            let ctx = cx.tree().ctx_at(r.offset);
            let first_len = r.raw.find('\\').unwrap_or(r.raw.len());
            let first = &r.raw[..first_len];
            let fqn = if let Some(t) = ctx.class_imports.get(&first.to_ascii_lowercase()) {
                format!("{t}{}", &r.raw[first_len..])
            } else if ctx.namespace.is_empty() {
                r.raw.clone()
            } else {
                format!("{}\\{}", ctx.namespace, r.raw)
            };
            fqn.to_ascii_lowercase()
        }
        RefKind::Unqualified => {
            let ctx = cx.tree().ctx_at(r.offset);
            let name = r.raw.to_ascii_lowercase();
            // A `use function` import resolves the name outright.
            if let Some(t) = ctx.fn_imports.get(&name) {
                return t.to_ascii_lowercase();
            }
            // Otherwise PHP tries the current-namespace candidate first; the global
            // fallback (bare `name`, no separator) never matches a reserved `PHPStan\`
            // FQN, so the namespace candidate is the only one recognition needs.
            if ctx.namespace.is_empty() {
                name
            } else {
                format!("{}\\{}", ctx.namespace.to_ascii_lowercase(), name)
            }
        }
        // ADR-0049 A8: `namespace\name` resolves against the enclosing namespace only
        // (no imports, no global fallback). In the global namespace it is `name` itself.
        RefKind::Relative => {
            let ctx = cx.tree().ctx_at(r.offset);
            let name = r.raw.to_ascii_lowercase();
            if ctx.namespace.is_empty() {
                name
            } else {
                format!("{}\\{}", ctx.namespace.to_ascii_lowercase(), name)
            }
        }
    }
}

/// Which explicit dump a `Callee::Function` call is, recognized by resolved FQN
/// (ADR-0053 §5): the reserved `PHPStan\` pair, definition-insensitive and
/// case-insensitive. `None` for every other call.
fn dump_family(cx: &Cx, call: &CallExpr) -> Option<DumpFamily> {
    let Callee::Function(_) = &call.receiver else { return None };
    let r = call.callee_ref.as_ref()?;
    match resolved_fn_fqn(cx, r).as_str() {
        DUMP_TYPE_FQN => Some(DumpFamily::Type),
        DUMP_PHPDOC_TYPE_FQN => Some(DumpFamily::PhpDocType),
        _ => None,
    }
}

/// Whether a call resolves to the **global** `var_dump()` under PHP's own name
/// resolution and fallback rule (ADR-0053 §5 / D4) — the `debug.var-dump` trigger.
/// The six enumerated legs:
///
/// - (a) `\var_dump($e)` — always (the fully-qualified global builtin);
/// - (b) unqualified `var_dump($e)` in the root namespace — always;
/// - (c) unqualified in `namespace Foo;` — only if `Foo\var_dump` is **provably
///   undefined** (the runtime falls back to global); a same-namespace homonym, an
///   ambiguous resolution, or a dam that leaves existence Unknown ⇒ **no dump** (a
///   missed dump is never an FP — silence is the free safe side);
/// - (d) `Foo\var_dump($e)` qualified, or `use function Foo\var_dump;` — never
///   (resolves elsewhere); a `use function var_dump;` importing the global is still
///   the global, so it dumps;
/// - (e) a *method* `$o->var_dump()` / `static::var_dump()` — never (a different
///   symbol space; `Callee::Method`/`Static`, not `Function`);
/// - (f) first-class callables and string callables — never (no argument expression
///   at the site to dump — handled by the arg-less guard in [`emit_dumps`]).
fn recognizes_var_dump(cx: &Cx, call: &CallExpr) -> bool {
    let Callee::Function(_) = &call.receiver else { return false };
    let Some(r) = call.callee_ref.as_ref() else { return false };
    name_reaches_global_var_dump(cx, r)
}

/// The name-resolution core of [`recognizes_var_dump`] (legs a–d; e/f are call-
/// shape questions its caller answers). Split out so the ADR-0070 survival
/// gate's dump-read recognition ([`is_dump_read_site`]) shares it verbatim.
fn name_reaches_global_var_dump(cx: &Cx, r: &NameRef) -> bool {
    match r.kind {
        // (a) `\var_dump` — the global builtin (a single segment, no namespace).
        RefKind::FullyQualified => r.raw.eq_ignore_ascii_case("var_dump"),
        // (d) `Foo\var_dump` — a qualified name resolves elsewhere.
        // A8: `namespace\var_dump` is relative to the current namespace with NO global
        // fallback, so it never denotes the global builtin — never a dump.
        RefKind::Qualified | RefKind::Relative => false,
        RefKind::Unqualified => {
            if !r.raw.eq_ignore_ascii_case("var_dump") {
                return false;
            }
            let ctx = cx.tree().ctx_at(r.offset);
            // (d) `use function ...\var_dump;` — resolves to the import target; only a
            // `use function var_dump;` naming the global is still the trigger.
            if let Some(t) = ctx.fn_imports.get("var_dump") {
                return t.eq_ignore_ascii_case("var_dump");
            }
            // (b) the root namespace: always the global.
            if ctx.namespace.is_empty() {
                return true;
            }
            // (c) in a namespace: only if `Ns\var_dump` is provably undefined (index
            // Absent) AND the dam is clear (dynamic code could otherwise mint it,
            // leaving existence Unknown — silence, the free safe side).
            let ns_fqn = format!("{}\\var_dump", ctx.namespace).to_ascii_lowercase();
            matches!(cx.index.resolve_function(&ns_fqn), Res::Absent) && cx.dam.is_clear()
        }
    }
}

/// A first-class callable `f(...)` (ADR-0049 §6 shape): a non-positional call with
/// all of `args`/`named_args` empty and no spread. It creates a `Closure`, not a
/// call — there is no argument expression at the site to dump (ADR-0053 §5 leg f),
/// and a reserved-name first-class callable is not a dumping call either.
fn is_first_class_callable(call: &CallExpr) -> bool {
    !call.positional_only && call.args.is_empty() && call.named_args.is_empty() && !call.has_spread
}

/// Render a value-domain [`Fact`] for the dump surface (ADR-0053 §7). Finite layers
/// (`Singleton`/`OneOf`) render **value-precisely** — the literal itself, not its
/// base type — because value-precision is exactly what the dump surface exists to
/// show (and what PHPStan's own constant types render: `5`, `false`, `'a'`). This
/// reverses ADR-0053 §9's earlier collapse-to-base pin for the dump path only (the
/// annotate/docblock renderer keeps the base-collapsed spelling, unchanged — see
/// [`render_finite_precise`]). The abstract layers (`Refined`/`General`) carry no
/// enumerable value set; they render as the honest phpdoc keyword ladder, reusing
/// the speller's own `preds_keyword` for refined strings so the two agree. A set with
/// no faithful spelling (an array member) renders as honest [`DUMP_UNKNOWN`].
fn render_dump_fact(fact: &Fact) -> String {
    if let Some(members) = fact.finite_members() {
        return render_finite_precise(members).unwrap_or_else(|| DUMP_UNKNOWN.to_owned());
    }
    match fact {
        Fact::Refined { base: Base::Int, refinement: Refinement::Int(r), nullable } => {
            with_null(int_range_keyword(*r), *nullable)
        }
        Fact::Refined { base: Base::String, refinement: Refinement::Str(p), nullable } => {
            with_null(steins_contract::spell::preds_keyword(*p), *nullable)
        }
        Fact::Refined { base, nullable, .. } => with_null(base_keyword(*base).to_owned(), *nullable),
        Fact::General { base, nullable } => with_null(base_keyword(*base).to_owned(), *nullable),
        // The abstract array stratum (ADR-0062 `Fact::Shape`, S2): routed through
        // the same ONE speller as the contract-arm and concrete-value paths.
        Fact::Shape { shape, nullable } => render_shape_fact(shape, *nullable),
        // Finite layers are handled above.
        Fact::Singleton(_) | Fact::OneOf(_) => unreachable!("finite_members handled above"),
    }
}

/// Spell an abstract [`ShapeFact`] for the dump surface (ADR-0062 §6, D4) — the
/// same array-vocabulary decision [`render_contract_arms`]'s `Shape` arm and
/// [`render_finite_precise`]'s concrete-array path make, run over the flow-side
/// fact form instead of the declared or concrete one. Every field/tail value
/// slot recurses through [`render_dump_fact`] itself (the domain's `Fact` is
/// recursive, ADR-0062 §3). [`describe_fact`] inherits it for the
/// `phpdoc.*-mismatch` messages ADR-0072 unlocked, so the diagnostic surface
/// and the dump surface name a shape fact identically.
fn render_shape_fact(shape: &ShapeFact, nullable: bool) -> String {
    use steins_domain::{KeyClass, Presence, Tail};

    let is_list = shape.is_list == Certainty::Yes;
    // The degenerate forms (A-G1) spell as the GENERIC vocabulary, not as a
    // brace shape with only a tail in it: `array`, `array<K, V>`, `list<T>` —
    // which is both what they lowered from and what they round-trip back to.
    // `array{...<int, string>}` would parse to the same fact, but nobody writes
    // it and PHPStan does not print it. `covers` does not gate this: neither
    // spelling prints a disjunctive-presence fact (A-G8 lives in the domain,
    // not the surface), so a fieldless covers-bearing fact still spells the
    // generic keyword — PHPStan's own `non-empty-array` for the
    // `array_key_exists(A) || array_key_exists(B)` join.
    if shape.fields.is_empty()
        && let Tail::Unsealed { key, value } = &shape.tail
    {
        let val = value.as_ref().map(|f| render_dump_fact(f));
        // A key class is printed only where it is narrower than `array-key`;
        // `spell_generic_array` drops it entirely for a list.
        let key_text = match key {
            KeyClass::ArrayKey => None,
            KeyClass::Int => Some("int"),
            KeyClass::Str => Some("string"),
        };
        // A key-agnostic, value-agnostic tail IS plain `array`, which the
        // speller produces from the two `None`s. A denotational `No` (never
        // `Yes`, handled above) is Phan's `associative-array` — the fact-lane
        // mirror of `to_shape_fact`'s `MapOf.not_list` seed.
        let not_list = shape.is_list == Certainty::No;
        let body = steins_contract::spell::spell_generic_array(
            is_list,
            not_list,
            shape.non_empty,
            key_text,
            val.as_deref(),
        );
        return with_null(body, nullable);
    }
    let fields: Vec<(VKey, bool, String)> = shape
        .fields
        .iter()
        .filter(|(_, p, _)| !matches!(p, Presence::Absent))
        .map(|(k, p, slot)| {
            let value = slot.as_ref().map_or_else(|| "mixed".to_owned(), |f| render_dump_fact(f));
            (k.clone(), p.is_required(), value)
        })
        .collect();
    let tail = match &shape.tail {
        Tail::Sealed => steins_contract::spell::ShapeTail::Sealed,
        Tail::Unsealed { key: KeyClass::ArrayKey, value: None } => {
            steins_contract::spell::ShapeTail::Untyped
        }
        Tail::Unsealed { key, value } => {
            let val_spelling = value.as_ref().map_or_else(|| "mixed".to_owned(), |f| render_dump_fact(f));
            let key_spelling = match key {
                KeyClass::ArrayKey => None,
                KeyClass::Int => Some("int".to_owned()),
                KeyClass::Str => Some("string".to_owned()),
            };
            steins_contract::spell::ShapeTail::Typed { key: key_spelling, value: val_spelling }
        }
    };
    let body = steins_contract::spell::spell_shape(is_list, shape.non_empty, &fields, &tail);
    with_null(body, nullable)
}

/// Value-precise spelling of a finite value set (`Singleton`/`OneOf` members) for
/// the dump surface: int/float/bool literals verbatim (`123`, `-5`, `123.0`,
/// `false`), string literals single-quoted through the shared speller's own literal
/// escaping ([`steins_contract::spell::string_literal`] — ONE speller, no second
/// string escaper), `null` as `null`, and — ADR-0062 §6 — an array member through
/// the shared D4 spelling ([`steins_contract::spell::spell_val`], the `spell_arms`
/// "value-side counterpart": a list value `list{…}`, everything else keyed
/// `array{…}`, nested arrays recursing). Members are sorted+deduped and joined with
/// `|` in the domain's canonical [`Val`] order (int, float, string, bool, null,
/// array) — order is immaterial to the harness (it sorts union atoms) but kept
/// stable for readable output. `None` only for an empty member slice (unreachable
/// from `Fact::finite_members`, which is never empty by construction) — every
/// `Val`, including an array, now has a faithful spelling here.
fn render_finite_precise(members: &[Val]) -> Option<String> {
    let mut vals = members.to_vec();
    vals.sort();
    vals.dedup();
    // Emit in the canonical spelling order `summarize_vals` fixes (int, float,
    // string, bool, null) — value-precise per member. Order is immaterial to the
    // harness (it sorts atoms) but kept stable and PHPStan-shaped for readable output.
    let mut parts: Vec<String> = Vec::with_capacity(vals.len());
    parts.extend(vals.iter().filter_map(|v| match v {
        Val::Int(n) => Some(n.to_string()),
        _ => None,
    }));
    parts.extend(vals.iter().filter_map(|v| match v {
        Val::Float(f) => Some(render_dump_float(*f)),
        _ => None,
    }));
    parts.extend(vals.iter().filter_map(|v| match v {
        Val::Str(s) => Some(steins_contract::spell::string_literal(s)),
        _ => None,
    }));
    // Both bool literals present ⟺ the whole `bool` type — PHPStan renders `bool`
    // there, not `false|true`. A single bool literal stays precise (`true`/`false`).
    match (vals.contains(&Val::Bool(true)), vals.contains(&Val::Bool(false))) {
        (true, true) => parts.push("bool".to_owned()),
        (true, false) => parts.push("true".to_owned()),
        (false, true) => parts.push("false".to_owned()),
        (false, false) => {}
    }
    if vals.contains(&Val::Null) {
        parts.push("null".to_owned());
    }
    // Array members: the D4 spelling, appended last (mirroring spell_arms's own
    // array-vocabulary placement — scalar members first, arrays after).
    parts.extend(vals.iter().filter_map(|v| match v {
        Val::Array(_) => Some(steins_contract::spell::spell_val(v)),
        _ => None,
    }));
    (!parts.is_empty()).then(|| parts.join("|"))
}

/// Render a float constant as PHPStan does: an integral value keeps a visible
/// fractional part (`123.0`, not `123`); every other value uses its shortest
/// round-tripping decimal (`3.14`, `1.5`).
fn render_dump_float(f: f64) -> String {
    if f.is_finite() && f.fract() == 0.0 { format!("{f:.1}") } else { f.to_string() }
}

/// Append `|null` when the fact admits null (the honest nullable spelling).
fn with_null(s: String, nullable: bool) -> String {
    if nullable { format!("{s}|null") } else { s }
}

/// The bare phpdoc keyword for a scalar base.
fn base_keyword(b: Base) -> &'static str {
    match b {
        Base::Int => "int",
        Base::Float => "float",
        Base::String => "string",
        Base::Bool => "bool",
    }
}

/// How an int interval spells on the dump surface — the shared
/// [`steins_contract::spell::int_range_keyword`], not a second copy of the ladder,
/// so the value-fact path and the contract-arm path cannot disagree about a range
/// (issue #90). [`describe_fact`] keeps its own keyword prose: a finding message
/// is not the dump surface and reads better with the phpdoc sugar.
fn int_range_keyword(r: IntRange) -> String {
    steins_contract::spell::int_range_keyword(r)
}

/// Render a narrowed contract-fact arm list (ADR-0052 §1 carrier) for the dump
/// surface. Scalar arms spell through the shared [`steins_contract::spell::spell_arms`];
/// a pure class/`null` arm list renders each class's **source-cased,
/// namespace-qualified** FQN (via [`Cx::class_display_fqn`], matching PHPStan and the
/// casing diagnostics use); anything else has no faithful spelling (`None` → the
/// caller falls to honest unknown).
fn render_contract_arms(cx: &Cx, arms: &[ContractArm]) -> Option<String> {
    let tys: Vec<ContractTy> = arms.iter().map(|a| a.ty.clone()).collect();
    if let Some(scalar) = steins_contract::spell::spell_arms(&tys) {
        return Some(scalar);
    }
    let mut parts = Vec::new();
    for ty in &tys {
        match ty {
            ContractTy::Class(n) => parts.push(cx.class_display_fqn(n)),
            ContractTy::Null => parts.push("null".to_owned()),
            // An array/generic/shape/callable/intersection arm has no faithful plain
            // spelling here — honest unknown rather than a guess (§7).
            _ => return None,
        }
    }
    (!parts.is_empty()).then(|| parts.join("|"))
}

/// The `Known::bound` provenance every S4 flow refinement stamps on a shape
/// fact. Two things read it: `annotate` (as prose) and [`shape_is_flow_refined`]
/// (as the dump-preference signal), which is why it is a constant rather than a
/// literal at each site.
const SHAPE_REFINED: &str = "narrowed array shape";

/// Has this shape fact been refined by the flow, rather than merely seeded from
/// a declaration?
///
/// Two independent signals, because the S4 operators leave different traces: a
/// **witnessed** field is presence promotion's own record (the presence stratum,
/// ADR-0062 §3), and the [`SHAPE_REFINED`] provenance covers the operators that
/// leave no structural mark — `set_non_empty`, `set_is_list`, a `mark_absent`
/// whose field a sealed tail then drops, and the collapse mint.
fn shape_is_flow_refined(fact: &Fact, known: &Known) -> bool {
    if known.bound.as_deref() == Some(SHAPE_REFINED) {
        return true;
    }
    let Fact::Shape { shape, .. } = fact else { return false };
    shape
        .fields
        .iter()
        .any(|(_, p, _)| matches!(p, steins_domain::Presence::Required { witnessed: true }))
}

/// The best value fact of a dump argument, in the trust order (ADR-0052 §1 /
/// ADR-0037): a proven value fact, else the object holder's exact class / membership,
/// else the narrowed declared-arm list, else honest unknown. Drives `debug.type` and
/// `debug.var-dump` (identical rendering, identical fact source, ADR-0053 §2).
fn best_dump_type(
    w: &WalkCx,
    folder: &mut dyn Folder,
    value: &ArgValue,
    env: &HashMap<String, Known>,
    store: &Store,
    // The dump argument's span start — the provenance anchor for the issue-#60
    // value-lane descent below (its findings are suppressed, so this surfaces only
    // in the bound params' internal provenance strings).
    span_start: u32,
) -> DumpRendering {
    let cx = w.cx;
    let poisoned = w.scope.poisoned;
    if let ArgValue::Var(name) = value {
        // 1. A proven value fact (the four-layer value domain), carrying its stratum.
        if let Some(known) = env.get(name)
            && let Some(fact) = &known.fact
        {
            // A-G1a, applied to spelling: declared fidelity the fact domain cannot
            // express (class-typed slots, exotic key contracts) lives in the ALIGNED
            // arm, and an UNREFINED shape fact is by construction a lossy lowering
            // of that one arm — so a freshly seeded binding spells from the arm
            // lane while both describe the same thing.
            //
            // **S4 flips it once flow refinement exists** (the S3 note at this site
            // said it would have to): a fact carrying a witnessed field, or one
            // minted by arm subtraction, states something the declared arm does
            // not, and spelling the arm would report the declaration back at a
            // caller who just narrowed it. [`shape_is_flow_refined`] is the test.
            if matches!(fact, Fact::Shape { .. })
                && !shape_is_flow_refined(fact, known)
                && let Some(arms) = store.contract_arms(name)
                && let Some(text) = render_contract_arms(cx, arms)
            {
                return DumpRendering {
                    text,
                    asserted: arms.iter().any(|a| a.stratum == Stratum::Asserted),
                };
            }
            return DumpRendering {
                text: render_dump_fact(fact),
                asserted: known.stratum == Stratum::Asserted,
            };
        }
        // 2. An object holder: the heap's exact class (else the lower-bound class),
        //    rendered source-cased and namespace-qualified (matching PHPStan).
        if let Some(obj) = store.obj_of(name) {
            return DumpRendering { text: cx.class_display_fqn(&obj.class), asserted: false };
        }
        // 2b. The N4 `Member{yes:[…]}` carrier (ADR-0052 §1): a var an `instanceof`
        //     guard bound to a class but that carries no heap object — e.g. a
        //     `MethodCall`-typed var narrowed by `if ($x instanceof Foo)`, which
        //     otherwise dumps as its coarse declared `CallLike` supertype. A
        //     single-yes-member set renders that one class (tighter than the
        //     contract arm); a multi-member yes-set has no single faithful class
        //     spelling here, so it falls through to the contract carrier. The `no`
        //     side never names a positive type. Bound at `Verified` (a runtime
        //     `instanceof` on the live branch) ⇒ never `(asserted)`.
        if let Some(m) = store.member_of(name)
            && let [only] = m.yes.as_slice()
        {
            return DumpRendering { text: cx.class_display_fqn(only), asserted: false };
        }
        // 3. The narrowed declared-arm list (contract carrier).
        if let Some(arms) = store.contract_arms(name)
            && let Some(text) = render_contract_arms(cx, arms)
        {
            return DumpRendering {
                text,
                asserted: arms.iter().any(|a| a.stratum == Stratum::Asserted),
            };
        }
        // 4. Honest unknown.
        return DumpRendering { text: DUMP_UNKNOWN.to_owned(), asserted: false };
    }
    // A constant-key read against an abstract shape (ADR-0062 §4, S3): the declared
    // field's value slot. Every no-fact outcome (an optional field, an unknown slot,
    // a declared absence) falls through to honest unknown — the read surface says
    // nothing it cannot spell, and emits nothing at all.
    if let ArgValue::OffsetRead { base, key } = value
        && let Some((read, stratum)) = shape_read_at(base, key, env, poisoned, cx.php_minor)
        && let Some(fact) = read.into_fact()
    {
        return DumpRendering {
            text: render_dump_fact(&fact),
            asserted: stratum == Stratum::Asserted,
        };
    }

    // A `??` chain (ADR-0052 §6 + ADR-0062 A-G11, S5): the spine's join under the
    // left-to-right `¬isset` premise ladder, which is where a KeyCover discharges.
    // Placed above the fold because a `??` is never a literal the folder can reach.
    if let ArgValue::Coalesce(a, b) = value
        && let Some((fact, stratum)) = eval_coalesce_fact(w, folder, a, b, env, Some(store))
    {
        return DumpRendering {
            text: render_dump_fact(&fact),
            asserted: stratum == Stratum::Asserted,
        };
    }

    // A depth-1 property fetch `$var->prop` (ADR-0052 §7, Gap B): the allocation-keyed
    // heap property fact (alias-correct by construction, ADR-0036). Escaped-then-swept
    // props carry no fact and fall through to honest unknown; a readonly prop survives.
    // Deeper chains (`$a->b->c`) lower to `Other`, never here — depth stays exactly 1.
    if let ArgValue::PropFetch { var, prop } = value
        && !poisoned
        && let Some(fact) = store.prop_fact(var, prop)
    {
        return DumpRendering {
            text: render_dump_fact(fact),
            asserted: store.prop_stratum(var, prop) == Stratum::Asserted,
        };
    }
    // A non-variable argument: a resolved literal / foldable value fact wins first
    // (folding is the floor below the return fact — a fully-literal call folds to a
    // Singleton, ADR-0056 §4). Stratum comes from the resolution itself so a fold
    // over an Asserted project-call summary stays Asserted (issue #127).
    if let Some((lit, strat)) = cx.resolve_literal_strat(value, env, poisoned, folder)
        && let Some(fact) = singleton_fact(&lit, cx.php_minor)
    {
        return DumpRendering {
            text: render_dump_fact(&fact),
            asserted: strat == Stratum::Asserted,
        };
    }
    // The MEMBER-WISE UNION FOLD (issue #74): the fold lane's own generalization —
    // an argument that is a bounded union of constants is enumerated, each
    // combination folded through the very seam a literal call takes, and the
    // answers composed. It sits with the fold it generalizes, above every type rung
    // below: this is a VALUE the real engine answered, member by member.
    if let ArgValue::Call(name, cargs) = value
        && let Some((fact, stratum, _prov)) = cx.try_union_fold(name, cargs, env, poisoned, folder)
    {
        return DumpRendering {
            text: render_dump_fact(&fact),
            asserted: stratum == Stratum::Asserted,
        };
    }
    // A project-function call in argument position (issue #60): the T0 return-fact
    // summary, sitting exactly where the assignment ladder puts it (fold > summary >
    // builtin envelope > arms). `summary_binds` keeps the two forms observably
    // identical: a summary the assignment would not bind falls through to the same
    // arms floor here. The descent's findings go to a scratch — the dump surface
    // reads facts, it never emits for the callee (emission stays the statement-level
    // descent's job) — and `descent: None` is sound because `emit_dumps` runs only
    // in the plain per-scope pass.
    if let ArgValue::Call(name, cargs) = value
        && !cargs.is_empty()
    {
        let mut scratch: Vec<Diagnostic> = Vec::new();
        if let Some(ReturnSummary { value: Some(sv), .. }) = project_call_summary(
            cx, folder, name, cargs, env, poisoned, span_start, None, &mut scratch,
        ) && summary_binds(&sv.fact)
        {
            return DumpRendering {
                text: render_dump_fact(&sv.fact),
                asserted: sv.stratum == Stratum::Asserted,
            };
        }
    }
    // The argument-dependent type rung (ADR-0061 §1) — `count`/`array_is_list` over
    // an abstract shape (ADR-0062 §4) — sits above the envelope here exactly as it
    // does at the assignment seam, and carries the argument's stratum.
    if let ArgValue::Call(name, args) = value
        && let Some((fact, stratum)) =
            shape_builtin_return_fact(cx, folder, name, args, env, Some(store), poisoned)
    {
        return DumpRendering {
            text: render_dump_fact(&fact),
            asserted: stratum == Stratum::Asserted,
        };
    }

    // A uniquely-resolved builtin call the fold could not reach: its reflected
    // return envelope / admitted refinement (ADR-0056 R1). Always Verified — a
    // native declaration read off the engine's own arginfo (§2).
    if let ArgValue::Call(name, _) = value
        && let Some(fact) = builtin_call_return_fact(cx, folder, name)
    {
        return DumpRendering { text: render_dump_fact(&fact), asserted: false };
    }
    // The DECLARED-RETURN FLOOR (ADR-0069): the rung strictly below, reached only
    // where the engine said nothing about this name. Always `(asserted)` — the row
    // is a catalog declaration, not a runtime answer, and the marker is how the dump
    // surface says which rung answered. Rendered through the arm speller, the same
    // one the project-call floor below uses, so a `string|false` row spells the way
    // the contract lane spells it rather than degrading to its base.
    if let ArgValue::Call(name, _) = value
        && let Some(arms) = builtin_return_floor(cx, name)
        && let Some(text) = render_contract_arms(cx, &arms)
    {
        return DumpRendering { text, asserted: true };
    }
    // The declared-return floor of an unresolved project call (issue #60): the
    // callee's `: string` is a fact the caller should see even when no summary
    // crossed — `unknown` where the source declares a return type reads as a
    // defect. Exactly the arm list the assignment form seeds into the contract
    // store, rendered through the same speller; a call with no declared return
    // type still falls through to honest unknown.
    if let ArgValue::Call(name, _) = value
        && let Some(arms) = call_return_arms_by_name(cx, folder, name)
        && let Some(text) = render_contract_arms(cx, &arms)
    {
        return DumpRendering {
            text,
            asserted: arms.iter().any(|a| a.stratum == Stratum::Asserted),
        };
    }
    DumpRendering { text: DUMP_UNKNOWN.to_owned(), asserted: false }
}

/// The declared-side view of a dump argument (ADR-0053 §2, `debug.phpdoc-type`): the
/// contract-fact arm list (the declared envelope as narrowed by guards), or
/// `no declared contract` when the carrier is empty — never a synthesized type.
fn best_dump_phpdoc_type(
    cx: &Cx,
    folder: &mut dyn Folder,
    value: &ArgValue,
    store: &Store,
) -> DumpRendering {
    if let ArgValue::Var(name) = value
        && let Some(arms) = store.contract_arms(name)
        && let Some(text) = render_contract_arms(cx, arms)
    {
        return DumpRendering {
            text,
            asserted: arms.iter().any(|a| a.stratum == Stratum::Asserted),
        };
    }
    // A project call in argument position (issue #60): its declared envelope is the
    // same arm list the assignment form would seed into the contract store — parity
    // between `dumpPhpDocType(f(…))` and `$x = f(…); dumpPhpDocType($x)`.
    if let ArgValue::Call(name, _) = value
        && let Some(arms) = call_return_arms_by_name(cx, folder, name)
        && let Some(text) = render_contract_arms(cx, &arms)
    {
        return DumpRendering {
            text,
            asserted: arms.iter().any(|a| a.stratum == Stratum::Asserted),
        };
    }
    // A BUILTIN call, through the ADR-0069 floor (issue #79). Same parity claim, one
    // rung lower: the row IS a declared contract, so the declared-side surface must
    // show it wherever the assignment form would seed it into the contract store.
    if let ArgValue::Call(name, _) = value
        && let Some(arms) = builtin_return_floor(cx, name)
        && let Some(text) = render_contract_arms(cx, &arms)
    {
        return DumpRendering { text, asserted: true };
    }
    DumpRendering { text: DUMP_NO_CONTRACT.to_owned(), asserted: false }
}

/// The message frame around a rendered dump fact (ADR-0053 §7: wording is not a
/// contract, the rendered fact is). Carries the `(asserted)` marker when the fact
/// rode a docblock/assert premise.
fn dump_message(label: &str, r: &DumpRendering) -> String {
    let marker = if r.asserted { " (asserted)" } else { "" };
    format!("{label}: {}{marker}", r.text)
}

/// Emit the dump reports a recognized call site produces (ADR-0053 §7): the explicit
/// pair (D3) by resolved FQN, `var_dump` (D4) by the PHP fallback rule. One report
/// per positional argument, in argument order; a zero-argument `dumpType()` still
/// reports (fail-level, "nothing to dump" — the committed call is a runtime fatal
/// either way). Reads the walk's facts at the call position; binds nothing (§10 §3).
///
/// `removal` is the enclosing statement's span when the dump call IS the whole
/// expression-statement (`StmtKind::Call` — the caller decides), and drives the
/// fix payload (ADR-0010, issue #114): the explicit pair's remedy is deleting
/// that statement, the one remedy ADR-0053 names, so each `debug.type` /
/// `debug.phpdoc-type` finding at such a site carries the deletion as a
/// first-class [`Fix`]. A dump embedded in a larger statement (`$y =
/// dumpType($x);`, `return dumpType($x);`, `echo dumpType($x);`) gets `None` —
/// deleting the whole statement there would delete the enclosing binding too,
/// which is no longer mechanical — and `debug.var-dump` never carries a fix: a
/// `var_dump()` is legal working PHP, so deleting it is a judgment call.
fn emit_dumps(
    w: &WalkCx,
    folder: &mut dyn Folder,
    call: &CallExpr,
    env: &HashMap<String, Known>,
    store: &Store,
    removal: Option<Span>,
    out: &mut Vec<Diagnostic>,
) {
    let cx = w.cx;
    if let Some(family) = dump_family(cx, call) {
        // A first-class callable `dumpType(...)` is a Closure, not a dumping call.
        if is_first_class_callable(call) {
            return;
        }
        let (id, label, call_name) = match family {
            DumpFamily::Type => (DEBUG_TYPE_ID, "dumped type", "PHPStan\\dumpType()"),
            DumpFamily::PhpDocType => {
                (DEBUG_PHPDOC_TYPE_ID, "dumped phpdoc type", "PHPStan\\dumpPhpDocType()")
            }
        };
        // The statement deletion, widened to swallow its whole line when the
        // statement stands alone on it (no blank gutter line left behind). A
        // multi-argument dump emits one finding per argument; each carries this
        // SAME edit — one statement, one deletion — and the CLI's plan builder
        // dedupes identical edits rather than treating them as an overlap.
        let fix = removal.map(|span| {
            let span = cx.tree().whole_line_span(span);
            Fix {
                title: "remove the dump statement",
                edits: vec![FixEdit {
                    path: cx.path().to_owned(),
                    start: span.start,
                    end: span.end,
                    replacement: String::new(),
                }],
            }
        });
        if call.args.is_empty() {
            // Zero-argument explicit dump: still fail-level (§7) — the runtime fatal
            // stands regardless of what (nothing) it would dump.
            let pos = cx.tree().position(call.span.start);
            out.push(Diagnostic {
                id,
                facet: None,
                fix,
                path: cx.path().to_owned(),
                line: pos.line,
                column: pos.column,
                message: format!("{call_name} called with no argument — nothing to dump"),
            });
            return;
        }
        for arg in &call.args {
            let rendering = match family {
                DumpFamily::Type => best_dump_type(w, folder, &arg.value, env, store, arg.span.start),
                DumpFamily::PhpDocType => best_dump_phpdoc_type(cx, folder, &arg.value, store),
            };
            let pos = cx.tree().position(arg.span.start);
            out.push(Diagnostic {
                id,
                facet: None,
                fix: fix.clone(),
                path: cx.path().to_owned(),
                line: pos.line,
                column: pos.column,
                message: dump_message(label, &rendering),
            });
        }
        return;
    }

    // var_dump (ADR-0053 D4): default-on, one `debug.type`-shaped report per argument,
    // same rendering and same fact source as the explicit `debug.type`. A first-class
    // callable and a zero-argument `var_dump()` dump nothing (§2/§5 leg f) — no
    // argument expression exists at the site.
    if recognizes_var_dump(cx, call) {
        if is_first_class_callable(call) || call.args.is_empty() {
            return;
        }
        for arg in &call.args {
            let rendering = best_dump_type(w, folder, &arg.value, env, store, arg.span.start);
            let pos = cx.tree().position(arg.span.start);
            out.push(Diagnostic {
                id: DEBUG_VAR_DUMP_ID,
                facet: None,
                fix: None,
                path: cx.path().to_owned(),
                line: pos.line,
                column: pos.column,
                message: dump_message("dumped type", &rendering),
            });
        }
    }
}

/// Whether the statement starting at `stmt_start` is itself a **declaration**
/// (function / class / interface / enum / trait). Declarations lower to
/// [`StmtKind::Barrier`] in the trace IR, so the kind alone cannot say; the
/// tree's declaration indexes can — a named function's or class-like's name span
/// falls inside the declaration statement's own span, and inside no other
/// `Barrier`'s (a declaration nested in an `if`/loop sits under a `StmtKind::If`
/// / `Opaque` statement, never a `Barrier`, so the containment test is exact for
/// the caller's Barrier-gated use).
///
/// Why it matters (ADR-0074 §6: "declaration statements are inert at the
/// emitter"): a docblock a declaration owns is a contract surface, never a
/// statement trigger. The shared adoption query (`stmt_docblock`, ADR-0073's
/// tag-agnostic rule) does NOT exclude declaration-owned docblocks — a
/// docblock before a `function`/`class`/`interface`/`enum`/`trait` declaration
/// statement IS returned by it — so this guard is load-bearing for all five
/// declaration kinds; the trace-specific exclusion lives here, with the trace
/// emitter, keeping the query shared.
fn stmt_is_declaration(tree: &SourceTree, span: Span) -> bool {
    let within = |s: Span| span.start <= s.start && s.start < span.end;
    tree.functions().iter().any(|f| within(f.span))
        || tree.classes().iter().any(|c| within(c.span))
}

/// The docblock the statement adopts as a trace-annotation trigger (ADR-0074
/// §6), or `None` for every deliberate silence: a docblock the statement did
/// not adopt under the shared statement-adoption rule (`stmt_docblock`, the
/// same query the inline-`@var` cast reads — nothing but whitespace between
/// the nearest preceding comment trivium, which must be a docblock, and the
/// statement), and a declaration statement's docblock (a contract surface,
/// inert at the emitter for all five declaration kinds — see
/// [`stmt_is_declaration`]). Resolved at the top of the walk's per-statement
/// step; the answer is flushed by [`emit_trace_annotations`] at the step's
/// exit.
fn adopted_trace_docblock<'a>(w: &'a WalkCx, stmt: &Stmt) -> Option<&'a Comment> {
    let tree = w.cx.tree();
    let comment = tree.stmt_docblock(stmt.span.start)?;
    // Only a `Barrier` can be a declaration statement (see
    // `stmt_is_declaration`), so every other kind skips the index scan outright.
    if matches!(stmt.kind, StmtKind::Barrier) && stmt_is_declaration(tree, stmt.span) {
        return None;
    }
    Some(comment)
}

/// Emit the trace-annotation reports a statement's adopted docblock asks for
/// (ADR-0074 §5/§6): a `/** @psalm-trace $x */` directly above the statement is
/// the docblock spelling of `PHPStan\dumpType($x)` — the SAME question, answered
/// through the same machinery ([`best_dump_type`] → the one renderer, honoring
/// the `(asserted)` stratum marker) against the statement's **EXIT facts** (§5,
/// Psalm's semantics: the annotation is "applied to the next statement" and
/// reports what that statement leaves behind — what `dumpType($x)` would report
/// were it the following statement), and reported at the TAG's own position
/// (the question's own text, like a dump call reports at the call). A comma
/// list (`@psalm-trace $a, $b`, §7) arrives from the scanner as one tag per
/// named variable in source order, so this loop emits one diagnostic per
/// variable — each rendered independently (one variable's `unknown` never
/// perturbs its neighbors), all at the tag's position. Reads facts, binds
/// nothing (§9 transparency).
///
/// `pending` is the adoption [`adopted_trace_docblock`] resolved at the step's
/// top — `None` (nothing adopted, or a descent pass) flushes nothing. The walk
/// calls this exactly once per statement, on whichever exit the statement
/// takes: the divergent `return`s (a `return`/`throw`/`exit` under the
/// annotation still answers, §5) or the common bottom of the iteration. A
/// named variable with no fact renders honest `unknown` — a missing answer is
/// incompleteness, never silence.
///
/// Runs in the plain per-scope pass only (the capture site gates on
/// `descent.is_none()` exactly like [`emit_dumps`]'s call site), so an
/// annotated site emits once — never re-reported per caller under a binding
/// descent.
fn emit_trace_annotations(
    w: &WalkCx,
    folder: &mut dyn Folder,
    pending: Option<&Comment>,
    stmt: &Stmt,
    env: &HashMap<String, Known>,
    store: &Store,
    out: &mut Vec<Diagnostic>,
) {
    let cx = w.cx;
    let Some(comment) = pending else { return };
    for tag in scan_docblock(&comment.text) {
        if tag.kind != TagKind::TraceTag {
            continue;
        }
        let Some(var) = tag.var_name.as_deref() else { continue };
        let name = var.trim_start_matches('$');
        let rendering = best_dump_type(
            w,
            folder,
            &ArgValue::Var(name.to_owned()),
            env,
            store,
            stmt.span.start,
        );
        // The diagnostic sits at the tag's own line/column: the tag span is
        // docblock-relative (`comment.text` is the exact source substring at
        // `comment.span`), so the comment's file span start maps it back.
        let pos = cx.tree().position(comment.span.start + tag.tag_span.start);
        out.push(Diagnostic {
            id: DEBUG_TRACE_ID,
            facet: None,
            fix: None,
            path: cx.path().to_owned(),
            line: pos.line,
            column: pos.column,
            // The label names the variable so the list form stays unambiguous;
            // the rendered fact after the final ": " is the parity-pinned
            // part, the frame wording is not a contract (§5).
            message: dump_message(&format!("traced type of {var}"), &rendering),
        });
    }
}

/// The resolved FQN of `PHPStan\Testing\assertType` (oracle idea B), lowercase-
/// normalized — the assertType harness recognizer key, matched exactly like the
/// dump family's [`DUMP_FQNS`], by resolved FQN (definition- and case-insensitive).
const ASSERT_TYPE_FQN: &str = "phpstan\\testing\\asserttype";

/// Harness-only (oracle idea B): when the assertType sink is installed
/// ([`collect_assert_types`]), recognize a `PHPStan\Testing\assertType('T', $e)` call
/// by resolved FQN and record (expected string, Steins rendering of `$e`) — the
/// rendering shares the D3 dump path ([`best_dump_type`]) verbatim. A no-op when the
/// sink is absent (every normal check), so the check surface is byte-identical.
/// Runs in the plain per-scope pass only (like [`emit_dumps`]), so a site is recorded
/// once — never re-observed under a binding descent.
fn emit_asserts(
    w: &WalkCx,
    folder: &mut dyn Folder,
    call: &CallExpr,
    env: &HashMap<String, Known>,
    store: &Store,
) {
    // Fast path: no sink ⇒ not the harness ⇒ assertType is an ordinary call.
    if ASSERT_SINK.with(|s| s.borrow().is_none()) {
        return;
    }
    let cx = w.cx;
    let Callee::Function(_) = &call.receiver else { return };
    let Some(r) = call.callee_ref.as_ref() else { return };
    if resolved_fn_fqn(cx, r) != ASSERT_TYPE_FQN {
        return;
    }
    // `assertType('Expected', $expr)` needs both positional arguments; a first-class
    // callable or a mis-arity call records nothing (there is no fact pair to observe).
    if call.args.len() < 2 {
        return;
    }
    let expected = assert_expected_string(cx, &call.args[0].value, env, w.scope.poisoned, folder);
    let rendering = best_dump_type(w, folder, &call.args[1].value, env, store, call.args[1].span.start);
    let pos = cx.tree().position(call.span.start);
    let obs = AssertObservation {
        path: cx.path().to_owned(),
        line: pos.line,
        column: pos.column,
        expected,
        got: rendering.text,
        asserted: rendering.asserted,
    };
    ASSERT_SINK.with(|s| {
        if let Some(buf) = s.borrow_mut().as_mut() {
            buf.push(obs);
        }
    });
}

/// The expected-type string an `assertType` first argument names: a plain string
/// literal, or a value Steins can fold to one; `None` for a `::class`/concatenation
/// the fold cannot reduce (the harness counts those as skipped, never a false match).
fn assert_expected_string(
    cx: &Cx,
    value: &ArgValue,
    env: &HashMap<String, Known>,
    poisoned: bool,
    folder: &mut dyn Folder,
) -> Option<String> {
    if let ArgValue::Str(s) = value {
        return Some(s.clone());
    }
    match cx.resolve_literal(value, env, poisoned, folder) {
        Some(ArgValue::Str(s)) => Some(s),
        _ => None,
    }
}

/// Apply a plain `$var = <value>;` assignment to the env (extracted from the walk).
/// `return_arms` is the declared return floor resolved at the call site **before**
/// this assignment may unbind its own target (self-assign `$o = $o->m(1)`).
#[allow(clippy::too_many_arguments)]
fn apply_assign(
    w: &WalkCx,
    folder: &mut dyn Folder,
    var: &str,
    value: &ArgValue,
    call: Option<&CallExpr>,
    span_start: u32,
    env: &mut HashMap<String, Known>,
    store: &mut Store,
    facts: &mut Option<&mut Vec<LineFact>>,
    summary: Option<&ReturnSummary>,
    return_arms: Option<&[ContractArm]>,
    out: &mut Vec<Diagnostic>,
) {
    let cx = w.cx;
    let line = cx.tree().position(span_start).line;

    // A ternary rvalue `$x = $c ? A : B` is a conditional value (ADR-0031): the
    // walk evaluates the guard and resolves to the chosen arm, or (undecided) a
    // `OneOf` of the two arms when both are literal, else unknown.
    if let ArgValue::Ternary { cond, then_val, else_val } = value {
        match eval_ternary_fact(w, folder, cond, then_val, else_val, env, store) {
            Some(fact) => {
                if let (Fact::Singleton(lit), Some(facts)) = (&fact, facts.as_deref_mut()) {
                    facts.push(LineFact {
                        line,
                        kind: FactKind::Value { var: var.to_owned(), rendered: render_val(lit) },
                    });
                }
                // Derivation clause: the arm chosen is one of the two operands, so
                // the result stratum is `min` over the arms (either could be the
                // taken one under a `Maybe` verdict).
                let strat = value_stratum(then_val, env, Some(&*store)).min(value_stratum(else_val, env, Some(&*store)));
                env.insert(var.to_owned(), Known::value_strat(fact, line, None, strat));
                store.unbind(var);
            }
            None => {
                env.remove(var);
                store.unbind(var);
            }
        }
        return;
    }

    // A closure value `$f = fn(...) => …;` / `$f = strtolower(...);` (ADR-0033):
    // record a `ClosureVal` with its by-value capture snapshot taken from the
    // CURRENT (definition-site) env — the semantically correct PHP by-value
    // capture. A poisoned scope drops it (no reliable capture snapshot).
    if let ArgValue::Closure(cref) = value {
        env.remove(var);
        store.unbind(var);
        if w.scope.poisoned {
            return;
        }
        // A closure that captures an object escapes it (ADR-0036): the closure holds
        // the object handle, so an unknown call may reach and mutate it.
        if let steins_syntax::ClosureRef::Anonymous { captures, .. } = cref {
            for name in captures {
                store.mark_escaped(name);
            }
        }
        if let Some(cv) = build_closure_val(cx, cref, line, env) {
            env.insert(var.to_owned(), Known::closure(cv, line));
        }
        return;
    }

    match value {
        // `$x = new Foo(args)` (ADR-0036): a fresh allocation, class from resolution,
        // props populated from promoted ctor params + literal defaults.
        ArgValue::New(class_ref, args, named) => {
            env.remove(var);
            store.unbind(var);
            if !w.scope.poisoned {
                let class = cx.class_fqn(class_ref);
                let id = build_new_object(w, folder, &class, args, named, env, store);
                store.refs.insert(var.to_owned(), id);
                if let Some(facts) = facts.as_deref_mut() {
                    facts.push(LineFact {
                        line,
                        kind: FactKind::ExactClass { var: var.to_owned(), class },
                    });
                }
            }
        }
        // `$b = $a` where `$a` holds an object (ADR-0036 aliasing): copy the ObjRef
        // (shared id), so a later write through either alias is visible via both.
        ArgValue::Var(src) if !w.scope.poisoned && store.is_bound(src) => {
            env.remove(var);
            let id = store.id_of(src).expect("bound var has an id");
            store.refs.insert(var.to_owned(), id);
        }
        // `clone $a` (ADR-0036 adversarial #1): a NEW id with a COPY of the source
        // object's props (PHP shallow clone) — post-clone writes stay isolated.
        ArgValue::Clone(src) if !w.scope.poisoned && store.is_bound(src) => {
            // Read the source id BEFORE unbinding `var`. For a self-clone
            // `$a = clone $a` we have `var == src`, so `store.unbind(var)` would
            // also drop `src`'s binding and make `id_of(src)` return `None`. PHP
            // evaluates the rvalue (`clone $a`) against the current value first
            // and only then assigns, so the source id is the pre-assignment one;
            // capturing it here keeps the guard's `is_bound(src)` invariant true
            // at the `.expect` for every `var`/`src` pairing.
            let src_id = store.id_of(src).expect("bound var has an id");
            env.remove(var);
            store.unbind(var);
            if let Some(src_obj) = store.heap.get(&src_id) {
                let mut copy = src_obj.clone();
                copy.escaped = false; // a fresh, local clone has not escaped
                let id = w.fresh_id();
                store.heap.insert(id, copy);
                store.refs.insert(var.to_owned(), id);
            }
        }
        // `$x = $o->p` (ADR-0036): a property read flows the prop's fact into `$x`,
        // carrying the prop's stratum (derivation clause — heap reads).
        ArgValue::PropFetch { var: recv, prop } if !w.scope.poisoned => {
            env.remove(var);
            store.unbind(var);
            if let Some(fact) = store.prop_fact(recv, prop).cloned() {
                let strat = store.prop_stratum(recv, prop);
                env.insert(var.to_owned(), Known::value_strat(fact, line, None, strat));
            }
        }
        // `$x = $base[k]` where `$base` carries an abstract shape (ADR-0062 §4's
        // read row, S3): a constant-key read takes the declared field's value slot.
        // A key with no fact behind it (an optional field, an unknown slot, a
        // declared absence) binds NOTHING — never value∪null (A-G9: missing-ness is
        // the strict leg's finding, never a type pollution). The concrete-base read
        // is unchanged (it never bound a fact here either); this arm only adds the
        // abstract stratum, and the whitelisted `offset.missing` judgment for this
        // same statement has already run in the walk (1z) independently.
        ArgValue::OffsetRead { base, key } => {
            // Resolve against the PRE-assignment env: PHP evaluates the rvalue
            // first, so a self-read `$a = $a['k']` still reads the old `$a`.
            let read = shape_read_at(base, key, env, w.scope.poisoned, cx.php_minor)
                .and_then(|(read, strat)| Some((read.into_fact()?, strat)));
            env.remove(var);
            store.unbind(var);
            if let Some((fact, strat)) = read {
                env.insert(var.to_owned(), Known::value_strat(fact, line, None, strat));
            }
        }
        // `$x = $a ?? $b` (ADR-0052 §6): the value is the non-null part of `$a`
        // unioned with `$b` — `clear_null(fact($a)) join fact($b)`. A fact only when
        // BOTH operands are visible facts; an unseen operand (an array offset, an
        // unknown call) yields no fact, so `??` never manufactures certainty for a
        // value it cannot spell. The join widens, so it can only *lose* precision
        // (never fire a proof the concrete arms would not) — the FP-safe side.
        ArgValue::Coalesce(a, b) => {
            // The stratum is the evaluator's own `min` over the spine's arms — the
            // same derivation clause the two-operand form used, extended to a
            // projection arm, whose stratum comes from the base's shape fact rather
            // than from `value_stratum`'s syntactic reading.
            match eval_coalesce_fact(w, folder, a, b, env, Some(&*store)) {
                Some((fact, strat)) => {
                    env.insert(var.to_owned(), Known::value_strat(fact, line, None, strat));
                    store.unbind(var);
                }
                None => {
                    env.remove(var);
                    store.unbind(var);
                }
            }
        }
        _ => match cx
            .resolve_literal_strat_ex(
                value,
                env,
                w.scope.poisoned,
                folder,
                None,
                Some(&mut *out),
            )
            .and_then(|(lit, strat)| singleton_fact(&lit, cx.php_minor).map(|f| (lit, f, strat)))
        {
            Some((lit, fact, strat)) => {
                if let Some(facts) = facts.as_deref_mut() {
                    facts.push(LineFact {
                        line,
                        kind: FactKind::Value { var: var.to_owned(), rendered: lit.render() },
                    });
                }
                // Derivation clause: folds and array composition resolve through
                // `resolve_literal`, consuming env facts and nested project-call
                // summary strata (issue #127) — stamp that min, not a re-read of
                // the syntactic Call tree alone. Nested project-call descents for
                // fold args emit through `out` so binding-specific findings under
                // `strtoupper(g(1))` are not discarded (issue #127 review).
                env.insert(var.to_owned(), Known::value_strat(fact, line, None, strat));
                store.unbind(var);
            }
            // `$x = is_int($y)` and kin: the fold could not reach it, so seed the
            // uniquely-resolved builtin's reflected return envelope / admitted
            // refinement (ADR-0056 R1). Enters at `Verified` — a native declaration
            // (§2). A more-precise fold above already returned; this is the floor.
            None => match value {
                // The MEMBER-WISE UNION FOLD (issue #74): still the fold lane, one
                // rung wider — an argument that is a bounded union of constants is
                // enumerated and every combination answered by the real engine. It
                // therefore binds where a folded literal binds, above every type
                // rung below, and carries the input union's own stratum (N2's min),
                // not the engine's `Verified`.
                ArgValue::Call(name, args)
                    if let Some((fact, strat, prov)) =
                        cx.try_union_fold(name, args, env, w.scope.poisoned, folder) =>
                {
                    // A product whose members all agreed composes to a `Singleton`
                    // — a proven value, and the margin says so exactly as it does
                    // for the single-tuple fold.
                    if let (Fact::Singleton(v), Some(facts)) = (&fact, facts.as_deref_mut()) {
                        facts.push(LineFact {
                            line,
                            kind: FactKind::Value {
                                var: var.to_owned(),
                                rendered: render_val(v),
                            },
                        });
                    }
                    env.insert(var.to_owned(), Known::value_strat(fact, line, Some(prov), strat));
                    store.unbind(var);
                }
                // The type rung above the envelope (ADR-0061 §1): a rule that reads
                // the call's ARGUMENT facts — here ADR-0062 §4's `count`/
                // `array_is_list` shape transfers. Enters at the argument's own
                // stratum (§3's derivation clause), not `Verified`.
                ArgValue::Call(name, args)
                    if let Some((fact, strat)) = shape_builtin_return_fact(
                        cx,
                        folder,
                        name,
                        args,
                        env,
                        Some(&*store),
                        w.scope.poisoned,
                    ) =>
                {
                    env.insert(var.to_owned(), Known::value_strat(fact, line, None, strat));
                    store.unbind(var);
                }
                ArgValue::Call(name, _)
                    if !w.scope.poisoned
                        && let Some(fact) = builtin_call_return_fact(cx, folder, name) =>
                {
                    env.insert(var.to_owned(), Known::value(fact, line, None));
                    store.unbind(var);
                }
                // The DECLARED-RETURN FLOOR (ADR-0069): strictly below the rung
                // above, reached only where the engine said nothing about this name.
                // Enters `Asserted` — a catalog declaration, not a runtime answer —
                // so the proof layer's all-Verified premise rule keeps every finding
                // off it, and the derivation clause carries that down every step.
                //
                // BOTH carriers are seeded, as the `@param` entry seeding does with
                // `seed_contract_arms` + `seed_shape_fact`: the arm lane holds the
                // declaration itself (so a `string|false` row survives to both dump
                // surfaces and to whatever the arm lane learns to subtract), and the
                // value lane holds the one fact the arms denote where they denote
                // one. A multi-arm row has no single fact and lives in the arm lane
                // alone — observably identical to a hand-written `@param string|false`.
                ArgValue::Call(name, _)
                    if !w.scope.poisoned && let Some(arms) = builtin_return_floor(cx, name) =>
                {
                    store.unbind(var);
                    match floor_value_fact(&arms) {
                        Some(fact) => {
                            env.insert(
                                var.to_owned(),
                                Known::value_strat(
                                    fact,
                                    line,
                                    Some(CATALOG_FLOOR.to_owned()),
                                    Stratum::Asserted,
                                ),
                            );
                        }
                        None => {
                            env.remove(var);
                        }
                    }
                    store.contract.insert(var.to_owned(), arms);
                }
                // The return-fact SUMMARY, then the arm FLOOR (ADR-0057 amendment T0 /
                // ADR-0052 §9). `unbind` first (it voids any stale arm lane on `var`).
                // The summary is the value floor above the declared arms (A1): when it
                // carries a bindable value fact (strictly more precise than a bare base,
                // A3), it binds as `var`'s VALUE fact at its joined stratum — sitting
                // exactly where a folded literal would (the `resolve_const_fn`
                // degenerate case above is disjoint by arity: it is zero-arg only, the
                // summary descends on positional args ≥ 1). Otherwise the summary
                // degraded to the floor and the declared arms stand — observably
                // identical to no summary.
                _ => {
                    env.remove(var);
                    store.unbind(var);
                    if let Some(ReturnSummary { value: Some(sv), .. }) = summary
                        && summary_binds(&sv.fact)
                    {
                        env.insert(
                            var.to_owned(),
                            Known::value_strat(sv.fact.clone(), line, None, sv.stratum),
                        );
                    } else if let Some(arms) = return_arms {
                        // Prefer arms captured at resolution (before this unbind),
                        // so method self-assign keeps the declared floor.
                        store.contract.insert(var.to_owned(), arms.to_vec());
                    } else if let Some(c) = call
                        && let Some(arms) = call_return_arms(
                            cx,
                            c,
                            store,
                            w.this_exact,
                            w.enclosing_class,
                            w.scope.poisoned,
                        )
                    {
                        // Fallback: free-function / non-self-assign paths.
                        store.contract.insert(var.to_owned(), arms);
                    }
                }
            },
        },
    }
}

/// The fact of a `??` chain (ADR-0052 §6, extended by ADR-0062 A-G11 / S5).
///
/// **The join law is unchanged**: `clear_null(fact($a)) join fact($b)`, folded
/// right-to-left over the whole spine (`??` is right-associative, so `$a ?? $b ??
/// $c` is one chain of three arms, not two nested pairs). Every arm must produce a
/// fact — an operand the domain cannot spell yields `None` for the whole
/// expression, so `??` never manufactures certainty for a value it cannot see —
/// and every arm but the last contributes only its non-null part, because that is
/// the only case in which `??` takes it.
///
/// **What S5 adds is the premise ladder** (A-G11). A `??` arm is reached only when
/// every arm to its left failed `isset`, so a pure depth-1 projection arm
/// `$x['k']` contributes the premise `¬isset($x['k'])` to everything after it.
/// Those premises are what [`ShapeFact::cover_proves`] consumes: a KeyCover
/// recorded by `isset($x['a']) || isset($x['b'])` plus `¬isset($x['a'])` proves
/// `$x['b']` present, so the last arm — otherwise an undischarged optional read
/// with no fact — becomes a `Present` read and the chain gets a value.
///
/// **Any other arm form invalidates the ladder.** A call may write through a
/// reference or a global and make an earlier `¬isset` stale, so an arm that is not
/// a pure projection contributes no premise *and drops every accumulated one*
/// (A-G11's conservatism, and the reason `$x['a'] ?? f() ?? $x['b']` discharges
/// nothing).
fn eval_coalesce_fact(
    w: &WalkCx,
    folder: &mut dyn Folder,
    a: &ArgValue,
    b: &ArgValue,
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<(Fact, Stratum)> {
    let (poisoned, php_minor) = (w.scope.poisoned, w.cx.php_minor);
    let mut arms: Vec<&ArgValue> = Vec::new();
    flatten_coalesce(a, &mut arms);
    flatten_coalesce(b, &mut arms);
    let last = arms.len() - 1;

    let mut premises: Vec<(String, VKey)> = Vec::new();
    let mut parts: Vec<(Fact, Stratum)> = Vec::with_capacity(arms.len());
    for (i, arm) in arms.iter().enumerate() {
        let projection = coalesce_projection(arm, env, poisoned, php_minor);
        let (part, settled) = match &projection {
            Some((var, key)) => {
                let (f, s, settled) = coalesce_arm_fact(var, key, env, &premises, i == last)?;
                (Some((f, s)), settled)
            }
            None => (
                arg_value_fact(w, folder, arm, env).map(|f| (f, value_stratum(arm, env, store))),
                false,
            ),
        };
        parts.push(part?);
        // A projection arm the shape proves present AND non-null is the value: `??`
        // never evaluates anything to its right, so the chain ends here and the
        // arms after it contribute nothing. (Only the shape lane short-circuits;
        // the other operand forms keep their join verbatim.)
        if settled {
            break;
        }
        match projection {
            Some(p) => premises.push(p),
            None => premises.clear(),
        }
    }

    // Derivation clause (ADR-0052 §5): the value is one of the arms, so the whole
    // expression is no stronger than the weakest of them.
    let (mut acc, mut stratum) = parts.pop()?;
    while let Some((fact, s)) = parts.pop() {
        stratum = stratum.min(s);
        // A provably-null arm (nothing survives `clear_null`) can never be the
        // value: it contributes nothing, exactly as the two-operand law had it.
        if let Some(nonnull) = clear_null(&fact) {
            acc = nonnull.join(&acc)?;
        }
    }
    Some((acc, stratum))
}

/// Flatten a `??` spine into its arms, left to right. Both sides are walked: `??`
/// is right-associative, so the nesting is normally on the right, but explicit
/// parentheses (`($a ?? $b) ?? $c`) nest left and mean the same chain.
fn flatten_coalesce<'a>(v: &'a ArgValue, out: &mut Vec<&'a ArgValue>) {
    match v {
        ArgValue::Coalesce(a, b) => {
            flatten_coalesce(a, out);
            flatten_coalesce(b, out);
        }
        _ => out.push(v),
    }
}

/// Is this `??` arm a **pure depth-1 projection** `$x[k]` with a resolvable
/// constant key (A-G11's premise carrier)? The key resolution is the offset
/// family's own ([`offset_operand_fact`] + [`offset_key_of`]), so a premise and a
/// cover can never disagree about which key they mean.
///
/// Depth is exactly one and the base is exactly a binding: `$x['a']['b']` and
/// `$this->x['a']` are not premise carriers, and by falling through to the
/// non-projection path they *invalidate* the ladder rather than extending it.
fn coalesce_projection(
    arm: &ArgValue,
    env: &HashMap<String, Known>,
    poisoned: bool,
    php_minor: Option<(u16, u16)>,
) -> Option<(String, VKey)> {
    let ArgValue::OffsetRead { base, key } = arm else { return None };
    let ArgValue::Var(name) = base.as_ref() else { return None };
    let Some(Fact::Singleton(key_val)) = offset_operand_fact(key, env, poisoned, php_minor) else {
        return None;
    };
    Some((name.clone(), offset_key_of(&key_val)?))
}

/// The fact a projection arm `$var[key]` contributes to its `??` chain, the
/// stratum it inherits from the base's shape fact (the derivation clause: the read
/// consumes that fact, so it is never stronger than it — always `Asserted`), and
/// whether the arm **settles** the chain (is proven to be the value, so `??` never
/// evaluates anything to its right).
///
/// The two positions are genuinely different questions:
///
/// * a **non-final** arm is used only when `isset` holds of it, so presence does
///   not have to be proved — missing means fall-through — and the arm yields its
///   declared slot ([`ShapeRead::taken_fact`]);
/// * the **final** arm is the value whenever everything to its left fell through,
///   so it must be *proved* present. A declared-`Required` field proves it
///   outright; for an optional one, A-G11's cover discharge is the only thing that
///   can, and `absent` is the accumulated `¬isset` ladder over this same base.
fn coalesce_arm_fact(
    var: &str,
    key: &VKey,
    env: &HashMap<String, Known>,
    premises: &[(String, VKey)],
    final_arm: bool,
) -> Option<(Fact, Stratum, bool)> {
    let known = env.get(var)?;
    let Some(Fact::Shape { shape, nullable: false }) = &known.fact else { return None };
    let read = shape_read(shape, key);
    // Present AND non-null is exactly PHP's `isset`, so this arm is taken for every
    // value the shape admits — the same test in both positions, harmless on the
    // last arm and a short-circuit before it.
    let settled = matches!(&read, ShapeRead::Present(Some(f)) if f.is_null().is_no());
    if !final_arm {
        return read.taken_fact().map(|f| (f, known.stratum, settled));
    }
    if let ShapeRead::Present(Some(f)) = read {
        return Some((f, known.stratum, settled));
    }
    let absent: Vec<VKey> =
        premises.iter().filter(|(v, _)| v == var).map(|(_, k)| k.clone()).collect();
    let flavor = cover_discharges(shape, key, &absent)?;
    let slot = shape.field(key).and_then(|(_, _, s)| s.as_deref().cloned())?;
    match flavor {
        // "at least one covered key is present AND non-null": every other member
        // failed `isset`, so this one carries the claim — present, and not null.
        CoverFlavor::Isset => clear_null(&slot).map(|f| (f, known.stratum, true)),
        // "at least one covered key EXISTS", value possibly null (A-G11's table).
        CoverFlavor::KeyExists => Some((slot, known.stratum, false)),
    }
}

/// **The S5 discharge, asked as a presence question** (A-G11's table): does a
/// recorded KeyCover plus the accumulated `¬isset(absent)` ladder prove `key`
/// present? `Some(flavor)` when it does, `None` when nothing discharges it.
///
/// Split out of [`coalesce_arm_fact`] so the *value* lane and S6's *finding* lane
/// consult one predicate. The distinction matters: a discharged key whose declared
/// value slot is unrepresentable yields no fact (the value lane has nothing to
/// bind) but is still proven present (the finding lane must stay silent). Folding
/// the two together would have made an unspellable slot emit a false positive.
fn cover_discharges(shape: &ShapeFact, key: &VKey, absent: &[VKey]) -> Option<CoverFlavor> {
    match shape.cover_proves(key, absent)? {
        CoverFlavor::Isset => Some(CoverFlavor::Isset),
        // A present-*null* earlier key satisfies a KeyExists claim while `??` still
        // falls through it, so the cover would have been discharged by an arm that
        // is not this one. The discharge is sound only when every premise key's
        // declared value is provably non-nullable, which is what makes "fell
        // through" and "absent" the same statement for them.
        CoverFlavor::KeyExists => absent
            .iter()
            .all(|k| {
                shape
                    .field(k)
                    .and_then(|(_, _, s)| s.as_deref())
                    .is_some_and(|f| f.is_null().is_no())
            })
            .then_some(CoverFlavor::KeyExists),
    }
}

/// The value-domain fact of an rvalue operand for the `??` join: a bare variable's
/// env fact, or a literal/foldable value's `Singleton`. Non-representable operands
/// (calls, offsets → `Other`, objects) yield `None`.
fn arg_value_fact(
    w: &WalkCx,
    folder: &mut dyn Folder,
    arg: &ArgValue,
    env: &HashMap<String, Known>,
) -> Option<Fact> {
    match arg {
        ArgValue::Var(name) if !w.scope.poisoned => env.get(name)?.fact.clone(),
        _ => {
            let lit = w.cx.resolve_literal(arg, env, w.scope.poisoned, folder)?;
            singleton_fact(&lit, w.cx.php_minor)
        }
    }
}

/// Allocate a fresh heap object for `new Class(args)` (ADR-0036), populating its
/// props from literal property defaults and promoted constructor parameters, and
/// its readonly set from `readonly`-declared properties. Returns the allocation id.
fn build_new_object(
    w: &WalkCx,
    folder: &mut dyn Folder,
    class: &str,
    args: &[ArgValue],
    named: &[NamedArg],
    env: &HashMap<String, Known>,
    store: &mut Store,
) -> AllocId {
    let cx = w.cx;
    let id = w.fresh_id();
    let mut obj = HeapObj::new(class.to_owned());
    obj.class_exact = true; // `new Class(...)` allocates exactly `Class` (audit G1)
    let props = cx.class_props(class);

    // readonly set + literal defaults.
    for p in &props {
        // A hooked property (PHP 8.4 `get`/`set`) binds no value fact: writes run
        // arbitrary code, so the constructed/default value is not the stored value
        // (FP class 16). It is never readonly either (readonly + hook is a PHP fatal).
        if p.hooked {
            continue;
        }
        if p.readonly {
            obj.readonly.insert(p.name.clone());
        }
        if let Some(default) = &p.default
            && let Some(fact) = singleton_fact(default, cx.php_minor)
            // A typed slot stores the boundary-converted default (issue #48):
            // `public float $d = 3;` holds `3.0`, not `3` — PHP converts the
            // compile-time default exactly as it converts a write.
            && let Some(fact) = match p.ty.as_ref() {
                Some(ty) => coerce_fact_to_native(ty, fact),
                None => Some(fact),
            }
        {
            // Skip null-admitting facts (unsound to flow past unmodeled guards). A
            // literal default is `Verified` (no env fact consumed).
            if !fact_is_nullish(&fact) {
                obj.props.insert(p.name.clone(), PropFact { fact, stratum: Stratum::Verified });
            }
            if p.readonly {
                obj.ro_written.insert(p.name.clone());
            }
        }
    }

    // Promoted constructor params: bind each from its positional `new` argument.
    if let Some(ctor) = cx.find_ctor(class) {
        // A hooked promoted param (`public int $n { set { … } }`) binds no fact — its
        // write runs arbitrary code, so the raw argument is not the stored value
        // (FP class 16). Excluded here; its value stays Unknown.
        let promoted: HashMap<&str, &&PropertyDecl> =
            props.iter().filter(|p| p.promoted && !p.hooked).map(|p| (p.name.as_str(), p)).collect();
        for (i, param) in ctor.params.iter().enumerate() {
            if param.variadic {
                break;
            }
            let Some(pd) = promoted.get(param.name.as_str()) else { continue };
            // The bound argument: the positional at this index, else a named argument
            // whose name matches this parameter (case-sensitive, PHP semantics — Gap A
            // value-binding side). A positional-and-named collision is a PHP fatal, so
            // the two are disjoint on valid input.
            let bound = args
                .get(i)
                .or_else(|| named.iter().find(|n| n.name == param.name).map(|n| &n.value));
            // The value: the resolved arg literal (carrying the arg's stratum —
            // derivation clause, heap write), else the param's native-type seed
            // (`Verified`).
            let (fact, stratum) = match bound {
                Some(a) => match cx
                    .resolve_literal_strat(a, env, w.scope.poisoned, folder)
                    .and_then(|(lit, strat)| {
                        singleton_fact(&lit, cx.php_minor).map(|f| (f, strat))
                    })
                    // The promoted slot stores the boundary-converted argument
                    // (issue #48): `__construct(public float $g)` called with `2`
                    // holds `2.0`. A mode-dependent conversion falls back to the
                    // native seed — `General` of the declared scalar covers
                    // whatever the runtime conversion produces (or the write
                    // fatals), so the seed stays sound where the value is not.
                    .and_then(|(f, strat)| match param.ty.as_ref() {
                        Some(ty) => coerce_fact_to_native(ty, f).map(|f| (f, strat)),
                        None => Some((f, strat)),
                    }) {
                    Some((f, strat)) => (Some(f), strat),
                    None => (seed_fact(param), Stratum::Verified),
                },
                None => (seed_fact(param), Stratum::Verified),
            };
            // Skip null-admitting facts (unsound to flow past unmodeled guards).
            if let Some(fact) = fact
                && !fact_is_nullish(&fact)
            {
                obj.props.insert(pd.name.clone(), PropFact { fact, stratum });
            }
            // A promoted param is *always* written at construction — even when its
            // value is unknown, record the write (readonly.reassigned first write).
            if pd.readonly {
                obj.ro_written.insert(pd.name.clone());
            }
        }
    }

    store.heap.insert(id, obj);
    id
}

/// Seed the `$this` object shell for a method scope (ADR-0036): `class_fqn` (the
/// exact receiver when a descent proved one, else the enclosing class as a lower
/// bound), plus the readonly set and provably-written readonly props from the class
/// surface. `class_exact` records whether that class is exact (audit G1). `$this` is
/// **pre-escaped** (an overridable call on it sweeps its non-readonly props).
/// Returns `None` when the class has no tracked properties (leaving `$this` unbound
/// — identical to pre-heap behavior).
///
/// Crucially this seeds **no property value facts**. A property's value in an
/// arbitrary method is whatever some *other* method last stored (or a `!== null`
/// guard narrowed) — neither of which this per-scope walk models — so assuming the
/// declared default here would be unsound (it produced null-property false
/// positives past `if ($this->x !== null)` guards). Only facts written *in this
/// method* (explicit `$this->p = …`) flow; readonly bookkeeping stays because a
/// readonly value cannot change after construction.
fn seed_this_object(cx: &Cx, class_fqn: &str, class_exact: bool) -> Option<HeapObj> {
    let props = cx.class_props(class_fqn);
    if props.is_empty() {
        return None;
    }
    let mut obj = HeapObj::new(class_fqn.to_owned());
    obj.escaped = true; // pre-escaped
    // Membership is not exactness (audit G1): `$this` is a lower bound unless the
    // caller proved the exact receiver (a binding descent) or the enclosing class
    // has no subclass (`final`/enum). The No-side consumers gate on this bit.
    obj.class_exact = class_exact;
    for p in &props {
        // A hooked property (PHP 8.4) is never readonly (readonly + hook is a PHP
        // fatal) and holds no tracked value — nothing to seed (FP class 16).
        if p.hooked {
            continue;
        }
        if p.readonly {
            obj.readonly.insert(p.name.clone());
            // A promoted readonly param or a readonly prop with a literal default is
            // provably written by construction — the first write for reassign checks.
            if p.promoted || p.default.is_some() {
                obj.ro_written.insert(p.name.clone());
            }
        }
    }
    Some(obj)
}

/// Whether a fact admits `null` — such a fact must never be *seeded* into a
/// property (ADR-0036): property reads bypass the guard-narrowing that would clear
/// a `!== null` check, so a seeded nullable/null property fact flowing into a
/// non-null sink is a false positive. Explicitly-written facts still flow (they are
/// sound within the linear trace); only construction-time seeding is filtered.
fn fact_is_nullish(f: &Fact) -> bool {
    match f {
        Fact::Singleton(v) => matches!(v, Val::Null),
        Fact::OneOf(vs) => vs.iter().any(|v| matches!(v, Val::Null)),
        Fact::Refined { nullable, .. } | Fact::General { nullable, .. } => *nullable,
        // The array stratum (ADR-0062 `Fact::Shape`) has no property-seeding
        // consumer. Answering `true` keeps it out of the heap entirely, which is
        // the no-knowledge side of this filter.
        Fact::Shape { .. } => true,
    }
}

/// Apply a `$var->prop = <rvalue>` / `$this->prop = <rvalue>` property assignment
/// (ADR-0036): run the property checks (native `type.property-mismatch`, `@var`
/// `phpdoc.property-mismatch`, `readonly.reassigned`), then record the prop's new
/// fact in the heap. An unknown receiver (no tracked object) records nothing (but
/// an object rvalue still escapes — it is now reachable via the property).
#[allow(clippy::too_many_arguments)]
fn apply_prop_assign(
    w: &WalkCx,
    folder: &mut dyn Folder,
    target_var: &str,
    prop: &str,
    value: &ArgValue,
    span_start: u32,
    guarded: bool,
    checks_enabled: bool,
    env: &HashMap<String, Known>,
    store: &mut Store,
    out: &mut Vec<Diagnostic>,
) {
    let cx = w.cx;
    if w.scope.poisoned {
        return;
    }
    // An object rvalue stored into a property escapes (now reachable via the prop).
    if let ArgValue::Var(src) = value
        && store.is_bound(src)
    {
        store.mark_escaped(src);
    }
    let Some(id) = store.id_of(target_var) else {
        return;
    };
    let class = store.heap.get(&id).expect("bound id present").class.clone();

    // Resolve the rvalue to a proven literal (for the native check) and a fact
    // (for storage + the abstract phpdoc check). The rvalue's trust stratum
    // (ADR-0052 §5) gates the proof-layer native check and is recorded on the prop
    // (derivation clause — heap write). Stratum rides with the resolution so an
    // Asserted fold does not launder to Verified (issue #127 review).
    let proven = cx.resolve_literal_strat_ex(value, env, false, folder, None, Some(&mut *out));
    let (proven_lit, rvalue_strat) = match &proven {
        Some((lit, strat)) => (Some(lit.clone()), *strat),
        None => (None, value_stratum(value, env, Some(&*store))),
    };
    let prop_fact_val: Option<Fact> = proven_lit.as_ref().and_then(|l| singleton_fact(l, cx.php_minor)).or_else(|| {
        match value {
            ArgValue::PropFetch { var: rv, prop: rp } => store.prop_fact(rv, rp).cloned(),
            _ => arg_abstract_fact(value, env, false).cloned(),
        }
    });

    // Locate the property declaration on the object's class surface (for its native
    // type and `@var` contract).
    let pdecl = cx.class_props(&class).into_iter().find(|p| p.name == prop && !p.is_static);

    // A hooked property (PHP 8.4 `get`/`set`) routes this write through arbitrary
    // user code: the value that lands in the object is whatever the `set` hook
    // computes, not `value`. So neither property-mismatch id is sound against the
    // assigned value, and no fact may be recorded (FP class 16). Class-body hooked
    // props are dropped at lowering (pdecl is `None` — checks skip naturally); this
    // guards the promoted-param case, whose declaration survives on the surface.
    let hooked = pdecl.is_some_and(|pd| pd.hooked);

    // 1. Native `type.property-mismatch` — a proven literal against a native prop
    // type. Skip promoted props (checked as constructor args; no double-report).
    let mut native_fired = false;
    if checks_enabled
        && !hooked
        && rvalue_strat == Stratum::Verified
        && let Some(pd) = pdecl
        && !pd.promoted
        && let Some(ty) = pd.ty.as_ref()
        && let Some(lit) = proven_lit.as_ref()
        && lit.is_literal()
        && is_type_error(cx, ty, lit)
    {
        let pos = cx.tree().position(span_start);
        let mode = if cx.strict() { "strict" } else { "coercive" };
        out.push(Diagnostic {
            id: PROP_MISMATCH_ID,
            facet: None,
            fix: None,
            path: cx.path().to_owned(),
            line: pos.line,
            column: pos.column,
            message: format!(
                "Cannot assign {} to property {}::${} of type {} — proven TypeError ({} mode)",
                lit.render(), simple_class(&class), prop, ty.render(), mode,
            ),
        });
        native_fired = true;
    }

    // 2. phpdoc `@var` `phpdoc.property-mismatch` — a proven or abstract value that
    // provably does not inhabit the property's `@var` contract (definite No only).
    if checks_enabled
        && !hooked
        && !native_fired
        && let Some(pd) = pdecl
        && let Some(mut var_ty) = pd.docblock.as_deref().and_then(parse_var_type)
        && let Some((cfile, cdecl)) = cx.find_class(&class)
    {
        // Class-level `@template` names shadow same-named classes in this property's
        // `@var` type (issue #5) — a property is a member docblock too.
        neutralize_templates(&mut var_ty, &template_names_of(cdecl.docblock.as_deref()));
        let coff = pd.span.start;
        let violates = match proven_lit.as_ref().map(|l| CVal::Scalar(l.clone())) {
            Some(cv) if matches!(cv, CVal::Scalar(ref v) if v.is_literal()) => {
                accepts(cx, cfile, coff, &var_ty, &cv) == Certainty::No
            }
            _ => arg_abstract_fact(value, env, false).is_some_and(|fact| {
                let cty = steins_contract::lower(&var_ty);
                !contract_touches_class(&cty)
                    && steins_contract::admits_fact(&cty, fact) == Certainty::No
            }),
        };
        if violates {
            let rendered = proven_lit
                .as_ref()
                .map(ArgValue::render)
                .or_else(|| arg_abstract_fact(value, env, false).map(describe_fact))
                .unwrap_or_else(|| value.render());
            let pos = cx.tree().position(span_start);
            out.push(Diagnostic {
                id: PHPDOC_PROP_MISMATCH_ID,
                facet: None,
                fix: None,
                path: cx.path().to_owned(),
                line: pos.line,
                column: pos.column,
                message: format!(
                    "value {rendered} assigned to property {}::${prop} violates declared @var {var_ty} — declared contract violation",
                    simple_class(&class),
                ),
            });
        }
    }

    // Whether the rvalue is an object handle (computed before the mutable borrow).
    let rval_is_object = matches!(value, ArgValue::Var(src) if store.refs.contains_key(src));

    // 3. `readonly.reassigned` — a second proven write to a readonly property on
    // this (unguarded) path. `guarded` (inside a branch) suppresses it: the second
    // write is not proven on every path (ADR-0036 conservative side).
    let obj = store.heap.get_mut(&id).expect("bound id present");
    let is_readonly = obj.readonly.contains(prop);
    if checks_enabled && is_readonly && obj.ro_written.contains(prop) && !guarded {
        let pos = cx.tree().position(span_start);
        out.push(Diagnostic {
            id: READONLY_REASSIGNED_ID,
            facet: None,
            fix: None,
            path: cx.path().to_owned(),
            line: pos.line,
            column: pos.column,
            message: format!(
                "Cannot modify readonly property {}::${prop} — proven Error",
                simple_class(&class),
            ),
        });
    }

    // 4. Record the prop's new fact (or drop it when the rvalue is not representable
    // / is an object handle). Mark the readonly write for the reassign check.
    match prop_fact_val {
        // A hooked property never records a fact — its stored value is the `set`
        // hook's arbitrary-code result, not `value` (FP class 16). Keep the slot
        // Unknown so reads (dumps, receivers, depth-1 prop-fetch) fall back to
        // arbitrary code rather than the assigned value.
        Some(fact) if !rval_is_object && !hooked => {
            // A TYPED slot stores what PHP's boundary conversion makes of the
            // rvalue, not the rvalue (issue #48): an int written to a `float`
            // property IS a float. A fact the conversion cannot answer
            // mode-independently drops to Unknown (sound both ways).
            let stored = match pdecl.and_then(|pd| pd.ty.as_ref()) {
                Some(ty) => coerce_fact_to_native(ty, fact),
                None => Some(fact),
            };
            match stored {
                Some(fact) => {
                    obj.props.insert(prop.to_owned(), PropFact { fact, stratum: rvalue_strat });
                }
                None => {
                    obj.props.remove(prop);
                }
            }
        }
        _ => {
            obj.props.remove(prop);
        }
    }
    if is_readonly {
        obj.ro_written.insert(prop.to_owned());
    }
}

/// The simple (last-segment) class name of an FQN, for a diagnostic message.
fn simple_class(fqn: &str) -> &str {
    fqn.rsplit('\\').next().unwrap_or(fqn)
}

/// Parse the first `@var` tag's type out of a property docblock (ADR-0036), or
/// `None` when absent/unparseable — the property carries no phpdoc contract.
fn parse_var_type(docblock: &str) -> Option<PType> {
    for tag in scan_docblock(docblock) {
        if matches!(tag.kind, TagKind::Var) {
            return parse_tag_type(&tag.type_text);
        }
    }
    None
}

/// Build a [`ClosureVal`] from a lowered [`ClosureRef`] at its creation site,
/// snapshotting the by-value captures from the definition-site `env` (ADR-0033).
/// A capture whose variable has no proven scalar fact is simply omitted (the
/// closure body sees it as unknown — sound); a captured closure is not re-snapshot
/// (nested closure capture is not modeled — the body treats it as unknown).
/// Each captured fact keeps its trust stratum so descent seeding cannot launder
/// an `Asserted` claim into a `Verified` summary (issue #128 review).
fn build_closure_val(
    cx: &Cx,
    cref: &steins_syntax::ClosureRef,
    line: u32,
    env: &HashMap<String, Known>,
) -> Option<ClosureVal> {
    use steins_syntax::ClosureRef;
    match cref {
        ClosureRef::Anonymous { def_offset, captures } => {
            let mut snapshot: Vec<(String, Fact, Stratum)> = Vec::new();
            for name in captures {
                if let Some(k) = env.get(name)
                    && let Some(f) = &k.fact
                    // A `Fact::Shape` is deliberately NOT captured (ADR-0062 S3):
                    // the descent key collapses every non-`Singleton` fact to
                    // `Other` (`arg_of_fact_key`), so a captured shape carries no
                    // binding information — it would only flip the "descend at
                    // all" test. (Stratum is now snapshotted for scalars, but
                    // shapes stay out until the key can spell them.)
                    && !matches!(f, Fact::Shape { .. })
                {
                    snapshot.push((name.clone(), f.clone(), k.stratum));
                }
            }
            Some(ClosureVal { target: ClosureTarget::Scope(*def_offset), captures: snapshot, def_line: line })
        }
        ClosureRef::FunctionName(nameref) => {
            let _ = cx;
            Some(ClosureVal { target: ClosureTarget::Named(nameref.clone()), captures: Vec::new(), def_line: line })
        }
    }
}

/// Walk a structured `if`/`elseif`/`else` (ADR-0031 stage 1). Evaluates the guard
/// to a [`Certainty`], walks each **live** branch on a cloned env (applying
/// positive refinement), then joins the envs of the branches that fall through.
/// When no live branch falls through, the code after the `if` is unreachable and
/// the whole construct terminates.
#[allow(clippy::too_many_arguments)]
fn walk_if(
    w: &WalkCx,
    folder: &mut dyn Folder,
    cond: &CondExpr,
    then_trace: &[Stmt],
    elseifs: &[(CondExpr, Vec<Stmt>)],
    else_trace: Option<&[Stmt]>,
    env: &mut HashMap<String, Known>,
    store: &mut Store,
    descent: &mut Option<Descent<'_>>,
    facts: &mut Option<&mut Vec<LineFact>>,
    out: &mut Vec<Diagnostic>,
) -> Flow {
    let poisoned = w.scope.poisoned;
    // 1. Evaluate the guard in the pre-branch env (short-circuit env refinement is
    // stage 2 — each condition sees the same entry env).
    let verdict = eval_cond(w, folder, cond, env, store, poisoned);

    // A decided guard proves the skipped side dead — record it so the env-free
    // direct pass never reports inside it (live-path discipline, ADR-0002/0031).
    match verdict {
        Certainty::Yes => {
            for (_, trace) in elseifs {
                mark_dead(w, &[trace.as_slice()]);
            }
            if let Some(trace) = else_trace {
                mark_dead(w, &[trace]);
            }
        }
        Certainty::No => mark_dead(w, &[then_trace]),
        Certainty::Maybe => {}
    }

    // 2. The guard's own effects on *every* resulting path, sequenced at the calls'
    // positions (ADR-0052 §6): a
    // retained guard call escapes its object arguments/receiver and sweeps the
    // escaped objects' mutable props (the method receiver's binding survives — a
    // method call does not rebind its receiver variable, the payoff (i) that lets
    // `$x !== null && $x->m()` keep a proven-non-null receiver), then by-ref argument
    // invalidation and opaque reads are forgotten. Both apply before the branch
    // clones (a call in either operand may have executed on the excluded path too).
    let guard_calls: Vec<&CallExpr> = collect_guard_calls_any(cond);
    escape_and_sweep_calls(w, &guard_calls, store);
    for v in cond_invalidations(w.cx, cond, env, store, poisoned) {
        env.remove(&v);
        store.unbind(&v);
    }

    // 3. Walk the live branches on cloned envs, collecting those that fall through.
    let mut fell: Vec<(HashMap<String, Known>, Store)> = Vec::new();

    // Guard calls carrying `-if-true`/`-if-false` envelopes, collected per branch
    // polarity through the `&&`/`||` structure (ADR-0052 §6, extending N2's
    // top-level-only consumption into nested positions: `if ($a && isNonEmpty($s))`
    // now consumes `isNonEmpty`'s `-if-true` on the then-branch). Each carries whether
    // the call returned `true` on that branch, selecting the spec polarity. The specs
    // apply at the `Asserted` stratum (§5) — silence only, never a proof premise.
    if verdict != Certainty::No {
        let mut benv = env.clone();
        let mut bclasses = store.clone();
        // The DR2 type vocabulary runs FIRST of the four: it is the only one that
        // can *mint* a fact over an unfacted binding, and the scalar refinements
        // below must then see that fact — `if (is_string($v) && $v !== '')` on a
        // `mixed` binding narrows to `non-empty-string` only in this order.
        apply_type_narrowing(w.cx, cond, true, &mut benv, &mut bclasses);
        let refs = then_refinements(cond, w.cx.php_minor);
        apply_refinements(&refs, &mut benv, &mut bclasses, Stratum::Verified);
        apply_class_narrowing(w, cond, true, &mut bclasses);
        apply_shape_narrowing(w.cx, cond, true, &mut benv, &mut bclasses, true);
        let mut then_calls = Vec::new();
        collect_guard_calls(cond, true, &mut then_calls);
        for (call, returns_true) in then_calls {
            let kind = if returns_true { AssertKind::IfTrue } else { AssertKind::IfFalse };
            apply_guard_asserts(w, call, kind, &mut benv, &mut bclasses);
            // Guard-respect leg (ADR-0049 §4): a positive existence guard vouches its
            // symbol on the branch where it holds true, silencing the absence family.
            if returns_true && let Some(v) = existence_vouch(w.cx, &bclasses, call) {
                bclasses.vouch(v);
            }
        }
        seed_out_params(w, folder, cond, true, &mut benv, &mut bclasses);
        if walk_trace(w, folder, then_trace, &mut benv, &mut bclasses, descent, facts, true, out)
            == Flow::FellThrough
        {
            fell.push((benv, bclasses));
        }
    }

    if verdict != Certainty::Yes {
        let mut benv = env.clone();
        let mut bclasses = store.clone();
        apply_type_narrowing(w.cx, cond, false, &mut benv, &mut bclasses);
        let refs = else_refinements(cond, w.cx.php_minor);
        apply_refinements(&refs, &mut benv, &mut bclasses, Stratum::Verified);
        apply_class_narrowing(w, cond, false, &mut bclasses);
        apply_shape_narrowing(w.cx, cond, false, &mut benv, &mut bclasses, true);
        let mut else_calls = Vec::new();
        collect_guard_calls(cond, false, &mut else_calls);
        for (call, returns_true) in else_calls {
            let kind = if returns_true { AssertKind::IfTrue } else { AssertKind::IfFalse };
            apply_guard_asserts(w, call, kind, &mut benv, &mut bclasses);
            // Guard-respect leg (ADR-0049 §4): the negated-guard branch where the
            // predicate holds true (`if (!method_exists(...)) {} else <here>`) vouches too.
            if returns_true && let Some(v) = existence_vouch(w.cx, &bclasses, call) {
                bclasses.vouch(v);
            }
        }
        // The same seed on the other side of the branch, for the same reason and
        // under the same condition: `if (!preg_match($re, $s, $m)) { return; }`
        // reaches its else-branch — and everything after it — with the call
        // proven truthy (ADR-0077 §3.1). The branch is not what decides; the
        // polarity the witness survives under is.
        seed_out_params(w, folder, cond, false, &mut benv, &mut bclasses);
        if walk_else(w, folder, elseifs, else_trace, &mut benv, &mut bclasses, descent, facts, out)
            == Flow::FellThrough
        {
            fell.push((benv, bclasses));
        }
    }

    // 4. Merge. No live fall-through → the successor is unreachable.
    if fell.is_empty() {
        return Flow::Terminated;
    }
    let (jenv, jclasses) = join_envs(fell);
    *env = jenv;
    *store = jclasses;
    Flow::FellThrough
}

/// Walk the `else` side of an `if`: the `elseif` chain desugars to a nested
/// `if`/`else`; the terminal `else` (if any) is a plain sub-trace; an absent
/// `else` falls through unchanged (the negated-guard path).
#[allow(clippy::too_many_arguments)]
fn walk_else(
    w: &WalkCx,
    folder: &mut dyn Folder,
    elseifs: &[(CondExpr, Vec<Stmt>)],
    else_trace: Option<&[Stmt]>,
    env: &mut HashMap<String, Known>,
    store: &mut Store,
    descent: &mut Option<Descent<'_>>,
    facts: &mut Option<&mut Vec<LineFact>>,
    out: &mut Vec<Diagnostic>,
) -> Flow {
    match elseifs.split_first() {
        Some(((cond, trace), rest)) => {
            walk_if(w, folder, cond, trace, rest, else_trace, env, store, descent, facts, out)
        }
        None => match else_trace {
            Some(stmts) => walk_trace(w, folder, stmts, env, store, descent, facts, true, out),
            None => Flow::FellThrough,
        },
    }
}

/// Walk a structured statement-position `match`/`switch` (ADR-0031 Part B).
///
/// Per arm, the "taken" certainty is computed left to right with first-match
/// semantics: `taken(k) = Yes` iff arm `k` matches (`Yes`) **and** every earlier
/// arm provably does not (`No`); `No` iff arm `k` provably does not match; `Maybe`
/// otherwise. This ordering rule is what stops a later `Yes` arm from being walked
/// as the sole-live branch while an earlier arm is only `Maybe`. Arms with
/// `taken == No` are recorded dead (the env-free direct pass then stays silent
/// inside them); every other arm is walked on a cloned env, with the subject
/// var refined to the arm's literal set (a `match` binds `Singleton`/`OneOf`; a
/// `switch` binds nothing — its loose `==` truth set is multi-valued).
///
/// The "no arm matched" outcome depends on the construct: with a `default` arm it
/// runs that body (unless a decided `Yes` arm makes it dead); without one, a
/// `switch` falls through to after the construct (entry env preserved) while a
/// `match` raises `\UnhandledMatchError` — a terminator contributing no
/// fall-through. The successor env is the join of every branch that falls
/// through; if none does, the whole construct terminates (tail unreachable).
#[allow(clippy::too_many_arguments)]
fn walk_match(
    w: &WalkCx,
    folder: &mut dyn Folder,
    subject: &CondOperand,
    arms: &[MatchArmT],
    default: Option<&[Stmt]>,
    loose: bool,
    env: &mut HashMap<String, Known>,
    store: &mut Store,
    descent: &mut Option<Descent<'_>>,
    facts: &mut Option<&mut Vec<LineFact>>,
    out: &mut Vec<Diagnostic>,
) -> Flow {
    let poisoned = w.scope.poisoned;
    let op = if loose { CmpOp::Loose } else { CmpOp::Identical };
    let subj_vals = operand_values(subject, env, poisoned);

    // 1. Per-arm first-match "taken" certainty (left to right). `earlier_all_no`
    // tracks whether every arm before the current one provably does NOT match;
    // `decided_done` records that a *decided* match (`Yes` with all earlier `No`)
    // has been found — every later arm and the default are then unreachable,
    // because `match`/`switch` take the FIRST matching arm.
    let mut takens: Vec<Certainty> = Vec::with_capacity(arms.len());
    let mut earlier_all_no = true;
    let mut decided_done = false;
    for arm in arms {
        if decided_done {
            takens.push(Certainty::No); // a prior sure match makes this unreachable
            continue;
        }
        let cond_k =
            eval_arm_cond(op, subj_vals.as_deref(), &arm.conditions, env, poisoned, w.cx.php_minor);
        let taken = match cond_k {
            Certainty::No => Certainty::No,
            Certainty::Yes if earlier_all_no => {
                decided_done = true;
                Certainty::Yes
            }
            _ => Certainty::Maybe,
        };
        if cond_k != Certainty::No {
            earlier_all_no = false;
        }
        takens.push(taken);
    }
    // The default / no-match path: `No` once a decided arm consumed the value;
    // `Yes` when every arm provably fails to match; else `Maybe`.
    let no_match_taken = if decided_done {
        Certainty::No
    } else if earlier_all_no {
        Certainty::Yes
    } else {
        Certainty::Maybe
    };

    // 2. Walk each live arm on a cloned env; record `No` arms dead.
    let mut fell: Vec<(HashMap<String, Known>, Store)> = Vec::new();
    for (arm, taken) in arms.iter().zip(&takens) {
        if *taken == Certainty::No {
            mark_dead(w, &[arm.trace.as_slice()]);
            continue;
        }
        let mut benv = env.clone();
        let mut bclasses = store.clone();
        refine_match_arm(subject, &arm.conditions, loose, &mut benv, w.cx.php_minor);
        // Tag-based discrimination (ADR-0062 A-G4): a `match`/`switch` on a
        // constant-key projection subtracts the base's array arms by the field's
        // `admits` verdict, and mints the collapsed shape into the arm's env.
        // The `default` arm below refines nothing — its truth is "no listed tag
        // matched", a residue A-G4 does not model in v1.
        if let CondOperand::Offset { var, key } = subject
            && let Some(k) = guard_key(key, w.cx.php_minor)
            && let Some(tags) = arm_tag_literals(&arm.conditions)
        {
            apply_shape_guard(
                w.cx,
                &ShapeGuard::Tag { var: var.clone(), key: k, tags, loose },
                &mut benv,
                &mut bclasses,
                true,
            );
        }
        if walk_trace(w, folder, &arm.trace, &mut benv, &mut bclasses, descent, facts, true, out)
            == Flow::FellThrough
        {
            fell.push((benv, bclasses));
        }
    }

    // 3. The "no arm matched" outcome.
    match default {
        Some(dtrace) => {
            if no_match_taken == Certainty::No {
                mark_dead(w, &[dtrace]);
            } else {
                let mut benv = env.clone();
                let mut bclasses = store.clone();
                if walk_trace(w, folder, dtrace, &mut benv, &mut bclasses, descent, facts, true, out)
                    == Flow::FellThrough
                {
                    fell.push((benv, bclasses));
                }
            }
        }
        None => {
            // A default-less `switch` falls through to after itself on no match
            // (entry env unchanged); a default-less `match` throws
            // `\UnhandledMatchError` — a terminator that joins nothing.
            if loose && no_match_taken != Certainty::No {
                fell.push((env.clone(), store.clone()));
            }
        }
    }

    // 4. Merge. No live fall-through → the successor is unreachable.
    if fell.is_empty() {
        return Flow::Terminated;
    }
    let (jenv, jclasses) = join_envs(fell);
    *env = jenv;
    *store = jclasses;
    Flow::FellThrough
}

/// The certainty that a `match`/`switch` arm is the one taken *by value* — i.e.
/// the subject equals ANY of the arm's conditions (`===` for match, loose `==`
/// for switch). An unknown subject or condition contributes `Maybe`; the OR folds
/// the per-condition verdicts (any `Yes` → `Yes`, all `No` → `No`, else `Maybe`).
fn eval_arm_cond(
    op: CmpOp,
    subj_vals: Option<&[ArgValue]>,
    conditions: &[CondOperand],
    env: &HashMap<String, Known>,
    poisoned: bool,
    php_minor: Option<(u16, u16)>,
) -> Certainty {
    let Some(subj) = subj_vals else { return Certainty::Maybe };
    let mut acc = Certainty::No;
    for c in conditions {
        let cert = match operand_values(c, env, poisoned) {
            Some(cv) => eval_cmp(op, subj, &cv, php_minor),
            None => Certainty::Maybe,
        };
        acc = acc.or(cert);
        if acc == Certainty::Yes {
            return Certainty::Yes;
        }
    }
    acc
}

/// Refine the subject variable inside a matched arm's cloned env. A `match`
/// (strict `===`) whose subject is a bare variable and whose conditions are all
/// literals binds the subject to that exact finite set (`Singleton` for one,
/// `OneOf` for several) — the value is provably one of them on this path. A
/// `switch` (loose `==`) binds NOTHING: a loose-equal truth set is multi-valued
/// (`case 0` matches `0`, `"0"`, `false`, `0.0`, …), so no single `Fact` is sound.
/// A match/switch arm's condition literals, or `None` when any condition is not
/// one (a stacked arm lists several: `1, 2 => …` / `case 1: case 2:`).
fn arm_tag_literals(conditions: &[CondOperand]) -> Option<Vec<ArgValue>> {
    if conditions.is_empty() {
        return None;
    }
    conditions
        .iter()
        .map(|c| match c {
            CondOperand::Literal(v) => Some(v.clone()),
            _ => None,
        })
        .collect()
}

fn refine_match_arm(
    subject: &CondOperand,
    conditions: &[CondOperand],
    loose: bool,
    env: &mut HashMap<String, Known>,
    php_minor: Option<(u16, u16)>,
) {
    if loose {
        return;
    }
    let CondOperand::Var(name) = subject else { return };
    let mut vals = Vec::with_capacity(conditions.len());
    for c in conditions {
        match c {
            CondOperand::Literal(v) => match val_of(v, php_minor) {
                Some(val) => vals.push(val),
                None => return,
            },
            _ => return,
        }
    }
    if let Some(fact) = Fact::from_vals(vals) {
        let line = env.get(name).map_or(0, |k| k.line);
        env.insert(name.clone(), Known::value(fact, line, Some("matched arm".to_owned())));
    }
}

/// The branch-sensitive null-dereference proof (ADR-0031, `call.on-null`): a
/// non-null-safe `$v->m(...)` whose receiver `$v` is proven `Singleton(null)` on
/// the current path is a guaranteed runtime `Error`. A `OneOf` that merely
/// includes null stays `Maybe` (silent), and `?->` never fires.
fn check_call_on_null(
    w: &WalkCx,
    call: &CallExpr,
    env: &HashMap<String, Known>,
    store: &Store,
    out: &mut Vec<Diagnostic>,
) {
    if w.scope.poisoned {
        return;
    }
    let Callee::Method { receiver, method, nullsafe: false } = &call.receiver else {
        return;
    };
    // The proven-null receiver fact + its trust stratum + the receiver's rendering.
    // A bare `$v` reads the env value fact; a depth-1 `$v->prop` receiver reads the
    // allocation-keyed heap property fact (ADR-0052 §7, alias-correct by construction,
    // ADR-0036) — escaped-then-swept props return `None` here (silence preserved), a
    // readonly prop survives the sweep, and the stratum gate below refuses an
    // `Asserted` premise exactly as it does for a variable.
    let (fact, stratum, display) = match receiver {
        Receiver::Var(v) => {
            let Some(k) = env.get(v) else { return };
            (k.fact.as_ref(), k.stratum, format!("${v}"))
        }
        Receiver::Prop { var, prop } => {
            (store.prop_fact(var, prop), store.prop_stratum(var, prop), format!("${var}->{prop}"))
        }
        Receiver::This | Receiver::New(_) => return,
    };
    if !matches!(fact, Some(Fact::Singleton(Val::Null))) {
        return;
    }
    // Proof-layer consumption rule (ADR-0052 §5): a receiver proven null only by an
    // `Asserted` fact (e.g. `@phpstan-assert null $x`) cannot premise this proof —
    // stay silent.
    if stratum != Stratum::Verified {
        return;
    }
    let pos = w.cx.tree().position(call.span.start);
    out.push(Diagnostic {
        id: CALL_ON_NULL_ID,
        facet: None,
        fix: None,
        path: w.cx.path().to_owned(),
        line: pos.line,
        column: pos.column,
        message: format!(
            "method call {display}->{method}() — {display} is proven null on this path — proven Error (Call to a member function on null)"
        ),
    });
}

// ---------------------------------------------------------------------------
// Condition evaluation → `Certainty` (ADR-0031 stage 1).
// ---------------------------------------------------------------------------

/// Evaluate a lowered [`CondExpr`] against the env to a unified [`Certainty`].
///
/// `folder` is threaded because a foldable existence-guard call
/// (`method_exists`/`function_exists`/`class_exists` …, ADR-0049 §4 / N3) folds to
/// a real verdict by asking the runtime boot surface (the A2ii homonym oracle);
/// every other arm is env-only and ignores it.
/// Whether `r` names the ENGINE's `PHP_VERSION_ID` in the current file (issue
/// #29). Constants are case-sensitive, so the match is exact. A fully-qualified
/// `\PHP_VERSION_ID` always does (the engine defines it first; a `define` of an
/// already-defined constant is a no-op). An unqualified reference does unless
/// this file `use const`-imports the alias — the namespace fallback otherwise
/// lands on the global. Qualified/relative spellings never do. The remaining
/// residue — a userland `const`/literal `define` twin anywhere in the project —
/// zeroes [`Cx::version_id`] before this is ever consulted; a define with a
/// *computed* name is not scanned, the one modeled-out corner (recorded here
/// deliberately: the only consumer is branch pruning, and a computed define
/// minting a namespaced `PHP_VERSION_ID` twin has no known occurrence in the
/// wild).
fn is_engine_version_id(cx: &Cx, r: &NameRef) -> bool {
    if r.raw != "PHP_VERSION_ID" {
        return false;
    }
    match r.kind {
        RefKind::FullyQualified => true,
        RefKind::Unqualified => !cx.tree().php_version_id_aliased(),
        _ => false,
    }
}

/// The issue-#29 version-guard fold: `Some(verdict)` when one operand is the
/// engine `PHP_VERSION_ID` and the other an int literal — including the
/// `Maybe` verdict for an interval the literal splits (a target range that
/// straddles the comparison keeps both arms live). `None` hands the comparison
/// to the ordinary evaluation.
fn eval_version_id_cmp(
    cx: &Cx,
    op: CmpOp,
    lhs: &CondOperand,
    rhs: &CondOperand,
) -> Option<Certainty> {
    let (lo, hi) = cx.version_id?;
    let (r, lit, flipped) = match (lhs, rhs) {
        (CondOperand::Const(r), CondOperand::Literal(ArgValue::Int(n))) => (r, *n, false),
        (CondOperand::Literal(ArgValue::Int(n)), CondOperand::Const(r)) => (r, *n, true),
        _ => return None,
    };
    if !is_engine_version_id(cx, r) {
        return None;
    }
    // Mirror the operator when the constant sits on the right (`80400 <=
    // PHP_VERSION_ID` asks `PHP_VERSION_ID >= 80400`).
    let op = if flipped {
        match op {
            CmpOp::Lt => CmpOp::Gt,
            CmpOp::Le => CmpOp::Ge,
            CmpOp::Gt => CmpOp::Lt,
            CmpOp::Ge => CmpOp::Le,
            other => other,
        }
    } else {
        op
    };
    let lo = i64::from(lo);
    let hi = hi.map(i64::from);
    // Interval-vs-point trichotomy. `hi = None` is an open upper bound: the
    // interval can then never sit entirely below a literal.
    let all_ge = |p: i64| lo >= p;
    let all_le = |p: i64| hi.is_some_and(|h| h <= p);
    let verdict = match op {
        CmpOp::Ge => {
            if all_ge(lit) {
                Certainty::Yes
            } else if all_le(lit - 1) {
                Certainty::No
            } else {
                Certainty::Maybe
            }
        }
        CmpOp::Gt => {
            if all_ge(lit + 1) {
                Certainty::Yes
            } else if all_le(lit) {
                Certainty::No
            } else {
                Certainty::Maybe
            }
        }
        CmpOp::Le => {
            if all_le(lit) {
                Certainty::Yes
            } else if all_ge(lit + 1) {
                Certainty::No
            } else {
                Certainty::Maybe
            }
        }
        CmpOp::Lt => {
            if all_le(lit - 1) {
                Certainty::Yes
            } else if all_ge(lit) {
                Certainty::No
            } else {
                Certainty::Maybe
            }
        }
        // `==`/`===` (int against int: the loose and strict tables agree): `Yes`
        // only when the interval IS the point — unreachable at minor precision
        // (the interval always spans 100 patch ids) but written generally; a
        // point outside the interval is a definite `No`.
        CmpOp::Identical | CmpOp::Loose => {
            if lit < lo || hi.is_some_and(|h| lit > h) {
                Certainty::No
            } else if hi == Some(lo) && lit == lo {
                Certainty::Yes
            } else {
                Certainty::Maybe
            }
        }
        CmpOp::NotIdentical | CmpOp::NotLoose => {
            if lit < lo || hi.is_some_and(|h| lit > h) {
                Certainty::Yes
            } else if hi == Some(lo) && lit == lo {
                Certainty::No
            } else {
                Certainty::Maybe
            }
        }
    };
    Some(verdict)
}

fn eval_cond(
    w: &WalkCx,
    folder: &mut dyn Folder,
    cond: &CondExpr,
    env: &HashMap<String, Known>,
    store: &Store,
    poisoned: bool,
) -> Certainty {
    match cond {
        CondExpr::Cmp { op, lhs, rhs } => {
            // The PHP_VERSION_ID guard fold (issue #29): a comparison of the
            // engine's version id against an int literal decides against the
            // resolved target interval, and the ordinary decided-branch pruning
            // does the rest — a straddled boundary stays `Maybe` (both arms
            // live), never a guess.
            if let Some(v) = eval_version_id_cmp(w.cx, *op, lhs, rhs) {
                return v;
            }
            match (operand_values(lhs, env, poisoned), operand_values(rhs, env, poisoned)) {
                (Some(lv), Some(rv)) => eval_cmp(*op, &lv, &rv, w.cx.php_minor),
                _ => Certainty::Maybe,
            }
        }
        CondExpr::Truthy(op) => match operand_values(op, env, poisoned) {
            Some(vs) => all_agree(vs.iter().map(php_truthy)),
            None => Certainty::Maybe,
        },
        CondExpr::Instanceof { operand, class_ref } => {
            eval_instanceof(w, operand, class_ref, env, store, poisoned)
        }
        CondExpr::Not(c) => eval_cond(w, folder, c, env, store, poisoned).not(),
        // Short-circuit env threading (ADR-0052 §6 / N3): the RIGHT operand
        // evaluates under the env the LEFT operand's outcome establishes, exactly as
        // PHP's `&&`/`||` sequence it — `b` in `a && b` runs only when `a` was truthy
        // (so it sees `then_refinements(a)`); `b` in `a || b` runs only when `a` was
        // falsy (so it sees `else_refinements(a)`, De Morgan). The composed verdict
        // stays the trinary `and`/`or`; only the operand env threads. This is
        // walk-local left-to-right evaluation (ADR-0048 §2): the refinement clone is
        // discarded, no entry state contributes, no ordering beyond the source's own.
        CondExpr::And(a, b) => {
            let va = eval_cond(w, folder, a, env, store, poisoned);
            // `a` false ⇒ `b` never runs; the verdict is already `No`, and the
            // threaded env would be a contradiction — skip it.
            if va == Certainty::No {
                return Certainty::No;
            }
            let (benv, bstore) =
                threaded_operand_env(w.cx, a, true, env, store, w.cx.php_minor, poisoned);
            va.and(eval_cond(w, folder, b, &benv, &bstore, poisoned))
        }
        CondExpr::Or(a, b) => {
            let va = eval_cond(w, folder, a, env, store, poisoned);
            // `a` true ⇒ `b` never runs; the verdict is already `Yes`.
            if va == Certainty::Yes {
                return Certainty::Yes;
            }
            let (benv, bstore) =
                threaded_operand_env(w.cx, a, false, env, store, w.cx.php_minor, poisoned);
            va.or(eval_cond(w, folder, b, &benv, &bstore, poisoned))
        }
        // A foldable existence predicate in guard position folds to a Yes/No/Maybe
        // verdict against the closed world (ADR-0049 §4 / N3); an opaque condition or
        // any other guard call stays undecided.
        CondExpr::Call { call, .. } => eval_existence_call(w, folder, call),
        // `isset($x[k])` decides NOTHING (ADR-0062 S4). The only evidence that
        // could decide it on a declared base is a shape fact, which is
        // `Asserted` — and a verdict is what prunes branches and marks regions
        // dead, so deciding here would let a docblock claim silence the env-free
        // direct pass on a live path. Narrowing (silence) is the whole payoff;
        // reachability stays proof-only.
        CondExpr::Isset { .. } | CondExpr::Opaque { .. } => Certainty::Maybe,
    }
}

// ---------------------------------------------------------------------------
// Foldable existence-guard verdicts (ADR-0049 §4 / N3).
//
// `method_exists(C, 'm')` / `function_exists('f')` / `class_exists('N')` (and the
// `interface_`/`trait_`/`enum_exists` siblings) in guard position fold to a
// three-valued `Certainty` against the closed world, so the ADR-0031 dead-region
// discipline prunes the branch the runtime provably never takes. The verdict rests
// on the SAME closure the absence family fires under (S1 existence + S2 chain
// enumeration + the A2ii boot-surface homonym oracle + A2i conditional/dam leg):
//   * `Yes`  — the symbol is provably PRESENT under complete closure;
//   * `No`   — provably ABSENT under complete closure;
//   * `Maybe`— anything short of closure (a trait-bearing chain, a conditional decl
//              with the dam standing, an unresolvable ancestor, an unanswerable
//              homonym query, a non-literal argument, or no live boot surface).
// A `Maybe` verdict is always the FP-safe fallback: it walks both branches live and
// leans on the conservative guard-respect leg (the per-symbol vouch) for silence.
// ---------------------------------------------------------------------------

/// Whether a function reference **denotes the global function it spells** — the
/// one question every builtin recognizer in this file asks before matching a name
/// against its vocabulary. It lives here, once, so the next recognizer someone
/// adds is correct by construction rather than by copying (issue #153).
///
/// The load-bearing distinction is that `\foo` denotes the global function while
/// `Ns\foo` does not, and the rule is emphatically **not** "reject a backslash":
/// [`NameRef::raw`] already has a leading `\` stripped and a `namespace\` prefix
/// dropped, so a purely textual test silently reads the wrong thing on two
/// spellings. Every leg below was measured against `php` 8.5.9:
///
/// * `\is_string($x)` — the global builtin whatever the file's namespace, even
///   where an `App\is_string` is declared alongside it. `\Foo\is_string` keeps a
///   separator and is a different function.
/// * `is_string($x)` — PHP's function fallback reaches the global name from any
///   namespace, so the spelling denotes it (the shadowing leg below is what
///   removes the cases where a project function wins).
/// * `Foo\is_string($x)` — relative to the current namespace: never global.
/// * `namespace\is_string($x)` inside `namespace App;` — resolves to
///   `App\is_string` **only**, with no global fallback: PHP fatals with "Call to
///   undefined function App\is_string()". In the root namespace the enclosing
///   namespace *is* global, so there the same spelling does denote the builtin.
/// * `use function Other\thing as is_string;` — the call goes to `Other\thing`
///   and never falls back, so the spelling is not the builtin; a plain
///   `use function is_string;` names the global one and still is.
///
/// The two rejected legs mirror [`name_reaches_global_var_dump`], which asks the
/// same question of one hard-coded name and reached the same answers.
///
/// The **shadowing** leg is a separate guarantee, unchanged and deliberately
/// kept: a project-defined function of the name is a different function whatever
/// the spelling would otherwise denote.
fn denotes_global_function(cx: &Cx, r: &NameRef) -> bool {
    let spells_global = match r.kind {
        RefKind::FullyQualified => !r.raw.contains('\\'),
        RefKind::Qualified => false,
        RefKind::Relative => {
            !r.raw.contains('\\') && cx.tree().ctx_at(r.offset).namespace.is_empty()
        }
        RefKind::Unqualified => {
            match cx.tree().ctx_at(r.offset).fn_imports.get(&r.raw.to_ascii_lowercase()) {
                Some(target) => target.eq_ignore_ascii_case(&r.raw),
                None => true,
            }
        }
    };
    spells_global && !matches!(cx.resolve_function(r), FnResolution::User(_))
}

/// The simple name a call's callee spells, when the reference denotes the
/// **global** function of that name ([`denotes_global_function`]) — the single
/// entry point every builtin recognizer below opens with. `None` for a dynamic
/// callee, a namespaced or namespace-relative twin, an aliased import, or a
/// userland shadow.
fn global_function_callee<'a>(cx: &Cx, call: &'a CallExpr) -> Option<&'a str> {
    let callee = call.callee.as_deref()?;
    let r = call.callee_ref.as_ref()?;
    denotes_global_function(cx, r).then_some(callee)
}

/// The recognized existence predicate a guard call names, or `None` when the call
/// is not one of them / does not denote the global builtin (a `Foo\class_exists`
/// or a same-named user function is a DIFFERENT function — see
/// [`global_function_callee`], which owns that whole rule).
fn existence_predicate(cx: &Cx, call: &CallExpr) -> Option<&'static str> {
    let callee = global_function_callee(cx, call)?;
    const PREDS: &[&str] = &[
        "method_exists",
        "function_exists",
        "class_exists",
        "interface_exists",
        "trait_exists",
        "enum_exists",
    ];
    PREDS.iter().copied().find(|p| callee.eq_ignore_ascii_case(p))
}

/// Fold a recognized existence-guard call to a verdict (the N3 machinery). Anything
/// unrecognized or short of closure is `Maybe`.
fn eval_existence_call(w: &WalkCx, folder: &mut dyn Folder, call: &CallExpr) -> Certainty {
    let Some(pred) = existence_predicate(w.cx, call) else {
        return Certainty::Maybe;
    };
    // A2ii/A9: without a live boot surface (or with a runtime-redefinition extension
    // loaded), neither presence nor absence is decidable — the sound subset is Maybe.
    if !folder.absence_family_available() {
        return Certainty::Maybe;
    }
    if pred == "method_exists" {
        // `method_exists(class, 'name')` — two positional literal arguments.
        if !call.positional_only || call.args.len() != 2 {
            return Certainty::Maybe;
        }
        let Some(class_fqn) = existence_class_literal(w.cx, &call.args[0].value) else {
            return Certainty::Maybe;
        };
        let ArgValue::Str(method) = &call.args[1].value else {
            return Certainty::Maybe;
        };
        method_exists_verdict(w.cx, folder, &class_fqn, method)
    } else if pred == "function_exists" {
        if !call.positional_only || call.args.len() != 1 {
            return Certainty::Maybe;
        }
        let ArgValue::Str(name) = &call.args[0].value else {
            return Certainty::Maybe;
        };
        function_exists_verdict(w.cx, folder, name)
    } else {
        // `class_exists`/`interface_exists`/`trait_exists`/`enum_exists('Name')`.
        if !call.positional_only || call.args.is_empty() {
            return Certainty::Maybe;
        }
        let Some(name) = existence_class_literal(w.cx, &call.args[0].value) else {
            return Certainty::Maybe;
        };
        classlike_exists_verdict(w.cx, folder, pred, &name)
    }
}

/// Resolve a *literal* class reference in an existence-predicate argument to an FQN:
/// the `C::class` magic constant (resolved in the call site's namespace context) or
/// a string class name (which PHP treats as fully qualified). A `$var` receiver or
/// any other form is `None` — the verdict then stays `Maybe`, and the conservative
/// guard-respect leg (which CAN read the store) carries the silence for a proven-class
/// variable.
fn existence_class_literal(cx: &Cx, v: &ArgValue) -> Option<String> {
    match v {
        ArgValue::ClassConst(StaticClass::Named(r), name) if name.eq_ignore_ascii_case("class") => {
            Some(cx.class_fqn(r))
        }
        ArgValue::Str(s) => Some(s.trim_start_matches('\\').to_owned()),
        _ => None,
    }
}

/// The three-valued `method_exists(start_fqn, method)` verdict: walk `start_fqn`'s
/// class chain under the S2 closure discipline (ADR-0049 §4). Unlike the absence
/// flagship this ignores `__call`/`__callStatic` — `method_exists` reports only
/// DECLARED methods, magic fallbacks do not make it true. An abstract or any-visibility
/// declaration counts as present (`method_exists` is visibility-blind). Any obstacle
/// to closure (a trait-bearing/enum node, an unresolvable ancestor, a cycle, a
/// conditional node with the dam standing, or an unanswerable/positive boot-surface
/// homonym on any traversed FQN) collapses to `Maybe`.
fn method_exists_verdict(
    cx: &Cx,
    folder: &mut dyn Folder,
    start_fqn: &str,
    method: &str,
) -> Certainty {
    let mut cur = start_fqn.to_owned();
    let mut seen: HashSet<String> = HashSet::new();
    let mut fqns: Vec<String> = Vec::new();
    let mut any_conditional = false;
    let present;
    loop {
        if !seen.insert(cur.to_ascii_lowercase()) {
            return Certainty::Maybe; // cycle — closure cannot terminate soundly.
        }
        let Some((cfile, cd)) = cx.find_class(&cur) else {
            return Certainty::Maybe; // ancestor leaves the project / ambiguous.
        };
        // Enum methods are not lowered; a trait/`uses_traits` node could carry the
        // method invisibly to this walk — either way, closure is unproven.
        if cd.is_enum || cd.is_trait || cd.uses_traits {
            return Certainty::Maybe;
        }
        fqns.push(cur.clone());
        if cd.conditional {
            any_conditional = true;
        }
        if cd.methods.iter().any(|m| m.name.eq_ignore_ascii_case(method)) {
            present = true;
            break;
        }
        match &cd.parent {
            None => {
                present = false;
                break;
            }
            Some(pref) => cur = cx.units[cfile].tree.resolve_class_fqn(pref),
        }
    }
    // A2i: a conditional declaration on the chain re-dams the claim — only the clear
    // whole-universe dam lets either verdict stand.
    if any_conditional && !cx.dam.is_clear() {
        return Certainty::Maybe;
    }
    // A2ii: every traversed FQN must be boot-surface homonym-clear, else the runtime
    // class differs from the textual one and neither presence nor absence is decidable.
    for fqn in &fqns {
        match folder.boot_surface_class_like(fqn) {
            Some(false) => {}
            Some(true) | None => return Certainty::Maybe,
        }
    }
    if present { Certainty::Yes } else { Certainty::No }
}

/// The three-valued `function_exists('name')` verdict (ADR-0049 §6 / S1 existence).
/// A catalog builtin is always present; a uniquely-indexed unconditional userland
/// function is present; an absent name that the boot surface answers NOT-a-function
/// is provably absent. A conditional declaration (dam standing), an ambiguous name,
/// or an unanswerable homonym is `Maybe`.
fn function_exists_verdict(cx: &Cx, folder: &mut dyn Folder, name: &str) -> Certainty {
    let lname = name.trim_start_matches('\\').to_ascii_lowercase();
    // A catalogued builtin is a resident function (`strlen`, `array_map`, …).
    if steins_catalog::effect_labels(&lname).is_some() {
        return Certainty::Yes;
    }
    match cx.index.resolve_function(&lname) {
        Res::Unique(site) => {
            if cx.fn_decl(site).conditional && !cx.dam.is_clear() {
                Certainty::Maybe // a conditional polyfill with the dam standing.
            } else {
                Certainty::Yes
            }
        }
        Res::Ambiguous => Certainty::Maybe,
        Res::Absent => match folder.boot_surface_function(&lname) {
            Some(true) => Certainty::Yes,  // a resident extension function.
            Some(false) => Certainty::No,  // provably absent everywhere.
            None => Certainty::Maybe,
        },
    }
}

/// The three-valued `class_exists`/`interface_exists`/`trait_exists`/`enum_exists`
/// verdict (ADR-0049 §4 / S1 existence). A uniquely-indexed unconditional project
/// class-like of the MATCHING kind is present; an absent name the boot surface reports
/// as resident is present; an absent name the boot surface reports NOT-resident is
/// provably absent. A conditional decl (dam standing), an ambiguous name, a kind
/// mismatch (`class_exists` on an interface), or an unanswerable homonym is `Maybe`.
fn classlike_exists_verdict(
    cx: &Cx,
    folder: &mut dyn Folder,
    pred: &str,
    name: &str,
) -> Certainty {
    let lname = name.trim_start_matches('\\').to_ascii_lowercase();
    match cx.index.resolve_class(&lname) {
        Res::Unique(site) => {
            let (_, cd) = cx.class_decl(site);
            if cd.conditional && !cx.dam.is_clear() {
                return Certainty::Maybe;
            }
            // The predicate queries one specific kind; `enum` satisfies both
            // `enum_exists` and `class_exists` (a PHP enum is a class), while a plain
            // interface/trait never satisfies `class_exists`. A mismatch cannot be
            // proven true here (the name may still resolve to a boot-surface homonym
            // of the right kind), so it stays `Maybe`.
            if classlike_kind_matches(pred, cd) {
                Certainty::Yes
            } else {
                Certainty::Maybe
            }
        }
        Res::Ambiguous => Certainty::Maybe,
        Res::Absent => match folder.boot_surface_class_like(&lname) {
            Some(true) => Certainty::Yes,
            Some(false) => Certainty::No,
            None => Certainty::Maybe,
        },
    }
}

/// Whether a resolved class-like declaration satisfies the given existence predicate:
/// `class_exists` accepts a class or enum (never a bare interface/trait);
/// `interface_exists`/`trait_exists`/`enum_exists` each accept only their own kind.
fn classlike_kind_matches(pred: &str, cd: &ClassDecl) -> bool {
    match pred {
        "class_exists" => !cd.is_interface && !cd.is_trait,
        "interface_exists" => cd.is_interface,
        "trait_exists" => cd.is_trait,
        "enum_exists" => cd.is_enum,
        _ => false,
    }
}

/// The symbol a positive existence guard call vouches for (ADR-0049 §4 guard-respect
/// leg), resolved against the branch store. `None` when the call is not a recognized
/// existence predicate or its subject cannot be pinned to a concrete symbol.
/// `method_exists` additionally resolves a `$var` receiver to its store-known class
/// (the literal `C::class`/string forms go through [`existence_class_literal`]), so
/// the instance idiom `if (method_exists($o,'m')) { $o->m(); }` vouches `C::m` — the
/// exact-textual-match discipline: the vouch key is the RESOLVED class + name.
fn existence_vouch(cx: &Cx, store: &Store, call: &CallExpr) -> Option<Vouch> {
    let pred = existence_predicate(cx, call)?;
    if pred == "method_exists" {
        if !call.positional_only || call.args.len() != 2 {
            return None;
        }
        let ArgValue::Str(method) = &call.args[1].value else {
            return None;
        };
        let class = match &call.args[0].value {
            ArgValue::Var(v) => store.class_of(v)?.to_owned(),
            other => existence_class_literal(cx, other)?,
        };
        Some(Vouch::Method {
            class: class.trim_start_matches('\\').to_ascii_lowercase(),
            method: method.to_ascii_lowercase(),
        })
    } else if pred == "function_exists" {
        if !call.positional_only || call.args.len() != 1 {
            return None;
        }
        let ArgValue::Str(name) = &call.args[0].value else {
            return None;
        };
        Some(Vouch::Function(name.trim_start_matches('\\').to_ascii_lowercase()))
    } else {
        if !call.positional_only || call.args.is_empty() {
            return None;
        }
        let name = existence_class_literal(cx, &call.args[0].value)?;
        Some(Vouch::Class(name.trim_start_matches('\\').to_ascii_lowercase()))
    }
}

/// A clone of `(env, store)` with the refinements `operand` establishes on the
/// given branch polarity applied (ADR-0052 §6 short-circuit threading). Used only
/// to evaluate the *right* operand of an `&&`/`||` at the precision the left
/// operand's runtime outcome guarantees. Native-condition refinements are
/// `Verified` (the runtime executed the test); the clone is discarded after the
/// verdict, so nothing leaks into the caller's env (ADR-0048 §2 walk-locality).
fn threaded_operand_env(
    cx: &Cx,
    operand: &CondExpr,
    then: bool,
    env: &HashMap<String, Known>,
    store: &Store,
    php_minor: Option<(u16, u16)>,
    poisoned: bool,
) -> (HashMap<String, Known>, Store) {
    let mut benv = env.clone();
    let mut bstore = store.clone();
    let mut refs = Vec::new();
    // The DR2 type vocabulary threads with the rest — and, as in the branch walk,
    // runs before the scalar refinements so a minted fact is what they refine:
    // `is_string($s) && strlen($s)` evaluates its right operand under a narrowed
    // `$s` (ADR-0052 §6).
    apply_type_narrowing(cx, operand, then, &mut benv, &mut bstore);
    collect_refine(operand, then, &mut refs, php_minor);
    apply_refinements(&refs, &mut benv, &mut bstore, Stratum::Verified);
    // The operand's own side effects land *after* its test narrowed (a by-ref call
    // in the operand may rebind a variable the test just constrained): forget them
    // so the right operand's verdict reads the post-`operand` env, not a stale one.
    for v in cond_invalidations(cx, operand, env, store, poisoned) {
        benv.remove(&v);
        bstore.unbind(&v);
    }
    (benv, bstore)
}

/// Evaluate a ternary rvalue to an env [`Fact`] (ADR-0031): a decided guard picks
/// the chosen arm's proven value; an undecided guard yields a `OneOf` of the two
/// arms when both resolve to literals, else `None` (unknown → the var is dropped).
fn eval_ternary_fact(
    w: &WalkCx,
    folder: &mut dyn Folder,
    cond: &CondExpr,
    then_val: &ArgValue,
    else_val: &ArgValue,
    env: &HashMap<String, Known>,
    store: &Store,
) -> Option<Fact> {
    let poisoned = w.scope.poisoned;
    let verdict = eval_cond(w, folder, cond, env, store, poisoned);
    // The arms evaluate under the guard's respective refinements (ADR-0052 §6):
    // `$c ? A : B` — `A` runs only when `$c` was truthy (so it sees
    // `then_refinements($c)`), `B` only when `$c` was falsy (`else_refinements`).
    // The arm-selection verdict logic is unchanged; only the arm *envs* thread.
    let (tenv, _) = threaded_operand_env(w.cx, cond, true, env, store, w.cx.php_minor, poisoned);
    let (eenv, _) = threaded_operand_env(w.cx, cond, false, env, store, w.cx.php_minor, poisoned);
    match verdict {
        Certainty::Yes => {
            w.cx
                .resolve_literal(then_val, &tenv, poisoned, folder)
                .and_then(|a| singleton_fact(&a, w.cx.php_minor))
        }
        Certainty::No => {
            w.cx
                .resolve_literal(else_val, &eenv, poisoned, folder)
                .and_then(|a| singleton_fact(&a, w.cx.php_minor))
        }
        Certainty::Maybe => {
            // Undecided guard: the value is one of the two arms. `Fact::from_vals`
            // gives the canonical finite form (a `Singleton` when the arms are
            // equal, else a `OneOf`), or `None` (dropped) when an arm is not
            // representable.
            let t =
                val_of(&w.cx.resolve_literal(then_val, &tenv, poisoned, folder)?, w.cx.php_minor)?;
            let e =
                val_of(&w.cx.resolve_literal(else_val, &eenv, poisoned, folder)?, w.cx.php_minor)?;
            Fact::from_vals(vec![t, e])
        }
    }
}

/// The candidate values of a condition operand: the fact's value set for a known
/// variable, the literal itself, else `None` (unknown → the caller yields `Maybe`).
fn operand_values(
    op: &CondOperand,
    env: &HashMap<String, Known>,
    poisoned: bool,
) -> Option<Vec<ArgValue>> {
    match op {
        CondOperand::Literal(v) => Some(vec![v.clone()]),
        // Only the finite layers (`Singleton`/`OneOf`) offer concrete candidate
        // values for a comparison; an abstract fact has none → `None` → `Maybe`
        // (the sound side). Condition evaluation over `finite_members()`.
        CondOperand::Var(name) if !poisoned => {
            env.get(name).and_then(|k| k.fact.as_ref()?.finite_members().map(|vs| vs.iter().map(arg_of_val).collect()))
        }
        _ => None,
    }
}

/// Evaluate a comparison over two candidate value sets (ADR-0031 OneOf rule: all
/// member pairs agree → that verdict; any disagreement or undecidable pair → Maybe).
fn eval_cmp(op: CmpOp, lhs: &[ArgValue], rhs: &[ArgValue], php_minor: Option<(u16, u16)>) -> Certainty {
    let mut acc: Option<bool> = None;
    for l in lhs {
        for r in rhs {
            let b = match op {
                CmpOp::Identical => php_identical(l, r, php_minor),
                CmpOp::NotIdentical => php_identical(l, r, php_minor).map(|x| !x),
                CmpOp::Loose => php_loose_eq(l, r, php_minor),
                CmpOp::NotLoose => php_loose_eq(l, r, php_minor).map(|x| !x),
                // Ordering: decide only for concrete numeric operands (PHP numeric
                // ordering); any other pairing is undecidable here → `Maybe`. The
                // refinement machinery consumes these guards regardless of verdict.
                CmpOp::Lt => php_num_order(l, r).map(|o| o == std::cmp::Ordering::Less),
                CmpOp::Le => php_num_order(l, r).map(|o| o != std::cmp::Ordering::Greater),
                CmpOp::Gt => php_num_order(l, r).map(|o| o == std::cmp::Ordering::Greater),
                CmpOp::Ge => php_num_order(l, r).map(|o| o != std::cmp::Ordering::Less),
            };
            match b {
                None => return Certainty::Maybe,
                Some(v) => match acc {
                    None => acc = Some(v),
                    Some(prev) if prev != v => return Certainty::Maybe,
                    _ => {}
                },
            }
        }
    }
    Certainty::from_opt(acc)
}

/// PHP numeric ordering of two concrete operands, decided only when **both** are
/// `int`/`float` (comparing as f64); any other pairing (strings, bools, null,
/// arrays) is `None` — undecidable here, so the guard verdict is `Maybe` (sound).
fn php_num_order(a: &ArgValue, b: &ArgValue) -> Option<std::cmp::Ordering> {
    let num = |v: &ArgValue| match v {
        #[allow(clippy::cast_precision_loss)]
        ArgValue::Int(i) => Some(*i as f64),
        ArgValue::Float(f) => Some(*f),
        _ => None,
    };
    let (x, y) = (num(a)?, num(b)?);
    x.partial_cmp(&y)
}

/// Fold a sequence of per-member truth verdicts (`None` = undecidable) into one
/// [`Certainty`]: all-agree → that pole, else `Maybe`.
fn all_agree(iter: impl Iterator<Item = Option<bool>>) -> Certainty {
    let mut acc: Option<bool> = None;
    for b in iter {
        match b {
            None => return Certainty::Maybe,
            Some(v) => match acc {
                None => acc = Some(v),
                Some(prev) if prev != v => return Certainty::Maybe,
                _ => {}
            },
        }
    }
    Certainty::from_opt(acc)
}

/// `operand instanceof Class`: `Yes` only when the operand's proven exact class
/// is-a the target through the project chain; a non-object literal is `No`;
/// everything else (unknown class, chain leaving the project) is `Maybe`.
fn eval_instanceof(
    w: &WalkCx,
    operand: &CondOperand,
    class_ref: &NameRef,
    env: &HashMap<String, Known>,
    store: &Store,
    poisoned: bool,
) -> Certainty {
    match operand {
        CondOperand::Var(name) if !poisoned => {
            let target = w.cx.class_fqn(class_ref);
            match store.class_of(name) {
                Some(obj_fqn) => {
                    // The trinary is-a oracle (ADR-0043): a proven supertype path is a
                    // definite `Yes`; a completely-enumerated hierarchy that excludes
                    // the target is a definite `No` (the branch is dead); an incomplete
                    // hierarchy stays `Maybe` (the FP-safe side). Instanceof still binds
                    // no exactness fact — membership is not exactness (see below).
                    match w.cx.is_a(obj_fqn, &target) {
                        // Yes-side holds for a lower bound too (every descendant of the
                        // proven class is still a `T`) — keep the branch-death precision.
                        IsA::Yes => Certainty::Yes,
                        // No-side needs exactness (audit G1): with a lower-bound `$this`,
                        // the runtime object may be a descendant that IS a `T`, so a
                        // `No` here is not decisive — the then-branch is not dead.
                        IsA::No if store.is_exact(name) => Certainty::No,
                        IsA::No | IsA::Unknown => Certainty::Maybe,
                    }
                }
                // No heap object. First the VALUE side (survey FP class 14): if the
                // variable's value-domain fact proves it holds a *non-object* value on
                // this path (`null`/int/float/string/bool/array — e.g. a call-site
                // `null` imported as `Singleton(null)` by a binding descent), then
                // `instanceof T` is definitionally `false` for every `T` — `null` and
                // every scalar are instances of nothing. This is a decisive `No` that
                // needs NO class reasoning and NO exactness: the G1 exactness discipline
                // (`store.is_exact`) is scoped to *object-class* No verdicts on the heap
                // path above and is untouched here. Sound unconditionally (silence: the
                // then-branch is dead — no PHP value that is not an object is an instance).
                None if env.get(name).and_then(|k| k.fact.as_ref()).is_some_and(fact_is_non_object) => {
                    Certainty::No
                }
                // Otherwise a prior `instanceof` guard may have bound a `Member` fact
                // whose is-a implication decides this test (ADR-0052 §3b, consumer (b)).
                // A11 does NOT thread here: it is scoped to the arm-deletion consumers,
                // and this implication is a separate one.
                None => member_instanceof(w.cx, store.member_of(name), &target),
            }
        }
        // A concrete non-object literal (`null`, `5`, `"x"`, …) is never an
        // instance of a class.
        CondOperand::Literal(v) if v.is_literal() => Certainty::No,
        _ => Certainty::Maybe,
    }
}

/// The `instanceof T2` verdict implied by a variable's guard-derived [`Member`]
/// fact (ADR-0052 §3b), when no exact heap class is known:
///
/// - **`Yes`** — some proven `T1 ∈ yes` has `is_a(T1, T2) = Yes`: the value is
///   already a `T1`, and every `T1` is a `T2`.
/// - **`No`** — some excluded `T1' ∈ no` has `is_a(T2, T1') = Yes`: a `T2` instance
///   would be a `T1'`, which the guard proved the value is not.
/// - **`Maybe`** — otherwise (no fact, or the hierarchy does not decide).
///
/// Sound in both directions and monotone: it only turns `Maybe` into a decided
/// verdict (branch-death → *silence*), never emits.
fn member_instanceof(cx: &Cx, member: Option<&Member>, target: &str) -> Certainty {
    let Some(m) = member else { return Certainty::Maybe };
    if m.yes.iter().any(|t1| cx.is_a(t1, target) == IsA::Yes) {
        return Certainty::Yes;
    }
    if m.no.iter().any(|excluded| cx.is_a(target, excluded) == IsA::Yes) {
        return Certainty::No;
    }
    Certainty::Maybe
}

/// Whether a value-domain [`Fact`] proves the variable holds a **non-object**
/// value on this path (survey FP class 14 — the value-side `instanceof` rule).
/// Every inhabitant of the fact must be a non-object PHP value; then `instanceof
/// T` is `false` for every `T` (`null`, ints, floats, strings, bools and arrays
/// are instances of nothing). All four fact layers denote non-object values —
/// objects live in the heap, never in the value domain — so this holds whenever
/// a value fact is present. A `Singleton`/`OneOf` is checked inhabitant-wise so
/// the rule stays correct (a *mixed* `OneOf` would be `Maybe`) if the value
/// domain ever gains an object inhabitant; the scalar-base layers admit only a
/// scalar base plus optionally `null`, both non-objects.
fn fact_is_non_object(f: &Fact) -> bool {
    match f {
        Fact::Singleton(v) => val_is_non_object(v),
        Fact::OneOf(vs) => vs.iter().all(val_is_non_object),
        Fact::Refined { .. } | Fact::General { .. } => true,
        // A shape fact does denote arrays, which are non-objects — but the
        // value-side `instanceof` rule gains no proof from it, so
        // the arm answers "not proven" (no narrowing), the no-knowledge side.
        Fact::Shape { .. } => false,
    }
}

/// Whether a concrete [`Val`] is a non-object PHP value. Exhaustive by design:
/// no current `Val` variant denotes an object, and if one is ever added this
/// match forces a deliberate decision rather than silently answering `No` to an
/// `instanceof` on a value that could be an object.
fn val_is_non_object(v: &Val) -> bool {
    match v {
        Val::Int(_) | Val::Float(_) | Val::Str(_) | Val::Bool(_) | Val::Null | Val::Array(_) => true,
    }
}

// ---------------------------------------------------------------------------
// Guard refinement (ADR-0031 stage 1 → stage 2 negative facts). A guard narrows
// a variable's fact on the branch where it holds. Stage 1's positive `$x === v`
// binds a Singleton; stage 2 adds the *negative* facts (ADR-0031): `!== null`
// clears nullability, `!== v` removes a member (or, for `!== ''`, adds
// NON_EMPTY), ordering guards intersect an int interval, and truthiness adds
// NON_FALSY / clears null. Instanceof binds nothing — membership is not
// exactness (a subclass instance would make an exact-class fact WRONG).
//
// A refinement that would empty a fact (e.g. an int-range intersection with no
// overlap, reachable only across an `&&` of contradictory guards) drops the
// var's fact rather than signalling branch-death: the decided-guard verdict
// already prunes truly-dead branches up front, so dropping-to-no-fact is the
// sound, simpler fallback here (documented choice).
// ---------------------------------------------------------------------------

/// The fact a parameter's **native** type guarantees at runtime (Feature B), or
/// `None` when nothing representable can be seeded. Only a **single scalar**
/// type (optionally nullable) seeds — a `General{base, nullable}` fact; unions and
/// bool-literal members (`string|false`) have no clean single-`Fact` form and are
/// skipped (documented). By-ref params are never seeded (the caller may hold
/// anything and the var can be rebound); variadic params are skipped.
fn seed_fact(p: &Param) -> Option<Fact> {
    if p.by_ref || p.variadic {
        return None;
    }
    let ty = p.ty.as_ref()?;
    let [TypeMember::Scalar(scalar)] = ty.members.as_slice() else { return None };
    let base = match scalar {
        ScalarType::Int => Base::Int,
        ScalarType::Float => Base::Float,
        ScalarType::String => Base::String,
        ScalarType::Bool => Base::Bool,
    };
    // A `= null` default makes even a non-`?T` param implicitly nullable.
    let nullable = ty.nullable || p.has_null_default;
    Some(Fact::General { base, nullable })
}

/// Seed a parameter's contract-fact arm lane (ADR-0052 §9): the native member list
/// at [`Stratum::Verified`], refined by the `@param` phpdoc envelope at
/// [`Stratum::Asserted`] (ADR-0037 trust order). Returns the declaration-ordered
/// arm list, or `None` when neither source yields a representable arm.
///
/// - **native only** (`int|string $x`, no `@param`): the scalar/instance/null arms,
///   each `Verified` — a runtime-enforced entry fact.
/// - **phpdoc present** (`object $value` + `@param User|Guest`): the phpdoc's arms
///   are the declared contract; an arm the native type *also* proves (`arm_eq` to a
///   native arm) stays `Verified`, every other (refined/added) arm is `Asserted` —
///   a claim, never a proof (so an `Asserted` arm can never premise the proof layer,
///   and an S6 finding it premises inherits the min stratum).
///
/// By-ref / variadic params are skipped (the caller may rebind a by-ref; a variadic
/// is an array), matching [`seed_fact`].
///
/// `resolve_class` namespace-resolves a phpdoc **class** arm's name to its normalized
/// (lowercase, no leading `\`) project FQN, using the callee file's namespace/use
/// context — the same resolution [`Cx::resolve_pclass`] performs for every other
/// phpdoc class contract. Without it, a `@param User|Guest` under a `namespace`
/// would seed the arm lane with the *unqualified* names while the `instanceof`
/// subtrahend (and S6's `find_class`) carry the fully-qualified ones, so subtraction
/// would silently keep both arms and the declared-receiver lane could never close
/// (the latent N4 gap this consumer surfaces). Native `Instance` arms are already
/// FQN-resolved at syntax lowering, so only the phpdoc arms are re-resolved.
fn seed_contract_arms(
    p: &Param,
    phpdoc: Option<&PType>,
    resolve_class: &dyn Fn(&str) -> String,
) -> Option<Vec<ContractArm>> {
    if p.by_ref || p.variadic {
        return None;
    }
    let native: Vec<ContractTy> = p.ty.as_ref().map(native_arms).unwrap_or_default();
    refine_contract_arms(&native, phpdoc, resolve_class)
}

/// The value-lane seed a seeded contract-arm lane contributes (ADR-0062 S3): the
/// canonical [`Fact::Shape`] of a lane whose array vocabulary is ONE arm, plus a
/// `null` arm's nullability (A-G2 — `nullable` is the same side-flag the other
/// abstract layers carry, never a field inside the shape).
///
/// `None` — no value-lane seed — in every other case, each for its own ADR reason:
///
/// * **two or more array arms**: a shape∪shape union stays in the arm lane until a
///   guard subtracts it to one (A-G3); the fact lane never joins them, because the
///   join would lose exactly the discrimination the arms exist to carry;
/// * **a mixed union** (`array{…}|string`): un-facted, exactly as for scalars
///   (A-G2);
/// * **no array arm at all**: the scalar lanes are untouched by this ADR.
///
/// The lowering itself is [`steins_contract::to_shape_fact`] — the ONE lowering,
/// shared with the speller's `is_list` computation, so a seeded fact and its
/// spelled arm can never disagree.
fn seed_shape_fact(arms: &[ContractArm]) -> Option<Fact> {
    let mut shape: Option<steins_domain::ShapeFact> = None;
    let mut nullable = false;
    for arm in arms {
        if matches!(arm.ty, ContractTy::Null) {
            nullable = true;
            continue;
        }
        let lowered = steins_contract::to_shape_fact(&arm.ty)?;
        if shape.is_some() {
            return None;
        }
        shape = Some(lowered);
    }
    Some(Fact::Shape { shape: Box::new(shape?), nullable })
}

/// Statement-level inline `/** @var T $x */` casts (ADR-0073): the docblock
/// immediately preceding a trace statement re-declares the named variable's type
/// from that statement on — PHPStan's inline-`@var` reading. The lowering is the
/// `@param` entry seeding's ([`seed_contract_arms`]) minus the native envelope:
/// every arm seeds `Asserted` (ADR-0037 — a docblock the runtime never checks),
/// and a lane whose array vocabulary collapsed to one arm seeds the value lane
/// with its canonical shape fact exactly as ADR-0062 S3's entry seeding does.
///
/// It is a **cast, not a refinement**: every carrier of the old value dies first
/// (`env.remove` + [`Store::unbind`] — the same forgetting a rebind performs),
/// because the tag re-declares what the variable holds rather than narrowing the
/// declared possibilities. Losing a proven value to an assertion only ever
/// silences (the proof-layer consumers take `Verified` facts, which the cast
/// never mints), so the trade is PHPStan parity at zero FP cost.
///
/// The guards, each its own reason:
///
/// * **property targets** (`@var T $this->p`, `@var T $obj->p`, bare `$this`)
///   never cast — the tag speaks about the property, and casting the *receiver*
///   could manufacture declared-receiver findings (S6) out of a tag that says
///   nothing about the receiver;
/// * **`@template` names shadow** exactly as in the declaration envelopes (issue
///   #5): the enclosing declaration's and, for a method, the class-level set;
/// * **an unparseable or unlowerable type casts nothing** — the same status-quo
///   silence a malformed `@param` gets (ADR-0029: a missing envelope only
///   silences), never a `Barrier`-style erasure;
/// * **a prefixed `@phpstan-var`/`@psalm-var` displaces the plain `@var`** for
///   the same variable in the same docblock (the ADR-0029 precedence rule).
///
/// Applied in the plain per-scope pass only: a binding descent carries
/// call-site-proven values, and propagated truth outranks a docblock assertion —
/// the same reason the ADR-0052 §9 entry seeding skips a descent-bound param
/// (a bound value moots the declared lane).
fn apply_inline_var_casts(
    w: &WalkCx,
    stmt: &Stmt,
    env: &mut HashMap<String, Known>,
    store: &mut Store,
) {
    let cx = w.cx;
    let Some(doc) = cx.tree().stmt_docblock(stmt.span.start) else { return };
    let tags = scan_docblock(&doc.text);
    // Computed on the first acting tag only — most adjacent docblocks carry none.
    let mut shadow: Option<HashSet<String>> = None;
    for tag in &tags {
        if !matches!(tag.kind, TagKind::Var) || tag.property_target {
            continue;
        }
        let Some(var) = &tag.var_name else { continue };
        let name = var.trim_start_matches('$');
        if name.is_empty() || name == "this" {
            continue;
        }
        if !tag.prefixed
            && tags.iter().any(|t| {
                matches!(t.kind, TagKind::Var) && t.prefixed && t.var_name == tag.var_name
            })
        {
            continue;
        }
        let Some(mut pt) = parse_tag_type(&tag.type_text) else { continue };
        let sh = shadow.get_or_insert_with(|| cx.scope_template_shadow(w.scope));
        neutralize_templates(&mut pt, sh);
        // Class arms resolve in the statement's namespace context, matching the
        // FQNs the `instanceof` subtrahend and S6's `find_class` carry.
        let resolve = |n: &str| {
            cx.resolve_pclass(cx.cur, stmt.span.start, n).trim_start_matches('\\').to_ascii_lowercase()
        };
        let Some(arms) = refine_contract_arms(&[], Some(&pt), &resolve) else { continue };
        if arms.is_empty() {
            continue;
        }
        env.remove(name);
        store.unbind(name);
        if let Some(fact) = seed_shape_fact(&arms) {
            let line = cx.tree().position(stmt.span.start).line;
            env.insert(
                name.to_owned(),
                // ALWAYS `Asserted` — the same A-G9 corollary the entry seeding
                // pins: shape-derived facts never feed proof-layer findings.
                Known::value_strat(
                    fact,
                    line,
                    Some("declared array shape".to_owned()),
                    Stratum::Asserted,
                ),
            );
        }
        store.contract.insert(name.to_owned(), arms);
    }
}

/// The shared core of declared-contract arm refinement (ADR-0052 §9), used for both
/// the `@param` entry-state seeding ([`seed_contract_arms`]) and the declared-return
/// call-site seeding ([`call_return_arms`]): the runtime-guaranteed native member
/// list refined by a declared phpdoc envelope, under the trust order's subset
/// discipline.
///
/// With **no** phpdoc envelope, each native member is a `Verified` arm (PHP enforces
/// native param/return types at runtime). With one, each lowered phpdoc arm refines
/// *within* the native envelope: a phpdoc arm the native base **provably cannot
/// cover** is a contradiction (`string` under `int`) and seeds NOTHING — the docblock
/// never widens past the runtime-enforced native type. An arm covering a native
/// member exactly is `Verified`; a strict refinement within it (`positive-int` under
/// `int`) is `Asserted`. An undecidable is-a (two unrelated classes — no hierarchy in
/// this crate) is NOT a contradiction; the arm stays (`Asserted`), the FP-safe side.
/// Where NO native type exists, every phpdoc arm seeds `Asserted`.
fn refine_contract_arms(
    native: &[ContractTy],
    phpdoc: Option<&PType>,
    resolve_class: &dyn Fn(&str) -> String,
) -> Option<Vec<ContractArm>> {
    match phpdoc {
        Some(pt) => {
            refine_declared_arms(native, flatten_arms(steins_contract::lower(pt)), resolve_class)
        }
        None => {
            let out: Vec<ContractArm> =
                native.iter().cloned().map(|ty| ContractArm { ty, stratum: Stratum::Verified }).collect();
            (!out.is_empty()).then_some(out)
        }
    }
}

/// [`refine_contract_arms`]' declared-side body, over an **already-flattened** arm
/// list rather than a parsed docblock.
///
/// Split out for the ADR-0069 builtin floor (issue #79), which reaches the same law
/// from a catalog type *string*: the row is lowered by `lower_str`, flattened by
/// [`flatten_arms`], and refined here against an empty native list — so a builtin's
/// declared return and a project function's declared return travel one lowering
/// path, and the builtin's arms come out `Asserted` for the same structural reason
/// a phpdoc arm over an untyped signature does (nothing runtime-enforced covers it).
fn refine_declared_arms(
    native: &[ContractTy],
    declared: Vec<ContractTy>,
    resolve_class: &dyn Fn(&str) -> String,
) -> Option<Vec<ContractArm>> {
    let out: Vec<ContractArm> = declared
        .into_iter()
        .filter_map(|ty| {
            // Resolve a top-level class arm against the declaring namespace; the
            // native member list already holds FQNs, so this aligns the two.
            let ty = match ty {
                ContractTy::Class(n) => ContractTy::Class(resolve_class(&n)),
                other => other,
            };
            if !native.is_empty() {
                let covered = native
                    .iter()
                    .fold(Certainty::No, |acc, n| acc.or(normalize::subsumes(n, &ty)));
                if covered.is_no() {
                    return None;
                }
            }
            let stratum = if native.iter().any(|n| normalize::arm_eq(n, &ty)) {
                Stratum::Verified
            } else {
                Stratum::Asserted
            };
            Some(ContractArm { ty, stratum })
        })
        .collect();
    // Canonicalize the minted list before it enters the lane: a mined row like
    // `strpos`' `positive-int|0|false` carries the two-armed spelling of one
    // interval, and every later reader (guard subtraction, join, dump) should see
    // the denotation once (issue #90).
    let mut out = out;
    absorb_contract_arms(&mut out);
    (!out.is_empty()).then_some(out)
}

/// The declared-return arm list to seed the assigned variable of `$x = f(...)` /
/// `$x = $o->m(...)` at a call site (ADR-0052 §9, the return direction; ADR-0075
/// for methods). For a uniquely-resolved USER function target (the same
/// `resolve_user_fn_any` the contract lane uses, so it fires on named-argument
/// calls too), or a resolved method/static target via [`resolve_call_target`], the
/// native return type seeds `Verified` arms and the `@return` phpdoc refines
/// `Asserted` within it, through [`refine_contract_arms`].
///
/// **Verified membership is never exactness.** A `: Foo` native return seeds an
/// Instance-*membership* arm (`ContractTy::Class`), NOT an exact-class object: PHP
/// guarantees the value *is a* `Foo`, but the concrete runtime class may be any
/// subclass. So this arm feeds the S6-style declared-receiver contract lane and the
/// `eval_instanceof` Yes-side only; it must NEVER satisfy an exactness-requiring proof
/// leg (the ADR-0052 §3 NOT-fed list: no S2/arity/descent consumption, the G1/A1
/// membership-is-not-exactness discipline). The arms are the FLOOR below values: a
/// caller seeds them only after every proven-value path (a folded literal, the R1
/// builtin return envelope, a bindable summary) has declined. `None` for a
/// builtin / unknown / dynamic target, a constructor, or a target with no declared
/// return type at all.
fn call_return_arms(
    cx: &Cx,
    call: &CallExpr,
    store: &Store,
    this_exact: Option<&str>,
    enclosing_class: Option<&str>,
    poisoned: bool,
) -> Option<Vec<ContractArm>> {
    if let Some(site) = cx.resolve_user_fn_any(call) {
        return fn_return_arms(cx, site);
    }
    // Constructors are the ADR-0036 exactness lane, not a value-return floor.
    if matches!(call.receiver, Callee::Construct { .. }) {
        return None;
    }
    let target = resolve_call_target(cx, &call.receiver, store, this_exact, enclosing_class, poisoned)?;
    method_return_arms(cx, &target)
}

/// [`call_return_arms`] for a call known only by its **simple name** (issue #60):
/// the declared-return floor of a call in value position, where no [`CallExpr`]
/// exists. Resolution is [`value_lane_fn_site`], the same hardened rule as the
/// value lane's [`project_call_summary`] — the two must agree on the target or the
/// floor could name a different function than the summary descended into.
fn call_return_arms_by_name(cx: &Cx, folder: &mut dyn Folder, name: &str) -> Option<Vec<ContractArm>> {
    fn_return_arms(cx, value_lane_fn_site(cx, folder, name)?)
}

/// The declared-return contract arms of the project function at `site` — the shared
/// body of [`call_return_arms`] (a resolved [`CallExpr`]) and
/// [`call_return_arms_by_name`] (a value-position simple name).
fn fn_return_arms(cx: &Cx, site: Site) -> Option<Vec<ContractArm>> {
    let decl = cx.fn_decl(site);
    let native: Vec<ContractTy> = decl.ret.as_ref().map(native_arms).unwrap_or_default();
    // The callee's own `@return` envelope (with its function-level `@template` names
    // already shadowed to `Opaque` by `parse_envelopes`, issue #5). Class arms resolve
    // in the CALLEE's file/namespace (where the return type is written), matching how
    // the native return member list's FQNs were resolved at lowering.
    let phpdoc = parse_envelopes(decl.docblock.as_deref()).and_then(|e| e.ret);
    let off = decl.span.start;
    let resolve = |n: &str| {
        cx.resolve_pclass(site.file, off, n).trim_start_matches('\\').to_ascii_lowercase()
    };
    refine_contract_arms(&native, phpdoc.as_ref(), &resolve)
}

/// The declared-return contract arms of a resolved method/static target (ADR-0075
/// floor parity with free functions). Same native + `@return` refinement as
/// [`fn_return_arms`]; class-level `@template` names shadow in the method docblock
/// (issue #5), matching [`scope_return_phpdoc`]'s method leg.
fn method_return_arms(cx: &Cx, target: &CallTarget<'_>) -> Option<Vec<ContractArm>> {
    let method = target.method;
    let native: Vec<ContractTy> = method.ret.as_ref().map(native_arms).unwrap_or_default();
    let mut envelopes = parse_envelopes(method.docblock.as_deref());
    if let Some(e) = &mut envelopes {
        e.shadow_templates(&template_names_of(target.declaring_class.docblock.as_deref()));
    }
    let phpdoc = envelopes.and_then(|e| e.ret);
    let off = method.span.start;
    let file = target.class_file;
    let resolve = |n: &str| {
        cx.resolve_pclass(file, off, n).trim_start_matches('\\').to_ascii_lowercase()
    };
    refine_contract_arms(&native, phpdoc.as_ref(), &resolve)
}

/// Lower a native scalar/union type to contract arms (declaration order, then a
/// `null` arm when nullable). Every native member is representable: the four
/// scalars, `false`/`true` literals, and object `Instance` members (the lowercase
/// FQN, matching [`ContractTy::Class`]'s normalization).
fn native_arms(ty: &NativeType) -> Vec<ContractTy> {
    let mut arms: Vec<ContractTy> = ty
        .members
        .iter()
        .map(|m| match m {
            TypeMember::Scalar(ScalarType::Int) => ContractTy::Base(Base::Int),
            TypeMember::Scalar(ScalarType::Float) => ContractTy::Base(Base::Float),
            TypeMember::Scalar(ScalarType::String) => ContractTy::Base(Base::String),
            TypeMember::Scalar(ScalarType::Bool) => ContractTy::Base(Base::Bool),
            TypeMember::BoolLiteral(b) => ContractTy::LitBool(*b),
            TypeMember::Instance { fqn, .. } => ContractTy::Class(fqn.clone()),
            TypeMember::InstanceInter(cs) => {
                ContractTy::Inter(cs.iter().map(|c| ContractTy::Class(c.fqn.clone())).collect())
            }
        })
        .collect();
    if ty.nullable {
        arms.push(ContractTy::Null);
    }
    arms
}

/// Flatten a lowered contract into a top-level arm list, dissolving nested unions
/// (a declared `User|Guest|null` lowers to a `Union`; each member is one arm). A
/// non-union lowers to a single arm.
fn flatten_arms(cty: ContractTy) -> Vec<ContractTy> {
    match cty {
        ContractTy::Union(members) => members.into_iter().flat_map(flatten_arms).collect(),
        other => vec![other],
    }
}

/// One narrowing a guard establishes for a variable on a given branch.
enum Refine {
    /// `$x === v` (then) — narrow to exactly this value.
    Exact(String, Val),
    /// `$x !== null` (then) / `$x === null` (else) — drop nullability: clear the
    /// abstract `nullable` flag, or remove the `null` member of a finite fact.
    NotNull(String),
    /// `$x !== v` (non-null, then) — remove `v` from a finite fact; for a
    /// String-based abstract fact and `v == ""`, add `NON_EMPTY` instead.
    Exclude(String, Val),
    /// `$x > k` &c. — intersect an Int-based abstract fact with this interval.
    IntRange(String, IntRange),
    /// `if ($x)` (then) — truthiness: clear nullability and, for a String-based
    /// fact, add `NON_FALSY` (a truthy string is neither `""` nor `"0"`).
    Truthy(String),
}

/// The refinements that hold when `cond` is TRUE (the then-branch).
fn then_refinements(cond: &CondExpr, php_minor: Option<(u16, u16)>) -> Vec<Refine> {
    let mut out = Vec::new();
    collect_refine(cond, true, &mut out, php_minor);
    out
}

/// The refinements that hold when `cond` is FALSE (the else-branch).
fn else_refinements(cond: &CondExpr, php_minor: Option<(u16, u16)>) -> Vec<Refine> {
    let mut out = Vec::new();
    collect_refine(cond, false, &mut out, php_minor);
    out
}

/// Guard calls whose `@phpstan-assert-if-true`/`-if-false` envelope applies on the
/// given branch polarity, in source order — the same And-then / Or-else
/// distribution as [`collect_refine`], so a call nested in a threaded `&&`/`||`
/// (`if ($a && isNonEmpty($s))`) reaches its consumption point (ADR-0052 §6). The
/// paired `bool` is whether the call returned `true` on this branch (it flips under
/// `Not`), selecting the [`AssertKind`] polarity.
fn collect_guard_calls<'a>(cond: &'a CondExpr, then: bool, out: &mut Vec<(&'a CallExpr, bool)>) {
    match cond {
        CondExpr::Call { call, .. } => out.push((call, then)),
        CondExpr::Not(c) => collect_guard_calls(c, !then, out),
        CondExpr::And(a, b) if then => {
            collect_guard_calls(a, true, out);
            collect_guard_calls(b, true, out);
        }
        CondExpr::Or(a, b) if !then => {
            collect_guard_calls(a, false, out);
            collect_guard_calls(b, false, out);
        }
        _ => {}
    }
}

/// The calls this branch proves returned a **truthy** value — the witness the
/// out-parameter seed (ADR-0077 §3.2) consumes, in source order.
///
/// Its `&&`/`||`/`!` distribution is [`collect_guard_calls`]', and for a call in
/// guard position it selects exactly the same calls that function's `returns_true`
/// flag did. What it adds is the **compared** call: `preg_match($re, $s, $m) === 1`
/// proves the result is `1`, which is as truthy as a bare `preg_match(…)` guard
/// proves it, and PHPStan types both.
///
/// Kept apart from [`collect_guard_calls`] deliberately, because the two ask
/// different questions. `@phpstan-assert-if-true` is stated about the callee
/// *returning `true`*, and `f($x) === 1` does not witness that — `1` is truthy
/// but is not `true`. Feeding compared calls into the assert consumption would
/// silently widen every envelope in the project; feeding them into the seed only
/// asserts what the comparison itself proved.
fn collect_truthy_calls<'a>(
    cond: &'a CondExpr,
    then: bool,
    php_minor: Option<(u16, u16)>,
    out: &mut Vec<&'a CallExpr>,
) {
    match cond {
        CondExpr::Call { call, .. } if then => out.push(call),
        CondExpr::Cmp { op, lhs, rhs } => {
            out.extend(cmp_truthy_witness(*op, lhs, rhs, then, php_minor));
        }
        CondExpr::Not(c) => collect_truthy_calls(c, !then, php_minor, out),
        CondExpr::And(a, b) if then => {
            collect_truthy_calls(a, true, php_minor, out);
            collect_truthy_calls(b, true, php_minor, out);
        }
        CondExpr::Or(a, b) if !then => {
            collect_truthy_calls(a, false, php_minor, out);
            collect_truthy_calls(b, false, php_minor, out);
        }
        _ => {}
    }
}

/// The call a comparison proves truthy on this branch polarity, or `None`.
///
/// The test is not a table of blessed shapes — it is the claim itself, checked:
/// **every** value that satisfies the comparison must be truthy, i.e. no falsy
/// value may satisfy it. PHP's falsy values are a finite, enumerable set
/// ([`FALSY_LITERALS`]), and the comparison semantics are the ones the evaluator
/// already implements, so the question is answered by running each falsy value
/// through [`eval_cmp`] rather than by reasoning about operators in prose.
///
/// It lands where it should: `f() === 1` and `f() == 1` prove truthy on the then
/// branch (nothing falsy is identical or loosely equal to `1`); `f() !== 1` and
/// `f() != 1` prove it on the *else* branch (every falsy value differs from `1`,
/// so none of them survives the negation); `f() === 0`, `f() !== false` and
/// `f() === ''` prove nothing, on either branch.
fn cmp_truthy_witness<'a>(
    op: CmpOp,
    lhs: &'a CondOperand,
    rhs: &'a CondOperand,
    then: bool,
    php_minor: Option<(u16, u16)>,
) -> Option<&'a CallExpr> {
    let (call, lit) = match (lhs, rhs) {
        (CondOperand::Other { call, .. }, CondOperand::Literal(v))
        | (CondOperand::Literal(v), CondOperand::Other { call, .. }) => (call.as_deref()?, v),
        _ => return None,
    };
    // On the then branch the comparison held, so a falsy result must be one the
    // comparison *rejects*; on the else branch it failed, so a falsy result must
    // be one it *accepts*. Anything undecidable (`Maybe`) refuses, silently.
    let excluded = if then { Certainty::No } else { Certainty::Yes };
    falsy_literals()
        .iter()
        .all(|f| {
            eval_cmp(op, std::slice::from_ref(f), std::slice::from_ref(lit), php_minor) == excluded
        })
        .then_some(call)
}

/// Every falsy value in PHP, as a literal. The list is exhaustive by the language
/// definition — `null`, `false`, `0`, `0.0`, `''`, `'0'` and the empty array —
/// and [`php_truthy`] is its other half (each of these is a value it answers
/// `Some(false)` for, and nothing else is).
fn falsy_literals() -> [ArgValue; 7] {
    [
        ArgValue::Null,
        ArgValue::Bool(false),
        ArgValue::Int(0),
        ArgValue::Float(0.0),
        ArgValue::Str(String::new()),
        ArgValue::Str("0".to_owned()),
        ArgValue::Array(Vec::new()),
    ]
}

/// Every retained guard call anywhere in the condition (both polarities), for the
/// position-sequenced escape/sweep and by-ref invalidation that apply on *every*
/// resulting path (a call in either operand may have executed on the excluded path).
fn collect_guard_calls_any(cond: &CondExpr) -> Vec<&CallExpr> {
    let mut out = Vec::new();
    collect_all_calls(cond, &mut out);
    out
}

fn collect_all_calls<'a>(cond: &'a CondExpr, out: &mut Vec<&'a CallExpr>) {
    match cond {
        CondExpr::Call { call, .. } => out.push(call),
        // A call in a comparison/`instanceof` operand escapes its arguments and
        // sweeps their props exactly as one in guard position does (issue #158 —
        // the same traversal gap that lost the by-ref invalidation).
        CondExpr::Cmp { lhs, rhs, .. } => {
            out.extend(operand_call(lhs));
            out.extend(operand_call(rhs));
        }
        CondExpr::Instanceof { operand, .. } => out.extend(operand_call(operand)),
        CondExpr::Not(c) => collect_all_calls(c, out),
        CondExpr::And(a, b) | CondExpr::Or(a, b) => {
            collect_all_calls(a, out);
            collect_all_calls(b, out);
        }
        _ => {}
    }
}

/// The resolvable call an operand **is**, when it is one.
fn operand_call(operand: &CondOperand) -> Option<&CallExpr> {
    match operand {
        CondOperand::Other { call, .. } => call.as_deref(),
        _ => None,
    }
}

/// Collect the refinements a condition implies on the given polarity (`then` =
/// true-path, `!then` = false-path). Negation flips polarity; `&&` distributes on
/// the true-path, `||` on the false-path (De Morgan).
fn collect_refine(cond: &CondExpr, then: bool, out: &mut Vec<Refine>, php_minor: Option<(u16, u16)>) {
    match cond {
        CondExpr::Cmp { op, lhs, rhs } => {
            collect_cmp_refine(*op, lhs, rhs, then, out, php_minor);
        }
        CondExpr::Truthy(op) => {
            // Only the true-path of a bare truthiness test refines (the false-path
            // — "falsy" — is not cleanly representable: `""`, `"0"`, `0`, null …).
            if then && let CondOperand::Var(v) = op {
                out.push(Refine::Truthy(v.clone()));
            }
        }
        CondExpr::Not(c) => collect_refine(c, !then, out, php_minor),
        CondExpr::And(a, b) if then => {
            collect_refine(a, true, out, php_minor);
            collect_refine(b, true, out, php_minor);
        }
        CondExpr::Or(a, b) if !then => {
            collect_refine(a, false, out, php_minor);
            collect_refine(b, false, out, php_minor);
        }
        _ => {}
    }
}

/// Refinements from a comparison guard on a given polarity.
fn collect_cmp_refine(
    op: CmpOp,
    lhs: &CondOperand,
    rhs: &CondOperand,
    then: bool,
    out: &mut Vec<Refine>,
    php_minor: Option<(u16, u16)>,
) {
    // Identity/equality guards over a (var, literal) pair.
    if let Some((v, val)) = var_literal(lhs, rhs) {
        // The *effective* operator on this branch: `===`/`!==` flip under `!then`.
        let identical = match (op, then) {
            (CmpOp::Identical, true) | (CmpOp::NotIdentical, false) => Some(true),
            (CmpOp::NotIdentical, true) | (CmpOp::Identical, false) => Some(false),
            _ => None,
        };
        if let Some(identical) = identical
            && let Some(vv) = val_of(&val, php_minor)
        {
            match (identical, &vv) {
                (true, _) => out.push(Refine::Exact(v, vv)),
                (false, Val::Null) => out.push(Refine::NotNull(v)),
                (false, _) => out.push(Refine::Exclude(v, vv)),
            }
            return;
        }
    }
    // Ordering guards over a (var, int-literal) pair → an interval intersection.
    if let Some((v, k, var_on_left)) = var_int_literal(lhs, rhs) {
        // Normalize so the operator reads `var <op> k`.
        let eff_op = if var_on_left { op } else { flip_ordering(op) };
        // On the false-path the guard is negated.
        let branch_op = if then { eff_op } else { negate_ordering(eff_op) };
        if let Some(range) = ordering_range(branch_op, k) {
            out.push(Refine::IntRange(v, range));
        }
    }
}

/// Collect the `instanceof` guards a condition establishes on the given polarity
/// (`then` = true-path, `!then` = false-path), with the **branch** polarity per
/// guard (`positive` = the guard held). Negation flips polarity; `&&` distributes
/// on the true-path, `||` on the false-path — the same De Morgan distribution as
/// [`collect_refine`], so an `instanceof` nested in `$a && $v instanceof T` reaches
/// its narrowing point. Only bare-variable operands are collected (a `$x->p
/// instanceof T` is depth-1 property narrowing, N5's concern, not here).
fn collect_instanceof<'a>(
    cond: &'a CondExpr,
    then: bool,
    out: &mut Vec<(&'a str, &'a NameRef, bool)>,
) {
    match cond {
        CondExpr::Instanceof { operand: CondOperand::Var(v), class_ref } => {
            out.push((v.as_str(), class_ref, then));
        }
        CondExpr::Not(c) => collect_instanceof(c, !then, out),
        CondExpr::And(a, b) if then => {
            collect_instanceof(a, true, out);
            collect_instanceof(b, true, out);
        }
        CondExpr::Or(a, b) if !then => {
            collect_instanceof(a, false, out);
            collect_instanceof(b, false, out);
        }
        _ => {}
    }
}

/// Apply a branch's **class-fact** narrowing (ADR-0052 N4) to its cloned `Store`:
/// the two NEW carriers, mutated arm-wise through the real is-a oracle. This runs
/// beside [`apply_refinements`] (which owns the value-domain `Fact` carrier).
///
/// 1. Each `instanceof T` guard on this branch subtracts from the variable's
///    **contract lane** — the negative branch deletes arm `M` iff `is_a(M, T) = Yes`
///    (is-a inherited), the positive branch deletes `M` only when `M` is final/enum
///    and `is_a(M, T) = No` — through steins-contract's single per-arm judgment
///    ([`normalize::subtract_arm`]), preserving each surviving arm's stratum.
///    An emptied lane drops to no-fact (never a death signal, §2). The `oracle`
///    threads the A11 demotion into exactly these arm-deletion queries.
/// 2. The same guard binds the **`Member`** fact at `Verified` (the runtime test
///    executed): the positive branch adds `T` to `yes`, the negative to `no`.
/// 3. A `!== null` on this branch subtracts the `null` arm from the contract lane
///    (the nullable-bit analogue for the arm carrier).
/// 4. A `!== v` on this branch subtracts the **value** `v` from the contract lane
///    ([`normalize::Subtrahend::Value`], ADR-0052 §2): an arm dies iff the literal
///    provably covers the whole arm (`Yes`), and `Maybe` keeps it. This is what
///    strips the `false` arm of a `T|false` row under `if (strpos(…) !== false)`,
///    and it is general over literals — an `!== 2` deletes a `2` arm, an `!== 'GET'`
///    deletes a `'GET'` arm. The interior-point rule is exactly what keeps it
///    sound: `false` does NOT cover a general `bool` arm (a `bool` may still be
///    `true`), so a `bool` arm survives `!== false`. The one **partial** deletion
///    is the interval endpoint: `!== 0` clips an `int<0, max>` arm to
///    `int<1, max>` ([`normalize::ArmFate::Narrows`]), while an interior `!== 5`
///    leaves it whole — the gap has no arm spelling.
///
/// Two neighbouring narrowings are deliberately NOT here:
///
/// * **`Refine::Truthy`** (`if ($pos)` over an `int|false` row). Truthiness kills
///   `0` and `''` as well as `false`, so it is not a value subtraction at all;
///   pretending it were would silently narrow `int|false` to `int` on a branch
///   where `$pos` cannot be `0`. That is PHPStan's classic `strpos` footgun and it
///   needs its own designed subtrahend, not a reuse of this seam.
/// * **Keep-only narrowing on the positive branch** (`if ($x === false)` ⇒ the arm
///   lane becomes `{false}`). The value lane's `Refine::Exact` already owns the
///   positive branch, and an arm lane is a *subtraction* carrier by construction
///   (§2): every mutation here removes arms it can prove dead. Intersecting to a
///   singleton is a different judgment and is not implemented.
fn apply_class_narrowing(w: &WalkCx, cond: &CondExpr, then: bool, store: &mut Store) {
    let oracle = ProjectIsa { cx: w.cx, demote_catalog: w.cx.a11_demote_catalog() };

    let mut ins = Vec::new();
    collect_instanceof(cond, then, &mut ins);
    for (var, class_ref, positive) in ins {
        let norm = w.cx.class_fqn(class_ref).trim_start_matches('\\').to_ascii_lowercase();
        // (1) Contract-arm subtraction (both polarities), strata preserved.
        subtract_contract_lane(
            store,
            var,
            &normalize::Subtrahend::Class { fqn: norm.clone(), polarity: positive },
            &oracle,
        );
        // (2) Member binding: positive → `yes`, negative → `no`.
        let m = store.members.entry(var.to_owned()).or_default();
        let bucket = if positive { &mut m.yes } else { &mut m.no };
        if !bucket.iter().any(|c| c.eq_ignore_ascii_case(&norm)) {
            bucket.push(norm);
        }
    }

    // (3)/(4) `!== null` and `!== v` on this branch → subtract from the contract
    // lane. `collect_refine` already carries the branch polarity, so both spellings
    // of the same guard arrive here: `!== v` on the then-branch and `=== v` on the
    // else-branch both produce `Exclude` (and `var_literal` normalizes the Yoda
    // order). `Refine::Exact`, `Truthy` and `IntRange` are the value lane's — see
    // the refusals in this function's doc comment.
    let mut refs = Vec::new();
    collect_refine(cond, then, &mut refs, w.cx.php_minor);
    for r in &refs {
        match r {
            Refine::NotNull(var) => {
                subtract_contract_lane(store, var, &normalize::Subtrahend::Null, &oracle);
            }
            Refine::Exclude(var, v) => {
                subtract_contract_lane(
                    store,
                    var,
                    &normalize::Subtrahend::Value(v.clone()),
                    &oracle,
                );
            }
            _ => {}
        }
    }
}

/// Subtract `sub` from `var`'s contract lane in `store`, arm-wise, preserving each
/// surviving arm's stratum (the single per-arm judgment [`normalize::subtract_arm`]
/// applied to the stratified lane — a partial deletion, an interval arm clipped at
/// its endpoint, keeps the stratum of the arm it shrinks); an emptied lane drops
/// to no-fact.
fn subtract_contract_lane(
    store: &mut Store,
    var: &str,
    sub: &normalize::Subtrahend,
    oracle: &dyn normalize::IsaOracle,
) {
    if let Some(arms) = store.contract.get_mut(var) {
        arms.retain_mut(|a| match normalize::subtract_arm(sub, &a.ty, oracle) {
            normalize::ArmFate::Survives => true,
            normalize::ArmFate::Dies => false,
            normalize::ArmFate::Narrows(narrowed) => {
                a.ty = narrowed;
                true
            }
        });
        if arms.is_empty() {
            store.contract.remove(var);
        }
    }
}

// ---------------------------------------------------------------------------
// Type-predicate guard vocabulary (ADR-0064 seam (v)).
//
// PHPStan ships this family as a `FunctionTypeSpecifyingExtension` set; Steins
// imports it into the existing narrowing machinery (ADR-0052) rather than a new
// extension mechanism — the arm lane subtracts, the value-fact lane refines, and
// `assert(is_string($x))` inherits both for free because assert lowers its
// argument to the same `CondExpr` and runs the same walk.
//
// **Both polarities are pinned per predicate, and each is a different question.**
// For an arm `M` and a predicate `P`, `pred_holds_on_arm` answers the trinary
// "does *every* value `M` admits satisfy `P`?":
//   * the TRUE branch deletes `M` iff that answer is `No`  — `P` refutes the arm;
//   * the FALSE branch deletes `M` iff that answer is `Yes` — `P` proves the arm,
//     so no value of `M` survives the negation.
// `Maybe` keeps the arm on both branches: ADR-0052 §2's "an arm dies only on a
// definite verdict", verbatim.
//
// **`ctype_*` is deliberately NOT here.** `ctype_digit` and kin are locale- and
// byte-sensitive (and, before PHP 8.1, silently reinterpreted int arguments in
// `-128..=255` as byte values), so the string-predicate mapping they *look* like
// needs its own measured slice; DR2 declines them rather than guessing.
// ---------------------------------------------------------------------------

/// One recognized `is_*` type predicate.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TypePred {
    /// `is_string`
    Str,
    /// `is_int` / `is_integer` / `is_long`
    Int,
    /// `is_float` / `is_double`
    Float,
    /// `is_bool`
    Bool,
    /// `is_array`
    Array,
    /// `is_null`
    Null,
    /// `is_object`
    Object,
    /// `is_scalar`
    Scalar,
    /// `is_numeric`
    Numeric,
    /// `is_callable`
    Callable,
    /// `is_iterable`
    Iterable,
}

/// A value's PHP **runtime** type class — what `gettype()` reports, which is the
/// only thing the `is_*` family actually tests. Deliberately distinct from the
/// contract crate's *acceptance* relation: `admits_val(Base(Float), Int(5))` is
/// `Yes` (PHPStan's "float accepts int" declaration rule), but `is_float(5)` is
/// `false` — a `float`-declared slot holds a float at runtime, because PHP widens
/// at the boundary. The judgment below reads declared arms as runtime types, the
/// same reading PHPStan's own type specifier uses.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RtKind {
    Null,
    Bool,
    Int,
    Float,
    String,
    Array,
    Object,
}

/// The **exhaustive** set of runtime kinds an arm's values can have, or `None`
/// when the arm spans an unknown set (`mixed`, its cuts, `Opaque`, `never`).
/// Unknown keeps the arm on both polarities.
fn arm_rt_kinds(arm: &ContractTy) -> Option<&'static [RtKind]> {
    use ContractTy as C;
    use RtKind::{Array, Bool, Float, Int, Null, Object, String as Str};
    Some(match arm {
        C::Null => &[Null],
        C::Base(Base::Int) | C::IntIn(_) | C::LitInt(_) => &[Int],
        C::Base(Base::Float) | C::LitFloat(_) => &[Float],
        // `class-string`/`literal-string`/`callable-string` are strings at
        // runtime — their non-extensionality (ADR-0038) is about *which*
        // strings, never about being one.
        C::Base(Base::String) | C::StrWith(_) | C::LitStr(_) | C::StrOpaque => &[Str],
        C::Base(Base::Bool) | C::LitBool(_) => &[Bool],
        C::ArrayAny { .. } | C::ListOf { .. } | C::MapOf { .. } | C::Shape { .. } => &[Array],
        C::Class(_) | C::ObjectAny => &[Object],
        // `iterable` is `array|Traversable`; `callable` is a callable-string, a
        // `[obj, 'm']`/`['C', 'm']` pair-array, a Closure or an `__invoke`able.
        C::IterableOf { .. } => &[Array, Object],
        C::CallableTy { .. } => &[Str, Array, Object],
        C::Mixed | C::MixedMinus(_) | C::Opaque | C::Never | C::Union(_) | C::Inter(_) => {
            return None;
        }
    })
}

/// `(kinds the predicate definitely accepts, kinds it definitely rejects)`. A kind
/// in neither set is undecidable for that predicate (`is_callable` on a string, on
/// an array, or on an object; `is_iterable` on an object).
fn pred_kind_sets(pred: TypePred) -> (&'static [RtKind], &'static [RtKind]) {
    use RtKind::{Array, Bool, Float, Int, Null, Object, String as Str};
    match pred {
        TypePred::Str => (&[Str], &[Null, Bool, Int, Float, Array, Object]),
        TypePred::Int => (&[Int], &[Null, Bool, Float, Str, Array, Object]),
        TypePred::Float => (&[Float], &[Null, Bool, Int, Str, Array, Object]),
        TypePred::Bool => (&[Bool], &[Null, Int, Float, Str, Array, Object]),
        TypePred::Array => (&[Array], &[Null, Bool, Int, Float, Str, Object]),
        TypePred::Null => (&[Null], &[Bool, Int, Float, Str, Array, Object]),
        TypePred::Object => (&[Object], &[Null, Bool, Int, Float, Str, Array]),
        // `is_scalar(null)` and `is_scalar([])` are both false — PHP's "scalar"
        // is exactly int|float|string|bool.
        TypePred::Scalar => (&[Bool, Int, Float, Str], &[Null, Array, Object]),
        // `is_iterable` is `is_array($x) || $x instanceof Traversable`; an object
        // arm is therefore undecided without the is-a oracle, and stays `Maybe`.
        TypePred::Iterable => (&[Array], &[Null, Bool, Int, Float, Str]),
        // `is_callable` accepts no *kind* outright (a string may name a function,
        // an array may be a `[obj, 'm']` pair, an object may be `__invoke`able),
        // and rejects the four kinds that can never be callable.
        TypePred::Callable => (&[], &[Null, Bool, Int, Float]),
        // `is_numeric(true)` is FALSE — bools are not numeric. The string kind is
        // decided by the arm's own predicate set, not by its kind, so it appears
        // in neither list here (see `pred_holds_on_arm`).
        TypePred::Numeric => (&[Int, Float], &[Null, Bool, Array, Object]),
    }
}

/// The [`Certainty`] that **every** value `arm` admits satisfies `pred`.
///
/// `Yes` licenses the FALSE branch to delete the arm, `No` licenses the TRUE
/// branch to; `Maybe` keeps it on both (ADR-0052 §2).
fn pred_holds_on_arm(pred: TypePred, arm: &ContractTy) -> Certainty {
    use Certainty::{Maybe, No, Yes};
    // A union answers only where every member agrees; an intersection is a subset
    // of each member, so one deciding member decides it.
    match arm {
        ContractTy::Union(members) if !members.is_empty() => {
            let mut it = members.iter().map(|m| pred_holds_on_arm(pred, m));
            let first = it.next().expect("non-empty checked");
            return if it.all(|c| c == first) { first } else { Maybe };
        }
        ContractTy::Inter(members) => {
            if members.iter().any(|m| pred_holds_on_arm(pred, m).is_yes()) {
                return Yes;
            }
            if members.iter().any(|m| pred_holds_on_arm(pred, m) == No) {
                return No;
            }
            return Maybe;
        }
        // The two arms whose whole meaning IS a predicate's answer.
        ContractTy::CallableTy { .. } if pred == TypePred::Callable => return Yes,
        ContractTy::IterableOf { .. } if pred == TypePred::Iterable => return Yes,
        // `is_numeric` on a string arm is decided by the arm's predicate set, not
        // by its runtime kind: `numeric-string` proves it, a numeric literal
        // proves it, a non-numeric literal refutes it, and a bare `string` (or a
        // non-extensional `class-string`) answers nothing.
        ContractTy::LitStr(s) if pred == TypePred::Numeric => {
            return Certainty::from_bool(php_is_numeric(s));
        }
        ContractTy::StrWith(p) if pred == TypePred::Numeric => {
            return if p.contains_all(StrPreds::NUMERIC) { Yes } else { Maybe };
        }
        _ => {}
    }
    let Some(kinds) = arm_rt_kinds(arm) else { return Maybe };
    let (sat, unsat) = pred_kind_sets(pred);
    if !kinds.is_empty() && kinds.iter().all(|k| sat.contains(k)) {
        return Yes;
    }
    if !kinds.is_empty() && kinds.iter().all(|k| unsat.contains(k)) {
        return No;
    }
    Maybe
}

/// The [`Certainty`] that a concrete value satisfies `pred` — the finite-layer
/// twin of [`pred_holds_on_arm`], and exact for every predicate except the two
/// whose answer depends on data the domain does not carry (`is_callable` on a
/// string that may name a function or on a `[obj, 'm']` pair).
fn pred_holds_on_val(pred: TypePred, v: &Val) -> Certainty {
    use Certainty::{Maybe, No, Yes};
    if pred == TypePred::Numeric {
        return match v {
            Val::Int(_) | Val::Float(_) => Yes,
            Val::Str(s) => Certainty::from_bool(php_is_numeric(s)),
            Val::Bool(_) | Val::Null | Val::Array(_) => No,
        };
    }
    if pred == TypePred::Callable {
        return match v {
            // A literal string may name a function; a literal array may be a
            // `['C', 'm']` pair. Undecidable here, so it filters nothing.
            Val::Str(_) | Val::Array(_) => Maybe,
            Val::Int(_) | Val::Float(_) | Val::Bool(_) | Val::Null => No,
        };
    }
    let kind = match v {
        Val::Null => RtKind::Null,
        Val::Bool(_) => RtKind::Bool,
        Val::Int(_) => RtKind::Int,
        Val::Float(_) => RtKind::Float,
        Val::Str(_) => RtKind::String,
        Val::Array(_) => RtKind::Array,
    };
    let (sat, unsat) = pred_kind_sets(pred);
    if sat.contains(&kind) {
        Yes
    } else if unsat.contains(&kind) {
        No
    } else {
        Maybe
    }
}

/// The [`Certainty`] that **every** value the fact admits satisfies `pred` — the
/// value-lane twin of [`pred_holds_on_arm`]. A `nullable` abstract fact carries the
/// null kind alongside its base, since `is_string(null)` is false.
fn pred_holds_on_fact(pred: TypePred, f: &Fact) -> Certainty {
    use Certainty::{Maybe, Yes};
    if let Some(members) = f.finite_members() {
        return Certainty::all_of(members.iter().map(|v| pred_holds_on_val(pred, v)));
    }
    let (kind, nullable) = match f {
        Fact::Refined { base, nullable, .. } | Fact::General { base, nullable } => {
            let k = match base {
                Base::Int => RtKind::Int,
                Base::Float => RtKind::Float,
                Base::String => RtKind::String,
                Base::Bool => RtKind::Bool,
            };
            (k, *nullable)
        }
        Fact::Shape { nullable, .. } => (RtKind::Array, *nullable),
        // Finite layers are handled above.
        Fact::Singleton(_) | Fact::OneOf(_) => return Maybe,
    };
    // The one refinement that decides a predicate the base alone cannot: a string
    // fact already carrying `NUMERIC` is proven numeric.
    if pred == TypePred::Numeric
        && !nullable
        && let Fact::Refined { base: Base::String, refinement: Refinement::Str(p), .. } = f
        && p.contains_all(StrPreds::NUMERIC)
    {
        return Yes;
    }
    let (sat, unsat) = pred_kind_sets(pred);
    let kinds: &[RtKind] = if nullable { &[kind, RtKind::Null] } else { &[kind] };
    if kinds.iter().all(|k| sat.contains(k)) {
        return Yes;
    }
    if kinds.iter().all(|k| unsat.contains(k)) {
        return Certainty::No;
    }
    Maybe
}

/// The scalar [`Base`] a predicate *proves* on its true branch, for the four
/// predicates that name exactly one. The rest prove a base the four-layer domain
/// cannot spell alone (`is_scalar`/`is_numeric` name a union of bases, `is_array`
/// the array stratum, `is_object`/`is_callable`/`is_iterable` nothing the domain
/// represents at all).
fn pred_base(pred: TypePred) -> Option<Base> {
    match pred {
        TypePred::Str => Some(Base::String),
        TypePred::Int => Some(Base::Int),
        TypePred::Float => Some(Base::Float),
        TypePred::Bool => Some(Base::Bool),
        _ => None,
    }
}

/// The recognized type predicate a guard call names, or `None` for a call that
/// does not denote the global builtin — the SAME [`global_function_callee`] every
/// other recognizer opens with (a `Foo\is_string` or a same-named user function is
/// a different function). Every member of the family takes exactly one by-value
/// argument.
fn type_predicate(cx: &Cx, call: &CallExpr) -> Option<TypePred> {
    let callee = global_function_callee(cx, call)?;
    if !call.positional_only || call.args.len() != 1 {
        return None;
    }
    const PREDS: &[(&str, TypePred)] = &[
        ("is_string", TypePred::Str),
        ("is_int", TypePred::Int),
        ("is_integer", TypePred::Int),
        ("is_long", TypePred::Int),
        ("is_float", TypePred::Float),
        ("is_double", TypePred::Float),
        ("is_bool", TypePred::Bool),
        ("is_array", TypePred::Array),
        ("is_null", TypePred::Null),
        ("is_object", TypePred::Object),
        ("is_scalar", TypePred::Scalar),
        ("is_numeric", TypePred::Numeric),
        ("is_callable", TypePred::Callable),
        ("is_iterable", TypePred::Iterable),
    ];
    PREDS.iter().find(|(n, _)| callee.eq_ignore_ascii_case(n)).map(|(_, p)| *p)
}

/// One type-vocabulary guard, resolved to a variable and a branch polarity.
enum TypeGuard {
    /// `is_string($x)` and kin.
    Pred { var: String, pred: TypePred, positive: bool },
    /// `in_array($x, [<literals>], true)` — the strict-only literal-haystack form.
    InArray { var: String, lits: Vec<Val>, positive: bool },
}

/// The `(needle var, haystack literals)` of a **strict** `in_array` over a literal
/// haystack, or `None`.
///
/// **The non-strict form narrows NOTHING, deliberately.** `in_array($x, ['a'], false)`
/// is PHP's loose `==`, whose equivalence classes are neither reflexive across types
/// nor transitive: `in_array(0, ['a'])` is *true* on PHP 7 (`0 == 'a'`), `in_array('1e2',
/// ['100'])` is true, `in_array(true, ['anything non-empty'])` is true, and the PHP 8
/// string↔int comparison change moved the boundary again. There is no sound OneOf to
/// mint from a loose membership test, so the whole guard is declined rather than
/// approximated. A non-literal haystack (`in_array($x, $allowed, true)`) is declined for
/// the plainer reason that its members are unknown.
fn in_array_literals(
    cx: &Cx,
    call: &CallExpr,
    php_minor: Option<(u16, u16)>,
) -> Option<(String, Vec<Val>)> {
    let callee = global_function_callee(cx, call)?;
    if !call.positional_only || !callee.eq_ignore_ascii_case("in_array") {
        return None;
    }
    // The third argument must be a literal `true`: strict is what makes the
    // membership an *identity*, and identity is what a `OneOf` means.
    if call.args.len() != 3 || !matches!(call.args[2].value, ArgValue::Bool(true)) {
        return None;
    }
    let ArgValue::Var(var) = &call.args[0].value else { return None };
    let ArgValue::Array(_) = &call.args[1].value else { return None };
    let Some(Val::Array(entries)) = val_of(&call.args[1].value, php_minor) else { return None };
    // A nested array member has no scalar identity the value domain can carry.
    if entries.iter().any(|(_, v)| matches!(v, Val::Array(_))) {
        return None;
    }
    let lits: Vec<Val> = entries.into_iter().map(|(_, v)| v).collect();
    if lits.is_empty() {
        return None;
    }
    Some((var.clone(), lits))
}

/// Collect the type-vocabulary guards a condition establishes at polarity `then`.
/// The polarity walk is [`collect_refine`]'s, verbatim in structure: `Not` flips,
/// `And` contributes on the true path, `Or` on the false one (De Morgan) — so
/// `if ($a && is_string($s))` reaches its narrowing point.
fn collect_type_guards(cx: &Cx, cond: &CondExpr, then: bool, out: &mut Vec<TypeGuard>) {
    match cond {
        CondExpr::Call { call, .. } => {
            if let Some(pred) = type_predicate(cx, call) {
                if let ArgValue::Var(var) = &call.args[0].value {
                    out.push(TypeGuard::Pred { var: var.clone(), pred, positive: then });
                }
                return;
            }
            if let Some((var, lits)) = in_array_literals(cx, call, cx.php_minor) {
                out.push(TypeGuard::InArray { var, lits, positive: then });
            }
        }
        CondExpr::Not(c) => collect_type_guards(cx, c, !then, out),
        CondExpr::And(a, b) if then => {
            collect_type_guards(cx, a, then, out);
            collect_type_guards(cx, b, then, out);
        }
        CondExpr::Or(a, b) if !then => {
            collect_type_guards(cx, a, then, out);
            collect_type_guards(cx, b, then, out);
        }
        _ => {}
    }
}

/// **Apply every type-vocabulary guard of `cond` at polarity `then`** to a branch's
/// cloned env and store (ADR-0064 seam (v)). Runs beside [`apply_refinements`] /
/// [`apply_class_narrowing`] / [`apply_shape_narrowing`] in the branch walk, and on
/// the fall-through of `assert($expr)`.
fn apply_type_narrowing(
    cx: &Cx,
    cond: &CondExpr,
    then: bool,
    env: &mut HashMap<String, Known>,
    store: &mut Store,
) {
    let mut guards = Vec::new();
    collect_type_guards(cx, cond, then, &mut guards);
    for g in &guards {
        match g {
            TypeGuard::Pred { var, pred, positive } => {
                subtract_pred_arms(store, var, *pred, *positive);
                // An arm lane that collapsed to a single array arm mints its shape
                // fact through the SAME gated helper `is_array`'s S4 siblings use —
                // never a second minting path.
                mint_collapsed_shape(var, env, store);
                refine_fact_for_pred(env, var, *pred, *positive);
                // A value the guard proved is not an object cannot still carry a
                // heap binding or an is-a bound; the declared-arm lane (just
                // narrowed) is deliberately kept.
                if *positive && !pred_kind_sets(*pred).0.contains(&RtKind::Object) {
                    store.refs.remove(var);
                    store.members.remove(var);
                }
            }
            TypeGuard::InArray { var, lits, positive } => {
                refine_fact_for_in_array(env, var, lits, *positive);
            }
        }
    }
}

/// Arm-lane subtraction for one type predicate: the TRUE branch deletes the arms
/// the predicate **refutes**, the FALSE branch the arms it **proves**. `Maybe`
/// keeps the arm on both. An emptied lane drops to no-fact, never a death signal
/// (ADR-0052 §2).
fn subtract_pred_arms(store: &mut Store, var: &str, pred: TypePred, positive: bool) {
    let Some(arms) = store.contract.get_mut(var) else { return };
    arms.retain(|a| {
        let holds = pred_holds_on_arm(pred, &a.ty);
        if positive { holds != Certainty::No } else { !holds.is_yes() }
    });
    if arms.is_empty() {
        store.contract.remove(var);
    }
}

/// Value-fact narrowing for one type predicate.
///
/// **`None` means "leave the fact exactly as it was", and that is also the answer
/// when the guard's polarity refutes the whole fact** — a binding proven `int` under
/// an `is_string` true-branch says the branch is unreachable, and this helper does not
/// own death (ADR-0052 §2: the verdict does). Rewriting the fact there would mint a
/// claim about a path the runtime never takes; leaving the fact alone is the
/// FP-safe answer on exactly that path.
fn refine_fact_for_pred(
    env: &mut HashMap<String, Known>,
    var: &str,
    pred: TypePred,
    positive: bool,
) {
    // The one predicate that narrows a binding carrying NO fact: `is_string`/
    // `is_int`/`is_float`/`is_bool` prove a single base, and `is_null` proves a
    // single value, so the true branch can state it outright (a `mixed`/undeclared
    // binding is the common real-world guard subject). Every other predicate names
    // a union of bases (`is_scalar`, `is_numeric`), the array stratum (`is_array` —
    // served by `mint_collapsed_shape` from the arm lane instead, so the Asserted
    // shape lane keeps its A-G9 stratum discipline), or something the four-layer
    // domain does not represent (`is_object`/`is_callable`/`is_iterable`).
    if env.get(var).is_none_or(|k| k.fact.is_none()) {
        if !positive {
            return;
        }
        let minted = match pred {
            TypePred::Null => Some(Fact::Singleton(Val::Null)),
            _ => pred_base(pred).map(|base| Fact::General { base, nullable: false }),
        };
        if let Some(fact) = minted {
            // A closure-only binding carries no scalar fact by construction
            // (ADR-0033); minting one over it would forget the closure target.
            if env.get(var).is_some_and(|k| k.closure.is_some()) {
                return;
            }
            let line = env.get(var).map_or(0, |k| k.line);
            env.insert(
                var.to_owned(),
                Known::value_strat(fact, line, Some("proven on this branch".to_owned()), Stratum::Verified),
            );
        }
        return;
    }
    refine_fact(env, var, Stratum::Verified, |f| {
        // **The guard's polarity refutes the binding's own fact ⇒ DROP it.** The
        // branch is unreachable (`is_string($n)` with `$n` proven `1`), and this
        // slice does not own death — the verdict does (ADR-0052 §2). Carrying the
        // refuted fact into the branch is worse than either alternative: it would
        // premise proof-layer findings about a path the runtime never takes (the
        // measured FP class — `new Identifier($name)` inside `if (is_string($name))`
        // under a call-site descent that bound `$name` to an int). Dropping to
        // no-fact is the FP-safe fallback: the guard's base is forgotten wholesale
        // here.
        let holds = pred_holds_on_fact(pred, f);
        if (positive && holds == Certainty::No) || (!positive && holds.is_yes()) {
            return None;
        }
        // The finite layers narrow by **exact member retention** on both
        // polarities — the only lossless subtraction the domain has (ADR-0052 §2).
        // The retention can no longer empty the set: the refutation test above
        // already caught the all-members-refuted case.
        if let Some(members) = f.finite_members() {
            let kept: Vec<Val> = members
                .iter()
                .filter(|v| {
                    let h = pred_holds_on_val(pred, v);
                    if positive { h != Certainty::No } else { !h.is_yes() }
                })
                .cloned()
                .collect();
            return Fact::from_vals(kept);
        }
        if !positive {
            // The abstract layers carry no negative-predicate vocabulary (ADR-0052
            // §2: "General has no point-complement representation, and gets none").
            // The one exception is the nullable bit, which IS the complement of
            // `is_null` — the same channel `!== null` already uses.
            return if pred == TypePred::Null { clear_null(f) } else { Some(f.clone()) };
        }
        Some(match (pred, f) {
            // `is_null($x)` true: the value IS null, whatever the fact said.
            (TypePred::Null, _) => Fact::Singleton(Val::Null),
            // A base-naming predicate on a matching base keeps every refinement it
            // had and drops nullability (`is_string(null)` is false).
            (_, Fact::Refined { base, refinement, .. }) if pred_base(pred) == Some(*base) => {
                Fact::refined(*base, *refinement, false)
            }
            (_, Fact::General { base, .. }) if pred_base(pred) == Some(*base) => {
                Fact::General { base: *base, nullable: false }
            }
            // `is_numeric` is the first guard to WIRE the already-modeled
            // `StrPreds::NUMERIC` (ADR-0064 §1 names it): on a string-based fact the
            // true branch intersects the numeric-string class in. On an int/float
            // fact it only drops nullability (every int and float is numeric).
            (
                TypePred::Numeric,
                Fact::Refined { base: Base::String, .. } | Fact::General { base: Base::String, .. },
            ) => add_str_preds(&clear_null(f)?, StrPreds::NUMERIC),
            (
                TypePred::Numeric,
                Fact::Refined { base: Base::Int | Base::Float, .. }
                | Fact::General { base: Base::Int | Base::Float, .. },
            ) => clear_null(f)?,
            // `is_scalar` names int|float|string|bool: on any scalar-based fact it
            // proves only non-nullness, which is exactly what it drops.
            (TypePred::Scalar, Fact::Refined { .. } | Fact::General { .. }) => clear_null(f)?,
            // `is_array` on an array-stratum fact proves non-nullness too.
            (TypePred::Array, Fact::Shape { .. }) => clear_null(f)?,
            // Everything else: either the predicate refutes this fact (an
            // unreachable branch — see the doc comment) or it says nothing the
            // domain can hold.
            (_, other) => other.clone(),
        })
    });
}

/// Value-fact narrowing for the strict literal-haystack `in_array` form.
///
/// TRUE branch: the needle is **identical** to one of the haystack literals, so the
/// fact becomes the `OneOf` of those literals intersected with what was already
/// known (`Fact::from_vals` re-canonicalizes — one survivor collapses to a
/// `Singleton`, an over-`CAP` set widens through the computed summary).
/// FALSE branch: subtraction is exact only on a **finite** fact (`OneOf` minus the
/// literals, through `exclude_member`); an abstract fact has no
/// point-complement, so it is left alone.
/// Either polarity emptying the set means the branch is unreachable — the fact is
/// left untouched, since the verdict owns death (ADR-0052 §2).
fn refine_fact_for_in_array(
    env: &mut HashMap<String, Known>,
    var: &str,
    lits: &[Val],
    positive: bool,
) {
    if env.get(var).is_none_or(|k| k.fact.is_none()) {
        if !positive || env.get(var).is_some_and(|k| k.closure.is_some()) {
            return;
        }
        let Some(fact) = Fact::from_vals(lits.to_vec()) else { return };
        let line = env.get(var).map_or(0, |k| k.line);
        env.insert(
            var.to_owned(),
            Known::value_strat(fact, line, Some("proven on this branch".to_owned()), Stratum::Verified),
        );
        return;
    }
    refine_fact(env, var, Stratum::Verified, |f| {
        if positive {
            // No admitted literal ⇒ the membership test cannot hold ⇒ the branch is
            // unreachable, and the fact drops rather than being carried into it (the
            // same rule `refine_fact_for_pred` states at length).
            let kept: Vec<Val> = lits.iter().filter(|v| f.admits(v)).cloned().collect();
            return Fact::from_vals(kept);
        }
        if f.finite_members().is_none() {
            return Some(f.clone());
        }
        let mut cur = f.clone();
        for v in lits {
            match exclude_member(&cur, v) {
                Some(next) => cur = next,
                // Emptied: every member was in the haystack, so the false branch is
                // unreachable — drop, do not carry.
                None => return None,
            }
        }
        Some(cur)
    });
}

/// The `($var, literal)` of a comparison whose two operands are exactly one bare
/// variable and one literal (in either order).
fn var_literal(lhs: &CondOperand, rhs: &CondOperand) -> Option<(String, ArgValue)> {
    match (lhs, rhs) {
        (CondOperand::Var(v), CondOperand::Literal(val))
        | (CondOperand::Literal(val), CondOperand::Var(v)) => Some((v.clone(), val.clone())),
        _ => None,
    }
}

/// The `($var, int_literal, var_on_left)` of a comparison with one bare variable
/// and one **int** literal (ordering refinement only applies to int bounds).
fn var_int_literal(lhs: &CondOperand, rhs: &CondOperand) -> Option<(String, i64, bool)> {
    match (lhs, rhs) {
        (CondOperand::Var(v), CondOperand::Literal(ArgValue::Int(i))) => Some((v.clone(), *i, true)),
        (CondOperand::Literal(ArgValue::Int(i)), CondOperand::Var(v)) => Some((v.clone(), *i, false)),
        _ => None,
    }
}

/// Mirror an ordering operator (used when the variable is the right operand).
fn flip_ordering(op: CmpOp) -> CmpOp {
    match op {
        CmpOp::Lt => CmpOp::Gt,
        CmpOp::Le => CmpOp::Ge,
        CmpOp::Gt => CmpOp::Lt,
        CmpOp::Ge => CmpOp::Le,
        other => other,
    }
}

/// The logical negation of an ordering operator (for the false-path).
fn negate_ordering(op: CmpOp) -> CmpOp {
    match op {
        CmpOp::Lt => CmpOp::Ge,
        CmpOp::Le => CmpOp::Gt,
        CmpOp::Gt => CmpOp::Le,
        CmpOp::Ge => CmpOp::Lt,
        other => other,
    }
}

/// The int interval `var <op> k` denotes (`> 0` → positive, `>= 0` → non-negative,
/// `<`/`<=` symmetric). `None` when the interval is empty (a saturating bound
/// overflow) — the caller adds no refinement.
fn ordering_range(op: CmpOp, k: i64) -> Option<IntRange> {
    match op {
        CmpOp::Gt => IntRange::new(k.checked_add(1)?, i64::MAX),
        CmpOp::Ge => IntRange::new(k, i64::MAX),
        CmpOp::Lt => IntRange::new(i64::MIN, k.checked_sub(1)?),
        CmpOp::Le => IntRange::new(i64::MIN, k),
        _ => None,
    }
}

/// Apply a branch's refinements to its cloned env (clearing any stale exact-class
/// fact for a positively-narrowed variable), at trust stratum `stratum` (ADR-0052
/// §5): `Verified` for native-condition branches (the runtime test executed) and for
/// `assert($expr)` (the owner ruling reads it as a throw-guard), `Asserted` for
/// `@phpstan-assert`-tag-derived narrowings (a docblock claim).
fn apply_refinements(
    refs: &[Refine],
    env: &mut HashMap<String, Known>,
    store: &mut Store,
    stratum: Stratum,
) {
    for r in refs {
        match r {
            // `=== v` replaces the value with proven equality: the fact is exactly
            // as trustworthy as the test that established it (`stratum`), regardless
            // of any prior (weaker) knowledge about the variable.
            Refine::Exact(var, val) => {
                env.insert(
                    var.clone(),
                    Known::value_strat(
                        Fact::Singleton(val.clone()),
                        0,
                        Some("proven on this branch".to_owned()),
                        stratum,
                    ),
                );
                store.unbind(var);
            }
            Refine::NotNull(var) => refine_fact(env, var, stratum, clear_null),
            Refine::Exclude(var, val) => {
                refine_fact(env, var, stratum, |f| exclude_member(f, val));
            }
            Refine::IntRange(var, range) => {
                refine_fact(env, var, stratum, |f| intersect_int(f, *range));
            }
            Refine::Truthy(var) => refine_fact(env, var, stratum, truthy_narrow),
        }
    }
}

/// Transform the fact of `var` in place with `f` (a `None` result drops the fact —
/// the conservative empty-fact fallback); a no-op when `var` has no fact. The
/// result stratum is `min(existing, refine_stratum)`: a narrowing (`!== null`,
/// interval, truthy, member exclusion) constrains the *existing* fact, so it is
/// only as trustworthy as its weakest component (ADR-0052 §5 derivation clause).
fn refine_fact(
    env: &mut HashMap<String, Known>,
    var: &str,
    refine_stratum: Stratum,
    f: impl FnOnce(&Fact) -> Option<Fact>,
) {
    let Some(k) = env.get(var) else { return };
    // A closure-only binding carries no scalar fact — value refinements do not
    // apply to it; leave it intact.
    let Some(kf) = &k.fact else { return };
    match f(kf) {
        Some(nf) => {
            let (line, bound, stratum) = (k.line, k.bound.clone(), k.stratum.min(refine_stratum));
            env.insert(var.to_owned(), Known::value_strat(nf, line, bound, stratum));
        }
        None => {
            env.remove(var);
        }
    }
}

/// Clear nullability: an abstract fact loses its `nullable` flag; a finite fact
/// loses its `null` member. `None` only if that empties a finite fact.
fn clear_null(f: &Fact) -> Option<Fact> {
    match f {
        Fact::Refined { base, refinement, nullable: true } => {
            Some(Fact::refined(*base, *refinement, false))
        }
        Fact::General { base, nullable: true } => Some(Fact::General { base: *base, nullable: false }),
        Fact::Singleton(_) | Fact::OneOf(_) => exclude_member(f, &Val::Null),
        // Already non-nullable abstract fact — unchanged.
        other => Some(other.clone()),
    }
}

/// Remove `val` from a finite fact; for a String-based abstract fact excluding
/// `""`, add `NON_EMPTY` (the `!== ''` refinement). Otherwise unchanged.
fn exclude_member(f: &Fact, val: &Val) -> Option<Fact> {
    match f.finite_members() {
        Some(members) => {
            let kept: Vec<Val> = members.iter().filter(|m| *m != val).cloned().collect();
            // Empty → drop the fact (conservative fallback; a truly-dead branch is
            // already pruned by the decided-guard verdict).
            Fact::from_vals(kept)
        }
        None => match (f, val) {
            (Fact::Refined { base: Base::String, .. } | Fact::General { base: Base::String, .. }, Val::Str(s))
                if s.is_empty() =>
            {
                Some(add_str_preds(f, StrPreds::NON_EMPTY))
            }
            _ => Some(f.clone()),
        },
    }
}

/// Intersect an Int-based abstract fact with `range`; a finite/other fact is left
/// unchanged. `None` when the intersection is empty.
fn intersect_int(f: &Fact, range: IntRange) -> Option<Fact> {
    match f {
        Fact::Refined { base: Base::Int, refinement: Refinement::Int(have), nullable } => {
            let r = have.intersect(range)?;
            Some(Fact::refined(Base::Int, Refinement::Int(r), *nullable))
        }
        Fact::General { base: Base::Int, nullable } => {
            Some(Fact::refined(Base::Int, Refinement::Int(range), *nullable))
        }
        other => Some(other.clone()),
    }
}

/// Truthiness narrowing on the true-path: clear nullability (null is falsy) and,
/// for a String-based fact, add `NON_FALSY`. Int-based facts gain nothing usable
/// (nonzero is not an interval — skipped, documented). Never empties.
fn truthy_narrow(f: &Fact) -> Option<Fact> {
    let f = clear_null(f)?;
    Some(match &f {
        Fact::Refined { base: Base::String, .. } | Fact::General { base: Base::String, .. } => {
            add_str_preds(&f, StrPreds::NON_FALSY)
        }
        other => other.clone(),
    })
}

/// Add string predicates to a String-based abstract fact (union-closed); a
/// non-string or finite fact is returned unchanged.
///
/// **Both arms close under implication.** [`StrPreds`] documents itself as
/// "canonically closed", and the `Refined` arm gets that for free from
/// [`StrPreds::union`] — the `General` arm, which starts from no predicates, has
/// to ask for it. Storing a raw `NON_FALSY` bit produces a fact that renders as
/// `non-falsy-string` but answers `false` to "is it non-empty?", which is the
/// closure existing to prevent: a consumer testing the weaker predicate (DR3's
/// `explode` separator gate is the first) would silently miss the stronger one.
fn add_str_preds(f: &Fact, preds: StrPreds) -> Fact {
    match f {
        Fact::Refined { base: Base::String, refinement: Refinement::Str(have), nullable } => {
            Fact::refined(Base::String, Refinement::Str(have.union(preds)), *nullable)
        }
        Fact::General { base: Base::String, nullable } => {
            Fact::refined(Base::String, Refinement::Str(preds.close()), *nullable)
        }
        other => other.clone(),
    }
}

// ---------------------------------------------------------------------------
// `@phpstan-assert` application (ADR-0030, Feature D). After a call to an
// assertion helper, the asserted type narrows the CALLER's env for the variable
// passed at the asserted position. `Always` asserts apply on the fall-through
// (statement position); `-if-true`/`-if-false` apply only in guard position.
// ---------------------------------------------------------------------------

/// Convert a lowered contract type to the domain [`Fact`] an assertion of it
/// establishes (conservative): `Base` → General, `IntIn` → Refined, `StrWith` →
/// Refined, `Null` → `Singleton(null)`, a nullable union (`X|null`) → `X`'s fact
/// with `nullable = true`; anything else → `None` (no application).
fn assert_fact_of(cty: &steins_contract::ContractTy) -> Option<Fact> {
    use steins_contract::ContractTy as C;
    match cty {
        C::Base(b) => Some(Fact::General { base: *b, nullable: false }),
        C::IntIn(r) => Some(Fact::refined(Base::Int, Refinement::Int(*r), false)),
        C::StrWith(p) => Some(Fact::refined(Base::String, Refinement::Str(*p), false)),
        C::Null => Some(Fact::Singleton(Val::Null)),
        // Literal claims (`@phpstan-assert 'hi' $v`, `42`, `true`) are Singleton
        // facts — the same denotation `steins_contract::fact_of` uses. Needed for
        // Asserted capture/fold summaries (issues #127 / #128) without laundering.
        C::LitInt(i) => Some(Fact::Singleton(Val::Int(*i))),
        C::LitFloat(f) => Some(Fact::Singleton(Val::Float(*f))),
        C::LitStr(s) => Some(Fact::Singleton(Val::Str(s.clone()))),
        C::LitBool(b) => Some(Fact::Singleton(Val::Bool(*b))),
        C::Union(members) => {
            let has_null = members.iter().any(|m| matches!(m, C::Null));
            let non_null: Vec<&C> = members.iter().filter(|m| !matches!(m, C::Null)).collect();
            // `X|null` (exactly one representable non-null member) → X, nullable.
            if has_null && non_null.len() == 1 {
                return Some(with_nullable(assert_fact_of(non_null[0])?));
            }
            None
        }
        _ => None,
    }
}

/// Set the `nullable` flag on an abstract fact (a `Singleton`/`OneOf` is left
/// unchanged — a nullable-union member never lowers to a finite fact here).
fn with_nullable(f: Fact) -> Fact {
    match f {
        Fact::General { base, .. } => Fact::General { base, nullable: true },
        Fact::Refined { base, refinement, .. } => Fact::refined(base, refinement, true),
        other => other,
    }
}

/// Apply the `Always` assertions of every statically-resolved call in a statement
/// to the caller's env (Feature D) — the fall-through position. `-if-true`/
/// `-if-false` asserts are conditional on the boolean result and belong to guard
/// position (see [`apply_guard_asserts`]).
#[allow(clippy::too_many_arguments)]
fn apply_stmt_asserts(
    cx: &Cx,
    scope: &Scope,
    call: &CallExpr,
    env: &mut HashMap<String, Known>,
    store: &mut Store,
    this_exact: Option<&str>,
    enclosing_class: Option<&str>,
    asserted: &mut HashSet<String>,
) {
    apply_call_asserts(cx, scope, call, env, store, this_exact, enclosing_class, AssertKind::Always, asserted);
}

/// The source line of a guard call — the provenance line an out-parameter seed
/// binds at, which is where the callee performed the write.
fn guard_call_line(w: &WalkCx, call: &CallExpr) -> u32 {
    w.cx.tree().position(call.span.start).line
}

/// Seed the out-parameters of every call this branch proves returned truthy
/// (ADR-0077), in source order.
///
/// A truthy result is the callee's own witness that it performed its by-ref
/// write, and the ONLY branch where the written fact is sound — `preg_match` on
/// an uncompilable pattern returns `false` and writes nothing at all. Runs after
/// the invalidation of `walk_if` step 2 and rebinds what it forgot (§3.4), and
/// after the branch's assert narrowings, so an explicit `@phpstan-assert`
/// envelope is not silently overwritten by a seed at a further call in the same
/// condition.
fn seed_out_params(
    w: &WalkCx,
    folder: &mut dyn Folder,
    cond: &CondExpr,
    then: bool,
    env: &mut HashMap<String, Known>,
    store: &mut Store,
) {
    let mut calls = Vec::new();
    collect_truthy_calls(cond, then, w.cx.php_minor, &mut calls);
    for call in calls {
        for (var, fact) in out_param_seed(w, folder, call, env) {
            seed_out_param(&var, fact, guard_call_line(w, call), env, store);
        }
    }
}

/// The [`Known::bound`] provenance an out-parameter seed stamps (ADR-0077), read
/// as the clause it becomes: "from `$m`, written by the guard call on this
/// branch". Both halves of the claim are in it — the fact is the callee's, and it
/// holds *here* because the branch proved the write happened.
const OUT_PARAM_SEEDED: &str = "written by the guard call on this branch";

/// **The out-parameter seed** (ADR-0077): the by-ref arguments a guard call
/// proved it wrote, paired with the fact its contract determines for each.
///
/// Called only from the branch where the call's result is proven truthy, and
/// that is the whole ADR. `preg_match` returns `1` and assigns the success shape,
/// returns `0` and assigns `[]` — and on a pattern PCRE refuses to compile it
/// returns `false` and assigns **nothing at all**, leaving the caller's variable
/// holding whatever it held (measured, PHP 8.5.9). The third outcome is not a
/// value a fact could widen to include; it is the absence of an assignment. So
/// truthiness is not merely where the sharper fact is, it is the only place any
/// fact is sound at all — and a seed at the call statement would manufacture one
/// on a reachable path.
///
/// Every leg refuses **silently**, and a refusal is exactly today's behavior: the
/// name stays forgotten, no diagnostic is produced, and nothing distinguishes a
/// pattern this engine cannot read from one it never looked at.
fn out_param_seed(
    w: &WalkCx,
    folder: &mut dyn Folder,
    call: &CallExpr,
    env: &HashMap<String, Known>,
) -> Vec<(String, Fact)> {
    // A poisoned scope (ADR-0046) has already lost the right to say which name a
    // binding is — `extract()` and variable-variables can rewrite the frame the
    // seed would land in. The same gate `apply_call_asserts` applies.
    if w.scope.poisoned {
        return Vec::new();
    }
    let Some(name) = out_param_seed_callee(w.cx, call) else { return Vec::new() };
    let Some(positions) = steins_catalog::out_params(name) else { return Vec::new() };
    let mut seeds = Vec::new();
    for &position in positions {
        // The witness leg (§3.2): only a *stated* written-when seeds, and the only
        // condition the catalog can state is the one the caller just proved.
        // Nothing is inferred from the mere existence of an `out_params` row.
        let Some(steins_catalog::WrittenWhen::ReturnTruthy) =
            steins_catalog::out_param_written_when(name, position)
        else {
            continue;
        };
        // The arity leg: an argument the call never supplied was never written.
        let Some(arg) = call.args.get(position) else { continue };
        // The aliasing leg (§3.6): only a plain local variable. `$this->m`,
        // `$arr['k']` and a variable-variable all refuse, because the write may be
        // visible to callers this scope cannot see (ADR-0063 §2.3) and because
        // nothing here could name the target if it were.
        let ArgValue::Var(var) = &arg.value else { continue };
        let Some(fact) = out_param_written_fact(w, folder, name, position, call, env) else {
            continue;
        };
        seeds.push((var.clone(), fact));
    }
    seeds
}

/// The builtin an out-parameter seed may consult: the name must denote the
/// **global** function ([`global_function_callee`] — a namespaced spelling or a
/// user function of the same name is a *different function*), and a call whose
/// positional mapping a named or spread argument defeated cannot say which
/// argument is which.
fn out_param_seed_callee<'a>(cx: &Cx, call: &'a CallExpr) -> Option<&'a str> {
    let callee = global_function_callee(cx, call)?;
    call.positional_only.then_some(callee)
}

/// The fact the callee's contract determines for the out-parameter at
/// `position`, computed from **proven arguments only** (ADR-0077 §3.3).
///
/// One row exists, and the dispatch is by (name, position) because that is what
/// the witness is keyed by: a second row would be a second arm, not a widening of
/// this one.
fn out_param_written_fact(
    w: &WalkCx,
    folder: &mut dyn Folder,
    name: &str,
    position: usize,
    call: &CallExpr,
    env: &HashMap<String, Known>,
) -> Option<Fact> {
    match (name.to_ascii_lowercase().as_str(), position) {
        ("preg_match", 2) => preg_match_written_fact(w, folder, call, env),
        _ => None,
    }
}

/// What `preg_match` wrote into `$matches`, for a call whose every premise is
/// proven — else `None`.
///
/// Three refusals live here, and each is a premise the fact would otherwise rest
/// on without holding it:
///
/// * **the pattern** must resolve to a proven `Singleton` string (ADR-0037): a
///   computed or widened pattern says nothing about the group structure;
/// * **the group reader declines** (#149) for every pattern whose numbering it
///   cannot establish, which is also what keeps this out of the business of
///   deciding whether PCRE would compile the pattern at all;
/// * **the flags argument**, when supplied, must be a proven `0`.
///   `PREG_OFFSET_CAPTURE` turns every entry into a `[string, int]` pair and
///   `PREG_UNMATCHED_AS_NULL` makes the trailing absence an explicit `null`
///   instead (both measured) — neither is modelled here, so both refuse
///   (ADR-0077 §4).
///
/// The `$offset` argument (position 4) is deliberately *not* consulted: it moves
/// where matching starts, and measurement confirms it leaves the written key set
/// alone.
fn preg_match_written_fact(
    w: &WalkCx,
    folder: &mut dyn Folder,
    call: &CallExpr,
    env: &HashMap<String, Known>,
) -> Option<Fact> {
    let poisoned = w.scope.poisoned;
    if let Some(flags) = call.args.get(3) {
        let resolved = w.cx.resolve_literal(&flags.value, env, poisoned, folder)?;
        if !matches!(resolved, ArgValue::Int(0)) {
            return None;
        }
    }
    let pattern = w.cx.resolve_literal(&call.args.first()?.value, env, poisoned, folder)?;
    let ArgValue::Str(pattern) = pattern else { return None };
    let groups = steins_catalog::preg::capture_groups(&pattern)?;
    preg_success_shape(&groups)
}

/// The element type of one `$matches` entry, read off the sub-pattern that
/// produced it (issue #156).
///
/// Three rules, each a property of the sub-pattern's whole language and each
/// answering plain `string` — today's behavior — for anything it cannot
/// establish:
///
/// * a floor of one character rules out `''`, so the entry is
///   `non-empty-string`;
/// * a floor of **two** rules out `'0'` as well, and those are exactly the
///   falsy strings, so the entry is `non-falsy-string`;
/// * a sub-pattern that can produce nothing but ASCII digits, and must produce
///   at least one, is `numeric-string` — measured, PHP calls every non-empty
///   ASCII digit run numeric, leading zeros and four hundred digits included.
///
/// The floors are counted in **characters**, which is what keeps the second
/// rule honest for a multi-byte literal: `(£|€)` has a one-character floor and
/// a two-*byte* one, and PHPStan agrees it is only `non-empty-string`.
///
/// Deliberately not implemented: the issue also offers "a mandatory literal
/// character other than `'0'`" as a second route to `non-falsy-string`. It is
/// sound — a string containing `'x'` is neither `''` nor `'0'` — but it claims
/// more than PHPStan does for the same pattern (`/(a|b)|(?:c)/` is
/// `non-empty-string` there), so it would trade agreement for sharpness on
/// rows that are otherwise exact. A decline costs nothing and is easy to add
/// later.
fn preg_element_fact(text: &steins_catalog::preg::MatchedText) -> Fact {
    let mut preds = StrPreds::empty();
    if text.min_chars >= 1 {
        preds = preds.union(StrPreds::NON_EMPTY);
        if text.digits_only {
            preds = preds.union(StrPreds::NUMERIC);
        }
    }
    if text.min_chars >= 2 {
        preds = preds.union(StrPreds::NON_FALSY);
    }
    Fact::refined(Base::String, Refinement::Str(preds), false)
}

/// The success shape of `$matches`: key `0` plus one key per capture group in
/// numeric order, each value a string refined from the sub-pattern that fills
/// it, named groups additionally under their string key, sealed.
///
/// Every claim below was produced by running PHP 8.5.9, and three are
/// counter-intuitive enough to be worth the ink:
///
/// * a **trailing** unmatched group is dropped from the array outright
///   (`preg_match('/(a)(b)?/', 'a', $m)` gives keys `[0, 1]`), so the slice-A
///   reader's `can_be_trailing_absent` becomes an **optional** key;
/// * an **interior** unmatched group is present as `''`
///   (`preg_match('/(a)(b)?(c)/', 'ac', $m)` gives `[0, 1, 2 => '', 3]`), so it
///   stays a **required** key — absence is a trailing-only phenomenon and the
///   reader has already applied that rule;
/// * a named group occupies its string key **and** a numeric one, both present
///   exactly when the group's entry is, which is why one presence serves both.
///
/// **The element type is coupled to that same absence rule, and the coupling is
/// the whole hazard.** PHPStan's expectation for `/(a)(b)*(c)(d)*/` is
/// `array{0: non-falsy-string, 1: 'a', 2: string, 3: 'c', 4?: non-empty-string}`
/// — the middle `(b)*` and the trailing `(d)*` are the same sub-pattern and get
/// **different** element types. A group that can be *present* while unmatched
/// holds `''` on that path, so no refinement of its body may be stated however
/// its floor reads; only a group whose unmatched case is *absence* keeps the
/// claim. The reader answers which is which
/// ([`can_be_present_empty`](steins_catalog::preg::CaptureGroup::can_be_present_empty)),
/// and getting it backwards would put a false fact on a reachable path.
///
/// **List-ness.** The keys PHP writes are `0..n` in ascending order and the
/// trailing drop removes a *suffix* of them, so every realizable key set is a
/// prefix and `array_is_list($m)` measured `true` for every group-only pattern
/// probed — including `/(a)(b)?(c)?/` matching only `a`. The shape alone cannot
/// see this (`array{0: string, 1?: string, 2?: string}` also admits a
/// hole-bearing `{0, 2}` that PCRE never produces), so the flag is asserted where
/// the shape would only guess. A named group ends it: its string key makes
/// `array_is_list` false whenever the group participates, and it may still not
/// participate (`/(a)(?<b>x)?/` on `'a'` measured a list, on `'ax'` measured not
/// one) — so a pattern with any name asserts nothing and lets the denotational
/// computation answer, which is `No` for a name that always participates and
/// `Maybe` for one that may not.
fn preg_success_shape(groups: &steins_catalog::preg::CaptureGroups) -> Option<Fact> {
    use steins_domain::{Presence, SHAPE_WIDTH_LIMIT, Tail};

    // Presence is `witnessed: false` throughout (ADR-0062 §3): this is a declared
    // contract read off the callee, not a guard that observed the array.
    let required = Presence::Required { witnessed: false };
    let slot = |fact: Fact| Some(Box::new(fact));

    let mut fields = vec![(VKey::Int(0), required, slot(preg_element_fact(&groups.whole)))];
    for (i, g) in groups.groups.iter().enumerate() {
        let presence = if g.can_be_trailing_absent { Presence::Optional } else { required };
        // A group that may be present as `''` admits the empty string on a
        // reachable path, so its body's floor says nothing about its entry.
        let element = if g.can_be_present_empty {
            Fact::General { base: Base::String, nullable: false }
        } else {
            preg_element_fact(&g.body)
        };
        let index = i64::try_from(i + 1).ok()?;
        fields.push((VKey::Int(index), presence, slot(element.clone())));
        if let Some(name) = &g.name {
            fields.push((VKey::Str(name.clone()), presence, slot(element)));
        }
    }
    // A pattern with more groups than a shape may carry has no faithful shape, and
    // a truncated one would claim a seal it cannot honor.
    if fields.len() > SHAPE_WIDTH_LIMIT {
        return None;
    }
    let list = groups.groups.iter().all(|g| g.name.is_none());
    let shape = ShapeFact::normalize(
        fields,
        // Sealed: a match writes these keys and no others. The verb family that
        // would add one (`(*MARK:x)`) is a decline in the reader, not a key here.
        Tail::Sealed,
        if list { Certainty::Yes } else { Certainty::Maybe },
        true,
        Vec::new(),
    );
    Some(Fact::Shape { shape: Box::new(shape), nullable: false })
}

/// Bind an out-parameter seed on a branch env (ADR-0077 §3.4).
///
/// **The order is fixed, and the seed is second.** [`walk_if`] has already run
/// [`cond_invalidations`] over the pre-branch env, so the name reaches this
/// function forgotten and this rebinds it; the two never race, and no reader has
/// to work out which won. The binding is `Asserted` (§3.3): it rests on a
/// declared contract plus proven inputs, never on observing a run, so it may
/// silence but never premise a proof.
fn seed_out_param(
    var: &str,
    fact: Fact,
    line: u32,
    env: &mut HashMap<String, Known>,
    store: &mut Store,
) {
    env.insert(
        var.to_owned(),
        Known::value_strat(fact, line, Some(OUT_PARAM_SEEDED.to_owned()), Stratum::Asserted),
    );
    // The callee assigned the whole variable, so the guard-derived class facts and
    // the declared-arm lane the old value earned are void — the same reasoning any
    // rebinding applies.
    store.unbind(var);
}

/// Apply a guard-position call's `@phpstan-assert-if-true`/`-if-false` specs to a
/// branch env (ADR-0052 §5, at the `Asserted` stratum). `kind` selects the
/// polarity: `IfTrue` on the true branch, `IfFalse` on the false branch. This is
/// the *minimal* guard-call tag consumption — the full retained-guard-call
/// machinery (§6) is N3.
fn apply_guard_asserts(
    w: &WalkCx,
    call: &CallExpr,
    kind: AssertKind,
    env: &mut HashMap<String, Known>,
    store: &mut Store,
) {
    let mut asserted = HashSet::new();
    apply_call_asserts(
        w.cx, w.scope, call, env, store, w.this_exact, w.enclosing_class, kind, &mut asserted,
    );
}

/// Resolve a call's callee declaration and apply every assertion spec of a given
/// `kind`, mapping each spec's `@param` name to the call's positional argument
/// variable and narrowing it via [`apply_assert_to_var`] (always at the `Asserted`
/// stratum). Shared by the fall-through (`Always`) and guard (`IfTrue`/`IfFalse`)
/// consumption points.
#[allow(clippy::too_many_arguments)]
fn apply_call_asserts(
    cx: &Cx,
    scope: &Scope,
    call: &CallExpr,
    env: &mut HashMap<String, Known>,
    store: &mut Store,
    this_exact: Option<&str>,
    enclosing_class: Option<&str>,
    kind: AssertKind,
    asserted: &mut HashSet<String>,
) {
    if scope.poisoned || !call.positional_only {
        return;
    }
    let (params, docblock): (&[Param], Option<&str>) = match &call.receiver {
        Callee::Function(_) => {
            let Some(site) = cx.resolve_user_fn(call) else { return };
            let decl = cx.fn_decl(site);
            (&decl.params, decl.docblock.as_deref())
        }
        Callee::Method { .. } | Callee::Static { .. } | Callee::Construct { .. } => {
            let Some(target) = resolve_call_target(
                cx, &call.receiver, store, this_exact, enclosing_class, scope.poisoned,
            ) else {
                return;
            };
            (&target.method.params, target.method.docblock.as_deref())
        }
        // A `$fn(...)` variable call carries no static declaration to read
        // `@phpstan-assert` envelopes from — nothing to apply.
        Callee::DynamicVar(_) | Callee::Dynamic => return,
    };
    let Some(envelopes) = parse_envelopes(docblock) else { return };
    for spec in &envelopes.asserts {
        if spec.kind != kind {
            continue;
        }
        let Some(pos) = params.iter().position(|p| p.name == spec.param) else { continue };
        // The assertion-helper leg: the spec asserts a BOOLEAN of the parameter,
        // and the argument at that position is a condition. Read it as the guard
        // it is, before the value-fact lane gets a chance to make nothing of it.
        if let Some(then) = asserted_boolean(spec)
            && let Some(cond) = call.arg_cond(pos)
        {
            apply_helper_guard(cx, call, cond, then, env, store, asserted);
            continue;
        }
        let Some(arg) = call.args.get(pos) else { continue };
        let ArgValue::Var(v) = &arg.value else { continue };
        if apply_assert_to_var(env, store, v, spec) {
            asserted.insert(v.clone());
        }
    }
}

/// The boolean an assertion spec claims of its parameter, or `None` when the spec
/// asserts something other than a literal `true`/`false`.
///
/// Four spellings collapse to two answers, and negation is a plain XOR because the
/// asserted subject is a *condition* — `isset(…)`, a comparison, a `&&` chain —
/// whose value is a `bool` by construction, so "not `true`" is "`false`":
/// `@phpstan-assert true $c` and `@phpstan-assert !false $c` both say the guard
/// held; `@phpstan-assert false $c` and `@phpstan-assert !true $c` both say it did
/// not.
fn asserted_boolean(spec: &AssertSpec) -> Option<bool> {
    match steins_contract::lower(&spec.ty) {
        steins_contract::ContractTy::LitBool(b) => Some(b != spec.negated),
        _ => None,
    }
}

/// **Assertion-helper discharge** (ADR-0058 §3's tag lane, ADR-0062 A-G10's
/// discharge ladder): route a userland assertion helper's condition argument
/// through the SAME guard walk `assert($cond)` uses.
///
/// `Util_Assert::true(isset($options['user_id']));` is the corpus pattern this
/// exists for. `assert(isset(…))` discharges the strict leg because its argument
/// survives lowering as a condition; the helper form did not, because the value
/// lowering of `isset(…)` is [`ArgValue::Other`] — nothing to consume. With the
/// condition retained (`CallExpr::arg_conds`) the two forms differ in exactly one
/// respect, and it is the one ADR-0058 legislates:
///
/// * **Stratum.** `assert()` is *Verified, unconditionally* (the 2026-07-25
///   ruling reads it as `if (!$cond) throw`). A helper carrying only a
///   `@phpstan-assert` tag is **Asserted** — ADR-0058's table row "userland
///   helper, tag-declared only", restated as a refusal in its §8: the tag lane is
///   a claim and a lying tag must not forge a proof. So the presence promotion
///   this applies is `Required { witnessed: false }`. The DISCHARGE is unaffected
///   — `offset.maybe-missing` is a contract-layer finding over an `Asserted`
///   shape (A-G9's corollary), so an Asserted presence silences it just as a
///   witnessed one does, and no proof-layer id can be premised on either.
///   Raising this leg to Verified needs the descent proof of ADR-0058 §3 (slice
///   I2), which reads the helper's throw-guard out of its body rather than
///   trusting the tag; that remains outside this rule.
/// * **Nothing else.** Polarity, `&&`/`||` distribution, the S5 disjunctive
///   cover, tag discrimination and arm subtraction are the walk's, unmodified.
///
/// The by-ref exemption is the second half. `assert()` never forgets its argument
/// (its statement carries no invalidation); a helper call *does* — the lowering
/// conservatively forgets every variable the call expression mentions, which
/// includes the base inside `isset($d['a'])` and would erase the narrowing one
/// statement later. A variable mentioned only inside a condition argument cannot
/// be bound by reference (PHP binds a reference to a variable or lvalue, never to
/// the value of `isset(…)` or `$a && $b`), so it is exempt — unless the SAME call
/// also hands that variable over directly, which is the one case that can mutate.
#[allow(clippy::too_many_arguments)]
fn apply_helper_guard(
    cx: &Cx,
    call: &CallExpr,
    cond: &CondExpr,
    then: bool,
    env: &mut HashMap<String, Known>,
    store: &mut Store,
    asserted: &mut HashSet<String>,
) {
    let mut guards = Vec::new();
    collect_shape_guards(cx, cond, then, &mut guards);
    for g in &guards {
        // ADR-0058: tag-declared, so the presence stratum is the declared one.
        apply_shape_guard(cx, g, env, store, false);
        let var = g.var();
        let handed_over = call
            .args
            .iter()
            .map(|a| &a.value)
            .chain(call.named_args.iter().map(|n| &n.value))
            .any(|v| matches!(v, ArgValue::Var(name) if name == var));
        if !handed_over {
            asserted.insert(var.to_owned());
        }
    }
}

/// Apply one assertion spec to a caller variable at the **`Asserted`** stratum
/// (ADR-0052 §5 — a docblock is a claim, never a proof). Replace-if-weaker, in two
/// halves: (1) a stronger finite fact (`Singleton`/`OneOf`) is kept — an assert
/// never coarsens known-exact knowledge; (2) **an `Asserted` fact never overwrites
/// a `Verified` one of any layer**, so a lying
/// `@phpstan-assert` cannot downgrade a proven fact into a forgeable one (nor
/// launder its own claim past the stratum gate). A negated `!null` clears
/// nullability (also `Asserted`); other negated forms are not representable as a
/// positive fact and are skipped (documented).
///
/// Returns whether the variable now carries an established fact (so the caller
/// protects it from the by-ref invalidation) — `true` when a fact was set or a
/// stronger/Verified fact was deliberately kept, `false` when nothing applied.
fn apply_assert_to_var(
    env: &mut HashMap<String, Known>,
    store: &mut Store,
    var: &str,
    spec: &AssertSpec,
) -> bool {
    let cty = steins_contract::lower(&spec.ty);
    if spec.negated {
        // Only `!null` is representable as a positive narrowing (clear nullable);
        // other negated forms establish nothing. The narrowing is `Asserted`, so
        // `refine_fact` mins the result to `Asserted`.
        // The presence test is deliberately blind to a `Fact::Shape` entry
        // (ADR-0062 S3): the shape seed is entry-state provenance, not an
        // assert-visible narrowing target, and `clear_null` is a no-op on it
        // anyway. Counting it would flip this to `true` for every array param and
        // so protect the variable from the by-ref invalidation sweep — a control
        // change with nothing behind it. Shape narrowing (including clearing a
        // nullable shape) is S4's, and arrives with its own refinement operator.
        if matches!(cty, steins_contract::ContractTy::Null)
            && env
                .get(var)
                .is_some_and(|k| !matches!(k.fact, Some(Fact::Shape { .. })))
        {
            refine_fact(env, var, Stratum::Asserted, clear_null);
            return true;
        }
        return false;
    }
    let Some(fact) = assert_fact_of(&cty) else { return false };
    // Keep the existing fact when it is a stronger finite layer OR when it is
    // already `Verified` (replace-if-weaker, both halves): an `Asserted` claim may
    // neither coarsen exact knowledge nor overwrite a proven fact. Either way the
    // variable stays protected from the by-ref invalidation (a by-value assert did
    // not mutate it).
    if env.get(var).is_some_and(|k| {
        k.stratum == Stratum::Verified || k.fact.as_ref().is_some_and(|f| f.finite_members().is_some())
    }) {
        return true;
    }
    env.insert(var.to_owned(), Known::value_strat(fact, 0, Some("asserted".to_owned()), Stratum::Asserted));
    store.unbind(var);
    true
}

/// Every bare variable a guard may mutate by reference, and therefore forgets on
/// both paths.
///
/// **The S4 exemption, and how narrow it is.** `isset($x['k'])`,
/// `array_key_exists('k', $x)` and `array_is_list($x)` cannot mutate anything —
/// the first is not even a function call, the other two are pure by-value
/// builtins. Before S4 all three forgot their base (the first because it lowered
/// to `Opaque`, the other two because a retained guard call forgets its reads),
/// which was pure conservatism. Lifting it *wholesale* would let every lane see
/// facts across such a guard for the first time, and a proven `Singleton` array
/// surviving into the branch can premise a proof-layer `offset.missing` that did
/// not fire before. So the exemption is granted only to a base that carries the
/// **shape lane** — a `Fact::Shape`, or a contract lane with an array arm — which
/// is exactly what this narrowing consumes and is `Asserted` end to end
/// (A-G9). A base mentioned anywhere else in the same condition keeps the old
/// forgetting, because that other mention is what might mutate it.
fn cond_invalidations(
    cx: &Cx,
    cond: &CondExpr,
    env: &HashMap<String, Known>,
    store: &Store,
    poisoned: bool,
) -> Vec<String> {
    let mut out = Vec::new();
    collect_cond_opaque_reads(cx, cond, &CondEnv { env, store, poisoned }, &mut out);
    let mut pure = Vec::new();
    collect_pure_guard_bases(cx, cond, &mut pure);
    for v in pure {
        if out.contains(&v) || shape_lane_present(&v, env, store) {
            continue;
        }
        out.push(v);
    }
    out
}

/// The bases of guards that provably cannot mutate: the `isset` form and the
/// recognized pure array builtins.
fn collect_pure_guard_bases(cx: &Cx, cond: &CondExpr, out: &mut Vec<String>) {
    match cond {
        CondExpr::Isset { var, .. } => {
            if !out.contains(var) {
                out.push(var.clone());
            }
        }
        CondExpr::Call { call, reads }
            if array_guard_predicate(cx, call).is_some()
                || array_all_any_predicate(cx, call).is_some() =>
        {
            for r in reads {
                if !out.contains(r) {
                    out.push(r.clone());
                }
            }
        }
        // A pure predicate keeps its exemption when it is *compared* rather than
        // tested (`array_is_list($x) === true`): position within the condition
        // does not change what a call can do, in either direction.
        CondExpr::Cmp { lhs, rhs, .. } => {
            for operand in [lhs, rhs] {
                let CondOperand::Other { call: Some(call), invalidates, .. } = operand else {
                    continue;
                };
                if array_guard_predicate(cx, call).is_some()
                    || array_all_any_predicate(cx, call).is_some()
                {
                    for r in invalidates {
                        if !out.contains(r) {
                            out.push(r.clone());
                        }
                    }
                }
            }
        }
        CondExpr::Not(c) => collect_pure_guard_bases(cx, c, out),
        CondExpr::And(a, b) | CondExpr::Or(a, b) => {
            collect_pure_guard_bases(cx, a, out);
            collect_pure_guard_bases(cx, b, out);
        }
        _ => {}
    }
}

/// Does `var` carry the shape lane — either half of it? The fact half is empty
/// for a *union* of array shapes by design (A-G3 keeps the union in the arm
/// lane), so testing the fact alone would leave exactly the discriminated-union
/// case unexempted.
fn shape_lane_present(var: &str, env: &HashMap<String, Known>, store: &Store) -> bool {
    if env.get(var).is_some_and(|k| matches!(k.fact, Some(Fact::Shape { .. }))) {
        return true;
    }
    store
        .contract
        .get(var)
        .is_some_and(|arms| arms.iter().any(|a| steins_contract::to_shape_fact(&a.ty).is_some()))
}

/// The walk-local state the operand arm of [`collect_cond_opaque_reads`] needs
/// to run ADR-0070's by-value gate — everything the gate asks that the condition
/// itself cannot answer.
struct CondEnv<'a> {
    env: &'a HashMap<String, Known>,
    store: &'a Store,
    poisoned: bool,
}

fn collect_cond_opaque_reads(cx: &Cx, cond: &CondExpr, ce: &CondEnv, out: &mut Vec<String>) {
    match cond {
        // An opaque condition may mutate any variable it reads by reference — the
        // whole read-set is forgotten (the conservative floor, unchanged).
        CondExpr::Opaque { reads } => {
            for r in reads {
                if !out.contains(r) {
                    out.push(r.clone());
                }
            }
        }
        CondExpr::Call { call, reads } => collect_call_opaque_reads(cx, call, reads, out),
        // **Operand position** (issue #158). A call does not become harmless by
        // sitting inside a comparison: `preg_match($re, $s, $m) === 1` writes
        // `$m` exactly as the bare `preg_match($re, $s, $m)` guard does, and
        // before this arm existed the walk had nothing to forget — an earlier
        // `$m = []` survived into the branch and was reported there as `list{}`,
        // a false fact on a reachable path. The rule is the one-liner it should
        // always have been: **an operand's writes are judged by the same policy
        // as a guard call's, because position within the condition changes
        // nothing about what a call can do.**
        CondExpr::Cmp { lhs, rhs, .. } => {
            collect_operand_opaque_reads(cx, lhs, ce, out);
            collect_operand_opaque_reads(cx, rhs, ce, out);
        }
        // `f($x, $m) instanceof Foo` — the same gap, reached through the other
        // operand-carrying variant. (`Truthy`'s operand can only be an `Offset`
        // here: `lower_cond` routes a call or any other unrepresentable
        // condition to `Call`/`Opaque` before it can become a `Truthy(Other)`.)
        CondExpr::Instanceof { operand, .. } => {
            collect_operand_opaque_reads(cx, operand, ce, out);
        }
        CondExpr::Not(c) => collect_cond_opaque_reads(cx, c, ce, out),
        CondExpr::And(a, b) | CondExpr::Or(a, b) => {
            collect_cond_opaque_reads(cx, a, ce, out);
            collect_cond_opaque_reads(cx, b, ce, out);
        }
        _ => {}
    }
}

/// The invalidation a comparison/`instanceof` operand contributes: nothing for
/// the modelled variants (a bare variable, a literal, a constant-key projection,
/// a constant fetch — none of them writes), and for [`CondOperand::Other`]
/// whatever its write set earns under the guard-call policy above, **minus what
/// ADR-0070's by-value gate proves the callee could not reach**.
///
/// The gate runs here and not on [`CondExpr::Call`] because this is where the
/// floor is being chosen for the first time. The blanket read-set drop in guard
/// position is pre-existing and measured, and lifting it would let facts survive
/// guards that never let them through before — a precision change with its own
/// FP exposure and its own measurement run. Choosing the *precise* sound rule
/// for a path that had no rule at all costs nothing and keeps 191 nsrt
/// observations (`count($listA) === count($listB)`, `strstr($s, 'a') === 'b'`)
/// that the missing invalidation had been holding up.
fn collect_operand_opaque_reads(
    cx: &Cx,
    operand: &CondOperand,
    ce: &CondEnv,
    out: &mut Vec<String>,
) {
    let CondOperand::Other { call, invalidates, sites } = operand else { return };
    let mut floor = Vec::new();
    match call {
        // The operand *is* a resolvable call: it gets every exemption a guard
        // call gets, including the by-value predicate families and the
        // method-receiver survival.
        Some(call) => collect_call_opaque_reads(cx, call, invalidates, &mut floor),
        // A write the lowering could not name a callee for — a dynamic call, a
        // call nested inside arithmetic, an assignment or an increment
        // (`($x = f()) === 1`, `$i++ === 5`). No call-shaped exemption applies to
        // something this walk cannot identify, so the whole set is the floor.
        None => floor = invalidates.clone(),
    }
    let survivors = by_value_survivors(cx, ce.poisoned, sites, ce.env, ce.store);
    for r in floor {
        if !survivors.contains(r.as_str()) && !out.contains(&r) {
            out.push(r);
        }
    }
}

/// One retained call's contribution to the invalidation set — **the single
/// policy for what a call in a condition forgets**, wherever in the condition it
/// sits (guard position, or an operand of a comparison/`instanceof`).
///
/// The general rule is its `reads`, minus the pure method receiver (`$x` in
/// `$x->m()` is not rebound by the call, only its object's props are swept;
/// ADR-0052 §6 payoff (i)) — which survives only when it is not also handed in
/// as an argument (`$x->m($x)` passes it by value/ref, so it is still
/// forgotten). Two families are exempt outright:
///
/// **The S4 exemption.** A recognized pure array builtin mutates nothing; its
/// bases are decided by [`collect_pure_guard_bases`] + the shape-lane test
/// instead. `array_all`/`array_any` (A8) join this set: neither parameter is
/// by-ref in PHP's own signature, so the base array is exactly as safe as
/// `array_is_list`'s — any *other* alias risk (a callback closing over the base
/// by reference) is still caught, because `collect_pure_guard_bases` only
/// exempts a read that also carries the shape lane, and a by-ref-captured var
/// generally won't.
///
/// **The DR2 exemption, and why it is unconditional** (unlike S4's, which is
/// gated on the shape lane). The `is_*` family and `in_array` declare every
/// parameter BY VALUE in PHP's own signature and are side-effect free, so a
/// guard call cannot have changed the base between the test and the branch.
/// S4 kept its exemption shape-lane-gated because lifting it wholesale would
/// let *any* proven fact survive a guard for the first time; here the base's
/// scalar fact surviving is the entire point of the slice — and every finding
/// it can premise is true by construction, because the value the branch sees
/// is the value the predicate tested. A base mentioned by any OTHER call in
/// the same condition is still forgotten: that mention is what might mutate
/// it, and it is collected by that call's own visit.
fn collect_call_opaque_reads(cx: &Cx, call: &CallExpr, reads: &[String], out: &mut Vec<String>) {
    if array_guard_predicate(cx, call).is_some()
        || array_all_any_predicate(cx, call).is_some()
        || type_predicate(cx, call).is_some()
        || in_array_literals(cx, call, cx.php_minor).is_some()
    {
        return;
    }
    let recv = call_method_receiver_var(call);
    let recv_is_arg = recv
        .is_some_and(|r| call.args.iter().any(|a| matches!(&a.value, ArgValue::Var(v) if v == r)));
    for r in reads {
        if Some(r.as_str()) == recv && !recv_is_arg {
            continue;
        }
        if !out.contains(r) {
            out.push(r.clone());
        }
    }
}

/// The bare method-receiver variable of a call (`$x` in `$x->m(...)`), or `None`
/// for a function/static/constructor/dynamic call or a non-variable receiver.
fn call_method_receiver_var(call: &CallExpr) -> Option<&str> {
    match &call.receiver {
        Callee::Method { receiver: Receiver::Var(v), .. } => Some(v),
        _ => None,
    }
}

/// Join the fall-through envs of several live branches (ADR-0031/0035): a scalar
/// fact survives only when present in *every* branch, folded through [`Fact::join`]
/// (equal → Singleton; differing → OneOf; overflow → dropped). An exact-class fact
/// survives only when every branch agrees on the class.
fn join_envs(
    branches: Vec<(HashMap<String, Known>, Store)>,
) -> (HashMap<String, Known>, Store) {
    let mut it = branches.into_iter();
    let (first_env, first_classes) = it.next().expect("join_envs called with no branches");
    let rest: Vec<(HashMap<String, Known>, Store)> = it.collect();
    if rest.is_empty() {
        return (first_env, first_classes);
    }

    let mut env: HashMap<String, Known> = HashMap::new();
    for (name, k0) in &first_env {
        // A closure-only binding survives a join only when every branch binds the
        // SAME closure target (a differing/absent branch drops it — the safe side).
        if let Some(cv0) = &k0.closure {
            let all_same = rest.iter().all(|(be, _)| {
                be.get(name)
                    .and_then(|k| k.closure.as_ref())
                    .is_some_and(|cv| closure_target_eq(&cv0.target, &cv.target))
            });
            if all_same {
                env.insert(name.clone(), Known::closure(cv0.clone(), k0.line));
            }
            continue;
        }
        let Some(mut fact) = k0.fact.clone() else { continue };
        // Derivation clause: a branch join takes `min` over the joined arms' strata
        // (Verified ⊔ Asserted ⇒ Asserted). The neutral start is `k0`'s own stratum.
        let mut stratum = k0.stratum;
        let mut ok = true;
        for (be, _) in &rest {
            match be.get(name) {
                Some(k) if k.fact.is_some() => match fact.join(k.fact.as_ref().expect("checked")) {
                    Some(joined) => {
                        fact = joined;
                        stratum = stratum.min(k.stratum);
                    }
                    None => {
                        ok = false;
                        break;
                    }
                },
                _ => {
                    ok = false;
                    break;
                }
            }
        }
        if ok {
            env.insert(name.clone(), Known::value_strat(fact, k0.line, k0.bound.clone(), stratum));
        }
    }

    let rest_stores: Vec<&Store> = rest.iter().map(|(_, s)| s).collect();
    let store = join_stores(&first_classes, &rest_stores);
    (env, store)
}

/// Join the heap stores of several fall-through branches (ADR-0036). A variable's
/// ObjRef survives only when every branch binds it to the SAME allocation id (a
/// pre-branch object keeps its id across the clones; a per-branch `new`/`clone`
/// gets a distinct id and so is dropped). A surviving object joins its props
/// member-wise (a prop survives only if present-and-joinable in every branch),
/// unions `escaped` (escaped anywhere → escaped), and intersects `ro_written` (a
/// readonly write counts only when proven on every joined path).
fn join_stores(first: &Store, rest: &[&Store]) -> Store {
    let mut refs: HashMap<String, AllocId> = HashMap::new();
    for (var, id) in &first.refs {
        if rest.iter().all(|s| s.refs.get(var) == Some(id)) {
            refs.insert(var.clone(), *id);
        }
    }
    let mut heap: HashMap<AllocId, HeapObj> = HashMap::new();
    // Join every id that survives via a ref (and any id present in all branches).
    let live_ids: HashSet<AllocId> = refs.values().copied().collect();
    for id in live_ids {
        let Some(o0) = first.heap.get(&id) else { continue };
        let others: Vec<&HeapObj> = rest.iter().filter_map(|s| s.heap.get(&id)).collect();
        if others.len() != rest.len() {
            continue; // not present in every branch — drop it
        }
        let mut joined = HeapObj::new(o0.class.clone());
        // A surviving id is the SAME allocation across every branch, so its class and
        // exactness bit are invariant — carry them from the first branch (audit G1).
        joined.class_exact = o0.class_exact;
        joined.readonly = o0.readonly.clone();
        joined.escaped = o0.escaped || others.iter().any(|o| o.escaped);
        // ro_written: written on EVERY joined path.
        joined.ro_written = o0
            .ro_written
            .iter()
            .filter(|n| others.iter().all(|o| o.ro_written.contains(*n)))
            .cloned()
            .collect();
        // props: present-and-joinable in every branch, at `min` over strata
        // (derivation clause — a joined prop is Asserted if any branch's was).
        for (name, p0) in &o0.props {
            let mut fact = p0.fact.clone();
            let mut stratum = p0.stratum;
            let mut ok = true;
            for o in &others {
                match o.props.get(name) {
                    Some(kp) => match fact.join(&kp.fact) {
                        Some(j) => {
                            fact = j;
                            stratum = stratum.min(kp.stratum);
                        }
                        None => {
                            ok = false;
                            break;
                        }
                    },
                    None => {
                        ok = false;
                        break;
                    }
                }
            }
            if ok {
                joined.props.insert(name.clone(), PropFact { fact, stratum });
            }
        }
        heap.insert(id, joined);
    }

    // Contract lane: a var survives the join only if present in every branch; its
    // arms are the union of the branches' surviving arms (any value live on ANY
    // path is possible after the merge), deduped, each arm keeping its own stratum
    // (an `Asserted` arm never launders to `Verified` through a join). Absent in any
    // branch → dropped to no-fact (sound: the successor simply carries no lane).
    let mut contract: HashMap<String, Vec<ContractArm>> = HashMap::new();
    for (var, arms0) in &first.contract {
        if !rest.iter().all(|s| s.contract.contains_key(var)) {
            continue;
        }
        let mut merged = arms0.clone();
        for s in rest {
            if let Some(arms) = s.contract.get(var) {
                merged.extend(arms.iter().cloned());
            }
        }
        dedup_contract_arms(&mut merged);
        contract.insert(var.clone(), merged);
    }

    // Member lane: a var survives only if present in every branch; its `yes`/`no`
    // sets are the INTERSECTION across branches (a bound holds after the merge only
    // if it held on every path). An emptied Member is dropped (no-fact).
    let mut members: HashMap<String, Member> = HashMap::new();
    for (var, m0) in &first.members {
        let others: Vec<&Member> = rest.iter().filter_map(|s| s.members.get(var)).collect();
        if others.len() != rest.len() {
            continue;
        }
        let yes: Vec<String> =
            m0.yes.iter().filter(|c| others.iter().all(|o| o.yes.contains(c))).cloned().collect();
        let no: Vec<String> =
            m0.no.iter().filter(|c| others.iter().all(|o| o.no.contains(c))).cloned().collect();
        if !(yes.is_empty() && no.is_empty()) {
            members.insert(var.clone(), Member { yes, no });
        }
    }

    // Existence-vouch lane (ADR-0049 §4): a vouch survives the join only if EVERY
    // branch carried it — the intersection. A vouch bound on a guarded branch that
    // falls through must not leak onto a sibling path that was never guarded (so the
    // tail of `if (method_exists(C,'m')) {} (new C)->m();` still fires).
    let vouched: HashSet<Vouch> =
        first.vouched.iter().filter(|v| rest.iter().all(|s| s.vouched.contains(*v))).cloned().collect();

    Store { refs, heap, contract, members, vouched }
}

/// Remove contract arms another surviving arm subsumes (`Certainty::Yes`) — the
/// stratified analogue of [`normalize::dedup_arms`]: on a subsumption tie the arm
/// with the **weaker** (min) stratum is kept, so a join can never raise an
/// `Asserted` possibility to `Verified` by dropping it in favor of a `Verified`
/// twin that denotes the same set (ADR-0052 §5 derivation clause).
fn dedup_contract_arms(arms: &mut Vec<ContractArm>) {
    let mut kept: Vec<ContractArm> = Vec::with_capacity(arms.len());
    for arm in arms.drain(..) {
        // Collapse a structurally-identical arm FIRST (`ty == ty`), keeping the min
        // stratum. This is the reflexive tie `subsumes`/`arm_eq` deliberately cannot
        // prove for the non-extensional arms (`StrOpaque`, `CallableTy`, `Opaque` —
        // ADR-0038: membership is unmodeled, so `subsumes(x, x)` is `Maybe`, not
        // `Yes`). The array vocabulary (`ArrayAny`/`ListOf`/`MapOf`/`IterableOf`/
        // `Shape`) left that list with ADR-0071, which gave it a structural
        // denotation and hence arm_eq-reflexivity; this fast path still collapses it
        // first, and more cheaply. Exact structural equality is a strictly stronger
        // witness of same-denotation than mutual subsumption, so keeping one is sound
        // and loses no precision — and it is what stops a branch-union from *doubling*
        // a pile of identical opaque arms at every join. Without it an `array`/`Closure`
        // parameter threaded through a deeply nested `if` tree grew to 2^depth copies
        // of one arm (survey non-termination on nextcloud `core/Migrations`).
        if let Some(k) =
            kept.iter_mut().find(|k| k.ty == arm.ty || normalize::arm_eq(&k.ty, &arm.ty))
        {
            k.stratum = k.stratum.min(arm.stratum);
            continue;
        }
        // Drop an arm strictly subsumed by a kept one; if it subsumes kept arms,
        // it replaces them (widening), inheriting the min stratum of all it covers.
        if kept.iter().any(|k| normalize::subsumes(&k.ty, &arm.ty).is_yes()) {
            continue;
        }
        let mut stratum = arm.stratum;
        kept.retain(|k| {
            if normalize::subsumes(&arm.ty, &k.ty).is_yes() {
                stratum = stratum.min(k.stratum);
                false
            } else {
                true
            }
        });
        kept.push(ContractArm { ty: arm.ty, stratum });
    }
    absorb_contract_arms(&mut kept);
    *arms = kept;
}

/// Run a contract-arm list to the interval-absorption fixpoint (issue #90), the
/// stratified analogue of the pass [`normalize::dedup_arms`] gained: `int<1, max>`
/// beside `0` is one denotation spelled two ways, and subsumption cannot collapse
/// it because neither arm covers the other.
///
/// The merged arm takes the **min** stratum of the pair, for the same reason the
/// subsumption widening above does (ADR-0052 §5): the merged arm is only as
/// strongly held as the weaker of the two claims it replaces, so a `Verified`
/// twin can never lift an `Asserted` one.
///
/// Runs wherever an arm list is minted or joined, so the lane never *stores* the
/// two-armed spelling — the collapse is semantic, not a rendering choice, and the
/// dump surface inherits it rather than deciding it (the ADR-0052 §4 charter).
fn absorb_contract_arms(arms: &mut Vec<ContractArm>) {
    loop {
        let mut merged_at: Option<(usize, usize, ContractArm)> = None;
        'outer: for i in 0..arms.len() {
            for j in (i + 1)..arms.len() {
                if let Some(ty) = normalize::merge_int_arms(&arms[i].ty, &arms[j].ty) {
                    let stratum = arms[i].stratum.min(arms[j].stratum);
                    merged_at = Some((i, j, ContractArm { ty, stratum }));
                    break 'outer;
                }
            }
        }
        let Some((i, j, m)) = merged_at else { return };
        arms[i] = m;
        arms.remove(j);
    }
}

// ---------------------------------------------------------------------------
// PHP scalar comparison semantics (ADR-0031). `===`/truthiness are exact; `==`
// is settled EMPIRICALLY against PHP 8.5.8 (see [`php_loose_eq`]). Undecidable
// cells return `None` → the caller yields `Maybe` (silence, the sound side).
// ---------------------------------------------------------------------------

/// PHP truthiness of a proven value. Note `"0"` and `""` are the only falsy
/// non-empty/-empty strings (`"0.0"` and `"00"` are **truthy**), `0`/`0.0`/`[]`
/// are falsy. `None` for a non-concrete value.
fn php_truthy(v: &ArgValue) -> Option<bool> {
    match v {
        ArgValue::Null => Some(false),
        ArgValue::Bool(b) => Some(*b),
        ArgValue::Int(i) => Some(*i != 0),
        ArgValue::Float(f) => Some(*f != 0.0),
        ArgValue::Str(s) => Some(!(s.is_empty() || s == "0")),
        ArgValue::Array(items) => Some(!items.is_empty()),
        _ => None,
    }
}

/// Strict identity `===`: same runtime type AND equal value. Different concrete
/// runtime types are a definite non-identity; a non-concrete operand is `None`.
fn php_identical(a: &ArgValue, b: &ArgValue, php_minor: Option<(u16, u16)>) -> Option<bool> {
    use ArgValue::{Array, Bool, Float, Int, Null, Str};
    match (a, b) {
        (Int(x), Int(y)) => Some(x == y),
        (Float(x), Float(y)) => Some(x == y),
        (Str(x), Str(y)) => Some(x == y),
        (Bool(x), Bool(y)) => Some(x == y),
        (Null, Null) => Some(true),
        (Array(_), Array(_)) => php_array_identical(a, b, php_minor),
        _ if is_concrete(a) && is_concrete(b) => Some(false),
        _ => None,
    }
}

/// Deep `===` of two array literals: same length, same key order, element-wise
/// identical. A non-concrete element makes the result `None`.
fn php_array_identical(a: &ArgValue, b: &ArgValue, php_minor: Option<(u16, u16)>) -> Option<bool> {
    let (ArgValue::Array(ai), ArgValue::Array(bi)) = (a, b) else { return None };
    // Keys the project's PHP minor cannot pin down make the whole verdict
    // undecidable (ADR-0049 A12) — `===` compares key order, so a guessed key
    // would forge a `===` premise.
    let na = normalize_array(ai, php_minor)?;
    let nb = normalize_array(bi, php_minor)?;
    if na.len() != nb.len() {
        return Some(false);
    }
    for ((ka, va), (kb, vb)) in na.iter().zip(nb.iter()) {
        if ka != kb {
            return Some(false);
        }
        match php_identical(va, vb, php_minor) {
            Some(true) => {}
            Some(false) => return Some(false),
            None => return None,
        }
    }
    Some(true)
}

/// Whether a value is a fully-known concrete value (a scalar literal or an array).
fn is_concrete(v: &ArgValue) -> bool {
    v.is_literal() || matches!(v, ArgValue::Array(_))
}

/// Loose equality `==`, settled **empirically against PHP 8.5.8** (`php -r`, the
/// full cross-product of `null`/`false`/`true`/`0`/`0.0`/`""`/`"0"`/`"abc"`/`"5"`/`[]`
/// recorded). The measured table (`T` = equal):
///
/// ```text
///           null false true  0   0.0   ""   "0"  "abc" "5"   []
///   null     T    T    F    T    T     T    F    F     F     T
///   false    T    T    F    T    T     T    T    F     F     T
///   true     F    F    T    F    F     F    F    T     T     F
///   0        T    T    F    T    T     F    T    F     F     F
///   0.0      T    T    F    T    T     F    T    F     F     F
///   ""       T    T    F    F    F     T    F    F     F     F
///   "0"      F    T    F    T    T     F    T    F     F     F
///   "abc"    F    F    T    F    F     F    F    T     F     F
///   "5"      F    F    T    F    F     F    F    F     T     F
///   []       T    T    F    F    F     F    F    F     F     T
/// ```
///
/// The rules reproduced (stable since PHP 8.0): a `bool` operand casts BOTH sides
/// to bool; `null` compares to the other side's zero/empty (except bool, handled
/// by the bool rule); `int`/`float` vs a numeric string compares numerically,
/// vs a non-numeric string compares the number's string form; two strings compare
/// numerically iff both are numeric strings, else byte-wise; an array is unequal
/// to any scalar (non-null, non-bool). Cells not covered (a `float` vs a
/// non-numeric string; non-trivial arrays) return `None` → `Maybe`.
fn php_loose_eq(a: &ArgValue, b: &ArgValue, php_minor: Option<(u16, u16)>) -> Option<bool> {
    use ArgValue::{Array, Bool, Float, Int, Null, Str};
    // A `bool` on either side casts both operands to bool (subsumes null==bool).
    if matches!(a, Bool(_)) || matches!(b, Bool(_)) {
        return Some(php_truthy(a)? == php_truthy(b)?);
    }
    match (a, b) {
        (Null, Null) => Some(true),
        (Null, Int(i)) | (Int(i), Null) => Some(*i == 0),
        (Null, Float(f)) | (Float(f), Null) => Some(*f == 0.0),
        (Null, Str(s)) | (Str(s), Null) => Some(s.is_empty()),
        (Null, Array(items)) | (Array(items), Null) => Some(items.is_empty()),
        (Null, _) | (_, Null) => None,

        (Int(x), Int(y)) => Some(x == y),
        (Int(x), Float(y)) | (Float(y), Int(x)) => Some((*x as f64) == *y),
        (Float(x), Float(y)) => Some(x == y),

        (Int(i), Str(s)) | (Str(s), Int(i)) => Some(php_int_str_eq(*i, s)),
        (Float(f), Str(s)) | (Str(s), Float(f)) => php_float_str_eq(*f, s),
        (Str(x), Str(y)) => Some(php_str_eq(x, y)),

        (Array(x), Array(y)) => php_array_loose_eq(x, y, php_minor),
        // An array is never loosely equal to a (non-null, non-bool) scalar.
        (Array(_), Int(_) | Float(_) | Str(_)) | (Int(_) | Float(_) | Str(_), Array(_)) => {
            Some(false)
        }
        _ => None,
    }
}

/// `int == string`: numeric string → numeric compare; else compare the int's
/// decimal form to the string (PHP 8 semantics).
fn php_int_str_eq(i: i64, s: &str) -> bool {
    if php_is_numeric(s) {
        php_str_to_float(s).is_some_and(|f| (i as f64) == f)
    } else {
        i.to_string() == s
    }
}

/// `float == string`: numeric string → numeric compare; a non-numeric string is
/// undecidable here (float→string formatting is precision-sensitive) → `None`.
fn php_float_str_eq(f: f64, s: &str) -> Option<bool> {
    if php_is_numeric(s) {
        Some(php_str_to_float(s).is_some_and(|g| f == g))
    } else {
        None
    }
}

/// `string == string`: both numeric strings → numeric compare; else byte compare.
fn php_str_eq(x: &str, y: &str) -> bool {
    if php_is_numeric(x) && php_is_numeric(y) {
        match (php_str_to_float(x), php_str_to_float(y)) {
            (Some(a), Some(b)) => a == b,
            _ => x == y,
        }
    } else {
        x == y
    }
}

/// `array == array`: same key set with loosely-equal values (order-independent).
/// An undecidable element value makes the whole comparison `None`.
fn php_array_loose_eq(
    x: &[(ArrayKey, ArgValue)],
    y: &[(ArrayKey, ArgValue)],
    php_minor: Option<(u16, u16)>,
) -> Option<bool> {
    // As in `php_array_identical`: unproven keys make `==` undecidable, since the
    // comparison is key-set-based (ADR-0049 A12).
    let nx = normalize_array(x, php_minor)?;
    let ny = normalize_array(y, php_minor)?;
    if nx.len() != ny.len() {
        return Some(false);
    }
    for (k, va) in &nx {
        let Some((_, vb)) = ny.iter().find(|(k2, _)| k2 == k) else {
            return Some(false);
        };
        match php_loose_eq(va, vb, php_minor) {
            Some(true) => {}
            Some(false) => return Some(false),
            None => return None,
        }
    }
    Some(true)
}

/// The class FQN that lexically owns a method scope; `None` for function/top.
fn scope_class(scope: &Scope) -> Option<&str> {
    match &scope.owner {
        ScopeOwner::Method { class, .. } => Some(class),
        // A closure lexically inside a method captures `$this`, but the analyzer
        // does not thread the enclosing class into the closure scope (documented).
        ScopeOwner::TopLevel | ScopeOwner::Function(_) | ScopeOwner::Closure { .. } => None,
    }
}

/// The statically-named calls a statement carries.
fn checkable_calls(kind: &StmtKind) -> Vec<&CallExpr> {
    match kind {
        StmtKind::Call(c) => vec![c],
        StmtKind::Return { call: Some(c), .. }
        | StmtKind::Assign { call: Some(c), .. }
        | StmtKind::PropAssign { value_call: Some(c), .. } => vec![c],
        StmtKind::Echo(cs) => cs.iter().collect(),
        _ => Vec::new(),
    }
}

/// Escape + sweep the heap for a statement's calls (ADR-0036). Passing an object
/// (as an argument, or as the `$var` receiver of a method call) escapes it. If any
/// object was passed into a call, or any call is unknown/overridable (not resolved
/// to a project target), sweep every escaped object's non-readonly props. A purely
/// local object never passed anywhere survives an unrelated unknown call — the
/// precision payoff.
fn apply_call_escape_and_sweep(w: &WalkCx, kind: &StmtKind, store: &mut Store) {
    let calls = checkable_calls(kind);
    escape_and_sweep_calls(w, &calls, store);
}

/// Escape + sweep for an explicit set of calls (ADR-0036), shared by the
/// statement-position pass ([`apply_call_escape_and_sweep`]) and the guard-position
/// retained-call handling (ADR-0052 §6): a guard call's object arguments and its
/// method receiver escape, and any object passed in — or any unknown/overridable
/// call — sweeps every escaped object's non-readonly props. The receiver's var→id
/// *binding* survives (a method call does not rebind its receiver variable), so the
/// receiver stays usable on the guarded path; only its mutable props are swept.
fn escape_and_sweep_calls(w: &WalkCx, calls: &[&CallExpr], store: &mut Store) {
    if calls.is_empty() {
        return;
    }
    let mut object_passed = false;
    let mut unknown = false;
    for call in calls {
        if let Callee::Method { receiver: Receiver::Var(v), .. } = &call.receiver
            && store.is_bound(v)
        {
            store.mark_escaped(v);
            object_passed = true;
        }
        for arg in &call.args {
            if let ArgValue::Var(name) = &arg.value
                && store.is_bound(name)
            {
                store.mark_escaped(name);
                object_passed = true;
            }
        }
        if !call_is_resolved(w, call, store) {
            unknown = true;
        }
    }
    if object_passed || unknown {
        store.sweep_escaped();
    }
}

/// Whether a call resolves to a known project/user target (ADR-0036). An unresolved
/// function (builtin/unknown/dynamic) or an unresolved-via-guard method (an
/// overridable `$this`/`self` call) counts as unknown — the sweeping side.
fn call_is_resolved(w: &WalkCx, call: &CallExpr, store: &Store) -> bool {
    match &call.receiver {
        Callee::Function(_) => w.cx.resolve_user_fn(call).is_some(),
        Callee::Method { .. } | Callee::Static { .. } | Callee::Construct { .. } => {
            resolve_call_target(
                w.cx, &call.receiver, store, w.this_exact, w.enclosing_class, w.scope.poisoned,
            )
            .is_some()
        }
        Callee::DynamicVar(_) | Callee::Dynamic => false,
    }
}

/// Check a function call whose arguments may be propagated values (`Var`/`Call`/
/// array). Runs the native runtime check and the phpdoc declared-contract check;
/// a site where the native check fired is skipped by the phpdoc check.
#[allow(clippy::too_many_arguments)]
fn check_propagated_call(
    cx: &Cx,
    folder: &mut dyn Folder,
    poisoned: bool,
    in_descent: bool,
    call: &CallExpr,
    env: &HashMap<String, Known>,
    store: &Store,
    out: &mut Vec<Diagnostic>,
) {
    // Resolve non-positional calls too (Gap A): the positional prefix and the named
    // arguments are contract-checked here; only the binding descent stays positional.
    let Some(site) = cx.resolve_user_fn_any(call) else { return };
    let decl = cx.fn_decl(site);
    let envelopes = parse_envelopes(decl.docblock.as_deref());

    for (i, arg) in call.args.iter().enumerate() {
        let Some(param) = decl.params.get(i) else { break };
        if param.variadic {
            break;
        }
        if param.by_ref {
            continue;
        }

        let mut native_fired = false;
        if let Some(ty) = param.ty.as_ref() {
            // Resolved value + provenance + the trust stratum that arrived with the
            // resolution (issue #127 review). The proof gate must use this stratum —
            // never a re-read of the syntactic call tree via `value_stratum`, which
            // would launder an Asserted fold (`strtoupper(g(...))`) into Verified.
            let resolved: Option<(ArgValue, String, Stratum)> = match &arg.value {
                ArgValue::Var(name) if !poisoned => env.get(name).and_then(|k| {
                    let v = k.singleton()?;
                    let prov = match &k.bound {
                        Some(b) => format!("from ${name}, {b}"),
                        None => format!("from ${name}, assigned at line {}", k.line),
                    };
                    Some((v, prov, k.stratum))
                }),
                ArgValue::Call(name, args) => {
                    let direct = if args.is_empty() {
                        cx.resolve_const_fn(name)
                            .map(|(lit, line)| {
                                (
                                    lit,
                                    format!("from {name}(), defined at line {line}"),
                                    Stratum::Verified,
                                )
                            })
                            .or_else(|| {
                                cx.try_fold_emit(name, args, env, poisoned, folder, out)
                            })
                    } else {
                        cx.try_fold_emit(name, args, env, poisoned, folder, out)
                    };
                    // A nested project call (issue #60): its Singleton return summary
                    // is the argument's proven value — `takesInt(g(1))` sees what `g`
                    // provably returns, the same crossing `$x = g(1); takesInt($x)`
                    // always had. Plain per-scope pass only: a fresh descent tree
                    // started from inside a live descent would evade the on-stack
                    // recursion guard (mutual recursion through an argument position
                    // would loop), and the plain pass walks every scope anyway, so
                    // the descent-pass decline loses no site. `Verified`-only: the
                    // native proof below consumes an all-Verified premise (ADR-0052
                    // §5), and an Asserted summary must not launder into it. Findings
                    // go to the real `out` so a binding-specific proof under `g(1)`
                    // is not discarded (issue #127 review); dedup absorbs any
                    // binding-independent copy already emitted by the plain walk.
                    direct.or_else(|| {
                        if in_descent {
                            return None;
                        }
                        let summary = project_call_summary(
                            cx, folder, name, args, env, poisoned, arg.span.start, None, out,
                        )?;
                        let sv = summary.value?;
                        if sv.stratum != Stratum::Verified {
                            return None;
                        }
                        let Fact::Singleton(v) = &sv.fact else { return None };
                        Some((arg_of_val(v), format!("returned from {name}()"), sv.stratum))
                    })
                }
                // A property read `$o->p` (ADR-0036): a `Singleton` prop fact flows.
                ArgValue::PropFetch { var, prop } if !poisoned => {
                    store.prop_fact(var, prop).and_then(|f| match f {
                        Fact::Singleton(v) => Some((
                            arg_of_val(v),
                            format!("from ${var}->{prop}"),
                            store.prop_stratum(var, prop),
                        )),
                        _ => None,
                    })
                }
                _ => None,
            };
            // Proof-layer consumption rule (ADR-0052 §5): the native
            // `type.argument-mismatch` fires only on an all-`Verified` premise. A
            // value proven through an `Asserted` env/heap fact stays silent (the
            // phpdoc contract check below still accepts it).
            if let Some((value, provenance, strat)) = resolved
                && strat == Stratum::Verified
                && is_type_error(cx, ty, &value)
                && !object_world_guard_blind(in_descent, ty, &value)
            {
                out.push(cx.diagnostic(
                    arg.span.start,
                    &value,
                    Some(&provenance),
                    &decl.name,
                    &param.name,
                    ty,
                ));
                native_fired = true;
            }
            // A variable bound to a proven object (ADR-0036 heap): object-vs-type
            // definite-No (ADR-0043 stage 3). `new`/enum/const args are the direct
            // pass's job; this covers the env/heap-dependent `$x = new Foo(); f($x)`.
            // Guard-blind inside a descent (see `object_world_guard_blind`).
            if !native_fired
                && !poisoned
                && !in_descent
                && let ArgValue::Var(name) = &arg.value
                && store.is_exact(name) // No-side needs exactness (audit G1)
                && let Some(class) = store.class_of(name)
                && cx.object_is_type_error(ty, class)
            {
                out.push(cx.diagnostic(
                    arg.span.start,
                    &ArgValue::Var(name.clone()),
                    Some(&format!("holds a {}", simple_class(class))),
                    &decl.name,
                    &param.name,
                    ty,
                ));
                native_fired = true;
            }
        }

        // Only the propagation-carrier arg kinds (`$var`/`call()`) are the
        // propagation pass's to phpdoc-check; literal/array/`new` args are owned
        // by the direct pass (no double-report across the two passes).
        if !native_fired
            && matches!(arg.value, ArgValue::Var(_) | ArgValue::Call(..))
            && let Some(env_e) = &envelopes
        {
            check_phpdoc_param(
                cx,
                folder,
                env_e,
                param,
                site.file,
                decl.span.start,
                &decl.name,
                arg.span.start,
                &arg.value,
                env,
                store,
                poisoned,
                in_descent,
                out,
            );
        }
    }

    // Named arguments (`f(n: <expr>)`, Gap A): bind each to its parameter by name and
    // run the same declared-contract judgment. Owned solely by this pass for function
    // calls — the direct pass never touches named arguments — so no double-report.
    if let Some(env_e) = &envelopes {
        check_named_phpdoc_params(
            cx,
            folder,
            env_e,
            &decl.params,
            call.args.len(),
            site.file,
            decl.span.start,
            &decl.name,
            &call.named_args,
            env,
            store,
            poisoned,
            in_descent,
            out,
        );
    }
}

/// Attempt an interprocedural binding descent into a same-project function. Returns
/// the callee's return-fact summary (ADR-0057 amendment T0), if one was computed.
fn try_descend_function(
    cx: &Cx,
    folder: &mut dyn Folder,
    call: &CallExpr,
    env: &HashMap<String, Known>,
    poisoned: bool,
    descent: Option<&mut Descent<'_>>,
    out: &mut Vec<Diagnostic>,
) -> Option<ReturnSummary> {
    let site = cx.resolve_user_fn(call)?;
    let decl = cx.fn_decl(site);
    let (callee_file, callee_scope) = cx.fn_scope(site)?;
    let arg_values: Vec<&ArgValue> = call.args.iter().map(|a| &a.value).collect();
    descend(
        cx,
        folder,
        &decl.params,
        callee_file,
        callee_scope,
        &decl.fqn,
        &decl.name,
        None,
        &arg_values,
        call.span.start,
        &[],
        env,
        poisoned,
        descent,
        out,
    )
}

/// The T0 binding descent reached from **value position** (issue #60): resolve a
/// project function by its unique simple name and compute its [`ReturnSummary`]
/// for these argument values. This is what makes `dumpType(greet(2, "World"))`,
/// `takesInt(g(1))` and `$x = f(g(1))` see the same summary the assignment form
/// `$x = greet(2, "World")` always saw — the machinery is [`descend`] verbatim,
/// only the entry point differs.
///
/// # Name resolution is the `resolve_const_fn` precedent
///
/// An [`ArgValue::Call`] carries the call's **simple name only** (lowering takes
/// the identifier's last segment; no [`NameRef`] survives into the value IR), so
/// resolution here is `unique_fn_by_simple` — exactly the rule the zero-argument
/// `resolve_const_fn` value lane has always used. A project with two same-named
/// functions in different namespaces declines (the statement-level descent, which
/// has the full `NameRef`, still resolves those). Widening this would mean carrying
/// the resolved FQN in the value IR — a deliberate non-goal.
///
/// # Recursion discipline
///
/// The caller's `descent` MUST be threaded whenever one is live: the on-stack
/// binding-key guard is what turns mutual recursion (`f` calling `g` calling `f`)
/// into a bounded decline instead of an unbounded tree of fresh stacks. A `None`
/// here is only correct at a **plain-pass** entry (the dump surface and the
/// propagated-argument check, both `descent.is_none()`-gated), where the fresh
/// tree is the same shape `try_descend_function` has always created. Expression
/// nesting across such trees is bounded by the source's own nesting depth — each
/// level is one bounded tree, never a loop.
#[allow(clippy::too_many_arguments)]
fn project_call_summary(
    cx: &Cx,
    folder: &mut dyn Folder,
    name: &str,
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    poisoned: bool,
    span_start: u32,
    descent: Option<&mut Descent<'_>>,
    out: &mut Vec<Diagnostic>,
) -> Option<ReturnSummary> {
    let site = value_lane_fn_site(cx, folder, name)?;
    let decl = cx.fn_decl(site);
    let (callee_file, callee_scope) = cx.fn_scope(site)?;
    let arg_values: Vec<&ArgValue> = args.iter().collect();
    descend(
        cx,
        folder,
        &decl.params,
        callee_file,
        callee_scope,
        &decl.fqn,
        &decl.name,
        None,
        &arg_values,
        span_start,
        &[],
        env,
        poisoned,
        descent,
        out,
    )
}

/// The project function a **value-position** simple name may be trusted to mean
/// (issue #60) — `unique_fn_by_simple` hardened against the two ways a written
/// simple name can target a *different* function at runtime:
///
/// * **A conditional declaration** (the `function_exists`-guarded polyfill shape,
///   ADR-0049 A2i): which body binds is a load-order fact, so a summary from this
///   body could describe a function the runtime never defined. Declined — the same
///   re-damming instinct the arity check applies to conditional targets.
/// * **A homonym of a runtime function**: for a namespaced project function the
///   unqualified call outside its namespace falls back to the RUNTIME function
///   (and the value IR does not carry the caller's qualification); for a *global*
///   one the program could not even have loaded (a fatal redeclaration), so there
///   is no runtime behavior to speak for. Both decline — the same posture the
///   ADR-0061 rule seam takes on a shadowed builtin, pinned by
///   `a_project_function_shadowing_the_name_declines`. The runtime is asked three
///   ways, any positive answer declining: the boot-surface reflect oracle, a
///   reflected builtin return type, and (folderless — the playground) the static
///   catalog standing in for the common builtins.
///
/// What this deliberately does NOT close: a `use function … as …` alias shadowing
/// a same-named project function at one call site. The written simple name is all
/// the value IR carries (the alias residue is shared verbatim with
/// `resolve_const_fn`, which has always resolved this way); closing it means
/// carrying the resolved FQN in [`ArgValue::Call`] — a follow-up.
fn value_lane_fn_site(cx: &Cx, folder: &mut dyn Folder, name: &str) -> Option<Site> {
    let site = cx.index.unique_fn_by_simple(name)?;
    let decl = cx.fn_decl(site);
    if decl.conditional {
        return None;
    }
    let runtime_knows = matches!(folder.boot_surface_function(name), Some(true))
        || folder.builtin_return_type(name).is_some()
        || steins_catalog::foldable(name)
        || steins_catalog::effect_labels(name).is_some();
    if runtime_knows {
        return None;
    }
    Some(site)
}

/// [`project_call_summary`] narrowed to what a **binding** can consume (issue #60):
/// a `Singleton` summary as the concrete [`ArgValue`] it names, with the summary's
/// stratum. `None` for anything else — a non-call, a zero-argument call (that is
/// `resolve_const_fn`'s lane, already tried by `resolve_literal`), an abstract or
/// absent summary. A non-`Singleton` fact (say `positive-int`) is real knowledge,
/// but a bound parameter seeds from a concrete value; carrying abstract facts into
/// bindings is a documented ceiling, not an oversight.
#[allow(clippy::too_many_arguments)]
fn nested_call_singleton(
    cx: &Cx,
    folder: &mut dyn Folder,
    value: &ArgValue,
    env: &HashMap<String, Known>,
    poisoned: bool,
    span_start: u32,
    descent: Option<&mut Descent<'_>>,
    out: &mut Vec<Diagnostic>,
) -> Option<(ArgValue, Stratum)> {
    let ArgValue::Call(name, cargs) = value else { return None };
    if cargs.is_empty() {
        return None;
    }
    let summary =
        project_call_summary(cx, folder, name, cargs, env, poisoned, span_start, descent, out)?;
    let sv = summary.value?;
    let Fact::Singleton(v) = &sv.fact else { return None };
    Some((arg_of_val(v), sv.stratum))
}

/// Outcome of a `$fn(...)` variable call (issue #128): the return-fact summary
/// and optional declared return arms for the assignment floor.
struct VarCallOutcome {
    summary: Option<ReturnSummary>,
    return_arms: Option<Vec<ContractArm>>,
}

/// Handle a `$fn(...)` variable call (ADR-0033): resolve the callee variable
/// against the env. A proven closure value → argument check against the closure's
/// params + binding descent into the closure scope (with the capture snapshot
/// seeded); a proven `Singleton(Str)` → resolve as a function name through the
/// normal function path. An unresolved `$fn` does nothing (opaque; the effects
/// pass taints exhaustiveness separately).
///
/// Returns the callee's [`ReturnSummary`] when one was computed (issue #128), so
/// `$x = $fn(...)` rebinds on the same rungs as free functions and methods.
#[allow(clippy::too_many_arguments)]
fn handle_var_call(
    cx: &Cx,
    folder: &mut dyn Folder,
    scope: &Scope,
    name: &str,
    call: &CallExpr,
    env: &HashMap<String, Known>,
    descent: Option<&mut Descent<'_>>,
    out: &mut Vec<Diagnostic>,
) -> VarCallOutcome {
    let empty = VarCallOutcome { summary: None, return_arms: None };
    if scope.poisoned {
        return empty;
    }
    let Some(known) = env.get(name) else { return empty };

    // 1. Proven closure value → check args + descend into the closure scope.
    if let Some(cv) = &known.closure {
        return match &cv.target {
            ClosureTarget::Scope(def_offset) => {
                let Some(callee_scope) = cx.closure_scope(*def_offset) else {
                    return empty;
                };
                // Declared return floor first — same rung free functions/methods keep
                // when named/spread refuse binding descent (issue #128 review).
                let return_arms = closure_return_arms(cx, callee_scope);
                // Argument type check at the `$fn(...)` site (mirrors the direct /
                // propagated check for named calls, which never see a variable call).
                check_callable_args(
                    cx,
                    folder,
                    scope.poisoned,
                    descent.is_some(),
                    &callee_scope.params,
                    "closure",
                    call,
                    env,
                    out,
                );
                // Named/spread: no positional binding map — keep arms, skip summary.
                if !call.positional_only {
                    return VarCallOutcome { summary: None, return_arms };
                }
                let display = format!("closure (defined on line {})", cv.def_line);
                let arg_values: Vec<&ArgValue> = call.args.iter().map(|a| &a.value).collect();
                let summary = descend(
                    cx,
                    folder,
                    &callee_scope.params,
                    cx.cur,
                    callee_scope,
                    &format!("closure@{def_offset}"),
                    &display,
                    None,
                    &arg_values,
                    call.span.start,
                    &cv.captures,
                    env,
                    scope.poisoned,
                    descent,
                    out,
                );
                VarCallOutcome { summary, return_arms }
            }
            ClosureTarget::Named(nameref) => {
                dispatch_named_callable(cx, folder, scope.poisoned, nameref, call, env, descent, out)
            }
        };
    }

    // 2. Proven string value → resolve as a function name (`$fn = 'strtolower';`).
    // Named/spread still route through `dispatch_named_callable` so the declared
    // return floor is kept when binding refuses (issue #128 review) — same rung as
    // local closures and first-class callables.
    if let Some(ArgValue::Str(s)) = known.singleton() {
        let nameref = NameRef { raw: s.clone(), kind: RefKind::Unqualified, offset: call.span.start };
        return dispatch_named_callable(cx, folder, scope.poisoned, &nameref, call, env, descent, out);
    }
    empty
}

/// Declared-return contract arms of a closure scope (issue #128): the native
/// `: R` member list refined by the scope's adopted-docblock `@return` — the
/// same [`refine_contract_arms`] composition (and so the same native-vs-phpdoc
/// precedence: phpdoc refines *within* the runtime-enforced native envelope,
/// never past it) as [`fn_return_arms`]. Class arms in the `@return` resolve in
/// the closure's own file/namespace, at its definition offset.
fn closure_return_arms(cx: &Cx, callee_scope: &Scope) -> Option<Vec<ContractArm>> {
    let native: Vec<ContractTy> =
        callee_scope.ret_ty.as_ref().map(native_arms).unwrap_or_default();
    let phpdoc = parse_envelopes(callee_scope.docblock.as_deref()).and_then(|e| e.ret);
    let off = match &callee_scope.owner {
        ScopeOwner::Closure { def_offset } => *def_offset,
        _ => 0,
    };
    let resolve = |n: &str| {
        cx.resolve_pclass(cx.cur, off, n).trim_start_matches('\\').to_ascii_lowercase()
    };
    refine_contract_arms(&native, phpdoc.as_ref(), &resolve)
}

/// Dispatch a `$fn(...)` call whose target is a named free function (a first-class
/// callable or a proven string callable, ADR-0033): argument type check against the
/// resolved function's params, then normal binding descent.
#[allow(clippy::too_many_arguments)]
fn dispatch_named_callable(
    cx: &Cx,
    folder: &mut dyn Folder,
    poisoned: bool,
    nameref: &NameRef,
    call: &CallExpr,
    env: &HashMap<String, Known>,
    descent: Option<&mut Descent<'_>>,
    out: &mut Vec<Diagnostic>,
) -> VarCallOutcome {
    let synth = synth_function_call(call, nameref);
    let return_arms = cx.resolve_user_fn_any(&synth).and_then(|site| fn_return_arms(cx, site));
    if let Some(site) = cx.resolve_user_fn(&synth) {
        let decl = cx.fn_decl(site);
        check_callable_args(
            cx, folder, poisoned, descent.is_some(), &decl.params, &decl.name, call, env, out,
        );
    }
    let summary = try_descend_function(cx, folder, &synth, env, poisoned, descent, out);
    VarCallOutcome { summary, return_arms }
}

/// A synthetic named-function [`CallExpr`] from a `$fn(...)` variable call and a
/// resolved function reference, so the normal function-resolution/descent path can
/// consume it (ADR-0033 first-class-callable / string-callable dispatch).
fn synth_function_call(call: &CallExpr, nameref: &NameRef) -> CallExpr {
    CallExpr {
        callee: Some(nameref.raw.clone()),
        callee_ref: Some(nameref.clone()),
        receiver: Callee::Function(nameref.raw.clone()),
        args: call.args.clone(),
        named_args: call.named_args.clone(),
        has_spread: call.has_spread,
        positional_only: call.positional_only,
        span: call.span,
        arg_conds: call.arg_conds.clone(),
    }
}

/// Argument type check for a `$fn(...)` call at the call site (ADR-0033): each
/// proven argument (literal, or resolved `$var`/fold) is checked against the
/// callable's corresponding native param type, firing `type.argument-mismatch` on
/// a proven coercive TypeError — the variable-call analogue of the direct /
/// propagated check (which never see a variable call). `display` names the callee
/// in the message (`"closure"` or the resolved function name).
#[allow(clippy::too_many_arguments)]
fn check_callable_args(
    cx: &Cx,
    folder: &mut dyn Folder,
    poisoned: bool,
    in_descent: bool,
    params: &[Param],
    display: &str,
    call: &CallExpr,
    env: &HashMap<String, Known>,
    out: &mut Vec<Diagnostic>,
) {
    for (i, arg) in call.args.iter().enumerate() {
        let Some(param) = params.get(i) else { break };
        if param.variadic {
            break;
        }
        if param.by_ref {
            continue;
        }
        let Some(ty) = param.ty.as_ref() else { continue };
        // Resolve the argument to a proven value (literal directly; `$var`/fold via
        // the env). Provenance names the variable/fold source where applicable.
        // Stratum rides with the resolution (issue #127 review) — never a syntactic
        // re-read that would launder an Asserted fold into Verified.
        let resolved: Option<(ArgValue, Option<String>, Stratum)> = match &arg.value {
            v if v.is_literal() => Some((v.clone(), None, Stratum::Verified)),
            ArgValue::Var(vn) if !poisoned => env.get(vn).and_then(|k| {
                let v = k.singleton()?;
                let prov = match &k.bound {
                    Some(b) => format!("from ${vn}, {b}"),
                    None => format!("from ${vn}, assigned at line {}", k.line),
                };
                Some((v, Some(prov), k.stratum))
            }),
            ArgValue::Call(cn, cargs) => cx
                .try_fold_emit(cn, cargs, env, poisoned, folder, out)
                .map(|(lit, prov, strat)| (lit, Some(prov), strat)),
            // A proven object (`new` / enum case) or resolved class constant
            // (ADR-0043 stage 3); env-free, `self`/`parent` unavailable here.
            _ => cx
                .resolve_static_value(&arg.value, None)
                .map(|v| (v, None, Stratum::Verified)),
        };
        // Proof-layer consumption rule (ADR-0052 §5): silent on an `Asserted`
        // premise (no store here — a prop-fetch arg never resolves to a fire).
        if let Some((value, provenance, strat)) = resolved
            && strat == Stratum::Verified
            && is_type_error(cx, ty, &value)
            && !object_world_guard_blind(in_descent, ty, &value)
        {
            out.push(cx.diagnostic(
                arg.span.start,
                &value,
                provenance.as_deref(),
                display,
                &param.name,
                ty,
            ));
        }
    }
}

/// Interprocedural argument-binding descent into a resolved callee body. Returns the
/// callee's [`ReturnSummary`] (ADR-0057 amendment T0) when one was computed — the
/// join over its returning exits, memoized under the binding key — or `None` when no
/// descent ran (unbound, by-ref, depth-exhausted, recursive) or no summarizable exit
/// remained. The caller consumes it as the call-result value floor above the arms.
#[allow(clippy::too_many_arguments)]
fn descend(
    cx: &Cx,
    folder: &mut dyn Folder,
    params: &[Param],
    callee_file: usize,
    callee_scope: &Scope,
    key_name: &str,
    display_name: &str,
    body_this_exact: Option<String>,
    // The call's positional argument values + its span start (for the provenance
    // line). Taken apart rather than as a `&CallExpr` (issue #60): a nested call in
    // argument position exists only as an `ArgValue::Call` — no `CallExpr` is ever
    // lowered for it — and these two pieces are all the descent ever used.
    args: &[&ArgValue],
    span_start: u32,
    captures: &[(String, Fact, Stratum)],
    env: &HashMap<String, Known>,
    poisoned: bool,
    mut descent: Option<&mut Descent<'_>>,
    out: &mut Vec<Diagnostic>,
) -> Option<ReturnSummary> {
    if callee_scope.poisoned {
        return None;
    }

    // Resolve each positional argument to a literal and try to bind it (using
    // the *caller's* env, strict mode, and folding). Each binding carries the arg's
    // trust stratum (ADR-0052 §5): the seeded callee param inherits it, so an
    // `Asserted` argument narrows into the descent without laundering to `Verified`.
    let mut bound: Vec<(String, ArgValue, Stratum)> = Vec::new();
    let mut render_args: Vec<ArgValue> = Vec::new();
    for (i, arg_value) in args.iter().enumerate() {
        let Some(param) = params.get(i) else { break };
        if param.variadic {
            break;
        }
        // Direct resolution first; when it declines and the argument is itself a
        // project call, the T0 machinery answers for its own argument position
        // (issue #60): `f(g(1))` binds `g(1)`'s Singleton summary. The CURRENT
        // descent is threaded (reborrowed), so the on-stack recursion guard and
        // `MAX_BINDING_DEPTH` bound the nested resolution exactly as they bound a
        // statement-level chain; the nested walk emits through the same `out` a
        // statement-level descent would.
        // Thread the live descent into literal resolution so a foldable builtin
        // whose arg is a project call (`strtoupper(g($x))` inside a callee)
        // reuses the on-stack guard (issue #127). Project-call-only args still
        // fall through to `nested_call_singleton` with the real `out`.
        let (value, strat) = match cx.resolve_literal_under(
            arg_value,
            env,
            poisoned,
            folder,
            descent.as_deref_mut(),
            Some(&mut *out),
        ) {
            // Stratum comes from the fold/env path (includes nested project-call
            // Asserted summaries — issue #127 review). Nested project-call descents
            // for fold args emit through `out` so binding-specific findings are not
            // discarded.
            Some(vs) => vs,
            None => {
                let Some(vs) = nested_call_singleton(
                    cx,
                    folder,
                    arg_value,
                    env,
                    poisoned,
                    span_start,
                    descent.as_deref_mut(),
                    out,
                ) else {
                    continue;
                };
                vs
            }
        };
        render_args.push(value.clone());
        if param.by_ref {
            return None;
        }
        let Some(ty) = param.ty.as_ref() else {
            bound.push((param.name.clone(), value, strat));
            continue;
        };
        let coerced = coerce_into_param(cx, ty, &value)?;
        bound.push((param.name.clone(), coerced, strat));
    }

    // A closure with captures descends even with no bound args (the capture
    // snapshot drives the body); a plain function needs at least one bound arg.
    // Zero-argument factories do NOT descend in T0 (ADR-0057 §3 / A5, deferred to
    // T2's emission-suppressed summary-only walk) — they take the arm floor.
    if bound.is_empty() && captures.is_empty() {
        return None;
    }

    // The binding key incorporates the captured snapshot so two calls of the same
    // closure with different snapshots memoize distinctly (adversarial #1). Each
    // binding's stratum is part of the key (issue #128 review): a Verified summary
    // for `$f('hi')` must not replay as Verified when the next call is `$f($u)` with
    // `$u` Asserted Singleton('hi') — otherwise the Asserted claim launders into a
    // proof premise through the memo.
    //
    // ADR-0075 §2.1: a method body reached through `resolve_exact` is keyed by
    // declaring FQN (`Base::m`), but two exact receivers (`Sub1`, `Sub2`) can
    // inherit the same body while `$this->hook()` inside it dispatches differently.
    // When `body_this_exact` is `Some`, a `this:` pseudo-binding carries that
    // receiver so the memo never replays one receiver's value (or emissions) for
    // the other. Guarded resolutions pass `None` and key exactly as before — a
    // final/private body's inner dispatch is a pure function of its declaring class.
    let mut key_binding: Vec<(String, ArgValue, Stratum)> = bound
        .iter()
        .map(|(n, v, s)| (n.clone(), v.clone(), *s))
        .collect();
    for (name, fact, strat) in captures {
        key_binding.push((format!("use:{name}"), arg_of_fact_key(fact), *strat));
    }
    if let Some(exact) = &body_this_exact {
        // Exact receiver is a runtime-proven identity — Verified.
        key_binding.push((
            "this:".to_owned(),
            ArgValue::Str(exact.clone()),
            Stratum::Verified,
        ));
    }
    key_binding.sort_by(|a, b| a.0.cmp(&b.0));
    let key: BindingKey = (key_name.to_owned(), key_binding);

    // Provenance names the *first* binding site; a nested descent inherits it.
    // When the call crosses files, the site names the caller's file.
    let cross = cx.cur != callee_file;
    let new_provenance;
    let (provenance, next_depth): (&str, usize) = match &descent {
        Some(d) => (d.provenance, d.depth + 1),
        None => {
            let line = cx.tree().position(span_start).line;
            let render = render_call(display_name, &render_args);
            new_provenance = if cross {
                format!("bound at {render} call at {} line {line}", cx.path())
            } else {
                format!("bound at {render} call on line {line}")
            };
            (&new_provenance, 1)
        }
    };

    // Depth exhaustion widens, never lies (ADR-0057 §3 / A5): no descent ⇒ no
    // summary ⇒ the caller keeps the arm floor.
    if next_depth > MAX_BINDING_DEPTH {
        return None;
    }

    // Bound params are always resolved literals/arrays, so `singleton_fact`
    // succeeds; a value that somehow fails conversion is simply left unbound
    // (the callee param stays unknown — sound).
    let mut bound_env: HashMap<String, Known> = bound
        .into_iter()
        .filter_map(|(name, value, strat)| {
            singleton_fact(&value, cx.php_minor)
                .map(|fact| (name, Known::value_strat(fact, 0, Some(provenance.to_owned()), strat)))
        })
        .collect();
    // Closure captures (ADR-0033): the by-value snapshot seeds the initial env,
    // UNDER the param bindings (a param of the same name shadows a capture, PHP
    // semantics — `use ($x)` is ignored if `$x` is also a parameter). The capture's
    // snapshotted stratum is restored so an Asserted claim does not launder to
    // Verified in the summary rebound to the caller (issue #128 review).
    for (name, fact, strat) in captures {
        bound_env.entry(name.clone()).or_insert_with(|| {
            Known::value_strat(fact.clone(), 0, Some(provenance.to_owned()), *strat)
        });
    }

    let child_cx = cx.at(callee_file);
    match descent {
        Some(d) => {
            // Recursion (ADR-0057 §3 / A5): the key is already on the descent stack;
            // the walk is suppressed and no summary exists yet — `None` (arm floor).
            // The enclosing exit degrades to the floor via A3 rather than dying.
            if d.stack.contains(&key) {
                return None;
            }
            // Memo hit: REPLAY the cached summary (a value, not a suppression bit) —
            // no re-walk, so no re-emitted findings. Legitimate caching (§3): the
            // summary is a pure function of the key's entry state.
            if let Some(cached) = d.memo.get(&key) {
                return cached.clone();
            }
            d.stack.push(key.clone());
            let child = Descent { provenance, depth: next_depth, stack: d.stack, memo: d.memo };
            let mut exits: Vec<ExitContribution> = Vec::new();
            analyze_scope(
                &child_cx,
                folder,
                callee_scope,
                bound_env,
                Store::default(),
                body_this_exact,
                Some(child),
                None,
                None,
                Some(&mut exits),
                out,
            );
            d.stack.pop();
            let summary = join_summary(&child_cx, callee_scope, &exits);
            d.memo.insert(key, summary.clone());
            summary
        }
        None => {
            let mut stack: Vec<BindingKey> = vec![key.clone()];
            let mut memo: HashMap<BindingKey, Option<ReturnSummary>> = HashMap::new();
            let child = Descent { provenance, depth: next_depth, stack: &mut stack, memo: &mut memo };
            let mut exits: Vec<ExitContribution> = Vec::new();
            analyze_scope(
                &child_cx,
                folder,
                callee_scope,
                bound_env,
                Store::default(),
                body_this_exact,
                Some(child),
                None,
                None,
                Some(&mut exits),
                out,
            );
            join_summary(&child_cx, callee_scope, &exits)
        }
    }
}

/// Build the [`ReturnSummary`] from a callee's collected returning-exit contributions
/// (ADR-0057 amendment T0): join the value facts (A1), a factless exit contributing
/// the declared value floor (A3), the stratum `min` over exits (A4). The heap
/// component (T1) is always `None` here. `None` when nothing summarizable remained.
fn join_summary(
    cx: &Cx,
    callee_scope: &Scope,
    exits: &[ExitContribution],
) -> Option<ReturnSummary> {
    // Generators: the call result is a Generator, not the value of `return`
    // after `yield` (ADR-0057 §5). Refuse the whole value summary.
    if callee_scope.is_generator {
        return None;
    }
    let ret = cx.scope_return(callee_scope).map(|(ty, _)| ty);
    // A written return hint Steins cannot lower (`: object`, `: array`, `: void`,
    // `: never`, …) leaves `scope_return` as `None`, so the A2 native-oracle arms
    // are empty and `native_violates` cannot drop boundary TypeErrors
    // (`return null` under `: object`). Refuse the whole value summary rather than
    // rebind an uncheckable exit as a Singleton premise (ADR-0075 review).
    if ret.is_none() && callee_scope.ret_hint.is_some() {
        return None;
    }
    let floor = ret.and_then(native_value_floor);
    // The declared return type is a CONVERSION boundary, not just an envelope
    // (the #48 family, return edition): PHP hands the caller what the boundary
    // converts, so `return 1` under `: float` crosses as `1.0`, never as the
    // callee's raw int — an int-based summary there is a wrong value, the exact
    // FP class #48 closed for property writes and promoted params. A2 already
    // dropped the *violating* exits at collection; this converts the admitted
    // ones, and an admitted-but-unconvertible fact degrades to the declared
    // floor (the A3 side — wider, never wrong).
    let coerced: Vec<ExitContribution> = exits
        .iter()
        .map(|e| match (e, ret) {
            (ExitContribution::Fact(f, s), Some(ty)) => {
                match coerce_fact_to_native(ty, f.clone()) {
                    Some(cf) => ExitContribution::Fact(cf, *s),
                    None => ExitContribution::Floor,
                }
            }
            (ExitContribution::Fact(f, s), None) => ExitContribution::Fact(f.clone(), *s),
            (ExitContribution::Floor, _) => ExitContribution::Floor,
        })
        .collect();
    let (fact, stratum) = join_exits(&coerced, floor.as_ref())?;
    Some(ReturnSummary { value: Some(SummaryValue { fact, stratum }), heap: None })
}

/// Join a callee's returning-exit contributions into the value-domain summary fact
/// (ADR-0057 A1/A3/A4). Each `Fact` exit joins by the existing value-domain join;
/// each `Floor` exit contributes the declared value floor (a `None` floor — an object
/// or mixed-base return — kills the whole value summary, there being no representable
/// degraded top). Stratum is `min` over exits (N2). An empty exit set (no returning
/// exit, or every exit dropped by A2) or an unrepresentable join (mixed bases) yields
/// `None` — arm floor.
fn join_exits(exits: &[ExitContribution], floor: Option<&Fact>) -> Option<(Fact, Stratum)> {
    if exits.is_empty() {
        return None;
    }
    let mut acc: Option<Fact> = None;
    let mut stratum = Stratum::Verified;
    for e in exits {
        let (fact, s) = match e {
            ExitContribution::Fact(f, s) => (f.clone(), *s),
            ExitContribution::Floor => (floor?.clone(), Stratum::Verified),
        };
        stratum = stratum.min(s);
        acc = Some(match acc {
            None => fact,
            Some(a) => a.join(&fact)?,
        });
    }
    Some((acc?, stratum))
}

/// The declared return type's value-domain FLOOR as a single [`Fact`] — the sound top
/// within the envelope a factless exit contributes (ADR-0057 A3). Representable only
/// when every native member shares ONE scalar base (`int`, `?int`); a union of bases,
/// an object, or a bool-literal return has no single-base value floor (`None`).
fn native_value_floor(ty: &NativeType) -> Option<Fact> {
    let mut base: Option<Base> = None;
    for m in &ty.members {
        let b = match m {
            TypeMember::Scalar(ScalarType::Int) => Base::Int,
            TypeMember::Scalar(ScalarType::Float) => Base::Float,
            TypeMember::Scalar(ScalarType::String) => Base::String,
            TypeMember::Scalar(ScalarType::Bool) => Base::Bool,
            _ => return None,
        };
        match base {
            None => base = Some(b),
            Some(x) if x == b => {}
            Some(_) => return None,
        }
    }
    base.map(|base| Fact::General { base, nullable: ty.nullable })
}

/// The returned expression's best value-domain fact and stratum at a returning exit
/// (ADR-0057 amendment T0): a bare variable's env fact (covering the assert-narrowed
/// `positive-int` case), else a literal/const/foldable `Singleton`, else a depth-1
/// property fact. `None` for any exit the value domain cannot spell (an object, an
/// unresolved call, an array offset) — a factless exit (A3).
fn return_value_fact(
    w: &WalkCx,
    folder: &mut dyn Folder,
    value: &ArgValue,
    env: &HashMap<String, Known>,
    store: &Store,
) -> Option<(Fact, Stratum)> {
    let poisoned = w.scope.poisoned;
    if let ArgValue::Var(name) = value
        && let Some(known) = env.get(name)
        && let Some(fact) = known.fact.clone()
    {
        return Some((fact, known.stratum));
    }
    // Stratum from the resolution itself (issue #127 review): a fold over an
    // Asserted project-call summary stays Asserted — never re-read from the
    // syntactic tree. Scratch sink: findings for nested fold args are owned by the
    // return-check / assignment paths that resolve with a real `out`.
    if let Some((lit, strat)) = w.cx.resolve_literal_strat(value, env, poisoned, folder)
        && let Some(fact) = singleton_fact(&lit, w.cx.php_minor)
    {
        return Some((fact, strat));
    }
    if let ArgValue::PropFetch { var, prop } = value
        && !poisoned
        && let Some(fact) = store.prop_fact(var, prop).cloned()
    {
        return Some((fact, store.prop_stratum(var, prop)));
    }
    None
}

/// Whether a summary value fact is precise enough to bind as the call-result's value
/// (ADR-0057 A3): a `Singleton`/`OneOf`/`Refined` fact is strictly more than the
/// declared arm floor and binds; a bare `General{base}` (the degraded join) carries
/// nothing beyond the arms — the arm floor stands, observably identical to no summary.
fn summary_binds(fact: &Fact) -> bool {
    matches!(fact, Fact::Singleton(_) | Fact::OneOf(_) | Fact::Refined { .. })
}

// ---------------------------------------------------------------------------
// Class-world method resolution (ADR-0001 sound dispatch), project-wide.
// ---------------------------------------------------------------------------

/// A method resolved through a project inheritance chain.
struct ResolvedMethod<'a> {
    method: &'a MethodDecl,
    declaring_class: &'a ClassDecl,
    class_file: usize,
}

/// The outcome of walking a class's inheritance chain for a method.
enum Resolution<'a> {
    Found(ResolvedMethod<'a>),
    NotFoundChainComplete,
    Unknown,
}

/// Walk `start_fqn`'s project inheritance chain for a concrete `method`.
fn resolve_in_chain<'a>(cx: &Cx<'a>, start_fqn: &str, method: &str) -> Resolution<'a> {
    let mut cur = start_fqn.to_owned();
    let mut seen: HashSet<String> = HashSet::new();
    loop {
        if !seen.insert(cur.to_ascii_lowercase()) {
            return Resolution::Unknown;
        }
        let Some((cfile, cd)) = cx.find_class(&cur) else {
            return Resolution::Unknown; // chain leaves the project
        };
        if cd.uses_traits {
            return Resolution::Unknown;
        }
        if let Some(m) = cd.methods.iter().find(|m| m.name.eq_ignore_ascii_case(method)) {
            return if m.is_abstract {
                Resolution::Unknown
            } else {
                Resolution::Found(ResolvedMethod { method: m, declaring_class: cd, class_file: cfile })
            };
        }
        match &cd.parent {
            None => return Resolution::NotFoundChainComplete,
            Some(pref) => cur = cx.units[cfile].tree.resolve_class_fqn(pref),
        }
    }
}

/// A resolved call target.
struct CallTarget<'a> {
    method: &'a MethodDecl,
    declaring_class: &'a ClassDecl,
    class_file: usize,
    this_exact: Option<String>,
}

/// Resolve a method/static/constructor `receiver` to a project target.
fn resolve_call_target<'a>(
    cx: &Cx<'a>,
    receiver: &Callee,
    store: &Store,
    this_exact: Option<&str>,
    enclosing_class: Option<&str>,
    poisoned: bool,
) -> Option<CallTarget<'a>> {
    match receiver {
        Callee::Construct { class } => {
            let fqn = cx.class_fqn(class);
            resolve_exact(cx, &fqn, "__construct", enclosing_class, Some(fqn.clone()))
        }
        Callee::Method { receiver: Receiver::New(class), method, .. } => {
            let fqn = cx.class_fqn(class);
            resolve_exact(cx, &fqn, method, enclosing_class, Some(fqn.clone()))
        }
        Callee::Method { receiver: Receiver::Var(v), method, .. } => {
            if poisoned {
                return None;
            }
            let obj = store.obj_of(v)?;
            let class = obj.class.clone();
            if obj.class_exact {
                // An allocation-proven receiver (`$x = new Foo(); $x->m()`) dispatches
                // exactly — the precise dispatch.
                resolve_exact(cx, &class, method, enclosing_class, Some(class.clone()))
            } else {
                // A lower-bound receiver — a laundered `$this` alias (`$u = $this`) or
                // `clone $this` — is NOT exact (audit G1): fall back to the same
                // final/private override guard `Receiver::This` uses, so an overridable
                // method on it never resolves to the enclosing declaration.
                resolve_guarded(cx, &class, method, enclosing_class)
            }
        }
        Callee::Method { receiver: Receiver::This, method, .. } => {
            let enclosing = enclosing_class?;
            match this_exact {
                Some(exact) => resolve_exact(cx, exact, method, enclosing_class, Some(exact.to_owned())),
                None => resolve_guarded(cx, enclosing, method, enclosing_class),
            }
        }
        Callee::Static { class: StaticClass::SelfKw, method } => {
            let enclosing = enclosing_class?;
            resolve_guarded(cx, enclosing, method, enclosing_class)
        }
        Callee::Static { class: StaticClass::Parent, method } => {
            let parent = cx.parent_fqn(enclosing_class?)?;
            resolve_static_named(cx, &parent, method, enclosing_class)
        }
        Callee::Static { class: StaticClass::Named(name), method } => {
            let fqn = cx.class_fqn(name);
            resolve_static_named(cx, &fqn, method, enclosing_class)
        }
        Callee::Static { class: StaticClass::Static, .. } => None,
        // A depth-1 property-fetch receiver is never a dispatch target (ADR-0052 §7):
        // the method is not resolved from the heap object — silent, like `Dynamic`.
        Callee::Method { receiver: Receiver::Prop { .. }, .. } => None,
        Callee::Function(_) | Callee::DynamicVar(_) | Callee::Dynamic => None,
    }
}

/// Resolve an exact-receiver instance/constructor call (no override guard).
fn resolve_exact<'a>(
    cx: &Cx<'a>,
    class: &str,
    method: &str,
    enclosing_class: Option<&str>,
    this_exact: Option<String>,
) -> Option<CallTarget<'a>> {
    match resolve_in_chain(cx, class, method) {
        Resolution::Found(r) if !private_blocked(&r, enclosing_class) => Some(CallTarget {
            method: r.method,
            declaring_class: r.declaring_class,
            class_file: r.class_file,
            this_exact,
        }),
        _ => None,
    }
}

/// Resolve a `$this->`/`self::` call under the override guard.
fn resolve_guarded<'a>(
    cx: &Cx<'a>,
    class: &str,
    method: &str,
    enclosing_class: Option<&str>,
) -> Option<CallTarget<'a>> {
    let Resolution::Found(r) = resolve_in_chain(cx, class, method) else { return None };
    if private_blocked(&r, enclosing_class) {
        return None;
    }
    let declaring_final = r.declaring_class.is_final;
    let final_or_private =
        r.method.is_final || r.method.visibility == Visibility::Private || declaring_final;
    if !final_or_private {
        return None;
    }
    Some(CallTarget {
        method: r.method,
        declaring_class: r.declaring_class,
        class_file: r.class_file,
        this_exact: None,
    })
}

/// Resolve an explicit `Foo::m()` / `parent::m()` static call (exact).
fn resolve_static_named<'a>(
    cx: &Cx<'a>,
    class: &str,
    method: &str,
    enclosing_class: Option<&str>,
) -> Option<CallTarget<'a>> {
    let Resolution::Found(r) = resolve_in_chain(cx, class, method) else { return None };
    if private_blocked(&r, enclosing_class) {
        return None;
    }
    if !r.method.is_static && enclosing_class.is_none() {
        return None;
    }
    Some(CallTarget {
        method: r.method,
        declaring_class: r.declaring_class,
        class_file: r.class_file,
        this_exact: None,
    })
}

/// Whether a resolved `private` method is invisible at the call site.
fn private_blocked(r: &ResolvedMethod, enclosing_class: Option<&str>) -> bool {
    r.method.visibility == Visibility::Private
        && !enclosing_class.is_some_and(|e| e.eq_ignore_ascii_case(&r.declaring_class.fqn))
}

// ---------------------------------------------------------------------------
// The finding-breadth flagship: `call.undefined-method` (ADR-0049 §4 / S2).
//
// An *absence* proof — fire only under complete closure over every place a method
// could hide. The ladder (ADR-0049 §4 + amendments A1/A2/A3/A9) is applied leg by
// leg; ANY doubt is silence (the zero-FP identity, ADR-0013). The cheap textual
// legs run first so the sidecar homonym IPC (A2ii) is reached only for a chain
// that already survived every local check.
// ---------------------------------------------------------------------------

/// Which magic fallback swallows an otherwise-undefined call, and the PHP phrasing
/// of the call kind — instance (`$recv->m()`, `__call`) vs static (`C::m()`,
/// `__callStatic`).
#[derive(Clone, Copy, PartialEq, Eq)]
enum UndefKind {
    Instance,
    Static,
}

impl UndefKind {
    /// The magic method whose presence anywhere in the chain makes the call defined.
    fn magic(self) -> &'static str {
        match self {
            UndefKind::Instance => "__call",
            UndefKind::Static => "__callStatic",
        }
    }
}

/// The receiver a `call.undefined-method` claim can rest on, after legs (a)/(l).
/// Carries the *exact* receiver class FQN and the call kind. `None` from the
/// resolver means the receiver is out of scope for S2 (silence): `$this` (A1
/// membership), an inexact/lower-bound variable, a nullsafe `?->`, a first-class
/// callable, `self`/`static`/`parent`, or any dynamic form.
fn undefined_method_receiver(
    cx: &Cx,
    call: &CallExpr,
    store: &Store,
    poisoned: bool,
) -> Option<(String, String, UndefKind)> {
    // Leg (l): the first-class-callable form `$v->m(...)` / `C::m(...)` lowers to an
    // arg-less non-positional call — it builds a Closure, it does not invoke — so it
    // is never an undefined-method site. (A named/spread call keeps `args` non-empty
    // and stays eligible: method existence is argument-shape-independent.)
    if !call.positional_only && call.args.is_empty() {
        return None;
    }
    match &call.receiver {
        Callee::Method { receiver, method, nullsafe } => {
            if *nullsafe {
                return None; // leg (l): `?->` excluded in v1.
            }
            let class = match receiver {
                // Leg (a)/A1: an exact-class receiver only. `new Foo()` is exact by
                // construction; a `$var` is exact only when the heap says so (a
                // `new`/clone-of-exact allocation, never a `$this` lower bound or a
                // laundered alias). `class_exact` is set solely by Verified-origin
                // allocation sites, so the N2 stratum requirement on the receiver
                // identity holds by construction.
                Receiver::New(name) => cx.class_fqn(name),
                Receiver::Var(v) => {
                    if poisoned {
                        return None;
                    }
                    let obj = store.obj_of(v)?;
                    if !obj.class_exact {
                        return None; // lower bound → S6's lane, not ours.
                    }
                    obj.class.clone()
                }
                // A1: `$this` is a membership fact, never exactness — silent in S2.
                Receiver::This => return None,
                // A depth-1 property-fetch receiver carries no exact-class proof for
                // absence dispatch (ADR-0052 §7) — silent, like an unknown receiver.
                Receiver::Prop { .. } => return None,
            };
            Some((class, method.clone(), UndefKind::Instance))
        }
        Callee::Static { class, method } => match class {
            // Textual, exact — no receiver proof needed. `self`/`static`/`parent`
            // stay unlowered and silent (ADR-0043 §1).
            StaticClass::Named(name) => {
                Some((cx.class_fqn(name), method.clone(), UndefKind::Static))
            }
            StaticClass::SelfKw | StaticClass::Parent | StaticClass::Static => None,
        },
        // `new C()` (no method), `$fn()`, dynamic method names → not our sites.
        Callee::Function(_)
        | Callee::Construct { .. }
        | Callee::DynamicVar(_)
        | Callee::Dynamic => None,
    }
}

/// The outcome of walking `start_fqn`'s ancestor chain for `method` under the
/// ADR-0049 §4 closure discipline (the C1 completeness standard).
enum ChainWalk {
    /// The method is absent from a fully-enumerated, obstacle-free chain: fire
    /// eligible. Carries the ordered simple class names (for the message), the
    /// ordered chain FQNs (for the A2ii homonym leg), and whether any node was
    /// declared conditionally (A2i — re-dams the claim).
    Absent { simple_chain: Vec<String>, fqns: Vec<String>, any_conditional: bool },
    /// An obstacle taints closure anywhere on the chain, or the method is present:
    /// silence (the FP-safe verdict).
    Silent,
}

/// Walk `start_fqn`'s parent chain proving the method's *absence* under complete
/// enumeration (ADR-0049 §4 (b)–(f), (j); A2i/A2iii). Interfaces are not walked:
/// a PHP interface never carries a method body, so it can never *define* the
/// method — only the `extends` (class-parent) chain can, exactly as
/// [`resolve_in_chain`] does. Any of these taints closure ⇒ `Silent`:
/// unresolvable/`Ambiguous`/builtin ancestor (leg b/f/i), a trait name or a
/// `uses_traits` node (leg e), an `is_enum` node (leg j / A3), the magic fallback
/// (`__call`/`__callStatic`, leg d), a cycle (leg b), or the method being present
/// (not undefined).
fn enumerate_method_chain(cx: &Cx, start_fqn: &str, method: &str, kind: UndefKind) -> ChainWalk {
    let magic = kind.magic();
    let mut cur = start_fqn.to_owned();
    let mut seen: HashSet<String> = HashSet::new();
    let mut simple_chain: Vec<String> = Vec::new();
    let mut fqns: Vec<String> = Vec::new();
    let mut any_conditional = false;
    loop {
        if !seen.insert(cur.to_ascii_lowercase()) {
            return ChainWalk::Silent; // cycle — closure cannot terminate soundly.
        }
        // Leg (b)/(f)/(i): every ancestor edge must resolve to a UNIQUE project
        // declaration. `find_class` returns `None` for `Absent` (a builtin/vendor-
        // unresolved ancestor — leg f, awaiting the reflect method surface, M2) and
        // for `Ambiguous` (a duplicate FQN or an alias/decl collision — leg i).
        let Some((cfile, cd)) = cx.find_class(&cur) else {
            return ChainWalk::Silent;
        };
        // Leg (j)/A3: enum methods are not lowered, so an enum chain would look
        // method-empty — Unknown until enum method lowering lands.
        if cd.is_enum {
            return ChainWalk::Silent;
        }
        // A trait name in the class-like index carries no lowered members (S1): it
        // would falsely read as "method absent". Never a method holder here.
        if cd.is_trait {
            return ChainWalk::Silent;
        }
        // Leg (e): a trait use adds methods the is-a oracle rightly ignores for
        // ancestry — Unknown until trait flattening (per-node, like resolve_in_chain).
        if cd.uses_traits {
            return ChainWalk::Silent;
        }
        // Leg (d): a magic fallback anywhere swallows the name — no error at runtime.
        if cd.methods.iter().any(|m| m.name.eq_ignore_ascii_case(magic)) {
            return ChainWalk::Silent;
        }
        // The method is present (case-insensitively) — including an abstract
        // declaration: it is defined, so the call is not undefined.
        if cd.methods.iter().any(|m| m.name.eq_ignore_ascii_case(method)) {
            return ChainWalk::Silent;
        }
        simple_chain.push(cd.name.clone());
        fqns.push(cur.clone());
        if cd.conditional {
            any_conditional = true;
        }
        match &cd.parent {
            None => {
                return ChainWalk::Absent { simple_chain, fqns, any_conditional };
            }
            Some(pref) => cur = cx.units[cfile].tree.resolve_class_fqn(pref),
        }
    }
}

/// Run the full ADR-0049 §4 ladder for one method/static call and emit
/// `call.undefined-method` iff **every** leg holds. Called only from the plain
/// per-scope pass (`descent.is_none()`) so a site is judged once, never re-emitted
/// under an interprocedural descent.
fn check_undefined_method(
    cx: &Cx,
    folder: &mut dyn Folder,
    call: &CallExpr,
    store: &Store,
    poisoned: bool,
    out: &mut Vec<Diagnostic>,
) {
    // Legs (a)/(l): identify an exact receiver and the call kind, or bail.
    let Some((class_fqn, method, kind)) = undefined_method_receiver(cx, call, store, poisoned)
    else {
        return;
    };
    // Guard-respect leg (ADR-0049 §4): a positive `method_exists($this-or-C, 'm')`
    // guard dominating this site vouched `C::m` — the programmer supplied existence
    // evidence, so stay silent even if the chain enumeration below would reach Absent
    // (a `Maybe`-verdict guard whose branch we are walking live). Exact-textual match
    // on the RESOLVED class + method (case-insensitive).
    if store.vouches_method(&class_fqn, &method) {
        return;
    }
    // A9 (global) + A2ii's honest consequence: without a live sidecar, or with a
    // monkey-patch extension loaded, the id is entirely silent (checked once, cached).
    if !folder.absence_family_available() {
        return;
    }
    // Legs (b)–(f), (j), A2i/A2iii: textual closure over the ancestor chain.
    let ChainWalk::Absent { simple_chain, fqns, any_conditional } =
        enumerate_method_chain(cx, &class_fqn, &method, kind)
    else {
        return;
    };
    // Leg A2i: a conditional declaration in the chain re-dams the claim — fire only
    // when the whole-universe dam is clear (vouch machinery is not available here).
    if any_conditional && !cx.dam.is_clear() {
        return;
    }
    // Leg (h)/A2ii: every chain FQN must be answered NOT-present by the boot-surface
    // existence oracle. A homonym (`Some(true)`) or an unanswerable query (`None` —
    // a mid-run sidecar failure) is silence.
    for fqn in &fqns {
        match folder.boot_surface_class_like(fqn) {
            Some(false) => {}
            Some(true) | None => return,
        }
    }

    // Every leg holds — a proven `Error: Call to undefined method C::m()`.
    let pos = cx.tree().position(call.span.start);
    let simple_class = simple_chain.first().map_or(class_fqn.as_str(), String::as_str);
    let chain_render = simple_chain.join(" → ");
    let message = format!(
        "call to undefined method {simple_class}::{method}() — hierarchy fully enumerated ({chain_render}), no {}",
        kind.magic(),
    );
    out.push(Diagnostic {
        id: CALL_UNDEFINED_METHOD_ID,
        path: cx.path().to_owned(),
        line: pos.line,
        column: pos.column,
        message,
        facet: None,
        fix: None,
    });
}

// ---------------------------------------------------------------------------
// The existence ids: `call.undefined-function` + `class.undefined`
// (ADR-0049 §3/§5 / S4 — the FP-risk hotspot, opened in measurement mode first).
//
// Both are DAMMED absence claims (unlike S2's method-absence, which is immune —
// PHP cannot reopen a resolved class, but eval and out-of-universe includes DO mint
// functions and classes at runtime). So a standing dam site ANYWHERE in the universe
// silences the whole slice: the include-heavy legacy monorepo stays quiet while
// dynamism-free OSS packages fire — the §10 falsifiable prediction. The shared
// ladder (any leg failing ⇒ silence, the zero-FP identity ADR-0013):
//   - a real direct call / a hard-error class position (first-class callables,
//     `$fn()`, `::class`, instanceof, catch, type-decls are §5's verified NON-findings);
//   - `absence_family_available` (A9 monkey-patch void + the no-sidecar sound subset);
//   - not a reserved dump FQN (D3 carve-out) and not a curated SAPI-provided name (A6);
//   - every candidate FQN index-Absent — not Unique, not Ambiguous, not a catalog builtin;
//   - the whole-universe dam clear (A5-corrected; the vouch valve is NOT in scope —
//     dammed ⇒ silent);
//   - the boot surface answers not-found for every candidate (A2ii / reflect);
//   - not existence-vouched by a dominating `function_exists`/`class_exists` guard —
//     for `call.undefined-function` via the branch store (FP-15); for `class.undefined`
//     via dead-region pruning, since a decided guard whose class meets the firing
//     conditions (Absent + boot not-found) folds its branch dead under the SAME closure;
//   - PHP function-/class-name case-insensitivity throughout.
// ---------------------------------------------------------------------------

/// The curated SAPI-provided functions (ADR-0049 A6): symbols a CLI sidecar lacks
/// but the serving FPM/Apache/LiteSpeed runtime provides, so they are NEVER Absent
/// while the serving SAPI is undeclared (the default — `[runtime] sapi` would unlock
/// a firing claim, deferred-with-design). Matched case-insensitively on the already-
/// lowercased candidate; the `apache_`/`litespeed_` families are prefix-matched.
fn is_sapi_provided_function(lname: &str) -> bool {
    const EXACT: &[&str] = &["fastcgi_finish_request", "getallheaders", "virtual"];
    lname.starts_with("apache_") || lname.starts_with("litespeed_") || EXACT.contains(&lname)
}

/// Resolve a function-call reference to its provably-**absent** target under PHP name
/// resolution (ADR-0049 §3 (a) + A8): `Some((display, candidates))` when EVERY FQN the
/// call could denote is index-`Absent` (no Unique decl — conditional decls are indexed
/// too, so this excludes the polyfill idiom — and no `Ambiguous`), and no candidate is
/// a catalog builtin; `None` otherwise (resolved / ambiguous / builtin ⇒ silence).
/// `display` is the source-cased primary target (the current-ns candidate for an
/// unqualified call); `candidates` are the lowercased FQNs whose runtime existence the
/// boot-surface leg must also refute (two for an unqualified in-namespace call: the
/// `Ns\name` candidate PHP tries first, then the global fallback).
fn undefined_function_target(cx: &Cx, r: &NameRef) -> Option<(String, Vec<String>)> {
    let catalog_knows = |n: &str| steins_catalog::effect_labels(n).is_some();
    let absent = |fqn: &str| matches!(cx.index.resolve_function(fqn), Res::Absent);
    match r.kind {
        RefKind::FullyQualified => {
            let lname = r.raw.to_ascii_lowercase();
            // A single-segment global name (`\strlen`) may be a builtin.
            if !r.raw.contains('\\') && catalog_knows(&lname) {
                return None;
            }
            absent(&lname).then(|| (r.raw.clone(), vec![lname]))
        }
        RefKind::Qualified => {
            let ctx = cx.tree().ctx_at(r.offset);
            let first_len = r.raw.find('\\').unwrap_or(r.raw.len());
            let first = &r.raw[..first_len];
            let fqn = if let Some(t) = ctx.class_imports.get(&first.to_ascii_lowercase()) {
                format!("{t}{}", &r.raw[first_len..])
            } else if ctx.namespace.is_empty() {
                r.raw.clone()
            } else {
                format!("{}\\{}", ctx.namespace, r.raw)
            };
            let lname = fqn.to_ascii_lowercase();
            absent(&lname).then_some((fqn, vec![lname]))
        }
        RefKind::Relative => {
            // A8: `namespace\name` — the enclosing-ns candidate only, no fallback.
            let ctx = cx.tree().ctx_at(r.offset);
            if ctx.namespace.is_empty() {
                let lname = r.raw.to_ascii_lowercase();
                if catalog_knows(&lname) {
                    return None;
                }
                absent(&lname).then(|| (r.raw.clone(), vec![lname]))
            } else {
                let fqn = format!("{}\\{}", ctx.namespace, r.raw);
                let lname = fqn.to_ascii_lowercase();
                absent(&lname).then_some((fqn, vec![lname]))
            }
        }
        RefKind::Unqualified => {
            let ctx = cx.tree().ctx_at(r.offset);
            let name = r.raw.to_ascii_lowercase();
            // `use function` import wins outright: the single candidate is its target.
            if let Some(t) = ctx.fn_imports.get(&name) {
                let lt = t.to_ascii_lowercase();
                if !lt.contains('\\') && catalog_knows(&lt) {
                    return None;
                }
                return absent(&lt).then(|| (t.clone(), vec![lt]));
            }
            let (display, ns_candidate) = if ctx.namespace.is_empty() {
                (r.raw.clone(), None)
            } else {
                // PHP tries `Ns\name` first; a Unique or Ambiguous there ⇒ not absent.
                let ns_l = format!("{}\\{}", ctx.namespace, name);
                if !absent(&ns_l) {
                    return None;
                }
                (format!("{}\\{}", ctx.namespace, r.raw), Some(ns_l))
            };
            // Global fallback candidate: a catalog builtin or any user/ambiguous global
            // means the call resolves — silence.
            if catalog_knows(&name) || !absent(&name) {
                return None;
            }
            let mut candidates: Vec<String> = ns_candidate.into_iter().collect();
            candidates.push(name);
            Some((display, candidates))
        }
    }
}

/// Run the ADR-0049 §3 ladder for one function call and emit
/// `call.undefined-function` iff **every** leg holds. Called only in the plain
/// per-scope pass (`descent.is_none()`), and never inside a proven-dead region (the
/// walk prunes those), so a site is judged once with the branch store live.
fn check_undefined_function(
    cx: &Cx,
    folder: &mut dyn Folder,
    call: &CallExpr,
    store: &Store,
    out: &mut Vec<Diagnostic>,
) {
    // Leg (d): a real direct call. A first-class callable `f(...)` builds a Closure
    // (never invokes); `$fn()` / `call_user_func` are other `Callee` variants.
    let Callee::Function(_) = &call.receiver else {
        return;
    };
    if is_first_class_callable(call) {
        return;
    }
    let Some(r) = call.callee_ref.as_ref() else {
        return;
    };
    // Index leg (cheap, first): every candidate provably Absent (not Unique/Ambiguous,
    // not a catalog builtin). `None` ⇒ resolved/ambiguous ⇒ silence.
    let Some((display, candidates)) = undefined_function_target(cx, r) else {
        return;
    };
    // D3 carve-out: a reserved dump FQN already reds CI with a fail-level dump — a
    // second finding for one deletable line is noise (ADR-0053 §6).
    if is_dump_family_fqn(&resolved_fn_fqn(cx, r)) {
        return;
    }
    // A6: a curated SAPI-provided name is never Absent under an undeclared SAPI.
    if candidates.iter().any(|c| is_sapi_provided_function(c)) {
        return;
    }
    // FP-15 guard leg: a dominating positive `function_exists('f')` vouched the name.
    if candidates.iter().any(|c| store.vouches_function(c)) {
        return;
    }
    // Dam leg (A5): function existence is dammed — a standing dynamism site could mint
    // the name (the vouch valve is unavailable here, so dammed is silent).
    if !cx.dam.is_clear() {
        return;
    }
    // A9 + no-sidecar sound subset: the whole family is silent (checked once, cached).
    if !folder.absence_family_available() {
        return;
    }
    // Boot-surface leg (A2ii / reflect): every candidate must be answered NOT-a-function
    // by the project's own PHP. A homonym (`Some(true)`) or unanswerable (`None`) ⇒ silence.
    for c in &candidates {
        match folder.boot_surface_function(c) {
            Some(false) => {}
            Some(true) | None => return,
        }
    }

    // Every leg holds — a proven `Error: Call to undefined function f()`.
    let pos = cx.tree().position(call.span.start);
    let evidence = existence_evidence(folder);
    out.push(Diagnostic {
        id: CALL_UNDEFINED_FUNCTION_ID,
        path: cx.path().to_owned(),
        line: pos.line,
        column: pos.column,
        message: format!("call to undefined function {display}() — {evidence}"),
        facet: None,
        fix: None,
    });
}

/// The ADR-0049 §9 closure-evidence clause for the existence ids: the boot surface's
/// self-description (`not defined in the project, not on PHP 8.5.8 (32 extensions)`),
/// or a version-agnostic phrasing when the sidecar reports no label.
fn existence_evidence(folder: &mut dyn Folder) -> String {
    folder.boot_surface_label().map_or_else(
        || "not defined in the project, not on the analyzing PHP".to_owned(),
        |label| format!("not defined in the project, not on {label}"),
    )
}

/// Run the ADR-0049 §5 ladder for the file's hard-error class references and emit
/// `class.undefined` for each provably-absent one. Called once per file (never under
/// a descent); dead-region references are skipped by the caller, which is exactly the
/// guard leg for this id (a `class_exists('X')` whose class meets the firing
/// conditions folds its branch dead under the SAME closure this ladder rests on).
fn check_undefined_class(cx: &Cx, folder: &mut dyn Folder, r: &NameRef, out: &mut Vec<Diagnostic>) {
    // The class-LIKE closure set (classes + interfaces + enums + traits, alias edges
    // followed) — index Absent, not Ambiguous. `self`/`static`/`parent`, dynamic
    // classes, and `X::class` were excluded at collection.
    let display = cx.tree().resolve_class_fqn(r);
    let lname = display.to_ascii_lowercase();
    if !matches!(cx.index.resolve_class(&lname), Res::Absent) {
        return; // Unique (defined / aliased) or Ambiguous ⇒ silence.
    }
    // Extra silence (a subset of the sidecar's answer, never a firing license): a class
    // the catalog knows as a builtin/extension class-like in its hierarchy.
    if steins_catalog::builtin_class_supers(&lname).is_some() {
        return;
    }
    // Dam leg (A5): class existence is dammed — eval / out-of-universe include mints.
    if !cx.dam.is_clear() {
        return;
    }
    // A9 + no-sidecar sound subset.
    if !folder.absence_family_available() {
        return;
    }
    // Boot-surface leg (A2ii / reflect): the project's own PHP must answer not-found.
    match folder.boot_surface_class_like(&lname) {
        Some(false) => {}
        Some(true) | None => return,
    }

    let pos = cx.tree().position(r.offset);
    let evidence = existence_evidence(folder);
    out.push(Diagnostic {
        id: CLASS_UNDEFINED_ID,
        path: cx.path().to_owned(),
        line: pos.line,
        column: pos.column,
        message: format!("reference to undefined class {display} — {evidence}"),
        facet: None,
        fix: None,
    });
}

// ---------------------------------------------------------------------------
// Arity: `call.too-few-arguments` / `call.unknown-named-argument`
// (ADR-0049 §6 / S5 — the userland arms).
//
// The verified PHP 8.5 table is ASYMMETRIC (every row `php -r`-checked): too few
// positional/named arguments to a userland target is always a fatal
// `ArgumentCountError`; too MANY to a non-variadic runs clean (extras ignored) and
// is NEVER a finding (the ADR-0002 consequence pattern, whatever PHPStan reports —
// `call.too-many-arguments` stays REGISTERED_NOT_YET_EMITTED for the internal
// slice, M2); an unknown named argument to a non-variadic is a fatal `Error`, while
// a variadic silently collects it (`fv(x: 1)` → `{"x":1}`). A named argument that
// overwrites a positional (`f(1, a: 5)`) is a fatal `Error` too — a DEFERRED id, so
// it is a *silence* leg here. The verified runtime precedence is
// **overwrite ≻ unknown-named ≻ too-few** (`f(z: 9)` on `f($a, $b)` throws the
// unknown-name `Error`, not `ArgumentCountError`), and the checks below honor it so
// the emitted id never misnames the runtime consequence. Internal (builtin) targets
// take their arity from sidecar reflection and ship with the reflect slice (M2).
//
// Provability rests entirely on the RESOLVED TARGET's ground-truth signature:
//   - functions: a uniquely-indexed userland function (ADR-0049 A2 legs — not
//     Ambiguous, not builtin-shadowed; a conditional declaration re-dams the claim;
//     the boot-surface function-homonym is cleared via the sidecar);
//   - methods/constructors/statics: ONLY under a proven-EXACT receiver. The
//     declared-receiver variant is UNSOUND — an override may ADD optional
//     parameters (`P::m(int $a)` vs `Q::m($a = 0, $b = 0)`), so `$p->m()` on a
//     declared `P` holding a `Q` satisfies the runtime contract and runs; a finding
//     there is a false positive, REFUSED outright (never deferred to a contract
//     lane, unlike `phpdoc.undefined-method`). Exactness reuses S2's gate: `new`,
//     a `class_exact` heap object, or a textual `Class::` static; `$this`
//     (membership, A1), `self::`/`static::`/`parent::`, `?->`, and every dynamic
//     form are silent.
// Call-site conditions: no argument unpacking (`...` ⇒ count unproven; counting
// proven Singleton arrays is deferred); the first-class-callable `f(...)` is not a
// call; named binding is resolved against the target's parameter names
// case-SENSITIVELY, exactly as PHP binds them.
// ---------------------------------------------------------------------------

/// A resolved arity target: the callee's parameter list (the ground-truth
/// signature) and its PHP display name for the message (`format`, `Order::pay`,
/// `Order::__construct`).
struct ArityTarget<'a> {
    params: &'a [Param],
    display: String,
}

/// The number of **required** parameters (ADR-0049 §6): the 1-based index of the
/// last parameter that is neither variadic nor default-valued. Matches PHP 8.5's
/// `ReflectionFunctionAbstract::getNumberOfRequiredParameters`, including the
/// deprecated "optional parameter declared before a required one is implicitly
/// required" shape (`f($a = 1, $b)` ⇒ 2, `php -r`-verified). A variadic is never
/// required; by-ref and promoted parameters are required exactly like any other
/// (both `php -r`-verified).
fn required_param_count(params: &[Param]) -> usize {
    let mut required = 0;
    for (i, p) in params.iter().enumerate() {
        if !p.variadic && !p.has_default {
            required = i + 1;
        }
    }
    required
}

/// Resolve the exact-receiver class + method name for an arity method/static/
/// constructor call, or `None` when the receiver is not proven exact (S2's gate,
/// plus constructors). Constructors and textual `Class::` statics are exact by
/// construction; a `$var` receiver is exact only under a `class_exact` heap fact.
/// The `bool` is whether this is a **static** (`Class::m()`) call — a static call
/// to a NON-static method raises `Error: Non-static method … cannot be called
/// statically` *before* any `ArgumentCountError` (`php -r`-verified), so the caller
/// silences that shape rather than misnaming the consequence.
fn arity_method_receiver(
    cx: &Cx,
    call: &CallExpr,
    store: &Store,
    poisoned: bool,
) -> Option<(String, String, bool)> {
    match &call.receiver {
        Callee::Construct { class } => Some((cx.class_fqn(class), "__construct".to_owned(), false)),
        Callee::Method { receiver, method, nullsafe } => {
            if *nullsafe {
                return None; // `?->` excluded in v1 (S2 leg (l)).
            }
            let class = match receiver {
                Receiver::New(name) => cx.class_fqn(name),
                Receiver::Var(v) => {
                    if poisoned {
                        return None;
                    }
                    let obj = store.obj_of(v)?;
                    if !obj.class_exact {
                        return None; // lower bound → the refused declared-receiver lane.
                    }
                    obj.class.clone()
                }
                // A1: `$this` is a membership fact, never exactness — silent.
                Receiver::This => return None,
                // A depth-1 property-fetch receiver carries no exact-class proof for
                // arity dispatch (ADR-0052 §7) — silent.
                Receiver::Prop { .. } => return None,
            };
            Some((class, method.clone(), false))
        }
        Callee::Static { class, method } => match class {
            StaticClass::Named(name) => Some((cx.class_fqn(name), method.clone(), true)),
            StaticClass::SelfKw | StaticClass::Parent | StaticClass::Static => None,
        },
        Callee::Function(_) | Callee::DynamicVar(_) | Callee::Dynamic => None,
    }
}

/// Walk `start_fqn`'s exact-receiver chain resolving `method` to its declaring
/// [`MethodDecl`] under S2's closure discipline. Returns the method, its declaring
/// class's simple name, the ordered traversed FQNs (for the A2ii homonym leg), and
/// whether any traversed class was declared conditionally (A2i). `None` on any
/// obstacle: an unresolvable/`Ambiguous`/absent class, an enum (A3 — methods not
/// lowered), a trait name or a `uses_traits` class (a trait could shadow the method
/// with a different signature), a cycle, an **abstract** or **non-public** resolved
/// method (a protected/private method may route to `__call` or raise a distinct
/// visibility `Error` — not an `ArgumentCountError`), or the method being absent
/// from the whole chain (that is S2's job, not arity's).
fn walk_arity_chain<'a>(
    cx: &Cx<'a>,
    start_fqn: &str,
    method: &str,
) -> Option<(&'a MethodDecl, String, Vec<String>, bool)> {
    let mut cur = start_fqn.to_owned();
    let mut seen: HashSet<String> = HashSet::new();
    let mut traversed: Vec<String> = Vec::new();
    let mut any_conditional = false;
    loop {
        if !seen.insert(cur.to_ascii_lowercase()) {
            return None; // cycle — closure cannot terminate soundly.
        }
        let (cfile, cd) = cx.find_class(&cur)?; // unique project class, or bust.
        if cd.is_enum || cd.is_trait || cd.uses_traits {
            return None;
        }
        traversed.push(cur.clone());
        if cd.conditional {
            any_conditional = true;
        }
        if let Some(m) = cd.methods.iter().find(|m| m.name.eq_ignore_ascii_case(method)) {
            if m.is_abstract || m.visibility != Visibility::Public {
                return None;
            }
            return Some((m, cd.name.clone(), traversed, any_conditional));
        }
        // A `None` parent ends the chain: the method is absent from the whole chain
        // — that is S2's `call.undefined-method`, never arity's id.
        cur = cx.units[cfile].tree.resolve_class_fqn(cd.parent.as_ref()?);
    }
}

/// Resolve a userland **function** call to its arity target (ADR-0049 §6 / A2
/// legs). Cheap textual resolution first, then the sidecar-backed legs.
fn resolve_arity_function<'a>(
    cx: &Cx<'a>,
    folder: &mut dyn Folder,
    call: &CallExpr,
) -> Option<ArityTarget<'a>> {
    let r = call.callee_ref.as_ref()?;
    // Unique userland function only — `Ambiguous` and builtin-shadowed both resolve
    // to `Unknown` (silent); a catalogued builtin is the internal slice (M2).
    let FnResolution::User(site) = cx.resolve_function(r) else {
        return None;
    };
    let decl = cx.fn_decl(site);
    // A9 + the A2ii homonym leg both require a live sidecar.
    if !folder.absence_family_available() {
        return None;
    }
    // A2i: a conditionally-declared function re-dams the claim.
    if decl.conditional && !cx.dam.is_clear() {
        return None;
    }
    // A2ii: the resolved FQN must be answered NOT-present as a boot-surface
    // function (a homonym extension function may be the real runtime binding — the
    // `function_exists`-guarded polyfill shadowed by a loaded extension).
    match folder.boot_surface_function(&decl.fqn) {
        Some(false) => {}
        Some(true) | None => return None,
    }
    Some(ArityTarget { params: &decl.params, display: decl.name.clone() })
}

/// Resolve a method/static/constructor arity target under a proven-exact receiver
/// and S2's chain closure (ADR-0049 §6). Cheap textual legs first.
fn resolve_arity_method<'a>(
    cx: &Cx<'a>,
    folder: &mut dyn Folder,
    call: &CallExpr,
    store: &Store,
    poisoned: bool,
) -> Option<ArityTarget<'a>> {
    let (start_fqn, method, is_static_call) = arity_method_receiver(cx, call, store, poisoned)?;
    // `new AbstractClass()` / `new SomeInterface()` raises `Error: Cannot
    // instantiate abstract class / interface` BEFORE any `ArgumentCountError`
    // (`php -r`-verified) — silence it (would misname the consequence).
    if let Callee::Construct { .. } = &call.receiver {
        let (_, start_cd) = cx.find_class(&start_fqn)?;
        if start_cd.is_abstract || start_cd.is_interface {
            return None;
        }
    }
    let (mdecl, declaring_name, traversed, any_conditional) =
        walk_arity_chain(cx, &start_fqn, &method)?;
    // A static call (`Class::m()`) to a NON-static method raises the non-static
    // `Error` before any `ArgumentCountError` — silence it (would misname).
    if is_static_call && !mdecl.is_static {
        return None;
    }
    // A9 + the A2ii homonym leg both require a live sidecar.
    if !folder.absence_family_available() {
        return None;
    }
    // A2i: a conditional class anywhere on the traversed chain re-dams the claim.
    if any_conditional && !cx.dam.is_clear() {
        return None;
    }
    // A2ii: every traversed class must be boot-surface-absent as a class-like.
    for fqn in &traversed {
        match folder.boot_surface_class_like(fqn) {
            Some(false) => {}
            Some(true) | None => return None,
        }
    }
    let display = if method.eq_ignore_ascii_case("__construct") {
        format!("{declaring_name}::__construct")
    } else {
        format!("{declaring_name}::{}", mdecl.name)
    };
    Some(ArityTarget { params: &mdecl.params, display })
}

/// The finding half: given a resolved target, apply the ordered arity checks
/// (overwrite ≻ unknown-named ≻ too-few) to one call site, honoring the verified
/// runtime precedence so the emitted id never misnames the consequence.
fn emit_arity(cx: &Cx, call: &CallExpr, target: &ArityTarget, out: &mut Vec<Diagnostic>) {
    let params = target.params;
    // Shape gates. Unpacking (or a non-canonical order) leaves the count unproven.
    if call.has_spread {
        return;
    }
    let pos = call.args.len();
    let named = &call.named_args;
    // First-class-callable `f(...)` lowers to an arg-less non-positional call — not
    // a call for arity. (Any real call is `positional_only`, or has ≥1 arg.)
    if !call.positional_only && pos == 0 && named.is_empty() {
        return;
    }

    // Overwrite guard (verified precedence #1): a named argument targeting a
    // parameter already filled by a positional argument (`f(1, a: 5)`) raises the
    // DEFERRED overwrite `Error` — silence both of our ids so neither misclaims.
    let overwrite = named
        .iter()
        .any(|n| params.iter().position(|p| p.name == n.name).is_some_and(|i| i < pos));
    if overwrite {
        return;
    }

    let has_variadic = params.iter().any(|p| p.variadic);
    // unknown-named (verified precedence #2): a named argument matching no parameter
    // of a NON-variadic target is a fatal `Error`; a variadic silently collects it.
    // Parameter-name matching is case-SENSITIVE (`f(A: 1)` on `$a` is unknown).
    if !has_variadic
        && let Some(unknown) = named.iter().find(|n| !params.iter().any(|p| p.name == n.name))
    {
        let at = cx.tree().position(call.span.start);
        out.push(Diagnostic {
            id: CALL_UNKNOWN_NAMED_ARGUMENT_ID,
            facet: None,
            fix: None,
            path: cx.path().to_owned(),
            line: at.line,
            column: at.column,
            message: format!(
                "unknown named argument ${} to {}() — no parameter ${}, provable Error",
                unknown.name, target.display, unknown.name,
            ),
        });
        return;
    }

    // too-few (verified precedence #3): a required parameter covered by neither a
    // positional argument (index < pos) nor a named argument of that name.
    let required = required_param_count(params);
    let uncovered =
        (0..required).any(|i| i >= pos && !named.iter().any(|n| n.name == params[i].name));
    if uncovered {
        let passed = pos + named.len();
        let at = cx.tree().position(call.span.start);
        out.push(Diagnostic {
            id: CALL_TOO_FEW_ARGUMENTS_ID,
            facet: None,
            fix: None,
            path: cx.path().to_owned(),
            line: at.line,
            column: at.column,
            message: format!(
                "too few arguments to {}(): {passed} passed, {required} required — provable ArgumentCountError",
                target.display,
            ),
        });
    }
}

/// Run the full ADR-0049 §6 userland arity ladder for one call and emit
/// `call.too-few-arguments` / `call.unknown-named-argument` iff every leg holds.
/// Called only from the plain per-scope pass (`descent.is_none()`) so a site is
/// judged once, never re-emitted under an interprocedural descent.
fn check_arity(
    cx: &Cx,
    folder: &mut dyn Folder,
    call: &CallExpr,
    store: &Store,
    poisoned: bool,
    out: &mut Vec<Diagnostic>,
) {
    let target = match &call.receiver {
        Callee::Function(_) => resolve_arity_function(cx, folder, call),
        Callee::Method { .. } | Callee::Static { .. } | Callee::Construct { .. } => {
            resolve_arity_method(cx, folder, call, store, poisoned)
        }
        Callee::DynamicVar(_) | Callee::Dynamic => None,
    };
    let Some(target) = target else {
        return;
    };
    emit_arity(cx, call, &target, out);
}

// ---------------------------------------------------------------------------
// The declared-receiver lane: `phpdoc.undefined-method` (ADR-0049 §8 / S6).
//
// The **contract-layer** twin of `call.undefined-method`. Where S2 fires on a
// proven-exact receiver (`class_exact`), S6 fires on a receiver whose *declared*
// type — a phpdoc `@param User|Guest`, narrowed by branch analysis (N4) down to a
// surviving contract-arm list — provably lacks the method under a stricter ladder:
// "conditional is not enough" (§8), so each surviving arm must clear both the §4
// chain legs AND **descendant closure** (a subclass, incl. an `eval`-minted one,
// could satisfy the contract and define the method).
//
// **Disjointness from S2 (stated in code).** S2 owns `class_exact` receivers; S6
// requires the receiver be NOT exact — an inexact/lower-bound `$var` carrying a
// narrowed arm lane. A receiver is never judged by both ids: an exact object has no
// contract lane consulted here (the `is_exact` bail), and a lane-carrying var is
// never `class_exact`. The two lists (`ALL_EMITTABLE_IDS`) stay disjoint too.
//
// This id **accepts Asserted premises** (contract layer, ADR-0052 §5): the
// narrowed lane's arms may be `Asserted` (a `@param` refinement) — the finding is
// coherent at the min stratum. It still respects `absence_family_available` (A9
// monkey-patch silence + the A2ii homonym leg needs a live sidecar) and the A11
// version-skew demotion of descendant closure.
// ---------------------------------------------------------------------------

/// The `(receiver-var, method)` an S6 claim can rest on, or `None` when the call is
/// out of scope for the declared-receiver lane (silence). Only a plain
/// `$var->method(...)` qualifies: `?->` (leg l), static/`$this`/`new`/dynamic forms,
/// and the first-class-callable shape are excluded exactly as S2 excludes them.
fn phpdoc_undefined_method_receiver(call: &CallExpr) -> Option<(String, String)> {
    // Leg (l): the first-class-callable form builds a Closure, never a call.
    if !call.positional_only && call.args.is_empty() {
        return None;
    }
    match &call.receiver {
        Callee::Method { receiver: Receiver::Var(v), method, nullsafe: false } => {
            Some((v.clone(), method.clone()))
        }
        _ => None,
    }
}

/// The project-wide descendant enumeration of a union member (ADR-0049 §8 / A4).
enum DescendantClosure<'a> {
    /// The member is `final` (or an enum): no subclass can exist — extending it is
    /// fatal — so the arm is immune and needs no descendant scan and no dam.
    Immune,
    /// The member's descendant declarations are **completely enumerated** (no
    /// obstacle): every declared class either provably is-a the member (collected
    /// here) or provably is not, over declarations (both halves of an Ambiguous FQN)
    /// with alias-edge parent matching and interface edge kinds. A non-empty set
    /// still requires the dam clear (an `eval`-minted subclass) before it closes.
    Enumerated(Vec<(usize, &'a ClassDecl)>),
    /// Closure is tainted — Unknown ⇒ silence. An anonymous class could extend the
    /// member (invisible to the index), a candidate's is-a is Unknown (incomplete
    /// hierarchy), the member itself is Ambiguous/absent, or a catalog-backed verdict
    /// is demoted under a PHP-minor skew (A11).
    Obstacle,
}

/// Whether the specific declaration `cd` (in file `file`) provably **is-a**
/// `target` (lowercase FQN), walking its own inheritance edges directly rather than
/// through the deduped index — so an Ambiguous declaration still contributes as a
/// descendant (A4). A direct edge resolving to the *same index site* as `target`
/// counts as `Yes`, which folds literal `class_alias` edges into parent matching
/// (`class B extends LegacyName` with `class_alias('T', 'LegacyName')` makes B a
/// descendant of T). Deeper hops defer to the trinary [`Cx::is_a`] oracle, whose
/// `Unknown` (an unresolvable/uncatalogued ancestor) taints the enumeration.
fn decl_is_a(cx: &Cx, file: usize, cd: &ClassDecl, target: &str) -> IsA {
    let tree = &cx.units[file].tree;
    let arm_site = match cx.index.resolve_class(target) {
        Res::Unique(s) => Some(s),
        _ => None,
    };
    let mut edges: Vec<String> = Vec::new();
    if let Some(p) = &cd.parent {
        edges.push(tree.resolve_class_fqn(p));
    }
    for i in &cd.implements {
        edges.push(tree.resolve_class_fqn(i));
    }
    if cd.is_enum {
        edges.push("UnitEnum".to_owned());
        if cd.enum_backing.is_some() {
            edges.push("BackedEnum".to_owned());
        }
    }
    let mut any_unknown = false;
    for e in &edges {
        let en = e.trim_start_matches('\\');
        if en.eq_ignore_ascii_case(target) {
            return IsA::Yes;
        }
        // Alias-edge / site-identity parent match (A4): the direct edge resolves to
        // the same index site as the arm.
        if let (Some(a), Res::Unique(es)) = (arm_site, cx.index.resolve_class(en))
            && es == a
        {
            return IsA::Yes;
        }
        match cx.is_a(en, target) {
            IsA::Yes => return IsA::Yes,
            IsA::Unknown => any_unknown = true,
            IsA::No => {}
        }
    }
    if any_unknown { IsA::Unknown } else { IsA::No }
}

/// Enumerate the project-wide descendant set of a union member (ADR-0049 §8 / A4).
/// A query-style whole-universe function (ADR-0048): recomputed per run, no ordering
/// dependence. See [`DescendantClosure`].
fn descendant_closure<'a>(cx: &Cx<'a>, arm_fqn: &str) -> DescendantClosure<'a> {
    // The member must resolve Unique — an Ambiguous/absent member cannot be closed.
    let Some((_, arm_cd)) = cx.find_class(arm_fqn) else {
        return DescendantClosure::Obstacle;
    };
    // A `final` class or an enum has no subclass — extending it is fatal — so the
    // arm is immune (A9 already gated finality via `absence_family_available`).
    if arm_cd.is_final || arm_cd.is_enum {
        return DescendantClosure::Immune;
    }
    // A11: a PHP-minor skew can fake a catalog-backed is-a edge, so descendant
    // closure demotes to Unknown (blanket v1) — silence, never a wrong narrowing.
    if cx.a11_demote_catalog() {
        return DescendantClosure::Obstacle;
    }
    // A4 anonymous-class obstacle: an anon class is invisible to the index, so any
    // one whose extends/implements edge could reach the member taints closure.
    for unit in cx.units {
        for edge in unit.tree.anonymous_class_edges() {
            let refs = edge.parent.iter().chain(edge.implements.iter());
            for r in refs {
                let efqn = unit.tree.resolve_class_fqn(r);
                let en = efqn.trim_start_matches('\\');
                if en.eq_ignore_ascii_case(arm_fqn) {
                    return DescendantClosure::Obstacle;
                }
                // is-a-or-Unknown against the member ⇒ a possible invisible descendant.
                match cx.is_a(en, arm_fqn) {
                    IsA::Yes | IsA::Unknown => return DescendantClosure::Obstacle,
                    IsA::No => {}
                }
            }
        }
    }
    // Enumerate declared descendants over ALL declarations (not the deduped index —
    // both halves of an Ambiguous FQN count, A4). A single Unknown candidate (an
    // incompletely-enumerated hierarchy) taints the whole closure.
    let mut descendants: Vec<(usize, &'a ClassDecl)> = Vec::new();
    for (fi, unit) in cx.units.iter().enumerate() {
        for cd in unit.tree.classes() {
            if cd.fqn.eq_ignore_ascii_case(arm_fqn) {
                continue; // the member itself (Unique — resolved above).
            }
            match decl_is_a(cx, fi, cd, arm_fqn) {
                IsA::Yes => descendants.push((fi, cd)),
                IsA::Unknown => return DescendantClosure::Obstacle,
                IsA::No => {}
            }
        }
    }
    DescendantClosure::Enumerated(descendants)
}

/// Whether a descendant declaration could **introduce** `method` (or an obstacle
/// that hides it) below a member whose own chain already lacks it (ADR-0049 §8). A
/// descendant that declares the method, uses a trait, is an enum (A3, methods
/// unlowered), or carries `__call` is a witness that the runtime object — though
/// contract-typed as the member — may answer the call. Any such descendant makes
/// the absence claim fail (silence).
fn descendant_introduces_method(cd: &ClassDecl, method: &str) -> bool {
    cd.is_enum
        || cd.is_trait
        || cd.uses_traits
        || cd.methods.iter().any(|m| m.name.eq_ignore_ascii_case("__call"))
        || cd.methods.iter().any(|m| m.name.eq_ignore_ascii_case(method))
}

/// Run the full §8 ladder for one narrowed contract arm and return its display
/// simple-name when the method is **provably absent** across the arm's whole
/// hierarchy *and* its complete descendant set, or `None` when any leg fails
/// (silence). Instance calls only — the declared-receiver lane is `$var->m()`.
fn arm_provably_lacks_method(
    cx: &Cx,
    folder: &mut dyn Folder,
    arm_fqn: &str,
    method: &str,
) -> Option<String> {
    // §4 chain closure over the arm's own ancestor chain (reuses S2's walk).
    let ChainWalk::Absent { simple_chain, fqns, any_conditional } =
        enumerate_method_chain(cx, arm_fqn, method, UndefKind::Instance)
    else {
        return None;
    };
    // A2i: a conditional declaration in the chain re-dams the claim.
    if any_conditional && !cx.dam.is_clear() {
        return None;
    }
    // A2ii homonym: every chain FQN must be answered NOT-present by the boot surface.
    for fqn in &fqns {
        if folder.boot_surface_class_like(fqn) != Some(false) {
            return None;
        }
    }
    // Descendant closure (A4): the arm is final-immune, or its descendant set is
    // fully enumerated AND the dam is clear (an `eval`-minted subclass), and no
    // descendant introduces the method.
    match descendant_closure(cx, arm_fqn) {
        DescendantClosure::Immune => {}
        DescendantClosure::Obstacle => return None,
        DescendantClosure::Enumerated(descendants) => {
            if !cx.dam.is_clear() {
                return None; // eval could mint a subclass carrying the method.
            }
            for (_, dcd) in &descendants {
                if descendant_introduces_method(dcd, method) {
                    return None;
                }
                // A homonym descendant may be dead code shadowed by a loaded class.
                if folder.boot_surface_class_like(&dcd.fqn) != Some(false) {
                    return None;
                }
            }
        }
    }
    Some(simple_chain.first().cloned().unwrap_or_else(|| arm_fqn.to_owned()))
}

/// Run the ADR-0049 §8 ladder for one `$var->method()` and emit
/// `phpdoc.undefined-method` iff the receiver's narrowed contract-arm lane consists
/// entirely of class arms that **each** provably lack the method under descendant
/// closure. Contract layer — Asserted arms are coherent premises; any leg failure
/// on any arm is silence.
fn check_phpdoc_undefined_method(
    cx: &Cx,
    folder: &mut dyn Folder,
    call: &CallExpr,
    store: &Store,
    poisoned: bool,
    out: &mut Vec<Diagnostic>,
) {
    if poisoned {
        return;
    }
    let Some((var, method)) = phpdoc_undefined_method_receiver(call) else {
        return;
    };
    // Disjointness with S2: an exact receiver is S2's, never S6's.
    if store.is_exact(&var) {
        return;
    }
    // The narrowed declared-type arm lane (N4's accessor). No lane ⇒ nothing declared
    // to close over.
    let Some(arms) = store.contract_arms(&var) else {
        return;
    };
    if arms.is_empty() {
        return;
    }
    // Every surviving arm must be a class/interface arm: a scalar/array/null arm
    // means the runtime receiver may be a non-object, so a method-absence claim does
    // not hold (a different error, out of this lane) — silence.
    let mut class_fqns: Vec<String> = Vec::with_capacity(arms.len());
    for a in arms {
        match &a.ty {
            steins_contract::ContractTy::Class(f) => class_fqns.push(f.clone()),
            _ => return,
        }
    }
    // A9 (monkey-patch) + A2ii's honest consequence: without a live sidecar, or with
    // a runtime-redefinition extension loaded, the id is silent (checked once).
    if !folder.absence_family_available() {
        return;
    }
    // Every arm must provably lack the method under its closed ladder.
    let mut arm_names: Vec<String> = Vec::with_capacity(class_fqns.len());
    for f in &class_fqns {
        match arm_provably_lacks_method(cx, folder, f, &method) {
            Some(name) => arm_names.push(name),
            None => return, // any arm not provably-absent ⇒ silence.
        }
    }

    let pos = cx.tree().position(call.span.start);
    let arms_disp = arm_names.join("|");
    let message = format!(
        "call to undefined method {arms_disp}::{method}() — declared receiver ${var} narrowed to {{{arms_disp}}}, \
         hierarchy and descendants fully enumerated, no __call"
    );
    out.push(Diagnostic {
        id: PHPDOC_UNDEFINED_METHOD_ID,
        path: cx.path().to_owned(),
        line: pos.line,
        column: pos.column,
        message,
        facet: None,
        fix: None,
    });
}

// ---------------------------------------------------------------------------
// The offset family: `offset.missing` / `offset.on-unsupported` (ADR-0049 §7 / S3).
//
// A value-domain absence proof: a read `$base[$key]` provably emits an `E_WARNING`
// because the whole container value is known (a Verified `Singleton`/all-array
// `OneOf`) and the key is provably absent, or the base is a proven non-offsetable
// scalar/null. Provability is value-domain evidence only (§7): `General`/`Refined`,
// objects, string bases, and any non-`Verified` fact (N2) are silent.
//
// **Read-context whitelist (A7).** The emitter is called ONLY from the whitelisted
// read positions — a plain assignment-RHS and a return operand — in the plain
// per-scope pass. Every silence context (`isset`/`??`/`array_key_exists`/`unset`,
// write lvalues, by-ref/unresolved-callee argument positions, array elements) never
// reaches here: `??` lowers its operand into an [`ArgValue::Coalesce`] (not a
// top-level `OffsetRead`), a write lvalue never lowers to an `Assign`/`Return`
// value, and `isset`/`unset`/`array_key_exists` are constructs/calls the lowering
// keeps out of these value slots entirely.
//
// v1 scope (deferred-with-comment, all safe silence): the Error-grade object case
// (needs the ArrayAccess is-a surface), the TypeError string-key-on-string case,
// string-base offset reads (in-range present / uninitialized-offset warning), the
// call-argument read position (the by-ref / unresolved-callee autovivification risk,
// A7), and the compound-assignment read half — none of which the current lowering
// carries into `Assign`/`Return` value slots.
// ---------------------------------------------------------------------------

/// Severity grade of an offset finding (ADR-0049 §7 verified table). The
/// `warning-handler` posture gates only [`Self::Warning`]; [`Self::Fatal`] (the
/// object `Error` / string-key `TypeError` cases) would emit under both — but those
/// cases are not implemented, so every finding here is currently `Warning`.
#[derive(Clone, Copy, PartialEq, Eq)]
enum OffsetGrade {
    Warning,
    #[allow(dead_code)]
    Fatal,
}

/// Canonicalize a proven key [`Val`] to a domain array key (ADR-0049 A10), reusing
/// the SAME [`php_canonical_int_string`] primitive as the write/lowering side — so
/// `$a = [5 => 'x']; $a["5"]` resolves to the present key `5`, while `"05"`/`"+5"`
/// stay strings. `None` for an array key (an illegal offset type — a distinct
/// TypeError, out of scope here) or a non-finite float.
fn offset_key_of(v: &Val) -> Option<VKey> {
    match v {
        Val::Int(i) => Some(VKey::Int(*i)),
        Val::Bool(b) => Some(VKey::Int(i64::from(*b))),
        Val::Null => Some(VKey::Str(String::new())),
        #[allow(clippy::cast_possible_truncation)]
        Val::Float(f) if f.is_finite() => Some(VKey::Int(f.trunc() as i64)),
        Val::Str(s) => Some(match php_canonical_int_string(s) {
            Some(i) => VKey::Int(i),
            None => VKey::Str(s.clone()),
        }),
        Val::Float(_) | Val::Array(_) => None,
    }
}

/// The proven `Verified` value-domain fact for an offset-read operand (base or key),
/// or `None` when unproven, poisoned, or below the proof stratum (N2). A bare `Var`
/// reads the env (requiring `Verified`); a literal / fully-literal array resolves
/// directly (literals are `Verified` whole values). Every other form is unproven.
fn offset_operand_fact(
    arg: &ArgValue,
    env: &HashMap<String, Known>,
    poisoned: bool,
    php_minor: Option<(u16, u16)>,
) -> Option<Fact> {
    match arg {
        ArgValue::Var(name) => {
            if poisoned {
                return None;
            }
            let k = env.get(name)?;
            (k.stratum == Stratum::Verified).then(|| k.fact.clone()).flatten()
        }
        _ => singleton_fact(arg, php_minor),
    }
}

/// The PHP type word for an offset read on a proven non-offsetable scalar/null base
/// (verified PHP 8.5.8: `Trying to access array offset on null|int|float|true|false`).
/// `None` for a string base (offsetable — deferred) or any array.
fn unsupported_base_word(v: &Val) -> Option<&'static str> {
    match v {
        Val::Null => Some("null"),
        Val::Int(_) => Some("int"),
        Val::Float(_) => Some("float"),
        Val::Bool(true) => Some("true"),
        Val::Bool(false) => Some("false"),
        Val::Str(_) | Val::Array(_) => None,
    }
}

/// Render a canonical key in Steins' own phrasing (`0`, `'foo'`) for the evidence
/// clause, and in PHP's verbatim phrasing (`0`, `"foo"`) for the quoted consequence.
fn render_offset_key(k: &VKey) -> (String, String) {
    match k {
        VKey::Int(i) => (i.to_string(), i.to_string()),
        VKey::Str(s) => (format!("'{s}'"), format!("\"{s}\"")),
    }
}

/// Judge a single whitelisted offset read `base[key]` and emit at most one finding
/// (ADR-0049 §7 / S3). `span` locates the diagnostic (the enclosing statement).
#[allow(clippy::too_many_arguments)]
fn check_offset_read(
    cx: &Cx,
    folder: &mut dyn Folder,
    base: &ArgValue,
    key: &ArgValue,
    env: &HashMap<String, Known>,
    poisoned: bool,
    span: Span,
    out: &mut Vec<Diagnostic>,
) {
    // A9 (global): the whole family is silent without a live, monkey-patch-free
    // sidecar (checked once, cached) — the uniform absence-family availability gate.
    if !folder.absence_family_available() {
        return;
    }
    // Legs (b)/(e): the base must be a proven `Verified` whole value (N2). An object
    // base (fact `None` — object state lives in the heap, not the value domain) is
    // silent: the ArrayAccess-arbitrary-code / non-ArrayAccess-`Error` split is the
    // deferred object case.
    let Some(base_fact) = offset_operand_fact(base, env, poisoned, cx.php_minor) else {
        return;
    };

    // Case 1 — a proven non-offsetable scalar/null base (`offset.on-unsupported`,
    // warning-grade): the read warns regardless of the key, so no proven key is
    // required. Only a `Singleton` fires (a mixed/abstract base is silent).
    if let Fact::Singleton(v) = &base_fact
        && let Some(word) = unsupported_base_word(v)
    {
        emit_offset(
            cx,
            span,
            OFFSET_ON_UNSUPPORTED_ID,
            OffsetGrade::Warning,
            format!(
                "offset read on {} — provably {word}; reads null with \"Trying to access array offset on {word}\"",
                base.render(),
            ),
            out,
        );
        return;
    }

    // Case 2 — a container base (`offset.missing`, warning-grade): the key must be a
    // proven single value (leg (c)), canonicalized through the shared helper (A10).
    let Some(Fact::Singleton(key_val)) = offset_operand_fact(key, env, poisoned, cx.php_minor)
    else {
        return;
    };
    let Some(canon) = offset_key_of(&key_val) else {
        return;
    };

    let (our_key, php_key) = render_offset_key(&canon);
    match &base_fact {
        // A single proven array (including `Singleton([])` from an `=== []` guard):
        // key absence is definite (leg (b)).
        Fact::Singleton(Val::Array(entries)) => {
            if !array_has_key(entries, &canon) {
                emit_offset(
                    cx,
                    span,
                    OFFSET_MISSING_ID,
                    OffsetGrade::Warning,
                    format!(
                        "offset {our_key} provably missing — {} is {} on this path; reads null with \"Undefined array key {php_key}\"",
                        base.render(),
                        render_val(&base_fact_val(&base_fact)),
                    ),
                    out,
                );
            }
        }
        // A `OneOf` fires only when EVERY member is an array and none carries the key
        // (leg (b), the join rule): any member with the key — or any non-array member
        // — is silence.
        Fact::OneOf(members) => {
            let all_arrays_missing = members.iter().all(|m| {
                matches!(m, Val::Array(entries) if !array_has_key(entries, &canon))
            });
            if all_arrays_missing {
                emit_offset(
                    cx,
                    span,
                    OFFSET_MISSING_ID,
                    OffsetGrade::Warning,
                    format!(
                        "offset {our_key} provably missing — {} is one of {} proven arrays, none carrying the key; reads null with \"Undefined array key {php_key}\"",
                        base.render(),
                        members.len(),
                    ),
                    out,
                );
            }
        }
        // `Refined`/`General` (no proven whole value), a string base, or anything
        // else: silent (§7 value-domain-only provability).
        _ => {}
    }
}

// ---------------------------------------------------------------------------
// Shape-aware reads (ADR-0062 §4's read row, S3).
//
// The value-lane sibling of `check_offset_read`: where that function judges a
// PROVEN whole container for an absence FINDING, this one answers "what does the
// declaration say this key holds" against the abstract stratum, and emits
// nothing at all. The two never overlap — a `Fact::Shape` base falls into
// `check_offset_read`'s silent `_` arm, and an `Asserted` shape seed is invisible
// to its `Verified`-only operand gate to begin with (A-G9's corollary: shape-
// derived facts never feed proof-layer findings).
// ---------------------------------------------------------------------------

/// What a constant-key read against an abstract shape found (ADR-0062 §4).
///
/// The three no-fact outcomes are deliberately distinct even though S3 renders
/// them identically (unknown, silent): they are exactly the finding ladder S6
/// wires (A-G10) — [`Self::MaybeMissing`] is `offset.maybe-missing`'s site and
/// [`Self::DeclaredAbsent`] is `offset.undeclared`'s. Keeping the distinction in
/// the return type now means S6 adds emitters, not a second read path.
#[derive(Debug, Clone, PartialEq)]
enum ShapeRead {
    /// A `Required` field: its value slot (`None` — an unknown slot — is the
    /// honest floor, A-G1a).
    Present(Option<Fact>),
    /// An `Optional` field, undischarged: **no fact**, and specifically never
    /// the slot's value ∪ null (A-G9 — reads are never null-poisoned).
    ///
    /// The declared slot rides along but [`Self::into_fact`] does not yield it —
    /// the read surface must stay null-poison-free. Its ONE consumer is
    /// [`ShapeRead::taken_fact`], the `??` left-arm reading, where missing-ness
    /// is fall-through rather than a value (A-G11).
    MaybeMissing(Option<Fact>),
    /// The declaration proves the key is not there: an `Absent` field, a key
    /// outside a `Sealed` shape's fields, or a key the unsealed tail's own key
    /// class rejects.
    DeclaredAbsent,
    /// An undeclared key admitted by an `Unsealed` tail: the tail's value bound.
    Tail(Option<Fact>),
}

impl ShapeRead {
    /// The fact this read yields, if any. Every no-fact outcome collapses here —
    /// the distinction above is for S6's emitters, not for the value lane.
    fn into_fact(self) -> Option<Fact> {
        match self {
            ShapeRead::Present(f) | ShapeRead::Tail(f) => f,
            ShapeRead::MaybeMissing(_) | ShapeRead::DeclaredAbsent => None,
        }
    }

    /// The value this read yields **when a `??` takes the arm** (S5, A-G11).
    ///
    /// A non-final `??` arm is used only when `isset` holds of it, so its
    /// missing-ness is fall-through, not a value: an undischarged optional field
    /// still yields its declared slot here, and the `??` fold's `clear_null` is
    /// what applies the `isset` half. A *declared absence* yields nothing —
    /// nothing admitted by the shape can take that arm.
    ///
    /// This is not a weakening of A-G9: the fact never reaches a read surface,
    /// only the `??` join, and the join is where PHP itself says the arm's value
    /// is the one the expression has.
    fn taken_fact(self) -> Option<Fact> {
        match self {
            ShapeRead::Present(f) | ShapeRead::Tail(f) | ShapeRead::MaybeMissing(f) => f,
            ShapeRead::DeclaredAbsent => None,
        }
    }
}

/// Read one canonical key out of an abstract shape (ADR-0062 §4).
fn shape_read(shape: &ShapeFact, key: &VKey) -> ShapeRead {
    use steins_domain::{Presence, Tail};
    match shape.field(key) {
        // The witness bit is provenance, not extension: a declared-Required and a
        // guard-Verified key read the same value (the presence stratum is what S6
        // consumes, and it lives on the field, not on the read).
        Some((_, Presence::Required { .. }, slot)) => {
            ShapeRead::Present(slot.as_deref().cloned())
        }
        Some((_, Presence::Optional, slot)) => {
            ShapeRead::MaybeMissing(slot.as_deref().cloned())
        }
        Some((_, Presence::Absent, _)) => ShapeRead::DeclaredAbsent,
        None => match &shape.tail {
            Tail::Sealed => ShapeRead::DeclaredAbsent,
            Tail::Unsealed { key: class, value } if class.admits_key(key) => {
                ShapeRead::Tail(value.as_deref().cloned())
            }
            // The tail's key class excludes this key, so no admitted value has it.
            Tail::Unsealed { .. } => ShapeRead::DeclaredAbsent,
        },
    }
}

/// Resolve a read site `base[key]` to the **shape and canonical key** it names, or
/// decline. The one resolver both the value lane ([`shape_read_at`]) and the strict
/// leg's emitters (S6) go through, so a read and a finding can never disagree about
/// which field they mean.
///
/// `None` — decline — when the base carries no shape fact, when the base is
/// **nullable** (the value may be null, so no field is guaranteed; narrowing that is
/// S4's job), or when the key is not a proven single value.
fn shape_site_at<'a>(
    base: &ArgValue,
    key: &ArgValue,
    env: &'a HashMap<String, Known>,
    poisoned: bool,
    php_minor: Option<(u16, u16)>,
) -> Option<(&'a ShapeFact, VKey, Stratum)> {
    if poisoned {
        return None;
    }
    let ArgValue::Var(name) = base else { return None };
    let known = env.get(name)?;
    let Some(Fact::Shape { shape, nullable: false }) = &known.fact else { return None };
    // The key resolution is the offset family's, unchanged: a literal or a
    // `Verified` proven value, canonicalized by PHP's own key rule (A10).
    let Some(Fact::Singleton(key_val)) = offset_operand_fact(key, env, poisoned, php_minor) else {
        return None;
    };
    let canon = offset_key_of(&key_val)?;
    Some((shape, canon, known.stratum))
}

/// Resolve a read site `base[key]` against the abstract stratum: the base's own
/// shape fact and the offset family's proven-key resolution ([`offset_key_of`],
/// the ONE canonicalization), plus the stratum the result inherits.
fn shape_read_at(
    base: &ArgValue,
    key: &ArgValue,
    env: &HashMap<String, Known>,
    poisoned: bool,
    php_minor: Option<(u16, u16)>,
) -> Option<(ShapeRead, Stratum)> {
    let (shape, canon, stratum) = shape_site_at(base, key, env, poisoned, php_minor)?;
    // Derivation clause (ADR-0052 §5): the read consumes the base's fact, so the
    // result is no stronger than it — which is always `Asserted` for a shape.
    Some((shape_read(shape, &canon), stratum))
}

// ---------------------------------------------------------------------------
// The offset family's STRICT leg (ADR-0062 S6 / A-G10, issue #51).
//
// Two contract-layer ids, both at `Floor::Strict`, emitted from the SAME
// whitelisted read positions the proof leg uses (a plain assignment-RHS and a
// return operand) plus one position the proof leg deliberately does not judge:
// the right-most arm of a `??` chain.
//
// **Evidence discipline.** Every finding here reads a `Fact::Shape` — the declared
// envelope, `Asserted`. A-G9's corollary holds by construction: nothing below
// consults a proof-layer fact, and nothing below can produce a proof-layer id.
//
// **What is silent, and why.**
//
// * `ShapeRead::Present` — S3 reads it, S4's guards promoted it, or S5's cover
//   ladder proved it. Guarded code is clean *by proof*, never by skip.
// * `ShapeRead::Tail` — the unsealed tail's value bound. A general map/list read is
//   OUT of v1 scope (A-G10): it stays silent here and is a future separate id,
//   mirroring PHPStan's own two-flag split.
// * Every non-whitelisted read position — an `isset`/`array_key_exists`/`unset`
//   argument, a write lvalue, an array element, a NON-final `??` arm — never
//   reaches these emitters at all, exactly as in the proof leg (A7).
//
// **The `??` split** (issue #51 §2). PHP protects only the arms it may fall
// *through*; the right-most arm is evaluated as a plain read under the premise
// `¬isset` of every arm to its left. So the left arms stay silent on every surface
// and the final arm is judged — under S5's accumulated premise ladder, which is
// what makes the disjunctive-assert pattern clean rather than a wolf cry.
// ---------------------------------------------------------------------------

/// Render the evidence + consequence clauses shared by both strict-leg ids, in the
/// offset family's established message discipline (see `check_offset_read`): what
/// the declaration says, then what PHP does at runtime, quoted verbatim.
fn strict_leg_message(kind: &str, base: &str, shape: &ShapeFact, canon: &VKey) -> String {
    let (our_key, php_key) = render_offset_key(canon);
    let declared = render_shape_fact(shape, false);
    // `{base} is {declared}` mirrors `offset.missing`'s own evidence clause. The
    // spelling is the shape fact's, which may differ from the source text (a
    // sealed shape's head is canonicalized, and issue #163 takes it from the
    // shape's own `is_list`) — the same rendering the dump surface shows, so the
    // two never disagree about what Steins believes.
    match kind {
        "undeclared" => format!(
            "offset {our_key} is outside the declared shape — {base} is {declared}, which cannot carry the key; reads null with \"Undefined array key {php_key}\""
        ),
        "coalesce" => format!(
            "offset {our_key} may be missing on the final `??` arm — {base} is {declared}, which declares the key optional, and nothing to the left of this arm discharges it; reads null with \"Undefined array key {php_key}\""
        ),
        _ => format!(
            "offset {our_key} may be missing — {base} is {declared}, which declares the key optional, and no guard on this path discharges it; reads null with \"Undefined array key {php_key}\""
        ),
    }
}

/// Judge one whitelisted **plain** read `base[key]` against the declared shape and
/// emit at most one strict-leg finding (ADR-0062 S6).
///
/// Deliberately NOT gated on [`Folder::absence_family_available`], unlike the proof
/// leg: A9's gate exists because a monkey-patched runtime can invalidate a
/// *value-domain* absence proof. This leg's evidence is the docblock, which no
/// sidecar posture can move, so gating it would withhold a contract claim for a
/// reason that does not apply to it.
fn check_shape_read(
    cx: &Cx,
    base: &ArgValue,
    key: &ArgValue,
    env: &HashMap<String, Known>,
    poisoned: bool,
    span: Span,
    out: &mut Vec<Diagnostic>,
) {
    let Some((shape, canon, _)) = shape_site_at(base, key, env, poisoned, cx.php_minor) else {
        return;
    };
    let rendered = base.render();
    match shape_read(shape, &canon) {
        // Proven present (declared Required, or promoted by an S4 guard / S5 cover),
        // or an unsealed tail's value (out of v1 scope): silent.
        ShapeRead::Present(_) | ShapeRead::Tail(_) => {}
        ShapeRead::DeclaredAbsent => emit_offset(
            cx,
            span,
            OFFSET_UNDECLARED_ID,
            OffsetGrade::Warning,
            strict_leg_message("undeclared", &rendered, shape, &canon),
            out,
        ),
        // A plain read carries no `¬isset` premises — a discharged optional key is
        // already `Present` here (S4 promotion / S5 collapse), so reaching this arm
        // IS the "no proof on this path" statement.
        ShapeRead::MaybeMissing(_) => emit_offset(
            cx,
            span,
            OFFSET_MAYBE_MISSING_ID,
            OffsetGrade::Warning,
            strict_leg_message("maybe-missing", &rendered, shape, &canon),
            out,
        ),
    }
}

/// Judge the **right-most arm** of a `??` chain in a whitelisted value position
/// (ADR-0062 S6, issue #51 §2).
///
/// The arm walk mirrors [`eval_coalesce_fact`]'s exactly — same projection test,
/// same premise accumulation, same invalidation on a non-projection arm, same
/// settle-and-stop — because the two must agree on which arm PHP actually
/// evaluates. Only the final arm can produce a finding; every arm before it is
/// protected by the operator.
fn check_coalesce_final_arm(
    cx: &Cx,
    value: &ArgValue,
    env: &HashMap<String, Known>,
    poisoned: bool,
    span: Span,
    out: &mut Vec<Diagnostic>,
) {
    let mut arms: Vec<&ArgValue> = Vec::new();
    flatten_coalesce(value, &mut arms);
    let Some(last) = arms.len().checked_sub(1) else { return };

    let mut premises: Vec<(String, VKey)> = Vec::new();
    for (i, arm) in arms.iter().enumerate() {
        let projection = coalesce_projection(arm, env, poisoned, cx.php_minor);
        if i == last {
            let Some((var, canon)) = projection else { return };
            judge_coalesce_final(cx, &var, &canon, env, &premises, span, out);
            return;
        }
        match projection {
            Some((var, canon)) => {
                // A projection arm the shape proves present AND non-null IS the
                // value: `??` never evaluates anything to its right, so the final
                // arm is dead code and judging it would be a wolf cry.
                if coalesce_arm_settles(&var, &canon, env) {
                    return;
                }
                premises.push((var, canon));
            }
            // A non-projection arm may write through a reference or a global, so
            // every accumulated `¬isset` goes stale (A-G11's conservatism).
            None => premises.clear(),
        }
    }
}

/// Whether a non-final projection arm settles the chain — the emitter's reading of
/// [`eval_coalesce_fact`]'s `settled`, kept spelling-identical so the two lanes
/// cannot drift about which arms are reachable.
fn coalesce_arm_settles(var: &str, key: &VKey, env: &HashMap<String, Known>) -> bool {
    let Some(known) = env.get(var) else { return false };
    let Some(Fact::Shape { shape, nullable: false }) = &known.fact else { return false };
    matches!(shape_read(shape, key), ShapeRead::Present(Some(f)) if f.is_null().is_no())
}

/// Emit for the final `??` arm, consuming S5's premise ladder as its discharge.
fn judge_coalesce_final(
    cx: &Cx,
    var: &str,
    canon: &VKey,
    env: &HashMap<String, Known>,
    premises: &[(String, VKey)],
    span: Span,
    out: &mut Vec<Diagnostic>,
) {
    let Some(known) = env.get(var) else { return };
    let Some(Fact::Shape { shape, nullable: false }) = &known.fact else { return };
    let rendered = format!("${var}");
    match shape_read(shape, canon) {
        ShapeRead::Present(_) | ShapeRead::Tail(_) => {}
        ShapeRead::DeclaredAbsent => emit_offset(
            cx,
            span,
            OFFSET_UNDECLARED_ID,
            OffsetGrade::Warning,
            strict_leg_message("undeclared", &rendered, shape, canon),
            out,
        ),
        ShapeRead::MaybeMissing(_) => {
            // The `¬isset` ladder over THIS base, exactly as `coalesce_arm_fact`
            // builds it — the S5 discharge, asked as a presence question.
            let absent: Vec<VKey> =
                premises.iter().filter(|(v, _)| v == var).map(|(_, k)| k.clone()).collect();
            if cover_discharges(shape, canon, &absent).is_none() {
                emit_offset(
                    cx,
                    span,
                    OFFSET_MAYBE_MISSING_ID,
                    OffsetGrade::Warning,
                    strict_leg_message("coalesce", &rendered, shape, canon),
                    out,
                );
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Shape narrowing (ADR-0062 S4): guards on the fact lane, subtraction on the
// arm lane, and the collapse that mints one from the other.
//
// Two lanes, one pass. A binding whose declaration has ONE array arm carries a
// `Fact::Shape` in the env and is refined by the domain's narrowing operators;
// a binding whose declaration has SEVERAL array arms carries none — the union
// lives in the arm lane (A-G3) — and is refined by deleting arms. The moment
// subtraction leaves exactly one array arm the two meet: `seed_shape_fact`
// mints the fact, and the same guard that did the subtraction then promotes it.
//
// **Reachability is deliberately untouched.** None of this feeds `eval_cond`,
// `mark_dead`, or the dead-region set. A shape fact is `Asserted` (A-G9's
// corollary), and a dead region computed from an `Asserted` premise would let
// the env-free direct pass stop reporting on a live path — an FP class that must
// stay closed. `Fact::truthy` / `is_null` / `int_in` /
// `satisfies_str` are *decisive* on `Fact::Shape` (`truthy` reads `non_empty`,
// the other three answer `No` outright), so the first caller that routes a
// shape fact into a verdict re-opens exactly that question; the tripwire test
// `shape_facts_do_not_decide_guard_verdicts` in `tests/shape_guards.rs` is
// what makes that a deliberate decision rather than a silent one.
// ---------------------------------------------------------------------------

/// Which presence predicate a guard tests — A-G8's flavor discipline applied to
/// guards rather than covers.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PresenceFlavor {
    /// `isset($x[k])`: the key is present **and its value is not null**.
    Isset,
    /// `array_key_exists(k, $x)`: the key exists; the value may be null.
    KeyExists,
}

/// One guard form S4 consumes, already resolved to a branch polarity.
#[derive(Debug, Clone, PartialEq)]
enum ShapeGuard {
    /// A key-presence guard (A-G3).
    Present { var: String, key: VKey, flavor: PresenceFlavor, positive: bool },
    /// `if ($x)` on an array binding.
    Truthy { var: String, positive: bool },
    /// `array_is_list($x)` — the RFC's C1 flag flip.
    IsList { var: String, positive: bool },
    /// A constant-key projection guard (A-G4): `$x[k] === <lit>`, or a
    /// `match`/`switch` arm on `$x[k]`. Several tags come from a stacked arm
    /// (`case 1: case 2:` / `1, 2 => …`); `loose` is the `switch` reading.
    Tag { var: String, key: VKey, tags: Vec<ArgValue>, loose: bool },
    /// A **disjunctive**-presence guard (A-G8, S5): `isset($x['a']) ||
    /// isset($x['b'])` and its `array_key_exists` twin, over ONE binding, at
    /// truth polarity. `flavor` is the weakest claim every disjunct implies — a
    /// mixed disjunction reads as [`PresenceFlavor::KeyExists`], because
    /// `isset(k)` implies `k` exists but not conversely.
    Cover { var: String, keys: Vec<VKey>, flavor: PresenceFlavor },
    /// `array_all($x, $f)` falsy / `array_any($x, $f)` truthy (A8, ADR-0062
    /// §4, PHP 8.4): the ONE unconditional leg of each — `array_all([], f)`
    /// and `array_any([], f)` are respectively always true and always false,
    /// so only the branch that leg refutes proves `$x` non-empty. The opposite
    /// (vacuous-on-empty) branch is never recorded — [`collect_shape_guards`]
    /// pushes this only at the firing polarity, so its absence on that branch
    /// is silence, not a claim.
    NonEmpty { var: String },
}

impl ShapeGuard {
    fn var(&self) -> &str {
        match self {
            ShapeGuard::Present { var, .. }
            | ShapeGuard::Truthy { var, .. }
            | ShapeGuard::IsList { var, .. }
            | ShapeGuard::Tag { var, .. }
            | ShapeGuard::Cover { var, .. }
            | ShapeGuard::NonEmpty { var, .. } => var,
        }
    }
}

/// A guard's literal key, canonicalized by PHP's own key rule — the SAME
/// [`offset_key_of`] the read side uses, so a guard and a read can never
/// disagree about which key they mean.
fn guard_key(arg: &ArgValue, php_minor: Option<(u16, u16)>) -> Option<VKey> {
    offset_key_of(&val_of(arg, php_minor)?)
}

/// The recognized array-predicate a guard call names, or `None` for a call that
/// does not denote the global builtin ([`global_function_callee`]: a
/// `Foo\array_key_exists` or a same-named user function is a different function).
fn array_guard_predicate(cx: &Cx, call: &CallExpr) -> Option<&'static str> {
    let callee = global_function_callee(cx, call)?;
    if !call.positional_only {
        return None;
    }
    ["array_key_exists", "key_exists", "array_is_list"]
        .into_iter()
        .find(|p| callee.eq_ignore_ascii_case(p))
}

/// The recognized `array_all`/`array_any` name a guard call names (A8), through
/// the same [`global_function_callee`] as [`array_guard_predicate`] — kept as a
/// separate lookup because the two calls have a different arity (`$array,
/// $callback`) and a different firing rule than the presence/list-flag guards.
fn array_all_any_predicate(cx: &Cx, call: &CallExpr) -> Option<&'static str> {
    let callee = global_function_callee(cx, call)?;
    if !call.positional_only {
        return None;
    }
    ["array_all", "array_any"].into_iter().find(|p| callee.eq_ignore_ascii_case(p))
}

/// Collect the shape guards a condition establishes at polarity `then`.
///
/// The polarity walk is `collect_refine`'s, verbatim in structure: `Not` flips,
/// `And` contributes on the true path, `Or` on the false one (De Morgan).
/// Everything else contributes nothing, so an unmodeled condition
/// narrows nothing rather than narrowing wrongly.
fn collect_shape_guards(
    cx: &Cx,
    cond: &CondExpr,
    then: bool,
    out: &mut Vec<ShapeGuard>,
) {
    let php_minor = cx.php_minor;
    match cond {
        CondExpr::Isset { var, key } => {
            if let Some(k) = guard_key(key, php_minor) {
                out.push(ShapeGuard::Present {
                    var: var.clone(),
                    key: k,
                    flavor: PresenceFlavor::Isset,
                    positive: then,
                });
            }
        }
        CondExpr::Truthy(CondOperand::Var(v)) => {
            out.push(ShapeGuard::Truthy { var: v.clone(), positive: then });
        }
        // `$x[k] === <lit>` and its negation-by-polarity twin `!($x[k] !== <lit>)`.
        // Only the *positive* reading of a tag guard subtracts: knowing the tag is
        // NOT `'circle'` kills an arm only if that arm's tag slot admits nothing
        // else, which is a residue question A-G4 does not open in v1.
        CondExpr::Cmp { op, lhs, rhs } => {
            let positive = match op {
                CmpOp::Identical | CmpOp::Loose => then,
                CmpOp::NotIdentical | CmpOp::NotLoose => !then,
                _ => return,
            };
            let loose = matches!(op, CmpOp::Loose | CmpOp::NotLoose);
            if !positive {
                return;
            }
            let (offset, lit) = match (lhs, rhs) {
                (CondOperand::Offset { var, key }, CondOperand::Literal(v))
                | (CondOperand::Literal(v), CondOperand::Offset { var, key }) => {
                    ((var, key), v)
                }
                _ => return,
            };
            if let Some(k) = guard_key(offset.1, php_minor) {
                out.push(ShapeGuard::Tag {
                    var: offset.0.clone(),
                    key: k,
                    tags: vec![lit.clone()],
                    loose,
                });
            }
        }
        CondExpr::Call { call, .. } => {
            if let Some(pred) = array_guard_predicate(cx, call) {
                match pred {
                    "array_key_exists" | "key_exists" => {
                        if call.args.len() != 2 {
                            return;
                        }
                        let ArgValue::Var(var) = &call.args[1].value else { return };
                        if let Some(k) = guard_key(&call.args[0].value, php_minor) {
                            out.push(ShapeGuard::Present {
                                var: var.clone(),
                                key: k,
                                flavor: PresenceFlavor::KeyExists,
                                positive: then,
                            });
                        }
                    }
                    _ => {
                        if call.args.len() != 1 {
                            return;
                        }
                        if let ArgValue::Var(var) = &call.args[0].value {
                            out.push(ShapeGuard::IsList { var: var.clone(), positive: then });
                        }
                    }
                }
                return;
            }
            // A8: `array_all` fires on its falsy branch (`array_all([], f)` is
            // vacuously true, so falsy means at least one element existed and
            // failed); `array_any` fires on its truthy branch (`array_any([],
            // f)` is vacuously false). The opposite branch of each is a vacuity
            // trap — it proves nothing about emptiness — so it pushes no guard.
            if let Some(pred) = array_all_any_predicate(cx, call) {
                if call.args.len() != 2 {
                    return;
                }
                let fires = match pred {
                    "array_all" => !then,
                    "array_any" => then,
                    _ => false,
                };
                if fires && let ArgValue::Var(var) = &call.args[0].value {
                    out.push(ShapeGuard::NonEmpty { var: var.clone() });
                }
            }
        }
        CondExpr::Not(c) => collect_shape_guards(cx, c, !then, out),
        CondExpr::And(a, b) if then => {
            collect_shape_guards(cx, a, then, out);
            collect_shape_guards(cx, b, then, out);
        }
        // De Morgan: `¬(isset a ∨ isset b)` is `¬isset a ∧ ¬isset b`, so the false
        // branch of a disjunction is just both disjuncts at false polarity — the
        // per-key S4 narrowing, distributed by the walk itself. Nothing S5-specific
        // is needed here; the cover lives on the TRUE branch only.
        CondExpr::Or(a, b) if !then => {
            collect_shape_guards(cx, a, then, out);
            collect_shape_guards(cx, b, then, out);
        }
        // The true branch of a disjunction (A-G8, S5). Individually a disjunct
        // proves nothing — either could be the false one — so the ONLY thing
        // recorded is the disjunctive fact itself.
        CondExpr::Or(..) if then => {
            if let Some(g) = disjunctive_cover(cx, cond) {
                out.push(g);
            }
        }
        _ => {}
    }
}

/// One disjunct of a truth-context `||` chain, as A-G11's v1 scope admits it: a
/// depth-1 constant-key presence test over a named binding.
type PresenceDisjunct = (String, VKey, PresenceFlavor);

/// Flatten a `||` chain into its presence disjuncts. `false` — and the whole
/// cover is abandoned — the moment ANY disjunct is something else: a non-presence
/// condition (`isset($x['a']) || $y`), a deeper path, or a key that does not
/// resolve to a constant. A disjunction is only as strong as its weakest disjunct,
/// so one unmodelled arm makes the whole claim unrecordable rather than partial.
fn presence_disjuncts(cx: &Cx, cond: &CondExpr, out: &mut Vec<PresenceDisjunct>) -> bool {
    match cond {
        CondExpr::Or(a, b) => {
            presence_disjuncts(cx, a, out) && presence_disjuncts(cx, b, out)
        }
        CondExpr::Isset { var, key } => match guard_key(key, cx.php_minor) {
            Some(k) => {
                out.push((var.clone(), k, PresenceFlavor::Isset));
                true
            }
            None => false,
        },
        CondExpr::Call { call, .. } => {
            let Some(pred) = array_guard_predicate(cx, call) else { return false };
            if !matches!(pred, "array_key_exists" | "key_exists") || call.args.len() != 2 {
                return false;
            }
            let ArgValue::Var(var) = &call.args[1].value else { return false };
            match guard_key(&call.args[0].value, cx.php_minor) {
                Some(k) => {
                    out.push((var.clone(), k, PresenceFlavor::KeyExists));
                    true
                }
                None => false,
            }
        },
        _ => false,
    }
}

/// The [`ShapeGuard::Cover`] a truth-context disjunction records, or `None` when
/// A-G11's v1 scope declines it.
///
/// Three conditions, each a soundness requirement rather than a convenience:
///
/// * **every** disjunct is a modelled presence test (see [`presence_disjuncts`]);
/// * they all test the **same** binding — a cover is a fact about one array, and
///   `isset($x['a']) || isset($y['b'])` says nothing about either;
/// * at least two distinct keys remain, so the claim really is disjunctive (a
///   singleton would be presence, which the domain's `normalize` promotes anyway).
///
/// Flavor is the **weakest** claim every disjunct implies: all-`isset` gives an
/// Isset-cover ("at least one present and non-null"); any `array_key_exists`
/// disjunct drags the whole cover down to KeyExists, since a present-null entry
/// satisfies that disjunct without satisfying `isset`.
fn disjunctive_cover(cx: &Cx, cond: &CondExpr) -> Option<ShapeGuard> {
    let mut parts: Vec<PresenceDisjunct> = Vec::new();
    if !presence_disjuncts(cx, cond, &mut parts) || parts.len() < 2 {
        return None;
    }
    let var = parts[0].0.clone();
    if parts.iter().any(|(v, _, _)| *v != var) {
        return None;
    }
    let flavor = if parts.iter().all(|(_, _, f)| *f == PresenceFlavor::Isset) {
        PresenceFlavor::Isset
    } else {
        PresenceFlavor::KeyExists
    };
    let mut keys: Vec<VKey> = parts.into_iter().map(|(_, k, _)| k).collect();
    keys.dedup();
    Some(ShapeGuard::Cover { var, keys, flavor })
}

/// **Apply every shape guard of `cond` at polarity `then`** to a branch's cloned
/// env and store. Runs after `apply_refinements` in the branch walk, so a shape
/// operator is the last word on a `Fact::Shape` binding — none of the scalar
/// refinement operators can express anything about one anyway.
///
/// `witnessed` is the **evidence stratum of the condition itself** (ADR-0058's
/// table): `true` for a condition the runtime evaluated — an `if`, an `assert()`
/// — and `false` for one whose only evidence is a docblock, which today means a
/// `@phpstan-assert true $cond` tag on a userland assertion helper. It reaches
/// exactly one operator, [`ShapeFact::promote_present`]; every other narrowing
/// here (arm subtraction, cover recording, `mark_absent`) is already confined to
/// the `Asserted` shape lane, whose stratum is A-G9's corollary and does not vary
/// per guard.
fn apply_shape_narrowing(
    cx: &Cx,
    cond: &CondExpr,
    then: bool,
    env: &mut HashMap<String, Known>,
    store: &mut Store,
    witnessed: bool,
) {
    let mut guards = Vec::new();
    collect_shape_guards(cx, cond, then, &mut guards);
    for g in &guards {
        apply_shape_guard(cx, g, env, store, witnessed);
    }
}

/// One guard, both lanes: subtract the arm lane, mint a fact if the subtraction
/// collapsed the union to one array arm, then refine the fact.
fn apply_shape_guard(
    cx: &Cx,
    g: &ShapeGuard,
    env: &mut HashMap<String, Known>,
    store: &mut Store,
    witnessed: bool,
) {
    subtract_shape_arms(cx, g, store);
    mint_collapsed_shape(g.var(), env, store);
    refine_shape_fact(g, env, witnessed);
}

/// **Arm subtraction** (A-G3/A-G4): delete the arms of `var`'s contract lane the
/// guard proves cannot be the live one. Non-array arms are left alone except for
/// the one case PHP decides — `isset` on an offset of `null` is false, so an
/// `isset`-true branch kills a `null` arm.
///
/// An emptied lane drops to no-fact, never a death signal (ADR-0052 §2).
fn subtract_shape_arms(cx: &Cx, g: &ShapeGuard, store: &mut Store) {
    let Some(arms) = store.contract.get(g.var()) else { return };
    // A single-arm lane has no discrimination to do; leaving it alone keeps the
    // fact lane the only thing this guard can move for the common case.
    if arms.len() < 2 {
        return;
    }
    let kept: Vec<ContractArm> =
        arms.iter().filter(|a| shape_arm_survives(g, &a.ty, cx.php_minor)).cloned().collect();
    if kept.len() == arms.len() {
        return;
    }
    if kept.is_empty() {
        store.contract.remove(g.var());
    } else {
        store.contract.insert(g.var().to_owned(), kept);
    }
}

/// Does `ty` survive `g`? The FP-safe answer is always `true`: an arm dies only
/// on a definite verdict, exactly as ADR-0052 §2's arm deletion does.
fn shape_arm_survives(g: &ShapeGuard, ty: &ContractTy, php_minor: Option<(u16, u16)>) -> bool {
    use steins_domain::Presence;
    let shape = steins_contract::to_shape_fact(ty);
    match g {
        ShapeGuard::Present { key, flavor, positive, .. } => {
            // `isset($x[k])` on a `null` base is false — PHP decides it, so the
            // arm dies. `array_key_exists` on null is a TypeError, not a false
            // verdict, so it kills nothing (the conservative reading).
            if matches!(ty, ContractTy::Null) {
                return !(*positive && *flavor == PresenceFlavor::Isset);
            }
            let Some(shape) = shape else { return true };
            if *positive {
                // Sealed-by-default is what makes the idiom sound (A-G3): an arm
                // that cannot hold `k` at all cannot be the live one.
                arm_can_hold_key(&shape, key)
            } else {
                // The false branch kills arms where `k` is `Required` — for
                // `isset` only when the value cannot be null, because a
                // present-null entry makes `isset` false without the key being
                // absent (the A-G8 S2 flavor correction, applied to guards).
                match shape.field(key) {
                    Some((_, p, slot)) if p.is_required() => match flavor {
                        PresenceFlavor::KeyExists => false,
                        PresenceFlavor::Isset => {
                            !slot.as_ref().is_some_and(|f| f.is_null().is_no())
                        }
                    },
                    _ => true,
                }
            }
        }
        // A tag guard asks the field's declared value contract whether it admits
        // the literal; a `No` verdict kills the arm (A-G4). An undeclared or
        // unknown-slot field answers nothing and keeps it.
        ShapeGuard::Tag { key, tags, loose, .. } => {
            let Some(shape) = shape else { return true };
            let Some((_, presence, Some(slot))) = shape.field(key) else { return true };
            if matches!(presence, Presence::Absent) {
                return false;
            }
            tags.iter().any(|t| tag_possible(slot, t, *loose, php_minor))
        }
        // Truthiness, list-ness, and A8's non-emptiness leg are all properties
        // of the whole array, not of a key, and every array arm can be
        // non-empty or a list for *some* value the arm admits — so v1
        // subtracts nothing here and refines the fact lane only.
        ShapeGuard::Truthy { .. } | ShapeGuard::IsList { .. } | ShapeGuard::NonEmpty { .. } => {
            true
        }
        // **Covers on arms are future work** (A-G8's home for them is inside the
        // shape fact, and A-G3 keeps unions in the arm lane). An arm that can hold
        // NONE of the covered keys is in fact refuted by the disjunction — the
        // same sealed-by-default reasoning `Present { positive: true }` uses — but
        // v1 records covers on a single-shape fact only, so nothing is subtracted
        // here and no discriminated union changes shape because of one.
        ShapeGuard::Cover { .. } => true,
    }
}

/// Can an array admitted by `shape` have the key `k` at all?
fn arm_can_hold_key(shape: &ShapeFact, k: &VKey) -> bool {
    use steins_domain::{Presence, Tail};
    match shape.field(k) {
        Some((_, Presence::Absent, _)) => false,
        Some(_) => true,
        None => match &shape.tail {
            Tail::Sealed => false,
            Tail::Unsealed { key: class, .. } => class.admits_key(k),
        },
    }
}

/// Could the slot's declared value equal the tag? `loose` selects PHP's `==`
/// (the `switch` reading), whose truth set is a superset of `===`'s — so a
/// finite slot is compared through the one comparison judgment ([`eval_cmp`])
/// rather than by `admits`, and an abstract slot under a loose comparison keeps
/// the arm (its truth set is not decidable from the fact alone).
fn tag_possible(slot: &Fact, tag: &ArgValue, loose: bool, php_minor: Option<(u16, u16)>) -> bool {
    match slot.finite_members() {
        Some(members) => {
            let op = if loose { CmpOp::Loose } else { CmpOp::Identical };
            let args: Vec<ArgValue> = members.iter().map(arg_of_val).collect();
            eval_cmp(op, &args, std::slice::from_ref(tag), php_minor) != Certainty::No
        }
        // An abstract slot decides only under `===`, where membership *is* the
        // question `admits` answers.
        None => loose || val_of(tag, php_minor).is_none_or(|v| slot.admits(&v)),
    }
}

/// **The collapse rule** (A-G3): once subtraction leaves a lane whose array
/// vocabulary is one arm, that lane states a single shape truth — so mint it
/// into the fact lane through the S3 lowering ([`seed_shape_fact`], the same one
/// entry-state seeding uses, so a minted fact and a seeded one are identical by
/// construction).
///
/// Only ever *adds* a fact: a binding that already carries one (seeded, or minted
/// by an earlier guard on the same branch) is left to the refinement step, and a
/// binding carrying a non-shape fact — a proven `Singleton` array, say — is
/// strictly better information and is never overwritten.
fn mint_collapsed_shape(var: &str, env: &mut HashMap<String, Known>, store: &Store) {
    if env.get(var).is_some_and(|k| k.fact.is_some()) {
        return;
    }
    let Some(arms) = store.contract.get(var) else { return };
    let Some(fact) = seed_shape_fact(arms) else { return };
    let line = env.get(var).map_or(0, |k| k.line);
    env.insert(
        var.to_owned(),
        // `Asserted`, for the same reason entry-state seeding is: A-G9's
        // corollary is normative, and the stratum is what enforces it.
        Known::value_strat(fact, line, Some(SHAPE_REFINED.to_owned()), Stratum::Asserted),
    );
}

/// **Fact-lane refinement**: apply the guard's domain operator to `var`'s
/// `Fact::Shape`, if it has one. Every operator is a narrowing
/// (`crates/steins-domain/src/shape.rs`), so the result admits everything the
/// binding admitted that satisfies the guard.
fn refine_shape_fact(g: &ShapeGuard, env: &mut HashMap<String, Known>, witnessed: bool) {
    use steins_domain::Presence;
    let Some(known) = env.get(g.var()) else { return };
    let Some(Fact::Shape { shape, nullable }) = &known.fact else { return };
    let (shape, nullable) = (shape.as_ref(), *nullable);
    let next = match g {
        ShapeGuard::Present { key, flavor, positive: true, .. } => Some(Fact::Shape {
            shape: Box::new(shape.promote_present(
                key,
                *flavor == PresenceFlavor::Isset,
                witnessed,
            )),
            // `isset($x[k])` is false when `$x` is null, so the true branch also
            // proves the base non-null. `array_key_exists` on null raises a
            // TypeError rather than answering false, so it proves nothing here.
            nullable: nullable && *flavor == PresenceFlavor::KeyExists,
        }),
        ShapeGuard::Present { key, flavor, positive: false, .. } => {
            match (flavor, shape.field(key)) {
                // `!array_key_exists(k, $x)` tests key existence and nothing
                // else: the key is proven absent whatever its declared value.
                (PresenceFlavor::KeyExists, _) => {
                    Some(Fact::Shape { shape: Box::new(shape.mark_absent(key)), nullable })
                }
                // `!isset($x[k])` on an optional non-nullable slot: the only way
                // the guard can be false is the key being absent.
                (PresenceFlavor::Isset, Some((_, Presence::Optional, slot)))
                    if slot.as_ref().is_some_and(|f| f.is_null().is_no()) =>
                {
                    Some(Fact::Shape { shape: Box::new(shape.mark_absent(key)), nullable })
                }
                // A `Required` field with a non-nullable slot makes this branch
                // runtime-impossible. **Deliberate v1 conservatism**: the env is
                // left unchanged rather than the region marked dead. Death is the
                // verdict's business (ADR-0052 §2), the premise here is `Asserted`
                // (A-G9), and an `Asserted`-derived dead region would stop the
                // env-free direct pass from reporting on a live path.
                _ => None,
            }
        }
        ShapeGuard::Truthy { positive: true, .. } => {
            Some(Fact::Shape { shape: Box::new(shape.set_non_empty()), nullable })
        }
        // A falsy array is the empty array — but only when the base cannot be
        // null, since `null` is falsy too and would make the claim wrong.
        ShapeGuard::Truthy { positive: false, .. } => {
            (!nullable).then(|| Fact::Singleton(Val::Array(Vec::new())))
        }
        ShapeGuard::IsList { positive, .. } => Some(Fact::Shape {
            shape: Box::new(shape.set_is_list(Certainty::from_bool(*positive))),
            nullable,
        }),
        // A8: the guard only ever fires on the leg that proves non-emptiness
        // (collect_shape_guards never pushes it on the vacuous branch), so
        // there is no positive/negative split to make here — unlike
        // `Truthy`, whose false branch also needs a distinct (empty-array)
        // reading. The concrete/value lane is untouched: `array_all`/
        // `array_any` say nothing about entry order or values, only that at
        // least one entry exists.
        ShapeGuard::NonEmpty { .. } => {
            Some(Fact::Shape { shape: Box::new(shape.set_non_empty()), nullable })
        }
        // The S5 recording (A-G8): the disjunction's own claim, stored on the
        // fact for A-G11's `??` discharge to consume.
        ShapeGuard::Cover { keys, flavor, .. } => Some(Fact::Shape {
            shape: Box::new(shape.record_cover(
                keys.clone(),
                match flavor {
                    PresenceFlavor::Isset => CoverFlavor::Isset,
                    PresenceFlavor::KeyExists => CoverFlavor::KeyExists,
                },
            )),
            // The WHOLE disjunction being true means at least one `isset` returned
            // true — and `isset` on an offset of `null` is false — so an all-`isset`
            // disjunction proves the base is a non-null array. (A single *false*
            // `isset($x['a'])` would prove nothing of the sort; it is the truth of
            // the disjunction, not of any one disjunct, that carries this.) An
            // `array_key_exists` disjunct raises a TypeError on `null` rather than
            // answering, so a KeyExists-flavored cover proves nothing here —
            // exactly the reading `Present { positive: true }` already takes.
            nullable: nullable && *flavor == PresenceFlavor::KeyExists,
        }),
        // A tag guard's job is arm subtraction; the collapsed arm's own slot is
        // already the declared literal, so refining the fact adds nothing v1.
        ShapeGuard::Tag { .. } => None,
    };
    let Some(next) = next else { return };
    let (line, stratum) = (known.line, known.stratum);
    env.insert(
        g.var().to_owned(),
        Known::value_strat(next, line, Some(SHAPE_REFINED.to_owned()), stratum),
    );
}

// ---------------------------------------------------------------------------
// Write invalidation (ADR-0062 A-G8's table)
// ---------------------------------------------------------------------------

/// `$var[k] = v` / `$var[k1][k2] = v` and `unset($var[k])`.
///
/// **Barrier first, then one binding.** The walk still clears the whole env and
/// store, exactly as the pre-S4 `Barrier` lowering did — an offset write can
/// alias through references the trace does not model — and only then puts back
/// the base binding's array shape with the key promoted or removed. That order
/// is the containment: this rule can move the shape lane and nothing else, so a
/// finding that did not premise a shape fact cannot move with it.
///
/// The by-ref sweep needs no separate fence: everything is dropped before
/// anything is restored, and the restore reads facts captured *before* the
/// clear, so a by-ref exposure that dropped the fact earlier in the walk leaves
/// nothing to restore.
fn apply_offset_write(
    w: &WalkCx,
    folder: &mut dyn Folder,
    base: &str,
    keys: &[ArgValue],
    value: Option<&ArgValue>,
    env: &mut HashMap<String, Known>,
    store: &mut Store,
) {
    use steins_domain::{KeyClass, Tail};
    let php_minor = w.cx.php_minor;
    // Capture before the barrier clears everything.
    let before = env.get(base).cloned();
    let arms = store.contract.get(base).cloned();
    // The written value's fact, resolved in the PRE-write env through the same
    // ladder an ordinary assignment uses; `None` (an unresolvable rvalue, or the
    // `unset` case) leaves the slot unknown, which is the honest floor.
    let slot = value.and_then(|v| {
        w.cx.resolve_literal(v, env, w.scope.poisoned, folder).and_then(|lit| singleton_fact(&lit, php_minor))
    });

    env.clear();
    store.clear();

    let Some(known) = before else { return };
    let Some(Fact::Shape { shape, nullable }) = &known.fact else { return };
    let Some(first) = keys.first().and_then(|k| guard_key(k, php_minor)) else { return };

    let next = match value {
        None => {
            // `unset($x[k])` — the key is proven gone. Cover interplay (a cover
            // containing `k` dies with it, A-G8) is handled inside `mark_absent`;
            // the *sharper* law that shrinks a cover instead of dropping it is
            // S5's, with the rest of the cover lane.
            shape.mark_absent(&first)
        }
        Some(_) => {
            // A write makes the key real: `Required { witnessed: true }` with the
            // value's own fact. A nested write (`$x['a']['b'] = v`) autovivifies
            // the OUTER key and **clears its slot**: the inner array just changed
            // in a way the declared slot may no longer describe (a `string` written
            // under `array<string, int>`), so carrying the declaration across would
            // state something the write may have falsified. Unknown is the honest
            // floor; a real nested-shape update is not v1.
            let nested = keys.len() > 1;
            let mut next = shape.promote_present(&first, false, true);
            // Writing an UNDECLARED key under a `Sealed` tail: the declaration
            // says the key cannot be there and the code just put it there, so the
            // runtime value has diverged from the docblock. Resolved the A-G5
            // way — "flow refinement lives in the domain form": the write is
            // order-witnessed truth, so the field is added AND the tail unseals.
            // Keeping `Sealed` would leave a fact that rejects the very array the
            // code just built; unsealing is sound and loses only the declared
            // sealing, on this binding, from this point on.
            if next.field(&first).is_none() {
                next = ShapeFact::normalize(
                    next.fields.clone(),
                    Tail::Unsealed { key: KeyClass::ArrayKey, value: None },
                    next.is_list,
                    next.non_empty,
                    next.covers.clone(),
                )
                .promote_present(&first, false, true);
            }
            if nested { set_slot_fact(&next, &first, None) } else { set_slot_fact(&next, &first, slot) }
        }
    };
    env.insert(
        base.to_owned(),
        Known::value_strat(
            Fact::Shape { shape: Box::new(next), nullable: *nullable },
            known.line,
            Some(SHAPE_REFINED.to_owned()),
            known.stratum,
        ),
    );
    if let Some(arms) = arms {
        store.contract.insert(base.to_owned(), arms);
    }
}

/// Replace one field's value slot, keeping every other component. `None` sets the
/// unknown floor. The field is known to exist (the caller promoted it first), so
/// a miss is a no-op.
fn set_slot_fact(shape: &ShapeFact, key: &VKey, fact: Option<Fact>) -> ShapeFact {
    let fields = shape
        .fields
        .iter()
        .map(|(k, p, slot)| {
            if k == key {
                (k.clone(), *p, fact.clone().map(Box::new))
            } else {
                (k.clone(), *p, slot.clone())
            }
        })
        .collect();
    ShapeFact::normalize(
        fields,
        shape.tail.clone(),
        shape.is_list,
        shape.non_empty,
        shape.covers.clone(),
    )
}

/// Whether a normalized array-entry list contains `key` (the read-side membership
/// check, over the already-canonical [`VKey`]s the domain stores).
fn array_has_key(entries: &[(VKey, Val)], key: &VKey) -> bool {
    entries.iter().any(|(k, _)| k == key)
}

/// The `Val` inside a `Singleton` fact (for rendering the container); a no-op clone
/// guarded by the caller having matched `Singleton`.
fn base_fact_val(f: &Fact) -> Val {
    match f {
        Fact::Singleton(v) => v.clone(),
        _ => Val::Null,
    }
}

/// Emit one offset finding, honoring the `warning-handler` posture (ADR-0049 §7):
/// under `"null"` (`!warning_handler_abort`) a warning-grade finding leaves the
/// proof surface and is not emitted; a `Fatal`-grade finding would emit under both
/// (none are currently produced).
fn emit_offset(
    cx: &Cx,
    span: Span,
    id: &'static str,
    grade: OffsetGrade,
    message: String,
    out: &mut Vec<Diagnostic>,
) {
    if grade == OffsetGrade::Warning && !cx.warning_handler_abort {
        return;
    }
    let pos = cx.tree().position(span.start);
    out.push(Diagnostic { id, path: cx.path().to_owned(), line: pos.line, column: pos.column, message, facet: None, fix: None });
}

/// Outcome of a resolved method/static call (ADR-0075): the return-fact summary
/// **and** the declared return arms, both computed against the store **before**
/// the assignment may unbind a self-assign receiver (`$o = $o->m(1)`).
struct MethodCallOutcome {
    summary: Option<ReturnSummary>,
    return_arms: Option<Vec<ContractArm>>,
}

/// Check + descend one method / static / constructor call. Returns the callee's
/// summary and declared return arms when the target resolves (ADR-0075). Constructors
/// still descend for diagnostics; the walk-trace leaves their outcome unread
/// (ADR-0075 §3 — construction is the ADR-0036 exactness lane).
#[allow(clippy::too_many_arguments)]
fn handle_method_call(
    cx: &Cx,
    folder: &mut dyn Folder,
    scope: &Scope,
    call: &CallExpr,
    env: &HashMap<String, Known>,
    store: &Store,
    this_exact: Option<&str>,
    enclosing_class: Option<&str>,
    descent: Option<&mut Descent<'_>>,
    out: &mut Vec<Diagnostic>,
) -> MethodCallOutcome {
    let empty = MethodCallOutcome { summary: None, return_arms: None };
    let Some(target) =
        resolve_call_target(cx, &call.receiver, store, this_exact, enclosing_class, scope.poisoned)
    else {
        return empty;
    };

    // Capture arms at resolution — before any later store mutation at the assign site.
    let return_arms = if matches!(call.receiver, Callee::Construct { .. }) {
        None
    } else {
        method_return_arms(cx, &target)
    };

    let callee_name = format!("{}::{}", target.declaring_class.name, target.method.name);
    let class_templates = template_names_of(target.declaring_class.docblock.as_deref());
    // The argument-contract check runs for every argument shape — the positional
    // prefix and the named arguments (Gap A: `new Foo(n: 0)` / `$o->m(n: 0)` were
    // previously skipped wholesale by the `positional_only` guard below).
    check_method_args(
        cx,
        folder,
        target.method,
        target.class_file,
        &class_templates,
        &callee_name,
        call,
        env,
        store,
        scope.poisoned,
        descent.is_some(),
        out,
    );

    // The binding descent maps positional arguments to parameters, so it stays
    // positional-only (a named/spread call's parameter binding is not modeled here);
    // the contract check above already covered the arguments.
    if !call.positional_only {
        return MethodCallOutcome { summary: None, return_arms };
    }
    let Some(callee_scope) =
        cx.method_scope(target.class_file, &target.declaring_class.fqn, &target.method.name)
    else {
        return MethodCallOutcome { summary: None, return_arms };
    };
    let display = display_of_call(&call.receiver, &target.declaring_class.name, &target.method.name);
    // ADR-0075: the same `descend` path functions use; the walk-trace rebinds the
    // summary for method/static calls and leaves constructors unread.
    let arg_values: Vec<&ArgValue> = call.args.iter().map(|a| &a.value).collect();
    let summary = descend(
        cx,
        folder,
        &target.method.params,
        target.class_file,
        callee_scope,
        &format!("{}::{}", target.declaring_class.fqn, target.method.name),
        &display,
        target.this_exact,
        &arg_values,
        call.span.start,
        &[],
        env,
        scope.poisoned,
        descent,
        out,
    );
    MethodCallOutcome { summary, return_arms }
}

/// The provenance render base for a bound method/constructor call.
fn display_of_call(receiver: &Callee, declaring_class: &str, method: &str) -> String {
    match receiver {
        Callee::Construct { class } => format!("new {}", class.simple()),
        _ => format!("{declaring_class}::{method}"),
    }
}

/// Check the arguments of a resolved method/constructor call at its call site
/// (native runtime check plus the phpdoc declared-contract check; no double-report).
/// `class_file` locates the callee method's docblock context for class-name
/// resolution.
#[allow(clippy::too_many_arguments)]
fn check_method_args(
    cx: &Cx,
    folder: &mut dyn Folder,
    method: &MethodDecl,
    class_file: usize,
    class_templates: &HashSet<String>,
    callee_name: &str,
    call: &CallExpr,
    env: &HashMap<String, Known>,
    store: &Store,
    poisoned: bool,
    in_descent: bool,
    out: &mut Vec<Diagnostic>,
) {
    let mut envelopes = parse_envelopes(method.docblock.as_deref());
    // Class-level `@template` names shadow same-named classes in every member
    // docblock of the class-like (issue #5) — the second, idempotent shadow stage.
    if let Some(e) = &mut envelopes {
        e.shadow_templates(class_templates);
    }
    for (i, arg) in call.args.iter().enumerate() {
        let Some(param) = method.params.get(i) else { break };
        if param.variadic {
            break;
        }
        if param.by_ref {
            continue;
        }

        let mut native_fired = false;
        if let Some(ty) = param.ty.as_ref() {
            // Resolved value + provenance + trust stratum (issue #127 review): the
            // proof gate uses the stratum that arrived with the resolution, not a
            // syntactic re-read that would launder an Asserted fold to Verified.
            let resolved: Option<(ArgValue, Option<String>, Stratum)> = match &arg.value {
                v if v.is_literal() => Some((v.clone(), None, Stratum::Verified)),
                ArgValue::Var(name) if !poisoned => env.get(name).and_then(|k| {
                    let v = k.singleton()?;
                    let prov = match &k.bound {
                        Some(b) => format!("from ${name}, {b}"),
                        None => format!("from ${name}, assigned at line {}", k.line),
                    };
                    Some((v, Some(prov), k.stratum))
                }),
                ArgValue::Call(name, args) => {
                    if args.is_empty() {
                        cx.resolve_const_fn(name)
                            .map(|(lit, line)| {
                                (
                                    lit,
                                    Some(format!("from {name}(), defined at line {line}")),
                                    Stratum::Verified,
                                )
                            })
                            .or_else(|| {
                                cx.try_fold_emit(name, args, env, poisoned, folder, out)
                                    .map(|(l, p, s)| (l, Some(p), s))
                            })
                    } else {
                        cx.try_fold_emit(name, args, env, poisoned, folder, out)
                            .map(|(l, p, s)| (l, Some(p), s))
                    }
                }
                // A property read `$o->p` (ADR-0036): a `Singleton` prop fact flows.
                ArgValue::PropFetch { var, prop } if !poisoned => {
                    store.prop_fact(var, prop).and_then(|f| match f {
                        Fact::Singleton(v) => Some((
                            arg_of_val(v),
                            Some(format!("from ${var}->{prop}")),
                            store.prop_stratum(var, prop),
                        )),
                        _ => None,
                    })
                }
                // A proven object (`new` / enum case) or resolved class constant
                // (ADR-0043 stage 3). Env-free; `self`/`parent` at the call site are
                // not available here, so only a written class name resolves.
                _ => cx
                    .resolve_static_value(&arg.value, None)
                    .map(|v| (v, None, Stratum::Verified)),
            };
            // Proof-layer consumption rule (ADR-0052 §5): silent on an `Asserted`
            // premise; the phpdoc contract check below still accepts it.
            if let Some((value, prov, strat)) = resolved
                && strat == Stratum::Verified
                && is_type_error(cx, ty, &value)
                && !object_world_guard_blind(in_descent, ty, &value)
            {
                out.push(cx.diagnostic(
                    arg.span.start,
                    &value,
                    prov.as_deref(),
                    callee_name,
                    &param.name,
                    ty,
                ));
                native_fired = true;
            }
            // A variable bound to a proven object (ADR-0036 heap): the object-vs-type
            // definite-No, rendered against the variable (ADR-0043 stage 3).
            // Guard-blind inside a descent (see `object_world_guard_blind`).
            if !native_fired
                && !poisoned
                && !in_descent
                && let ArgValue::Var(name) = &arg.value
                && store.is_exact(name) // No-side needs exactness (audit G1)
                && let Some(class) = store.class_of(name)
                && cx.object_is_type_error(ty, class)
            {
                out.push(cx.diagnostic(
                    arg.span.start,
                    &ArgValue::Var(name.clone()),
                    Some(&format!("holds a {}", simple_class(class))),
                    callee_name,
                    &param.name,
                    ty,
                ));
                native_fired = true;
            }
        }

        if !native_fired
            && let Some(env_e) = &envelopes
        {
            check_phpdoc_param(
                cx,
                folder,
                env_e,
                param,
                class_file,
                method.span.start,
                callee_name,
                arg.span.start,
                &arg.value,
                env,
                store,
                poisoned,
                in_descent,
                out,
            );
        }
        // Callable-signature variance (issue #11) for a closure / first-class
        // callable argument to a method against a signature-bearing `callable(...)`
        // @param. The closure's declared signature is a static CST fact, so this is
        // safe to run at the resolved call site.
        if let ArgValue::Closure(closure) = &arg.value
            && let Some(env_e) = &envelopes
        {
            check_callable_arg(cx, env_e, param, callee_name, arg.span.start, closure, out);
        }
    }

    // Named arguments (`$o->m(n: <expr>)` / `new Foo(n: <expr>)`, Gap A): bind each
    // to its parameter by name and run the same declared-contract judgment. This is
    // the sole contract lane for method/constructor calls, so no double-report.
    if let Some(env_e) = &envelopes {
        check_named_phpdoc_params(
            cx,
            folder,
            env_e,
            &method.params,
            call.args.len(),
            class_file,
            method.span.start,
            callee_name,
            &call.named_args,
            env,
            store,
            poisoned,
            in_descent,
            out,
        );
    }
}

// ---------------------------------------------------------------------------
// Value / type helpers.
// ---------------------------------------------------------------------------

/// Render a call with its literal arguments for a folding provenance string.
fn render_call(name: &str, args: &[ArgValue]) -> String {
    let inner: Vec<String> = args.iter().map(ArgValue::render).collect();
    format!("{name}({})", inner.join(", "))
}

/// The generalized truth table: does passing (or returning) a **literal** `arg`
/// where a native scalar/union type `ty` is required provably raise a
/// `TypeError` under PHP 8.1+ (honoring `strict`)?
///
/// The table was settled **empirically against PHP 8.5.8** (the analyzer's floor
/// is 8.1, ADR-0011; these union-coercion rules have been stable since 8.0). The
/// reproduction snippets and outputs (union members, both modes):
///
/// ```text
/// COERCIVE (error iff the value coerces to NO member):
///   1.5   -> int|string  => OK  (becomes int 1; the string sink also accepts)
///   1.5   -> string|bool => OK  (becomes '1.5')
///   true  -> int|string  => OK  (becomes int 1)
///   "abc" -> int|float    => TypeError   (non-numeric string, no string sink)
///   "abc" -> int|false    => TypeError   (false-literal accepts only `false`)
///   "5"   -> int|float    => OK  (numeric string coerces)
///   false -> string|false => OK  (matches the `false` literal member exactly)
///   true  -> string|false => OK  (becomes '1' via the string member)
///   null  -> int|string   => TypeError   (non-nullable)
///   0/""/true -> false     => TypeError   (no coercion into a bool-literal)
/// STRICT (value must match SOME member; only int->float widening is implicit):
///   1.5   -> int|string  => TypeError   (float, no float member)
///   true  -> int|string  => TypeError   (bool, no bool/bool-literal member)
///   5     -> int|float    => OK  (int member; also OK via int->float widening)
///   false -> string|false => OK  (matches the `false` literal member)
///   true  -> string|false => TypeError   (`false` literal ≠ `true`; no bool)
///   5     -> string|false => TypeError   (int, no int member)
/// ```
///
/// Uncertain cells resolve to "not an error" (silence is always safe; ADR-0002).
///
/// ADR-0043 stage 3 opens two definite-No arms, both riding the trinary is-a
/// oracle on `cx`: a **proven object value** (`new` / enum case) errors iff every
/// union member provenly rejects its exact class, and a **scalar value** now sees
/// through any `Instance` union members (an object member never accepts a scalar —
/// no coercion exists — so the verdict rests on the scalar members, exactly as the
/// empirically-verified `member_accepts_*` tables already encode via their
/// `Instance => false` arms). A `null` value against an object-bearing type stays
/// silent (null-vs-object is out of scope; preserves the pre-stage-3 behavior and
/// sidesteps the `has_null_default` implicit-nullable interplay).
fn is_type_error(cx: &Cx, ty: &NativeType, arg: &ArgValue) -> bool {
    let strict = cx.strict();
    match arg {
        // `null` is accepted iff the type is nullable (`?T` / `null` member). An
        // object-bearing type stays silent on `null`.
        ArgValue::Null => !ty.nullable && !ty.has_instance(),
        // A concrete non-null literal: an error iff no member accepts it. `Instance`
        // members contribute nothing (they never accept a scalar) — ADR-0043 stage-3
        // scalar-vs-object opening (e.g. a raw string where an enum is required).
        ArgValue::Int(_) | ArgValue::Float(_) | ArgValue::Str(_) | ArgValue::Bool(_) => {
            if strict {
                !ty.members.iter().any(|m| member_accepts_strict(m, arg))
            } else {
                !ty.members.iter().any(|m| member_accepts_coercive(m, arg))
            }
        }
        // A proven object value (ADR-0043 stage 3): a definite No iff every union
        // member provenly rejects an object of its exact class. An unresolvable /
        // ambiguous class stays unproven (silent).
        ArgValue::New(..) | ArgValue::EnumCase(..) => match cx.proven_object_class(arg) {
            Some(class) => cx.object_is_type_error(ty, &class),
            None => false,
        },
        // An array is never a native scalar/union finding (arrays only ever fail
        // the phpdoc contract relation, checked separately).
        ArgValue::Array(_) => false,
        // Non-provable carriers: silent (a `Ternary` is resolved to a concrete arm
        // before this point; a `ClassConst` is resolved upstream to an enum case /
        // literal, so an unresolved one is genuinely unproven).
        ArgValue::Var(_)
        | ArgValue::Call(..)
        | ArgValue::Ternary { .. }
        | ArgValue::Coalesce(..)
        | ArgValue::OffsetRead { .. }
        | ArgValue::PropFetch { .. }
        | ArgValue::Clone(_)
        | ArgValue::ClassConst(..)
        // A concatenation reaching here did not resolve — an operand's value is
        // unknown, so the result string is too. (A resolved one arrives as `Str`.)
        | ArgValue::Concat(..)
        // A closure value against a scalar/union param is never a scalar finding
        // (a `callable`/`Closure` param is not a native scalar type this checks).
        | ArgValue::Closure(_)
        | ArgValue::Other => false,
    }
}

/// ADR-0043 stage 3 — the object-world native definite-No is **guard-blind inside
/// a binding descent** and must be suppressed there. A descent rebinds a callee's
/// parameter to a hypothetical caller value, but the callee's in-body `instanceof`
/// / type guards that would narrow that value are unmodeled (e.g. Carbon's
/// `if ($x instanceof DateTimeInterface) { … $x … }` is dead for a string `$x`,
/// yet the walk cannot prove it because the guard flows through an intermediate
/// boolean). Checking an object-world mismatch on a descent-bound value is
/// therefore unsound — exactly the reason descent-bound property writes are also
/// unchecked (see `apply_prop_assign`). Scalar-vs-scalar descent checks, whose
/// guards the walk *can* evaluate, are unaffected: only a judgment that touches an
/// object type (an `Instance`-bearing param, or a proven object value) is
/// suppressed. In the non-descent direct/propagation passes this is always `false`.
fn object_world_guard_blind(in_descent: bool, ty: &NativeType, value: &ArgValue) -> bool {
    in_descent
        && (ty.has_instance() || matches!(value, ArgValue::New(..) | ArgValue::EnumCase(..)))
}

/// Strict mode: does a single union `member` accept the non-null literal `arg`
/// *exactly* (the only implicit conversion PHP allows in strict mode is
/// int→float, so a `float` member also accepts an `int` arg)?
fn member_accepts_strict(m: &TypeMember, arg: &ArgValue) -> bool {
    match m {
        TypeMember::Scalar(ScalarType::Int) => matches!(arg, ArgValue::Int(_)),
        TypeMember::Scalar(ScalarType::Float) => matches!(arg, ArgValue::Int(_) | ArgValue::Float(_)),
        TypeMember::Scalar(ScalarType::String) => matches!(arg, ArgValue::Str(_)),
        TypeMember::Scalar(ScalarType::Bool) => matches!(arg, ArgValue::Bool(_)),
        TypeMember::BoolLiteral(b) => matches!(arg, ArgValue::Bool(v) if v == b),
        // Object member (ADR-0043): no scalar literal is a member of a class type
        // or an object intersection. Unreachable in stage 1 (the `has_instance`
        // guard in `is_type_error` short-circuits before any member is inspected);
        // explicit for stage 3.
        TypeMember::Instance { .. } | TypeMember::InstanceInter(_) => false,
    }
}

/// Coercive mode: could the non-null literal `arg` be coerced into this single
/// union `member`? `string`/`bool` are universal sinks for scalars; numeric
/// members accept int/float/bool and numeric strings only; a bool-literal member
/// accepts **only** the exact matching bool value (no coercion into it).
fn member_accepts_coercive(m: &TypeMember, arg: &ArgValue) -> bool {
    match m {
        // Any scalar coerces to `string` or to `bool`.
        TypeMember::Scalar(ScalarType::String) | TypeMember::Scalar(ScalarType::Bool) => true,
        // Numeric members accept numbers, bools, and numeric strings; a
        // non-numeric string is the only scalar that fails.
        TypeMember::Scalar(ScalarType::Int) | TypeMember::Scalar(ScalarType::Float) => match arg {
            ArgValue::Str(s) => php_is_numeric(s),
            ArgValue::Int(_) | ArgValue::Float(_) | ArgValue::Bool(_) => true,
            _ => false,
        },
        // No value coerces *into* a bool-literal; only the exact bool matches.
        TypeMember::BoolLiteral(b) => matches!(arg, ArgValue::Bool(v) if v == b),
        // Object member (ADR-0043): no scalar coerces into a class type or an
        // object intersection. See `member_accepts_strict` — unreachable in stage 1,
        // explicit for stage 3.
        TypeMember::Instance { .. } | TypeMember::InstanceInter(_) => false,
    }
}

/// The value a parameter of type `ty` holds when `value` is passed under
/// `strict`, or `None` when the pass fatals at entry or the coercion is
/// uncertain (silence is safe — ADR-0002).
///
/// For a single-scalar type the exact per-scalar coercion is reproduced (keeping
/// interprocedural binding precise). For a **union** the value is bound only when
/// it already matches a member's own type exactly — Steins does not guess which
/// member PHP would coerce a mismatched value into, so it stops the descent
/// (silent) rather than risk an unsound bound value.
fn coerce_into_param(cx: &Cx, ty: &NativeType, value: &ArgValue) -> Option<ArgValue> {
    // ADR-0043 stage 1 — an object-bearing type binds the value verbatim, exactly
    // as the pre-ADR-0043 `None`-typed (untracked) parameter did: the caller's
    // `None => bind raw value` path is reproduced here so an object parameter does
    // not abort the interprocedural descent. No scalar coercion applies to objects.
    if ty.has_instance() {
        return Some(value.clone());
    }
    if is_type_error(cx, ty, value) {
        return None;
    }
    if matches!(value, ArgValue::Null) {
        return Some(ArgValue::Null);
    }
    if let [TypeMember::Scalar(scalar)] = ty.members.as_slice() {
        return coerce_scalar(*scalar, value);
    }
    // Union: bind only on an exact-type member match; otherwise silence.
    if ty.members.iter().any(|m| member_matches_exact(m, value)) {
        return Some(value.clone());
    }
    None
}

/// The fact a **native-typed slot** actually stores after PHP's typed-boundary
/// conversion (issue #48) — a typed property write, a promoted-param
/// construction, a literal property default — or `None` when no sound fact can
/// be stored and the slot must stay Unknown.
///
/// PHP converts at every typed boundary; recording the *assigned* fact verbatim
/// is how #48's soundness hole opened: an int written to a `float` property read
/// back as the int `1`, `=== 1` folded true on a value the runtime holds as
/// `1.0`, and a dead branch's `null` premised a proof-layer `call.on-null` on
/// code that runs clean.
///
/// The table is deliberately narrower than [`coerce_scalar`]'s coercive-mode
/// table, because a stored fact must be right under `declare(strict_types=1)`
/// and without it alike, and this seam does not consult the file's mode. Only
/// **mode-independent** outcomes are stored:
///
/// - a value/base whose runtime type exactly matches a union member stores
///   as-is (no conversion happens in either mode);
/// - an int into a type with a `float` member and no `int` member stores as the
///   float it becomes — the ONE implicit conversion PHP performs in both modes
///   (the strict-mode int→float widening exception), value-precisely for the
///   finite layers and as `General` float for the abstract ones (the int
///   refinement is an int-domain claim; the domain has no float refinement, so
///   widening drops it — wider, never wrong);
/// - `null` into a nullable type stores as-is;
/// - everything else drops the fact: under strict types the write fatals (no
///   fact is the soundest fact), and under coercive mode the conversion may be
///   computable but storing nothing is sound where storing the unconverted
///   fact was not.
///
/// An object-bearing type stores verbatim (ADR-0043 stage 1: the native scalar
/// machinery treats such a slot as untracked, and the object arm never reaches
/// here — object rvalues are excluded before storage).
fn coerce_fact_to_native(ty: &NativeType, fact: Fact) -> Option<Fact> {
    if ty.has_instance() {
        return Some(fact);
    }
    // "int arrives, a float slot converts it": a float member with no int member.
    let float_slot = ty.members.iter().any(|m| matches!(m, TypeMember::Scalar(ScalarType::Float)))
        && !ty.members.iter().any(|m| matches!(m, TypeMember::Scalar(ScalarType::Int)));
    match fact {
        Fact::Singleton(v) => coerce_val_to_native(ty, float_slot, v).map(Fact::Singleton),
        Fact::OneOf(vs) => {
            let coerced: Option<Vec<Val>> =
                vs.into_iter().map(|v| coerce_val_to_native(ty, float_slot, v)).collect();
            // int→float can merge previously-distinct members; `from_vals` re-dedupes.
            coerced.and_then(Fact::from_vals)
        }
        Fact::Refined { base, refinement, nullable } => {
            if native_has_base(ty, base) {
                Some(Fact::Refined { base, refinement, nullable })
            } else if base == Base::Int && float_slot {
                Some(Fact::General { base: Base::Float, nullable })
            } else {
                None
            }
        }
        Fact::General { base, nullable } => {
            if native_has_base(ty, base) {
                Some(Fact::General { base, nullable })
            } else if base == Base::Int && float_slot {
                Some(Fact::General { base: Base::Float, nullable })
            } else {
                None
            }
        }
        // A tracked native type is scalars-only (an `array` member lowers the
        // whole hint to `None`), so an array fact never inhabits one.
        Fact::Shape { .. } => None,
    }
}

/// The [`Val`] half of [`coerce_fact_to_native`]: exact-member match keeps the
/// value, int→float converts value-precisely (PHP's long→double is the same
/// IEEE conversion as `as f64`), `null` needs the nullable flag, anything else
/// is mode-dependent and drops.
fn coerce_val_to_native(ty: &NativeType, float_slot: bool, v: Val) -> Option<Val> {
    match &v {
        Val::Null => ty.nullable.then_some(v),
        Val::Int(i) if float_slot => Some(Val::Float(*i as f64)),
        Val::Int(_) | Val::Float(_) | Val::Str(_) | Val::Bool(_) => ty
            .members
            .iter()
            .any(|m| native_member_matches_val(m, &v))
            .then_some(v),
        Val::Array(_) => None,
    }
}

/// Whether a union `member` matches the runtime type of scalar value `v`
/// exactly — the [`Val`]-shaped sibling of [`member_matches_exact`].
fn native_member_matches_val(m: &TypeMember, v: &Val) -> bool {
    match (m, v) {
        (TypeMember::Scalar(ScalarType::Int), Val::Int(_))
        | (TypeMember::Scalar(ScalarType::Float), Val::Float(_))
        | (TypeMember::Scalar(ScalarType::String), Val::Str(_))
        | (TypeMember::Scalar(ScalarType::Bool), Val::Bool(_)) => true,
        (TypeMember::BoolLiteral(b), Val::Bool(x)) => x == b,
        _ => false,
    }
}

/// Whether the native type carries the FULL scalar member for `base`. A
/// `true`/`false` literal member deliberately does not count — a `General` bool
/// covers both values, and only one inhabits the slot.
fn native_has_base(ty: &NativeType, base: Base) -> bool {
    ty.members.iter().any(|m| {
        matches!(
            (m, base),
            (TypeMember::Scalar(ScalarType::Int), Base::Int)
                | (TypeMember::Scalar(ScalarType::Float), Base::Float)
                | (TypeMember::Scalar(ScalarType::String), Base::String)
                | (TypeMember::Scalar(ScalarType::Bool), Base::Bool)
        )
    })
}

/// Whether a union `member` matches the *runtime type* of the non-null literal
/// `value` exactly (no coercion) — used to decide when a union binding is safe.
fn member_matches_exact(m: &TypeMember, value: &ArgValue) -> bool {
    match (m, value) {
        (TypeMember::Scalar(ScalarType::Int), ArgValue::Int(_))
        | (TypeMember::Scalar(ScalarType::Float), ArgValue::Float(_))
        | (TypeMember::Scalar(ScalarType::String), ArgValue::Str(_))
        | (TypeMember::Scalar(ScalarType::Bool), ArgValue::Bool(_)) => true,
        (TypeMember::BoolLiteral(b), ArgValue::Bool(v)) => v == b,
        // Object member (ADR-0043): scalar literals never match a class type.
        _ => false,
    }
}

/// The value a single-scalar parameter holds after coercion (the per-scalar
/// PHP 8 coercion table), or `None` when the conversion is uncertain.
fn coerce_scalar(scalar: ScalarType, value: &ArgValue) -> Option<ArgValue> {
    Some(match (scalar, value) {
        (ScalarType::Int, ArgValue::Int(_))
        | (ScalarType::Float, ArgValue::Float(_))
        | (ScalarType::String, ArgValue::Str(_))
        | (ScalarType::Bool, ArgValue::Bool(_)) => value.clone(),

        (ScalarType::Float, ArgValue::Int(i)) => ArgValue::Float(*i as f64),

        (ScalarType::Int, ArgValue::Str(s)) => ArgValue::Int(php_str_to_int(s)?),
        (ScalarType::Float, ArgValue::Str(s)) => ArgValue::Float(php_str_to_float(s)?),
        (ScalarType::Int, ArgValue::Float(f)) => ArgValue::Int(php_float_to_int(*f)?),
        (ScalarType::Int, ArgValue::Bool(b)) => ArgValue::Int(i64::from(*b)),
        (ScalarType::Float, ArgValue::Bool(b)) => ArgValue::Float(if *b { 1.0 } else { 0.0 }),
        (ScalarType::Bool, ArgValue::Int(i)) => ArgValue::Bool(*i != 0),
        (ScalarType::Bool, ArgValue::Float(f)) => ArgValue::Bool(*f != 0.0),
        (ScalarType::Bool, ArgValue::Str(s)) => ArgValue::Bool(!(s.is_empty() || s == "0")),
        (ScalarType::String, ArgValue::Int(i)) => ArgValue::Str(i.to_string()),
        (ScalarType::String, ArgValue::Bool(b)) => {
            ArgValue::Str(if *b { "1".to_owned() } else { String::new() })
        }

        _ => return None,
    })
}

/// Whitespace PHP trims before interpreting a numeric string.
fn php_trim(s: &str) -> &str {
    s.trim_matches(|c| matches!(c, ' ' | '\t' | '\n' | '\r' | '\x0b' | '\x0c'))
}

/// Convert a PHP numeric string to the int it coerces to.
fn php_str_to_int(s: &str) -> Option<i64> {
    let t = php_trim(s);
    if let Ok(i) = t.parse::<i64>() {
        return Some(i);
    }
    php_float_to_int(t.parse::<f64>().ok()?)
}

/// Convert a PHP numeric string to the float it coerces to.
fn php_str_to_float(s: &str) -> Option<f64> {
    php_trim(s).parse::<f64>().ok()
}

/// Truncate a float toward zero to an int (PHP scalar coercion).
fn php_float_to_int(f: f64) -> Option<i64> {
    f.is_finite().then(|| f.trunc() as i64)
}

// ---------------------------------------------------------------------------
// PHPDoc declared-contract acceptance (ADR-0029/0030 relation #1).
//
// A separate acceptance relation from the runtime one above: **pure set
// semantics, NO coercion** (a numeric string `"5"` does NOT satisfy `int`). The
// judgment is trinary — `Yes`/`No`/`Maybe` — and only a definite `No` (proven
// non-membership) is ever reported; `Maybe` is silent (the zero-FP side).
// ---------------------------------------------------------------------------

/// Intersection-style combine: `No` dominates, then `Maybe`, else `Yes`. Used
/// when *every* sub-obligation must hold (element/key membership, shape items).
/// This is exactly [`Certainty::and`], kept as a free function for the existing
/// call sites.
fn combine(a: Certainty, b: Certainty) -> Certainty {
    a.and(b)
}

/// A convenience alias inside this module: the phpdoc contract acceptance code
/// (ADR-0030) was written against a local `Tri`; it now shares the one project-wide
/// [`Certainty`] type (ADR-0031 — one trinary, never parallel ones).
use Certainty as Tri;

/// A proven value in contract terms: a scalar literal, an array of proven values
/// (normalized keys), or an object of an exact class (a `New` fact).
///
/// An object additionally carries its **class-level generic type-argument values**
/// (ADR-0032 tier 3, issue #10): the per-`@template` values that flowed into the
/// object at its `new` site (tier-1 propagation), in template-declaration order.
/// The vector is empty when the class is non-generic, or when the arguments could
/// not be proven — an empty carry is the honest floor (acceptance then answers
/// `Maybe` on the argument half, never a manufactured `No`). These live in the
/// contract lane, not the object-free value lattice (ADR-0035/0043 §4).
enum CVal {
    Scalar(ArgValue),
    Array(Vec<(NormKey, CVal)>),
    Object(String, Vec<CVal>),
}

/// The `@param`/`@return` phpdoc envelopes parsed off one declaration's docblock.
struct Envelopes {
    /// Parameter name (no `$`) → declared phpdoc type.
    params: Vec<(String, PType)>,
    ret: Option<PType>,
    /// Parameter names (no `$`) that an assertion tag (`@phpstan-assert` &c.)
    /// targets on this same declaration — the function is an **assertion helper**
    /// for them (see [`check_phpdoc_param`]). Property/`$this->…` assertion targets
    /// are excluded (they say nothing about a call-site argument).
    assert_params: HashSet<String>,
    /// The full assertion specs on this declaration (Feature D): the asserted type
    /// applied to the caller's env after a call (`Always`), or in guard position
    /// (`IfTrue`/`IfFalse`). Property/`$this` targets are excluded (as above).
    asserts: Vec<AssertSpec>,
}

/// One `@phpstan-assert[-if-true|-if-false] [!]<type> $param` spec (Feature D).
struct AssertSpec {
    /// Target parameter name (no `$`).
    param: String,
    /// The asserted phpdoc type.
    ty: PType,
    /// Unconditional / conditional-on-true / conditional-on-false.
    kind: AssertKind,
    /// The negated form (`@phpstan-assert !T $x`): asserts NOT `T`.
    negated: bool,
}

impl Envelopes {
    fn param(&self, name: &str) -> Option<&PType> {
        self.params.iter().find(|(n, _)| n == name).map(|(_, t)| t)
    }

    /// Whether `name` is an assertion target on this declaration, in which case its
    /// `@param` states a **post**-condition and checking arguments against it is a
    /// category error (see [`check_phpdoc_param`]).
    fn is_assert_target(&self, name: &str) -> bool {
        self.assert_params.contains(name)
    }

    /// Neutralize every envelope identifier naming a template from `shadow` (issue
    /// #5): a `@template`-declared name is a template parameter, not a class, so it
    /// must not lower to a class contract that would reject real arguments. Applied
    /// in two idempotent stages — [`parse_envelopes`] applies this declaration's own
    /// `@template` names, then a member-check site applies the enclosing class-like's
    /// class-level `@template` names — so a `no-op` empty set costs nothing.
    fn shadow_templates(&mut self, shadow: &HashSet<String>) {
        if shadow.is_empty() {
            return;
        }
        for (_, t) in &mut self.params {
            neutralize_templates(t, shadow);
        }
        if let Some(t) = &mut self.ret {
            neutralize_templates(t, shadow);
        }
        for s in &mut self.asserts {
            neutralize_templates(&mut s.ty, shadow);
        }
    }
}

/// The lowercased set of `@template` names a docblock declares — the *shadow set*
/// (issue #5). A name here is a template parameter, not a class, inside the
/// docblock's own `@param`/`@return`/`@var` types (and, when this is a class-like's
/// docblock, inside every member docblock).
///
/// **Case-insensitive by decision.** PHPStan treats template names as
/// case-sensitive identifiers, so strictly `@template Model` would not shadow a
/// `@param model`. Steins folds case instead, for three reasons: (1) zero-FP is
/// paramount and over-shadowing only ever *silences* a diagnostic — it can never
/// manufacture one; (2) the whole identifier pipeline (`is_known_class`, contract
/// lowering, `accepts_identifier`) already normalizes to lowercase, so a folded
/// shadow set composes uniformly instead of needing a lone case-sensitive path; (3)
/// the only observable divergence from PHPStan is Steins staying silent where
/// PHPStan would still resolve the class — and silence is the safe side (ADR-0029).
fn template_names_of(docblock: Option<&str>) -> HashSet<String> {
    docblock
        .map(|t| {
            steins_phpdoc::scan_template_names(t)
                .into_iter()
                .map(|n| n.to_ascii_lowercase())
                .collect()
        })
        .unwrap_or_default()
}

/// Rewrite every **bare, unqualified** identifier naming a template from `shadow`
/// to an opaque node (issue #5). The neutral node is [`PKind::Unsupported`], which
/// lowers to `ContractTy::Opaque` and rides `accepts` as `Maybe` — exactly the
/// silence a template already gets today when it names no existing class (ADR-0032:
/// templates are transparent/thin where propagation does not reach). A `\`-qualified
/// or namespaced reference (`\Model`, `App\Model`) is **never** shadowed —
/// qualification opts out of the template namespace. Idempotent; recurses through
/// every composite so a nested `list<Model>` / `array{a: Model}` is neutralized too.
fn neutralize_templates(ty: &mut PType, shadow: &HashSet<String>) {
    match &mut ty.kind {
        PKind::Identifier(name) => {
            if !name.contains('\\') && shadow.contains(&name.to_ascii_lowercase()) {
                let raw = std::mem::take(name);
                ty.kind = PKind::Unsupported(raw);
            }
        }
        PKind::Nullable(inner) | PKind::Array(inner) => neutralize_templates(inner, shadow),
        PKind::Union { types, .. } | PKind::Intersection(types) => {
            for t in types {
                neutralize_templates(t, shadow);
            }
        }
        PKind::Generic { args, .. } => {
            for a in args {
                neutralize_templates(&mut a.ty, shadow);
            }
        }
        PKind::OffsetAccess { base, offset } => {
            neutralize_templates(base, shadow);
            neutralize_templates(offset, shadow);
        }
        PKind::ArrayShape(s) => {
            for it in &mut s.items {
                neutralize_templates(&mut it.value, shadow);
            }
        }
        PKind::ObjectShape(items) => {
            for it in items {
                neutralize_templates(&mut it.value, shadow);
            }
        }
        PKind::This | PKind::Callable(_) | PKind::Const(_) | PKind::Conditional(_)
        | PKind::Unsupported(_) => {}
    }
}

/// Parse the `@param`/`@return` envelopes from a raw docblock, or `None` when the
/// declaration carries no docblock or no envelope-bearing tag. A tag whose type
/// fails to parse (or carries an `Unsupported` node) contributes no envelope; the
/// other tags are unaffected (ADR-0029). `@var`/`@throws` are out of scope.
fn parse_envelopes(docblock: Option<&str>) -> Option<Envelopes> {
    let text = docblock?;
    // A `@phpstan-`/`@psalm-` prefixed tag overrides the plain one for the same
    // target (PHPStan precedence; ADR-0029). Track whether each recorded envelope
    // came from a prefixed tag so a later prefixed tag wins but a plain one never
    // displaces a prefixed one.
    let mut params: Vec<(String, PType)> = Vec::new();
    let mut param_prefixed: HashSet<String> = HashSet::new();
    let mut ret: Option<PType> = None;
    let mut ret_prefixed = false;
    let mut assert_params: HashSet<String> = HashSet::new();
    let mut asserts: Vec<AssertSpec> = Vec::new();
    for tag in scan_docblock(text) {
        // An assertion tag targeting a parameter marks it an assert-helper param
        // (its `@param` is a post-condition; ADR-0030). Property targets are inert.
        // All three kinds (Always/IfTrue/IfFalse) and the negated form exempt alike:
        // whatever the type or condition, the parameter is not being *constrained*
        // on entry, so a call-site argument cannot violate it. The spec is also
        // recorded (with its parsed type) for post-call application (Feature D).
        if let TagKind::Assert { kind: akind, negated } = tag.kind
            && !tag.property_target
            && let Some(var) = &tag.var_name
        {
            let name = var.trim_start_matches('$').to_owned();
            assert_params.insert(name.clone());
            if let Some(ty) = parse_tag_type(&tag.type_text) {
                asserts.push(AssertSpec { param: name, ty, kind: akind, negated });
            }
            continue;
        }
        match tag.kind {
            TagKind::Param => {
                let Some(var) = &tag.var_name else { continue };
                let name = var.trim_start_matches('$').to_owned();
                let Some(ty) = parse_tag_type(&tag.type_text) else { continue };
                match params.iter_mut().find(|(n, _)| *n == name) {
                    Some(slot) => {
                        // Replace only if we are not downgrading precedence.
                        if tag.prefixed || !param_prefixed.contains(&name) {
                            slot.1 = ty;
                        }
                    }
                    None => params.push((name.clone(), ty)),
                }
                if tag.prefixed {
                    param_prefixed.insert(name);
                }
            }
            TagKind::Return => {
                let Some(ty) = parse_tag_type(&tag.type_text) else { continue };
                if tag.prefixed || (ret.is_none() && !ret_prefixed) {
                    ret = Some(ty);
                    ret_prefixed = tag.prefixed;
                }
            }
            TagKind::Var | TagKind::Throws => {}
            // Conditional purity is an effect contract (ADR-0063), not a type
            // envelope; `conditional_purity` is its consumer.
            TagKind::ConditionalPurity(_) => {}
            // Assertion tags are consumed above (collected into `assert_params`);
            // they never contribute a `@param`/`@return` envelope.
            TagKind::Assert { .. } => {}
            // The trace annotation (ADR-0074) is a statement-level introspection
            // trigger, never a declaration envelope; its consumer is the
            // statement-docblock emitter, not this seam.
            TagKind::TraceTag => {}
        }
    }
    // Return an envelope set whenever there is anything to check *or* any assertion
    // to remember: an assert-only docblock still carries the exemption fact, so a
    // sibling `@param` (added later, or resolved in another pass) sees it.
    if !(!params.is_empty() || ret.is_some() || !assert_params.is_empty()) {
        return None;
    }
    let mut env = Envelopes { params, ret, assert_params, asserts };
    // Shadow this declaration's own `@template` names in its envelope types (issue
    // #5). A member-check site additionally applies the enclosing class-like's
    // class-level templates (idempotent second stage).
    env.shadow_templates(&template_names_of(Some(text)));
    Some(env)
}

/// Parse one tag's type text into a phpdoc [`PType`], or `None` on a parse error
/// or an `Unsupported` node (no envelope — silence is safe).
fn parse_tag_type(text: &str) -> Option<PType> {
    let parsed = parse_type(text).ok()?;
    (!kind_has_unsupported(&parsed.ty.kind)).then_some(parsed.ty)
}

/// Whether a phpdoc type subtree contains an `Unsupported` node anywhere.
fn kind_has_unsupported(kind: &PKind) -> bool {
    match kind {
        PKind::Unsupported(_) => true,
        PKind::Nullable(t) | PKind::Array(t) => kind_has_unsupported(&t.kind),
        PKind::Union { types, .. } | PKind::Intersection(types) => {
            types.iter().any(|t| kind_has_unsupported(&t.kind))
        }
        PKind::Generic { args, .. } => args.iter().any(|a| kind_has_unsupported(&a.ty.kind)),
        PKind::OffsetAccess { base, offset } => {
            kind_has_unsupported(&base.kind) || kind_has_unsupported(&offset.kind)
        }
        PKind::ArrayShape(s) => s.items.iter().any(|i| kind_has_unsupported(&i.value.kind)),
        PKind::ObjectShape(items) => items.iter().any(|i| kind_has_unsupported(&i.value.kind)),
        _ => false,
    }
}

impl<'a> Cx<'a> {
    /// Resolve a call/return value to a proven [`CVal`] (scalars, arrays of proven
    /// values, or a `New` exact-class object), or `None` when not provable.
    fn resolve_cval(
        &self,
        value: &ArgValue,
        env: &HashMap<String, Known>,
        store: &Store,
        poisoned: bool,
        folder: &mut dyn Folder,
    ) -> Option<CVal> {
        match value {
            v if v.is_literal() => Some(CVal::Scalar(v.clone())),
            // `new Class(args)` — a proven object of exactly `Class`, carrying the
            // generic type-argument values that flow into it (ADR-0032 tier 3,
            // issue #10). Empty carry when non-generic / unprovable (FP-safe).
            ArgValue::New(class_ref, args, _) if !poisoned => {
                let class = self.class_fqn(class_ref);
                let targs = self.infer_generic_args(&class, args, env, store, poisoned, folder);
                Some(CVal::Object(class, targs))
            }
            // ADR-0043 stage 4: an enum case is an object value of its enum class,
            // so it can ride the is-a oracle against enum/interface phpdoc contracts.
            // An enum is never `@template`-parameterized → no generic carry.
            ArgValue::EnumCase(fqn, _) => Some(CVal::Object(fqn.clone(), Vec::new())),
            // A class-const access (`Foo::BAR`, `Suit::Hearts`) resolves env-free:
            // an enum case becomes an object, a literal const its value. `self`/
            // `parent` need an enclosing class, absent here → unresolved (silent).
            ArgValue::ClassConst(sc, name) => match self.resolve_class_const(sc, name, None)? {
                ArgValue::EnumCase(fqn, _) => Some(CVal::Object(fqn, Vec::new())),
                lit => self.resolve_cval(&lit, env, store, poisoned, folder),
            },
            ArgValue::Array(items) => {
                // ADR-0049 A12: the walk knows the project's own PHP minor, so a
                // negative-key literal resolves exactly; only an unreported minor
                // over such a literal declines.
                let normalized = normalize_array(items, self.php_minor)?;
                let mut out = Vec::with_capacity(normalized.len());
                for (k, v) in normalized {
                    out.push((k, self.resolve_cval(&v, env, store, poisoned, folder)?));
                }
                Some(CVal::Array(out))
            }
            ArgValue::Var(name) if !poisoned => {
                if let Some(k) = env.get(name) {
                    // A `OneOf` fact is not one proven value → not a `CVal`.
                    let v = k.singleton()?;
                    self.resolve_cval(&v, env, store, poisoned, folder)
                } else if store.is_exact(name) {
                    // Only an EXACT object becomes a `CVal::Object` (audit G1): the
                    // phpdoc-acceptance consumer draws a No-side `is_a` conclusion from
                    // it, which a lower-bound `$this` would make unsound. An inexact
                    // object stays unresolved (silent) — acceptance never fires on it.
                    //
                    // Generic type arguments are NOT carried through a variable binding
                    // through a variable binding (the heap records no type-arg carry); a
                    // `$x = new Box('x'); f($x)` therefore judges only its class half.
                    // Stage 1 scopes the argument half to the direct `new` argument
                    // position (the conformance fixtures' shape) — empty carry here.
                    store.class_of(name).map(|c| CVal::Object(c.to_owned(), Vec::new()))
                } else {
                    None
                }
            }
            ArgValue::Call(..) => {
                self.resolve_literal(value, env, poisoned, folder).map(CVal::Scalar)
            }
            _ => None,
        }
    }

    /// Resolve a phpdoc class name to its FQN in the callee file `cfile`'s context
    /// (offset `coff` picks the namespace/use scope where the docblock was written).
    fn resolve_pclass(&self, cfile: usize, coff: u32, name: &str) -> String {
        let raw = name.trim_start_matches('\\').to_owned();
        let kind = if name.starts_with('\\') {
            RefKind::FullyQualified
        } else if raw.contains('\\') {
            RefKind::Qualified
        } else {
            RefKind::Unqualified
        };
        self.units[cfile].tree.resolve_class_fqn(&NameRef { raw, kind, offset: coff })
    }

    /// Whether `fqn` names a **known class** — a Unique project class or a
    /// catalogued builtin (ADR-0043 stage 4). This is the same closure predicate
    /// the is-a oracle uses ([`Self::ancestors_of`] returns `Some`): only a known
    /// class may make a proven scalar a definite non-member. An unresolved bare
    /// identifier (a `@template` param, a `@phpstan-type` alias, or an uncatalogued
    /// external) is *not* known, so a scalar against it stays silent.
    fn is_known_class(&self, fqn: &str) -> bool {
        self.ancestors_of(fqn.trim_start_matches('\\')).is_some()
    }

    // -----------------------------------------------------------------------
    // ADR-0043 stage 3 — native object acceptance (definite-No opening).
    // -----------------------------------------------------------------------

    /// The proven exact class (namespace-resolved FQN) of an object-valued
    /// [`ArgValue`], or `None` when it is not a proven object. `New` resolves its
    /// written class reference in this file's context (matching the ADR-0036 heap
    /// `class_of`); an `EnumCase` already carries the resolved enum FQN.
    fn proven_object_class(&self, v: &ArgValue) -> Option<String> {
        match v {
            ArgValue::New(r, _, _) => Some(self.class_fqn(r)),
            ArgValue::EnumCase(fqn, _) => Some(fqn.clone()),
            _ => None,
        }
    }

    /// ADR-0043 stage 3 — does an object of exact class `class_fqn` **provably
    /// violate** the native type `ty`? A definite-No: `true` only when *every*
    /// union member definitively rejects an object of that class (any `Unknown`
    /// or accepting member makes the whole verdict silent). `nullable` is
    /// irrelevant to an object value — an object is never `null`.
    fn object_is_type_error(&self, ty: &NativeType, class_fqn: &str) -> bool {
        ty.members.iter().all(|m| self.member_rejects_object(m, class_fqn))
    }

    /// Whether a single union `member` **definitively rejects** an object of exact
    /// class `class_fqn`.
    ///
    /// Verified against PHP 8.5.8 (`php -r`):
    /// - `int`/`float`/`bool` (and `false`/`true` literals): no object — **not
    ///   even one with `__toString`** — coerces into these in either mode; passing
    ///   any object `TypeError`s → an unconditional definite reject.
    /// - `string`: a `__toString` object *does* coerce to a `string` parameter in
    ///   **coercive** mode (no error), while a plain object and **any** object in
    ///   **strict** mode `TypeError`. Steins does not (yet) prove the *absence* of
    ///   `__toString` across a class hierarchy, so a `string` member is a definite
    ///   reject only in **strict** mode; in coercive mode it stays silent
    ///   (Unknown), the FP-safe choice.
    /// - `Instance { fqn, .. }`: rejects iff the trinary is-a oracle proves non-membership
    ///   (`IsA::No`); `Yes` accepts and `Unknown` (incomplete hierarchy) is silent.
    fn member_rejects_object(&self, m: &TypeMember, class_fqn: &str) -> bool {
        match m {
            TypeMember::Instance { fqn, .. } => self.is_a(class_fqn, fqn) == IsA::No,
            // An intersection (`A&B&…`) demands membership in **every** conjunct,
            // so it definitively rejects the object the moment the is-a oracle
            // proves non-membership (`IsA::No`) in **any** one of them. An
            // incomplete hierarchy on the remaining conjuncts stays silent — the
            // one proven `No` is already a sound definite reject.
            TypeMember::InstanceInter(cs) => {
                cs.iter().any(|c| self.is_a(class_fqn, &c.fqn) == IsA::No)
            }
            TypeMember::Scalar(ScalarType::String) => self.strict(),
            TypeMember::Scalar(_) | TypeMember::BoolLiteral(_) => true,
        }
    }

    /// Resolve a [`StaticClass`] class-expression to its FQN (ADR-0043). `Named`
    /// resolves in this file's namespace context (source-cased); `self`/`parent`
    /// need the enclosing class; `static` (late static binding) stays unproven.
    fn resolve_static_class_fqn(&self, sc: &StaticClass, enclosing: Option<&str>) -> Option<String> {
        match sc {
            StaticClass::Named(r) => Some(self.class_fqn(r)),
            StaticClass::SelfKw => enclosing.map(str::to_owned),
            StaticClass::Parent => self.parent_fqn(enclosing?),
            StaticClass::Static => None,
        }
    }

    /// Resolve a class-constant / enum-case access `Class::NAME` to a proven value
    /// (ADR-0043 §2), or `None` when unresolvable/non-literal (→ silent).
    ///
    /// - `Class::class` → the FQN **string** literal. Only a written name
    ///   (`Named`) is resolved: it preserves the declared source casing (verified
    ///   against php 8.5.8 — `::class` yields the `use`-target's declared casing).
    ///   `self`/`parent`/`static::class` resolve only to the lowercase-normalized
    ///   index FQN, so emitting them would risk a wrong-case string — left
    ///   unproven (documented deferral).
    /// - An enum case → an [`ArgValue::EnumCase`] **object** value of the enum
    ///   class (never its backing scalar — an enum case is an object).
    /// - A class constant with a literal initializer → that literal, resolved
    ///   through the class/interface hierarchy (child overrides parent).
    fn resolve_class_const(&self, sc: &StaticClass, name: &str, enclosing: Option<&str>) -> Option<ArgValue> {
        if name.eq_ignore_ascii_case("class") {
            return match sc {
                StaticClass::Named(r) => {
                    Some(ArgValue::Str(self.class_fqn(r).trim_start_matches('\\').to_owned()))
                }
                _ => None,
            };
        }
        let fqn = self.resolve_static_class_fqn(sc, enclosing)?;
        if let Some((_, cd)) = self.find_class(&fqn)
            && cd.is_enum
            && cd.enum_cases.iter().any(|c| c.name == name)
        {
            return Some(ArgValue::EnumCase(cd.fqn.clone(), name.to_owned()));
        }
        self.resolve_const_literal(&fqn, name)
    }

    /// Resolve a class constant `fqn::name` to its literal value by walking the
    /// class's own consts, its directly-implemented interfaces' consts, then its
    /// parent chain (most-derived first, matching PHP constant override). Returns
    /// `None` on an unresolvable node or a name with no proven literal.
    fn resolve_const_literal(&self, fqn: &str, name: &str) -> Option<ArgValue> {
        let mut cur = fqn.to_owned();
        let mut seen: HashSet<String> = HashSet::new();
        loop {
            if !seen.insert(cur.to_ascii_lowercase()) {
                return None;
            }
            let (file, cd) = self.find_class(&cur)?;
            if let Some((_, v)) = cd.consts.iter().find(|(n, _)| n == name) {
                return Some(v.clone());
            }
            for iref in &cd.implements {
                let ifqn = self.units[file].tree.resolve_class_fqn(iref);
                if let Some((_, icd)) = self.find_class(&ifqn)
                    && let Some((_, v)) = icd.consts.iter().find(|(n, _)| n == name)
                {
                    return Some(v.clone());
                }
            }
            let pref = cd.parent.as_ref()?;
            cur = self.units[file].tree.resolve_class_fqn(pref);
        }
    }

    /// Resolve an [`ArgValue`] to a proven value **without an environment** — a
    /// self-evident literal, a proven object (`new` / enum case), or a resolved
    /// class constant (ADR-0043). Feeds the native definite-No checks at the
    /// call/return sites. `enclosing` supplies `self`/`parent` for class-const
    /// resolution inside a method body (`None` at file scope).
    fn resolve_static_value(&self, v: &ArgValue, enclosing: Option<&str>) -> Option<ArgValue> {
        match v {
            _ if v.is_literal() => Some(v.clone()),
            ArgValue::New(..) | ArgValue::EnumCase(..) => Some(v.clone()),
            ArgValue::ClassConst(sc, name) => self.resolve_class_const(sc, name, enclosing),
            _ => None,
        }
    }

    /// The **trinary is-a oracle** (ADR-0043 §3): is a value of exact class
    /// `sub_fqn` an instance of `super_fqn`?
    ///
    /// - **`Yes`** — a supertype path exists: the parent chain *and* the
    ///   transitive `implements` closure (class→interface and interface→interface,
    ///   since a lowered interface's extends become parent+implements). Reflexive
    ///   (`sub == super` is `Yes`).
    /// - **`No`** — only under a **completely enumerated hierarchy**: every
    ///   ancestor edge reachable from `sub` resolved either Unique in-project or in
    ///   the catalog's builtin tree, and `super` is absent from that closed
    ///   ancestor set. This is the Certainty discipline applied to subtyping —
    ///   non-membership is provable only under closure.
    /// - **`Unknown`** — the enumeration is incomplete: some ancestor is
    ///   unresolvable/ambiguous, or the chain leaves the project into an
    ///   uncatalogued builtin, or `sub`/`super` is itself unknown.
    ///
    /// Enums (ADR-0043): a lowered enum is-a its explicit `implements` plus the
    /// implicit `UnitEnum` interface, and a *backed* enum additionally is-a
    /// `BackedEnum` (which the catalog records as extending `UnitEnum`).
    ///
    /// A `use`d trait does **not** force `Unknown`: in PHP a trait adds methods,
    /// never types, so it cannot change the is-a relation — [`Self::ancestors_of`]
    /// simply ignores trait use and reports the class's real parent/interfaces.
    fn is_a(&self, sub_fqn: &str, super_fqn: &str) -> IsA {
        self.is_a_tracked(sub_fqn, super_fqn).0
    }

    /// [`Self::is_a`], additionally reporting whether the verdict was **catalog-
    /// backed** — whether any ancestor edge on the walk resolved through the builtin
    /// catalog ([`steins_catalog::builtin_class_supers`]) rather than in-project
    /// source. ADR-0052 A11 reads this: a catalog-backed verdict used for arm
    /// deletion is demoted to `Unknown` on a PHP-minor skew (the builtin edge set
    /// may differ from the catalog pin). A reflexive or purely in-project verdict is
    /// never catalog-backed (`false`), so a project's own `A|B` union narrows under
    /// A11 exactly as before — the demotion touches only builtin-dependent edges.
    fn is_a_tracked(&self, sub_fqn: &str, super_fqn: &str) -> (IsA, bool) {
        let target = super_fqn.trim_start_matches('\\');
        // `Stringable` is implicitly implemented by any class with a `__toString`
        // method (PHP 8.0+), which the explicit parent/`implements` closure does
        // not see. For this target only: a proven `__toString` on any visited class
        // is a definite `Yes`, and a visited trait-using class (whose merged methods
        // are unmodeled — it *might* declare `__toString`) forces `Unknown` rather
        // than an unsound `No`.
        let stringable_target = target.eq_ignore_ascii_case("Stringable");
        let mut queue: Vec<String> = vec![sub_fqn.trim_start_matches('\\').to_owned()];
        let mut seen: HashSet<String> = HashSet::new();
        // Whether every ancestor edge inspected so far resolved — the closure
        // condition for a sound `No`. A single unresolvable node taints it.
        let mut complete = true;
        // Whether a visited class may implicitly gain `Stringable` via a trait.
        let mut maybe_stringable = false;
        // Whether any traversed ancestor edge came from the builtin catalog (A11).
        let mut catalog = false;
        while let Some(cur) = queue.pop() {
            if cur.eq_ignore_ascii_case(target) {
                return (IsA::Yes, catalog);
            }
            if !seen.insert(cur.to_ascii_lowercase()) {
                continue;
            }
            if stringable_target
                && let Some((_, cd)) = self.find_class(&cur)
            {
                if cd.methods.iter().any(|m| m.name.eq_ignore_ascii_case("__toString")) {
                    return (IsA::Yes, catalog);
                }
                if cd.uses_traits {
                    maybe_stringable = true;
                }
            }
            // An edge resolved through the catalog (not an in-project class) marks
            // the whole verdict catalog-backed.
            let in_project = self.find_class(&cur).is_some();
            match self.ancestors_of(&cur) {
                Some(supers) => {
                    if !in_project {
                        catalog = true;
                    }
                    queue.extend(supers);
                }
                None => complete = false,
            }
        }
        if stringable_target && maybe_stringable {
            return (IsA::Unknown, catalog);
        }
        (if complete { IsA::No } else { IsA::Unknown }, catalog)
    }

    /// The **direct** supertypes (parent + `implements`, plus an enum's implicit
    /// interfaces) of `fqn`, or `None` when `fqn` is an unknown external (not a
    /// Unique project class, not a catalogued builtin) — which makes the is-a
    /// enumeration incomplete. A resolvable class with no supertypes returns an
    /// empty vector (fully enumerated, a root).
    fn ancestors_of(&self, fqn: &str) -> Option<Vec<String>> {
        if let Some((file, cd)) = self.find_class(fqn) {
            let tree = &self.units[file].tree;
            let mut supers = Vec::new();
            if let Some(pref) = &cd.parent {
                supers.push(tree.resolve_class_fqn(pref));
            }
            for imp in &cd.implements {
                supers.push(tree.resolve_class_fqn(imp));
            }
            if cd.is_enum {
                supers.push("UnitEnum".to_owned());
                if cd.enum_backing.is_some() {
                    supers.push("BackedEnum".to_owned());
                }
            }
            Some(supers)
        } else {
            steins_catalog::builtin_class_supers(fqn)
                .map(|s| s.into_iter().map(str::to_owned).collect())
        }
    }
}

/// The verdict of the trinary is-a oracle ([`Cx::is_a`], ADR-0043 §3).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum IsA {
    /// A supertype path exists (membership is proven).
    Yes,
    /// The hierarchy is completely enumerated and the target is absent from it
    /// (non-membership is proven under closure).
    No,
    /// The hierarchy is incomplete — no verdict (the FP-safe silence).
    Unknown,
}

/// The **project** is-a oracle for contract-arm subtraction (ADR-0052 N4): the
/// steins-infer implementor of steins-contract's [`normalize::IsaOracle`] seam.
/// It wraps the real trinary hierarchy ([`Cx::is_a_tracked`]) and applies the A11
/// version-skew demotion — keeping steins-contract free of any steins-infer /
/// catalog dependency (the polarity law stays in steins-contract; the hierarchy
/// and version knowledge stay here).
struct ProjectIsa<'c, 'a> {
    cx: &'c Cx<'a>,
    /// Whether a catalog-backed verdict must demote to `Unknown` (A11 skew).
    demote_catalog: bool,
}

impl normalize::IsaOracle for ProjectIsa<'_, '_> {
    fn is_a(&self, sub: &str, sup: &str) -> Certainty {
        let (verdict, catalog) = self.cx.is_a_tracked(sub, sup);
        let c = match verdict {
            IsA::Yes => Certainty::Yes,
            IsA::No => Certainty::No,
            IsA::Unknown => Certainty::Maybe,
        };
        // A11: a decisive but catalog-backed verdict falls to `Unknown` on a minor
        // skew — the arm is then kept in both polarities (the FP-safe side).
        if self.demote_catalog && catalog && c != Certainty::Maybe { Certainty::Maybe } else { c }
    }

    fn is_final(&self, fqn: &str) -> bool {
        // Only an in-project `final` class or enum is provably closed; a builtin
        // (finality untracked in the catalog) stays open → the positive branch keeps
        // its arm (FP-safe).
        self.cx.find_class(fqn).is_some_and(|(_, cd)| cd.is_final || cd.is_enum)
    }
}

/// Contract acceptance (ADR-0030): does the proven value `v` inhabit the phpdoc
/// type `ty`? Class names in `ty` resolve in the callee file `cfile` at `coff`.
fn accepts(cx: &Cx, cfile: usize, coff: u32, ty: &PType, v: &CVal) -> Tri {
    match &ty.kind {
        PKind::Identifier(name) => accepts_identifier(cx, cfile, coff, name, v),
        // `$this` is intentionally undecided here.
        PKind::This => Tri::Maybe,
        PKind::Nullable(inner) => match v {
            CVal::Scalar(ArgValue::Null) => Tri::Yes,
            _ => accepts(cx, cfile, coff, inner, v),
        },
        // Union: `Yes` if any member accepts, `No` only if all definitely reject.
        PKind::Union { types, .. } => {
            let (mut any_yes, mut any_maybe) = (false, false);
            for t in types {
                match accepts(cx, cfile, coff, t, v) {
                    Tri::Yes => any_yes = true,
                    Tri::Maybe => any_maybe = true,
                    Tri::No => {}
                }
            }
            if any_yes {
                Tri::Yes
            } else if any_maybe {
                Tri::Maybe
            } else {
                Tri::No
            }
        }
        PKind::Intersection(_) => Tri::Maybe, // class intersections — silent
        // `T[]` — an array (any keys) whose values inhabit `T`.
        PKind::Array(inner) => match v {
            CVal::Array(entries) => {
                let mut r = Tri::Yes;
                for (_, cv) in entries {
                    r = combine(r, accepts(cx, cfile, coff, inner, cv));
                    if r == Tri::No {
                        return Tri::No;
                    }
                }
                r
            }
            _ => Tri::No,
        },
        PKind::Generic { base, args } => accepts_generic(cx, cfile, coff, base, args, v),
        PKind::ArrayShape(shape) => accepts_shape(cx, cfile, coff, shape, v),
        PKind::Const(c) => accepts_const(c, v),
        // Callables, offset-access, conditionals, object-shapes → silent.
        PKind::Callable(_) | PKind::OffsetAccess { .. } | PKind::Conditional(_)
        | PKind::ObjectShape(_) | PKind::Unsupported(_) => Tri::Maybe,
    }
}

/// Acceptance for a bare identifier type.
///
/// **One identifier table** (ADR-0030's no-second-relation discipline, ADR-0062 §5
/// — the same convergence [`accepts_shape`] performs for shapes). The keyword
/// vocabulary is *not* restated here: the name is lowered by
/// [`steins_contract::lower_identifier`] — the table the abstract-fact lane in
/// [`check_phpdoc_param`] already lowers through — and the lowered contract is
/// judged against the proven value by [`steins_contract::admits_val`].
///
/// The divergence this convergence removed: this lane kept a hand-maintained
/// sibling match on the raw phpdoc AST, and it had drifted. `non-positive-int`,
/// `numeric`, `number`, `non-zero-int`, `int-range<…>` and the `boolean`/`integer`/
/// `double` synonyms were enforced against an abstract fact and silent against a
/// *proven* value — strictly less knowledge applied to strictly more information.
///
/// Two judgments stay lane-local, because the value domain has no inhabitant for
/// them (ADR-0035/0038 — there is no `Val::Object`):
///
/// * a **class name** — which the one table reports as its `Class` catch-all —
///   rides this crate's trinary is-a oracle and its `is_known_class` gate;
/// * a value the domain cannot express (an **object**, or an array holding one) is
///   judged by [`unrepresentable_verdict`], which reads the *lowered* contract, not
///   the keyword — so it is a leaf judge, not a second table.
fn accepts_identifier(cx: &Cx, cfile: usize, coff: u32, name: &str, v: &CVal) -> Tri {
    let cty = steins_contract::lower_identifier(name);
    // Not a keyword → a class name, whose judgment this crate owns.
    if matches!(cty, steins_contract::ContractTy::Class(_)) {
        return accepts_class_name(cx, cfile, coff, name, v);
    }
    // Pseudo-type/class precedence (PHPStan's `tryResolvePseudoTypeClassType`): a
    // keyword PHP does not *reserve* — `integer`, `boolean`, `double`, `number`,
    // `closure`, … — is a legal class name, and a class of that name in scope wins
    // over the keyword. `steins-contract` answers the vocabulary half (which
    // spellings are shadowable at all); the registry half is necessarily ours, and
    // this is why the identifier path delegates rather than being replaced by the
    // one table outright.
    //
    // The gate is **in-project declaration**, not `is_known_class`, and that is a
    // deliberate narrowing of PHPStan's rule: the seeded catalog carries global
    // class-likes whose names collide with pseudo-types (`number` is in there,
    // implementing `Stringable`), and letting those shadow would silently turn the
    // overwhelmingly-intended `@param number` (int|float) into a class contract in
    // every non-namespaced file — a false positive manufactured out of a name
    // collision the docblock author never saw. A project that declares its own
    // `class Integer` and then writes `@param Integer` plainly means that class;
    // that is the case the rule exists for, and the case the conformance fixture
    // states. Same in-project/catalog cut as `ProjectIsa::is_final` (ADR-0043 A11).
    if steins_contract::is_shadowable_pseudo_type(name)
        && cx.find_class(&cx.resolve_pclass(cfile, coff, name)).is_some()
    {
        return accepts_class_name(cx, cfile, coff, name, v);
    }
    match cval_as_val(v) {
        Some(val) => steins_contract::admits_val(&cty, &val),
        None => unrepresentable_verdict(&cty, v),
    }
}

/// The conversion seam from the contract lane's proven value into the domain's
/// [`Val`], so the shared acceptance relation can judge it. `None` for a value the
/// domain has no inhabitant for: an object, or an array holding one (ADR-0035/0038
/// — the value lattice is object-free).
fn cval_as_val(v: &CVal) -> Option<Val> {
    match v {
        // The array minor-version question is already settled: a `CVal`'s keys are
        // normalized (`NormKey`), so no next-int guess is needed here.
        CVal::Scalar(s) => val_of(s, None),
        CVal::Array(entries) => entries
            .iter()
            .map(|(k, cv)| cval_as_val(cv).map(|val| (domain_key(k), val)))
            .collect::<Option<Vec<_>>>()
            .map(Val::Array),
        CVal::Object(..) => None,
    }
}

/// The lane-local leaf judge for a value the domain cannot represent — an **object**
/// (ADR-0043's world, which the object-free value lattice has no inhabitant for) or
/// an array holding one.
///
/// It reads the **lowered** contract rather than the keyword, so it states only what
/// is true of *every* object, or of an array whose members are unknown — no keyword
/// knowledge is duplicated here. This is the convergence debt of the identifier
/// path, and it is exactly the debt `steins-contract` cannot retire: hosting it
/// would mean giving the value domain an object inhabitant.
fn unrepresentable_verdict(cty: &steins_contract::ContractTy, v: &CVal) -> Tri {
    use steins_contract::ContractTy as C;
    use steins_contract::MixedCut;
    match v {
        CVal::Object(..) => match cty {
            C::Mixed | C::ObjectAny => Tri::Yes,
            // Both cuts of `mixed` keep every object: an object is not null,
            // and PHP has considered every object truthy since PHP 7 (no
            // `count()`-based falsiness survives), so `non-empty-mixed` admits
            // it too. This is the arm that keeps `f(new stdClass())` against
            // `@param non-empty-mixed` from being a manufactured `No`.
            C::MixedMinus(_) => Tri::Yes,
            // An object may be `Traversable`, may have `__invoke`, and a
            // provenance-flavored string type is non-extensional (ADR-0038) — none
            // of it provable from the class name alone.
            C::Opaque | C::IterableOf { .. } | C::CallableTy { .. } | C::StrOpaque => Tri::Maybe,
            // Every other lowered form denotes scalars, null, or arrays, of which no
            // object is a member (pure set membership, no coercion — ADR-0030).
            _ => Tri::No,
        },
        // An array with an unrepresentable member: its array-ness is decided, its
        // contents are not, so only the contract's own array-ness answers.
        CVal::Array(entries) => match cty {
            C::Mixed | C::ArrayAny { non_empty: false } => Tri::Yes,
            // An array's falsiness is its emptiness alone, and that *is*
            // decided here however unrepresentable its members are — so both
            // cuts answer exactly, with no reference to the contents.
            C::MixedMinus(MixedCut::Null) => Tri::Yes,
            C::MixedMinus(MixedCut::Falsy) => {
                if entries.is_empty() { Tri::No } else { Tri::Yes }
            }
            C::ArrayAny { .. }
            | C::ListOf { .. }
            | C::MapOf { .. }
            | C::IterableOf { .. }
            | C::Shape { .. }
            | C::CallableTy { .. }
            | C::Opaque => Tri::Maybe,
            _ => Tri::No,
        },
        // Unreachable in practice: `resolve_cval` yields only literal scalars here.
        // The honest floor, not a verdict.
        CVal::Scalar(_) => Tri::Maybe,
    }
}

/// A class-name type (ADR-0043 stage 4) — the identifier judgment the one table
/// cannot host. Rides the trinary is-a oracle for a proven object value
/// (`Yes`→Yes, `No`→No, `Unknown`→Maybe) and rejects a proven scalar against a
/// *known* class — phpdoc acceptance is pure set membership (ADR-0030 registry 1,
/// no coercion), so no scalar is ever a class instance, in either mode. The
/// `is_known_class` gate is the safety valve: an unresolved bare identifier may be
/// a `@template` param or a `@phpstan-type` alias (which can denote a scalar), so
/// it stays silent — the same closure discipline the is-a oracle applies to
/// non-membership.
fn accepts_class_name(cx: &Cx, cfile: usize, coff: u32, name: &str, v: &CVal) -> Tri {
    let target = cx.resolve_pclass(cfile, coff, name);
    match v {
        CVal::Object(obj, _) => match cx.is_a(obj, &target) {
            IsA::Yes => Tri::Yes,
            // A definite `No` requires a *known* target: an object whose own
            // hierarchy is closed is-a-No against an unresolved name, but that
            // name may be a `@template`/`@phpstan-type` alias the object *does*
            // satisfy — so gate on `is_known_class`, as for the scalar arm.
            IsA::No if cx.is_known_class(&target) => Tri::No,
            IsA::No | IsA::Unknown => Tri::Maybe,
        },
        CVal::Scalar(_) if cx.is_known_class(&target) => Tri::No,
        // An array is likewise never a class instance, but it is left
        // intentionally undecided here (out of the stage-4 scope).
        _ => Tri::Maybe,
    }
}

/// Acceptance for a literal constant type (`'foo'`, `123`, `1.5`, `true`, …) by
/// value equality; a const-fetch (`Foo::BAR`) is unresolved → silent.
fn accepts_const(c: &ConstExpr, v: &CVal) -> Tri {
    // A const-fetch type (`Foo::BAR`, `self::CONST`, or an enum-case type like
    // `Suit::Hearts`) is unresolved here — its denotation is unknown, so it must
    // stay silent for *every* value (ADR-0043 stage 4): an enum-case object or the
    // referenced literal may well inhabit it, and a returned/passed value that *is*
    // that very constant must never be manufactured into a `No`. This guards the
    // class-const value resolution (which now flows enum cases and const literals
    // into the contract check) from firing on `@return self::CONST { return
    // self::CONST; }` tautologies.
    if matches!(c, ConstExpr::Fetch { .. }) {
        return Tri::Maybe;
    }
    let scalar = match v {
        CVal::Scalar(s) => s,
        _ => return Tri::No,
    };
    let yes_no = |b: bool| if b { Tri::Yes } else { Tri::No };
    match c {
        ConstExpr::Int(s) => match (s.parse::<i64>().ok(), scalar) {
            (Some(n), ArgValue::Int(i)) => yes_no(*i == n),
            _ => Tri::No,
        },
        ConstExpr::Float(s) => match (s.parse::<f64>().ok(), scalar) {
            (Some(n), ArgValue::Float(f)) => yes_no(*f == n),
            _ => Tri::No,
        },
        ConstExpr::Str(lit) => match scalar {
            ArgValue::Str(s) => yes_no(s == string_lit_value(lit)),
            _ => Tri::No,
        },
        ConstExpr::True => yes_no(matches!(scalar, ArgValue::Bool(true))),
        ConstExpr::False => yes_no(matches!(scalar, ArgValue::Bool(false))),
        ConstExpr::Null => yes_no(matches!(scalar, ArgValue::Null)),
        ConstExpr::Fetch { .. } => Tri::Maybe,
    }
}

fn string_lit_value(lit: &StringLit) -> &str {
    match lit {
        StringLit::Single(s) | StringLit::Double(s) => s,
    }
}

/// Resolve a `key-of<Foo::MAP>` / `value-of<Foo::MAP>` operand — a class constant
/// holding an array literal — to the sealed [`ContractTy::Shape`] the shared
/// projection reads (census bucket vi, const tier).
///
/// This is an **operand resolver, not a second projection**: it answers only "what
/// array does this reference denote", and hands the answer to the same
/// `project_key_of`/`project_value_of` the inline tier uses. It lives here rather
/// than in `steins-contract` because the answer needs the project index, which that
/// crate deliberately does not carry.
///
/// `None` — the honest floor, which the caller turns back into the context-free
/// delegation and hence into silence — whenever any step is unproven: a
/// non-const-fetch operand, an unresolvable class, a constant with no *literal*
/// initializer (`ClassDecl::consts` records only literals, so absence never means
/// "no such constant"), a non-array constant, an array whose runtime keys are
/// version-dependent, or an element that is not a scalar literal.
///
/// Deliberately **not** covered: a backed **enum** operand (`value-of<Suit>`).
/// Its backing values are recorded (`EnumCaseDecl::value`) but never read — the
/// const resolver returns an enum case as an *object* by design (ADR-0043 §2), so
/// projecting backing scalars would be new semantics, not a new resolver. Named as
/// a ceiling rather than guessed at.
fn const_operand_shape(cx: &Cx, cfile: usize, coff: u32, ty: &PType) -> Option<ContractTy> {
    let PKind::Const(ConstExpr::Fetch { class, name }) = &ty.kind else { return None };
    let fqn = cx.resolve_pclass(cfile, coff, class);
    let ArgValue::Array(items) = cx.resolve_const_literal(&fqn, name)? else { return None };
    let normalized = normalize_array(&items, cx.php_minor)?;
    let mut fields = Vec::with_capacity(normalized.len());
    for (k, v) in normalized {
        let key = match k {
            NormKey::Int(i) => steins_contract::CKey::Int(i),
            NormKey::Str(s) => steins_contract::CKey::Str(s),
        };
        fields.push(steins_contract::CField { key, optional: false, ty: literal_contract(&v)? });
    }
    let non_empty = !fields.is_empty();
    Some(ContractTy::Shape { list: false, fields, sealed: true, non_empty, unsealed: None })
}

/// The literal contract one *proven* array element denotes. `None` for anything
/// that is not a scalar literal (a nested array, an object, an unresolved
/// reference) — which drops the whole operand to silence rather than projecting a
/// partial key/value set.
fn literal_contract(v: &ArgValue) -> Option<ContractTy> {
    Some(match v {
        ArgValue::Int(i) => ContractTy::LitInt(*i),
        ArgValue::Float(f) => ContractTy::LitFloat(*f),
        ArgValue::Str(s) => ContractTy::LitStr(s.clone()),
        ArgValue::Bool(b) => ContractTy::LitBool(*b),
        ArgValue::Null => ContractTy::Null,
        _ => return None,
    })
}

/// Acceptance for a generic type: `array<…>`/`list<…>`/`non-empty-*<…>` (per the
/// phpstan#14939 list semantics), simple `int<lo, hi>` ranges; everything else
/// (`Collection<…>`, `iterable<…>`, template generics) is silent.
fn accepts_generic(
    cx: &Cx,
    cfile: usize,
    coff: u32,
    base: &str,
    args: &[steins_phpdoc::ast::GenericArg],
    v: &CVal,
) -> Tri {
    let base_lc = base.to_ascii_lowercase();
    match base_lc.as_str() {
        // `array`/`non-empty-array`/`list`/`non-empty-list`, per phpstan#14939's
        // list semantics.
        //
        // NOT converged onto `lower_generic` + `admits_val` (unlike the
        // `associative-array`/`int`/`key-of` arms below): a residue-slice attempt
        // at that convergence regressed `nested_generic_fires_on_inner_mismatch`
        // (`steins-infer/tests/generics_carry.rs`) — `list<Box<int>>` with a
        // `Box<string>` element must still fire `No`, but a `Box` element is an
        // **object**, which `cval_as_val` cannot represent (the value domain has
        // no object inhabitant, ADR-0035/0038), so the whole array collapses to
        // `None` → `Maybe`, silently losing the inner-mismatch detection. Unlike
        // the associative-array/`key-of` arms (whose fixtures never exercise an
        // object element), this leg is reached for arrays of PROJECT OBJECTS
        // (`list<Box<int>>`, `array<string, User>`, …), so `check_arraylike`'s
        // per-element recursion through the lane-local `accepts()` — which
        // dispatches object elements to `accepts_class_generic`/
        // `accepts_class_name` — is load-bearing, not incidental duplication.
        // Kept as the stricter-correct side per the fixture, ADR-0062 §5's own
        // discipline: one relation only where the value domain can host it.
        "array" | "non-empty-array" | "list" | "non-empty-list" => {
            let CVal::Array(entries) = v else { return Tri::No };
            let non_empty = base_lc.starts_with("non-empty");
            let require_list = base_lc.ends_with("list");
            // list<V> / non-empty-list<V>: 1 arg (value). array<V>: 1 arg (value);
            // array<K, V>: 2 args (key, value).
            let (key_ty, val_ty) = match (require_list, args) {
                (_, [v1]) => (None, &v1.ty),
                (false, [k, v2]) => (Some(&k.ty), &v2.ty),
                (true, [_, v2]) => (None, &v2.ty), // list<int, V> is unusual; ignore key
                _ => return Tri::Maybe,
            };
            check_arraylike(cx, cfile, coff, entries, key_ty, val_ty, require_list, non_empty)
        }
        // `int<lo, hi>` and Phan's `int-range<lo, hi>` — the same bounded range under
        // two base names. Neither the recognized spellings nor the bound grammar
        // (`min`/`max`/integer literals, an unparseable bound → `Opaque` → silent)
        // is restated here: the one generic table lowers it and the shared relation
        // judges it, exactly as the identifier path does (ADR-0030, ADR-0062 §5).
        "int" | "int-range" if args.len() == 2 => match cval_as_val(v) {
            Some(val) => {
                steins_contract::admits_val(&steins_contract::lower_generic(base, args), &val)
            }
            None => Tri::Maybe,
        },
        // Phan's `associative-array<K, V>` / `non-empty-associative-array<K, V>`
        // (census bucket ix): unlike the plain-array arm above, this does not
        // restate a hand-rolled list check — `lower_generic` already carries the
        // not-a-list refusal (`MapOf.not_list`, seeded `is_list = No` via
        // `to_shape_fact`), so the shared relation judges it exactly as the
        // `int`/`int-range` delegation just above does.
        "associative-array" | "non-empty-associative-array" if matches!(args.len(), 1 | 2) => {
            match cval_as_val(v) {
                Some(val) => {
                    steins_contract::admits_val(&steins_contract::lower_generic(base, args), &val)
                }
                None => Tri::Maybe,
            }
        }
        // `key-of<T>` / `value-of<T>` (census bucket vi, inline tier): the one
        // generic table projects the key/value set out of the lowered operand and
        // the shared relation judges the result, so this lane restates neither the
        // projection nor the "which operands are enumerable" rule. An operand the
        // projection cannot read (a template, a class-constant fetch, an unsealed
        // shape) lowers to `Opaque`, which is `Maybe` for every value — the floor
        // arrives through the same delegation rather than a guard here.
        "key-of" | "value-of" if args.len() == 1 => {
            let Some(val) = cval_as_val(v) else { return Tri::Maybe };
            // The operand comes from one of two resolvers, and the projection that
            // reads it is the SAME function either way: `lower_generic` resolves the
            // context-free operands (an inline shape, `array<K, V>`, `list<T>`), and
            // the const-fetch resolver just below supplies the one operand only this
            // lane can see — a class constant holding an array, which needs the
            // project index. Two resolvers, one projection rule (ADR-0030).
            let projected = const_operand_shape(cx, cfile, coff, &args[0].ty).map(|shape| {
                if base_lc == "key-of" {
                    steins_contract::project_key_of(&shape)
                } else {
                    steins_contract::project_value_of(&shape)
                }
            });
            match projected {
                Some(ty) => steins_contract::admits_val(&ty, &val),
                None => {
                    steins_contract::admits_val(&steins_contract::lower_generic(base, args), &val)
                }
            }
        }
        // A class-level generic `Class<A, …>` (ADR-0032 tier 3, issue #10).
        _ => accepts_class_generic(cx, cfile, coff, base, args, v),
    }
}

/// Acceptance of a value against a class-level generic contract `Class<A, …>`
/// (ADR-0032 tier 3, issue #10). The class half rides the trinary is-a oracle
/// exactly as the bare-class identifier path; the argument half judges ONLY when
/// the object carries provable, arity-matched per-position type-argument values
/// (from `new`-site propagation — see [`Cx::infer_generic_args`]).
///
/// Honesty bounds (zero-FP, stage 1):
/// - A **non-object** value is silent (`Maybe`): the bare-class identifier path
///   owns scalar-vs-class `No`; a *generic* spelling never manufactures it here.
/// - The class half only **gates**: a `No`/`Unknown` is-a answers `Maybe`, never a
///   manufactured `No` — generic-class *class-mismatch* reporting is deferred, so
///   the sole `No` this arm yields comes from a provable **argument-half** violation
///   on an object that **is** the required class.
/// - An **empty** carry or an **arity mismatch** between declared arguments and
///   carried values answers `Maybe` (no provable knowledge / library-author
///   inconsistency stays a thin lint, per ADR-0032).
fn accepts_class_generic(
    cx: &Cx,
    cfile: usize,
    coff: u32,
    base: &str,
    args: &[steins_phpdoc::ast::GenericArg],
    v: &CVal,
) -> Tri {
    let CVal::Object(obj_class, targs) = v else { return Tri::Maybe };
    let target = cx.resolve_pclass(cfile, coff, base);
    // Class half: proceed only on a proven is-a; otherwise stay silent.
    if cx.is_a(obj_class, &target) != IsA::Yes {
        return Tri::Maybe;
    }
    // Argument half: needs provable, arity-matched per-position knowledge.
    if targs.is_empty() || targs.len() != args.len() {
        return Tri::Maybe;
    }
    let mut r = Tri::Yes;
    for (declared, actual) in args.iter().zip(targs.iter()) {
        r = combine(r, accepts(cx, cfile, coff, &declared.ty, actual));
        if r == Tri::No {
            return Tri::No;
        }
    }
    r
}

/// Membership for an `array`/`list` generic (per phpstan#14939): a value is a list
/// iff its normalized keys are exactly `0..n-1` in order; element (and, for
/// `array<K, V>`, key) membership is checked recursively; an uncertain element
/// makes the whole check `Maybe` (silent).
#[allow(clippy::too_many_arguments)]
fn check_arraylike(
    cx: &Cx,
    cfile: usize,
    coff: u32,
    entries: &[(NormKey, CVal)],
    key_ty: Option<&PType>,
    val_ty: &PType,
    require_list: bool,
    non_empty: bool,
) -> Tri {
    if non_empty && entries.is_empty() {
        return Tri::No;
    }
    if require_list && !is_list_shaped(entries) {
        return Tri::No;
    }
    let mut r = Tri::Yes;
    for (k, cv) in entries {
        if let Some(kt) = key_ty {
            r = combine(r, accepts(cx, cfile, coff, kt, &normkey_cval(k)));
            if r == Tri::No {
                return Tri::No;
            }
        }
        r = combine(r, accepts(cx, cfile, coff, val_ty, cv));
        if r == Tri::No {
            return Tri::No;
        }
    }
    r
}

/// Whether normalized `entries` form a list: keys exactly `0, 1, …, n-1` in order.
fn is_list_shaped(entries: &[(NormKey, CVal)]) -> bool {
    entries
        .iter()
        .enumerate()
        .all(|(i, (k, _))| matches!(k, NormKey::Int(n) if *n == i as i64))
}

/// A normalized key as a scalar [`CVal`] (for key membership).
fn normkey_cval(k: &NormKey) -> CVal {
    match k {
        NormKey::Int(i) => CVal::Scalar(ArgValue::Int(*i)),
        NormKey::Str(s) => CVal::Scalar(ArgValue::Str(s.clone())),
    }
}

/// Membership for an array-shape / list-shape (per phpstan#14939): `array{…}` is an
/// order-agnostic required-key map (optional `?` keys may be absent; sealed unless
/// `…`); `list{…}` is positional. A missing required key, a definite element-type
/// violation, an extra key in a sealed shape, or an extra key/value violating the
/// unsealed tail contract → `No`. An unresolvable shape key (a const-fetch) makes
/// the whole check `Maybe`.
///
/// **One acceptance relation** (ADR-0030's no-second-relation discipline, ADR-0062
/// §5). The structural rules are *not* implemented here: this lowers the proven
/// value's keys into the domain's key vocabulary, hands `steins-contract` the
/// declared shape, and lets [`steins_contract::shape_verdict`] — the same code the
/// fact path's `admits_shape` runs — decide. Only the leaf judgment stays local,
/// because the proven lane's values include objects (judged through the is-a
/// oracle) which the value domain cannot express. The divergence this convergence
/// removed: the tail **key** contract went unchecked here, so `['a' => 1, 9 => 2]`
/// passed `array{a: int, ...<string, int>}` on this path while the fact path
/// rejected it.
fn accepts_shape(cx: &Cx, cfile: usize, coff: u32, shape: &steins_phpdoc::ast::ArrayShape, v: &CVal) -> Tri {
    let CVal::Array(entries) = v else { return Tri::No };
    // An unresolvable shape key (const-fetch) → no verdict.
    let Some(keys) = steins_contract::shape_keys(shape) else { return Tri::Maybe };
    let spec = steins_contract::ShapeSpec {
        list: matches!(shape.kind, ArrayShapeKind::List | ArrayShapeKind::NonEmptyList),
        sealed: shape.sealed,
        non_empty: matches!(
            shape.kind,
            ArrayShapeKind::NonEmptyArray | ArrayShapeKind::NonEmptyList
        ),
        fields: keys
            .into_iter()
            .zip(&shape.items)
            .map(|(k, item)| (k, item.optional, &item.value))
            .collect(),
        tail: shape.unsealed.as_ref().map(|u| (u.key.as_deref(), &*u.value)),
    };
    let items: Vec<(VKey, &CVal)> =
        entries.iter().map(|(k, cv)| (domain_key(k), cv)).collect();
    steins_contract::shape_verdict(
        &spec,
        &items,
        &mut |ty, cv| accepts(cx, cfile, coff, ty, cv),
        &mut |ty, k| accepts(cx, cfile, coff, ty, &key_cval(k)),
    )
}

/// A proven array's normalized key in the domain's key vocabulary (the shared
/// acceptance relation speaks [`VKey`], the trace IR speaks [`NormKey`]).
fn domain_key(k: &NormKey) -> VKey {
    match k {
        NormKey::Int(i) => VKey::Int(*i),
        NormKey::Str(s) => VKey::Str(s.clone()),
    }
}

/// A runtime array key as a proven scalar value — the subject of an unsealed
/// tail's key contract.
fn key_cval(k: &VKey) -> CVal {
    match k {
        VKey::Int(i) => CVal::Scalar(ArgValue::Int(*i)),
        VKey::Str(s) => CVal::Scalar(ArgValue::Str(s.clone())),
    }
}

/// The phpdoc contract-acceptance check for one argument at a call site. Runs only
/// when the native check did **not** fire at this site (no double-report). Reports
/// `phpdoc.param-mismatch` iff the proven value provably does not inhabit the
/// `@param` type. `cfile`/`coff` locate the callee's docblock context (class-name
/// resolution). Returns nothing for `Maybe`/`Yes`.
///
/// # Assertion-helper exemption (ADR-0030)
///
/// A function/method whose docblock carries an assertion tag (`@phpstan-assert`
/// and its `-if-true`/`-if-false`/negated variants) targeting parameter `$x` is an
/// **assertion helper for `$x`**: its `@param` for `$x` states a *post*-condition
/// that the helper establishes about `$x`, not a precondition its callers must
/// satisfy. Checking a call-site argument against it is therefore semantically
/// wrong — the whole point of such a helper is to be called with a *wider* value
/// (e.g. `mixed`/`string|int`) and to narrow it. So we skip `phpdoc.param-mismatch`
/// for that parameter. This holds for all three assert kinds and the negated form.
///
/// Scope of the exemption, deliberately narrow:
/// - **Other parameters** of the same function are still checked (the tag exempts
///   only its own target).
/// - **`@return`** checking is unaffected (a different relation entirely).
/// - **Native** runtime checks are unaffected: a native type hint is a real
///   runtime gate regardless of any docblock assertion, so it still fires (and,
///   firing first, already suppresses this phpdoc check at that site).
///
/// This slice does **not** implement the *positive* refinement effect — applying
/// the asserted type to the caller's environment after the call. That is a
/// branch-analysis capability and lands with the structured trace tree / value
/// domain (ADR-0031, ADR-0035); here we only suppress the incorrect precondition
/// reading.
#[allow(clippy::too_many_arguments)]
fn check_phpdoc_param(
    cx: &Cx,
    folder: &mut dyn Folder,
    envelopes: &Envelopes,
    param: &Param,
    cfile: usize,
    coff: u32,
    callee: &str,
    arg_offset: u32,
    value: &ArgValue,
    env: &HashMap<String, Known>,
    store: &Store,
    poisoned: bool,
    in_descent: bool,
    out: &mut Vec<Diagnostic>,
) {
    // Assertion-helper exemption (see the doc comment above): this parameter's
    // `@param` is a post-condition, so a call-site argument cannot violate it.
    if envelopes.is_assert_target(&param.name) {
        return;
    }
    let Some(ty) = envelopes.param(&param.name) else { return };

    // ADR-0063 P3 — the refined callable spellings' obligations, propagation-pass
    // lane. A variable bound to a PROVEN closure value carries no scalar fact at all
    // (`Known::closure` sets `fact: None`), so neither the proven-value lane nor the
    // abstract-fact lane below can see it; the obligation is judged here instead,
    // against the closure's definition, exactly as [`check_callable_arg`] judges a
    // closure written directly in argument position.
    //
    // Restricted to a non-descent site on purpose: a `ClosureVal` records only its
    // definition *offset*, and the fixpoint's closure symbol is file-keyed. Outside a
    // descent the env and `cx` are the same file by construction; inside one they can
    // differ, and a same-offset closure in the other file would be a different
    // closure. Documented ceiling rather than a guess.
    if !in_descent
        && let ArgValue::Var(name) = value
        && let Some(cv) = env.get(name).and_then(|k| k.closure.as_ref())
        && let ContractTy::CallableTy { obl, .. } = steins_contract::lower(ty)
        && !obl.is_bare()
        && let Some(violation) = callable_obl_violation(cx, obl, &cv.target)
    {
        push_obligation_diag(cx, violation, callee, ty, &param.name, arg_offset, out);
        return;
    }

    let param_name = &param.name;
    let rendered = match cx.resolve_cval(value, env, store, poisoned, folder) {
        Some(cv) => {
            // A parameter that is nullable by its native type, or implicitly nullable
            // via a `= null` default, accepts `null` regardless of a non-nullable
            // `@param` spelling — PHP/PHPStan honor this, so reporting it would be a
            // false positive.
            if matches!(cv, CVal::Scalar(ArgValue::Null))
                // ADR-0043 stage 1: consult native nullability only for scalar-value
                // types. An object-bearing type contributes no native-nullable signal
                // here (it lowered to `None` before ADR-0043), so `?Foo` does not
                // change which `null` arguments this guard accepts.
                && (param.has_null_default
                    || param.ty.as_ref().is_some_and(|t| t.nullable && !t.has_instance()))
            {
                return;
            }
            if accepts(cx, cfile, coff, ty, &cv) != Tri::No {
                return;
            }
            // ADR-0043 stage 4: a class-touching verdict is guard-blind inside a
            // binding descent (mirror of the native `object_world_guard_blind`) —
            // the callee's in-body type guards that would narrow the rebound value
            // are unmodeled. Scalar-vs-scalar phpdoc checks stay live.
            if phpdoc_object_guard_blind(in_descent, ty, Some(&cv)) {
                return;
            }
            rendered_cval(&cv)
        }
        // Abstract-fact path (Feature E, ADR-0030/0035): an argument that resolves
        // to an abstract fact (not a proven value — e.g. a native-seeded param or a
        // guard-refined var) is judged by the domain's **set** acceptance via
        // `steins_contract::admits_fact`. Only a definite `No` (every value the fact
        // admits is rejected) reports; `Maybe` is silent.
        None => {
            let Some(fact) = arg_abstract_fact(value, env, poisoned) else { return };
            let cty = steins_contract::lower(ty);
            // ADR-0043 stage 4 — the class valve. A class-touching contract used to
            // stay silent against every fact. It opens for exactly one sound case:
            // a **pure class contract of known classes** (`Foo`, `Foo|null`, `A|B`)
            // against a definite scalar fact. The abstract-fact domain is scalar-only
            // (ADR-0035/0038 — no object inhabitant), so any fact here is a definite
            // scalar, and a scalar is never a member of a class type (pure set
            // membership, no coercion). It stays shut for an unknown identifier — a
            // `@template` param or `@phpstan-type` alias may denote a scalar — and,
            // like the proven path, for any class-touching verdict inside a descent.
            let open_class_valve = is_pure_class_contract(cx, cfile, coff, ty)
                && !phpdoc_object_guard_blind(in_descent, ty, None);
            if contract_touches_class(&cty) && !open_class_valve {
                return;
            }
            if steins_contract::admits_fact(&cty, fact) != Certainty::No {
                return;
            }
            describe_fact(fact)
        }
    };
    let pos = cx.tree().position(arg_offset);
    let message = format!(
        "argument {rendered} to {callee}() violates declared @param {ty} ${param_name} — declared contract violation",
    );
    out.push(Diagnostic {
        id: PARAM_MISMATCH_ID,
        path: cx.path().to_owned(),
        line: pos.line,
        column: pos.column,
        message,
        facet: None,
        fix: None,
    });
}

/// Bind each **named** argument (`name: <expr>`) to its target parameter by name
/// and run the same declared-contract acceptance judgment [`check_phpdoc_param`]
/// applies to a positional argument (Gap A). Named-argument binding is PHP-exact:
///
/// - **case-sensitive** name matching (`f(A: 1)` on `$a` is a fatal `Error`, not a
///   binding — PHP does not fold case here), so an unmatched name binds nothing and
///   is silent (the arity lane owns that `Error`);
/// - a **variadic** collector parameter takes the named argument as a keyed element
///   (`function f(...$rest)`, `f(x: 1)`), never a scalar contract, so it is skipped;
/// - a **by-ref** parameter is skipped exactly as the positional lane skips it;
/// - a name that resolves to a parameter already filled by a **positional**
///   argument (index `< positional_count`) is the deferred overwrite `Error` — a
///   fatal, so neither the positional nor this lane reports it (mirrors
///   [`emit_arity`]'s overwrite guard).
///
/// `positional_count` is the call's positional-argument arity (`call.args.len()`);
/// every other argument is shared verbatim with the positional-lane call.
#[allow(clippy::too_many_arguments)]
fn check_named_phpdoc_params(
    cx: &Cx,
    folder: &mut dyn Folder,
    envelopes: &Envelopes,
    params: &[Param],
    positional_count: usize,
    cfile: usize,
    coff: u32,
    callee: &str,
    named_args: &[NamedArg],
    env: &HashMap<String, Known>,
    store: &Store,
    poisoned: bool,
    in_descent: bool,
    out: &mut Vec<Diagnostic>,
) {
    for na in named_args {
        let Some((idx, param)) = params.iter().enumerate().find(|(_, p)| p.name == na.name) else {
            continue;
        };
        if param.variadic || param.by_ref || idx < positional_count {
            continue;
        }
        check_phpdoc_param(
            cx,
            folder,
            envelopes,
            param,
            cfile,
            coff,
            callee,
            na.span.start,
            &na.value,
            env,
            store,
            poisoned,
            in_descent,
            out,
        );
    }
}

/// The kind of callable-signature incompatibility a bound closure / first-class
/// callable exhibits against a declared `callable(...)` contract (issue #11).
#[derive(Debug, Clone, Copy)]
enum CallableViolation {
    /// The closure's declared parameter at this position is narrower than the
    /// contract supplies (parameter contravariance broken).
    Param(usize),
    /// The closure's declared return is provably incompatible with the contract's
    /// (return covariance broken).
    Return,
    /// The closure requires more parameters than the contract supplies, so the
    /// callee's invocation would `ArgumentCountError` (arity).
    Arity,
}

/// Lower a native scalar/union type to a [`ContractTy`] for the callable-signature
/// variance check (issue #11). Scalars and bool-literals map to their contract
/// arm; an object member maps to a class arm (which [`normalize::subsumes`] judges
/// only reflexively, so cross-class comparisons stay `Maybe` — silent); a nullable
/// hint adds a `null` arm. A [`NativeType`] is always representable — the syntax
/// layer already dropped `mixed`/`iterable`/`callable`/intersection hints to
/// `None`, so nothing here needs an `Opaque` escape.
fn native_to_contract(nt: &NativeType) -> ContractTy {
    let mut arms: Vec<ContractTy> = nt
        .members
        .iter()
        .map(|m| match m {
            TypeMember::Scalar(ScalarType::Int) => ContractTy::Base(steins_domain::Base::Int),
            TypeMember::Scalar(ScalarType::Float) => ContractTy::Base(steins_domain::Base::Float),
            TypeMember::Scalar(ScalarType::String) => ContractTy::Base(steins_domain::Base::String),
            TypeMember::Scalar(ScalarType::Bool) => ContractTy::Base(steins_domain::Base::Bool),
            TypeMember::BoolLiteral(b) => ContractTy::LitBool(*b),
            TypeMember::Instance { fqn, .. } => ContractTy::Class(fqn.clone()),
            TypeMember::InstanceInter(cs) => {
                ContractTy::Inter(cs.iter().map(|c| ContractTy::Class(c.fqn.clone())).collect())
            }
        })
        .collect();
    if nt.nullable {
        arms.push(ContractTy::Null);
    }
    match arms.len() {
        1 => arms.pop().expect("len checked"),
        _ => ContractTy::Union(arms),
    }
}

/// Whether a contract arm is decidable by the **scalar** overlap relation — the
/// only positions the callable-variance check will fire a definite `No` on
/// (issue #11). A bare identifier in a callable signature (`callable(T): T`) is
/// syntactically indistinguishable from a class name, and is far more often an
/// unbound `@template` than a real class (ADR-0032/0051 — no call-site template
/// solver), so a `Class`/`ObjectAny`/`Opaque`/array/callable arm is treated as
/// undecidable here and stays silent (zero-FP). Only scalar/literal/null arms —
/// where `subsumes` gives a sound `No` and no template can hide — are judged.
/// `StrOpaque` (`class-string` et al.) and `Mixed` never yield a decidable `No`
/// anyway, so excluding them costs nothing.
fn scalar_decidable(ty: &ContractTy) -> bool {
    match ty {
        ContractTy::Base(_)
        | ContractTy::IntIn(_)
        | ContractTy::StrWith(_)
        | ContractTy::LitInt(_)
        | ContractTy::LitFloat(_)
        | ContractTy::LitStr(_)
        | ContractTy::LitBool(_)
        | ContractTy::Null
        | ContractTy::Never => true,
        ContractTy::Union(m) | ContractTy::Inter(m) => m.iter().all(scalar_decidable),
        _ => false,
    }
}

/// Judge a bound closure's declared native signature against a `callable(...)`
/// contract (issue #11), returning the first definite incompatibility or `None`
/// when compatible or undecidable (zero-FP silence).
///
/// This is the **declared-contract** relation (ADR-0030 divergence #1 — envelope
/// checking, no runtime coercion; PHP does *not* enforce a `callable(int): string`
/// docblock at runtime, verified with `php -r`, so the claim is contract-layer),
/// and it reuses the single overlap relation [`normalize::subsumes`] (the
/// `isSuperTypeOf` shape) as its comparator rather than a bespoke one:
///
/// - **Parameters are contravariant.** At each contract position the closure's
///   declared parameter must accept everything the contract supplies:
///   `subsumes(closure_param, contract_param)`. A closure accepting WIDER than the
///   contract is fine; one requiring NARROWER is the violation. Only a definite
///   `No` (a scalar mismatch such as `string` vs `int`) reports; an undeclared
///   parameter, a template, or a cross-class comparison is `Maybe` → silent. A
///   by-reference position (either side) is skipped — by-ref callable semantics
///   are unverified, so Steins stays silent (zero-FP).
/// - **Return is covariant.** The closure's declared return must be subsumed by
///   the contract's: `subsumes(contract_ret, closure_ret)`. A closure returning
///   narrower/equal is fine; a provably-disjoint return (e.g. `int` vs `string`)
///   is the violation. Only a definite `No` reports; an undeclared return is silent.
/// - **Arity.** A closure REQUIRING more parameters (no default, non-variadic)
///   than the contract supplies would `ArgumentCountError` when the callee invokes
///   it with the contract's arity — verified against PHP 8.5 (`Too few arguments`).
///   PHP ignores surplus arguments, so a closure with FEWER params, or extra
///   OPTIONAL/variadic params, is fine. Skipped when the contract is itself
///   variadic (the callee may pass any number of arguments).
fn callable_sig_violation(
    sig: &steins_contract::CallableSig,
    closure_params: &[Param],
    closure_ret: Option<&NativeType>,
) -> Option<CallableViolation> {
    // Parameter contravariance, positional.
    for (i, cparam) in sig.params.iter().enumerate() {
        if cparam.by_ref || cparam.variadic {
            continue;
        }
        let Some(closure_param) = closure_params.get(i) else { continue };
        if closure_param.by_ref {
            continue;
        }
        let Some(pty) = closure_param.ty.as_ref() else { continue };
        let closure_ty = native_to_contract(pty);
        if scalar_decidable(&closure_ty)
            && scalar_decidable(&cparam.ty)
            && normalize::subsumes(&closure_ty, &cparam.ty) == Certainty::No
        {
            return Some(CallableViolation::Param(i));
        }
    }
    // Return covariance.
    if let Some(ret) = closure_ret {
        let closure_ret_ty = native_to_contract(ret);
        if scalar_decidable(&sig.ret)
            && scalar_decidable(&closure_ret_ty)
            && normalize::subsumes(&sig.ret, &closure_ret_ty) == Certainty::No
        {
            return Some(CallableViolation::Return);
        }
    }
    // Arity: the closure demands more parameters than the contract will supply.
    let contract_variadic = sig.params.iter().any(|p| p.variadic);
    if !contract_variadic {
        let required =
            closure_params.iter().filter(|p| !p.has_default && !p.variadic).count();
        if required > sig.params.len() {
            return Some(CallableViolation::Arity);
        }
    }
    None
}

/// A violated obligation of a **refined** callable spelling (ADR-0063 P3) — the
/// obligation half of the callable contract, beside [`CallableViolation`]'s
/// signature half.
#[derive(Clone, Copy)]
enum ObligationViolation {
    /// `pure-callable`/`pure-closure`/`static-pure-closure`: the bound callable's
    /// inferred effect envelope is provably not pure.
    Purity,
    /// `static-closure`/`static-pure-closure`: the bound closure is not declared
    /// `static`, so it can be bound to an object and reach `$this`.
    StaticBinding,
}

/// The [`ClosureTarget`] a lowered [`ClosureRef`] argument denotes — the one shape
/// [`callable_obl_violation`] judges, so the direct pass (a closure written *in*
/// argument position) and the propagation pass (a variable holding a proven closure
/// value) ask exactly the same question.
fn closure_target_of_ref(cref: &ClosureRef) -> ClosureTarget {
    match cref {
        ClosureRef::Anonymous { def_offset, .. } => ClosureTarget::Scope(*def_offset),
        ClosureRef::FunctionName(name) => ClosureTarget::Named(name.clone()),
    }
}

/// Judge a bound callable against the obligations of a refined callable spelling
/// (ADR-0063 §2 decision 4). `None` is "no proven violation" — the zero-FP floor:
/// every leg that cannot see the callable's definition answers `None` rather than
/// guessing, so an opaque callable value is silent by construction.
///
/// The two obligations are decided by different machinery, which is why the ADR
/// keeps them separate: `static` is written in the syntax (a mechanical binding
/// check against [`Scope::is_static`]), purity is a property of the body that only
/// the effect fixpoint can answer ([`Cx::provably_impure`]).
///
/// `closure_only` is **not** judged here: a closure literal and a first-class
/// callable both evaluate to a real `Closure` instance, so they satisfy it by
/// construction. The spelling's closure half bites on the *value* side instead
/// (`steins_contract::admits_val`/`admits_fact` — a callable-string is not a
/// `Closure`), which is exactly the fixtures' claim that the two halves of
/// `pure-closure` fail independently.
fn callable_obl_violation(
    cx: &Cx,
    obl: steins_contract::CallableObl,
    target: &ClosureTarget,
) -> Option<ObligationViolation> {
    match target {
        ClosureTarget::Scope(def_offset) => {
            let scope = cx.closure_scope(*def_offset)?;
            if obl.is_static && !scope.is_static {
                return Some(ObligationViolation::StaticBinding);
            }
            // Closures are same-file, and every caller of this leg judges a closure
            // written in the file `cx` points at, so the fixpoint's file-keyed
            // closure symbol matches by construction.
            if obl.pure
                && cx.provably_impure(&Sym::Closure(cx.path().to_owned(), *def_offset))
            {
                return Some(ObligationViolation::Purity);
            }
            None
        }
        ClosureTarget::Named(nameref) => {
            // `f(...)` — a first-class callable of a free function. It evaluates to a
            // `Closure` with no bound `$this`, so it satisfies the static-binding
            // obligation the way `static function () {}` does; only purity can be
            // violated, and only when the name resolves to a *user* function whose
            // body the fixpoint actually read (a builtin or an ambiguous name has no
            // envelope to judge, so it stays silent).
            if !obl.pure {
                return None;
            }
            let FnResolution::User(site) = cx.resolve_function(nameref) else { return None };
            let fqn = cx.fn_decl(site).fqn.clone();
            if cx.provably_impure(&Sym::Func(fqn)) {
                return Some(ObligationViolation::Purity);
            }
            None
        }
    }
}

/// Emit the one `phpdoc.param-mismatch` a violated callable obligation produces.
/// Shared by both lanes so a closure written in argument position and a variable
/// holding the same closure report identically.
#[allow(clippy::too_many_arguments)]
fn push_obligation_diag(
    cx: &Cx,
    violation: ObligationViolation,
    callee: &str,
    ty: &PType,
    param_name: &str,
    arg_offset: u32,
    out: &mut Vec<Diagnostic>,
) {
    let reason = match violation {
        ObligationViolation::Purity => {
            "the bound callable's inferred effect envelope is not pure"
        }
        ObligationViolation::StaticBinding => "the bound closure is not declared static",
    };
    let pos = cx.tree().position(arg_offset);
    out.push(Diagnostic {
        id: PARAM_MISMATCH_ID,
        path: cx.path().to_owned(),
        line: pos.line,
        column: pos.column,
        message: format!(
            "callable argument to {callee}() violates declared @param {ty} ${param_name} — {reason}",
        ),
        facet: None,
        fix: None,
    });
}

/// Check a closure / first-class-callable argument at a call site against a
/// declared `callable(...)` `@param` contract (issue #11), emitting at most one
/// `phpdoc.param-mismatch`. Silent unless the contract carries a signature AND the
/// bound callable's declared *native* signature (Verified — ADR-0052 N2) provably
/// violates it. Reuses the `phpdoc.param-mismatch` lane: a callable argument that
/// breaks the declared callable signature *is* a violation of the callee's
/// `@param $callback` (id-choice recorded in the commit body).
///
/// The closure's declared signature is a static CST fact — it does not depend on
/// the call-site environment (captures do not change the parameter/return hints),
/// so this rides the env-free direct pass (no overlap with the propagation pass).
fn check_callable_arg(
    cx: &Cx,
    envelopes: &Envelopes,
    param: &Param,
    callee: &str,
    arg_offset: u32,
    closure: &ClosureRef,
    out: &mut Vec<Diagnostic>,
) {
    let Some(ty) = envelopes.param(&param.name) else { return };
    let ContractTy::CallableTy { sig, obl } = steins_contract::lower(ty) else { return };

    // ADR-0063 P3: the refined spellings' obligations come first. They are decided
    // from the bound callable's *definition* (its `static` keyword, its inferred
    // effect envelope) rather than from the declared call shape, so they apply to a
    // bare `pure-callable` that carries no signature at all — and when both halves
    // are violated the obligation is the more specific report.
    if !obl.is_bare()
        && let Some(violation) = callable_obl_violation(cx, obl, &closure_target_of_ref(closure))
    {
        push_obligation_diag(cx, violation, callee, ty, &param.name, arg_offset, out);
        return;
    }

    let Some(sig) = sig else { return };

    // Resolve the bound callable's declared native signature. Anonymous closures
    // address their own scope by definition offset; a first-class callable naming
    // a user function reuses the function-resolution leg (S5) — a builtin or
    // unresolvable name has no ground-truth signature, so it stays silent (Maybe).
    let (closure_params, closure_ret): (&[Param], Option<&NativeType>) = match closure {
        ClosureRef::Anonymous { def_offset, .. } => {
            let Some(scope) = cx.closure_scope(*def_offset) else { return };
            (scope.params.as_slice(), scope.ret_ty.as_ref())
        }
        ClosureRef::FunctionName(name) => match cx.resolve_function(name) {
            FnResolution::User(site) => {
                let decl = cx.fn_decl(site);
                (decl.params.as_slice(), decl.ret.as_ref())
            }
            _ => return,
        },
    };

    let Some(violation) = callable_sig_violation(&sig, closure_params, closure_ret) else {
        return;
    };
    let param_name = &param.name;
    let message = match violation {
        CallableViolation::Param(i) => format!(
            "callable argument to {callee}() violates declared @param {ty} ${param_name} — parameter #{} type is incompatible (callable parameter contravariance)",
            i + 1,
        ),
        CallableViolation::Return => format!(
            "callable argument to {callee}() violates declared @param {ty} ${param_name} — return type is incompatible (callable return covariance)",
        ),
        CallableViolation::Arity => format!(
            "callable argument to {callee}() violates declared @param {ty} ${param_name} — it requires more parameters than the callable signature supplies",
        ),
    };
    let pos = cx.tree().position(arg_offset);
    out.push(Diagnostic {
        id: PARAM_MISMATCH_ID,
        path: cx.path().to_owned(),
        line: pos.line,
        column: pos.column,
        message,
        facet: None,
        fix: None,
    });
}

// ---------------------------------------------------------------------------
// Builtin return facts (ADR-0056 R1): the reflected envelope seeds the value
// domain; a curated row refines strictly within it. The admission gate of §2 is
// factored into pure functions so every leg is unit-testable without a sidecar.
// ---------------------------------------------------------------------------

/// Combine a reflected return-type string with an optional curated refinement
/// into the value-domain [`Fact`] to seed (ADR-0056 §1–2), or `None` when nothing
/// representable can be seeded.
///
/// * The **reflected envelope** is `return_type` lowered to a single-base fact
///   (`bool`, `int`, `string`, `float`, or their `?T` nullable form). A multi-base
///   union (`int|false`), a non-scalar (`array`, `object`, a class, `void`), or
///   `mixed` is not representable as one [`Fact`] and yields `None` — the union
///   case belongs to the contract-lane arms (§4) and remains deferred.
/// * A **curated refinement** (`curated`, a phpdoc type string such as
///   `int<0, max>` or `non-empty-string`) is admitted only when `minor_matches_pin`
///   holds (the A11 pin, §2), it lowers to a fact of the SAME base as the envelope,
///   AND the envelope extensionally subsumes it ([`normalize::subsumes`] `== Yes`).
///   Otherwise the envelope stands alone. Curation may narrow within the envelope;
///   it may never widen or cross bases — so a stale curated row loses precision,
///   never manufactures a wrong premise the runtime disowns.
fn admit_return_fact(return_type: &str, curated: Option<&str>, minor_matches_pin: bool) -> Option<Fact> {
    let envelope_ty = steins_contract::lower_str(return_type)?;
    let envelope = envelope_fact(&envelope_ty)?;
    // No curated row, or the minor pin fails: the envelope stands alone.
    let Some(curated) = curated.filter(|_| minor_matches_pin) else {
        return Some(envelope);
    };
    // The curated refinement must lower, be extensionally subsumed by the
    // envelope (curated ⊆ reflected, the §1.2 subset check), and share the
    // envelope's base. Any failure keeps the envelope alone (never widens).
    let refined = steins_contract::lower_str(curated).and_then(|cty| {
        if normalize::subsumes(&envelope_ty, &cty).is_yes() {
            contractty_to_fact(&cty).filter(|f| fact_base(f) == fact_base(&envelope))
        } else {
            None
        }
    });
    Some(refined.unwrap_or(envelope))
}

/// The scalar base of a [`General`]/[`Refined`] fact (`None` for the finite
/// layers, which the return-fact path never produces).
///
/// [`General`]: Fact::General
/// [`Refined`]: Fact::Refined
fn fact_base(f: &Fact) -> Option<Base> {
    match f {
        Fact::General { base, .. } | Fact::Refined { base, .. } => Some(*base),
        // The array stratum has no scalar base.
        Fact::Singleton(_) | Fact::OneOf(_) | Fact::Shape { .. } => None,
    }
}

/// Lower a reflected envelope [`ContractTy`] to the single-base value-domain
/// [`Fact`] it seeds, or `None` when it is not a single representable scalar base:
/// a bare `Base(b)` → `General{b}`, and a two-member `?T` union (`{Null, Base(b)}`)
/// → `General{b, nullable}`. Everything else (multi-base unions, non-scalars,
/// `mixed`) yields `None`.
fn envelope_fact(ty: &ContractTy) -> Option<Fact> {
    match ty {
        ContractTy::Base(b) => Some(Fact::General { base: *b, nullable: false }),
        ContractTy::Union(members) if members.len() == 2 && members.iter().any(|m| matches!(m, ContractTy::Null)) => {
            let base = members.iter().find_map(|m| match m {
                ContractTy::Base(b) => Some(*b),
                _ => None,
            })?;
            Some(Fact::General { base, nullable: true })
        }
        _ => None,
    }
}

/// Lower a curated refinement [`ContractTy`] to a value-domain [`Fact`] (ADR-0056
/// §1.2), or `None` when it is not a scalar refinement the domain carries. Handles
/// the base layer and the two Refined refinements (`int<lo, hi>`, string
/// predicates); a two-member `?T` nullable wrapper is unwrapped and re-nulled.
/// Unions of more than the nullable pair, and non-scalars, yield `None` — a
/// curated row that cannot be a single fact simply does not refine (the envelope
/// stands).
fn contractty_to_fact(ty: &ContractTy) -> Option<Fact> {
    match ty {
        ContractTy::Base(b) => Some(Fact::General { base: *b, nullable: false }),
        ContractTy::IntIn(r) => Some(Fact::refined(Base::Int, Refinement::Int(*r), false)),
        ContractTy::StrWith(p) => Some(Fact::refined(Base::String, Refinement::Str(*p), false)),
        ContractTy::Union(members) if members.len() == 2 && members.iter().any(|m| matches!(m, ContractTy::Null)) => {
            let inner = members.iter().find(|m| !matches!(m, ContractTy::Null))?;
            fact_with_null(&contractty_to_fact(inner)?)
        }
        _ => None,
    }
}

/// Add null admissibility to a single-base fact (the `?T` curated wrapper). `None`
/// for a finite fact (never produced here).
fn fact_with_null(f: &Fact) -> Option<Fact> {
    match f {
        Fact::General { base, .. } => Some(Fact::General { base: *base, nullable: true }),
        Fact::Refined { base, refinement, .. } => Some(Fact::refined(*base, *refinement, true)),
        // The curated `?T` wrapper is a scalar path; a shape fact refuses
        // rather than acquiring nullability here.
        Fact::Singleton(_) | Fact::OneOf(_) | Fact::Shape { .. } => None,
    }
}

/// The value-domain fact to seed for a call to builtin `name` at a call site
/// (ADR-0056 R1), or `None` when no fact may be seeded. The call must resolve
/// **uniquely to the builtin**: any project user function sharing the simple name
/// shadows (or makes ambiguous) the builtin, so — exactly as [`Cx::try_fold`]
/// does — a simple-name collision refuses (conservative, never an FP). The fact
/// itself, and the sidecar/monkey-patch/pin gating, come from
/// [`Folder::builtin_return_fact`].
fn builtin_call_return_fact(cx: &Cx, folder: &mut dyn Folder, name: &str) -> Option<Fact> {
    if cx.index.has_simple_function(name) {
        return None;
    }
    folder.builtin_return_fact(name)
}

/// The `Known::bound` provenance a floor-seeded fact carries. A constant rather
/// than a literal at each site because two rungs stamp it and a reader comparing
/// them must see one string.
const CATALOG_FLOOR: &str = "declared in the builtin catalog, unverified";

/// The **declared-return floor** (ADR-0069, issues #73/#79): the bottom rung of the
/// return ladder, seeded from `steins_catalog::declared_return` as a declared-contract
/// **arm list**, every arm `Asserted`.
///
/// It fires exactly where [`builtin_call_return_fact`] yielded `None` for this
/// name — which is *per name*, not per run. `--no-php` (and the browser before
/// php-wasm loads) is only the total case; with a live engine the floor still
/// speaks where that engine is **silent** about a name: an extension the analyzing
/// PHP does not load, a builtin with no declared return type. Where the engine
/// answers, the caller never reaches here, so a static row can never outvote the
/// real thing — the consuming engine may not be the pinned one.
///
/// Three gates, and each is the same gate an existing rung already applies:
///
/// 1. **Project shadow wins** — `has_simple_function` refuses exactly as
///    [`builtin_call_return_fact`] does: a project function of the same simple name
///    shadows (or makes ambiguous) the builtin, and the project's own definition is
///    the better answer.
/// 2. **Version discipline** ([`floor_target_admits`]) — the A11-shaped target gate.
/// 3. **The lowering is the declared-return lowering** — `lower_str` →
///    [`flatten_arms`] → [`refine_declared_arms`] against an empty native list,
///    which is byte for byte the path a project function's `@return` takes at a call
///    site ([`fn_return_arms`], issue #60). One lowering, two provenances
///    (ADR-0069 §2). Issue #79 replaced the #73 `envelope_fact` rung with this one
///    rather than stacking a second: a bare base is a trivial arm set, so the
///    envelope case is subsumed, and a `string|false` row now seeds the same way.
///
/// The stratum is not returned: `refine_declared_arms` over an empty native list
/// marks every arm `Asserted`, and the proof layer's all-Verified premise rule then
/// keeps the fact out of every finding by construction. The absence family never
/// comes here at all — existence is a boot-surface fact, and this table answers only
/// about return types.
fn builtin_return_floor(cx: &Cx, name: &str) -> Option<Vec<ContractArm>> {
    if cx.index.has_simple_function(name) {
        return None;
    }
    if !floor_target_admits(name, cx.php_target) {
        return None;
    }
    let declared = steins_catalog::declared_return(name)?;
    let arms = flatten_arms(steins_contract::lower_str(declared)?);
    // The resolver is the **identity**, and now that the mining admits class rows
    // (`imageloadfont` = `GdFont`) that is a claim worth stating rather than an
    // accident of there being nothing to resolve.
    //
    // `refine_declared_arms`' resolver exists to turn a *relative* class name in a
    // project docblock into an FQN against the declaring namespace — `@return Node`
    // inside `namespace App;` means `App\Node`. A functionMap row has no declaring
    // namespace and never carries a relative name: every class it names is a global
    // builtin FQN, written as PHP resolves it (`GdFont`, `CurlHandle`, and the
    // already-qualified `ast\Node` for a namespaced extension). Running a project
    // namespace resolver over those would MANGLE them — `GdFont` read from inside
    // `namespace App;` would become `App\GdFont`, a class that does not exist — so
    // the identity is not merely sufficient here, it is the only correct resolver.
    //
    // `ContractTy::Class` already normalizes on the way in (`lower_identifier` strips
    // a leading `\` and case-folds), so the arms compare by `class_eq` exactly as the
    // generation-time countersign compared them, and the identity preserves that
    // normalization instead of disturbing it. The same argument covers a class
    // *inside* an array row's element type and at the top level, for the same
    // reason and through the same seam.
    refine_declared_arms(&[], arms, &|n: &str| n.to_owned())
}

/// The value-lane seed a floor arm list contributes: the single value-domain
/// [`Fact`] its arms denote, or `None` when they denote more than one.
///
/// Both abstract layers are reachable from here, through the lowering each already
/// owns — [`seed_shape_fact`] for an array arm (ADR-0062 S3), [`contractty_to_fact`]
/// for a scalar one. That is the whole of ADR-0071's consumption side: the array
/// vocabulary needed no new seam, because a builtin row and a project function's
/// `@return array{…}` are the same arm list by the time they arrive here.
///
/// The single-fact rule is the reason the #73 pins survive every widening unchanged.
/// A one-arm row (`string`, `array{a: int}`) binds `$r = f(...)` to one fact, which
/// is what premises the contract-layer return check. A genuinely multi-arm row
/// (`string|false`, `false|array`) has no single fact — the value domain carries no
/// union layer over either the scalar or the array vocabulary — so it stays in the
/// arm lane alone, exactly where a hand-written `@param string|false` would live,
/// and narrows through the same operators.
///
/// A `?T` **scalar** pair is one fact (the domain carries `nullable` as a side flag),
/// which is how the `?string` rows keep the rendering they had at #73. A `?array{…}`
/// row is **not**: [`fact_with_null`] refuses a shape, so the row lives in the arm
/// lane alone. That is a designed refusal rather than a gap — the floor states one
/// nullability rule and applies it to whatever the arms denote, and declining is the
/// FP-safe side of it (the arms still carry the null, so nothing is lost to the
/// declared surface or to guard subtraction).
///
/// A **class** row (`GdFont`, `?GdFont`, bare `object`) declines here too, and for a
/// stronger reason than either of those: the value domain has no object inhabitant at
/// all (ADR-0035/0038), so there is no fact to seed rather than a fact this refuses to
/// seed. Both lowerings say so independently — [`contractty_to_fact`] has no arm for
/// `Class`/`ObjectAny`, and `to_shape_fact` (through [`seed_shape_fact`]) has none
/// either. A class row is therefore **arm-lane only**, unconditionally: it reaches the
/// declared surface and guard subtraction, and it puts nothing whatever into the value
/// lane, which is why it can never become a premise anywhere.
fn floor_value_fact(arms: &[ContractArm]) -> Option<Fact> {
    let (nulls, rest): (Vec<ContractArm>, Vec<ContractArm>) =
        arms.iter().cloned().partition(|a| matches!(a.ty, ContractTy::Null));
    let [only] = rest.as_slice() else { return None };
    let fact = match seed_shape_fact(&rest) {
        Some(shape) => shape,
        None => contractty_to_fact(&only.ty)?,
    };
    if nulls.is_empty() { Some(fact) } else { fact_with_null(&fact) }
}

/// The floor's version gate (ADR-0069 §3, A11-shaped): whether the project's
/// declared PHP target agrees with the minor the mined row was stated at.
///
/// `steins_catalog::declared_return_changed_at` is the change oracle — a
/// `Some(m)` says the builtin's declared return type last moved at minor `m`, so
/// the mined row (stated at the pin) is only known good for a target lying
/// **wholly at or above** `m`. That is stricter than "does not straddle": a target
/// entirely *below* the boundary does not straddle it either, and the row would be
/// as wrong there as in the straddling case.
///
/// An **undeclared target admits**: the row is Asserted anyway, and its consumers
/// tolerate that grade. A name the oracle does not list admits unconditionally —
/// its declared return type never moved across the supported line.
fn floor_target_admits(name: &str, target: Option<&steins_db::PhpTarget>) -> bool {
    let Some(boundary) = steins_catalog::declared_return_changed_at(name) else {
        return true;
    };
    match target {
        Some(t) => t.floor >= boundary,
        None => true,
    }
}

/// The **argument-dependent** return rung (ADR-0061 §1) for the two ADR-0062 §4
/// transfers that read the abstract array stratum: `count($x)` and
/// `array_is_list($x)`. `None` — decline — is a first-class outcome (ADR-0061 §1),
/// and the caller falls through to the argument-insensitive envelope rung exactly
/// as before.
///
/// The rule fires only on a single-argument call whose one argument is a bare
/// variable carrying a non-nullable [`Fact::Shape`]; a nullable base declines
/// (the value may be null, which is a TypeError rather than a count), a second
/// argument declines (`count($x, COUNT_RECURSIVE)` counts something else), and a
/// project function shadowing the simple name declines through
/// [`builtin_call_return_fact`]'s own check.
///
/// **The admission gate is ADR-0061 §2's, unweakened**: the computed fact is
/// seeded only when the sidecar-backed envelope for this name exists (which is
/// where the sidecar-presence and PHP-minor-pin legs live, via
/// [`Folder::builtin_return_fact`]) AND the fact is extensionally inside it —
/// checked in the domain itself, as `envelope ⊔ out == envelope`. A rule that
/// claims something the running engine's own declaration disowns is discarded,
/// never demoted.
///
/// **Stratum is ADR-0061 §3's derivation clause**: the output carries the
/// argument fact's stratum, which for a declared shape is always `Asserted` — so
/// `count($declaredShape)` can never premise a proof-layer finding (A-G9's
/// corollary), while `count()` of a *proven* array keeps folding to a Singleton
/// on the value rung above, untouched.
fn shape_builtin_return_fact(
    cx: &Cx,
    folder: &mut dyn Folder,
    name: &str,
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    store: Option<&Store>,
    poisoned: bool,
) -> Option<(Fact, Stratum)> {
    if poisoned {
        return None;
    }
    // The argument-DISPATCHED family (ADR-0064 seam ii, DR3) sits at the same
    // seam, one step earlier: its rules read arguments this rung's single-shape
    // pattern cannot even bind (a separator, a literal flag, a subject's base).
    // Declining falls straight through to the shape rung below, unchanged.
    if let Some(out) = arg_dispatch_return_fact(cx, folder, name, args, env, store) {
        return Some(out);
    }
    let [ArgValue::Var(var), rest @ ..] = args else { return None };
    let known = env.get(var)?;
    let subject_stratum = known.stratum;

    // **The value lane's own privilege** (ADR-0062 §2): a subject whose fact is a
    // witnessed `Val::Array` carries true insertion order, so the order-dependent
    // projection may be *executed* rather than widened. Taken before the shape
    // binding below, because a `Singleton` is not a `Fact::Shape` — and refused for
    // every name but the one issue #118 authored it for.
    if let Some(Fact::Singleton(Val::Array(entries))) = &known.fact {
        let out = witnessed_projection_fact(cx, folder, name, entries, args, env, store)?;
        return Some((out, derivation_stratum(cx, folder, args, env, store, subject_stratum)));
    }

    let Some(Fact::Shape { shape, nullable: false }) = &known.fact else { return None };

    let out = if rest.is_empty()
        && (name.eq_ignore_ascii_case("count") || name.eq_ignore_ascii_case("sizeof"))
    {
        let range = shape.count_range();
        if range.lo() == range.hi() {
            // The one place a shape has an exact size: a sealed, all-required
            // shape (ADR-0062 §4, mirroring PHPStan's own exactness).
            Fact::Singleton(Val::Int(range.lo()))
        } else {
            Fact::refined(Base::Int, Refinement::Int(range), false)
        }
    } else if rest.is_empty() && name.eq_ignore_ascii_case("array_is_list") {
        match shape.is_list {
            // The answer IS the denotational flag (§4's row) — no structural
            // inspection, and `Maybe` answers nothing.
            Certainty::Yes => Fact::Singleton(Val::Bool(true)),
            Certainty::No => Fact::Singleton(Val::Bool(false)),
            Certainty::Maybe => return None,
        }
    } else {
        // The positional-projection family (ADR-0062 S7) carries its own
        // admission gate — the reflected *declaration*, since its results are not
        // facts the scalar envelope path can name.
        let fact = shape_projection_fact(cx, folder, name, shape, args, env, store)?;
        return Some((fact, derivation_stratum(cx, folder, args, env, store, subject_stratum)));
    };

    let envelope = builtin_call_return_fact(cx, folder, name)?;
    (envelope.join(&out).as_ref() == Some(&envelope)).then_some((out, subject_stratum))
}

/// **ADR-0061 §3's derivation clause over every argument the call passes**: `min`
/// of the subject's own stratum and each other argument's.
///
/// For the single-argument arms this is the subject's stratum unchanged, so the
/// two forms are observably identical there; the argument-reading arm
/// (`array_slice`, issue #118) is where an offset read out of a docblock-claimed
/// binding can lower it. It is computed **after** a rule has produced a fact and
/// never before, because reaching an argument's fact can dispatch to the engine
/// and most calls arriving here are not in this family at all.
fn derivation_stratum(
    cx: &Cx,
    folder: &mut dyn Folder,
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    store: Option<&Store>,
    subject: Stratum,
) -> Stratum {
    args.iter().fold(subject, |acc, v| {
        acc.min(
            transfer_arg_known(cx, folder, v, env, store)
                .map_or_else(|| value_stratum(v, env, store), |(_, s)| s),
        )
    })
}

/// **The admission gate both symbolic-transfer rungs share** (ADR-0061 §2): the
/// running engine's own reflected *declaration* must be the one the rule was
/// written against, and — where the declaration pins too little on its own —
/// its arity must be too (ADR-0064 Amendment B).
///
/// Three refusals, each of which an existing rung already applied by hand before
/// issue #118 gave them one home:
///
/// 1. **A project function shadowing the simple name** is not the builtin.
/// 2. **A silent engine withholds.** No sidecar, an A9 monkey-patch extension
///    loaded, or a name the engine declares nothing about: the rule is withheld
///    rather than trusted.
/// 3. **A moved signature withholds.** An engine that answers no arity (an older
///    runner, a replay table recorded before the field) withholds exactly as a
///    silent declaration does; an arity that is not the pinned one means this
///    engine's signature has moved and the rule is stale.
fn transfer_declaration_admits(
    cx: &Cx,
    folder: &mut dyn Folder,
    name: &str,
    declared: &[&str],
    arity: Option<(u32, u32)>,
) -> bool {
    if cx.index.has_simple_function(name) {
        return false;
    }
    let Some(reflected) = folder.builtin_return_type(name) else { return false };
    if !declared.iter().any(|d| d.eq_ignore_ascii_case(&reflected)) {
        return false;
    }
    match arity {
        None => true,
        Some(pin) => folder.builtin_param_counts(name) == Some(pin),
    }
}

/// **The positional projections over the order-DECLARED lane** (ADR-0062 §4's
/// `array_values`/`array_keys`/… row, §2's rule, §7's declined import 1).
///
/// A `Fact::Shape` is a key *set*, never a key sequence: field order in the fact
/// is the domain's canonical [`VKey`] order, which has nothing to do with the
/// insertion order of any array the shape admits. So every transfer here is a
/// **sound widening** that reads only order-independent structure — the value
/// union, the key union, the key classes, `non_empty`, and the denotational
/// `is_list`. None of them may produce `list{k1, k2}` in declaration order; that
/// is exactly the upstream defect (phpstan/phpstan#14940) this ADR declines.
///
/// Concrete arrays never come here: they are order-**witnessed**, and the fold
/// seam runs the real builtin on the real array (ADR-0004/0028), which is where
/// an exact, order-correct answer legitimately comes from.
///
/// **The admission gate** is [`Folder::builtin_return_type`]: the running engine
/// must itself declare the return type this transfer assumes (`array` for the
/// four array-valued projections, `string|int|null` for the key-member pair).
/// It carries the same sidecar-presence and A9 monkey-patch legs the ADR-0061 §2
/// envelope gate does, so a redefined builtin, or a run with no PHP, withholds
/// the rule rather than trusting it.
///
/// # The read-position family and its arity second leg (ADR-0064 Amendment B)
///
/// The ten names `current reset end next prev key array_pop array_shift
/// array_first array_last` read *a position* rather than restructuring the array,
/// so their answer is drawn from the shape's **value** union (or, for `key`, its
/// key union) rather than from a new shape. `key` reuses the `array_key_first`
/// arm verbatim — same widening, same real `string|int|null` pin.
///
/// The nine value forms declare a bare **`mixed`**, which pins nothing: every rule
/// output is inside `mixed`, so the declaration check degenerates to a presence
/// test. ADR-0064 Amendment B rules that inadmissible and requires the **arity
/// second leg** — [`Folder::builtin_param_counts`] must report the signature the
/// rule was written against (`(1, 1)` for all ten, measured at `PINNED_PHP`).
/// An engine that cannot answer the arity withholds the rule exactly as an engine
/// silent on the declaration does.
///
/// **The internal pointer is not modeled**, and that boundary is where each arm's
/// `false`/`null` arm comes from (probes at 8.5.8):
///
/// * `next`/`prev` are **unconditionally** `∪ false` — they step off the end of
///   even a non-empty array (`$a = [1]; next($a) === false`).
/// * `current`/`reset`/`end` add `false` only when the shape may be empty
///   (`current([]) === false`); on a non-empty shape they take the union alone,
///   which is upstream PHPStan's position too. It assumes the pointer has not
///   already been advanced past the end — the one place this family reads a
///   runtime state Steins does not carry. It is tolerable exactly here: the fact
///   is shape-derived, so ADR-0062 A-G9's corollary keeps it out of every
///   proof-layer premise, and the fp-gate is the standing instrument.
/// * `array_pop`/`array_shift`/`array_first`/`array_last` never touch the pointer;
///   they add `null` on a possibly-empty shape (`array_pop($e = []) === null`).
///
/// A `∪ false` that the four-layer domain cannot spell — `int|false` is a
/// two-base union with no single [`Fact`] — **declines**, exactly as `json_decode`
/// does in the sibling dispatch rung. A rule that cannot state its own answer says
/// nothing.
///
/// **Mutation is not this function's business, and must not be.** Six of the ten
/// (`array_pop array_shift next prev reset end`) take argument 0 by reference and
/// move or shorten it. The *return* is computed from the pre-call shape, which is
/// correct; the argument's own fact is dropped after the statement by the walk's
/// call-argument invalidation (the `Stmt::invalidated` entries — a by-ref
/// position never passes the gate), and `steins_catalog::out_params` carries
/// all six so the ADR-0063 §2.3 by-ref coloring agrees. No stale shape survives
/// a mutating call.
///
/// # The argument channel (issue #118, ADR-0062 Amendment B)
///
/// The v1 report declined `array_slice` because "the seam is single-argument by
/// construction". That constraint was the decline's whole content, so the
/// implementation removed it rather than weakening the rule: the rung now receives
/// the CALL's argument list, and an arm may read a sibling argument's fact through
/// [`transfer_arg_fact`] — the very reader the DR3 rung next door already owns.
/// Every arm that does not ask keeps the single-shape shape it always had, and the
/// §2 order boundary is untouched: what the arms read is a `$preserve_keys` flag,
/// an offset, and a length — never field declaration order.
fn shape_projection_fact(
    cx: &Cx,
    folder: &mut dyn Folder,
    name: &str,
    shape: &ShapeFact,
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<Fact> {
    /// The `(string)` renderings of `array_key_first`/`array_key_last`/`key`'s
    /// declared return type. PHP 8 renders the union in its own order; both are
    /// accepted so the gate tests the *declaration*, not the engine's spelling of it.
    const KEY_OR_NULL: &[&str] = &["string|int|null", "int|string|null"];
    const ARRAY: &[&str] = &["array"];
    /// The read-position family's declaration: `mixed`, which pins nothing on its
    /// own — every arm using it MUST carry [`ARITY_1`] (ADR-0064 Amendment B, and
    /// the `debug_assert!` at the gate below).
    const MIXED: &[&str] = &["mixed"];
    /// The read-position family's live signature at `PINNED_PHP`: one parameter,
    /// required. Measured, not assumed — see `reflect_reports_the_parameter_counts`.
    const ARITY_1: Option<(u32, u32)> = Some((1, 1));
    /// `array_slice`'s live signature at `PINNED_PHP` (8.5.8): four parameters, two
    /// required — `array_slice(array $array, int $offset, ?int $length = null,
    /// bool $preserve_keys = false)`. Measured, not assumed. Its `array`
    /// declaration is already a real pin, so Amendment B does not *demand* the
    /// second leg here; the arm carries it anyway because it is the one arm that
    /// reads its siblings **positionally**, and a php-src signature that grew a
    /// parameter in front of `$preserve_keys` would make the read stale while the
    /// declaration still said `array`.
    const ARITY_SLICE: Option<(u32, u32)> = Some((4, 2));

    let lower = name.to_ascii_lowercase();
    // ---- The ARGUMENT-READING arm (issue #118), taken first ------------------
    //
    // `array_slice($x, $offset [, $length [, $preserve_keys]])`: the WIDENING FLOOR
    // of the two rungs — see [`slice_widening`] for what it claims and why each
    // part is sound for any offset/length whatever. The exact rung lives in
    // [`witnessed_projection_fact`], on the value lane alone.
    //
    // It is matched *before* the arity binding below because it is the one arm the
    // grown seam gave an argument channel to; everything after this point is
    // single-argument by construction.
    if lower == "array_slice" {
        let out = slice_widening(cx, folder, shape, args, env, store)?;
        return transfer_declaration_admits(cx, folder, name, ARRAY, ARITY_SLICE).then_some(out);
    }
    // The rest of the family reads exactly ONE argument, and a call passing more is
    // a different function than the rule describes: `array_reverse($x, true)`
    // preserves keys, `current($x, 1)` is an `ArgumentCountError`.
    let [_] = args else { return None };
    let (out, declared, arity): (Fact, &[&str], Option<(u32, u32)>) = match lower.as_str() {
        // `array_values($x)`: the values in witnessed order, reindexed. The key
        // structure is gone (a list), the value set is preserved exactly, and an
        // array with an entry still has one after the projection.
        "array_values" => (shape_fact(project_values(shape)), ARRAY, None),
        // `array_keys($x)`: a list whose ELEMENTS are the keys. Enumerable only
        // under a sealed tail, where every present key is a declared key.
        "array_keys" => (shape_fact(project_keys(shape)), ARRAY, None),
        // `array_flip($x)`: keys and values swap. Both bounds widen (see the
        // helper), and `non_empty` is *dropped* — flip silently skips an entry
        // whose value is not `int|string`, so a non-empty input can flip to `[]`.
        "array_flip" => (shape_fact(project_flip(shape)), ARRAY, None),
        // `array_reverse($x)` — the one-argument form only, whose `$preserve_keys`
        // is `false`: string keys survive, integer keys are renumbered.
        "array_reverse" => (shape_fact(project_reverse(shape)), ARRAY, None),
        // `array_key_first`/`array_key_last`: **SOME key of the set**, never the
        // declared-first one — ADR-0062 §2's rule at its sharpest. `null` joins in
        // unless the shape proves the array is non-empty (PHP returns `null` for
        // `[]`).
        //
        // `key($x)` reads the key AT THE INTERNAL POINTER, which is the same
        // widening — some key of the set, or `null` — so it shares this arm
        // verbatim, and shares the real `string|int|null` pin with it (the one
        // member of the read-position family whose declaration says something).
        "array_key_first" | "array_key_last" | "key" => {
            let keys = shape_key_union(shape)?;
            let out = if shape.non_empty { keys } else { fact_admitting_null(&keys)? };
            (out, KEY_OR_NULL, None)
        }
        // ---- The read-position VALUE forms: `mixed` declaration + arity pin ----
        //
        // `array_pop`/`array_shift` take the last/first entry OFF the array and
        // return it; `array_first`/`array_last` (PHP 8.5) read the same entries
        // without mutating. All four ignore the internal pointer, and all four
        // return `null` — not `false` — on an empty array.
        "array_pop" | "array_shift" | "array_first" | "array_last" => {
            (read_position_value(shape, Val::Null)?, MIXED, ARITY_1)
        }
        // `reset`/`end` move the pointer to the first/last entry and return it;
        // `current` returns the entry at wherever the pointer already is. Their
        // empty-array answer is `false` (`current([]) === false`), and on a
        // non-empty shape they take the value union alone — the pointer assumption
        // documented above.
        "current" | "reset" | "end" => {
            (read_position_value(shape, Val::Bool(false))?, MIXED, ARITY_1)
        }
        // `next`/`prev` STEP the pointer, and a step off either end returns `false`
        // — from a non-empty array just as readily as from an empty one
        // (`$a = [1]; next($a) === false`; `$a = [1, 2]; prev($a) === false`). So
        // the `false` arm is unconditional here, and `non_empty` buys nothing.
        "next" | "prev" => {
            let out = if shape.can_be_non_empty() {
                fact_admitting_false(&shape_value_union(shape)?)?
            } else {
                Fact::Singleton(Val::Bool(false))
            };
            (out, MIXED, ARITY_1)
        }
        // Still declined, and now for the only reason left: the value side of
        // `in_array`/`array_search` is a multi-base union (`int|string|false`) the
        // four-layer domain has no single `Fact` for, so the rule cannot state its
        // own answer (ADR-0061 §1). `array_slice`'s v1 decline — "the seam is
        // single-argument by construction" — was answered by growing the seam, not
        // by weakening the rule (ADR-0062 Amendment B).
        _ => return None,
    };
    // ADR-0064 Amendment B, enforced structurally: a `mixed` declaration pin is
    // inadmissible on its own, so every arm declaring it carries an arity pin.
    debug_assert!(
        !declared.iter().any(|d| d.eq_ignore_ascii_case("mixed")) || arity.is_some(),
        "{lower}: a `mixed` declaration pin requires the arity second leg"
    );
    transfer_declaration_admits(cx, folder, name, declared, arity).then_some(out)
}

/// **`array_slice` on the ORDER-WITNESSED lane** (ADR-0062 §2), the exact rung of
/// issue #118's two.
///
/// The subject's fact is a `Singleton(Val::Array)`: a real array whose entries sit
/// in true insertion order, built by observing the construction (a literal, a
/// write, ADR-0001 call-site propagation). Order-dependent results are sound *here
/// and only here*, so this is the one place the projection may be **executed**
/// rather than widened — the same privilege the fold seam exercises when it hands
/// a written literal to the real engine, reached natively because a fold result is
/// scalar-only and this one is an array.
///
/// The window arithmetic is php-src's, probed verbatim at `PINNED_PHP` (8.5.8):
///
/// ```text
/// start = offset < 0 ? max(0, n + offset) : min(offset, n)
/// end   = length is null ? n
///       : length < 0    ? max(start, n + length)
///       :                 min(start + length, n)
/// ```
///
/// with witnesses `array_slice([1,2,3,4,5], 1, -1) === [2,3,4]`,
/// `array_slice([1,2,3,4,5], 1, -10) === []`,
/// `array_slice([1,2,3,4,5], -10) === [1,2,3,4,5]` and
/// `array_slice([1,2,3], -1, -1) === []`.
///
/// Keys follow the same probes: `$preserve_keys = false` (the default) renumbers
/// **integer** keys `0..` in the surviving order and leaves **string** keys alone
/// (`array_slice(['a' => 1, 5 => 2, 'b' => 3, 9 => 4], 1) === [0 => 2, 'b' => 3,
/// 1 => 4]`), while `true` keeps every key as it was.
///
/// **Three declines, and every one of them falls to the widening rather than to
/// silence**: an offset or length that is not a `Singleton` int, a `$preserve_keys`
/// that is not a literal bool, and any other name in the family. The shape the
/// widening then reads is [`ShapeFact::lift`] of the same entries — which is
/// exactly where order-witnessed-ness is honestly lost — so a value-lane subject is
/// never *worse* off than a declared one.
fn witnessed_projection_fact(
    cx: &Cx,
    folder: &mut dyn Folder,
    name: &str,
    entries: &[(VKey, Val)],
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<Fact> {
    /// The one name this lane answers for; see [`shape_projection_fact`]'s own
    /// `array_slice` arm for the widening the others take.
    const ARRAY: &[&str] = &["array"];
    const ARITY_SLICE: Option<(u32, u32)> = Some((4, 2));

    if !name.eq_ignore_ascii_case("array_slice") || !(2..=4).contains(&args.len()) {
        return None;
    }
    if !transfer_declaration_admits(cx, folder, name, ARRAY, ARITY_SLICE) {
        return None;
    }
    match slice_window(cx, folder, args, env, store) {
        Some((offset, length, preserve)) => {
            Some(Fact::Singleton(Val::Array(slice_entries(entries, offset, length, preserve))))
        }
        // The widening reads the LIFT of the same entries — which is exactly where
        // order-witnessed-ness is honestly lost — so a value-lane subject is never
        // worse off than a declared one.
        None => slice_widening(cx, folder, &ShapeFact::lift(entries), args, env, store),
    }
}

/// The exact rung's three premises, read together: a `Singleton` offset, a
/// `Singleton`-or-absent length, and a literal `$preserve_keys`. `None` — the
/// caller takes the widening — as soon as one of them is not proven.
fn slice_window(
    cx: &Cx,
    folder: &mut dyn Folder,
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<(i64, Option<i64>, bool)> {
    let Some(Fact::Singleton(Val::Int(offset))) = transfer_arg_fact(cx, folder, &args[1], env, store)
    else {
        return None;
    };
    let length = match args.get(2) {
        None => None,
        Some(a) => match transfer_arg_fact(cx, folder, a, env, store)? {
            // `$length = null` is the documented "to the end" spelling, and the
            // parameter's own default.
            Fact::Singleton(Val::Null) => None,
            Fact::Singleton(Val::Int(l)) => Some(l),
            _ => return None,
        },
    };
    let preserve = match slice_preserve_keys(cx, folder, args, env, store) {
        PreserveKeys::No => false,
        PreserveKeys::Yes => true,
        PreserveKeys::Unknown => return None,
    };
    Some((offset, length, preserve))
}

/// The witnessed window of `entries`, keyed as PHP keys it (see
/// [`witnessed_projection_fact`] for the probes both halves are written from).
fn slice_entries(
    entries: &[(VKey, Val)],
    offset: i64,
    length: Option<i64>,
    preserve: bool,
) -> Vec<(VKey, Val)> {
    let n = i64::try_from(entries.len()).unwrap_or(i64::MAX);
    let start = if offset < 0 { (n.saturating_add(offset)).max(0) } else { offset.min(n) };
    let end = match length {
        None => n,
        Some(l) if l < 0 => n.saturating_add(l).max(start),
        Some(l) => start.saturating_add(l).min(n),
    };
    // `0 <= start <= end <= n` holds by the three arms above, so both casts are
    // in range; the fallback keeps the function total rather than trusting that.
    let (lo, hi) = (usize::try_from(start).unwrap_or(0), usize::try_from(end).unwrap_or(0));
    let mut next = 0i64;
    entries[lo.min(entries.len())..hi.min(entries.len())]
        .iter()
        .map(|(k, v)| match k {
            VKey::Str(_) => (k.clone(), v.clone()),
            VKey::Int(_) if preserve => (k.clone(), v.clone()),
            VKey::Int(_) => {
                let key = VKey::Int(next);
                next += 1;
                (key, v.clone())
            }
        })
        .collect()
}

/// What the call says about `array_slice`'s fourth argument.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PreserveKeys {
    /// Absent, or a literal `false` — the reindexing default.
    No,
    /// A literal `true`.
    Yes,
    /// Present but not a literal bool. Every rule here takes the join of the two
    /// branches, which is the honest widening.
    Unknown,
}

/// Read `$preserve_keys` off the call. A non-literal (including a truthy `int`
/// that weak mode would coerce) is [`PreserveKeys::Unknown`], never guessed.
fn slice_preserve_keys(
    cx: &Cx,
    folder: &mut dyn Folder,
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> PreserveKeys {
    let Some(arg) = args.get(3) else { return PreserveKeys::No };
    match transfer_arg_fact(cx, folder, arg, env, store) {
        Some(Fact::Singleton(Val::Bool(false))) => PreserveKeys::No,
        Some(Fact::Singleton(Val::Bool(true))) => PreserveKeys::Yes,
        _ => PreserveKeys::Unknown,
    }
}

/// **`array_slice` on the ORDER-DECLARED lane** — the widening floor, sound for
/// *any* offset and length (issue #118, ADR-0062 Amendment B).
///
/// The v1 decline's stated cost was that "the shape-only answer carries no more
/// than the reflected `array` envelope already does". That is false, and the
/// element union is the counterexample: `array_slice(list<Foo>, $n)` is a
/// `list<Foo>`, and the envelope says `array`. Six claims, each read from
/// order-INDEPENDENT structure only (§2 — no field declaration order is consulted,
/// and the arguments the arm reads are a flag, an offset, and a length):
///
/// * **Element bound** — the slice's values are a subset of the subject's, so
///   [`shape_value_union`] carries across unchanged.
/// * **Key class** — a slice never *invents* a key class. `$preserve_keys = true`
///   keeps each surviving key as it was; `false` renumbers integer keys and leaves
///   string keys alone (probe: `array_slice(['a' => 1, 5 => 2], 0) ===
///   ['a' => 1, 0 => 2]`). Either way an all-int subject yields all-int keys and an
///   all-string subject all-string ones, so the class is the subject's own.
/// * **List-ness survives under an absent-or-false flag.** An all-integer-keyed
///   subject sliced with `$preserve_keys` absent-or-false is renumbered `0..n-1`,
///   which *is* a list. Under a truthy — or merely *unknown* — flag it degrades to
///   `Maybe` (`array_slice([1,2,3], 1, null, true) === [1 => 2, 2 => 3]`), and so
///   does any subject that can carry a string key. Never `No`: the empty array a
///   slice can always return is itself a list.
/// * **List-ness survives `preserve_keys = true` from offset 0** (issue #137's
///   first claim). When the subject's shape PROVES `is_list` and the offset is a
///   proven int `0`, a literal `true` keeps the surviving keys `0..k-1` unchanged
///   — still a list, for any length sign (probes:
///   `array_slice([1,2,3], 0, null, true) === [1,2,3]`,
///   `array_slice([1,2,3], 0, -1, true) === [0 => 1, 1 => 2]`,
///   `array_slice([1,2,3], 0, 0, true) === []`). The subject's proven list-ness
///   is load-bearing — all-int keys alone are NOT enough:
///   `array_slice([5 => 2], 0, null, true) === [5 => 2]`, not a list. An unknown
///   offset, like a non-list subject, stays `Maybe` exactly as before.
/// * **A proven zero length is `array{}`** (issue #137's second claim). When the
///   `$length` argument is a proven int `0`, the window is empty for ANY subject,
///   offset, and flag — `array_slice(['a' => 1], 0, 0) === []`,
///   `array_slice([1,2,3], -2, 0, true) === []` — so the answer is the SEALED
///   empty shape rather than this floor's unsealed tail. Literal int `0` only:
///   `null` is the documented "to the end" spelling and must not match, and
///   anything short of a proven `Singleton` int declines to the floor. Taken
///   before every other claim — `array{}` is the sharper fact and is itself a
///   list, so it subsumes the preserved-prefix claim when both apply.
/// * **`non_empty` NEVER survives.** Every possibly-empty result is reachable from
///   a non-empty subject — `array_slice([1,2,3], 10) === []`,
///   `array_slice([1,2,3], 1, 0) === []` — so the flag is dropped unconditionally.
///
/// **The size bound is deliberately not claimed.** The result's entry count is
/// bounded above by the subject's, and expressing that would need a sealed result
/// shape with keys the projection cannot name; the tail is unsealed instead, which
/// is the sound direction. The issue left this optional and the widening is worth
/// more than the arithmetic.
fn slice_widening(
    cx: &Cx,
    folder: &mut dyn Folder,
    shape: &ShapeFact,
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<Fact> {
    use steins_domain::{KeyClass, Tail};
    // Two required, four total (`ARITY_SLICE`) — a call PHP itself rejects with an
    // `ArgumentCountError` has no return value for the rule to describe.
    if !(2..=4).contains(&args.len()) {
        return None;
    }
    // The zero-length claim first: a proven `$length = 0` empties the window for
    // any subject, offset, and flag, and the sealed empty shape it answers is
    // sharper than anything the unsealed floor below could say.
    if slice_arg_is_int_zero(cx, folder, args.get(2), env, store) {
        return Some(shape_fact(ShapeFact::normalize(
            Vec::new(),
            Tail::Sealed,
            Certainty::Yes,
            false,
            Vec::new(),
        )));
    }
    let preserve = slice_preserve_keys(cx, folder, args, env, store);
    let (all_int, all_str) = shape_key_classes(shape);
    let key = if all_int {
        KeyClass::Int
    } else if all_str {
        KeyClass::Str
    } else {
        KeyClass::ArrayKey
    };
    // The two combinations list-ness survives: renumbering (absent-or-false flag
    // over all-int keys) and the preserved prefix (a PROVEN list kept from a
    // proven offset 0 under a literal `true`).
    let renumbered = all_int && preserve == PreserveKeys::No;
    let preserved_prefix = shape.is_list == Certainty::Yes
        && preserve == PreserveKeys::Yes
        && slice_arg_is_int_zero(cx, folder, args.get(1), env, store);
    let is_list =
        if renumbered || preserved_prefix { Certainty::Yes } else { Certainty::Maybe };
    Some(shape_fact(ShapeFact::normalize(
        Vec::new(),
        Tail::Unsealed { key, value: shape_value_union(shape).map(Box::new) },
        is_list,
        false,
        Vec::new(),
    )))
}

/// Is this argument a proven int `0`? The two literal reads issue #137's precision
/// claims added share the answer — the offset for the preserved-prefix claim, the
/// length for the zero-length claim — and both take [`transfer_arg_fact`], the same
/// resolution [`slice_window`] and [`slice_preserve_keys`] use. An absent argument
/// is `false`, and so is `Singleton(Val::Null)` (`$length = null` means "to the
/// end"): nothing short of a proven `Singleton` int `0` matches.
fn slice_arg_is_int_zero(
    cx: &Cx,
    folder: &mut dyn Folder,
    arg: Option<&ArgValue>,
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> bool {
    arg.is_some_and(|a| {
        matches!(transfer_arg_fact(cx, folder, a, env, store), Some(Fact::Singleton(Val::Int(0))))
    })
}

/// `(every key is an int, every key is a string)` over the shape's declared,
/// non-`Absent` keys **and** its tail class. A `Sealed` tail contributes nothing
/// (it admits no undeclared key), so a sealed shape answers from its fields alone
/// and `array{}` answers `(true, true)` vacuously — which is right: the only array
/// it admits is `[]`.
fn shape_key_classes(shape: &ShapeFact) -> (bool, bool) {
    use steins_domain::{KeyClass, Presence, Tail};
    let declared = |want: fn(&VKey) -> bool| {
        shape.fields.iter().all(|(k, p, _)| matches!(p, Presence::Absent) || want(k))
    };
    let tail = |want: KeyClass| match &shape.tail {
        Tail::Sealed => true,
        Tail::Unsealed { key, .. } => *key == want,
    };
    (
        declared(|k| matches!(k, VKey::Int(_))) && tail(KeyClass::Int),
        declared(|k| matches!(k, VKey::Str(_))) && tail(KeyClass::Str),
    )
}

/// One entry of an admitted array, read by position: the shape's value union, plus
/// `empty` when the shape does not prove the array is non-empty.
///
/// `empty` is the builtin's own empty-array answer — [`Val::Null`] for the
/// `array_pop`/`array_first` half of the family, `false` for the pointer half. A
/// union the addition makes unspellable (`int|false` is two bases) declines.
///
/// A shape that admits **only** `[]` (a sealed tail with no present field) answers
/// with the empty-array value exactly: `current(array{})` is `false`, and
/// `array_first(array{})` is `null`. That case has to be taken before the value
/// union, which is `None` there for the uninformative reason — an empty join, not
/// an unrepresentable one.
fn read_position_value(shape: &ShapeFact, empty: Val) -> Option<Fact> {
    if !shape.can_be_non_empty() {
        return Some(Fact::Singleton(empty));
    }
    let values = shape_value_union(shape)?;
    if shape.non_empty {
        return Some(values);
    }
    match empty {
        Val::Null => fact_admitting_null(&values),
        other => values.join(&Fact::Singleton(other)),
    }
}

/// Add `false` to a fact's denotation. Unlike `null` there is no side-flag for it,
/// so this is the plain domain join: finite layers absorb it as another member, and
/// an abstract non-`bool` base yields `None` — `int|false` is a two-base union the
/// four-layer domain does not name, and a rule that cannot state its answer
/// declines (ADR-0061 §1).
fn fact_admitting_false(f: &Fact) -> Option<Fact> {
    f.join(&Fact::Singleton(Val::Bool(false)))
}

/// **The argument-dispatched transfers** (ADR-0064 seam ii, the DR3 batch).
///
/// [`shape_builtin_return_fact`]'s own rung reads exactly one argument, and that
/// argument has to be an array — `count($x)`, `array_values($x)`. The transfers
/// here need strictly more: which argument decides the answer varies by function
/// (`explode`'s separator, `var_export`'s flag, `preg_replace`'s subject), and
/// the deciding fact is a scalar, not a shape. So the seam gains ONE thing — a
/// per-argument fact reader ([`transfer_arg_fact`]) — and every rule stays a
/// plain `&[ArgValue] -> Option<Fact>` function behind the same gate.
///
/// **The admission gate is [`shape_projection_fact`]'s, verbatim**: the running
/// engine's own reflected *declaration* must be the one the rule was written
/// against. These results are array/nullable-union facts the scalar envelope path
/// (`envelope_fact`) cannot represent at all, so there is no envelope to be
/// extensionally inside — the declaration is what countersigns them, and it
/// carries the same sidecar-presence and A9 monkey-patch legs. A run with no PHP,
/// a monkey-patch extension, a project function shadowing the name, or an engine
/// whose declaration has moved withholds the rule rather than trusting it.
///
/// **Stratum is ADR-0061 §3's derivation clause**: `min` over every argument the
/// call passes, exactly as [`value_stratum`]'s own `Call` arm computes it — a
/// transfer premised on a docblock-claimed separator is `Asserted` and can never
/// premise a proof-layer finding.
///
/// Every rule below is **independently implemented** (ADR-0061 §4): authored from
/// `php -r` probes against `PINNED_PHP` and php.net's documented semantics, not
/// from phpstan-src text — hence no port header on this module.
fn arg_dispatch_return_fact(
    cx: &Cx,
    folder: &mut dyn Folder,
    name: &str,
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<(Fact, Stratum)> {
    /// `explode`/`range`: `array` (PHP 8.5.8 `ReflectionFunction::getReturnType`).
    const ARRAY: &[&str] = &["array"];
    /// `var_export`: `?string` — the flag is what strips the null arm.
    const NULLABLE_STRING: &[&str] = &["?string", "string|null"];
    /// `preg_replace`: the three-member union, either rendering order.
    const PREG_REPLACE: &[&str] = &["array|string|null", "string|array|null"];
    /// `min`/`max`: a bare **`mixed`**, which pins nothing on its own — the arm
    /// declaring it MUST carry [`ARITY_MIN_MAX`] (ADR-0064 Amendment B, and the
    /// `debug_assert!` at the gate below).
    const MIXED: &[&str] = &["mixed"];
    /// `min`/`max`'s live signature at `PINNED_PHP` (8.5.8): variadic, `(total,
    /// required) = (2, 1)` — `min(mixed $value, mixed ...$values)`. Measured, not
    /// assumed; a variadic reports the *declared* parameters, not a call's.
    const ARITY_MIN_MAX: Option<(u32, u32)> = Some((2, 1));

    let lower = name.to_ascii_lowercase();
    let (out, declared, arity): (Fact, &[&str], Option<(u32, u32)>) = match lower.as_str() {
        "explode" => (explode_transfer(cx, folder, args, env, store)?, ARRAY, None),
        "range" => (range_transfer(cx, folder, args, env, store)?, ARRAY, None),
        "preg_replace" => {
            (preg_replace_transfer(cx, folder, args, env, store)?, PREG_REPLACE, None)
        }
        "var_export" => {
            (var_export_transfer(cx, folder, args, env, store)?, NULLABLE_STRING, None)
        }
        "min" | "max" => {
            (min_max_transfer(cx, folder, &lower, args, env, store)?, MIXED, ARITY_MIN_MAX)
        }
        // `json_decode` is the batch's recorded DECLINE, not an omission: its
        // reflected declaration is bare `mixed`, and the soundest envelope any
        // flag combination admits — `$assoc = true` still allows
        // `array|int|float|string|bool|null` — is a six-base union the four-layer
        // domain has no single `Fact` for (`envelope_fact`'s multi-base `None`).
        // A rule that cannot state its own answer declines (ADR-0061 §1).
        //
        // The string-predicate transfer family (issue #77) is keyed inside its own
        // table rather than spelled out here — ~25 names sharing one `string` pin
        // (`strlen`: `int`), so a per-name arm would be a transcription of that
        // table with nothing added.
        other => {
            let (fact, declared) = str_pred_transfer(cx, folder, other, args, env, store)?;
            (fact, declared, None)
        }
    };
    // ADR-0064 Amendment B, enforced structurally at this rung too. Until issue #118
    // this assertion was a flat *refusal* — the rung had no arity leg to offer, so a
    // `mixed` pin could only be a hole, and `json_decode`'s is the recorded decline
    // above. `min`/`max` declare a bare `mixed` and are otherwise the batch's most
    // load-bearing rule, so the rung grew the same second leg the S7 rung next door
    // already carried, and the assertion became the same OBLIGATION: name `mixed`
    // and you must pin the signature the rule was written against.
    debug_assert!(
        !declared.iter().any(|d| d.eq_ignore_ascii_case("mixed")) || arity.is_some(),
        "{lower}: a `mixed` declaration pin requires the arity second leg"
    );
    if !transfer_declaration_admits(cx, folder, name, declared, arity) {
        return None;
    }
    // ADR-0061 §3's derivation clause, over the facts the rules actually read: an
    // argument answered from the declared arm lane contributes that lane's own
    // (`Asserted`) stratum, and everything else contributes what it always did.
    let stratum = args.iter().fold(Stratum::Verified, |acc, v| {
        acc.min(
            transfer_arg_known(cx, folder, v, env, store)
                .map_or_else(|| value_stratum(v, env, store), |(_, s)| s),
        )
    });
    Some((out, stratum))
}

/// The fact one call argument carries: a bound variable's env fact, else the
/// literal (or fold-resolved) value's own Singleton. The seam's whole extension
/// beyond the single-shape-argument pattern.
fn transfer_arg_fact(
    cx: &Cx,
    folder: &mut dyn Folder,
    value: &ArgValue,
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<Fact> {
    transfer_arg_known(cx, folder, value, env, store).map(|(fact, _)| fact)
}

/// The same fact **with the stratum it enters at** — the two are computed together
/// because the second leg below can change both at once.
///
/// The env fact is the first answer, as it always was. Where it is only the
/// *envelope* (`Fact::General`, which is what a native `string $s` parameter seeds
/// and says nothing this rung can transfer), the **declared contract arm lane** is
/// consulted instead: `@param non-empty-string $s` on a natively-typed `string`
/// parameter lives there and nowhere else, because ADR-0052 §9's entry-state
/// seeding puts only *array* arms into the value lane (ADR-0062 A-G9's corollary),
/// leaving every scalar refinement in the arm lane for the contract surface.
///
/// Reading it here is the narrowest possible widening of that seam: nothing about
/// entry state moves, the variable's own dump is unchanged, and only a rule that
/// asked for this argument sees it. The arm's own stratum comes with it, so a
/// refinement the docblock merely *claims* enters `Asserted` and can never premise
/// a proof-layer finding (ADR-0061 §3's derivation clause). An arm lane that
/// lowers to no better than the envelope contributes nothing, so a plain native
/// `string $s` keeps the `Verified` stratum it already had.
fn transfer_arg_known(
    cx: &Cx,
    folder: &mut dyn Folder,
    value: &ArgValue,
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<(Fact, Stratum)> {
    if let ArgValue::Var(v) = value {
        let known = env.get(v);
        let env_fact = known.and_then(|k| k.fact.clone());
        let env_stratum = known.map_or(Stratum::Verified, |k| k.stratum);
        if let Some(fact) = env_fact.clone()
            && !matches!(fact, Fact::General { .. })
        {
            return Some((fact, env_stratum));
        }
        if let Some(arms) = store.and_then(|s| s.contract_arms(v))
            && let Some((fact, stratum)) = declared_arm_known(arms)
            && !matches!(fact, Fact::General { .. })
        {
            return Some((fact, stratum));
        }
        return env_fact.map(|f| (f, env_stratum));
    }
    let lit = cx.resolve_literal(value, env, false, folder)?;
    Some((singleton_fact(&lit, cx.php_minor)?, value_stratum(value, env, store)))
}

/// The declared contract lane as ONE fact, with the weakest stratum any arm of it
/// carries. Every arm must lower ([`steins_contract::to_fact`]) and the domain must
/// be able to join them — `'foo'|'bar'` becomes a `OneOf`, `int|string` declines,
/// which is the same honest floor the value-slot lowering takes everywhere else.
fn declared_arm_known(arms: &[ContractArm]) -> Option<(Fact, Stratum)> {
    let mut acc: Option<Fact> = None;
    let mut stratum = Stratum::Verified;
    for arm in arms {
        let f = steins_contract::to_fact(&arm.ty)?;
        stratum = stratum.min(arm.stratum);
        acc = Some(match acc {
            None => f,
            Some(prev) => prev.join(&f)?,
        });
    }
    Some((acc?, stratum))
}

/// `explode($separator, $string)` → **`non-empty-list<string>`**.
///
/// PHP 8 removed `explode`'s `false` arm (the empty separator became a
/// `ValueError`), and the split of *any* string on a non-empty separator has at
/// least one piece — `explode(',', '')` is `['']`, not `[]`. Witnesses at
/// `PINNED_PHP` (8.5.8): `explode(',', '')` → `array(1){ [0]=> "" }`;
/// `explode('', 'abc')` → `ValueError: explode(): Argument #1 ($separator) must
/// not be empty`.
///
/// **Two declines, both load-bearing.** An empty (or not-known-non-empty)
/// separator declines — the `ValueError` form has no return value to describe,
/// and an unknown separator might be it. And the three-argument form declines
/// **because `$limit` breaks non-emptiness outright**: the probe
/// `explode(',', 'a,b,c', -5)` returns `array(0){}` at 8.5.8, so a rule that kept
/// `non-empty` across a limit argument would be a false premise, not a lost
/// refinement.
fn explode_transfer(
    cx: &Cx,
    folder: &mut dyn Folder,
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<Fact> {
    // Exactly two arguments — see the `$limit` witness above.
    let [sep, _string] = args else { return None };
    let sep = transfer_arg_fact(cx, folder, sep, env, store)?;
    // The `$string` argument is deliberately unread: it is declared `string`, so
    // anything reaching the body is one (or was coerced to one), and every string
    // splits to at least one string piece.
    fact_is_non_empty_string(&sep)
        .then(|| list_transfer_fact(true, Some(Fact::General { base: Base::String, nullable: false })))
}

/// `range($start, $end [, $step])` → **`non-empty-list<int>`** for integral
/// bounds and step, **`non-empty-list<mixed>`** otherwise.
///
/// The unconditional half is the stronger claim and the one worth having: PHP's
/// `range` always returns a *packed* array — keys `0..n-1`, so a list — with at
/// least one entry, because equal bounds still produce one (`range(1, 1)` →
/// `[1]`, witnessed at 8.5.8). No argument shape changes that: `range(3, 1)` is
/// the three-element descending list, and `range('a', 'c')` is
/// `['a', 'b', 'c']` — a non-empty list of strings. Every input PHP 8.3+ refuses
/// (`$step` of `0`, a `$step` larger than the span, a negative `$step` on an
/// increasing range — all three witnessed as `ValueError` at 8.5.8) produces no
/// value at all, so non-emptiness survives them vacuously.
///
/// The element bound is where the arguments dispatch, and it is **narrower than
/// "any float involved"** on purpose: PHP 8.3's saner-`range` semantics make
/// `range(1, 3, 1.0)` an *int* array (witnessed), so a float step does not imply
/// a float result, while `range(1, 2, 0.5)` and `range(1.0, 3.0)` are float
/// arrays. Rather than encode that fractional-part rule, the transfer claims
/// `int` only when every bound and the step are known integral and leaves the
/// element unknown otherwise — the list-ness and the non-emptiness still land.
///
/// The integrality test is [`fact_is_int`], which also passes a *nullable* int.
/// That is sound for the same vacuous reason the `ValueError` inputs are:
/// `range(null, 3)` is a `TypeError` at 8.3+, so the `null` member of such a fact
/// contributes no returned value for the claim to be wrong about.
fn range_transfer(
    cx: &Cx,
    folder: &mut dyn Folder,
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<Fact> {
    // `range` accepts two or three arguments; any other arity is an
    // `ArgumentCountError`, and the seam refuses to describe a call PHP rejects.
    if !(2..=3).contains(&args.len()) {
        return None;
    }
    let mut integral = true;
    for a in args {
        // No short-circuit: every argument's fact is read, so the decision is a
        // function of the whole call rather than of evaluation order.
        integral &= transfer_arg_fact(cx, folder, a, env, store).as_ref().is_some_and(fact_is_int);
    }
    Some(list_transfer_fact(
        true,
        integral.then_some(Fact::General { base: Base::Int, nullable: false }),
    ))
}

/// `preg_replace($pattern, $replacement, $subject, …)` → **`string|null`** for a
/// string subject, **`array|null`** for an array one.
///
/// The reflected declaration is the three-member `array|string|null`, which
/// `envelope_fact` cannot represent (multi-base) — so today the call carries *no*
/// fact at all, and the subject's own base is exactly what splits it. `$subject`
/// alone governs: `preg_replace(['/a/', '/b/'], 'z', 'ab')` is `'zz'`, a string,
/// despite the array `$pattern` (witnessed at 8.5.8).
///
/// The `null` arm is **kept on both sides**, deliberately. A string subject
/// genuinely returns `null` on a PCRE error (`@preg_replace('/a', 'b', 'aaa')` →
/// `NULL`, witnessed). The array-subject probes returned `array(0){}` rather than
/// `null` on the same errors — but "no probe produced null" is not a proof that
/// none can, and ADR-0061 §2's ledger only balances one way: a kept-but-impossible
/// `null` costs one arm of precision, a dropped-but-possible one is a false
/// premise. `$limit`/`&$count` may follow without changing the answer.
fn preg_replace_transfer(
    cx: &Cx,
    folder: &mut dyn Folder,
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<Fact> {
    if !(3..=5).contains(&args.len()) {
        return None;
    }
    let string_or_null = || Fact::General { base: Base::String, nullable: true };
    let array_or_null =
        || Fact::Shape { shape: Box::new(ShapeFact::plain_array()), nullable: true };
    match transfer_arg_fact(cx, folder, &args[2], env, store)? {
        Fact::Singleton(Val::Str(_)) => Some(string_or_null()),
        Fact::Singleton(Val::Array(_)) => Some(array_or_null()),
        Fact::OneOf(ref vals) if vals.iter().all(|v| matches!(v, Val::Str(_))) => {
            Some(string_or_null())
        }
        Fact::OneOf(ref vals) if vals.iter().all(|v| matches!(v, Val::Array(_))) => {
            Some(array_or_null())
        }
        // A nullable subject declines: `null` is a deprecation-plus-coercion in
        // weak mode and a `TypeError` in strict mode, and neither is a case this
        // rule was probed against.
        Fact::Refined { base: Base::String, nullable: false, .. }
        | Fact::General { base: Base::String, nullable: false } => Some(string_or_null()),
        Fact::Shape { nullable: false, .. } => Some(array_or_null()),
        _ => None,
    }
}

/// `min(…)` / `max(…)` → **the union of what the arguments already say** (issue
/// #118, ADR-0061's rung).
///
/// # The load-bearing PHP fact
///
/// **`min`/`max` RETURN ONE OF THEIR ARGUMENTS**, whatever PHP's comparison
/// semantics did on the way — not a coerced copy of one, and never a value that
/// was not passed in. Witnessed at `PINNED_PHP` (8.5.8): `min('a', 1)` is
/// `int(1)`, the second argument verbatim, and `min([3, '1', 2])` is
/// `string(1) "1"`, an element verbatim. So the union of the argument facts admits
/// the result **unconditionally** — the rule needs no premise about comparability,
/// ordering, or type juggling, which is exactly what makes it worth having where a
/// per-type case analysis would not be.
///
/// # The ladder
///
/// 1. **Two or more arguments, all int-ranged** → the *composed interval*, which is
///    strictly sharper than the union: for `a ∈ [l₁, h₁]`, `b ∈ [l₂, h₂]`,
///    `min(a, b) ∈ [min(l₁, l₂), min(h₁, h₂)]` (`min(a, b) ≤ a ≤ h₁` and
///    `≤ b ≤ h₂`, and both endpoints are attained), and `max` dually. This is
///    interval arithmetic over declared knowledge — the `count()`/`strlen`
///    precedent — never a re-derivation of what PHP compared. A composition that
///    collapses to a point spells the point (`min(1, 2)` is `1`), which is what
///    keeps the rule from being *worse* than a fold on constant arguments; `min`
///    and `max` are not on the folding allowlist, so nothing else answers them.
/// 2. **Two or more arguments otherwise** → the plain domain join of the facts.
/// 3. **One argument** → the unary ARRAY form: the shape's own value union
///    ([`shape_value_union`]), because the result is one of the array's *elements*.
///    A witnessed array lifts first, so `min([1, 2, 3])` is `1|2|3`.
///
/// # The declines, each for a stated reason
///
/// * **Any argument without a usable fact declines the whole rule.** A union over
///   the arguments that *did* answer is not sound — the missing one could hold the
///   winner — so there is no partial answer to give.
/// * **A join the four-layer domain cannot spell declines** — `min($int, $string)`
///   is an `int|string`, a two-base union with no single [`Fact`], exactly as
///   `json_decode`'s six-base envelope is. See the deviation note in ADR-0062
///   Amendment B: the design called for these to enter the *arm* lane, which has no
///   argument-dependent channel at this seam, so the honest floor stands instead.
/// * **A nullable int leaves the interval path** and takes the union: `min(null, 5)`
///   is `NULL` at 8.5.8, so an `?int` argument must not yield a bare `int` claim.
///   The union carries the null side correctly (`int|null` is one fact).
/// * **A one-argument call whose fact is not an array declines** — `min(5)` is a
///   `TypeError`, and a rule describes a call that returns.
/// * **A zero-argument call declines** — `min()` is an `ArgumentCountError`.
///
/// `min([])` throwing a `ValueError` costs the rule nothing and buys it no
/// `non_empty` premise: a throw is the *absence* of a return, so there is no value
/// for the claim to be wrong about (the same vacuity [`range_transfer`] leans on).
fn min_max_transfer(
    cx: &Cx,
    folder: &mut dyn Folder,
    lower: &str,
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<Fact> {
    let [first, rest @ ..] = args else { return None };
    if rest.is_empty() {
        // The unary array form. A `Singleton(Val::Array)` lifts (A-G5) rather than
        // being read positionally: which element wins is a comparison question, and
        // the union is the claim this rule makes on either lane.
        return match transfer_arg_fact(cx, folder, first, env, store)? {
            Fact::Shape { shape, nullable: false } => shape_value_union(&shape),
            Fact::Singleton(Val::Array(entries)) => shape_value_union(&ShapeFact::lift(&entries)),
            _ => None,
        };
    }
    let mut facts = Vec::with_capacity(args.len());
    for a in args {
        // No short-circuit and no skipping: an argument with no fact declines the
        // whole rule, so the answer is a function of the entire call.
        facts.push(transfer_arg_fact(cx, folder, a, env, store)?);
    }
    min_max_interval(lower == "min", &facts).or_else(|| {
        facts.iter().skip(1).try_fold(facts[0].clone(), |acc, f| acc.join(f))
    })
}

/// The composed interval of a `min`/`max` call whose every argument is a
/// non-nullable int — see [`min_max_transfer`] for the arithmetic and why it is
/// tight. `None` as soon as one argument is anything else, which routes the call
/// to the union.
fn min_max_interval(is_min: bool, facts: &[Fact]) -> Option<Fact> {
    let mut acc: Option<IntRange> = None;
    for f in facts {
        let r = fact_int_range(f)?;
        acc = Some(match acc {
            None => r,
            Some(a) => {
                let (lo, hi) = if is_min {
                    (a.lo().min(r.lo()), a.hi().min(r.hi()))
                } else {
                    (a.lo().max(r.lo()), a.hi().max(r.hi()))
                };
                // `lo <= hi` holds for both arms (a pointwise min/max of two
                // ordered pairs stays ordered); the fallback keeps this total.
                IntRange::new(lo, hi)?
            }
        });
    }
    let r = acc?;
    Some(if r.lo() == r.hi() {
        Fact::Singleton(Val::Int(r.lo()))
    } else {
        Fact::refined(Base::Int, Refinement::Int(r), false)
    })
}

/// The interval a fact pins on a **non-nullable int**, or `None` for anything else.
/// A `OneOf` is deliberately excluded: its finite member set is what the union path
/// carries exactly, and hulling it here would trade a gap-free answer for an
/// interval.
fn fact_int_range(f: &Fact) -> Option<IntRange> {
    match f {
        Fact::Singleton(Val::Int(i)) => Some(IntRange::point(*i)),
        Fact::Refined { base: Base::Int, refinement: Refinement::Int(r), nullable: false } => {
            Some(*r)
        }
        Fact::General { base: Base::Int, nullable: false } => Some(IntRange::FULL),
        _ => None,
    }
}

/// `var_export($value, true)` → **`string`**.
///
/// The reflected declaration is `?string`, and the `null` half is precisely the
/// `$return = false` behavior: the export is *printed* and nothing is returned.
/// A literal `true` flag is therefore the whole transfer — it strips the null
/// arm, and nothing else about `$value` matters (`var_export(null, true)` is the
/// four-character string `'NULL'`, not `null`; witnessed at 8.5.8).
///
/// The one-argument and literal-`false` forms decline: the reflected `?string`
/// envelope already describes them exactly, and a rule that restated its own
/// envelope would add a stratum-carrying fact where a `Verified` one already
/// stands (ADR-0061 §3's replace-if-weaker corollary).
fn var_export_transfer(
    cx: &Cx,
    folder: &mut dyn Folder,
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<Fact> {
    let [_value, flag] = args else { return None };
    let flag = transfer_arg_fact(cx, folder, flag, env, store)?;
    (flag == Fact::Singleton(Val::Bool(true)))
        .then_some(Fact::General { base: Base::String, nullable: false })
}

/// **The string-predicate transfers** (issue #77) — the residual half of the names
/// whose constant half the fold lane already owns.
///
/// A string builtin called on a *known constant* folds to a Singleton one rung up
/// (ADR-0028). Called on a string the walk only knows *predicates* about —
/// `non-empty-string`, `lowercase-string`, a `'foo'|'bar'` union — nothing computed
/// before this table. It answers one question per name: **which
/// [`StrPreds`](steins_domain::StrPreds) bits survive the call, and which does the
/// call establish on its own?**
///
/// The shape is uniform, so the whole family is one rule rather than twenty-five:
///
/// ```text
/// out = (preds(arg0) ∩ KEEP(name, args)) ∪ FORCE(name, args)
/// ```
///
/// with `out == ∅` meaning **decline** — an empty summary is exactly the reflected
/// `string` envelope, and restating an envelope would put a stratum-carrying fact
/// where a `Verified` one already stands (ADR-0061 §3's replace-if-weaker
/// corollary, the same reason [`var_export_transfer`] declines its one-argument
/// form). `strlen` is the one member whose output is not a string: a non-empty
/// subject makes it `int<1, max>`, one notch inside the curated `int<0, max>` row.
///
/// # What the two casing bits MEAN here, and why the forced leg is total
///
/// `LOWERCASE` is `strtolower($s) === $s`, which
/// [`php_str_is_lowercase`](steins_domain::php_str_is_lowercase) implements as **no
/// ASCII uppercase byte** — PHP 8.2+ made the two case functions locale-insensitive
/// and byte-wise, so nothing outside `A-Z`/`a-z` participates. Two consequences the
/// table leans on, both probed at `PINNED_PHP` (8.5.8):
///
/// * `strtolower('ÄB') === 'Äb'` — the non-ASCII byte is untouched, and the result
///   still has no ASCII uppercase byte. So `strtolower` **forces** `LOWERCASE` for
///   *any* input, including one carrying no fact at all, and `strtoupper` mirrors it
///   (`strtoupper('äb') === 'äB'`). This is the one leg that fires without reading
///   the subject: the claim is about the function, not its argument.
/// * A transfer that only ever *removes* bytes or *inserts* uncased ones preserves
///   both casing bits — `trim`, `substr`, `strrev`, `str_repeat`, `implode`. That is
///   why an explicit `trim` charlist changes nothing here: the output is still a
///   substring of the input.
///
/// # The table
///
/// | name(s) | keeps | forces | declines |
/// | --- | --- | --- | --- |
/// | `trim ltrim rtrim chop` | casing | — | length (`trim('  ') === ''`) |
/// | `substr` | casing | — | length in v1 (`substr('abc', 0, 0) === ''`) |
/// | `strrev` | casing + length | — | — |
/// | `str_repeat` | casing always; length at a provable multiplier ≥ 1 | — | length at `str_repeat('a', 0) === ''` |
/// | `str_pad` | length; casing when the pad argument carries it | `NON_EMPTY` at a provable length ≥ 1 | casing under an unknown pad |
/// | `strtolower` / `strtoupper` | length | `LOWERCASE` / `UPPERCASE` | the opposite casing |
/// | `ucfirst` / `ucwords` | length + `UPPERCASE` | — | `LOWERCASE` (`ucfirst('abc') === 'Abc'`) |
/// | `lcfirst` | length + `LOWERCASE` | — | `UPPERCASE` |
/// | `implode` / `join` | casing, over the glue **and** every element | — | length (an empty array implodes to `''`) |
/// | `addslashes addcslashes escapeshellarg urlencode rawurlencode preg_quote` | length | — | casing |
/// | `htmlspecialchars` / `htmlentities` | length, **only** under `ENT_SUBSTITUTE` | — | casing; everything under a non-constant flags argument |
/// | `urldecode` / `rawurldecode` | `NON_EMPTY` only | — | `NON_FALSY` (`urldecode('%30') === '0'`) |
/// | `sprintf` | — | `NON_EMPTY` at a constant format with a literal byte | everything else |
/// | `strlen` | — | `int<1, max>` at a non-empty subject | — |
///
/// Only those four bits move. `NUMERIC`, `DECIMAL_INT` and `NON_DECIMAL_INT` are
/// never propagated even where they would survive (`ucfirst(' 1e5')` is still
/// numeric): dropping a bit is a widening, and keeping the table to the measured
/// axis is worth more than the two rows it would buy.
///
/// # The declines, each for a stated reason
///
/// * **`escapeshellcmd`** — in upstream PHPStan's own non-empty set, and **wrong**
///   there: `escapeshellcmd("\x80") === ''` at 8.5.8 (it drops an invalid multibyte
///   sequence). A measured counterexample outranks upstream's say-so (ADR-0061 §2:
///   "upstream's say-so is provenance, not evidence"), so the name is refused.
/// * **`urldecode`/`rawurldecode` keep `NON_EMPTY` only** — upstream propagates
///   non-falsiness through them too, and `urldecode('%30') === '0'` refutes it.
/// * **Any `mb_*` name** — encoding- and locale-dependent, the catalog's standing
///   exclusion (`steins_catalog` lib.rs "Deliberate exclusions"). `mb_strtolower`
///   and `mb_substr` are *absent by that rule*, not by oversight.
/// * **`substr` non-emptiness** — `substr($nonEmpty, 0, 1)` really is non-empty, but
///   only once offset and length are both known to select a character inside the
///   subject's bounds, and the subject's length is exactly what a predicate summary
///   does not carry. v1 keeps casing and says nothing about length.
/// * **`sprintf` casing, and every non-constant format** — a conversion may emit
///   uppercase (`sprintf('%X', 255) === 'FF'`) or nothing at all
///   (`sprintf('%.0s', 'abc') === ''`), so only a *literal byte in a constant
///   format* is claimed, and the scanner refuses any format it cannot parse.
/// * **`str_replace`/`substr_replace`/`parse_str`** — nsrt asks for casing through
///   them too; they need a second subject's predicates (or an out-parameter) rather
///   than this table's single-subject shape. Not modeled by this table.
///
/// # Unions are read directly (the #75 survey's nuance)
///
/// A `Fact::OneOf` of constant strings answers by **intersecting** each member's
/// summary — `'foo'|'bar'` is `LOWERCASE`, and `trim($fooOrBar, $s)` is a
/// `lowercase-string`. That path needs no fold and is not blocked on #74, which
/// gates only the sidecar route; [`fact_str_preds`] is the whole of it.
fn str_pred_transfer(
    cx: &Cx,
    folder: &mut dyn Folder,
    lower: &str,
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<(Fact, &'static [&'static str])> {
    /// Every member of the family declares a real `string` (PHP 8.5.8
    /// `ReflectionFunction::getReturnType`, non-tentative) — a pin that moves when
    /// php-src adds an arm, so ADR-0064 Amendment B's `mixed` hole never opens here.
    const STRING: &[&str] = &["string"];
    /// `strlen` is the one member returning an `int`.
    const INT: &[&str] = &["int"];

    if lower == "strlen" {
        // `strlen($nonEmpty)` is `int<1, max>`: one byte in, one byte counted. The
        // curated `int<0, max>` row (ADR-0056 R3) stays the floor for every other
        // subject, and this narrows strictly inside it.
        let [subject] = args else { return None };
        let preds = arg_str_preds(cx, folder, subject, env, store)?;
        if !preds.contains_all(StrPreds::NON_EMPTY) {
            return None;
        }
        return Some((Fact::refined(Base::Int, Refinement::Int(IntRange::POSITIVE), false), INT));
    }
    let out = str_pred_out(cx, folder, lower, args, env, store)?;
    if out.is_empty() {
        return None;
    }
    Some((Fact::refined(Base::String, Refinement::Str(out), false), STRING))
}

/// The table itself: the output predicate summary for one call, or `None` where the
/// name is not a member (or its arity is not one this rule was written against).
/// Every arm is authored from `php -r` probes at `PINNED_PHP` and php.net's
/// documented semantics — see [`str_pred_transfer`] for the reasoning per row.
fn str_pred_out(
    cx: &Cx,
    folder: &mut dyn Folder,
    lower: &str,
    args: &[ArgValue],
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<StrPreds> {
    /// The length axis: `non-empty-string` and its `non-falsy-string` refinement.
    const LENGTH: StrPreds = StrPreds::NON_EMPTY.union(StrPreds::NON_FALSY);
    /// The casing pair. Both bits together is "no cased character at all", which is
    /// a legitimate summary (`''`, `'123'`) and survives every transfer that keeps
    /// either one.
    const CASING: StrPreds = StrPreds::LOWERCASE.union(StrPreds::UPPERCASE);
    /// Everything this table ever propagates.
    const BOTH_AXES: StrPreds = LENGTH.union(CASING);
    /// `ENT_SUBSTITUTE`. Without it, `htmlspecialchars` answers `''` for a
    /// non-empty subject holding an invalid encoding sequence — witnessed at 8.5.8:
    /// `htmlspecialchars("\x80", ENT_QUOTES) === ''`, while
    /// `htmlspecialchars("\x80", ENT_SUBSTITUTE)` is the three-byte U+FFFD.
    const ENT_SUBSTITUTE: i64 = 8;

    // Argument 0 is the subject for every member but `implode`, whose own arm
    // ignores this. A zero-argument call is not one of these builtins at all.
    let subject = arg_str_preds(cx, folder, args.first()?, env, store).unwrap_or_default();

    match lower {
        // ---- Removal only: the output is a SUBSTRING of the subject ----------
        //
        // `trim('  ') === ''` kills the length axis outright, and an explicit
        // charlist changes nothing on either axis — `ltrim('0abc', '0') === 'abc'`
        // is still a substring, so casing survives a charlist that could strip the
        // whole string. `chop` is `rtrim` (same reflected `string`, same 1..=2).
        "trim" | "ltrim" | "rtrim" | "chop" => {
            (1..=2).contains(&args.len()).then(|| subject.intersect(CASING))
        }
        // `substr('abc', 0, 0) === ''` — same shape, and the length axis needs
        // bounds arithmetic this rung does not carry (see the doc's declines).
        "substr" => (2..=3).contains(&args.len()).then(|| subject.intersect(CASING)),
        // ---- Permutation: the byte MULTISET is preserved -------------------
        //
        // `strrev` keeps the length exactly, so `''`/`'0'` can only come from
        // `''`/`'0'`: both length bits survive alongside both casing bits.
        "strrev" => {
            let [_] = args else { return None };
            Some(subject.intersect(BOTH_AXES))
        }
        // ---- Repetition: length survives only at a provable multiplier ≥ 1 ----
        //
        // `str_repeat('a', 0) === ''`. Casing survives regardless — `''` carries
        // both casing bits, so the zero case cannot falsify a casing claim.
        "str_repeat" => {
            let [_subject, times] = args else { return None };
            let once = transfer_arg_fact(cx, folder, times, env, store)
                .as_ref()
                .is_some_and(fact_is_positive_int);
            Some(subject.intersect(if once { BOTH_AXES } else { CASING }))
        }
        // ---- Padding: the subject is a SUBSEQUENCE of the output --------------
        //
        // So the length axis always survives (`str_pad` never shortens: a `$length`
        // below the subject's own returns it unchanged). The output length is
        // `max(strlen($subject), $length)`, which makes a provable `$length >= 1`
        // FORCE non-emptiness whatever the subject was — `str_pad('', 1) === ' '`,
        // while `str_pad('', 0) === ''` and `str_pad('', -5) === ''`.
        //
        // Casing needs the pad string too, since the padding is inserted verbatim.
        // An absent pad argument is `' '`, which has no cased character and so
        // carries both bits; an unknown one contributes nothing and drops casing.
        "str_pad" => {
            if !(2..=4).contains(&args.len()) {
                return None;
            }
            let pad = match args.get(2) {
                None => CASING,
                Some(p) => arg_str_preds(cx, folder, p, env, store).unwrap_or_default().intersect(CASING),
            };
            let forced = if transfer_arg_fact(cx, folder, &args[1], env, store)
                .as_ref()
                .is_some_and(fact_is_positive_int)
            {
                StrPreds::NON_EMPTY
            } else {
                StrPreds::empty()
            };
            Some(subject.intersect(LENGTH.union(pad)).union(forced))
        }
        // ---- The FORCED casing pair ------------------------------------------
        //
        // Byte-wise ASCII case mapping (locale-insensitive since 8.2): the length is
        // preserved, so both length bits survive, and the target casing holds for
        // ANY input — the one leg that fires with no subject fact at all. The
        // OPPOSITE casing is dropped: `strtolower('AB')` is `'ab'`, which has
        // lowercase bytes, so an `uppercase-string` subject does not stay one.
        "strtolower" => {
            let [_] = args else { return None };
            Some(subject.intersect(LENGTH).union(StrPreds::LOWERCASE))
        }
        "strtoupper" => {
            let [_] = args else { return None };
            Some(subject.intersect(LENGTH).union(StrPreds::UPPERCASE))
        }
        // ---- Selective casing: length survives, one casing bit does ----------
        //
        // `ucfirst('abc') === 'Abc'` breaks `LOWERCASE` but cannot break
        // `UPPERCASE` (it only ever uppercases). `lcfirst` is the mirror. `ucwords`
        // is `ucfirst` at every word boundary, with the same asymmetry, and its
        // optional `$separators` argument does not change it.
        "ucfirst" => {
            let [_] = args else { return None };
            Some(subject.intersect(LENGTH.union(StrPreds::UPPERCASE)))
        }
        "lcfirst" => {
            let [_] = args else { return None };
            Some(subject.intersect(LENGTH.union(StrPreds::LOWERCASE)))
        }
        "ucwords" => {
            (1..=2).contains(&args.len()).then(|| subject.intersect(LENGTH.union(StrPreds::UPPERCASE)))
        }
        // ---- Concatenation: EVERY contributor must carry the claim -----------
        //
        // The output's bytes are the elements' bytes plus the glue's, so a casing
        // bit holds exactly when the glue and every admitted element hold it. The
        // one-argument form's glue is `''`, which carries both. The length axis is
        // NOT claimed: `implode(',', [])` is `''`, and proving otherwise needs the
        // array's non-emptiness *and* an element's — a join this arm leaves to a
        // separate rule.
        "implode" | "join" => {
            let (glue, array) = match args {
                [array] => (CASING, array),
                [glue, array] => {
                    (arg_str_preds(cx, folder, glue, env, store).unwrap_or_default().intersect(CASING), array)
                }
                _ => return None,
            };
            Some(glue.intersect(implode_element_preds(cx, folder, array, env, store)?))
        }
        // ---- The escaping family: insertion only ------------------------------
        //
        // Each of these only ever *inserts* bytes (backslashes, entities, percent
        // escapes) or copies them, so a non-empty subject stays non-empty and a
        // non-falsy one cannot collapse to `'0'` (that would need a one-byte output
        // from a one-byte non-`'0'` input, and every one-byte input either survives
        // or grows). Casing is NOT claimed: `htmlspecialchars('<')` is `'&lt;'`
        // (lowercase letters appear) and `urlencode('ä')` is `'%C3%A4'` (uppercase
        // hex), so both bits genuinely break.
        "addslashes" | "escapeshellarg" | "urlencode" | "rawurlencode" => {
            let [_] = args else { return None };
            Some(subject.intersect(LENGTH))
        }
        "addcslashes" => {
            let [_, _] = args else { return None };
            Some(subject.intersect(LENGTH))
        }
        "preg_quote" => (1..=2).contains(&args.len()).then(|| subject.intersect(LENGTH)),
        // `urldecode('%30') === '0'`: decoding SHRINKS, so a non-falsy subject can
        // decode to the falsy `'0'`. Non-emptiness still holds — every `%XX` triple
        // yields one byte and every other byte yields itself, so the output is never
        // shorter than one byte for a non-empty input.
        "urldecode" | "rawurldecode" => {
            let [_] = args else { return None };
            Some(subject.intersect(StrPreds::NON_EMPTY))
        }
        // The one gated pair, and the gate is the engine's own: without
        // `ENT_SUBSTITUTE` an invalid encoding sequence makes the whole call answer
        // `''`. A missing flags argument is the 8.1+ default
        // (`ENT_QUOTES | ENT_SUBSTITUTE | ENT_HTML401` == 11, read off
        // `ReflectionFunction` at the pin), which carries the bit; an explicit
        // non-constant flags argument cannot be checked and declines everything.
        // The `$encoding`/`$double_encode` arguments do not move the boundary —
        // probed at 8.5.8 across UTF-8, ISO-8859-1, SJIS and two unsupported
        // charsets, every substitute-flag answer for a non-empty subject was
        // non-empty.
        "htmlspecialchars" | "htmlentities" => {
            if !(1..=4).contains(&args.len()) {
                return None;
            }
            let substitutes = match args.get(1) {
                None => true,
                Some(flags) => fact_int_bits_all_set(
                    &transfer_arg_fact(cx, folder, flags, env, store)?,
                    ENT_SUBSTITUTE,
                ),
            };
            substitutes.then(|| subject.intersect(LENGTH))
        }
        // ---- `sprintf`: a literal byte in a CONSTANT format --------------------
        //
        // Every conversion can produce nothing (`sprintf('%.0s', 'abc') === ''`), so
        // the only thing a format proves on its own is the literal text between the
        // conversions. `'%%'` counts — it emits one `'%'`.
        "sprintf" => {
            let Some(Fact::Singleton(Val::Str(fmt))) = transfer_arg_fact(cx, folder, &args[0], env, store)
            else {
                return None;
            };
            sprintf_emits_a_literal(fmt.as_bytes())?.then_some(StrPreds::NON_EMPTY)
        }
        _ => None,
    }
}

/// The predicate summary an argument's fact carries, or `None` when the fact is not
/// a string one at all. `General { String }` answers the *empty* summary — it is a
/// string, just one nothing is known about — so a caller intersecting against it
/// declines for the right reason.
fn arg_str_preds(
    cx: &Cx,
    folder: &mut dyn Folder,
    value: &ArgValue,
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<StrPreds> {
    fact_str_preds(&transfer_arg_fact(cx, folder, value, env, store)?)
}

/// The predicate summary EVERY value a fact admits satisfies.
///
/// The finite layers are read directly, which is the #75 survey's union nuance in
/// one line: a `OneOf` of constant strings intersects its members' summaries, so
/// `'foo'|'bar'` is `LOWERCASE` and `'foo'|'BAR'` is neither casing. No fold and no
/// #74 dependency — that issue gates the sidecar route only.
fn fact_str_preds(f: &Fact) -> Option<StrPreds> {
    match f {
        Fact::Singleton(Val::Str(s)) => Some(StrPreds::of(s)),
        Fact::OneOf(vals) => {
            let mut acc: Option<StrPreds> = None;
            for v in vals {
                let Val::Str(s) = v else { return None };
                let p = StrPreds::of(s);
                acc = Some(acc.map_or(p, |a| a.intersect(p)));
            }
            acc
        }
        Fact::Refined { base: Base::String, refinement: Refinement::Str(p), nullable: false } => {
            Some(*p)
        }
        Fact::General { base: Base::String, nullable: false } => Some(StrPreds::empty()),
        _ => None,
    }
}

/// The predicate summary every element of `implode`'s array argument satisfies.
///
/// An abstract shape answers through [`shape_value_union`] — one unknown slot there
/// already yields `None`, which is exactly the decline this rule wants. A fully
/// known array answers by intersecting its values, and the empty array answers the
/// summary of `''` (both casing bits), because that is what it implodes to.
/// A non-string element declines: `implode` casts it, and what the cast produces is
/// the element's business, not this rule's.
fn implode_element_preds(
    cx: &Cx,
    folder: &mut dyn Folder,
    value: &ArgValue,
    env: &HashMap<String, Known>,
    store: Option<&Store>,
) -> Option<StrPreds> {
    match transfer_arg_fact(cx, folder, value, env, store)? {
        Fact::Shape { shape, nullable: false } => fact_str_preds(&shape_value_union(&shape)?),
        Fact::Singleton(Val::Array(entries)) => {
            let mut acc = StrPreds::of("");
            for (_, v) in &entries {
                let Val::Str(s) = v else { return None };
                acc = acc.intersect(StrPreds::of(s));
            }
            Some(acc)
        }
        _ => None,
    }
}

/// Is every value this fact admits an integer of at least 1? The multiplier gate
/// for `str_repeat` and the length gate for `str_pad` — both of which turn on
/// exactly that boundary (`str_repeat('a', 0) === ''`, `str_pad('', 0) === ''`).
fn fact_is_positive_int(f: &Fact) -> bool {
    match f {
        Fact::Singleton(Val::Int(n)) => *n >= 1,
        // `all` over an empty set is vacuously true; a `OneOf` is never empty in
        // practice, and the guard says so rather than relying on it.
        Fact::OneOf(vals) => {
            !vals.is_empty() && vals.iter().all(|v| matches!(v, Val::Int(n) if *n >= 1))
        }
        Fact::Refined { base: Base::Int, refinement: Refinement::Int(r), nullable: false } => {
            r.lo() >= 1
        }
        _ => false,
    }
}

/// Does every integer this fact admits have all of `bits` set? A flags argument the
/// rule cannot see through (a variable, an abstract int) answers `false`, which is
/// the decline `htmlspecialchars` needs.
fn fact_int_bits_all_set(f: &Fact, bits: i64) -> bool {
    match f {
        Fact::Singleton(Val::Int(n)) => n & bits == bits,
        Fact::OneOf(vals) => {
            !vals.is_empty() && vals.iter().all(|v| matches!(v, Val::Int(n) if n & bits == bits))
        }
        _ => false,
    }
}

/// Does this `sprintf` format guarantee at least one output byte?
///
/// `Some(true)` when a byte is emitted no matter what the arguments are — a literal
/// outside any conversion, or a `'%%'` escape. `Some(false)` when the format is all
/// conversions (`'%s'`, `'%.0s'`), each of which may emit nothing. **`None` when the
/// scanner does not recognize the format**, which is a decline, not a `false`: a
/// mis-parsed conversion specifier read as a literal would be a false premise, so
/// anything outside the documented `%[argnum$][flags][width][.precision]specifier`
/// grammar refuses the rule outright. A trailing `%` is a `ValueError` at 8.5.8 and
/// lands in the same refusal — there is no return value to describe.
fn sprintf_emits_a_literal(fmt: &[u8]) -> Option<bool> {
    /// php-src's `php_formatted_print` conversion characters.
    const SPECIFIERS: &[u8] = b"bcdeEfFgGosuxX";

    let mut i = 0;
    let mut literal = false;
    while i < fmt.len() {
        if fmt[i] != b'%' {
            literal = true;
            i += 1;
            continue;
        }
        i += 1;
        if *fmt.get(i)? == b'%' {
            // `sprintf('%%') === '%'` — a guaranteed byte.
            literal = true;
            i += 1;
            continue;
        }
        loop {
            match *fmt.get(i)? {
                // `%'x5s`: the byte after the quote is the custom padding char.
                b'\'' => {
                    i += 2;
                    if i > fmt.len() {
                        return None;
                    }
                }
                b'-' | b'+' | b' ' | b'.' | b'$' | b'0'..=b'9' => i += 1,
                _ => break,
            }
        }
        if !SPECIFIERS.contains(fmt.get(i)?) {
            return None;
        }
        i += 1;
    }
    Some(literal)
}

/// A `list<T>` / `non-empty-list<T>` fact, through the canonical constructor —
/// `None` element is the unknown floor (`list<mixed>`).
fn list_transfer_fact(non_empty: bool, elem: Option<Fact>) -> Fact {
    use steins_domain::{KeyClass, Tail};
    shape_fact(ShapeFact::normalize(
        Vec::new(),
        Tail::Unsealed { key: KeyClass::Int, value: elem.map(Box::new) },
        Certainty::Yes,
        non_empty,
        Vec::new(),
    ))
}

/// Is every value this fact admits a non-empty string? A literal (or literal set)
/// answers by inspection; an abstract string answers through the predicate the
/// domain already models. Anything else — including a nullable string — is `false`.
fn fact_is_non_empty_string(f: &Fact) -> bool {
    match f {
        Fact::Singleton(Val::Str(s)) => !s.is_empty(),
        Fact::OneOf(vals) => vals.iter().all(|v| matches!(v, Val::Str(s) if !s.is_empty())),
        Fact::Refined { base: Base::String, refinement: Refinement::Str(p), nullable: false } => {
            p.contains_all(StrPreds::NON_EMPTY)
        }
        _ => false,
    }
}

fn shape_fact(shape: ShapeFact) -> Fact {
    Fact::Shape { shape: Box::new(shape), nullable: false }
}

/// The fact **every value** of an admitted array satisfies: the join of every
/// non-`Absent` field's value slot with the tail's value bound. One unknown
/// contributor (or an unrepresentable join) yields `None` — the unknown floor,
/// which admits anything.
fn shape_value_union(shape: &ShapeFact) -> Option<Fact> {
    use steins_domain::{Presence, Tail};
    let mut acc: Option<Fact> = None;
    for (_, presence, slot) in &shape.fields {
        if matches!(presence, Presence::Absent) {
            continue;
        }
        acc = join_into(acc, slot.as_deref()?)?;
    }
    if let Tail::Unsealed { value, .. } = &shape.tail {
        acc = join_into(acc, value.as_deref()?)?;
    }
    acc
}

/// The fact **every key** of an admitted array satisfies. Under a `Sealed` tail
/// the key set is exactly the declared, non-`Absent` keys, so the answer is those
/// key literals (a `Singleton`/`OneOf`, or the domain's own computed widening past
/// [`steins_domain::CAP`] — never a hand-rolled degradation). An `Unsealed` tail
/// contributes its key class, joined with the declared keys; `array-key` (PHP's
/// `int|string`) is not a single-base fact, so it yields the unknown floor.
fn shape_key_union(shape: &ShapeFact) -> Option<Fact> {
    use steins_domain::{KeyClass, Presence, Tail};
    let declared: Vec<Val> = shape
        .fields
        .iter()
        .filter(|(_, p, _)| !matches!(p, Presence::Absent))
        .map(|(k, _, _)| val_of_key(k))
        .collect();
    match &shape.tail {
        Tail::Sealed => Fact::from_vals(declared),
        Tail::Unsealed { key, .. } => {
            let class = match key {
                KeyClass::Int => Fact::General { base: Base::Int, nullable: false },
                KeyClass::Str => Fact::General { base: Base::String, nullable: false },
                KeyClass::ArrayKey => return None,
            };
            declared
                .iter()
                .try_fold(class, |acc, v| acc.join(&Fact::Singleton(v.clone())))
        }
    }
}

/// `array_values($x)`: a list of the value union. `non_empty` carries — the
/// projection preserves the entry count.
fn project_values(shape: &ShapeFact) -> ShapeFact {
    use steins_domain::{KeyClass, Tail};
    ShapeFact::normalize(
        Vec::new(),
        Tail::Unsealed { key: KeyClass::Int, value: shape_value_union(shape).map(Box::new) },
        Certainty::Yes,
        shape.non_empty,
        Vec::new(),
    )
}

/// `array_keys($x)`: a list of the key union. `non_empty` carries.
fn project_keys(shape: &ShapeFact) -> ShapeFact {
    use steins_domain::{KeyClass, Tail};
    ShapeFact::normalize(
        Vec::new(),
        Tail::Unsealed { key: KeyClass::Int, value: shape_key_union(shape).map(Box::new) },
        Certainty::Yes,
        shape.non_empty,
        Vec::new(),
    )
}

/// `array_flip($x)`: the values become keys and the keys become values.
///
/// Two soundness points, both measured against the engine:
///
/// * **The result key class is `int` only when every value is an `int`.** A
///   *string* value does not give a string key: PHP's own array-key cast turns
///   `'5'` into `5` (`array_flip(['a' => '5']) === [5 => 'a']`), so a string-valued
///   flip can produce integer keys and the honest class is `array-key`.
/// * **`non_empty` is dropped.** `array_flip` skips (with a warning) any entry
///   whose value is not `int|string`, so a non-empty input can flip to `[]`.
///
/// `is_list` is left to `normalize` (`Maybe`): whether the values happen to be
/// `0..n-1` is not something the shape knows.
fn project_flip(shape: &ShapeFact) -> ShapeFact {
    use steins_domain::{KeyClass, Tail};
    let all_int = shape_value_union(shape).is_some_and(|f| fact_is_int(&f));
    ShapeFact::normalize(
        Vec::new(),
        Tail::Unsealed {
            key: if all_int { KeyClass::Int } else { KeyClass::ArrayKey },
            value: shape_key_union(shape).map(Box::new),
        },
        Certainty::Maybe,
        false,
        Vec::new(),
    )
}

/// `array_reverse($x)` with the default `$preserve_keys = false`: **string keys
/// keep their keys, integer keys are renumbered `0..n-1`** (measured:
/// `array_reverse(['a' => 1, 5 => 2, 9 => 3]) === [0 => 3, 1 => 2, 'a' => 1]`).
///
/// The result's key SET is therefore the input's string keys plus a fresh integer
/// prefix — which is why the fields are dropped rather than carried, and why the
/// `is_list` verdict is a three-way read of the input's key structure:
///
/// * **`Yes`** when no admitted array can carry a string key (a sealed tail whose
///   declared keys are all integers, or an `int`-classed unsealed tail with the
///   same): everything is renumbered, so the result is exactly `0..n-1`.
/// * **`No`** when some string key is `Required`: it survives into the result, and
///   an array with a string key is not a list.
/// * **`Maybe`** otherwise — the honest widening.
///
/// `non_empty` carries (reversal preserves the entry count).
fn project_reverse(shape: &ShapeFact) -> ShapeFact {
    use steins_domain::{KeyClass, Presence, Tail};
    let declared_ints =
        shape.fields.iter().all(|(k, p, _)| matches!(p, Presence::Absent) || matches!(k, VKey::Int(_)));
    let tail_ints = match &shape.tail {
        Tail::Sealed => true,
        Tail::Unsealed { key, .. } => *key == KeyClass::Int,
    };
    let all_int_keys = declared_ints && tail_ints;
    let required_str =
        shape.fields.iter().any(|(k, p, _)| p.is_required() && matches!(k, VKey::Str(_)));
    let is_list = if all_int_keys {
        Certainty::Yes
    } else if required_str {
        Certainty::No
    } else {
        Certainty::Maybe
    };
    ShapeFact::normalize(
        Vec::new(),
        Tail::Unsealed {
            key: if all_int_keys { KeyClass::Int } else { KeyClass::ArrayKey },
            value: shape_value_union(shape).map(Box::new),
        },
        is_list,
        shape.non_empty,
        Vec::new(),
    )
}

/// Join `f` into an accumulator that may still be empty; `None` propagates the
/// unrepresentable join as the unknown floor.
fn join_into(acc: Option<Fact>, f: &Fact) -> Option<Option<Fact>> {
    match acc {
        None => Some(Some(f.clone())),
        Some(a) => a.join(f).map(Some),
    }
}

/// The domain value a shape key denotes (`Key::Int(5)` is the value `5`).
fn val_of_key(k: &VKey) -> Val {
    match k {
        VKey::Int(i) => Val::Int(*i),
        VKey::Str(s) => Val::Str(s.clone()),
    }
}

/// Is every value this fact admits an `int`? (`null` is immaterial to
/// [`project_flip`]'s question — a null value is skipped by the flip, not turned
/// into a key.)
fn fact_is_int(f: &Fact) -> bool {
    match f.finite_members() {
        Some(vals) => vals.iter().all(|v| matches!(v, Val::Int(_) | Val::Null)),
        None => matches!(
            f,
            Fact::General { base: Base::Int, .. } | Fact::Refined { base: Base::Int, .. }
        ),
    }
}

/// Add `null` to a fact's denotation — the finite layers by value, the abstract
/// ones through their own `nullable` flag. `None` when the result is not
/// representable (a shape fact, or an over-cap finite widening).
fn fact_admitting_null(f: &Fact) -> Option<Fact> {
    match f.finite_members() {
        Some(vals) => {
            let mut vals = vals.to_vec();
            vals.push(Val::Null);
            Fact::from_vals(vals)
        }
        None => fact_with_null(f),
    }
}

/// The abstract fact an argument resolves to: a bare `$var` whose env fact is an
/// abstract layer (no finite members). Finite/proven values go through
/// `resolve_cval` instead, so this is the disjoint "abstract" arm of Feature E.
fn arg_abstract_fact<'e>(
    value: &ArgValue,
    env: &'e HashMap<String, Known>,
    poisoned: bool,
) -> Option<&'e Fact> {
    if poisoned {
        return None;
    }
    let ArgValue::Var(name) = value else { return None };
    let f = env.get(name)?.fact.as_ref()?;
    f.finite_members().is_none().then_some(f)
}

/// Whether a lowered contract type contains a class-name node — a bare identifier
/// that may actually be a template or a type-alias. The abstract-fact check stays
/// silent on these (see [`check_phpdoc_param`]).
fn contract_touches_class(ty: &steins_contract::ContractTy) -> bool {
    use steins_contract::ContractTy as C;
    match ty {
        C::Class(_) => true,
        C::Union(m) | C::Inter(m) => m.iter().any(contract_touches_class),
        C::ListOf { elem, .. } => contract_touches_class(elem),
        C::MapOf { key, val, .. } | C::IterableOf { key, val } => {
            contract_touches_class(key) || contract_touches_class(val)
        }
        C::Shape { fields, unsealed, .. } => {
            fields.iter().any(|f| contract_touches_class(&f.ty))
                || unsealed.as_ref().is_some_and(|(k, v)| {
                    k.as_ref().is_some_and(|k| contract_touches_class(k))
                        || contract_touches_class(v)
                })
        }
        _ => false,
    }
}

/// ADR-0043 stage 4 — the phpdoc-side analogue of [`object_world_guard_blind`]. A
/// class-touching phpdoc verdict is unsound inside a binding descent: the callee's
/// in-body type guards on the rebound value are unmodeled (the same reason the
/// native object-world check is suppressed there). "Touches a class" means the
/// proven value is an object, or the contract references a class name (a bare
/// identifier the lowering treats as a class). Scalar-vs-scalar phpdoc checks —
/// whose guards the walk *can* evaluate — are unaffected. Always `false` outside a
/// descent.
fn phpdoc_object_guard_blind(in_descent: bool, ty: &PType, cv: Option<&CVal>) -> bool {
    in_descent
        && (matches!(cv, Some(CVal::Object(..)))
            || contract_touches_class(&steins_contract::lower(ty)))
}

/// ADR-0043 stage 4 — is `ty` a **pure class contract**: a known class name, or a
/// union/nullable built only from known class names and `null` (e.g. `Foo`,
/// `Foo|null`, `?Foo`, `A|B`)? Only such a contract may let a definite scalar fact
/// open the [`contract_touches_class`] valve. The `is_known_class` gate is the
/// safety valve — an unresolved bare identifier may be a `@template` param or a
/// `@phpstan-type` alias (which can denote a scalar), so it disqualifies the whole
/// contract. A contract touching an array/generic/shape/intersection/callable, or
/// any scalar/pseudo-type keyword, is *not* pure-class (returns `false`): those
/// cases keep the existing silence.
fn is_pure_class_contract(cx: &Cx, cfile: usize, coff: u32, ty: &PType) -> bool {
    fn walk(cx: &Cx, cfile: usize, coff: u32, ty: &PType, saw_class: &mut bool) -> bool {
        match &ty.kind {
            PKind::Identifier(name) => {
                // A `null` companion (the `class|null` shape) is allowed but is not
                // itself the class that satisfies the "at least one class" rule.
                if name.eq_ignore_ascii_case("null") {
                    return true;
                }
                let target = cx.resolve_pclass(cfile, coff, name);
                if cx.is_known_class(&target) {
                    *saw_class = true;
                    true
                } else {
                    false
                }
            }
            PKind::Nullable(inner) => walk(cx, cfile, coff, inner, saw_class),
            PKind::Union { types, .. } => {
                types.iter().all(|t| walk(cx, cfile, coff, t, saw_class))
            }
            _ => false,
        }
    }
    let mut saw_class = false;
    walk(cx, cfile, coff, ty, &mut saw_class) && saw_class
}

/// A short, phpdoc-flavored description of an abstract fact for a diagnostic
/// message (`a value of type int`, `a non-empty-string value`, `an int|null
/// value`). Finite facts never reach here (they render as concrete values).
fn describe_fact(f: &Fact) -> String {
    let base_kw = |b: Base| match b {
        Base::Int => "int",
        Base::Float => "float",
        Base::String => "string",
        Base::Bool => "bool",
    };
    let (name, nullable) = match f {
        Fact::General { base, nullable } => (base_kw(*base).to_owned(), *nullable),
        Fact::Refined { base: Base::Int, refinement: Refinement::Int(r), nullable } => {
            let n = if *r == IntRange::POSITIVE {
                "positive-int".to_owned()
            } else if *r == IntRange::NEGATIVE {
                "negative-int".to_owned()
            } else if *r == IntRange::NON_NEGATIVE {
                "non-negative-int".to_owned()
            } else {
                format!("int<{}, {}>", r.lo(), r.hi())
            };
            (n, *nullable)
        }
        Fact::Refined { base: Base::String, refinement: Refinement::Str(p), nullable } => {
            let casing = match (
                p.contains_all(StrPreds::LOWERCASE),
                p.contains_all(StrPreds::UPPERCASE),
            ) {
                (true, false) => Some("lowercase"),
                (false, true) => Some("uppercase"),
                // Neither, or both (nothing cased to change): no single keyword.
                _ => None,
            };
            let n = if p.contains_all(StrPreds::NON_FALSY) {
                "non-falsy-string".to_owned()
            } else if p.contains_all(StrPreds::NUMERIC) {
                "numeric-string".to_owned()
            } else if let Some(c) = casing {
                if p.contains_all(StrPreds::NON_EMPTY) {
                    format!("non-empty-{c}-string")
                } else {
                    format!("{c}-string")
                }
            } else if p.contains_all(StrPreds::NON_EMPTY) {
                "non-empty-string".to_owned()
            } else {
                "string".to_owned()
            };
            (n, *nullable)
        }
        Fact::Refined { base, nullable, .. } => (base_kw(*base).to_owned(), *nullable),
        // The array stratum reaches this surface as of ADR-0072 (a shape fact is
        // now judged against a contract, so it can be the thing a
        // `phpdoc.*-mismatch` names). It spells through the ONE speller the dump
        // surface uses — `render_shape_fact` already carries the null half, so
        // the `nullable` flag stays `false` here rather than doubling it.
        Fact::Shape { shape, nullable } => (render_shape_fact(shape, *nullable), false),
        // Finite facts do not reach here: the callers gate on `finite_members`.
        Fact::Singleton(_) | Fact::OneOf(_) => ("value".to_owned(), false),
    };
    if nullable {
        format!("a value of type {name}|null")
    } else {
        format!("a value of type {name}")
    }
}

/// Render a proven [`CVal`] for a diagnostic message (delegates arrays/scalars to
/// [`ArgValue::render`]; objects show `new Class()`).
fn rendered_cval(v: &CVal) -> String {
    match v {
        CVal::Scalar(s) => s.render(),
        CVal::Object(class, _) => format!("new {}()", class.rsplit('\\').next().unwrap_or(class)),
        CVal::Array(entries) => {
            // Rebuild an `ArgValue::Array` with explicit keys so the shared compact
            // renderer applies (it re-normalizes; explicit keys round-trip).
            let items: Vec<(ArrayKey, ArgValue)> = entries
                .iter()
                .map(|(k, cv)| {
                    let key = match k {
                        NormKey::Int(i) => ArrayKey::Int(*i),
                        NormKey::Str(s) => ArrayKey::Str(s.clone()),
                    };
                    (key, cval_to_argvalue(cv))
                })
                .collect();
            ArgValue::Array(items).render()
        }
    }
}

/// A best-effort [`ArgValue`] reconstruction of a [`CVal`], for rendering only.
fn cval_to_argvalue(v: &CVal) -> ArgValue {
    match v {
        CVal::Scalar(s) => s.clone(),
        CVal::Object(..) => ArgValue::Other,
        CVal::Array(entries) => ArgValue::Array(
            entries
                .iter()
                .map(|(k, cv)| {
                    let key = match k {
                        NormKey::Int(i) => ArrayKey::Int(*i),
                        NormKey::Str(s) => ArrayKey::Str(s.clone()),
                    };
                    (key, cval_to_argvalue(cv))
                })
                .collect(),
        ),
    }
}

#[cfg(test)]
mod domain_tests {
    //! Unit tests for the ADR-0031/0035 domain skeleton: the unified [`Certainty`]
    //! algebra, [`Fact`] joins (agree / OneOf / cap overflow), and the empirically
    //! settled PHP comparison primitives.
    use super::*;
    use steins_syntax::ArgValue;

    fn sing(v: ArgValue) -> Fact {
        // Scalars only here — no array literal, so the minor is immaterial.
        singleton_fact(&v, None).expect("literal converts")
    }

    #[test]
    fn certainty_algebra() {
        use Certainty::{Maybe, No, Yes};
        // not swaps the poles, fixes Maybe.
        assert_eq!(Yes.not(), No);
        assert_eq!(No.not(), Yes);
        assert_eq!(Maybe.not(), Maybe);
        // and: No dominates, then Maybe.
        assert_eq!(Yes.and(Yes), Yes);
        assert_eq!(Yes.and(No), No);
        assert_eq!(Yes.and(Maybe), Maybe);
        assert_eq!(No.and(Maybe), No);
        // or: Yes dominates, then Maybe.
        assert_eq!(No.or(No), No);
        assert_eq!(No.or(Yes), Yes);
        assert_eq!(No.or(Maybe), Maybe);
        assert_eq!(Yes.or(Maybe), Yes);
    }

    #[test]
    fn fact_join_agree_keeps_singleton() {
        // The env now stores `steins_domain::Fact`; joins go through the domain
        // algebra. Equal singletons stay a Singleton and resolve to the value.
        let j = sing(ArgValue::Int(5)).join(&sing(ArgValue::Int(5))).unwrap();
        assert!(matches!(j, Fact::Singleton(Val::Int(5))));
        let k = Known::value(j, 0, None);
        assert_eq!(k.singleton(), Some(ArgValue::Int(5)));
    }

    #[test]
    fn fact_join_differ_forms_oneof_and_dedups() {
        let j = sing(ArgValue::Int(5)).join(&sing(ArgValue::Int(6))).unwrap();
        assert!(matches!(&j, Fact::OneOf(vs) if vs.len() == 2));
        // A OneOf never resolves to a single proven value.
        assert_eq!(Known::value(j.clone(), 0, None).singleton(), None);
        // Re-joining an already-present value dedups.
        let j2 = j.join(&sing(ArgValue::Int(6))).unwrap();
        assert!(matches!(&j2, Fact::OneOf(vs) if vs.len() == 2));
    }

    #[test]
    fn fact_join_overflow_widens_to_refined() {
        // Beyond the OneOf cap the domain widens to a *computed* Refined summary
        // (an int interval), rather than dropping — abstract facts now flow
        // through the env (ADR-0035 stage 2). The widened fact resolves no value.
        let full = Fact::from_vals((0..steins_domain::CAP as i64).map(Val::Int).collect()).unwrap();
        assert!(matches!(full, Fact::OneOf(_)));
        let widened = full.join(&sing(ArgValue::Int(999))).unwrap();
        assert!(matches!(widened, Fact::Refined { base: Base::Int, .. }));
        assert_eq!(Known::value(widened, 0, None).singleton(), None);
    }

    #[test]
    fn loose_eq_measured_cells_php_8_5_8() {
        use ArgValue::{Bool, Int, Null, Str};
        let s = |x: &str| Str(x.to_owned());
        // A representative slice of the recorded PHP 8.5.8 table.
        assert_eq!(php_loose_eq(&Null, &Null, Some((8, 5))), Some(true));
        assert_eq!(php_loose_eq(&Null, &Int(0), Some((8, 5))), Some(true));
        assert_eq!(php_loose_eq(&Null, &s(""), Some((8, 5))), Some(true));
        assert_eq!(php_loose_eq(&Null, &s("0"), Some((8, 5))), Some(false)); // the PHP 8 trap
        assert_eq!(php_loose_eq(&Null, &Bool(false), Some((8, 5))), Some(true));
        assert_eq!(php_loose_eq(&Bool(false), &s("0"), Some((8, 5))), Some(true));
        assert_eq!(php_loose_eq(&Bool(false), &s("abc"), Some((8, 5))), Some(false));
        assert_eq!(php_loose_eq(&Bool(true), &s("abc"), Some((8, 5))), Some(true));
        assert_eq!(php_loose_eq(&Int(0), &s("abc"), Some((8, 5))), Some(false)); // PHP 8, not PHP 7
        assert_eq!(php_loose_eq(&Int(0), &s("0"), Some((8, 5))), Some(true));
        assert_eq!(php_loose_eq(&Int(0), &s(""), Some((8, 5))), Some(false));
        assert_eq!(php_loose_eq(&s("0"), &s(""), Some((8, 5))), Some(false));
        assert_eq!(php_loose_eq(&s("5"), &s("5"), Some((8, 5))), Some(true));
        assert_eq!(php_loose_eq(&s("5"), &Int(5), Some((8, 5))), Some(true));
    }

    #[test]
    fn truthiness_edge_cells() {
        use ArgValue::{Array, Float, Int, Null, Str};
        assert_eq!(php_truthy(&Str("0".to_owned())), Some(false)); // "0" is falsy
        assert_eq!(php_truthy(&Str("0.0".to_owned())), Some(true)); // but "0.0" is truthy
        assert_eq!(php_truthy(&Str(String::new())), Some(false));
        assert_eq!(php_truthy(&Int(0)), Some(false));
        assert_eq!(php_truthy(&Float(0.0)), Some(false));
        assert_eq!(php_truthy(&Null), Some(false));
        assert_eq!(php_truthy(&Array(vec![])), Some(false)); // [] is falsy
    }

    #[test]
    fn identical_is_type_strict() {
        use ArgValue::{Float, Int};
        assert_eq!(php_identical(&Int(5), &Int(5), Some((8, 5))), Some(true));
        assert_eq!(php_identical(&Int(5), &Float(5.0), Some((8, 5))), Some(false)); // 5 === 5.0 is false
    }

    /// ADR-0049 A12: the next-auto-index rule for negative keys changed in PHP
    /// 8.3, so an array `===` verdict is a function of the *project's* minor —
    /// and is unproven when no minor was reported.
    #[test]
    fn negative_key_arrays_compare_per_the_project_minor() {
        use steins_syntax::ArrayKey;
        let s = |x: &str| ArgValue::Str(x.to_owned());
        let arr = |items: Vec<(ArrayKey, ArgValue)>| ArgValue::Array(items);

        // `[-5 => 'a', 'b']` — the omitted key is where the two rules disagree.
        let auto = arr(vec![(ArrayKey::Int(-5), s("a")), (ArrayKey::Auto, s("b"))]);
        // `[-5 => 'a', -4 => 'b']` (the 8.3+ landing) and `[-5 => 'a', 0 => 'b']`
        // (the pre-8.3 landing), both written with explicit keys.
        let at_minus_4 = arr(vec![(ArrayKey::Int(-5), s("a")), (ArrayKey::Int(-4), s("b"))]);
        let at_zero = arr(vec![(ArrayKey::Int(-5), s("a")), (ArrayKey::Int(0), s("b"))]);

        // Witnessed on PHP 8.5.8:
        //   php -r 'var_export([-5=>"a","b"] === [-5=>"a",-4=>"b"]);' → true
        //   php -r 'var_export([-5=>"a","b"] === [-5=>"a",0=>"b"]);'  → false
        assert_eq!(php_identical(&auto, &at_minus_4, Some((8, 5))), Some(true));
        assert_eq!(php_identical(&auto, &at_zero, Some((8, 5))), Some(false));

        // A project on 8.1/8.2 floors the auto index at 0 — the verdicts invert.
        for minor in [(8, 1), (8, 2)] {
            assert_eq!(php_identical(&auto, &at_minus_4, Some(minor)), Some(false), "{minor:?}");
            assert_eq!(php_identical(&auto, &at_zero, Some(minor)), Some(true), "{minor:?}");
        }

        // No reported minor: unproven, not guessed. This is the leg that keeps a
        // wrong key out of the proof layer.
        assert_eq!(php_identical(&auto, &at_minus_4, None), None);
        assert_eq!(php_identical(&auto, &at_zero, None), None);
        assert_eq!(php_loose_eq(&auto, &at_minus_4, None), None);

        // A version-independent literal still decides under an unknown minor —
        // the widening stays narrow.
        let list = arr(vec![(ArrayKey::Auto, s("a"))]);
        let list_explicit = arr(vec![(ArrayKey::Int(0), s("a"))]);
        assert_eq!(php_identical(&list, &list_explicit, None), Some(true));
    }

    /// The same premise on the fact side: an unresolvable key drops the
    /// `Val::Array` singleton rather than recording a guessed one.
    #[test]
    fn unproven_negative_key_drops_the_singleton_fact() {
        use steins_syntax::ArrayKey;
        let arr = ArgValue::Array(vec![
            (ArrayKey::Int(-5), ArgValue::Str("a".to_owned())),
            (ArrayKey::Auto, ArgValue::Str("b".to_owned())),
        ]);
        assert!(singleton_fact(&arr, None).is_none());
        assert!(singleton_fact(&arr, Some((8, 5))).is_some());
        assert!(singleton_fact(&arr, Some((8, 1))).is_some());
    }
}

#[cfg(test)]
mod oracle_tests {
    //! Unit tests for the ADR-0043 §3 trinary is-a oracle ([`Cx::is_a`]): the
    //! parent chain, the transitive `implements` closure, interface-extends, the
    //! builtin exception tree, the enum interface roots, the closed-set `No`, and
    //! every `Unknown` condition. The oracle is exercised directly against a
    //! one-file project so its verdicts are asserted without routing through
    //! instanceof branch analysis (integration tests cover that path separately).
    use super::*;

    fn is_a(src: &str, sub: &str, sup: &str) -> IsA {
        let tree = SourceTree::parse(src);
        let units = [FileUnit { path: "t.php", tree: &tree }];
        let index = Index::from_units(&units);
        Cx::new(&units, &index, 0).is_a(sub, sup)
    }

    #[test]
    fn reflexive_and_parent_chain() {
        let src = "<?php class A {} class B extends A {} class C extends B {}";
        assert_eq!(is_a(src, "c", "c"), IsA::Yes, "reflexive");
        assert_eq!(is_a(src, "c", "a"), IsA::Yes, "grandparent via chain");
        assert_eq!(is_a(src, "b", "a"), IsA::Yes);
        // Fully enumerated, unrelated direction → No.
        assert_eq!(is_a(src, "a", "c"), IsA::No, "a is not a c (closed set)");
    }

    #[test]
    fn transitive_implements_and_interface_extends() {
        let src = "<?php
interface I {}
interface J extends I {}
class Base implements J {}
class Foo extends Base {}";
        assert_eq!(is_a(src, "foo", "j"), IsA::Yes, "class implements via parent");
        assert_eq!(is_a(src, "foo", "i"), IsA::Yes, "transitive interface-extends");
        assert_eq!(is_a(src, "base", "i"), IsA::Yes);
        assert_eq!(is_a(src, "j", "i"), IsA::Yes, "interface extends interface");
        // A class with no relation to K, fully enumerated → No.
        let src2 = "<?php interface I {} interface K {} class Foo implements I {}";
        assert_eq!(is_a(src2, "foo", "k"), IsA::No);
    }

    #[test]
    fn builtin_exception_tree_closed() {
        let src = "<?php class MyEx extends \\RuntimeException {}";
        // Chain leaves the project into the catalogued exception tree — enumerated.
        assert_eq!(is_a(src, "myex", "runtimeexception"), IsA::Yes);
        assert_eq!(is_a(src, "myex", "exception"), IsA::Yes);
        assert_eq!(is_a(src, "myex", "throwable"), IsA::Yes);
        // A catalogued exception is provably NOT a LogicException (both under the
        // fully-known SPL tree).
        assert_eq!(is_a(src, "myex", "logicexception"), IsA::No);
        // PHP 8.0+: `Throwable extends Stringable`, so every Throwable IS-A
        // Stringable (verified against PHP 8.5). A `No` here would be unsound.
        assert_eq!(is_a(src, "myex", "stringable"), IsA::Yes);
    }

    #[test]
    fn enum_is_a_its_interfaces_and_roots() {
        let src = "<?php
interface HasLabel {}
enum Suit: string implements HasLabel { case H = 'h'; }
enum Dir { case Up; }";
        // A backed enum is-a UnitEnum, BackedEnum, and its explicit interface.
        assert_eq!(is_a(src, "suit", "unitenum"), IsA::Yes);
        assert_eq!(is_a(src, "suit", "backedenum"), IsA::Yes);
        assert_eq!(is_a(src, "suit", "haslabel"), IsA::Yes);
        // A pure enum is-a UnitEnum but NOT BackedEnum (closed enumeration).
        assert_eq!(is_a(src, "dir", "unitenum"), IsA::Yes);
        assert_eq!(is_a(src, "dir", "backedenum"), IsA::No);
        assert_eq!(is_a(src, "dir", "haslabel"), IsA::No);
    }

    #[test]
    fn unknown_when_chain_leaves_project() {
        // Parent is an uncatalogued external → enumeration incomplete → Unknown.
        let src = "<?php class Foo extends \\Vendor\\Base {}";
        assert_eq!(is_a(src, "foo", "vendor\\base"), IsA::Yes, "the named parent is still Yes");
        assert_eq!(is_a(src, "foo", "somethingelse"), IsA::Unknown, "beyond the unknown parent");
    }

    #[test]
    fn unknown_when_sub_or_super_unknown() {
        let src = "<?php class A {}";
        // Sub is an unknown external → Unknown (unless reflexively equal).
        assert_eq!(is_a(src, "ghost", "a"), IsA::Unknown);
        assert_eq!(is_a(src, "ghost", "ghost"), IsA::Yes, "reflexive even when unknown");
        // Sub known+enumerated, super an unknown name absent from the closed set → No.
        assert_eq!(is_a(src, "a", "ghost"), IsA::No);
    }

    #[test]
    fn ambiguous_sub_is_unknown() {
        // Two definitions of the same FQN → ambiguous → not Unique → Unknown.
        let src = "<?php class Dup {} class Dup {}";
        assert_eq!(is_a(src, "dup", "whatever"), IsA::Unknown);
    }

    #[test]
    fn trait_use_does_not_force_unknown() {
        // A `use`d trait adds no type; the class is still fully enumerated (its real
        // parent/interfaces), so a `No` verdict stands.
        let src = "<?php trait T {} class A {} class Foo extends A { use T; }";
        assert_eq!(is_a(src, "foo", "a"), IsA::Yes);
        assert_eq!(is_a(src, "foo", "unrelated"), IsA::No, "trait use keeps closure complete");
    }
}

#[cfg(test)]
mod n4_carrier_tests {
    //! ADR-0052 N4 — contract facts, class facts, and instanceof subtraction at the
    //! carrier level (the walk-integration path is covered by the `narrowing_n4`
    //! integration test). Each adversarial drift direction of the slice prompt has a
    //! test: argument-order (`is_a(M,T)`), positive-branch non-final survival,
    //! Unknown-keeps-both, emptied-lane-is-no-fact, Asserted-never-launders, and the
    //! A11 catalog-skew demotion scoped to arm deletion.
    use super::*;

    /// Build a `Cx` over a one-file project and run `f` against it. `php_minor` seeds
    /// the A11 version input; the skew flag is derived from it exactly as
    /// [`effective_php_view`] does with no declared target.
    fn with_cx<R>(src: &str, php_minor: Option<(u16, u16)>, f: impl FnOnce(&Cx) -> R) -> R {
        let tree = SourceTree::parse(src);
        let units = [FileUnit { path: "t.php", tree: &tree }];
        let index = Index::from_units(&units);
        let view = effective_php_view(php_minor, None);
        let cx = Cx::new_with(
            &units,
            &index,
            0,
            &EMPTY_DAM,
            true,
            view.effective_minor,
            view.catalog_skew,
            view.version_id,
            None,
            None,
        );
        f(&cx)
    }

    fn cls(s: &str) -> ContractTy {
        ContractTy::Class(s.to_owned())
    }
    fn arm(ty: ContractTy, stratum: Stratum) -> ContractArm {
        ContractArm { ty, stratum }
    }
    fn oracle<'c, 'a>(cx: &'c Cx<'a>) -> ProjectIsa<'c, 'a> {
        ProjectIsa { cx, demote_catalog: cx.a11_demote_catalog() }
    }

    /// The identity class resolver for the global-namespace seeding tests: the
    /// lowered phpdoc names are already the normalized FQNs there.
    fn id_resolve(n: &str) -> String {
        n.to_ascii_lowercase()
    }

    // ---- native_arms / flatten_arms / seeding -------------------------------

    #[test]
    fn native_arms_lowers_scalars_instances_and_null() {
        let src = "<?php function f(?int $a, User|Guest $b): void {}";
        with_cx(src, None, |cx| {
            let scope = cx.tree().scopes().iter().find(|s| matches!(&s.owner, ScopeOwner::Function(n) if n == "f")).unwrap();
            let params = cx.scope_params(scope).unwrap();
            // `?int` → [int, null] Verified.
            assert_eq!(
                seed_contract_arms(&params[0], None, &id_resolve),
                Some(vec![arm(ContractTy::Base(Base::Int), Stratum::Verified), arm(ContractTy::Null, Stratum::Verified)])
            );
            // `User|Guest` native (object instances) → [User, Guest] Verified.
            assert_eq!(
                seed_contract_arms(&params[1], None, &id_resolve),
                Some(vec![arm(cls("user"), Stratum::Verified), arm(cls("guest"), Stratum::Verified)])
            );
        });
    }

    #[test]
    fn seed_phpdoc_refines_at_asserted_stratum() {
        // `object $value` (native None) + `@param User|Guest` → phpdoc arms, Asserted.
        let src = "<?php /** @param User|Guest $value */ function f(object $value): void {}";
        with_cx(src, None, |cx| {
            let scope = cx.tree().scopes().iter().find(|s| matches!(&s.owner, ScopeOwner::Function(n) if n == "f")).unwrap();
            let p = &cx.scope_params(scope).unwrap()[0];
            let env = cx.scope_envelopes(scope).unwrap();
            let seeded = seed_contract_arms(p, env.param("value"), &id_resolve).unwrap();
            assert_eq!(
                seeded,
                vec![arm(cls("user"), Stratum::Asserted), arm(cls("guest"), Stratum::Asserted)]
            );
        });
    }

    #[test]
    fn seed_phpdoc_arm_backed_by_native_stays_verified() {
        // `int $x` + `@param int $x`: the `int` arm the native ALSO proves keeps the
        // Verified stratum (no needless downgrade); a phpdoc-only refinement would be
        // Asserted.
        let src = "<?php /** @param int $x */ function f(int $x): void {}";
        with_cx(src, None, |cx| {
            let scope = cx.tree().scopes().iter().find(|s| matches!(&s.owner, ScopeOwner::Function(n) if n == "f")).unwrap();
            let p = &cx.scope_params(scope).unwrap()[0];
            let env = cx.scope_envelopes(scope).unwrap();
            assert_eq!(
                seed_contract_arms(p, env.param("x"), &id_resolve),
                Some(vec![arm(ContractTy::Base(Base::Int), Stratum::Verified)])
            );
        });
    }

    #[test]
    fn dedup_contract_arms_ties_keep_min_stratum() {
        // Two arm_eq arms (a Verified `int` and an Asserted `int`, as a join would
        // produce): the survivor keeps the WEAKER (Asserted) stratum — no laundering.
        let mut arms = vec![
            arm(ContractTy::Base(Base::Int), Stratum::Verified),
            arm(ContractTy::Base(Base::Int), Stratum::Asserted),
        ];
        dedup_contract_arms(&mut arms);
        assert_eq!(arms, vec![arm(ContractTy::Base(Base::Int), Stratum::Asserted)]);
    }

    #[test]
    fn dedup_collapses_identical_opaque_arms() {
        // Survey non-termination regression (nextcloud `core/Migrations`): the
        // non-extensional arms (`CallableTy`/`StrOpaque`/`Opaque`) have
        // `subsumes(x, x) == Maybe`, so `arm_eq` alone could NOT collapse two
        // identical copies — a branch-union then doubled the pile at every join,
        // reaching 2^depth. Structural equality must collapse them. A whole pile of
        // one opaque arm dedups to a single arm regardless of count.
        // (`Mixed`/`ObjectAny` are arm_eq-reflexive already, so were never affected.)
        // The `\Closure $schemaClosure` arm observed exploding in the survey, plus
        // the other non-extensional floors. Each is an arm `arm_eq` cannot prove
        // equal to ITSELF (`subsumes(x, x) == Maybe`), so before the fix a 64-copy
        // pile stayed 64 and doubled at the next join.
        //
        // The survey's OTHER exploding arm, `array $options`, is deliberately no
        // longer in this list: ADR-0071 gave the array vocabulary a structural
        // denotation, so every array arm is now arm_eq-reflexive (asserted below,
        // and pinned in steins-contract's `array_arms_are_arm_eq_reflexive`). The
        // structural-equality collapse still catches it first, so the regression
        // this test guards stays guarded from both sides.
        for ty in [
            ContractTy::CallableTy { sig: None, obl: steins_contract::CallableObl::default() },
            ContractTy::StrOpaque,
            ContractTy::Opaque,
        ] {
            assert!(!normalize::arm_eq(&ty, &ty), "{ty:?} is expectedly non-arm_eq-reflexive");
            let mut arms: Vec<ContractArm> =
                (0..64).map(|_| arm(ty.clone(), Stratum::Verified)).collect();
            dedup_contract_arms(&mut arms);
            assert_eq!(arms, vec![arm(ty.clone(), Stratum::Verified)], "{ty:?} pile must collapse to one");
        }
        // The array arm collapses too, now for the stronger reason (ADR-0071).
        let array = ContractTy::ArrayAny { non_empty: false };
        assert!(normalize::arm_eq(&array, &array), "array arms are arm_eq-reflexive since ADR-0071");
        let mut arms: Vec<ContractArm> =
            (0..64).map(|_| arm(array.clone(), Stratum::Verified)).collect();
        dedup_contract_arms(&mut arms);
        assert_eq!(arms, vec![arm(array, Stratum::Verified)], "array pile must collapse to one");
    }

    #[test]
    fn dedup_identical_opaque_keeps_min_stratum() {
        // The structural-equality collapse still honors the derivation clause: a
        // Verified + Asserted pair of the SAME opaque arm survives at Asserted.
        let mut arms = vec![
            arm(ContractTy::CallableTy { sig: None, obl: steins_contract::CallableObl::default() }, Stratum::Verified),
            arm(ContractTy::CallableTy { sig: None, obl: steins_contract::CallableObl::default() }, Stratum::Asserted),
            arm(ContractTy::CallableTy { sig: None, obl: steins_contract::CallableObl::default() }, Stratum::Verified),
        ];
        dedup_contract_arms(&mut arms);
        assert_eq!(arms, vec![arm(ContractTy::CallableTy { sig: None, obl: steins_contract::CallableObl::default() }, Stratum::Asserted)]);
    }

    // ---- the deliverable: else-of-instanceof leaves {Guest} -----------------

    const FIXTURE: &str = "<?php interface Named { public function name(): string; } \
        final class User implements Named { public function name(): string { return 'u'; } } \
        final class Guest { public function guestId(): int { return 1; } }";

    #[test]
    fn negative_branch_leaves_guest_arm_asserted() {
        // The conformance deliverable, at the carrier level: a `User|Guest` lane, the
        // else of `instanceof User` subtracts User (is_a(User,User)=Yes), leaving
        // {Guest} — and Guest keeps its Asserted stratum (came from `@param`).
        with_cx(FIXTURE, None, |cx| {
            let mut store = Store::default();
            store.contract.insert(
                "value".into(),
                vec![arm(cls("user"), Stratum::Asserted), arm(cls("guest"), Stratum::Asserted)],
            );
            subtract_contract_lane(
                &mut store,
                "value",
                &normalize::Subtrahend::Class { fqn: "user".into(), polarity: false },
                &oracle(cx),
            );
            assert_eq!(store.contract_arms("value"), Some([arm(cls("guest"), Stratum::Asserted)].as_slice()));
        });
    }

    #[test]
    fn negative_branch_argument_order_is_m_then_t() {
        // `Named` is a supertype of `User`. else of `instanceof User` over a lane
        // holding `Named` asks is_a(Named, User) = No (a Named need not be a User) →
        // the arm SURVIVES. A reversed is_a(User, Named)=Yes would wrongly delete it.
        with_cx(FIXTURE, None, |cx| {
            let mut store = Store::default();
            store.contract.insert("v".into(), vec![arm(cls("named"), Stratum::Verified)]);
            subtract_contract_lane(
                &mut store,
                "v",
                &normalize::Subtrahend::Class { fqn: "user".into(), polarity: false },
                &oracle(cx),
            );
            assert_eq!(store.contract_arms("v"), Some([arm(cls("named"), Stratum::Verified)].as_slice()));
        });
    }

    #[test]
    fn positive_branch_deletes_final_nonmember_keeps_open() {
        // then of `instanceof User` over `Guest|Named`: Guest is final and
        // is_a(Guest,User)=No → deleted; Named is NOT final → survives (an unseen
        // Named subclass could be a User). Guards both positive-branch drifts.
        with_cx(FIXTURE, None, |cx| {
            let mut store = Store::default();
            store.contract.insert("v".into(), vec![arm(cls("guest"), Stratum::Verified), arm(cls("named"), Stratum::Verified)]);
            subtract_contract_lane(
                &mut store,
                "v",
                &normalize::Subtrahend::Class { fqn: "user".into(), polarity: true },
                &oracle(cx),
            );
            assert_eq!(store.contract_arms("v"), Some([arm(cls("named"), Stratum::Verified)].as_slice()));
        });
    }

    #[test]
    fn emptied_lane_drops_to_no_fact() {
        // A `!== null` on a `null`-only lane empties it → the lane is REMOVED (no
        // key), never a death signal (§2: the verdict owns death).
        with_cx(FIXTURE, None, |cx| {
            let mut store = Store::default();
            store.contract.insert("v".into(), vec![arm(ContractTy::Null, Stratum::Verified)]);
            subtract_contract_lane(&mut store, "v", &normalize::Subtrahend::Null, &oracle(cx));
            assert_eq!(store.contract_arms("v"), None, "emptied lane is no-fact, not present-and-empty");
        });
    }

    // ---- Member fact + eval_instanceof implication (§3b) --------------------

    #[test]
    fn member_implication_yes_no_maybe() {
        with_cx(FIXTURE, None, |cx| {
            // yes:[User], test `instanceof Named`: is_a(User,Named)=Yes → Yes.
            let m = Member { yes: vec!["user".into()], no: vec![] };
            assert_eq!(member_instanceof(cx, Some(&m), "named"), Certainty::Yes);
            // no:[Named], test `instanceof User`: is_a(User,Named)=Yes so a User would
            // be a Named, which the guard excluded → No.
            let m2 = Member { yes: vec![], no: vec!["named".into()] };
            assert_eq!(member_instanceof(cx, Some(&m2), "user"), Certainty::No);
            // yes:[Guest], test `instanceof Named`: is_a(Guest,Named)=No, no exclusion
            // matches → Maybe.
            let m3 = Member { yes: vec!["guest".into()], no: vec![] };
            assert_eq!(member_instanceof(cx, Some(&m3), "named"), Certainty::Maybe);
            // No fact → Maybe.
            assert_eq!(member_instanceof(cx, None, "named"), Certainty::Maybe);
        });
    }

    // ---- A11 catalog version-skew demotion ----------------------------------

    #[test]
    fn a11_catalog_backed_deletion_demoted_only_on_skew() {
        // Empty project: `ArrayObject`/`Traversable` resolve through the builtin
        // CATALOG. else of `instanceof Traversable` over an `ArrayObject` arm asks
        // is_a(ArrayObject, Traversable) = Yes (catalog-backed).
        let sub = normalize::Subtrahend::Class { fqn: "traversable".into(), polarity: false };
        // Pinned minor (matches catalog) → verdict stands → arm deleted.
        with_cx("<?php", Some(steins_catalog::PINNED_PHP), |cx| {
            let mut store = Store::default();
            store.contract.insert("v".into(), vec![arm(cls("arrayobject"), Stratum::Verified)]);
            subtract_contract_lane(&mut store, "v", &sub, &oracle(cx));
            assert_eq!(store.contract_arms("v"), None, "matching minor: catalog verdict stands, arm deleted");
        });
        // Skewed minor → catalog-backed verdict demotes to Unknown → arm KEPT.
        with_cx("<?php", Some((steins_catalog::PINNED_PHP.0, steins_catalog::PINNED_PHP.1 - 1)), |cx| {
            let mut store = Store::default();
            store.contract.insert("v".into(), vec![arm(cls("arrayobject"), Stratum::Verified)]);
            subtract_contract_lane(&mut store, "v", &sub, &oracle(cx));
            assert_eq!(
                store.contract_arms("v"),
                Some([arm(cls("arrayobject"), Stratum::Verified)].as_slice()),
                "skewed minor: catalog-backed deletion demoted, arm kept (FP-safe)"
            );
        });
    }

    #[test]
    fn a11_in_project_deletion_not_demoted_on_skew() {
        // A purely in-project `User|Guest` union narrows the SAME under a skewed minor
        // — A11 touches only catalog-backed edges, never in-project source.
        with_cx(FIXTURE, Some((steins_catalog::PINNED_PHP.0, steins_catalog::PINNED_PHP.1 - 1)), |cx| {
            assert!(cx.a11_demote_catalog(), "skew is active");
            let mut store = Store::default();
            store.contract.insert("v".into(), vec![arm(cls("user"), Stratum::Verified), arm(cls("guest"), Stratum::Verified)]);
            subtract_contract_lane(
                &mut store,
                "v",
                &normalize::Subtrahend::Class { fqn: "user".into(), polarity: false },
                &oracle(cx),
            );
            assert_eq!(
                store.contract_arms("v"),
                Some([arm(cls("guest"), Stratum::Verified)].as_slice()),
                "in-project is_a(User,User)=Yes not catalog-backed → deletion stands under skew"
            );
        });
    }

    #[test]
    fn parse_php_minor_reads_major_minor() {
        assert_eq!(parse_php_minor("8.5.8"), Some((8, 5)));
        assert_eq!(parse_php_minor("8.4.10-dev"), Some((8, 4)));
        assert_eq!(parse_php_minor("nonsense"), None);
    }

    // ---- join semantics -----------------------------------------------------

    #[test]
    fn join_unions_contract_arms_and_intersects_members() {
        // A branch with lane {User} and Member{yes:[User]} joined with a branch with
        // lane {Guest} and Member{yes:[Guest]}: the merged lane is {User,Guest} (a
        // value live on EITHER path is possible), and the Member intersection is empty
        // (no bound holds on both) → dropped.
        let mut a = Store::default();
        a.contract.insert("v".into(), vec![arm(cls("user"), Stratum::Asserted)]);
        a.members.insert("v".into(), Member { yes: vec!["user".into()], no: vec![] });
        let mut b = Store::default();
        b.contract.insert("v".into(), vec![arm(cls("guest"), Stratum::Asserted)]);
        b.members.insert("v".into(), Member { yes: vec!["guest".into()], no: vec![] });
        let j = join_stores(&a, &[&b]);
        let mut got = j.contract.get("v").cloned().unwrap();
        got.sort_by(|x, y| format!("{:?}", x.ty).cmp(&format!("{:?}", y.ty)));
        assert_eq!(got, vec![arm(cls("guest"), Stratum::Asserted), arm(cls("user"), Stratum::Asserted)]);
        assert_eq!(j.members.get("v"), None, "disjoint members intersect to empty → dropped");
    }

    #[test]
    fn unbind_forgets_narrowing_carriers() {
        // Reassignment (`store.unbind`) voids both new carriers for the var.
        let mut store = Store::default();
        store.contract.insert("v".into(), vec![arm(cls("user"), Stratum::Verified)]);
        store.members.insert("v".into(), Member { yes: vec!["user".into()], no: vec![] });
        store.unbind("v");
        assert_eq!(store.contract_arms("v"), None);
        assert_eq!(store.member_of("v"), None);
    }
}

#[cfg(test)]
mod dump_render_tests {
    //! ADR-0053 §7 — the dump fact renderer. Finite facts render **value-precisely**
    //! (the literal itself: `5`, `false`, `'abc'`); the abstract layers render the
    //! honest keyword ladder. Rendering, not the walk, is under test here; the
    //! end-to-end emitter is covered by the `dump_surface` integration test.
    //!
    //! The earlier ADR-0053 §9 pin — collapse a finite fact to its base type on the
    //! dump path, deferring value-literal spelling to assertType — is reversed FOR
    //! THE DUMP PATH by the rendering-fidelity fix: value-precision is the differ-
    //! entiator the dump surface exists to show, and PHPStan itself renders constant
    //! types (`5`, `false`, `'a'`). The `annotate`/docblock renderer
    //! (`render_value_domain` → `spell_arms(summarize_vals(...))`) keeps the base-
    //! collapsed spelling unchanged; its byte-parity suite in `steins-edit` is
    //! untouched. §9's message *frame* is non-contractual (§7); only the rendered
    //! fact changed.
    use super::*;

    fn i(n: i64) -> Val {
        Val::Int(n)
    }
    fn s(v: &str) -> Val {
        Val::Str(v.to_owned())
    }

    #[test]
    fn finite_facts_render_value_precisely() {
        let r = |vals: &[Val]| render_dump_fact(&Fact::from_vals(vals.to_vec()).expect("nonempty"));
        // Singleton int / string, OneOf int / string-enum, dedup, nullable, bool.
        assert_eq!(r(&[i(5)]), "5");
        assert_eq!(r(&[s("abc")]), "'abc'");
        assert_eq!(r(&[i(1), i(2), i(3)]), "1|2|3");
        assert_eq!(r(&[s("GET"), s("POST")]), "'GET'|'POST'");
        assert_eq!(r(&[i(1), i(2), i(1)]), "1|2"); // dedup
        assert_eq!(r(&[i(1), Val::Null]), "1|null");
        // Both bool literals ⟺ the whole `bool` type (PHPStan renders `bool`, not
        // `false|true`); a lone literal stays precise.
        assert_eq!(r(&[Val::Bool(true), Val::Bool(false)]), "bool");
        assert_eq!(r(&[Val::Bool(true)]), "true");
        // `bool` joins other precise members (e.g. an int literal alongside).
        assert_eq!(r(&[i(1), Val::Bool(true), Val::Bool(false)]), "1|bool");
        // Floats keep a visible fractional part; strings stay precise alongside ints.
        assert_eq!(r(&[Val::Float(123.0)]), "123.0");
        assert_eq!(r(&[Val::Float(2.5)]), "2.5");
        assert_eq!(r(&[i(-5)]), "-5");
    }

    #[test]
    fn singleton_renders_the_php_literal_not_the_base_type() {
        // The dump surface renders the literal itself (value-precision — the ADR-0053
        // §9 collapse is reversed for this path), NOT the collapsed base `int`. A
        // string literal is single-quoted; `null` is `null`.
        assert_eq!(render_dump_fact(&Fact::Singleton(i(5))), "5");
        assert_eq!(render_dump_fact(&Fact::Singleton(s("abc"))), "'abc'");
        assert_eq!(render_dump_fact(&Fact::Singleton(Val::Bool(false))), "false");
        assert_eq!(render_dump_fact(&Fact::Singleton(Val::Null)), "null");
    }

    #[test]
    fn abstract_layers_render_the_honest_keyword_ladder() {
        // General: bare base, with nullability.
        assert_eq!(render_dump_fact(&Fact::General { base: Base::Int, nullable: false }), "int");
        assert_eq!(
            render_dump_fact(&Fact::General { base: Base::String, nullable: true }),
            "string|null"
        );
        // Refined int range: the interval, PHPStan's own spelling for every range
        // (issue #90 — `positive-int` is phpdoc input sugar, never dump output).
        assert_eq!(
            render_dump_fact(&Fact::refined(Base::Int, Refinement::Int(IntRange::POSITIVE), false)),
            "int<1, max>"
        );
        // Refined string: reuse the speller's own preds_keyword so a refined-string
        // dump and its spell_arms rendering agree.
        let numeric = Fact::refined(Base::String, Refinement::Str(StrPreds::NUMERIC.close()), false);
        assert_eq!(
            render_dump_fact(&numeric),
            steins_contract::spell::preds_keyword(StrPreds::NUMERIC.close())
        );
    }

    #[test]
    fn array_bearing_fact_spells_through_the_d4_array_vocabulary() {
        // ADR-0062 §6 flip: the array-vocabulary slice teaches the speller, so an
        // array-bearing fact is no longer an honest-unknown refusal. The empty
        // array is denotationally a Yes-list (array_is_list([]) is vacuously
        // true, §3), and it is the one shape issue #163 does not print the word
        // for: `array{}` already says "no keys at all" and re-parses to the very
        // same `Yes`.
        let fact = Fact::Singleton(Val::Array(vec![]));
        assert_eq!(render_dump_fact(&fact), "array{}");
    }

    #[test]
    fn concrete_array_values_spell_value_precisely() {
        // Point 3 of the S1 mission fixtures: a keyed non-list value spells its
        // keys under `array{…}`; a sequential value IS a key sequence (a concrete
        // array is order-witnessed) and spells positionally under `list{…}`,
        // stating the fact rather than the oracle's spelling of it (issue #163).
        let map = Fact::Singleton(Val::Array(vec![(VKey::Str("a".to_owned()), s("v"))]));
        assert_eq!(render_dump_fact(&map), "array{a: 'v'}");
        let list = Fact::Singleton(Val::Array(vec![(VKey::Int(0), s("x")), (VKey::Int(1), s("y"))]));
        assert_eq!(render_dump_fact(&list), "list{'x', 'y'}");
    }

    #[test]
    fn shape_fact_spells_through_the_shared_speller() {
        // ADR-0062 S1 point 4: `Fact::Shape` spells through the shared speller, so
        // every consumer inherits the rendering for free.
        use steins_domain::{Presence, ShapeFact, Tail};
        let shape = ShapeFact::normalize(
            vec![(VKey::Str("a".to_owned()), Presence::Required { witnessed: false }, None)],
            Tail::Sealed,
            steins_domain::Certainty::Maybe,
            false,
            Vec::new(),
        );
        let fact = Fact::Shape { shape: Box::new(shape), nullable: false };
        // `ShapeFact::normalize` sets `non_empty` from the `Required` field
        // itself (shape.rs), but a sealed shape's required key already proves
        // non-emptiness, so issue #159 stops printing the modifier twice.
        assert_eq!(render_dump_fact(&fact), "array{a: mixed}");
    }
}

#[cfg(test)]
mod return_fact_admission_tests {
    //! ADR-0056 §1–2 — the pure admission-gate core ([`admit_return_fact`] and its
    //! helpers), tested without a sidecar. Covers: the reflected envelope alone for
    //! each single representable base; the un-representable cases (multi-base union,
    //! non-scalar, `mixed`/`void`); and the three curated-refinement legs — admitted
    //! (subset ∧ pinned), rejected by a failed subset check, and rejected by a minor
    //! mismatch. The R1 generated table is empty, so curation is exercised with
    //! hand-passed refinement strings here.
    use super::*;

    #[test]
    fn envelope_alone_for_each_representable_base() {
        // A curated-less row (the R1 reality) seeds exactly the reflected base.
        assert_eq!(admit_return_fact("bool", None, true), Some(Fact::General { base: Base::Bool, nullable: false }));
        assert_eq!(admit_return_fact("int", None, true), Some(Fact::General { base: Base::Int, nullable: false }));
        assert_eq!(admit_return_fact("string", None, true), Some(Fact::General { base: Base::String, nullable: false }));
        assert_eq!(admit_return_fact("float", None, true), Some(Fact::General { base: Base::Float, nullable: false }));
        // A `?T` nullable envelope carries nullability.
        assert_eq!(admit_return_fact("?string", None, true), Some(Fact::General { base: Base::String, nullable: true }));
    }

    #[test]
    fn unrepresentable_envelopes_seed_nothing() {
        // A multi-base union (`int|false`) is not a single value-domain fact — the
        // union case is deferred (§4), so R1 seeds nothing rather than a wrong arm.
        assert_eq!(admit_return_fact("int|false", None, true), None);
        assert_eq!(admit_return_fact("string|int|false", None, true), None);
        // Non-scalars and the top/void keywords never seed.
        assert_eq!(admit_return_fact("array", None, true), None);
        assert_eq!(admit_return_fact("object", None, true), None);
        assert_eq!(admit_return_fact("mixed", None, true), None);
        assert_eq!(admit_return_fact("void", None, true), None);
        assert_eq!(admit_return_fact("DateTime", None, true), None);
    }

    #[test]
    fn curated_refinement_admitted_when_subset_and_pinned() {
        // `count(): int` envelope refined to `int<0, max>` — a subset of `int` — is
        // admitted at the pinned minor, yielding a Refined (narrower) int fact.
        let got = admit_return_fact("int", Some("int<0, max>"), true).expect("some fact");
        assert!(
            matches!(got, Fact::Refined { base: Base::Int, .. }),
            "the admitted refinement must be a Refined int, got {got:?}"
        );
        assert_ne!(got, Fact::General { base: Base::Int, nullable: false }, "must be narrower than the envelope");
    }

    #[test]
    fn curated_string_refinement_admitted_within_string_envelope() {
        // R4 shape: `sha1(): string` envelope refined to `non-falsy-string` — a
        // subset of `string`, same base — is admitted at the pinned minor as a
        // Refined string fact (narrower than the bare string envelope).
        let got = admit_return_fact("string", Some("non-falsy-string"), true).expect("some fact");
        assert!(
            matches!(got, Fact::Refined { base: Base::String, .. }),
            "the admitted refinement must be a Refined string, got {got:?}"
        );
        assert_ne!(
            got,
            Fact::General { base: Base::String, nullable: false },
            "must be narrower than the string envelope"
        );
    }

    #[test]
    fn curated_refinement_rejected_when_not_a_subset() {
        // `non-empty-string` is NOT a subset of an `int` envelope (base mismatch):
        // the row is discarded and the envelope stands alone (never a wrong premise).
        assert_eq!(
            admit_return_fact("int", Some("non-empty-string"), true),
            Some(Fact::General { base: Base::Int, nullable: false })
        );
    }

    #[test]
    fn curated_refinement_rejected_on_minor_mismatch() {
        // A perfectly valid subset refinement is still NOT admitted when the project
        // PHP minor differs from PINNED_PHP (the A11 narrowing-direction guard, §2):
        // the envelope stands alone.
        assert_eq!(
            admit_return_fact("int", Some("int<0, max>"), false),
            Some(Fact::General { base: Base::Int, nullable: false })
        );
    }

    #[test]
    fn envelope_fact_shapes() {
        assert_eq!(envelope_fact(&ContractTy::Base(Base::Bool)), Some(Fact::General { base: Base::Bool, nullable: false }));
        // A non-nullable multi-base union → None.
        assert_eq!(
            envelope_fact(&ContractTy::Union(vec![ContractTy::Base(Base::Int), ContractTy::LitBool(false)])),
            None
        );
    }

    /// The ADR-0069 floor's version gate, against the real change oracle.
    ///
    /// The gate's own law, unit-tested against the mined data: `str_split` is the
    /// witness whose declared return type moved at 8.2. (Whether that particular
    /// name also carries an admitted row is a property of the mining, not of this
    /// gate — `declared_return_floor.rs` pins the end-to-end decline on a name that
    /// does.)
    #[test]
    fn floor_target_gate_declines_below_a_names_change_boundary() {
        use steins_db::{PhpTarget, PhpTargetSource};
        let target = |floor: (u16, u16), ceiling: Option<(u16, u16)>| PhpTarget {
            floor,
            ceiling,
            source: PhpTargetSource::Require,
            raw: "test".to_owned(),
        };
        // `str_split`'s declared return type moved at 8.2.
        assert_eq!(steins_catalog::declared_return_changed_at("str_split"), Some((8, 2)));

        // A STRADDLING target has no single answer — decline (the A11 shape).
        assert!(!floor_target_admits("str_split", Some(&target((8, 1), Some((8, 5))))));
        assert!(!floor_target_admits("str_split", Some(&target((8, 1), None))));
        // A target lying entirely BELOW the boundary is just as wrong: the mined row
        // states the type at the pin, which that project never runs.
        assert!(!floor_target_admits("str_split", Some(&target((8, 1), Some((8, 1))))));
        // Wholly at or above the boundary: the row is exactly what that range runs.
        assert!(floor_target_admits("str_split", Some(&target((8, 2), Some((8, 2))))));
        assert!(floor_target_admits("str_split", Some(&target((8, 3), None))));
        // An UNDECLARED target admits — the row is Asserted anyway, and its
        // consumers tolerate that grade (ADR-0069 §3).
        assert!(floor_target_admits("str_split", None));
        // A name the oracle does not list is admitted for every target: its declared
        // return type never moved across the supported line.
        assert!(floor_target_admits("str_repeat", Some(&target((8, 1), None))));
        assert!(floor_target_admits("str_repeat", None));
    }
}

#[cfg(test)]
mod shape_projection_tests {
    //! ADR-0062 S7 — the positional projections over the order-DECLARED lane
    //! ([`shape_projection_fact`]'s helpers), tested as pure algebra.
    //!
    //! The headline is [`every_projection_admits_the_real_result`]: for every
    //! (shape, array) pair in the universe where the shape admits the array, the
    //! projected shape admits the array the real builtin produces. The reference
    //! results are the measured PHP semantics (`array_reverse` renumbers integer
    //! keys and keeps string ones; `array_flip` skips a non-`int|string` value),
    //! written out here rather than derived from the transfer under test.
    //!
    //! The second discipline is §2's rule: no transfer may read field
    //! declaration order. [`array_key_first_is_never_the_declared_first_key`] is
    //! its negative pin.
    use super::*;
    use steins_domain::{Certainty, KeyClass, Presence, ShapeFact, Tail};

    fn ik(i: i64) -> VKey {
        VKey::Int(i)
    }

    fn sk(s: &str) -> VKey {
        VKey::Str(s.to_owned())
    }

    fn req() -> Presence {
        Presence::Required { witnessed: false }
    }

    fn slot(f: Fact) -> Option<Box<Fact>> {
        Some(Box::new(f))
    }

    fn base_fact(base: Base) -> Fact {
        Fact::General { base, nullable: false }
    }

    /// `array{a: int, b?: string}` — the ADR's own fixture shape.
    fn declared_shape() -> ShapeFact {
        ShapeFact::normalize(
            vec![
                (sk("a"), req(), slot(base_fact(Base::Int))),
                (sk("b"), Presence::Optional, slot(base_fact(Base::String))),
            ],
            Tail::Sealed,
            Certainty::Maybe,
            false,
            Vec::new(),
        )
    }

    /// `list<int>`: an int-classed unsealed tail, denotationally a list.
    fn list_of_int() -> ShapeFact {
        ShapeFact::normalize(
            Vec::new(),
            Tail::Unsealed { key: KeyClass::Int, value: slot(base_fact(Base::Int)) },
            Certainty::Yes,
            false,
            Vec::new(),
        )
    }

    /// `array<string, int>`.
    fn map_str_int() -> ShapeFact {
        ShapeFact::normalize(
            Vec::new(),
            Tail::Unsealed { key: KeyClass::Str, value: slot(base_fact(Base::Int)) },
            Certainty::Maybe,
            false,
            Vec::new(),
        )
    }

    /// The concrete arrays the soundness sweep runs over, in *witnessed* order.
    fn arrays() -> Vec<Vec<(VKey, Val)>> {
        vec![
            vec![],
            vec![(ik(0), Val::Int(7))],
            vec![(ik(0), Val::Str("x".to_owned())), (ik(1), Val::Str("y".to_owned()))],
            vec![(ik(5), Val::Int(1)), (ik(9), Val::Int(2))],
            vec![(ik(1), Val::Int(2)), (ik(0), Val::Int(3))],
            vec![(sk("a"), Val::Int(1)), (sk("b"), Val::Str("x".to_owned()))],
            vec![(sk("a"), Val::Int(1))],
            vec![(sk("b"), Val::Str("zz".to_owned())), (sk("a"), Val::Int(4))],
            vec![(ik(0), Val::Int(1)), (sk("a"), Val::Int(2)), (ik(3), Val::Int(3))],
        ]
    }

    fn shapes() -> Vec<ShapeFact> {
        let mut out =
            vec![declared_shape(), list_of_int(), map_str_int(), ShapeFact::plain_array()];
        out.extend(arrays().iter().map(|a| ShapeFact::lift(a)));
        out
    }

    // ---- The reference results (measured PHP semantics) --------------------

    fn php_array_values(a: &[(VKey, Val)]) -> Vec<(VKey, Val)> {
        a.iter()
            .enumerate()
            .map(|(i, (_, v))| (ik(i64::try_from(i).expect("small")), v.clone()))
            .collect()
    }

    fn php_array_keys(a: &[(VKey, Val)]) -> Vec<(VKey, Val)> {
        a.iter()
            .enumerate()
            .map(|(i, (k, _))| (ik(i64::try_from(i).expect("small")), val_of_key(k)))
            .collect()
    }

    /// `array_flip`: values become keys (an `int` value gives an `int` key, a
    /// non-numeric `string` value a string key), and anything else is skipped.
    /// The universe carries no duplicate flipped key, so last-wins never arises.
    fn php_array_flip(a: &[(VKey, Val)]) -> Vec<(VKey, Val)> {
        a.iter()
            .filter_map(|(k, v)| {
                let nk = match v {
                    Val::Int(i) => VKey::Int(*i),
                    Val::Str(s) => VKey::Str(s.clone()),
                    _ => return None,
                };
                Some((nk, val_of_key(k)))
            })
            .collect()
    }

    /// `array_reverse($a)` with the default `$preserve_keys = false`: walk the
    /// entries backwards, keep string keys, renumber integer ones from 0.
    fn php_array_reverse(a: &[(VKey, Val)]) -> Vec<(VKey, Val)> {
        let mut next = 0i64;
        let mut out = Vec::with_capacity(a.len());
        for (k, v) in a.iter().rev() {
            match k {
                VKey::Str(_) => out.push((k.clone(), v.clone())),
                VKey::Int(_) => {
                    out.push((ik(next), v.clone()));
                    next += 1;
                }
            }
        }
        out
    }

    #[test]
    fn every_projection_admits_the_real_result() {
        let mut checked = 0usize;
        for shape in shapes() {
            for a in arrays() {
                if !shape.admits(&a) {
                    continue;
                }
                checked += 1;
                assert!(
                    project_values(&shape).admits(&php_array_values(&a)),
                    "array_values: {shape:?} on {a:?}"
                );
                assert!(
                    project_keys(&shape).admits(&php_array_keys(&a)),
                    "array_keys: {shape:?} on {a:?}"
                );
                assert!(
                    project_flip(&shape).admits(&php_array_flip(&a)),
                    "array_flip: {shape:?} on {a:?}"
                );
                assert!(
                    project_reverse(&shape).admits(&php_array_reverse(&a)),
                    "array_reverse: {shape:?} on {a:?}"
                );
                // The key-member transfer: `array_key_first`/`_last` return SOME
                // key, or `null` on the empty array — every one of which the
                // transfer's fact must admit.
                if let Some(keys) = shape_key_union(&shape) {
                    let member = if shape.non_empty {
                        keys
                    } else {
                        fact_admitting_null(&keys).expect("representable")
                    };
                    match (a.first(), a.last()) {
                        (Some((f, _)), Some((l, _))) => {
                            assert!(member.admits(&val_of_key(f)), "first: {shape:?} on {a:?}");
                            assert!(member.admits(&val_of_key(l)), "last: {shape:?} on {a:?}");
                        }
                        _ => assert!(member.admits(&Val::Null), "empty: {shape:?}"),
                    }
                }
            }
        }
        // The sweep is only evidence if the pairs exist.
        assert!(checked >= 20, "universe too small: {checked} admitted pairs");
    }

    // ---- §2's rule: declaration order is never read ------------------------

    #[test]
    fn array_key_first_is_never_the_declared_first_key() {
        // Negative soundness test: `array{a: int, b: int}` is a key SET;
        // PHPStan answers `'a'` here (phpstan/phpstan#14940) and is wrong on
        // `['b' => 1, 'a' => 2]`, which the shape admits just as well.
        let shape = ShapeFact::normalize(
            vec![(sk("a"), req(), slot(base_fact(Base::Int))), (sk("b"), req(), slot(base_fact(Base::Int)))],
            Tail::Sealed,
            Certainty::Maybe,
            false,
            Vec::new(),
        );
        let keys = shape_key_union(&shape).expect("enumerable");
        assert_eq!(
            keys,
            Fact::OneOf(vec![Val::Str("a".to_owned()), Val::Str("b".to_owned())])
        );
        assert!(keys.admits(&Val::Str("b".to_owned())));
        // Both fields are Required, so the array cannot be empty and no `null`
        // joins in.
        assert!(shape.non_empty);
    }

    #[test]
    fn a_possibly_empty_shape_admits_null_as_its_key_member() {
        let keys = shape_key_union(&map_str_int()).expect("string class");
        let member = fact_admitting_null(&keys).expect("representable");
        assert_eq!(member, Fact::General { base: Base::String, nullable: true });
    }

    // ---- Per-projection structure -----------------------------------------

    #[test]
    fn array_values_is_a_list_of_the_value_union() {
        // int ⊔ string is not representable as one scalar fact, so the value slot
        // widens to the unknown floor — a list of anything, still non-empty.
        let p = project_values(&declared_shape());
        assert_eq!(p.is_list, Certainty::Yes);
        assert!(p.non_empty);
        assert!(p.fields.is_empty());
        assert_eq!(p.tail, Tail::Unsealed { key: KeyClass::Int, value: None });

        // A homogeneous shape keeps its value bound.
        let same = ShapeFact::normalize(
            vec![
                (sk("a"), req(), slot(base_fact(Base::Int))),
                (sk("b"), Presence::Optional, slot(base_fact(Base::Int))),
            ],
            Tail::Sealed,
            Certainty::Maybe,
            false,
            Vec::new(),
        );
        assert_eq!(
            project_values(&same).tail,
            Tail::Unsealed { key: KeyClass::Int, value: slot(base_fact(Base::Int)) }
        );
    }

    #[test]
    fn array_keys_enumerates_a_sealed_shapes_keys_and_widens_an_unsealed_one() {
        assert_eq!(
            project_keys(&declared_shape()).tail,
            Tail::Unsealed {
                key: KeyClass::Int,
                value: slot(Fact::OneOf(vec![
                    Val::Str("a".to_owned()),
                    Val::Str("b".to_owned())
                ])),
            }
        );
        // An `array-key`-classed tail is `int|string` — not one fact, so the
        // element slot is the unknown floor rather than a wrong guess.
        assert_eq!(
            project_keys(&ShapeFact::plain_array()).tail,
            Tail::Unsealed { key: KeyClass::Int, value: None }
        );
        assert_eq!(
            project_keys(&list_of_int()).tail,
            Tail::Unsealed { key: KeyClass::Int, value: slot(base_fact(Base::Int)) }
        );
    }

    #[test]
    fn array_flip_drops_non_empty_and_only_claims_int_keys_for_int_values() {
        let p = project_flip(&declared_shape());
        // Values are `int|string`; a string value can still produce an INT key
        // (PHP's array-key cast), so the class is `array-key`.
        assert!(matches!(p.tail, Tail::Unsealed { key: KeyClass::ArrayKey, .. }));
        // A non-`int|string` value is skipped by the flip, so the result may be
        // empty even though the input is not.
        assert!(!p.non_empty);

        let ints = ShapeFact::normalize(
            vec![(sk("a"), req(), slot(base_fact(Base::Int)))],
            Tail::Sealed,
            Certainty::Maybe,
            false,
            Vec::new(),
        );
        assert!(matches!(
            project_flip(&ints).tail,
            Tail::Unsealed { key: KeyClass::Int, .. }
        ));
    }

    #[test]
    fn array_reverse_reads_the_key_structure_three_ways() {
        // All-int keys: everything is renumbered, so the result IS a list.
        assert_eq!(project_reverse(&list_of_int()).is_list, Certainty::Yes);
        // A required string key survives the reversal — never a list.
        assert_eq!(project_reverse(&declared_shape()).is_list, Certainty::No);
        // A string key that may or may not be there: the honest widening.
        let optional_str = ShapeFact::normalize(
            vec![(sk("a"), Presence::Optional, slot(base_fact(Base::Int)))],
            Tail::Sealed,
            Certainty::Maybe,
            false,
            Vec::new(),
        );
        assert_eq!(project_reverse(&optional_str).is_list, Certainty::Maybe);
        // The entry count is preserved, so `non_empty` carries.
        assert!(project_reverse(&declared_shape()).non_empty);
    }
}

#[cfg(test)]
mod php_view_tests {
    use super::*;
    use steins_db::{PhpTarget, PhpTargetSource};

    fn target(floor: (u16, u16), ceiling: Option<(u16, u16)>) -> PhpTarget {
        PhpTarget { floor, ceiling, source: PhpTargetSource::Require, raw: String::new() }
    }

    /// Issue #28: the one seam both A11 and A12 follow (and, since #29, the
    /// PHP_VERSION_ID guard interval).
    #[test]
    fn a_declared_target_overrides_the_runtime() {
        // A range straddling the A12 boundary declines the effective minor
        // (boundary-sensitive literals must decline) and skews the catalog; the
        // version-id interval spans the declared range [8.1.00, 8.99.99].
        let caret81 = target((8, 1), Some((8, u16::MAX)));
        let v = effective_php_view(Some((8, 5)), Some(&caret81));
        assert_eq!((v.effective_minor, v.catalog_skew), (None, true));
        assert_eq!(v.version_id, Some((80100, Some(89999))));
        // A range entirely below the boundary answers with its floor.
        let old = target((8, 1), Some((8, 2)));
        let v = effective_php_view(Some((8, 5)), Some(&old));
        assert_eq!((v.effective_minor, v.catalog_skew), (Some((8, 1)), true));
        assert_eq!(v.version_id, Some((80100, Some(80299))));
        // A range entirely at/above the boundary answers with its floor too; an
        // open ceiling is an open interval.
        let new = target((8, 3), None);
        let v = effective_php_view(Some((8, 1)), Some(&new));
        assert_eq!((v.effective_minor, v.catalog_skew), (Some((8, 3)), true));
        assert_eq!(v.version_id, Some((80300, None)));
        // A target pinned exactly to the catalog pin carries no skew.
        let pinned = target(steins_catalog::PINNED_PHP, Some(steins_catalog::PINNED_PHP));
        let v = effective_php_view(None, Some(&pinned));
        assert_eq!((v.effective_minor, v.catalog_skew), (Some(steins_catalog::PINNED_PHP), false));
    }

    /// No declaration: the pre-#28 posture, verbatim — runtime minor passthrough,
    /// skew iff the runtime differs from the pin; the version-id interval spans
    /// the runtime's minor (the exact patch is unknown).
    #[test]
    fn no_target_falls_back_to_the_runtime() {
        let v = effective_php_view(Some(steins_catalog::PINNED_PHP), None);
        assert_eq!((v.effective_minor, v.catalog_skew), (Some(steins_catalog::PINNED_PHP), false));
        let v = effective_php_view(Some((8, 1)), None);
        assert_eq!((v.effective_minor, v.catalog_skew), (Some((8, 1)), true));
        assert_eq!(v.version_id, Some((80100, Some(80199))));
        let v = effective_php_view(None, None);
        assert_eq!((v.effective_minor, v.catalog_skew, v.version_id), (None, false, None));
    }
}
